'use strict';

(function initSidebarWidth() {
  document.documentElement.style.setProperty('--sidebar-width', '500px');
})();

// Zoom CSS proporzionale su <body> sotto 1680 px (cap 1.0, floor 0.65).
(function initAutoZoom() {
  const TARGET_W = 1680;
  const MIN_Z = 0.65;
  let _zoomTimer = null;
  function apply() {
    const body = document.body;
    if (!body) return;
    const w = window.innerWidth;
    const z = w >= TARGET_W ? 1 : Math.max(MIN_Z, w / TARGET_W);
    const next = z >= 0.999 ? '' : z.toFixed(3);
    if (body.style.zoom !== next) body.style.zoom = next;
  }
  function scheduleApply() {
    if (_zoomTimer) clearTimeout(_zoomTimer);
    _zoomTimer = setTimeout(apply, 80);
  }
  window.addEventListener('resize', scheduleApply);
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', apply);
  } else {
    apply();
  }
})();

let _sidebarCollapsed = false;
let _sidebarExpandedWidth = null;
const _SIDEBAR_COLLAPSED_W = 400;

function toggleSidebarCollapse() {
  const layout = document.querySelector('.app-layout');
  const btn = document.getElementById('btnSidebarExpand');
  const icon = document.getElementById('sidebarExpandIcon');
  const lbl = document.getElementById('sidebarExpandLabel');
  if (!layout) return;
  if (!_sidebarCollapsed) {
    const curW = parseInt(getComputedStyle(layout).getPropertyValue('--sidebar-width')) || 400;
    _sidebarExpandedWidth = curW;
    document.documentElement.style.setProperty('--sidebar-width', _SIDEBAR_COLLAPSED_W + 'px');
    layout.style.setProperty('--sidebar-width', _SIDEBAR_COLLAPSED_W + 'px');
    layout.classList.add('sidebar-compressed');
    _sidebarCollapsed = true;
    if (icon) icon.textContent = '▶';
    if (lbl) {
      lbl.setAttribute('data-i18n', 'sidebarEspandi');
      lbl.textContent = typeof t === 'function' ? t('sidebarEspandi') : 'Espandi';
    }
    if (btn) btn.classList.add('collapsed');
  } else {
    const restoreW = _sidebarExpandedWidth || 500;
    document.documentElement.style.setProperty('--sidebar-width', restoreW + 'px');
    layout.style.setProperty('--sidebar-width', restoreW + 'px');
    layout.classList.remove('sidebar-compressed');
    _sidebarCollapsed = false;
    if (icon) icon.textContent = '◀';
    if (lbl) {
      lbl.setAttribute('data-i18n', 'sidebarComprimi');
      lbl.textContent = typeof t === 'function' ? t('sidebarComprimi') : 'Comprimi';
    }
    if (btn) btn.classList.remove('collapsed');
  }
}

// Popover spiegazione badge stato logico
document.addEventListener('DOMContentLoaded', () => {
  try { if (typeof _initInlineConsentObserver === 'function') _initInlineConsentObserver(); } catch(_){}
  // Test lamejs all'avvio per diagnosticare problemi di caricamento MP3.
  // Il risultato viene memorizzato in window._lamejsStatus = 'ok' | 'fail',
  // così il badge accanto a "🔐 Hash particolari" può mostrarlo all'utente.
  (function() {
    window._lamejsStatus = 'fail';
    window._lamejsStatusReason = '';
    try {
      if (typeof lamejs === 'undefined') {
        window._lamejsStatusReason = 'lamejs non caricato';
        console.warn('[UXG] lamejs NON caricato — i particolari verranno salvati in WAV. Verificare che lame.min.js sia presente in app/js/.');
        return;
      }
      if (typeof lamejs.Mp3Encoder !== 'function') {
        window._lamejsStatusReason = 'Mp3Encoder non è una funzione';
        console.warn('[UXG] lamejs caricato ma Mp3Encoder non è una funzione (tipo: ' + typeof lamejs.Mp3Encoder + '). Possibile errore di inizializzazione.');
        return;
      }
      // Test rapido: crea encoder e codifica 1 frame silenzioso.
      const _testEnc = new lamejs.Mp3Encoder(1, 16000, 64);
      const _silence = new Int16Array(1152);
      _testEnc.encodeBuffer(_silence, _silence);
      _testEnc.flush();
      window._lamejsStatus = 'ok';
      console.log('[UXG] lamejs OK — codifica MP3 attiva per i particolari.');
    } catch (e) {
      window._lamejsStatusReason = (e && e.message) ? e.message : String(e);
      console.warn('[UXG] lamejs: errore durante il test di avvio:', e);
    }
  })();

  const _logicPopover = document.createElement('div');
  _logicPopover.id = 'logic-explain-popover';
  _logicPopover.className = 'logic-explain-popover';
  _logicPopover.style.display = 'none';
  document.body.appendChild(_logicPopover);

  document.addEventListener('click', (e) => {
    const factBadge = e.target.closest('[data-logic-state]');
    const circBadge = e.target.closest('[data-circ-state]');
    const badge = factBadge || circBadge;
    if (!badge) { _logicPopover.style.display = 'none'; return; }
    e.stopPropagation();
    let key;
    if (circBadge) {
      const stateKey = circBadge.dataset.circState;
      const explainMap = {
        NO_PROOFS:    'circExplainNoProofs',
        NO_ACTS:      'circExplainNoProofs',
        HAS_PROOFS:   'circExplainHasProofs',
        COHERENT:     'circExplainCoherent',
        INCOHERENCE:  'circExplainDistorsioneAg',
        OMISSION:     'circExplainOmissioneAg',
        DOCUMENTED:   'circExplainDocumented',
        TO_DOCUMENT:  'circExplainToDocument',
        UNCLASSIFIED: 'circExplainUnclassified',
      };
      key = explainMap[stateKey] || 'circExplainNoProofs';
    } else {
      const stateKey = factBadge.dataset.logicState;
      const explainMap = {
        NO_ACTS:     'logicExplainNoActs',
        HAS_PROOFS:  'logicExplainHasProofs',
        OMISSION:    'logicExplainOmission',
        INCOHERENCE: 'logicExplainIncoherence',
        COHERENT:    'logicExplainCoherent',
        NO_PROOFS:   'logicExplainNoProofs',
      };
      key = explainMap[stateKey] || 'logicExplainNoActs';
    }
    _logicPopover.innerHTML = `
      <div class="lep-header">
        <span class="lep-icon">ℹ</span>
        <span class="lep-title">${t('logicBadgePopoverTitle')}</span>
        <button class="lep-close" onclick="document.getElementById('logic-explain-popover').style.display='none'">✕</button>
      </div>
      <div class="lep-body">${t(key)}</div>`;
    const rect = badge.getBoundingClientRect();
    _logicPopover.style.display = 'block';
    const pw = _logicPopover.offsetWidth;
    let left = rect.left + window.scrollX;
    if (left + pw > window.innerWidth - 12) left = window.innerWidth - pw - 12;
    if (left < 8) left = 8;
    _logicPopover.style.left = left + 'px';
    _logicPopover.style.top = (rect.bottom + window.scrollY + 6) + 'px';
  });
});

