const LINK_KIND = {
  VIGILANZA: 'vigilanza',
  INQUIRENTE: 'inquirente',
  GIUDICANTE: 'giudicante',
  SEGNALATO: 'segnalato',
  PARTE_OFFESA: 'parteOffesa',
  INDAGATO_IMPUTATO: 'indagatoImputato',
  COINVOLTO: 'coinvolto'
};

const LINK_KIND_ORDER = [
  LINK_KIND.VIGILANZA, LINK_KIND.INQUIRENTE, LINK_KIND.GIUDICANTE,
  LINK_KIND.SEGNALATO, LINK_KIND.PARTE_OFFESA, LINK_KIND.INDAGATO_IMPUTATO,
  LINK_KIND.COINVOLTO
];

function _deriveLinkKindFromProcRole(procRole) {
  if (!procRole) return LINK_KIND.COINVOLTO;
  const r = String(procRole).toLowerCase();
  if (r === 'indagato' || r === 'imputato') return LINK_KIND.INDAGATO_IMPUTATO;
  if (r === 'persona_offesa' || r === 'parte_civile') return LINK_KIND.PARTE_OFFESA;
  if (r === 'querelante' || r === 'denunciante') return LINK_KIND.SEGNALATO;
  if (r === 'pm') return LINK_KIND.INQUIRENTE;
  if (r === 'gip' || r === 'gup' || r === 'magistrato' ||
      r === 'giudice_dibattimento' || r === 'giudice_appello' || r === 'giudice_cassazione') {
    return LINK_KIND.GIUDICANTE;
  }
  return LINK_KIND.COINVOLTO;
}

