/* ========== FILE DISPLAY HELPERS ========== */
async function getDisplayFile(entityType, entityId) {
  const lang = currentLang;
  let file = await DB.getEntityFile(entityType, entityId, lang);
  let isFallback = false;
  if (!file && lang === 'en') {
    file = await DB.getEntityFile(entityType, entityId, 'it');
    if (file) isFallback = true;
  }
  return { file, isFallback };
}

async function getDisplayFiles(entityType, entityId) {
  const allFiles = await DB.getEntityFiles(entityType, entityId);
  return allFiles || [];
}

function renderFileDisplay(file, isFallback) {
  if (!file) {
    return '<p class="hint">' + t('noFiles') + '</p>';
  }
  let fallbackNotice = '';
  if (isFallback) {
    fallbackNotice = '<div class="file-fallback-notice">' + t('showingFallback') + '</div>';
  }
  const previewHtml = renderFilePreview(file);
  return `
    ${fallbackNotice}
    ${previewHtml}
    <div class="file-item">
      <div class="file-item-info">
        <span class="file-lang-badge file-lang-${file.lang}">${file.lang.toUpperCase()}</span>
        <div class="file-item-name">${esc(file.fileName)}</div>
        <div class="file-item-meta">${formatSize(file.fileSize)} - ${esc(file.fileType)}</div>
      </div>
      <div class="file-item-actions">
        ${_isPreviewable(file.fileType, file.fileName) ? `<button class="btn btn-xs btn-action-preview" onclick="_openFilePreviewModal(${file.id})" data-testid="button-preview-file-${file.id}" title="${t('preview')||'Anteprima'}">👁</button>` : ''}
        <button class="btn btn-xs btn-action-download" onclick="downloadFile(${file.id})">${t('download')}</button>
      </div>
    </div>
  `;
}

function renderLinkedFileDisplay(files, uid_prefix, entityId) {
  if (!files || files.length === 0) return '';
  const lang = currentLang;
  let filtered = files.filter(f => f.lang === lang);
  let isFallback = false;
  if (filtered.length === 0 && lang === 'en') {
    filtered = files.filter(f => f.lang === 'it');
    isFallback = true;
  }
  if (filtered.length === 0) filtered = files;
  const uid = 'fv_' + uid_prefix + '_' + entityId;
  const fallbackHtml = isFallback ? `<div class="file-fallback-notice">${t('showingFallback')}</div>` : '';
  const listItems = filtered.map((f, i) => `
    <div class="file-select-item ${i === 0 ? 'selected' : ''}" data-file-id="${f.id}" onclick="event.stopPropagation(); selectFileForPreview('${uid}', ${f.id}, this)">
      <div class="file-select-info">
        <span class="file-lang-badge file-lang-${f.lang}">${(f.lang || '').toUpperCase()}</span>
        <span class="file-select-name">${esc(f.fileName)}</span>
        <span class="file-select-meta">${formatSize(f.fileSize)}</span>
      </div>
      <div class="file-select-actions" onclick="event.stopPropagation()">
        ${(() => { const p=_isPreviewable(f.fileType,f.fileName); return p ? `<button class="btn btn-xs btn-action-preview" onclick="_openFilePreviewModal(${f.id})" data-testid="button-preview-linked-${f.id}" title="${t('preview')||'Anteprima'}">👁</button>` : ''; })()}
        <button class="btn btn-xs btn-action-download" onclick="downloadFile(${f.id})">${t('download')}</button>
      </div>
    </div>
  `).join('');
  const firstFile = filtered[0];
  const firstPreview = firstFile ? renderFilePreview(firstFile) : '';
  return `
    ${fallbackHtml}
    <div class="file-viewer" id="${uid}">
      <div class="file-select-list">${listItems}</div>
      <div class="file-preview-container" id="${uid}_preview">${firstPreview}</div>
    </div>
  `;
}

function renderMultiFileDisplay(files, entityType, entityId) {
  if (!files || files.length === 0) {
    return '<p class="hint">' + t('noFiles') + '</p>';
  }
  const lang = currentLang;
  let filtered = files.filter(f => f.lang === lang);
  let isFallback = false;
  if (filtered.length === 0 && lang === 'en') {
    filtered = files.filter(f => f.lang === 'it');
    isFallback = true;
  }
  if (filtered.length === 0) {
    filtered = files;
  }
  const uid = 'fv_' + entityType + '_' + entityId;
  const fallbackHtml = isFallback ? `<div class="file-fallback-notice">${t('showingFallback')}</div>` : '';
  const listItems = filtered.map((f, i) => `
    <div class="file-select-item ${i === 0 ? 'selected' : ''}" data-file-id="${f.id}" onclick="selectFileForPreview('${uid}', ${f.id}, this)">
      <div class="file-select-info">
        <span class="file-lang-badge file-lang-${f.lang}">${(f.lang || '').toUpperCase()}</span>
        <span class="file-select-name">${esc(f.fileName)}</span>
        <span class="file-select-meta">${formatSize(f.fileSize)}</span>
      </div>
      <div class="file-select-actions" onclick="event.stopPropagation()">
        ${(() => { const p=_isPreviewable(f.fileType,f.fileName); return p ? `<button class="btn btn-xs btn-action-preview" onclick="_openFilePreviewModal(${f.id})" data-testid="button-preview-multi-${f.id}" title="${t('preview')||'Anteprima'}">👁</button>` : ''; })()}
        <button class="btn btn-xs btn-action-download" onclick="downloadFile(${f.id})">${t('download')}</button>
        ${(entityType !== 'dossier' && !f.sourceFileId) ? creatorOnly(`<button class="btn btn-xs btn-danger" onclick="deleteFileAndRefresh(${f.id}, '${entityType}', ${entityId})">${t('delete')}</button>`) : ''}
      </div>
    </div>
  `).join('');

  const firstFile = filtered[0];
  const firstPreview = firstFile ? renderFilePreview(firstFile) : '';

  return `
    ${fallbackHtml}
    <div class="file-viewer" id="${uid}">
      <div class="file-select-list">${listItems}</div>
      <div class="file-preview-container" id="${uid}_preview">${firstPreview}</div>
    </div>
  `;
}

function selectFileForPreview(uid, fileId, itemEl) {
  const list = itemEl.parentElement;
  list.querySelectorAll('.file-select-item').forEach(el => el.classList.remove('selected'));
  itemEl.classList.add('selected');
  const container = document.getElementById(uid + '_preview');
  if (!container) return;
  container.innerHTML = '<p class="hint">' + t('loadingPreview') + '</p>';
  DB.getFile(fileId).then(file => {
    if (!file) { container.innerHTML = '<p class="hint">' + t('previewNotAvailable') + '</p>'; return; }
    if (file.blob) {
      const blob = new Blob([file.blob], { type: file.fileType });
      const url = URL.createObjectURL(blob);
      container.innerHTML = _buildPreviewInner(url, file);
    } else {
      const cid = 'fp_sel_' + fileId;
      container.innerHTML = `<div id="${cid}" class="file-preview"><p class="hint">${t('loadingPreview')}</p></div>`;
      loadPreviewFromFS(file, cid);
    }
  });
}

function renderFilePreview(file) {
  if (!file) return '';
  const containerId = 'file-preview-' + file.id;
  if (file.blob) {
    const blob = new Blob([file.blob], { type: file.fileType });
    const url = URL.createObjectURL(blob);
    return _buildPreviewHtml(url, file);
  }
  setTimeout(() => loadPreviewFromFS(file, containerId), 50);
  return `<div id="${containerId}" class="file-preview"><p class="hint">${t('loadingPreview')}</p></div>`;
}

async function loadPreviewFromFS(file, containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;
  if (!FS_FILES_HANDLE) {
    container.innerHTML = '<p class="hint">' + t('previewNotAvailable') + '</p>';
    return;
  }
  try {
    const fsFile = await loadPreviewFileFromFS(file);
    if (!fsFile) throw new Error('not found');
    const url = URL.createObjectURL(fsFile);
    container.innerHTML = _buildPreviewInner(url, file);
  } catch (e) {
    container.innerHTML = '<p class="hint">' + t('previewNotAvailable') + '</p>';
  }
}

function _buildPreviewHtml(url, file) {
  return `<div class="file-preview">${_buildPreviewInner(url, file)}</div>`;
}

function _buildPreviewInner(url, file) {
  const type = file.fileType || '';
  if (type.startsWith('image/')) {
    // data-file-id consente al consent observer di nascondere immagini
    // appartenenti a prove con `sensitiveImage=true` finche' l'utente
    // non conferma esplicitamente di volerle vedere (vedi _consentInlineObserver).
    const _fid = file && file.id != null ? ` data-file-id="${file.id}" data-needs-consent="check"` : '';
    return `<img src="${url}" alt="${esc(file.fileName)}" class="file-preview-img"${_fid}>`;
  }
  if (type === 'application/pdf') {
    return `<iframe src="${url}#pagemode=none&view=FitH" class="file-preview-pdf" title="${esc(file.fileName)}"></iframe>`;
  }
  if (type.startsWith('video/')) {
    return `<video src="${url}" controls class="file-preview-video" title="${esc(file.fileName)}"></video>`;
  }
  if (type.startsWith('audio/')) {
    return `<audio src="${url}" controls class="file-preview-audio" title="${esc(file.fileName)}"></audio>`;
  }
  if (type.startsWith('text/') || type === 'application/json' || type === 'application/xml') {
    return `<iframe src="${url}" class="file-preview-text" title="${esc(file.fileName)}"></iframe>`;
  }
  return `<p class="hint">${t('previewNotAvailable')}</p>`;
}

/* ========== DETAIL VIEW ========== */
async function showDetail(type, id) {
  const panel = document.getElementById('detailView');
  panel.style.display = 'block';
  document.getElementById('welcomeView').style.display = 'none';
  document.getElementById('formView').style.display = 'none';
  state.activeSubjectId = null;

  const _subTabs = document.getElementById('subjectTabs');
  if (_subTabs) _subTabs.style.display = '';
  const _tabLinked = document.getElementById('tabLinkedSubjects');
  if (_tabLinked) _tabLinked.style.display = '';
  if (typeof switchSubjectTab === 'function') switchSubjectTab('all');

  if (type === 'case') await showCaseDetail(id);
  else if (type === 'proceedingGroup') await showProceedingGroupDetail(id);
  else if (type === 'proceeding') await showProceedingDetail(id);
  else if (type === 'dossier') await showDossierDetail(id);
  else if (type === 'act') await showActDetail(id);
  else if (type === 'fact') await showFactDetail(id);
  else if (type === 'proof') await showProofDetail(id);
  if (type !== 'proof') state.selection = { type, id };
  try { await renderSubjects(); } catch (e) { console.warn('renderSubjects after navigation failed:', e); }
}

async function showCaseDetail(id) {
  const c = await DB.getCase(id);
  if (!c) return;
  const _st = document.getElementById('subjectTabs');
  if (_st) _st.style.display = '';
  const panel = document.getElementById('detailView');
  const descr = currentLang === 'it' ? c.descrIt : (c.descrEn || c.descrIt);
  const entityFiles = await getDisplayFiles('case', id);
  const fileHtml = renderMultiFileDisplay(entityFiles, 'case', id);

  const _caseProceedings = await DB.getProceedings(id);
  const _caseProcCount = _caseProceedings.length;
  const _caseDossiersArrays = await Promise.all(_caseProceedings.map(p => DB.getDossiers(p.id)));
  const _caseDossiers = _caseDossiersArrays.flat();
  const _caseDossCount = _caseDossiers.length;
  const _caseFactsArrays = await Promise.all(_caseDossiers.map(d => DB.getFactsByDossier(d.id)));
  const _caseFactIds = new Set();
  for (const arr of _caseFactsArrays) for (const f of arr) _caseFactIds.add(f.id);
  const _caseFactCount = _caseFactIds.size;
  const _caseViolArrays = await Promise.all([..._caseFactIds].map(fid => DB.getViolationsByFact(fid)));
  const _caseViolCount = _caseViolArrays.reduce((s, a) => s + a.length, 0);
  const _L = currentLang === 'en';
  const _allCasesForBadge = await DB.getCases();
  const _caseIdxBadge = _allCasesForBadge.findIndex(x => x.id === id);
  const _caseBadgeNum = _caseIdxBadge >= 0 ? String(_caseIdxBadge + 1).padStart(3, '0') : null;
  const _caseBadge = _caseBadgeNum
    ? `<span class="tree-badge tree-badge-K" style="font-size:9px;font-weight:700;letter-spacing:0.04em;white-space:nowrap;padding:1px 6px">${_L ? 'Case' : 'Caso'} ${_caseBadgeNum}</span>`
    : '';

  panel.innerHTML = `
    <div class="detail-panel">
      <div class="proc-form-header no-print">
        <div class="proc-form-header-body">
          <div style="display:flex;flex-direction:column;align-items:center;gap:5px;flex-shrink:0">
            ${_caseBadge}
            <span class="proc-form-icon">🏛️</span>
          </div>
          <div class="proc-form-header-text">
            <div class="proc-form-header-title has-title">${esc(_caseDisplayTitle(c))}</div>
          </div>
        </div>
        <div class="proc-form-header-controls">
          <button class="btn btn-sm" onclick="window.print()" data-testid="button-print-case">🖨️ ${t('printDetail')}</button>
          ${creatorOnly(`<button class="btn btn-sm" onclick="openForm('case', null, ${id})">✏️ ${t('edit')}</button>`)}
          ${creatorOnly(`<button class="btn btn-sm btn-danger" onclick="deleteEntity('case', ${id})">🗑 ${t('delete')}</button>`)}
        </div>
      </div>
      <div class="proc-stats-bar no-print">
        <div class="proc-stat-item">
          <div class="proc-stat-count">${_caseProcCount}</div>
          <div class="proc-stat-label">⚖️ ${_L ? 'Proceedings' : 'Procedimenti'}</div>
        </div>
        <div class="proc-stat-item">
          <div class="proc-stat-count">${_caseDossCount}</div>
          <div class="proc-stat-label">📁 ${_L ? 'Dossiers' : 'Fascicoli'}</div>
        </div>
        <div class="proc-stat-item">
          <div class="proc-stat-count">${_caseFactCount}</div>
          <div class="proc-stat-label">🔍 ${_L ? 'Facts' : 'Fatti'}</div>
        </div>
        <div class="proc-stat-item ${_caseViolCount > 0 ? 'proc-stat-item--alert' : ''}">
          <div class="proc-stat-count">${_caseViolCount}</div>
          <div class="proc-stat-label">${t('dashboardViolations')}</div>
        </div>
      </div>
      ${(() => { const _sub = _L ? (c.subtitleEn || c.subtitle) : c.subtitle; return _sub ? `<div class="timeline-box" style="margin-top:16px;margin-bottom:12px;background:var(--bg-panel);box-shadow:0 2px 8px rgba(0,0,0,0.07);border-color:var(--border)">
        <div class="timeline-box-header"><h3>${t('caseSectionSubnarr')}</h3></div>
        <div class="rte-content" style="font-size:14px;line-height:1.6;color:var(--text);text-align:justify;hyphens:auto">${_renderRichForView(_sub)}</div>
      </div>` : ''; })()}
      <div class="timeline-box no-print" style="margin-top:16px;margin-bottom:12px">
        <div class="timeline-box-header"><h3>${t('timelineTitle')}: ${esc(_caseDisplayTitle(c))}</h3></div>
        <div id="caseTimelineContainer"></div>
      </div>
      ${descr ? `<div class="timeline-box" style="margin-top:0;margin-bottom:12px;background:var(--bg-panel);box-shadow:0 2px 8px rgba(0,0,0,0.07);border-color:var(--border)">
        <div class="timeline-box-header"><h3>${t('caseSectionNarr')}</h3></div>
        <div class="rte-content" style="font-size:14px;line-height:1.6;color:var(--text);text-align:justify;hyphens:auto">${_renderRichForView(descr)}</div>
      </div>` : ''}
      <div class="detail-section">
        <div class="detail-section-header"><h3>${t('docIntroduttivoCaso')}</h3></div>
        ${fileHtml}
      </div>
    </div>
  `;
  showLinkedSection('case', id);
  renderCaseTimeline(id);
}

const _PROC_GROUP_TYPE_ICON = { penale: '⚖️', civile: '🤝', amministrativo: '🏢', esecuzione: '🔨', altro: '📋' };
const _PROC_GROUP_TYPE_BADGE_PREFIX = { penale: 'PP', civile: 'PC', amministrativo: 'PA', esecuzione: 'PE', altro: 'PX' };
const _PROC_GROUP_TYPE_BADGE_CLS = { penale: 'P', civile: 'C', amministrativo: 'A', esecuzione: 'E', altro: 'X' };
const _PROC_GROUP_HDR_BG     = { penale: '#fecaca', civile: '#bbf7d0', esecuzione: '#fed7aa', amministrativo: '#a5f3fc', altro: '#e5e7eb' };
const _PROC_GROUP_HDR_TEXT   = { penale: '#7f1d1d', civile: '#14532d', esecuzione: '#7c2d12', amministrativo: '#164e63', altro: '#1f2937' };
const _PROC_GROUP_HDR_BORDER = { penale: '#f87171', civile: '#4ade80', esecuzione: '#fb923c', amministrativo: '#22d3ee', altro: '#9ca3af' };

async function _computeProceedingGroupSeq(caseId, groupId) {
  const groups = await DB.getProceedingGroups(caseId);
  const grp = groups.find(g => g.id === groupId);
  if (!grp) return { seq: 'PX001', badgeCls: 'X', type: 'altro' };
  const tp = grp.type || 'altro';
  let idx = grp.sortOrder;
  if (idx == null || idx <= 0) {
    const sameType = groups.filter(g => (g.type || 'altro') === tp).sort((a, b) => a.id - b.id);
    idx = sameType.findIndex(g => g.id === groupId) + 1 || 1;
  }
  const prefix = _PROC_GROUP_TYPE_BADGE_PREFIX[tp] || 'PX';
  return { seq: prefix + String(idx).padStart(3, '0'), badgeCls: _PROC_GROUP_TYPE_BADGE_CLS[tp] || 'X', type: tp };
}

// Helper condiviso: data di riferimento del contenitore (Passo 1+2).
function _computeContainerRefDate(grp, grpProcs) {
  const grpType = grp.type || 'altro';
  const dates = [];
  for (const _gp of (grpProcs || [])) {
    const _sd = _gp.specificData || {};
    let d = '';
    if (grpType === 'penale') {
      const _ph = (_sd.phases || []).find(p => p.tipo === 'fase_procura');
      d = _ph?.dataIscrizione || '';
    } else if (grpType === 'civile') {
      d = (_sd.civil && _sd.civil.dataIscrizione) || (_sd.phases?.[0]?.dataIscrizione) || '';
    } else if (grpType === 'amministrativo') {
      d = _sd.phases?.[0]?.dataIscrizione || '';
    } else if (grpType === 'esecuzione') {
      d = _sd.dataPignoramento || '';
    }
    if (d) dates.push(d);
  }
  if (dates.length > 0) return dates.slice().sort()[0];
  if (grpType === 'altro' && grp.createdAt) {
    try { return new Date(grp.createdAt).toISOString().slice(0, 10); } catch (e) {}
  }
  return '';
}

// Vergine = nessun file fisicamente legato al sottoalbero del contenitore.
async function _isContainerVergine(grpId) {
  if ((await db.files.where({ entityType: 'proceedingGroup', entityId: grpId }).count()) > 0) return false;
  const grp = await DB.getProceedingGroup(grpId);
  if (!grp) return true;
  const allProcs = await DB.getProceedings(grp.caseId);
  const grpProcs = allProcs.filter(p => p.proceedingGroupId === grpId);
  for (const p of grpProcs) {
    if ((await db.files.where({ entityType: 'proceeding', entityId: p.id }).count()) > 0) return false;
    const dossiers = await DB.getDossiers(p.id);
    for (const d of dossiers) {
      if ((await db.files.where({ entityType: 'dossier', entityId: d.id }).count()) > 0) return false;
      const factRels = await db.factDossierRelations.where('dossierId').equals(d.id).toArray();
      const factIds = [...new Set(factRels.map(r => r.factId))];
      for (const fid of factIds) {
        if ((await db.files.where({ entityType: 'fact', entityId: fid }).count()) > 0) return false;
        const actRels = await db.factActRelations.where('factId').equals(fid).toArray();
        for (const ar of actRels) {
          if ((await db.files.where({ entityType: 'act', entityId: ar.actId }).count()) > 0) return false;
        }
        const proofRels = await db.factProofRelations.where('factId').equals(fid).toArray();
        for (const pr of proofRels) {
          if ((await db.files.where({ entityType: 'proof', entityId: pr.proofId }).count()) > 0) return false;
        }
        try {
          const circs = await db.circumstances.where('factId').equals(fid).toArray();
          for (const cc of circs) {
            if ((await db.files.where({ entityType: 'circumstance', entityId: cc.id }).count()) > 0) return false;
          }
        } catch (_) {}
      }
    }
  }
  return true;
}

// Riordino cronologico dei contenitori VERGINI (per tipo, vecchio→giovane).
// I contenitori FROZEN (con almeno un file nel sottoalbero) NON vengono mai
// rinumerati: il loro sortOrder e la loro cartella su disco restano invariati.
// Ritorna Map<grpId, {isVergine, refDate, sortOrder}> per uso successivo (es. icona lucchetto).
async function _recomputeGroupSortOrder(caseId) {
  const out = new Map();
  const groups = await DB.getProceedingGroups(caseId);
  if (groups.length === 0) return out;
  const allProcs = await DB.getProceedings(caseId);
  const byType = {};
  for (const g of groups) {
    const t = g.type || 'altro';
    (byType[t] = byType[t] || []).push(g);
  }
  for (const type in byType) {
    const list = byType[type];
    const enriched = await Promise.all(list.map(async g => {
      const grpProcs = allProcs.filter(p => p.proceedingGroupId === g.id);
      return { g, isVergine: await _isContainerVergine(g.id), refDate: _computeContainerRefDate(g, grpProcs) };
    }));
    const frozen = enriched.filter(x => !x.isVergine);
    const vergini = enriched.filter(x => x.isVergine).sort((a, b) => (a.refDate || '9999-99-99').localeCompare(b.refDate || '9999-99-99'));
    const reservedSlots = new Set(frozen.map(x => x.g.sortOrder).filter(s => s != null && s > 0));
    let nextSlot = 1;
    for (const v of vergini) {
      while (reservedSlots.has(nextSlot)) nextSlot++;
      if (v.g.sortOrder !== nextSlot) {
        await DB.updateProceedingGroup(v.g.id, { sortOrder: nextSlot });
        v.g.sortOrder = nextSlot;
      }
      nextSlot++;
    }
    // Frozen senza sortOrder (legacy): assegna slot non usato senza toccare quelli già fissati.
    for (const f of frozen) {
      if (f.g.sortOrder == null || f.g.sortOrder <= 0) {
        while (reservedSlots.has(nextSlot)) nextSlot++;
        await DB.updateProceedingGroup(f.g.id, { sortOrder: nextSlot });
        f.g.sortOrder = nextSlot;
        reservedSlots.add(nextSlot);
        nextSlot++;
      }
    }
    for (const x of enriched) out.set(x.g.id, { isVergine: x.isVergine, refDate: x.refDate, sortOrder: x.g.sortOrder });
  }
  return out;
}

async function showProceedingGroupDetail(groupId) {
  const grp = await DB.getProceedingGroup(groupId);
  if (!grp) return;
  const c = await DB.getCase(grp.caseId);
  if (!c) return;
  const _st = document.getElementById('subjectTabs');
  if (_st) _st.style.display = '';

  const panel = document.getElementById('detailView');
  const _L = currentLang === 'en';

  const allProcs = await DB.getProceedings(grp.caseId);
  const _latestPmDateLocal = (p) => {
    let best = '';
    for (const ph of (p.specificData?.phases || [])) {
      for (const ev of (ph.pmEvents || [])) {
        if (ev.date && ev.date > best) best = ev.date;
      }
    }
    return best || p.dataIscrizioneRuolo || '';
  };
  const grpProcs = allProcs
    .filter(p => p.proceedingGroupId === groupId)
    .sort((a, b) => _latestPmDateLocal(b).localeCompare(_latestPmDateLocal(a)));
  const grpProcIds = new Set(grpProcs.map(p => p.id));

  const _grpDossArrays = await Promise.all(grpProcs.map(p => DB.getDossiers(p.id)));
  const _grpDossiers = _grpDossArrays.flat();
  const _grpDossCount = _grpDossiers.length;
  const _grpFactsArrays = await Promise.all(_grpDossiers.map(d => DB.getFactsByDossier(d.id)));
  const _grpFactIds = new Set();
  for (const arr of _grpFactsArrays) for (const f of arr) _grpFactIds.add(f.id);
  const _grpFactCount = _grpFactIds.size;
  const _grpViolArrays = await Promise.all([..._grpFactIds].map(fid => DB.getViolationsByFact(fid)));
  const _grpViolCount = _grpViolArrays.reduce((s, a) => s + a.length, 0);

  const seqInfo = await _computeProceedingGroupSeq(grp.caseId, groupId);
  const _grpType = grp.type || 'altro';
  const _typeLabel = t(_grpType) || _grpType;
  const _icon = _PROC_GROUP_TYPE_ICON[_grpType] || '📋';
  const _headerBg     = _PROC_GROUP_HDR_BG[_grpType]     || '#e5e7eb';
  const _headerText   = _PROC_GROUP_HDR_TEXT[_grpType]   || '#1f2937';
  const _headerBorder = _PROC_GROUP_HDR_BORDER[_grpType] || '#9ca3af';

  const _grpTitle = (_L ? (grp.titleEN || grp.title) : grp.title) || (_L ? ('Container ' + _typeLabel) : ('Contenitore ' + _typeLabel));

  const _mainProc = grpProcs[0] || null;
  const _mainMag = (() => {
    if (!_mainProc) return '';
    const _bestDate = _latestPmDateLocal(_mainProc);
    for (const _ph of (_mainProc.specificData?.phases || [])) {
      for (const _ev of (_ph.pmEvents || [])) {
        if (_ev.date === _bestDate && _ph.magistratoPrincipale) return _ph.magistratoPrincipale;
      }
    }
    return _mainProc.specificData?.phases?.[0]?.magistratoPrincipale || '';
  })();
  const _mainUff = _mainProc?.autoritaProcedente || '';
  const _subParts = [
    (_L ? `${grpProcs.length} proceedings` : `${grpProcs.length} procedimenti`),
    _mainUff,
    _mainMag ? 'PM ' + _mainMag : ''
  ].filter(Boolean);
  const _subtitle = _subParts.join(' \u2014 ');

  const _badgeHtml = `<span class="tree-badge tree-badge-${seqInfo.badgeCls}" style="font-size:9px;font-weight:700;letter-spacing:0.04em;white-space:nowrap;padding:1px 6px">${esc(seqInfo.seq)} ${esc(_typeLabel)}</span>`;

  const _grpDescr = _L ? (grp.descrEn || grp.descrIt) : (grp.descrIt || grp.descrEn);
  const _grpFiles = await getDisplayFiles('proceedingGroup', groupId);
  const _grpFilesHtml = renderMultiFileDisplay(_grpFiles, 'proceedingGroup', groupId);

  panel.innerHTML = `
    <div class="detail-panel">
      <div class="proc-form-header proc-form-header--group no-print" style="background:${_headerBg};border-bottom-color:${_headerBorder};color:${_headerText}">
        <div class="proc-form-header-body">
          <div style="display:flex;flex-direction:column;align-items:center;gap:5px;flex-shrink:0">
            ${_badgeHtml}
            <span class="proc-form-icon">${_icon}</span>
          </div>
          <div class="proc-form-header-text">
            <div class="proc-form-header-title has-title">${esc(_grpTitle)}</div>
            ${_subtitle ? `<div class="detail-case-subtitle-chip">${esc(_subtitle)}</div>` : ''}
          </div>
        </div>
        <div class="proc-form-header-controls">
          <button class="btn btn-sm" onclick="window.print()" data-testid="button-print-proc-group" style="background:rgba(0,0,0,0.06);color:${_headerText};border:1px solid ${_headerBorder}" onmouseenter="this.style.background='rgba(0,0,0,0.12)'" onmouseleave="this.style.background='rgba(0,0,0,0.06)'">🖨️ ${t('printDetail')}</button>
        </div>
      </div>
      <div class="proc-stats-bar no-print">
        <div class="proc-stat-item">
          <div class="proc-stat-count">${grpProcs.length}</div>
          <div class="proc-stat-label">⚖️ ${_L ? 'Proceedings' : 'Procedimenti'}</div>
        </div>
        <div class="proc-stat-item">
          <div class="proc-stat-count">${_grpDossCount}</div>
          <div class="proc-stat-label">📁 ${_L ? 'Dossiers' : 'Fascicoli'}</div>
        </div>
        <div class="proc-stat-item">
          <div class="proc-stat-count">${_grpFactCount}</div>
          <div class="proc-stat-label">🔍 ${_L ? 'Facts' : 'Fatti'}</div>
        </div>
        <div class="proc-stat-item ${_grpViolCount > 0 ? 'proc-stat-item--alert' : ''}">
          <div class="proc-stat-count">${_grpViolCount}</div>
          <div class="proc-stat-label">${t('dashboardViolations')}</div>
        </div>
      </div>
      <div class="timeline-box no-print" style="margin-top:16px;margin-bottom:12px">
        <div class="timeline-box-header"><h3>${t('timelineTitle')}: ${esc(_grpTitle)}</h3></div>
        <div id="caseTimelineContainer"></div>
      </div>
      <div class="timeline-box" id="grpDescrViewBox" style="margin-top:0;margin-bottom:12px;background:var(--bg-panel);box-shadow:0 2px 8px rgba(0,0,0,0.07);border-color:var(--border)">
        <div class="timeline-box-header" style="background:${_headerBg};border-bottom:1px solid ${_headerBorder};margin:-14px -16px 10px -16px;padding:9px 16px;border-radius:5px 5px 0 0;display:flex;align-items:center;gap:8px">
          <h3 style="color:${_headerText};margin:0;flex:1">${t('description')}</h3>
          <button class="btn btn-sm" onclick="_grpDescrEditMode(${groupId})" data-testid="button-edit-grp-descr" style="background:rgba(0,0,0,0.06);color:${_headerText};border:1px solid ${_headerBorder};padding:3px 11px;font-size:11px;font-weight:600" onmouseenter="this.style.background='rgba(0,0,0,0.12)'" onmouseleave="this.style.background='rgba(0,0,0,0.06)'">${_grpDescr ? ('✏️ ' + (_L ? 'Edit' : 'Modifica')) : ('➕ ' + (_L ? 'Add' : 'Aggiungi'))}</button>
        </div>
        ${_grpDescr
          ? `<div class="rte-content" style="font-size:14px;line-height:1.6;color:var(--text)">${_renderRichForView(_grpDescr)}</div>`
          : `<div style="font-size:13px;color:var(--text-muted);font-style:italic;padding:4px 0">${_L ? 'No description yet.' : 'Nessuna descrizione.'}</div>`}
      </div>
      <div class="detail-section">
        <div class="detail-section-header"><h3>${t('procGroupDocsTitle') || t('docIntroduttivoCaso')}</h3></div>
        ${_grpFilesHtml}
      </div>
    </div>
  `;
  showLinkedSection('proceedingGroup', groupId);
  renderCaseTimeline(grp.caseId, { procFilter: grpProcIds });
}

async function _grpDescrEditMode(groupId) {
  const box = document.getElementById('grpDescrViewBox');
  if (!box) return;
  const grp = await DB.getProceedingGroup(groupId);
  if (!grp) return;
  const _L = currentLang === 'en';
  const descrIT = grp.descrIt || '';
  const descrEN = grp.descrEn || '';
  const _tp = grp.type || 'altro';
  const _hdrBg     = _PROC_GROUP_HDR_BG[_tp]     || '#e5e7eb';
  const _hdrText   = _PROC_GROUP_HDR_TEXT[_tp]   || '#1f2937';
  const _hdrBorder = _PROC_GROUP_HDR_BORDER[_tp] || '#9ca3af';

  // Sostituisce il contenuto del box con l'editor IT/EN a tab
  box.innerHTML = `
    <div class="timeline-box-header" style="background:${_hdrBg};border-bottom:1px solid ${_hdrBorder};margin:-14px -16px 10px -16px;padding:9px 16px;border-radius:5px 5px 0 0;display:flex;align-items:center;gap:8px">
      <h3 style="color:${_hdrText};margin:0;flex:1">${t('description')}</h3>
      <button id="grpDescrSaveBtn" class="btn btn-sm" data-testid="button-save-grp-descr" style="background:${_hdrText};color:${_hdrBg};border:1px solid ${_hdrText};padding:3px 13px;font-size:11px;font-weight:700">💾 ${_L ? 'Save' : 'Salva'}</button>
      <button id="grpDescrCancelBtn" class="btn btn-sm" data-testid="button-cancel-grp-descr" style="background:rgba(0,0,0,0.06);color:${_hdrText};border:1px solid ${_hdrBorder};padding:3px 11px;font-size:11px;font-weight:600">✕ ${_L ? 'Cancel' : 'Annulla'}</button>
    </div>
    <div style="border:1px solid var(--border,#cbd5e1);border-radius:8px;overflow:hidden;background:var(--bg-panel,#fff)">
      <div style="display:flex;align-items:center;background:var(--bg-secondary,#f8fafc);border-bottom:1px solid var(--border,#e2e8f0);padding:0 8px;gap:4px">
        <button type="button" id="grpDescrTabIT" data-testid="tab-grp-descr-it" style="border:1px solid transparent;background:var(--bg-panel,#fff);padding:6px 14px;border-radius:6px 6px 0 0;cursor:pointer;font-size:13px;font-weight:600;color:var(--text-primary,#0f172a);display:flex;align-items:center;gap:6px;margin-bottom:-1px;border-bottom:1px solid var(--bg-panel,#fff)">
          <span class="file-lang-badge file-lang-it" style="font-size:10px">IT</span> ${t('descrIt')||'Descrizione IT'}
        </button>
        <button type="button" id="grpDescrTabEN" data-testid="tab-grp-descr-en" style="border:1px solid transparent;background:transparent;padding:6px 14px;border-radius:6px 6px 0 0;cursor:pointer;font-size:13px;font-weight:500;color:var(--text-secondary,#64748b);display:flex;align-items:center;gap:6px;margin-bottom:-1px">
          <span class="file-lang-badge file-lang-en" style="font-size:10px">EN</span> ${t('descrEn')||'Description EN'}
        </button>
        <div style="flex:1"></div>
        <div style="display:flex;gap:4px;align-items:center;padding-right:4px" title="${t('translate')||'Traduci'}">
          ${_renderTransArrow('grpDescrTA_IT','grpDescrTA_EN','it','en')}
          ${_renderTransArrow('grpDescrTA_EN','grpDescrTA_IT','en','it')}
        </div>
      </div>
      <div id="grpDescrPanIT" style="padding:8px">
        <textarea id="grpDescrTA_IT" rows="20" placeholder="${t('descrIt')||'Descrizione'}…" style="width:100%;box-sizing:border-box" data-testid="input-grp-descr-it">${esc(descrIT)}</textarea>
      </div>
      <div id="grpDescrPanEN" style="padding:8px;display:none">
        <textarea id="grpDescrTA_EN" rows="20" placeholder="${t('descrEn')||'Description'}…" style="width:100%;box-sizing:border-box" data-testid="input-grp-descr-en">${esc(descrEN)}</textarea>
      </div>
    </div>`;

  const _rteIT = _initRichEditor('grpDescrTA_IT', { placeholder: (t('descrIt')||'Descrizione IT') + '…', minHeight: 420, editorMinHeight: 380 });
  const _rteEN = _initRichEditor('grpDescrTA_EN', { placeholder: (t('descrEn')||'Description EN') + '…', minHeight: 420, editorMinHeight: 380 });

  const _tabIT = box.querySelector('#grpDescrTabIT');
  const _tabEN = box.querySelector('#grpDescrTabEN');
  const _panIT = box.querySelector('#grpDescrPanIT');
  const _panEN = box.querySelector('#grpDescrPanEN');

  const _switchTab = (lang) => {
    const isIT = lang === 'it';
    _panIT.style.display = isIT ? '' : 'none';
    _panEN.style.display = isIT ? 'none' : '';
    _tabIT.style.background = isIT ? 'var(--bg-panel,#fff)' : 'transparent';
    _tabIT.style.borderBottomColor = isIT ? 'var(--bg-panel,#fff)' : 'transparent';
    _tabIT.style.fontWeight = isIT ? '600' : '500';
    _tabIT.style.color = isIT ? 'var(--text-primary,#0f172a)' : 'var(--text-secondary,#64748b)';
    _tabEN.style.background = isIT ? 'transparent' : 'var(--bg-panel,#fff)';
    _tabEN.style.borderBottomColor = isIT ? 'transparent' : 'var(--bg-panel,#fff)';
    _tabEN.style.fontWeight = isIT ? '500' : '600';
    _tabEN.style.color = isIT ? 'var(--text-secondary,#64748b)' : 'var(--text-primary,#0f172a)';
    setTimeout(() => { try { (isIT ? _rteIT : _rteEN).focus(); } catch(e){} }, 0);
  };
  _tabIT.onclick = () => _switchTab('it');
  _tabEN.onclick = () => _switchTab('en');
  setTimeout(() => { try { _rteIT.focus(); } catch(e){} }, 60);

  box.querySelector('#grpDescrSaveBtn').onclick = async () => {
    const newIT = _rteIT ? _rteIT.getValue() : (box.querySelector('#grpDescrTA_IT').value || '').trim();
    const newEN = _rteEN ? _rteEN.getValue() : (box.querySelector('#grpDescrTA_EN').value || '').trim();
    await DB.updateProceedingGroup(groupId, { descrIt: newIT, descrEn: newEN });
    await showProceedingGroupDetail(groupId);
  };
  box.querySelector('#grpDescrCancelBtn').onclick = async () => {
    await showProceedingGroupDetail(groupId);
  };
}

const TIMELINE_COLORS = {
  penale: '#3b82f6',
  civile: '#22c55e',
  esecuzione: '#ef4444',
  amministrativo: '#eab308',
  altro: '#8b5cf6'
};

let _caseTlAllEvents = [];

async function renderCaseTimeline(caseId, opts) {
  opts = opts || {};
  const containerId = opts.containerId || 'caseTimelineContainer';
  const container = document.getElementById(containerId);
  if (!container) return;

  let proceedings = await DB.getProceedings(caseId);
  if (opts.procFilter) {
    const _allowed = opts.procFilter instanceof Set ? opts.procFilter : new Set(opts.procFilter);
    proceedings = proceedings.filter(p => _allowed.has(p.id));
  }
  _caseTlAllEvents = [];
  const procBlocks = [];

  for (const proc of proceedings) {
    const sd = proc.specificData || {};
    const evList = [];
    const procEvents = sd.events || [];
    const phases = sd.phases || [];

    // Usa gli eventi auto-sincronizzati (sd.events) come fonte principale
    // Includono gia' le decisioni PM con sottoTipo
    for (const ev of procEvents) {
      if (ev.date) evList.push({
        autoId: ev.autoId || '',
        date: ev.date,
        title: ev.title || '',
        description: ev.description || '',
        magistrate: ev.magistrate || '',
        phaseType: ev.phaseRef || _procFirstPhase || 'fase_procura',
        procTitle: buildProcTitle(proc),
        sottoTipo: ev.sottoTipo || '',
        pmTipo: ev.pmTipo || ''
      });
    }
    // Fallback: ph.events manuali se non ci sono eventi auto
    if (evList.length === 0) {
      for (const ph of phases) {
        for (const ev of (ph.events || [])) {
          if (ev.date) evList.push({
            date: ev.date,
            title: ev.title || '',
            description: ev.description || '',
            magistrate: ev.magistrate || '',
            phaseType: ph.tipo || 'generale',
            procTitle: buildProcTitle(proc),
            sottoTipo: '',
            pmTipo: ''
          });
        }
      }
    }

    if (evList.length > 0) {
      evList.sort((a, b) => a.date.localeCompare(b.date));
      for (const ev of evList) _caseTlAllEvents.push(ev);
      procBlocks.push({ proc, events: evList, phases });
    }
  }

  if (_caseTlAllEvents.length === 0) {
    container.innerHTML = `<p class="hint">${t('timelineNoEvents')}</p>`;
    return;
  }

  _caseTlAllEvents.sort((a, b) => a.date.localeCompare(b.date));

  const _iscEvs = _caseTlAllEvents.filter(e => e.autoId && e.autoId.startsWith('auto_iscrizione_'));
  const globalMin = _iscEvs.length > 0 ? new Date(_iscEvs[0].date) : new Date(_caseTlAllEvents[0].date);
  const globalMax = new Date(_caseTlAllEvents[_caseTlAllEvents.length - 1].date);
  const globalMs = Math.max(globalMax - globalMin, 86400000);
  const dateLabels = generateTimelineDateLabels(globalMin, globalMax);

  let globalDotIdx = 0;
  const lanesHtml = procBlocks.map(({ proc, events, phases }) => {
    const badge = typeToBadge(proc.type, proc.specificData?.origineProc);
    const badgeHtml = badge ? `<span class="tree-badge ${badge.cls}" style="font-size:10px">${esc(badge.label)}</span>` : '';
    const procTitle = esc(buildProcTitle(proc));
    const baseColor = proc.type === 'penale' ? '#bae6fd' : (TIMELINE_COLORS[proc.type] || '#7dd3fc');

    // Linea maestra con gradiente di fase
    const sortedPhases = phases.filter(ph => ph.dataIscrizione && ph.tipo).sort((a, b) => a.dataIscrizione.localeCompare(b.dataIscrizione));
    const masterGradient = (() => {
      if (sortedPhases.length < 2) return PHASE_COLORS[sortedPhases[0]?.tipo] || baseColor;
      const stops = sortedPhases.map(ph => {
        const pct = Math.round(Math.max(0, Math.min(100, ((new Date(ph.dataIscrizione) - globalMin) / globalMs) * 100)));
        return `${PHASE_COLORS[ph.tipo] || baseColor} ${pct}%`;
      });
      return `linear-gradient(to right, ${stops.join(', ')})`;
    })();

    // Raggruppa per fase
    const grouped = {};
    for (const ev of events) {
      if (!grouped[ev.phaseType]) grouped[ev.phaseType] = [];
      grouped[ev.phaseType].push(ev);
    }

    const procLanesHtml = Object.entries(grouped).map(([pt, evs]) => {
      const phaseColor = PHASE_COLORS[pt] || baseColor;
      const positions = evs.map(ev => Math.max(0, ((new Date(ev.date) - globalMin) / globalMs) * 100));
      const lineStart = Math.min(...positions);
      const lineWidth = Math.max(0.5, Math.max(...positions) - lineStart);
      const dots = evs.map((ev, i) => {
        const pos = positions[i];
        const idx = globalDotIdx++;
        const dotColor = (ev.sottoTipo && PM_DOT_COLORS[ev.sottoTipo]) ? PM_DOT_COLORS[ev.sottoTipo]
                       : (ev.autoId && ev.autoId.startsWith('auto_iscrizione_')) ? '#22c55e'
                       : phaseColor;
        const isAlert = ['#ef4444','#f97316'].includes(dotColor) && ev.sottoTipo;
        return `<div class="tl-dot${isAlert ? ' tl-dot-alert' : ''}" style="left:${pos}%;color:${dotColor}" data-case-tl-idx="${idx}" onclick="showCaseTlPopup(this,${idx})" title="${esc(_tlFormatDate(ev.date))} \u2014 ${esc(ev.title)}"></div>`;
      }).join('');
      return `<div class="tl-lane">
        <div class="tl-lane-track">
          <div class="tl-lane-line" style="background:${phaseColor};left:${lineStart}%;width:${lineWidth}%;right:auto"></div>
          ${dots}
        </div>
      </div>`;
    }).join('');

    return `
      <div class="case-tl-proc-section">
        <div class="case-tl-proc-label">${badgeHtml}&nbsp;${procTitle}</div>
        ${procLanesHtml}
      </div>`;
  }).join('');

  container.innerHTML = `
    <div class="tl-header-row">
      <div></div>
      <button class="btn btn-xs" onclick="showCaseEventListModal()" data-testid="btn-case-event-list">${t('timelineEventList')}</button>
    </div>
    <div class="case-tl-chart">
      ${lanesHtml}
      <div class="tl-date-axis">${dateLabels}</div>
    </div>`;

  document.addEventListener('click', _closeCaseTlPopup);
}


function _closeCaseTlPopup(e) {
  if (!e.target.closest('.tl-popup') && !e.target.closest('[data-case-tl-idx]')) {
    document.querySelectorAll('.tl-popup').forEach(p => p.remove());
    document.querySelectorAll('.tl-dot-active').forEach(d => d.classList.remove('tl-dot-active'));
  }
}

function showCaseTlPopup(dotEl, idx) {
  document.querySelectorAll('.tl-popup').forEach(p => p.remove());
  document.querySelectorAll('.tl-dot-active').forEach(d => d.classList.remove('tl-dot-active'));
  const ev = _caseTlAllEvents[idx];
  if (!ev) return;
  dotEl.classList.add('tl-dot-active');
  const color = (ev.sottoTipo && PM_DOT_COLORS[ev.sottoTipo]) ? PM_DOT_COLORS[ev.sottoTipo] : (PHASE_COLORS[ev.phaseType] || '#7dd3fc');
  const phaseLbl = t(ev.phaseType) || ev.phaseType;
  const sottoLbl = ev.sottoTipo ? (t(ev.sottoTipo) || ev.sottoTipo) : '';
  const popup = document.createElement('div');
  popup.className = 'tl-popup';
  popup.innerHTML = `
    <div class="tl-popup-phase"><span class="tl-popup-phase-dot" style="background:${color}"></span>${esc(phaseLbl)}${sottoLbl ? ` \u2014 <em>${esc(sottoLbl)}</em>` : ''}</div>
    <div class="tl-popup-date">${_tlFormatDate(ev.date)}</div>
    <div class="tl-popup-title">${esc(ev.title)}</div>
    ${ev.procTitle ? `<div class="tl-popup-mag" style="font-style:italic;font-size:.76rem">${esc(ev.procTitle)}</div>` : ''}
    ${ev.magistrate ? `<div class="tl-popup-mag">${esc(ev.magistrate)}</div>` : ''}
    ${ev.description ? `<div class="tl-popup-desc">${esc(ev.description)}</div>` : ''}
  `;
  document.body.appendChild(popup);
  const rect = dotEl.getBoundingClientRect();
  popup.style.left = (rect.left + rect.width / 2 - popup.offsetWidth / 2) + 'px';
  popup.style.top = (rect.top - popup.offsetHeight - 12 + window.scrollY) + 'px';
}

