function _actFromPdfHitTestAnnotHandle(a, lW, lH, x, y) {
  if (!a) return null;
  if (a.type === 'rect_mark') return null;
  const HR = 8;
  if (a.type === 'line') {
    const x1 = a.x1 * lW, y1 = a.y1 * lH;
    const x2 = a.x2 * lW, y2 = a.y2 * lH;
    if ((x - x1) * (x - x1) + (y - y1) * (y - y1) <= HR * HR) return 'p1';
    if ((x - x2) * (x - x2) + (y - y2) * (y - y2) <= HR * HR) return 'p2';
    const tol = Math.max((a.strokeWidth || 2) + 4, 6);
    const dx = x2 - x1, dy = y2 - y1;
    const len2 = dx * dx + dy * dy;
    let tt = 0;
    if (len2 > 0) tt = Math.max(0, Math.min(1, ((x - x1) * dx + (y - y1) * dy) / len2));
    const px = x1 + tt * dx, py = y1 + tt * dy;
    const d2 = (x - px) * (x - px) + (y - py) * (y - py);
    if (d2 <= tol * tol) return 'move';
    return null;
  }
  if (a.type === 'rect_mark') {
    const rx = a.x * lW, ry = a.y * lH;
    const rw = a.w * lW, rh = a.h * lH;
    const corners = [
      { id: 'nw', cx: rx,      cy: ry },
      { id: 'ne', cx: rx + rw, cy: ry },
      { id: 'sw', cx: rx,      cy: ry + rh },
      { id: 'se', cx: rx + rw, cy: ry + rh },
    ];
    for (const c of corners) {
      if (Math.abs(x - c.cx) <= HR && Math.abs(y - c.cy) <= HR) return c.id;
    }
    if (x >= rx && x <= rx + rw && y >= ry && y <= ry + rh) return 'move';
    return null;
  }
  return null;
}
function _actFromPdfHitTestAnnot(pageNum, lW, lH, x, y) {
  const state = _actFromPdfState;
  if (!state) return -1;
  const annots = state.annotations.get(pageNum) || [];
  for (let i = annots.length - 1; i >= 0; i--) {
    const a = annots[i];
    if (a.type === 'line') {
      const x1 = a.x1 * lW, y1 = a.y1 * lH;
      const x2 = a.x2 * lW, y2 = a.y2 * lH;
      const tol = Math.max((a.strokeWidth || 2) + 4, 6);
      const dx = x2 - x1, dy = y2 - y1;
      const len2 = dx * dx + dy * dy;
      let tt = 0;
      if (len2 > 0) tt = Math.max(0, Math.min(1, ((x - x1) * dx + (y - y1) * dy) / len2));
      const px = x1 + tt * dx, py = y1 + tt * dy;
      const d2 = (x - px) * (x - px) + (y - py) * (y - py);
      if (d2 <= tol * tol) return i;
    }
  }
  return -1;
}
