  const currentFact = await DB.getFact(factId);
  if (!currentFact) return;
  const allFacts = await DB.getAllFacts();
  const otherFacts = allFacts.filter(f => f.id !== factId);

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1400;display:flex;align-items:center;justify-content:center';

  const modal = document.createElement('div');
  modal.className = 'modal-content';
  modal.style.cssText = 'background:var(--bg-panel);border-radius:8px;padding:24px;max-width:600px;width:95%;max-height:80vh;display:flex;flex-direction:column;gap:12px;box-shadow:0 8px 32px rgba(0,0,0,0.3)';

  modal.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between">
      <h3 style="margin:0">${t('addCausalRelation')}</h3>
      <button class="modal-close" data-testid="button-close-causal-picker">✕</button>
    </div>
    <input type="text" id="causalFactSearch" placeholder="${t('searchFactPlaceholder')}" class="input" style="width:100%"
      data-testid="input-causal-fact-search" oninput="_filterCausalFactList()" />
    <div id="causalFactList" style="overflow-y:auto;max-height:50vh;display:flex;flex-direction:column;gap:6px">
      ${otherFacts.length === 0
        ? `<div class="sublist-empty">${t('noCausalRelations')}</div>`
        : otherFacts.map(f => `<div class="fact-column-item" data-causal-id="${f.id}" data-causal-title="${esc(f.title).replace(/"/g,'&quot;')}"
            style="cursor:pointer" onclick="_selectCausalFact(${factId}, ${f.id})" data-testid="causal-fact-option-${f.id}">
            <div class="fact-column-item-title">${esc(f.title)}</div>
            ${f.factDate ? `<div class="fact-column-item-meta">${esc(_chronoDateStr(f))}</div>` : ''}
          </div>`).join('')}
    </div>`;

  modal.querySelector('.modal-close').onclick = () => overlay.remove();
  overlay.appendChild(modal);
  overlay.onclick = (e) => { e.stopPropagation(); };
