function _filterCausalFactList() {
  const q = (document.getElementById('causalFactSearch')?.value || '').toLowerCase();
  const items = document.querySelectorAll('#causalFactList [data-causal-id]');
  items.forEach(el => {
    const title = (el.dataset.causalTitle || '').toLowerCase();
    el.style.display = title.includes(q) ? '' : 'none';
  });
}

async function _selectCausalFact(fromFactId, toFactId) {
  document.querySelector('.modal-overlay[style*="1400"]')?.remove();
  await new Promise(res => setTimeout(res, 80));
  _showRelationTypeModal(
    ['causa', 'consegue_da', 'connesso_a'],
    tFactCausalRelType,
    async (relType) => {
      let causeId, effectId, storedType;
      if (relType === 'consegue_da') {
        causeId = toFactId;
        effectId = fromFactId;
        storedType = 'causa';
      } else if (relType === 'connesso_a') {
        causeId = fromFactId;
        effectId = toFactId;
        storedType = 'connesso_a';
      } else {
        causeId = fromFactId;
        effectId = toFactId;
        storedType = 'causa';
      }
      await DB.createFactCausalRelation({ causeFactId: causeId, effectFactId: effectId, relationType: storedType });
      await _updateFactAnalysisColumns(_factAnalysisSelectedId);
    }
  );
}

async function _deleteCausalRel(relId) {
  await DB.deleteFactCausalRelation(relId);
  await _updateFactAnalysisColumns(_factAnalysisSelectedId);
}

