async function _factAnalysisLinkSubject(factId) {
  if (!factId) return;
  const fact = await DB.getFact(factId);
  if (!fact) return;
  const allSubjects = await DB.getSubjects();
  const existingLinks = await DB.getEntitySubjects('fact', factId);
  const existingIds = new Set(existingLinks.map(l => l.subjectId));
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1400;display:flex;align-items:center;justify-content:center';

  const renderList = (filter) => {
    const q = (filter || '').toLowerCase();
    const filtered = allSubjects.filter(s => {
      if (existingIds.has(s.id)) return false;
      if (!q) return true;
      return (`${s.firstName} ${s.lastName}`).toLowerCase().includes(q) || (s.salutation || '').toLowerCase().includes(q);
    });
    if (!filtered.length) return `<div class="sublist-empty">${t('noSubjectsAvailable')}</div>`;
    return filtered.map(s => {
      const name = `${s.salutation ? s.salutation + ' ' : ''}${s.firstName} ${s.lastName}`.trim();
      const _ico = '👤';
      return `<div class="fact-column-item" data-subj-id="${s.id}" data-subj-name="${esc(name).replace(/"/g,'&quot;')}"
          style="cursor:pointer;padding:10px 12px;gap:4px;overflow:visible" onclick="_selectFactSubject(${factId},${s.id})" data-testid="fact-subj-option-${s.id}">
          <div style="font-size:13px;font-weight:600;line-height:1.5;display:flex;align-items:center;gap:6px;color:var(--text-primary);padding:2px 0"><span style="flex-shrink:0">${_ico}</span><span style="flex:1;min-width:0;word-break:break-word">${esc(name)}</span></div>
          ${s.descriptionIt ? `<div style="font-size:11px;color:var(--text-secondary);line-height:1.4;word-break:break-word;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden">${esc(s.descriptionIt)}</div>` : ''}
        </div>`;
    }).join('');
  };

  overlay.innerHTML = `<div class="modal-content" style="background:var(--bg-panel);border-radius:8px;padding:24px;max-width:520px;width:95%;max-height:80vh;display:flex;flex-direction:column;gap:12px;box-shadow:0 8px 32px rgba(0,0,0,0.3)">
    <div style="display:flex;align-items:center;justify-content:space-between">
      <h3 style="margin:0">${t('addSubjectToFact') || 'Collega soggetto al fatto'}</h3>
      <button class="modal-close" onclick="this.closest('.modal-overlay').remove()" data-testid="button-close-fact-subj-picker">✕</button>
    </div>
    <input type="text" id="factSubjSearch" placeholder="${t('searchSubjectPlaceholder') || 'Cerca soggetto…'}" class="input" style="width:100%"
      data-testid="input-fact-subj-search" oninput="document.getElementById('factSubjList').innerHTML=_renderFactSubjList(${factId},this.value)" />
    <div id="factSubjList" style="overflow-y:auto;max-height:46vh;display:flex;flex-direction:column;gap:4px">
      ${renderList('')}
    </div>
  </div>`;

  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  document.body.appendChild(overlay);

  window._renderFactSubjList = (fid, q) => renderList(q);
}

async function _selectFactSubject(factId, subjectId) {
  document.querySelector('.modal-overlay[style*="1400"]')?.remove();
  let procType = 'altro';
  let subjName = '';
  try {
    const subj = await DB.getSubject(subjectId);
    if (subj) subjName = `${subj.firstName || ''} ${subj.lastName || ''}`.trim();
    const fact = await DB.getFact(factId);
    if (fact && fact.dossierId) {
      const dossier = await DB.getDossier(fact.dossierId);
      if (dossier && dossier.proceedingId) {
        const proc = await DB.getProceeding(dossier.proceedingId);
        if (proc && proc.type) procType = proc.type;
      }
    }
  } catch(e) { /* ignore */ }
  const roles = (ROLE_CATALOGS[procType] || ROLE_CATALOGS['altro']).map(rc => ({ roleCode: rc, roleId: rc }));
  const finalize = async (roleLabel) => {
    await DB.linkSubject({ entityType: 'fact', entityId: factId, subjectId, roleLabel: roleLabel || '' });
    await _updateFactAnalysisColumns(factId);
  };
  if (roles.length === 0) { await finalize(''); return; }
  const existing = document.querySelector('.fact-subj-link-role-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay fact-subj-link-role-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:10100;display:flex;align-items:center;justify-content:center';
  const roleItems = roles.map(r => `<button class="btn btn-sm" style="display:block;width:100%;margin-bottom:6px;text-align:left" data-rcode="${esc(r.roleCode)}" data-testid="fact-subj-link-role-opt-${r.roleId}">${esc(tRole(r.roleCode))}</button>`).join('');
  overlay.innerHTML = `<div class="modal-content" style="background:var(--bg-panel);border-radius:8px;padding:20px;max-width:420px;width:92%;display:flex;flex-direction:column;gap:10px;box-shadow:0 8px 32px rgba(0,0,0,0.3)">
    <h3 style="margin:0">${t('subjectPickerRoles')}</h3>
    <p class="hint" style="margin:0">👤 ${esc(subjName)}</p>
    <div style="max-height:50vh;overflow-y:auto;margin-top:6px">${roleItems}</div>
    <div class="form-actions" style="display:flex;justify-content:space-between;gap:8px">
      <button class="btn btn-xs" id="factSubjLinkRoleNone" data-testid="btn-fact-subj-link-role-none">${t('subjectPickerNoRoles') || 'Senza ruolo'}</button>
      <button class="btn btn-xs" id="factSubjLinkRoleClose" data-testid="btn-fact-subj-link-role-close">${t('cancel') || 'Annulla'}</button>
    </div>
  </div>`;
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  document.body.appendChild(overlay);
  overlay.querySelectorAll('button[data-rcode]').forEach(btn => {
    btn.onclick = async () => { const rcode = btn.dataset.rcode; overlay.remove(); await finalize(tRole(rcode) || ''); };
  });
  overlay.querySelector('#factSubjLinkRoleNone').onclick = async () => { overlay.remove(); await finalize(''); };
  overlay.querySelector('#factSubjLinkRoleClose').onclick = () => overlay.remove();
}

