async function _selectCircSubject(circId, subjectId, factId) {
  document.querySelector('.modal-overlay[style*="1400"]')?.remove();
  const all = await _getSubjectsWithRolesForFact(factId);
  const sw = all.find(x => x.subject && x.subject.id === subjectId);
  const roles = (sw && sw.roles) ? sw.roles : [];
  const finalize = async (roleLabel) => {
    await DB.linkSubjectToCircumstance(circId, subjectId, roleLabel || '');
    await _updateFactAnalysisColumns(factId || _factAnalysisSelectedId);
  };
  if (roles.length === 0) { await finalize(''); return; }
  if (roles.length === 1) { await finalize(tRole(roles[0].roleCode) || ''); return; }
  const existing = document.querySelector('.circ-subj-role-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay circ-subj-role-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:10100;display:flex;align-items:center;justify-content:center';
  const subjName = sw && sw.subject ? `${sw.subject.firstName || ''} ${sw.subject.lastName || ''}`.trim() : '';
  const roleItems = roles.map(r => `<button class="btn btn-sm" style="display:block;width:100%;margin-bottom:6px;text-align:left" data-rcode="${esc(r.roleCode)}" data-testid="circ-subj-link-role-opt-${r.roleId}">${esc(tRole(r.roleCode))}</button>`).join('');
  overlay.innerHTML = `<div class="modal-content" style="background:var(--bg-panel);border-radius:8px;padding:20px;max-width:420px;width:92%;display:flex;flex-direction:column;gap:10px;box-shadow:0 8px 32px rgba(0,0,0,0.3)">
    <h3 style="margin:0">${t('subjectPickerRoles')}</h3>
    <p class="hint" style="margin:0">👤 ${esc(subjName)}</p>
    <div style="max-height:50vh;overflow-y:auto;margin-top:6px">${roleItems}</div>
    <div class="form-actions" style="display:flex;justify-content:space-between;gap:8px">
      <button class="btn btn-xs" id="circSubjLinkRoleNone" data-testid="btn-circ-subj-link-role-none">${t('subjectPickerNoRoles') || 'Senza ruolo'}</button>
      <button class="btn btn-xs" id="circSubjLinkRoleClose" data-testid="btn-circ-subj-link-role-close">${t('cancel') || 'Annulla'}</button>
    </div>
  </div>`;
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  document.body.appendChild(overlay);
  overlay.querySelectorAll('button[data-rcode]').forEach(btn => {
    btn.onclick = async () => { const rcode = btn.dataset.rcode; overlay.remove(); await finalize(tRole(rcode) || ''); };
  });
  overlay.querySelector('#circSubjLinkRoleNone').onclick = async () => { overlay.remove(); await finalize(''); };
  overlay.querySelector('#circSubjLinkRoleClose').onclick = () => overlay.remove();
}

async function _factAnalysisAddNormForSubject(factId, subjectId) {
  if (!factId || !subjectId) return;
  const all = await _getSubjectsWithRolesForFact(factId);
  const sw = all.find(x => x.subject && x.subject.id === subjectId);
  const roles = (sw && sw.roles) ? sw.roles : [];
  const proceed = (roleId) => {
    state._normPickerPreSelectedSubjectIds = [{ subjectId, roleId: roleId || null }];
    _openNormPickerModal('fact-card', factId);
  };
  if (roles.length === 0) { proceed(null); return; }
  if (roles.length === 1) { proceed(roles[0].roleId); return; }
  const existing = document.querySelector('.fact-subj-role-overlay');
  if (existing) existing.remove();
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay fact-subj-role-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:10100;display:flex;align-items:center;justify-content:center';
  const subjName = sw && sw.subject ? `${sw.subject.firstName || ''} ${sw.subject.lastName || ''}`.trim() : '';
  const roleItems = roles.map(r => `<button class="btn btn-sm" style="display:block;width:100%;margin-bottom:6px;text-align:left" data-rid="${r.roleId}" data-testid="fact-subj-role-opt-${r.roleId}">${esc(tRole(r.roleCode))}</button>`).join('');
  overlay.innerHTML = `<div class="modal-content" style="background:var(--bg-panel);border-radius:8px;padding:20px;max-width:420px;width:92%;display:flex;flex-direction:column;gap:10px;box-shadow:0 8px 32px rgba(0,0,0,0.3)">
    <h3 style="margin:0">${t('subjectPickerRoles')}</h3>
    <p class="hint" style="margin:0">👤 ${esc(subjName)}</p>
    <div style="max-height:50vh;overflow-y:auto;margin-top:6px">${roleItems}</div>
    <div class="form-actions" style="display:flex;justify-content:space-between;gap:8px">
      <button class="btn btn-xs" id="factSubjRoleNone" data-testid="btn-fact-subj-role-none">${t('subjectPickerNoRoles') || 'Senza ruolo'}</button>
      <button class="btn btn-xs" id="factSubjRoleClose" data-testid="btn-fact-subj-role-close">${t('cancel') || 'Annulla'}</button>
    </div>
  </div>`;
  overlay.onclick = e => { if (e.target === overlay) overlay.remove(); };
  document.body.appendChild(overlay);
  overlay.querySelectorAll('button[data-rid]').forEach(btn => {
    btn.onclick = () => { const rid = parseInt(btn.dataset.rid); overlay.remove(); proceed(rid); };
  });
  overlay.querySelector('#factSubjRoleNone').onclick = () => { overlay.remove(); proceed(null); };
  overlay.querySelector('#factSubjRoleClose').onclick = () => overlay.remove();
}

