async function _openCircumstanceDetailModal(circId) {
  const c = await DB.getCircumstance(circId);
  if (!c) return;
  const typeLabel = t('circumstance' + c.tipo.charAt(0).toUpperCase() + c.tipo.slice(1));
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.style.zIndex = '10001';
  overlay.onclick = (e) => { e.stopPropagation(); };
  let body = `<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px">
    <strong style="font-size:16px">${esc(c.title || c.descrizione || '')}</strong>
    <span class="tree-badge tree-badge-neutral">${typeLabel}</span>
  </div>`;
  if (c.descrizione) {
    body += `<div class="fact-col-field"><div class="fact-col-field-label">${t('description')}</div><div class="fact-col-field-value rte-content">${_renderRichForView(c.descrizione)}</div></div>`;
  }
  if (c.descrizioneEN) {
    body += `<div class="fact-col-field"><div class="fact-col-field-label">${t('description')} (EN)</div><div class="fact-col-field-value rte-content">${_renderRichForView(c.descrizioneEN)}</div></div>`;
  }
  if (c.title && c.title !== c.descrizione) {
    body += `<div class="fact-col-field"><div class="fact-col-field-label">${t('title')}</div><div class="fact-col-field-value">${esc(c.title)}</div></div>`;
  }
  if (c.titleEN) {
    body += `<div class="fact-col-field"><div class="fact-col-field-label">${t('title')} (EN)</div><div class="fact-col-field-value">${esc(c.titleEN)}</div></div>`;
  }
  const cpRels = await DB.getCircumstanceProofRelations(circId);
  const caRels = await DB.getCircumstanceActRelations(circId);
  const circModalRegularProofNames = [];
  const circModalAttoProvaProofNames = [];
  for (const r of cpRels) {
    const p = await DB.getProof(r.proofId);
    if (!p) continue;
    const sharedSrc = await DB.getSharedSourceEntityIds('proof', p.id);
    if (sharedSrc && sharedSrc.length > 0) {
      circModalAttoProvaProofNames.push(esc(p.title || ''));
    } else {
      circModalRegularProofNames.push(esc(p.title || ''));
    }
  }
  const circModalRegularActNames = [];
  const circModalAttoProvaActNames = [];
  for (const r of caRels) {
    const a = await DB.getAct(r.actId);
    if (!a) continue;
    if (a.type === 'prova') {
      circModalAttoProvaActNames.push(esc(a.title || ''));
    } else {
      circModalRegularActNames.push(esc(a.title || ''));
    }
  }
  if (circModalRegularProofNames.length > 0) {
    body += `<div class="fact-col-field"><div class="fact-col-field-label">${t('linkedProofsHeader')} (${circModalRegularProofNames.length})</div><div class="fact-col-field-value">${circModalRegularProofNames.join(', ')}</div></div>`;
  }
  if (circModalRegularActNames.length > 0) {
    body += `<div class="fact-col-field"><div class="fact-col-field-label">${t('linkedActsHeader')} (${circModalRegularActNames.length})</div><div class="fact-col-field-value">${circModalRegularActNames.join(', ')}</div></div>`;
  }
  const circModalAttoProvaAll = [...circModalAttoProvaActNames, ...circModalAttoProvaProofNames];
  if (circModalAttoProvaAll.length > 0) {
    body += `<div class="fact-col-field fact-col-field-atto-prova"><div class="fact-col-field-label fd-atto-prova-label">\uD83D\uDCC1 ATTI PROVA NEL FASCICOLO (${circModalAttoProvaAll.length})</div><div class="fact-col-field-value">${circModalAttoProvaAll.join(', ')}</div></div>`;
  }
  overlay.innerHTML = `<div class="modal-content" style="max-width:500px" data-testid="modal-circumstance-detail">
    <div class="modal-header">
      <h3>${t('viewCircumstanceDetail')}</h3>
      <button class="modal-close" onclick="this.closest('.modal-overlay').remove()" data-testid="button-close-circ-detail">✕</button>
    </div>
    <div class="modal-body" style="padding:16px 0">${body}</div>
    <div class="modal-footer" style="display:flex;gap:8px;justify-content:flex-end;padding:12px 0 0;border-top:1px solid var(--border)">
      <button class="btn btn-sm" onclick="this.closest('.modal-overlay').remove()" data-testid="button-close-circ-detail-footer">${t('close')}</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
}

async function _renderLinkedCircumstancesColumn(circBody, fact, factId) {
  const _rawCircs = _isMemoContext ? await DB.getMemoCircostanze(factId) : await DB.getCircumstances(factId);
  const circumstances = _rawCircs.sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || a.id - b.id);
  const logicState = await computeFactLogicState(fact);

  if (circumstances.length > 0 && !_selectedCircumstanceId) {
    _selectedCircumstanceId = circumstances[0].id;
  }

  let html = '';

  html += `<div class="fact-col-section">`;
  if (circumstances.length > 0) {
    const circIds = circumstances.map(c => c.id);
    // ── Relazioni Prova-Circostanza (normale vs memo) ────────────────────────
    let circPRelsMap = {};
    let circProofsMap = {};
    if (_isMemoContext) {
      const allMemoCircPRels = await DB.getMemoCircProofRels(factId);
      circIds.forEach(id => {
        circPRelsMap[id] = allMemoCircPRels
          .filter(r => r.archivioCircId === id)
          .map(r => ({ ...r, proofId: r.archivioProofId }));
      });
      const memoProofIds = new Set(allMemoCircPRels.map(r => r.archivioProofId));
      const memoProofsArr = await Promise.all([...memoProofIds].map(id => DB.getMemoProof(id)));
      memoProofsArr.forEach(p => { if (p) circProofsMap[p.id] = p; });
    } else {
      const allCircPRels = await Promise.all(circIds.map(id => DB.getCircumstanceProofRelations(id)));
      circIds.forEach((id, i) => { circPRelsMap[id] = allCircPRels[i]; });
      const circProofIds = new Set();
      Object.values(circPRelsMap).forEach(arr => arr.forEach(r => circProofIds.add(r.proofId)));
      const circProofsArr = await Promise.all([...circProofIds].map(id => DB.getProof(id)));
      circProofsArr.forEach(p => { if (p) circProofsMap[p.id] = p; });
    }
    // ── Relazioni Atto-Circostanza ───────────────────────────────────────────
    let circARelsMap = {};
    let circActsMap = {};
    if (_isMemoContext) {
      const allMemoCircARels = await DB.getMemoCircActRels(factId);
      // Normalizziamo le rels in modo che `actId` punti a `archivioActId`
      circIds.forEach(id => {
        circARelsMap[id] = allMemoCircARels
          .filter(r => r.archivioCircId === id)
          .map(r => ({ ...r, actId: r.archivioActId, posizioneAtto: r.posizioneAtto }));
      });
      const memoActIds = new Set(allMemoCircARels.map(r => r.archivioActId));
      const memoActsArr = await Promise.all([...memoActIds].map(id => DB.getMemoAtto(id)));
      memoActsArr.forEach(a => {
        if (a) circActsMap[a.id] = { ...a, type: a.actType, subtype: a.actSubtype };
      });
    } else {
      const allCircARels = await Promise.all(circIds.map(id => DB.getCircumstanceActRelations(id)));
      circIds.forEach((id, i) => { circARelsMap[id] = allCircARels[i]; });
      const circActIds = new Set();
      Object.values(circARelsMap).forEach(arr => arr.forEach(r => circActIds.add(r.actId)));
      const circActsArr = await Promise.all([...circActIds].map(id => DB.getAct(id)));
      circActsArr.forEach(a => { if (a) circActsMap[a.id] = a; });
    }
    const circActIds = new Set();
    Object.values(circARelsMap).forEach(arr => arr.forEach(r => circActIds.add(r.actId)));

    const factActRelsArr = _isMemoContext ? [] : await DB.getFactActRelations(factId);
    const factActRelsByActId = {};
    factActRelsArr.forEach(r => { factActRelsByActId[r.actId] = r; });

    let circDRelsMap = {};
    let circDossiersMap = {};
    if (_proofEditActive && !_isMemoContext) {
      const allCircDRels = await Promise.all(circIds.map(id => DB.getCircumstanceDossierRelations(id)));
      circIds.forEach((id, i) => { circDRelsMap[id] = allCircDRels[i]; });
      const circDossierIds = new Set();
      Object.values(circDRelsMap).forEach(arr => arr.forEach(r => circDossierIds.add(r.dossierId)));
      const circDossiersArr = await Promise.all([...circDossierIds].map(id => DB.getDossier(id)));
      circDossiersArr.forEach(d => { if (d) circDossiersMap[d.id] = d; });
    }

    const allCircNRels = _isMemoContext
      ? circIds.map(() => [])
      : await Promise.all(circIds.map(id => DB.getCircumstanceNormaRelations(id)));
    const circNRelsMap = {};
    circIds.forEach((id, i) => { circNRelsMap[id] = allCircNRels[i]; });

    const _allNrIds = allCircNRels.flat().map(nr => nr.id);
    const _allNrSubjectLinks = await Promise.all(_allNrIds.map(nrId => DB.getNormSubjectLinks('circNorm', nrId)));
    const circNormSubjectLinksMap = {};
    _allNrIds.forEach((nrId, i) => { circNormSubjectLinksMap[nrId] = _allNrSubjectLinks[i]; });

    const _allCircActIds = [...circActIds];
    const _allCircProofIds = Object.keys(circProofsMap).map(Number);
    const [_actProvArr, _proofProvArr] = await Promise.all([
      Promise.all(_allCircActIds.map(id => DB.getEntityProvenance('act', id))),
      Promise.all(_allCircProofIds.map(id => DB.getEntityProvenance('proof', id)))
    ]);
    const circActHasSrcMap = {};
    _allCircActIds.forEach((id, i) => { circActHasSrcMap[id] = _actProvArr[i] || 'external'; });
    const circProofHasSrcMap = {};
    _allCircProofIds.forEach((id, i) => { circProofHasSrcMap[id] = _proofProvArr[i] || 'external'; });

    const circSubjectsMap = {};
    if (!_isMemoContext) {
      const _circSubjArr = await Promise.all(circIds.map(id => DB.getCircumstanceSubjects(id)));
      circIds.forEach((id, i) => { circSubjectsMap[id] = _circSubjArr[i] || []; });
    }

    // Prefetch dei file di TUTTE le prove e atti delle circostanze, in
    // un'unica passata, per renderizzare le icone download all'estrema
    // destra delle card del modale Analisi fatto. Il map sottostante e`
    // sincrono: il prefetch deve avvenire prima.
    const _circProofFilesById = {};
    const _circActFilesById = {};
    {
      const _pIds = Object.keys(circProofsMap).map(Number).filter(n => Number.isFinite(n));
      const _aIds = Object.keys(circActsMap).map(Number).filter(n => Number.isFinite(n));
      await Promise.all([
        ..._pIds.map(async _id => {
          try { _circProofFilesById[_id] = await DB.getEntityFiles('proof', _id) || []; }
          catch (_) { _circProofFilesById[_id] = []; }
        }),
        ..._aIds.map(async _id => {
          try { _circActFilesById[_id] = await DB.getEntityFiles('act', _id) || []; }
          catch (_) { _circActFilesById[_id] = []; }
        }),
      ]);
    }

    const circItems = circumstances.map((c, _ci) => {
      const circSeqBadge = `<span class="circ-seq-badge" title="Circostanza ${_ci + 1}">CR${String(_ci + 1).padStart(2, '0')}</span>`;
      const typeLabel = t('circumstance' + c.tipo.charAt(0).toUpperCase() + c.tipo.slice(1));
      const typeBadgeCls = c.tipo === 'aggravante' ? 'tree-badge-deny' : c.tipo === 'attenuante' ? 'tree-badge-confirm' : 'tree-badge-neutral';
      const cpRels = circPRelsMap[c.id] || [];
      const cnt = cpRels.length;
      const caRelsCount = (circARelsMap[c.id] || []).length;
      const cnRelsEarly = circNRelsMap[c.id] || [];
      const nNormsBadge = cnRelsEarly.length > 0 ? `<span class="tree-badge tree-badge-N" style="font-size:9px" title="${t('normsColumnTitle') || 'Norme'}">N·${cnRelsEarly.length}</span>` : '';
      const _aZeroStyle = caRelsCount === 0 ? 'color:#dc2626;' : '';
      const _pZeroStyle = cnt === 0 ? 'color:#dc2626;' : '';
      const countBadge = _isMemoContext
        ? `<span class="tree-badge tree-badge-P" style="font-size:9px;${_pZeroStyle}" title="${t('proofsColumnTitle')}">P·${cnt}</span>`
        : `<span class="tree-badge tree-badge-A" style="font-size:9px;${_aZeroStyle}" title="${t('actActRelationsHeader')}">A·${caRelsCount}</span><span class="tree-badge tree-badge-P" style="font-size:9px;${_pZeroStyle}" title="${t('proofsColumnTitle')}">P·${cnt}</span>${nNormsBadge}`;
      const selClass = _selectedCircumstanceId === c.id ? ' circ-selected' : '';
      const circProofRelsFiltered = cpRels.filter(r => circProofsMap[r.proofId]);
      const caRels = circARelsMap[c.id] || [];
      const caRelsFiltered = caRels.filter(r => circActsMap[r.actId]);
      // Separa ATTO PROVA dai normali
      const attoProvaActRels = caRelsFiltered.filter(r => circActHasSrcMap[r.actId] !== 'external');
      const regularActRels = caRelsFiltered.filter(r => circActHasSrcMap[r.actId] === 'external');
      const attoProvaProofRels = circProofRelsFiltered.filter(r => circProofHasSrcMap[r.proofId] !== 'external');
      const regularProofRels = circProofRelsFiltered.filter(r => circProofHasSrcMap[r.proofId] === 'external');
      const regularProofs = regularProofRels.map(r => circProofsMap[r.proofId]);
      const regularActs = regularActRels.map(r => circActsMap[r.actId]);
      // Sezione ATTI PROVA COLLEGATI
      const circAttoProvaActItems = attoProvaActRels.map(r => {
        const act = circActsMap[r.actId];
        if (!act) return '';
        const _pos = r.posizioneAtto || null;
        const _posBadge = _pos ? factPositionBadge(_pos) : { cls: 'tree-badge-neutral', label: '○' };
        const relLabel = _pos ? tFactPosition(_pos) : 'Collegato';
        const typeLabel2 = actTypeBadge(act.type, act.subtype);
        const unlinkActBtn = _proofEditActive
          ? `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkActFromCircumstance(${act.id},${c.id})" title="${t('unlink')}" data-testid="button-unlink-ap-circ-act-${act.id}">✂</button>`
          : '';
        return `<div class="sublist-item fd-linked-item" style="display:flex;align-items:center;gap:4px">
          <span class="tree-badge ${_posBadge.cls}" style="font-size:9px;flex-shrink:0;min-width:90px;text-align:center;justify-content:center;display:inline-flex" title="${esc(relLabel)}">${esc(relLabel)}</span>
          <span style="flex:1;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(act.title)}</span>
          ${unlinkActBtn}
        </div>`;
      }).join('');
      const circAttoProvaProofItems = attoProvaProofRels.map(r => {
        const p = circProofsMap[r.proofId];
        if (!p) return '';
        const mediaIcon = {document:'📄',image:'🖼️',audio:'🎵',video:'🎬'}[p.mediaType] || '📄';
        const mediaTypeLabel = {document:t('mediaDocument')||'Documento', image:t('mediaImage')||'Immagine', audio:t('mediaAudio')||'Audio', video:t('mediaVideo')||'Video'}[p.mediaType] || 'Documento';
        const relLabel2 = tCircProofRelType(r.relationType);
        const relBadgeCls2 = {confirms:'tree-badge-confirm', contradicts:'tree-badge-deny', describes:'tree-badge-neutral'}[r.relationType] || 'tree-badge-neutral';
        const unlinkProofBtn = _proofEditActive
          ? `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkProofFromCircumstance(${p.id},${c.id},${factId})" title="${t('unlink')}" data-testid="button-unlink-ap-circ-proof-${p.id}">✂</button>`
          : '';
        return `<div class="sublist-item fd-linked-item" style="display:flex;align-items:center;gap:4px">
          <span class="tree-badge ${relBadgeCls2}" style="font-size:9px;flex-shrink:0;min-width:90px;text-align:center;justify-content:center;display:inline-flex" title="${esc(relLabel2 || 'collega')}">${esc(relLabel2 || 'collega')}</span>
          <span style="flex:1;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(p.title)}</span>
          ${unlinkProofBtn}
        </div>`;
      }).join('');
      const circAttoProvaAllItems = circAttoProvaActItems + circAttoProvaProofItems;
      const circAttoProvaSection = circAttoProvaAllItems
        ? `<div class="sublist-section" style="border-left:3px solid #eab308;padding-left:6px;margin-bottom:6px">
            <div class="sublist-section-header" style="color:#eab308">\uD83D\uDCC1 ATTI PROVA NEL FASCICOLO</div>
            ${circAttoProvaAllItems}
          </div>`
        : '';
      // Atti esterni (inline, stesso look della card Fatto)
      const circRegularActItems = regularActs.map((a, idx) => {
        const r = regularActRels[idx];
        const _pos = r?.posizioneAtto || 'afferma';
        const _posBadge = factPositionBadge(_pos);
        const relLabel = tFactPosition(_pos);
        const unlinkActBtn = _proofEditActive
          ? `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkActFromCircumstance(${a.id},${c.id})" data-testid="button-unlink-circ-act-${a.id}" title="${t('unlink')}">✂</button>`
          : '';
        return `<div class="sublist-item fd-linked-item" onclick="event.stopPropagation();openViewActModal(${a.id},'${_pos}')" data-testid="circ-card-act-${a.id}" style="cursor:pointer;display:flex;align-items:center;gap:4px">
          <span class="tree-badge ${_posBadge.cls}" style="font-size:9px;flex-shrink:0;min-width:90px;text-align:center;justify-content:center;display:inline-flex" title="${esc(relLabel)}">${esc(relLabel)}</span>
          <span style="flex:1;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(a.title || '')}</span>
          ${unlinkActBtn}
        </div>`;
      }).join('');
      const circActsSublist = circRegularActItems
        ? `<div class="sublist-section" data-testid="circ-card-acts-section" style="border-left:3px solid #ea580c;padding-left:6px;margin-bottom:6px">
            <div class="sublist-section-header" style="color:#ea580c">
              <span>${currentLang === 'en' ? 'External acts' : 'Atti esterni'}</span>
            </div>
            ${circRegularActItems}
          </div>`
        : '';
      // Prove esterne (inline, stesso look della card Fatto)
      const circRegularProofItems = regularProofs.map((p, idx) => {
        const r = regularProofRels[idx];
        const relType = r?.relationType || 'confirms';
        const relLabel = tCircProofRelType(relType);
        const relCls = (relType === 'confirms') ? 'tree-badge-confirm' : (relType === 'contradicts') ? 'tree-badge-deny' : 'tree-badge-neutral';
        const unlinkProofBtn = _proofEditActive
          ? `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkProofFromCircumstance(${p.id},${c.id},${factId})" data-testid="button-unlink-circ-proof-${p.id}" title="${t('unlink')}">✂</button>`
          : '';
        const clickAttr = (!_isMemoContext)
          ? `onclick="event.stopPropagation();openViewProofModal(${p.id},'${relType}')"`
          : '';
        return `<div class="sublist-item fd-linked-item" data-testid="circ-card-proof-${p.id}" style="${clickAttr ? 'cursor:pointer;' : ''}display:flex;align-items:center;gap:4px" ${clickAttr}>
          <span class="tree-badge ${relCls}" style="font-size:9px;flex-shrink:0;min-width:90px;text-align:center;justify-content:center;display:inline-flex" title="${esc(relLabel || 'collega')}">${esc(relLabel || 'collega')}</span>
          <span style="flex:1;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(p.title || '')}</span>
          ${unlinkProofBtn}
        </div>`;
      }).join('');
      const circProofsItems = circRegularProofItems;
      let circStateBadge = '';
      if (_isMemoContext) {
        if (cnt === 0) {
          circStateBadge = `<span class="circ-state-badge circ-state-senza-prove" data-circ-state="NO_PROOFS">${t('circStateSenzaProve')}</span>`;
        }
      } else {
        // Atti "AF" (con sourceFileId) valgono anche come prova implicita.
        // circActHasSrcMap[actId] === 'external' -> atto esterno; qualsiasi
        // altro valore (af/af_pec/...) indica file proveniente dal fascicolo.
        const _amfInDossActIds = new Set(
          caRels.filter(ar => circActHasSrcMap[ar.actId] && circActHasSrcMap[ar.actId] !== 'external').map(ar => ar.actId)
        );
        const circState = DB.computeCircumstanceLogicalState(caRels, cpRels, c.natura, _amfInDossActIds);
        const _isOmPgAg = (c.natura === 'omissione_pg_ag');
        const circStateMap = {
          COHERENT:     ['provata',          t('circStateConfermata')],
          INCOHERENCE:  ['distorsione-ag',   t('circStateDistorsioneAg')],
          OMISSION:     ['omissione-ag',     _isOmPgAg ? t('circStateOmissionePgAg') : t('circStateOmissioneAg')],
          DOCUMENTED:   ['ag-silenziosa',    t('circStateAgSilenziosa')],
          TO_DOCUMENT:  ['da-documentare',   t('circStateDocumentare')],
          UNCLASSIFIED: ['non-classificata', t('circStateNonClassificata')],
          NO_PROOFS:    ['senza-prove',      t('circStateSenzaProve')],
          NO_ACTS:      ['senza-prove',      t('factNoActs')],
          HAS_PROOFS:   ['senza-prove',      t('factHasProofs')],
        };
        const [circStateCls, circStateLabel] = circStateMap[circState] || ['senza-prove', circState];
        circStateBadge = `<span class="circ-state-badge circ-state-${circStateCls}" data-circ-state="${circState}" style="cursor:pointer;" title="${t('logicBadgeClickHint')}">${circStateLabel}</span>`;
      }
      const cdRels = circDRelsMap[c.id] || [];
      const cdRelsFiltered = cdRels.filter(r => circDossiersMap[r.dossierId]);
      const linkedDossiers = cdRelsFiltered.map(r => circDossiersMap[r.dossierId]);
      const circDossiersItems = _renderDossiersSublist(linkedDossiers, {type:'circDossier', factId: factId, indented: true}, cdRelsFiltered);
      const circTipoProveSection = (circRegularProofItems
        ? `<div class="sublist-section" data-testid="circ-card-proofs-section" style="border-left:3px solid #ea580c;padding-left:6px;margin-bottom:6px">
            <div class="sublist-section-header" style="color:#ea580c">
              <span>${currentLang === 'en' ? 'External proofs' : 'Prove esterne'}</span>
            </div>
            ${circRegularProofItems}
          </div>`
        : '') + (circDossiersItems
        ? `<div class="fact-item-proofs-row" style="border-bottom:1px solid rgba(0,0,0,0.12);padding-bottom:6px;margin-bottom:6px"><div class="proof-sublist-header">${t('tipoProveCollegate')}</div>${circDossiersItems}</div>`
        : '');
      const cnRels = circNRelsMap[c.id] || [];
      const circNormsSublist = _renderNormsSublist(cnRels, {circId: c.id, factId: factId, circTipo: c.tipo}, circNormSubjectLinksMap);
      return `<div class="fact-col-detail-item circ-item-clickable${selClass}"
        data-testid="circumstance-item-${c.id}"
        data-circ-id="${c.id}"
        ${_proofEditActive ? 'draggable="true"' : ''}
        onclick="_selectCircumstanceFilter(${c.id})"
        ondragstart="${_proofEditActive ? `_circReorderDragStart(event,${c.id})` : 'void(0)'}"
        ondragend="_circReorderDragEnd(event)"
        ondragover="_circDragOver(event)"
        ondragleave="_circDragLeave(event)"
        ondrop="_circDrop(event, ${c.id}, ${factId})">
        <div class="card-header-area">
          <div class="card-row-top">
            <div class="card-badges">
              ${_proofEditActive ? `<span class="circ-drag-handle" title="Trascina per riordinare">⠿</span>` : ''}
              ${circSeqBadge}
              ${circStateBadge}
              ${countBadge}
            </div>
            <div class="card-actions">
              ${_proofEditActive ? creatorOnly(`<button class="btn btn-xs" onclick="event.stopPropagation(); openCircumstanceModal(${factId}, ${c.id}, async () => { await _updateFactAnalysisColumns(${factId}); })" data-testid="button-edit-circ-${c.id}">${t('edit')}</button>`) : ''}
              ${_proofEditActive ? creatorOnly(`<button class="btn btn-xs btn-danger" onclick="event.stopPropagation(); _deleteCircumstanceInAnalysis(${c.id}, ${factId})" data-testid="button-delete-circ-${c.id}">${t('delete')}</button>`) : ''}
            </div>
          </div>
          <div class="card-title-row" onclick="event.stopPropagation(); _openCircumstanceDetailModal(${c.id})" style="cursor:pointer;text-decoration:underline dotted;text-underline-offset:2px;display:flex;align-items:center;gap:5px;flex-wrap:nowrap;overflow:hidden" title="${esc(c.title || c.descrizione || '')}">${(c.tipo !== 'aggravante' && c.tipo !== 'attenuante') ? `<span class="tree-badge ${typeBadgeCls}" style="font-size:9px;flex-shrink:0">${typeLabel}</span>` : ''}<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0">${esc(c.title || c.descrizione || '')}</span></div>
        </div>
        ${(() => {
          const _csLinks = circSubjectsMap[c.id] || [];
          const _csSection = (() => {
            if (_csLinks.length === 0 && !_proofEditActive) return '';
            const _csItems = _csLinks.map(sl => {
              const subj = sl.subject;
              if (!subj) return '';
              const _name = esc(`${subj.salutation ? subj.salutation + ' ' : ''}${subj.firstName} ${subj.lastName}`.trim());
              const _roleChip = sl.roleLabel ? `<span class="tree-badge" style="font-size:9px;background:rgba(255,255,255,0.12);color:rgba(255,255,255,0.85);border-color:rgba(255,255,255,0.25);max-width:100px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(sl.roleLabel)}">${esc(sl.roleLabel)}</span>` : '';
              const _unlink = _proofEditActive ? `<button class="btn-unlink" onclick="event.stopPropagation();_circAnalysisUnlinkSubject(${sl.id},${c.id},${factId})" title="${t('unlink')}" data-testid="button-unlink-circ-subj-${sl.id}">✂</button>` : '';
              const _addNormBtn = (!_isMemoContext && _proofEditActive) ? `<button class="btn btn-xs" style="font-size:9px;padding:0 4px;background:#dc2626;border-color:#b91c1c;color:#fff;flex-shrink:0" onclick="event.stopPropagation();_circAnalysisAddNormForSubject(${factId},${c.id},${subj.id})" title="${t('addCircumstanceNorm')}" data-testid="button-add-circ-subj-norm-${sl.id}">+ norma</button>` : '';
              const _sIco = '👤';
              return `<div class="sublist-item" onclick="event.stopPropagation();showSubjectDetail(${subj.id})" style="cursor:pointer;display:flex;align-items:center;gap:4px" data-testid="circ-col-subj-${sl.id}">
                <span style="flex:1;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_sIco} ${_name}</span>
                ${_roleChip}${_unlink}${_addNormBtn}
              </div>`;
            }).join('');
            const _addBtn = (!_isMemoContext && _proofEditActive) ? `<button class="btn btn-xs" style="font-size:10px;margin-left:auto" onclick="event.stopPropagation();_circAnalysisLinkSubject(${c.id},${factId})" data-testid="button-add-circ-subject-${c.id}">+ Soggetto</button>` : '';
            return `<div class="sublist-section"><div class="sublist-section-header" style="display:flex;align-items:center"><span>👥 ${t('circSubjectsHeader')}</span>${_addBtn}</div>${_csItems || `<div style="font-size:10px;color:var(--text-secondary)">${t('noCircSubjects')}</div>`}</div>`;
          })();
          const _circDescSection = c.descrizione ? `<div class="rte-content" style="font-size:11px;color:var(--text-secondary);padding:4px 0 2px;word-break:break-word;text-align:justify;hyphens:auto">${_renderRichForView(c.descrizione)}</div>` : '';
          return `<div class="card-body"><div class="card-details">${_circDescSection}${circAttoProvaSection}${circActsSublist}${circTipoProveSection}${_csSection}${circNormsSublist}</div></div>`;
        })()}
      </div>`;
    });
    html += circItems.join('');
  } else {
    html += `<p class="hint" style="padding:0 8px">${t('noCircumstances')}</p>`;
  }
  html += `</div>`;

  circBody.innerHTML = html;
  _enrichViolNormBadges(circBody);
}

async function _updateProofsColumn(factId) {
  const proofsBody = document.getElementById('factColProofsBody');
  if (!proofsBody) return;
  try { await _buildFactAllMap(factId); } catch (_) {}

  if (_isMemoContext) {
    const memoProofs = await DB.getMemoProofs(factId);
    if (!memoProofs.length) {
      proofsBody.innerHTML = `<p class="hint" style="padding:12px;font-size:12px;color:var(--text-secondary)">${t('noProofs') || 'Nessuna prova'}</p>`;
      return;
    }
    const _L = currentLang === 'en';
    const mtLabels = { document: t('mediaDocument') || 'Documento', image: t('mediaImage') || 'Immagine', audio: t('mediaAudio') || 'Audio', video: t('mediaVideo') || 'Video', pec: t('mediaPec') || 'PEC' };
    const allCircPRels = await DB.getMemoCircProofRels(factId);
    const allActPRels = await DB.getMemoActProofRels(factId);
    const memoAttiArr = await DB.getMemoAtti(factId);
    const memoAttiById = {};
    memoAttiArr.forEach(a => { memoAttiById[a.id] = a; });
    const proofCircCountMap = {};
    allCircPRels.forEach(r => { proofCircCountMap[r.archivioProofId] = (proofCircCountMap[r.archivioProofId] || 0) + 1; });
    const proofActCountMap = {};
    allActPRels.forEach(r => { proofActCountMap[r.archivioProofId] = (proofActCountMap[r.archivioProofId] || 0) + 1; });
    proofsBody.innerHTML = memoProofs.map(p => {
      const mt = p.mediaType || 'document';
      const mtLabel = mtLabels[mt] || mt;
      const title = _L ? (p.titleEN || p.title || '') : (p.title || '');
      const cCount = proofCircCountMap[p.id] || 0;
      const aCount = proofActCountMap[p.id] || 0;
      const relsBadges = `<span class="tree-badge tree-badge-neutral" style="font-size:9px" title="${t('circumstancesColumnTitle')}">C·${cCount}</span>${aCount > 0 ? `<span class="tree-badge tree-badge-A" style="font-size:9px" title="${t('actsColumnTitle')}">A·${aCount}</span>` : ''}`;
      const editActions = _proofEditActive ? `
        ${creatorOnly(`<button class="btn btn-xs" onclick="event.stopPropagation();_openCreateProofModal(${factId},()=>_updateProofsColumn(${factId}),{editMemoProofId:${p.id}})" data-testid="button-memo-edit-proof-${p.id}">${t('edit')}</button>`)}
        ${creatorOnly(`<button class="btn btn-xs btn-danger" onclick="event.stopPropagation();_amfDeleteProof(${p.id},${factId})" data-testid="button-memo-delete-proof-${p.id}">${t('delete')}</button>`)}
      ` : '';
      // Sublist atti collegati a questa prova
      const linkedActRels = allActPRels.filter(r => r.archivioProofId === p.id);
      const actRows = linkedActRels.map(r => {
        const a = memoAttiById[r.archivioActId];
        if (!a) return '';
        const aTitle = _L ? (a.titleEN || a.title || '') : (a.title || '');
        const relLabel = tActProofRelType(r.relationType);
        const relCls = { cita_a_supporto: 'tree-badge-confirm', cita_a_contrario: 'tree-badge-deny', non_considera: 'tree-badge-neutral' }[r.relationType] || 'tree-badge-neutral';
        const unlinkBtn = _proofEditActive ? `<button class="btn-unlink" onclick="event.stopPropagation();_amfUnlinkActProof(${a.id},${p.id},${factId})" title="${t('unlink')}" data-testid="button-unlink-memo-proof-act-${p.id}-${a.id}">✂</button>` : '';
        return `<div class="proof-sublist-item" style="display:flex;align-items:center;gap:4px">
          <span class="tree-badge ${relCls}" style="font-size:9px;flex-shrink:0">${esc(relLabel || 'collega')}</span>
          <span style="flex:1;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(aTitle)}</span>
          ${unlinkBtn}
        </div>`;
      }).filter(Boolean).join('');
      const actsSublist = actRows ? `<div class="sublist-section"><div class="sublist-section-header"><span>${t('actsColumnTitle') || 'Atti'}</span></div>${actRows}</div>` : '';
      const dropAttrs = _proofEditActive ? `ondragover="_factItemDragOver(event)" ondragleave="_factItemDragLeave(event)" ondrop="_memoProofItemDrop(event,${p.id},${factId})"` : '';
      return `<div class="fact-col-detail-item" draggable="true" ondragstart="_memoProofDragStart(event,${p.id})" style="cursor:${_proofEditActive ? 'grab' : 'default'}" data-testid="memo-proof-${p.id}" ${dropAttrs}>
        <div class="card-header-area">
          <div class="card-row-top">
            <div class="card-badges">${relsBadges}</div>
            <div class="card-actions">${editActions}</div>
          </div>
          <div class="card-title-row" title="${esc(title || ('Prova #' + p.id))}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">
            <span class="tree-badge tree-badge-neutral" style="font-size:9px;flex-shrink:0;margin-right:4px">${esc(mtLabel)}</span>${esc(title || ('Prova #' + p.id))}
          </div>
        </div>
        ${actsSublist ? `<div class="card-body"><div class="card-details">${actsSublist}</div></div>` : ''}
      </div>`;
    }).join('');
    return;
  }

  const mtLabels = { document: t('mediaDocument'), image: t('mediaImage'), audio: t('mediaAudio'), video: t('mediaVideo'), pec: t('mediaPec') };

  // Mostra SOLO le prove collegate al fatto corrente (factProofRelations,
  // direttamente o tramite atti del fatto) + le prove orfane (nessuna
  // factProofRelations), cosi' restano disponibili per il drag-and-drop di
  // collegamento. Nessuna prova di altri fatti deve apparire qui.
  const linkedProofRels = await DB.getFactProofRelations(factId);
  const _linkedProofIds = new Set(linkedProofRels.map(r => r.proofId));
  const _factActRelsForProofs = await DB.getFactActRelations(factId);
  await Promise.all(_factActRelsForProofs.map(async ar => {
    const _apr = await DB.getActProofRelations(ar.actId);
    _apr.forEach(r => _linkedProofIds.add(r.proofId));
  }));
  const _allProofsRaw = await DB.getAllProofs();
  // Filtro unico: appartenenza per factId del record prova.
  let allDbProofs = _allProofsRaw.filter(p => p.factId === factId);
  // Reset contatori prove (anche in caso di early return)
  _amfStatP = 0; _amfStatPNoFile = 0; _amfStatAP_proofs = 0;
  const linkedProofRelMap = {};
  linkedProofRels.forEach(r => { linkedProofRelMap[r.proofId] = r; });

  const linkedActRels = await DB.getFactActRelations(factId);
  const proofLinkedViaActSet = new Set();
  await Promise.all(linkedActRels.map(async ar => {
    const actPRels = await DB.getActProofRelations(ar.actId);
    actPRels.forEach(r => proofLinkedViaActSet.add(r.proofId));
  }));
  // Prove collegate a una circostanza del fatto corrente (link diretto
  // tramite circumstanceProofRelations).
  const _factCircsForProofs = await DB.getCircumstances(factId);
  const _factCircIdsForProofs = new Set(_factCircsForProofs.map(c => c.id));
  const _allCircProofRels = await db.circumstanceProofRelations.toArray();
  const proofLinkedToFactCircSet = new Set(
    _allCircProofRels.filter(r => _factCircIdsForProofs.has(r.circumstanceId)).map(r => r.proofId)
  );

  const [allProofFactRelsArr, allProofCircRelsArr, allProofActRelsArr, allProofHasSourceArr, allProofFilesArr] = await Promise.all([
    Promise.all(allDbProofs.map(pr => DB.getProofFactRelations(pr.id))),
    Promise.all(allDbProofs.map(pr => DB.getProofCircumstanceRelations(pr.id))),
    Promise.all(allDbProofs.map(pr => DB.getProofActRelations(pr.id))),
    Promise.all(allDbProofs.map(pr => DB.getEntityHasSourceFile('proof', pr.id))),
    Promise.all(allDbProofs.map(pr => DB.getEntityFiles('proof', pr.id)))
  ]);
  const proofFactCountMap = {};
  const proofCircCountMap = {};
  const proofActCountMap = {};
  const proofHasSourceMap = {};
  const proofFileItMap = {};
  const proofFileEnMap = {};
  allDbProofs.forEach((pr, i) => {
    proofFactCountMap[pr.id] = allProofFactRelsArr[i].length;
    proofCircCountMap[pr.id] = allProofCircRelsArr[i].length;
    proofActCountMap[pr.id] = allProofActRelsArr[i].length;
    proofHasSourceMap[pr.id] = allProofHasSourceArr[i] || false;
    const _pFiles = allProofFilesArr[i] || [];
    proofFileItMap[pr.id] = _pFiles.filter(f => (f.lang||'it') === 'it');
    proofFileEnMap[pr.id] = _pFiles.filter(f => f.lang === 'en');
  });

  if (allDbProofs.length === 0) {
    proofsBody.innerHTML = `<p class="hint" style="padding:8px">${t('noResults')}</p>`;
    return;
  }

  // Back-fill folderPrefix/folderSeq per le prove preesistenti senza
  // numerazione persistita: PF se la prova ha almeno un file con
  // sourceFileId (lavora sul file del fascicolo via puntatore — utile
  // per video pesanti, no duplicato fisico), P altrimenti.
  // Una volta assegnata la categoria/sequenza non cambia piu'.
  {
    const _byDossier = new Map();
    for (const _p of allDbProofs) {
      if (_p.dossierId == null) continue;
      if (!_byDossier.has(_p.dossierId)) _byDossier.set(_p.dossierId, []);
      _byDossier.get(_p.dossierId).push(_p);
    }
    for (const [_did, _proofs] of _byDossier) {
      const _maxByPrefix = { PF: 0, PE: 0 };
      for (const _x of _proofs) {
        if (_x.folderPrefix && Number.isFinite(_x.folderSeq)) {
          const _xKey = (_x.folderPrefix === 'P') ? 'PE' : _x.folderPrefix;
          if (_xKey === 'PE' || _xKey === 'PF') {
            if ((_x.folderSeq || 0) > (_maxByPrefix[_xKey] || 0)) {
              _maxByPrefix[_xKey] = _x.folderSeq;
            }
          }
        }
      }
      for (const _p of _proofs) {
        if (_p.folderPrefix && Number.isFinite(_p.folderSeq)) continue;
        const _wanted = proofHasSourceMap[_p.id] ? 'PF' : 'PE';
        _maxByPrefix[_wanted] = (_maxByPrefix[_wanted] || 0) + 1;
        _p.folderPrefix = _wanted;
        _p.folderSeq = _maxByPrefix[_wanted];
        try { await DB.updateProof(_p.id, { folderPrefix: _p.folderPrefix, folderSeq: _p.folderSeq }); }
        catch (_) {}
      }
    }
  }

  allDbProofs.sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || a.id - b.id);

  const proofsHtml = allDbProofs.map(pr => {
    const mt = pr.mediaType || 'document';
    const isLinkedToFact = !!linkedProofRelMap[pr.id];
    const isLinkedToFactCirc = proofLinkedToFactCircSet.has(pr.id);
    const isLinkedViaAct = !isLinkedToFact && !isLinkedToFactCirc && proofLinkedViaActSet.has(pr.id);
    const isLinked = isLinkedToFact || isLinkedToFactCirc || isLinkedViaAct;
    const linkedBadge = (isLinkedToFact || isLinkedToFactCirc)
      ? `<span class="tree-badge tree-badge-confirm" style="font-size:9px" title="Collegata a questo fatto o a una sua circostanza">●</span>`
      : isLinkedViaAct
        ? `<span class="tree-badge tree-badge-neutral" style="font-size:9px" title="Collegata tramite atto">◉</span>`
        : '';
    // Orfano: nessun collegamento ad alcun fatto E ad alcuna circostanza.
    const isProofOrphan = (proofFactCountMap[pr.id] || 0) === 0 && (proofCircCountMap[pr.id] || 0) === 0;
    const orphanBadge = isProofOrphan ? `<span class="tree-badge" style="font-size:9px;background:#f59e0b;color:#fff;border-color:#f59e0b" title="Prova orfana: nessun collegamento ad alcun fatto o circostanza">ORFANA</span>` : '';
    const dimStyle = '';
    const fCount = proofFactCountMap[pr.id] || 0;
    const cCount = proofCircCountMap[pr.id] || 0;
    const aCount = proofActCountMap[pr.id] || 0;
    // Badge "ATTO PROVA DA FASCICOLO" rimosso: l'informazione e' gia'
    // veicolata dal prefisso PF### vs PE### nel seqBadge.
    const proofSharedSrcBadge = '';
    // Badge cartella persistente PF### / P### (analogo ad AF###/A### per atti).
    const _pHasFolder = !!pr.folderPrefix && Number.isFinite(pr.folderSeq);
    const _pExpPrefix = _pHasFolder ? (pr.folderPrefix === 'P' ? 'PE' : pr.folderPrefix) : (proofHasSourceMap[pr.id] ? 'PF' : 'PE');
    const _pSeqNum = _pHasFolder ? String(pr.folderSeq).padStart(3, '0') : '???';
    const _pSeqLabel = `${_pExpPrefix}${_pSeqNum}`;
    const _pSeqColor = _pExpPrefix === 'PF' ? '#0ea5e9' : '#16a34a';
    const _pSeqTitle = _pHasFolder
      ? (`Cartella ${_pSeqLabel}`)
      : (`(provvisorio) ${proofHasSourceMap[pr.id] ? 'Prova da fascicolo' : 'Prova esterna'}`);
    const _pSeqOpacity = _pHasFolder ? '1' : '0.7';
    const seqBadge = `<span class="tree-badge" style="font-size:9px;background:${_pSeqColor};color:#fff;border-color:${_pSeqColor};font-weight:600;letter-spacing:.3px;opacity:${_pSeqOpacity}" title="${_pSeqTitle}">${_pSeqLabel}</span>`;
    const relsBadges = `${proofSharedSrcBadge}<span class="tree-badge tree-badge-fact" style="font-size:9px" title="Fatti collegati">F·${fCount}</span><span class="tree-badge tree-badge-neutral" style="font-size:9px" title="Circostanze collegate">C·${cCount}</span><span class="tree-badge tree-badge-A" style="font-size:9px" title="Atti collegati">A·${aCount}</span>`;
    const editActions = _proofEditActive ? `
      ${creatorOnly(`<button class="btn btn-xs" onclick="event.stopPropagation(); openEditProofModal(${pr.id}, async () => { await _updateFactAnalysisColumns(${factId}); }, { factId: ${factId} })" data-testid="button-edit-proof-${pr.id}">${t('edit')}</button>`)}
      ${creatorOnly(`<button class="btn btn-xs btn-danger" onclick="event.stopPropagation(); _deleteProofInAnalysis(${pr.id}, ${factId})" data-testid="button-delete-proof-${pr.id}">${t('delete')}</button>`)}
    ` : '';
    const _proofFilesIt = proofFileItMap[pr.id] || [];
    const _proofFilesEn = proofFileEnMap[pr.id] || [];
    const _proofFileRowHtml = (f, lang) => {
      const isTranscript = f.fileRole === 'transcript_pdf';
      const icon = isTranscript ? '📝' : _dossFileIcon(f.fileType, f.diskFileName || f.fileName);
      const _isPdf = (((f.fileName||'') + '').toLowerCase().endsWith('.pdf'));
      const _dlColor = _isPdf ? '#b91c1c' : '#1d4ed8';
      const _hashBadge = (typeof renderHashBadgePlaceholder === 'function') ? renderHashBadgePlaceholder(f) : '';
      const _metaBtn = (typeof renderFileMetaBtn === 'function') ? renderFileMetaBtn(f) : '';
      const _allBadge = _factAllBadgeHtml(factId, f.id);
      return `<div class="card-file-row" data-testid="proof-file-name-${pr.id}-${f.id}" title="${esc(f.diskFileName||f.fileName)}"
        onclick="event.stopPropagation();openFilePreviewModal(${f.id})"
        style="cursor:pointer;display:flex;align-items:center;gap:4px">
        ${_allBadge}<span class="file-lang-badge file-lang-${lang}" style="font-size:9px;padding:1px 5px;margin-right:4px">${lang.toUpperCase()}</span><span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${icon} ${esc(f.diskFileName||f.fileName)}</span>${_metaBtn}${_hashBadge}<button class="card-file-dl-btn" onclick="event.stopPropagation();downloadFile(${f.id})" data-testid="button-dl-proof-file-${pr.id}-${f.id}" title="${t('download')||'Scarica'}" style="background:transparent;border:none;cursor:pointer;padding:0 4px;font-size:13px;line-height:1;color:${_dlColor};flex-shrink:0">⬇</button></div>`;
    };
    const proofFileHtml = _proofFilesIt.map(f => _proofFileRowHtml(f,'it')).join('') + _proofFilesEn.map(f => _proofFileRowHtml(f,'en')).join('');
    return `<div class="fact-col-detail-item" draggable="true"
      data-proof-id="${pr.id}"
      ondragstart="${_proofEditActive ? `_proofReorderDragStart(event,${pr.id})` : `_proofDragStart(event,${pr.id})`}"
      ondragend="_proofReorderDragEnd(event)"
      ondragover="_proofColumnDragOver(event)"
      ondragleave="_proofColumnDragLeave(event)"
      ondrop="_proofColumnDrop(event,${pr.id},${factId})"
      style="cursor:${_proofEditActive ? 'grab' : 'pointer'};${dimStyle}"
      onclick="openViewProofModal(${pr.id}, '${pr.relationType || 'confirms'}')"
      data-testid="proof-item-${pr.id}">
      <div class="card-header-area">
        <div class="card-row-top">
          <div class="card-badges">
            ${_proofEditActive ? `<span class="circ-drag-handle" title="Trascina per riordinare" onmousedown="event.stopPropagation()">⠿</span>` : ''}
            ${seqBadge}
            ${linkedBadge}
            ${orphanBadge}
            ${relsBadges}
          </div>
          <div class="card-actions">
            ${editActions}
          </div>
        </div>
        <div class="card-title-row" title="${esc(proofTitle(pr))}" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">
          <span class="tree-badge tree-badge-neutral" style="font-size:9px;flex-shrink:0;margin-right:4px">${mtLabels[mt] || mt}</span>${esc(proofTitle(pr))}
        </div>
      </div>
      ${proofFileHtml ? `<div class="card-body"><div class="card-details">${proofFileHtml}</div></div>` : ''}
    </div>`;
  }).join('');

  proofsBody.innerHTML = proofsHtml;
  if (typeof refreshHashBadgesIn === 'function') refreshHashBadgesIn(proofsBody).catch(() => {});

  // Calcola contatori prove per la header bar
  _amfStatP = 0; _amfStatPNoFile = 0; _amfStatAP_proofs = 0;
  for (const rel of linkedProofRels) {
    if (proofHasSourceMap[rel.proofId]) { _amfStatAP_proofs++; continue; }
    _amfStatP++;
    const proofFilesForStat = await DB.getEntityFiles('proof', rel.proofId);
    if (proofFilesForStat.length === 0) _amfStatPNoFile++;
  }
}

async function _selectFactInAnalysis(factId) {
  _selectedCircumstanceId = null;
  await _updateFactAnalysisColumns(factId);
}

async function _openFascConsultaModal(dossierId, opts) {
  const allFiles = await DB.getEntityFiles('dossier', dossierId);
  const htmlFile = allFiles.find(f =>
    f.fileRole === 'doss_extract' && /\.(html|htm)$/i.test(f.fileName || '')
  );
  if (htmlFile) {
    await _openFascicoloTelematicModal(dossierId, htmlFile, allFiles.filter(f => f.fileRole === 'doss_extract'));
    return;
  }
  await _openDossierDetailModal(dossierId, { readOnly: true, ...(opts || {}) });
}

async function _openFascConsultaForZip(dossierId, zipFileId) {
  const allFiles = await DB.getEntityFiles('dossier', dossierId);
  const extractFiles = allFiles.filter(f => f.fileRole === 'doss_extract');
  let htmlFile = extractFiles.find(f =>
    f.sourceFileId === zipFileId &&
    /\.(html|htm)$/i.test(f.fileName || '')
  );
  if (!htmlFile) {
    htmlFile = extractFiles.find(f =>
      f.sourceFileId == null &&
      /\.(html|htm)$/i.test(f.fileName || '')
    );
  }
  if (!htmlFile) return;
  await _openFascicoloTelematicModal(dossierId, htmlFile, extractFiles);
}

let _ftChoiceOverlay = null;
let _ftFullModalOverlay = null;
let _ftExtractFiles = null;

function _closeFtChoiceModal() {
  if (_ftChoiceOverlay) { _ftChoiceOverlay.remove(); _ftChoiceOverlay = null; }
}
function _closeFtFullModal() {
  if (_ftFullModalOverlay) { _ftFullModalOverlay.remove(); _ftFullModalOverlay = null; }
  _ftExtractFiles = null;
  _dossDetailZip = null;
  _dossDetailZipChoiceState = null;
}

function _showFascTypeChoiceModal(dossierId, dossTitle) {
  _closeFtChoiceModal();
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay ft-choice-overlay';
  overlay.innerHTML = `
    <div class="ft-choice-dialog">
      <div class="ft-choice-dialog-header">
        <span class="ft-choice-icon">📁</span>
        <div>
          <div class="ft-choice-doss-title">${esc(dossTitle)}</div>
          <div class="ft-choice-subtitle">${t('zipTypeChoiceTitle')}</div>
        </div>
      </div>
      <div class="ft-choice-buttons-row">
        <button class="ft-choice-btn" id="ftChoiceBtnExplore" data-testid="button-ft-choice-explore">
          <span class="ft-choice-btn-icon">🗂</span>
          <span class="ft-choice-btn-label">${t('zipChoiceExplore')}</span>
          <span class="ft-choice-btn-hint">${t('zipChoiceExploreHint')}</span>
        </button>
        <button class="ft-choice-btn ft-choice-btn-primary" id="ftChoiceBtnFasc" data-testid="button-ft-choice-fasc">
          <span class="ft-choice-btn-icon">📋</span>
          <span class="ft-choice-btn-label">${t('zipChoiceFasc')}</span>
          <span class="ft-choice-btn-hint">${t('zipChoiceFascHint')}</span>
        </button>
      </div>
      <button class="ft-choice-close" id="ftChoiceClose" data-testid="button-ft-choice-close">&times;</button>
    </div>`;
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  overlay.querySelector('#ftChoiceClose').onclick = () => _closeFtChoiceModal();
  overlay.querySelector('#ftChoiceBtnExplore').onclick = async () => {
    _closeFtChoiceModal();
    await _openDossierDetailModal(dossierId, { readOnly: true });
  };
  overlay.querySelector('#ftChoiceBtnFasc').onclick = async () => {
    _closeFtChoiceModal();
    await _openFascicoloTelematicModal(dossierId);
  };
  document.body.appendChild(overlay);
  _ftChoiceOverlay = overlay;
}

async function _openFascicoloTelematicModal(dossierId, htmlFile, extractFiles) {
  _closeFtFullModal();
  _ftExtractFiles = extractFiles || [];
  const dossier = await DB.getDossier(dossierId);
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay ft-full-overlay';
  overlay.innerHTML = `
    <div class="ft-full-modal">
      <div class="ft-full-header">
        <div class="ft-full-header-left">
          <span>📋</span>
          <span class="ft-full-title">${esc(dossier ? dossier.title : '')}</span>
        </div>
        <div class="ft-full-header-right">
          <div class="ft-search-bar" id="ftSearchBar">
            <input type="search" id="ftSearchInput" placeholder="${t('searchInDocument') || 'Cerca nel testo…'}" class="ft-search-input" data-testid="input-ft-search" autocomplete="off">
            <span class="ft-search-count" id="ftSearchCount"></span>
            <button class="ft-search-nav-btn" id="ftSearchPrev" title="${t('searchPrev') || 'Precedente (Shift+F3)'}" data-testid="button-ft-search-prev">&#8679;</button>
            <button class="ft-search-nav-btn" id="ftSearchNext" title="${t('searchNext') || 'Successivo (F3)'}" data-testid="button-ft-search-next">&#8681;</button>
            <button class="ft-search-nav-btn ft-search-clear" id="ftSearchClear" title="${t('searchClear') || 'Cancella ricerca'}" data-testid="button-ft-search-clear" style="display:none">&#10005;</button>
          </div>
          <button class="ft-pdf-search-btn" id="ftPdfSearchBtn" title="${t('searchInPdfs') || 'Cerca nei file PDF allegati'}" data-testid="button-ft-pdf-search">📄 PDF</button>
          <button class="fact-analysis-close" id="ftFullClose" data-testid="button-ft-full-close">&times;</button>
        </div>
      </div>
      <div class="ft-full-body ft-split-body" id="ftFullBody">
        <div class="ft-html-pane" id="ftHtmlPane">
          <p class="hint" style="padding:24px">${t('zipFtLoading')}</p>
        </div>
        <div class="ft-pdf-pane" id="ftPdfPane" style="display:none">
          <div class="ft-pdf-results-panel" id="ftPdfResultsPanel"></div>
          <div class="ft-pdf-viewer-wrap" id="ftPdfViewerWrap" style="display:none">
            <div class="ft-pdf-toolbar" id="ftPdfToolbar"></div>
            <div class="ft-pdf-canvas-outer" id="ftPdfCanvasOuter">
              <canvas id="ftPdfCanvas"></canvas>
              <div class="ft-pdf-textlayer" id="ftPdfTextLayer"></div>
            </div>
          </div>
        </div>
      </div>
    </div>`;
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  overlay.querySelector('#ftFullClose').onclick = () => _closeFtFullModal();

  // ---- Ricerca nel testo ----
  let _ftMatches = [], _ftMatchIdx = -1;

  function _ftClearHighlights() {
    const body = overlay.querySelector('#ftHtmlPane');
    if (!body) return;
    body.querySelectorAll('mark.ft-hl').forEach(m => {
      const txt = document.createTextNode(m.textContent);
      m.parentNode.replaceChild(txt, m);
      txt.parentNode && txt.parentNode.normalize();
    });
    _ftMatches = []; _ftMatchIdx = -1;
    const c = overlay.querySelector('#ftSearchCount');
    if (c) c.textContent = '';
  }

  function _ftRunSearch(query) {
    _ftClearHighlights();
    const clearBtn = overlay.querySelector('#ftSearchClear');
    if (clearBtn) clearBtn.style.display = query ? '' : 'none';
    if (!query || query.trim().length < 2) return;
    const q = query.trim();
    const re = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
    const body = overlay.querySelector('#ftHtmlPane');
    if (!body) return;
    const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, {
      acceptNode: (node) => {
        const tag = node.parentElement ? node.parentElement.tagName : '';
        if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'MARK') return NodeFilter.FILTER_REJECT;
        return node.textContent.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
      }
    });
    const nodes = [];
    let n;
    while ((n = walker.nextNode())) nodes.push(n);
    for (const textNode of nodes) {
      const text = textNode.textContent;
      re.lastIndex = 0;
      if (!re.test(text)) continue;
      re.lastIndex = 0;
      const frag = document.createDocumentFragment();
      let last = 0, m;
      while ((m = re.exec(text)) !== null) {
        if (m.index > last) frag.appendChild(document.createTextNode(text.slice(last, m.index)));
        const mark = document.createElement('mark');
        mark.className = 'ft-hl';
        mark.textContent = m[0];
        frag.appendChild(mark);
        _ftMatches.push(mark);
        last = m.index + m[0].length;
      }
      if (last < text.length) frag.appendChild(document.createTextNode(text.slice(last)));
      textNode.parentNode.replaceChild(frag, textNode);
    }
    const countEl = overlay.querySelector('#ftSearchCount');
    if (_ftMatches.length) {
      _ftMatchIdx = 0;
      _ftMatches[0].classList.add('ft-hl-current');
      _ftMatches[0].scrollIntoView({ block: 'center', behavior: 'smooth' });
      if (countEl) countEl.textContent = `1 / ${_ftMatches.length}`;
    } else {
      if (countEl) countEl.textContent = t('searchNoResults') || '0 risultati';
    }
  }

  function _ftNavSearch(dir) {
    if (!_ftMatches.length) return;
    _ftMatches[_ftMatchIdx].classList.remove('ft-hl-current');
    _ftMatchIdx = (_ftMatchIdx + dir + _ftMatches.length) % _ftMatches.length;
    const cur = _ftMatches[_ftMatchIdx];
    cur.classList.add('ft-hl-current');
    cur.scrollIntoView({ block: 'center', behavior: 'smooth' });
    const countEl = overlay.querySelector('#ftSearchCount');
    if (countEl) countEl.textContent = `${_ftMatchIdx + 1} / ${_ftMatches.length}`;
  }

  let _ftSearchTimer = null;
  const ftInput = overlay.querySelector('#ftSearchInput');
  ftInput.addEventListener('input', () => {
    clearTimeout(_ftSearchTimer);
    _ftSearchTimer = setTimeout(() => _ftRunSearch(ftInput.value), 300);
  });
  ftInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === 'F3') { e.preventDefault(); if (_ftPdfMode) _ftNavPdfMatch(e.shiftKey ? -1 : 1); else _ftNavSearch(e.shiftKey ? -1 : 1); }
    if (e.key === 'Escape') { ftInput.value = ''; _ftClearHighlights(); overlay.querySelector('#ftSearchClear').style.display = 'none'; if (_ftPdfMode) _ftResetPdfSearch(); }
  });
  overlay.querySelector('#ftSearchNext').onclick = () => { if (_ftPdfMode) _ftNavPdfMatch(1); else _ftNavSearch(1); };
  overlay.querySelector('#ftSearchPrev').onclick = () => { if (_ftPdfMode) _ftNavPdfMatch(-1); else _ftNavSearch(-1); };
  overlay.querySelector('#ftSearchClear').onclick = () => {
    ftInput.value = '';
    _ftClearHighlights();
    overlay.querySelector('#ftSearchClear').style.display = 'none';
    if (_ftPdfMode) _ftResetPdfSearch();
    ftInput.focus();
  };
  document.addEventListener('keydown', function _ftKeyHandler(e) {
    if (!_ftFullModalOverlay) { document.removeEventListener('keydown', _ftKeyHandler); return; }
    if (e.key === 'F3') { e.preventDefault(); if (_ftPdfMode) _ftNavPdfMatch(e.shiftKey ? -1 : 1); else _ftNavSearch(e.shiftKey ? -1 : 1); }
    if ((e.ctrlKey || e.metaKey) && e.key === 'f') { e.preventDefault(); ftInput.focus(); ftInput.select(); }
    if (e.key === 'Escape' && _ftPdfMode) { ftInput.value = ''; _ftClearHighlights(); overlay.querySelector('#ftSearchClear').style.display = 'none'; _ftResetPdfSearch(); }
  });

  // ---- Ricerca nei PDF ----
  let _ftPdfIndex = null;
  let _ftPdfMatches = [], _ftPdfMatchIdx = -1;
  let _ftPdfIndexing = false;
  let _ftPdfMode = false;
  let _ftPdfCurrentDoc = null;
  let _ftPdfCurrentQuery = '';
  let _ftPdfCurrentPage = 1;
  let _ftPdfCurrentNumPages = 0;
  let _ftPdfCurrentFileRec = null;
  let _ftPdfSearchTimer2 = null;

  async function _ftReadFileBlob(rec) {
    let blob = rec.blob;
    if (!blob && rec.storagePath) {
      try {
        let dir = (typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) ? FS_FILES_HANDLE
                : (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) ? FS_DIR_HANDLE : null;
        if (dir) {
          const parts = rec.storagePath.split('/').filter(Boolean);
          for (const part of parts) dir = await dir.getDirectoryHandle(part);
          const fh = await dir.getFileHandle(rec.diskFileName || rec.fileName);
          const file = await fh.getFile();
          blob = new Uint8Array(await file.arrayBuffer());
        }
      } catch(e) {}
    }
    return blob;
  }

  async function _ftBuildIndex() {
    if (_ftPdfIndex !== null || _ftPdfIndexing) return;
    _ftPdfIndexing = true;
    _ftPdfIndex = [];
    if (typeof pdfjsLib === 'undefined') { _ftPdfIndexing = false; return; }
    if (pdfjsLib.GlobalWorkerOptions) pdfjsLib.GlobalWorkerOptions.workerSrc = 'js/pdf.worker.min.js';
    const pdfFiles = (_ftExtractFiles || []).filter(f => /\.pdf$/i.test(f.fileName || ''));
    const resultsPanel = overlay.querySelector('#ftPdfResultsPanel');
    for (let i = 0; i < pdfFiles.length; i++) {
      const rec = pdfFiles[i];
      if (resultsPanel) resultsPanel.innerHTML =
        `<div class="ft-pdf-indexing-msg">⏳ Indicizzazione PDF… ${i + 1} / ${pdfFiles.length}<br><em>${esc(rec.fileName)}</em></div>`;
      try {
        const blobData = await _ftReadFileBlob(rec);
        if (!blobData) continue;
        const rawBytes = blobData instanceof Uint8Array ? blobData : new Uint8Array(blobData);
        const pdfDoc = await pdfjsLib.getDocument({ data: rawBytes.slice(0) }).promise;
        const pages = [];
        for (let pn = 1; pn <= pdfDoc.numPages; pn++) {
          try {
            const page = await pdfDoc.getPage(pn);
            const tc = await page.getTextContent();
            let pos = 0;
            const items = tc.items.map(item => {
              const str = item.str || '';
              const textStart = pos;
              const textEnd = pos + str.length;
              pos += str.length + 1; // +1 per spazio separatore
              return { str, transform: item.transform, width: item.width, height: item.height, textStart, textEnd };
            });
            const text = items.map(it => it.str).join(' ');
            if (text.trim()) pages.push({ pageNum: pn, text, items });
          } catch(e) { /* pagina senza testo */ }
        }
        _ftPdfIndex.push({ fileName: rec.fileName, fileRec: rec, pages });
        pdfDoc.destroy();
      } catch(e) { console.warn('FT PDF index err:', rec.fileName, e); }
    }
    _ftPdfIndexing = false;
    if (_ftPdfMode && ftInput.value.trim().length >= 2) _ftSearchInPdfs(ftInput.value.trim());
    else if (_ftPdfMode && resultsPanel) {
      resultsPanel.innerHTML = `<p class="ft-pdf-hint">${t('searchPdfHint') || 'Indicizzazione completata. Digita almeno 2 caratteri per cercare nei PDF.'}</p>`;
    }
  }

  function _ftSearchInPdfs(query) {
    _ftPdfMatches = []; _ftPdfMatchIdx = -1;
    const resultsPanel = overlay.querySelector('#ftPdfResultsPanel');
    const viewerWrap = overlay.querySelector('#ftPdfViewerWrap');
    if (!resultsPanel) return;
    if (_ftPdfIndexing || _ftPdfIndex === null) {
      resultsPanel.innerHTML = `<div class="ft-pdf-indexing-msg">⏳ Indicizzazione in corso…</div>`;
      return;
    }
    if (!query || query.trim().length < 2) {
      resultsPanel.innerHTML = `<p class="ft-pdf-hint">${t('searchPdfHint') || 'Digita almeno 2 caratteri per cercare nei PDF.'}</p>`;
      return;
    }
    const re = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
    for (let fi = 0; fi < _ftPdfIndex.length; fi++) {
      const entry = _ftPdfIndex[fi];
      for (const pg of entry.pages) {
        re.lastIndex = 0;
        let m;
        while ((m = re.exec(pg.text)) !== null) {
          const start = Math.max(0, m.index - 60);
          const end = Math.min(pg.text.length, m.index + m[0].length + 60);
          const pre = esc(pg.text.slice(start, m.index));
          const hit = esc(m[0]);
          const post = esc(pg.text.slice(m.index + m[0].length, end));
          const snippet = (start > 0 ? '…' : '') + pre + `<mark class="ft-hl">${hit}</mark>` + post + (end < pg.text.length ? '…' : '');
          _ftPdfMatches.push({ fi, fileName: entry.fileName, fileRec: entry.fileRec, pageNum: pg.pageNum, snippet,
            matchStart: m.index, matchEnd: m.index + m[0].length });
        }
      }
    }
    const countEl = overlay.querySelector('#ftSearchCount');
    if (!_ftPdfMatches.length) {
      resultsPanel.innerHTML = `<p class="ft-pdf-hint">${t('searchNoResults') || '0 risultati'}</p>`;
      if (countEl) countEl.textContent = '0';
      if (viewerWrap) viewerWrap.style.display = 'none';
      resultsPanel.style.display = '';
      return;
    }
    const nFiles = new Set(_ftPdfMatches.map(m => m.fileName)).size;
    if (countEl) countEl.textContent = `1 / ${_ftPdfMatches.length}`;
    let html = `<div class="ft-pdf-results-header"><span>${_ftPdfMatches.length} risultat${_ftPdfMatches.length === 1 ? 'o' : 'i'} in ${nFiles} file</span></div>`;
    html += `<div class="ft-pdf-results-list">`;
    _ftPdfMatches.forEach((m, idx) => {
      html += `<div class="ft-pdf-result-card" data-match-idx="${idx}" data-testid="ft-pdf-result-${idx}">
        <div class="ft-pdf-result-meta"><span class="ft-pdf-result-file">📄 ${esc(m.fileName)}</span> <span class="ft-pdf-result-page">pag. ${m.pageNum}</span></div>
        <div class="ft-pdf-result-snippet">${m.snippet}</div>
      </div>`;
    });
    html += `</div>`;
    resultsPanel.innerHTML = html;
    resultsPanel.querySelectorAll('.ft-pdf-result-card').forEach(card => {
      card.addEventListener('click', () => {
        const idx = parseInt(card.dataset.matchIdx);
        _ftOpenPdfPageInline(_ftPdfMatches[idx], idx, query);
      });
    });
    resultsPanel.style.display = '';
    if (viewerWrap) viewerWrap.style.display = 'none';
  }

  async function _ftOpenPdfPageInline(matchObj, matchIdx, query) {
    _ftPdfMatchIdx = matchIdx;
    _ftPdfCurrentQuery = query;
    const viewerWrap = overlay.querySelector('#ftPdfViewerWrap');
    const resultsPanel = overlay.querySelector('#ftPdfResultsPanel');
    const toolbar = overlay.querySelector('#ftPdfToolbar');
    const canvasOuter = overlay.querySelector('#ftPdfCanvasOuter');
    const canvas = overlay.querySelector('#ftPdfCanvas');
    const textLayer = overlay.querySelector('#ftPdfTextLayer');
    if (!canvas || !textLayer || !toolbar) return;
    const total = _ftPdfMatches.length;
    toolbar.innerHTML = `
      <button class="ft-pdf-tb-btn" id="ftPdfBackToResults" data-testid="button-ft-pdf-back">&#8592; ${t('back') || 'Risultati'}</button>
      <span class="ft-pdf-tb-filename" title="${esc(matchObj.fileName)}">📄 ${esc(matchObj.fileName)}</span>
      <div class="ft-pdf-tb-page-nav">
        <button class="ft-pdf-tb-btn" id="ftPdfPagePrev" title="Pagina precedente" data-testid="button-ft-pdf-page-prev">&#9664;</button>
        <span class="ft-pdf-tb-page">Pag.&nbsp;<input type="number" id="ftPdfPageInput" class="ft-pdf-page-input" value="${matchObj.pageNum}" min="1" data-testid="input-ft-pdf-page">&nbsp;/&nbsp;<span id="ftPdfPageTotal">…</span></span>
        <button class="ft-pdf-tb-btn" id="ftPdfPageNext" title="Pagina successiva" data-testid="button-ft-pdf-page-next">&#9654;</button>
      </div>
      <div class="ft-pdf-tb-nav">
        <button class="ft-pdf-tb-btn" id="ftPdfMatchPrev" title="Corrispondenza precedente" data-testid="button-ft-pdf-match-prev">&#8679;</button>
        <span class="ft-pdf-tb-count">${matchIdx + 1} / ${total}</span>
        <button class="ft-pdf-tb-btn" id="ftPdfMatchNext" title="Corrispondenza successiva" data-testid="button-ft-pdf-match-next">&#8681;</button>
      </div>
      <button class="ft-pdf-tb-btn ft-pdf-tb-ext" id="ftPdfOpenExt" title="Apri in nuova finestra" data-testid="button-ft-pdf-open-ext">&#8599;</button>`;
    toolbar.querySelector('#ftPdfBackToResults').onclick = () => {
      if (viewerWrap) viewerWrap.style.display = 'none';
      if (resultsPanel) resultsPanel.style.display = '';
      if (_ftPdfCurrentDoc) { try { _ftPdfCurrentDoc.destroy(); } catch(e2) {} _ftPdfCurrentDoc = null; }
    };
    toolbar.querySelector('#ftPdfPagePrev').onclick = () => _ftNavPdfPage(-1);
    toolbar.querySelector('#ftPdfPageNext').onclick = () => _ftNavPdfPage(1);
    toolbar.querySelector('#ftPdfPageInput').onchange = (ev) => {
      const pg = parseInt(ev.target.value);
      if (isNaN(pg) || pg < 1) { ev.target.value = _ftPdfCurrentPage; return; }
      const clamped = Math.min(Math.max(1, pg), _ftPdfCurrentNumPages || 1);
      ev.target.value = clamped;
      _ftGoToPdfPage(clamped);
    };
    toolbar.querySelector('#ftPdfPageInput').onkeydown = (ev) => {
      if (ev.key === 'Enter') { ev.target.dispatchEvent(new Event('change')); ev.preventDefault(); }
    };
    toolbar.querySelector('#ftPdfMatchPrev').onclick = () => _ftNavPdfMatch(-1);
    toolbar.querySelector('#ftPdfMatchNext').onclick = () => _ftNavPdfMatch(1);
    toolbar.querySelector('#ftPdfOpenExt').onclick = async () => {
      // Apre sempre in nuova finestra, bypassa l'intercettazione inline
      const blobExt = await _ftReadFileBlob(matchObj.fileRec);
      if (!blobExt) return;
      const urlExt = URL.createObjectURL(new Blob([blobExt], { type: 'application/pdf' }));
      window.open(urlExt, '_blank');
      setTimeout(() => URL.revokeObjectURL(urlExt), 30000);
    };
    if (viewerWrap) { viewerWrap.style.display = 'flex'; }
    if (resultsPanel) resultsPanel.style.display = 'none';
    textLayer.innerHTML = `<div style="padding:16px;color:#666">Caricamento pag. ${matchObj.pageNum}…</div>`;
    canvas.width = 0; canvas.height = 0;
    try {
      if (typeof pdfjsLib === 'undefined') return;
      if (pdfjsLib.GlobalWorkerOptions) pdfjsLib.GlobalWorkerOptions.workerSrc = 'js/pdf.worker.min.js';
      const blobData = await _ftReadFileBlob(matchObj.fileRec);
      if (!blobData) return;
      const rawBytes = blobData instanceof Uint8Array ? blobData : new Uint8Array(blobData);
      if (_ftPdfCurrentDoc) { try { _ftPdfCurrentDoc.destroy(); } catch(e2) {} }
      const pdfDoc = await pdfjsLib.getDocument({ data: rawBytes.slice(0) }).promise;
      _ftPdfCurrentDoc = pdfDoc;
      _ftPdfCurrentPage = matchObj.pageNum;
      _ftPdfCurrentNumPages = pdfDoc.numPages;
      _ftPdfCurrentFileRec = matchObj.fileRec;
      const ptEl = toolbar.querySelector('#ftPdfPageTotal');
      if (ptEl) ptEl.textContent = pdfDoc.numPages;
      const piEl = toolbar.querySelector('#ftPdfPageInput');
      if (piEl) { piEl.value = matchObj.pageNum; piEl.max = pdfDoc.numPages; }
      await _ftRenderPdfPage(pdfDoc, matchObj.pageNum, query, canvas, textLayer, canvasOuter, matchObj.matchStart, matchObj.matchEnd);
      // Aggiorna counter nell'header: N / TOT
      const countElNav = overlay.querySelector('#ftSearchCount');
      if (countElNav) countElNav.textContent = `${matchIdx + 1} / ${_ftPdfMatches.length}`;
    } catch(e) {
      textLayer.innerHTML = `<div style="padding:16px;color:red">Errore: ${esc(String(e))}</div>`;
    }
  }

  async function _ftRenderPdfPage(pdfDoc, pageNum, query, canvas, textLayer, canvasOuter, targetMatchStart, targetMatchEnd) {
    const page = await pdfDoc.getPage(pageNum);
    const containerWidth = (canvasOuter ? canvasOuter.clientWidth : 760) || 760;
    const unscaledVp = page.getViewport({ scale: 1 });
    const scale = Math.min(2.5, Math.max(0.8, (containerWidth - 32) / unscaledVp.width));
    const vp = page.getViewport({ scale });
    canvas.width = Math.round(vp.width);
    canvas.height = Math.round(vp.height);
    const ctx = canvas.getContext('2d');
    await page.render({ canvasContext: ctx, viewport: vp }).promise;
    textLayer.innerHTML = '';
    textLayer.style.width = canvas.width + 'px';
    textLayer.style.height = canvas.height + 'px';
    const tc = await page.getTextContent();

    // Ricalcola textStart/textEnd per ogni item (stessa logica di _ftBuildIndex)
    let pos = 0;
    const itemsWithRange = tc.items.map(item => {
      const str = item.str || '';
      const textStart = pos;
      const textEnd = pos + str.length;
      pos += str.length + 1;
      return { ...item, textStart, textEnd };
    });
    const pageText = itemsWithRange.map(it => it.str).join(' ');

    // Trova tutti i range di match nella pagina per highlight multi-item
    const allMatchRanges = [];
    if (query && query.trim().length >= 2) {
      const reAll = new RegExp(query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
      let mAll;
      while ((mAll = reAll.exec(pageText)) !== null) {
        allMatchRanges.push({ start: mAll.index, end: mAll.index + mAll[0].length });
      }
    }

    const hasTarget = typeof targetMatchStart === 'number' && targetMatchStart >= 0;
    let currentSpan = null;
    itemsWithRange.forEach(item => {
      if (!item.str) return;
      const [sx, ky, kx, sy, tx, ty] = item.transform;
      const fontSize = Math.sqrt(sx * sx + ky * ky) * scale;
      const cssX = tx * scale;
      const cssY = vp.height - ty * scale;
      const span = document.createElement('span');
      span.className = 'ft-pdf-tl-span';
      span.style.cssText = `left:${cssX}px;top:${cssY - fontSize}px;font-size:${Math.round(fontSize)}px;` +
        `${item.width > 0 ? 'width:' + Math.round(item.width * scale) + 'px;' : ''}`;

      // Controlla sovrapposizione con qualsiasi match (per ft-hl)
      const overlapsAny = allMatchRanges.some(r => item.textEnd > r.start && item.textStart < r.end);
      // Controlla sovrapposizione con il match corrente (per ft-hl-current)
      const isCurrent = hasTarget
        ? (item.textEnd > targetMatchStart && item.textStart < targetMatchEnd)
        : (!currentSpan && overlapsAny);

      if (overlapsAny) {
        span.classList.add('ft-hl');
        if (isCurrent) {
          span.classList.add('ft-hl-current');
          if (!currentSpan) currentSpan = span;
        }
      }
      span.textContent = item.str;
      textLayer.appendChild(span);
    });
    if (currentSpan) requestAnimationFrame(() => currentSpan.scrollIntoView({ block: 'center', behavior: 'smooth' }));
  }

  function _ftNavPdfMatch(dir) {
    if (!_ftPdfMatches.length) return;
    const newIdx = (_ftPdfMatchIdx + dir + _ftPdfMatches.length) % _ftPdfMatches.length;
    _ftOpenPdfPageInline(_ftPdfMatches[newIdx], newIdx, _ftPdfCurrentQuery);
  }

  function _ftNavPdfPage(delta) {
    if (!_ftPdfCurrentDoc || !_ftPdfCurrentNumPages) return;
    const newPage = Math.min(Math.max(1, _ftPdfCurrentPage + delta), _ftPdfCurrentNumPages);
    if (newPage === _ftPdfCurrentPage) return;
    _ftGoToPdfPage(newPage);
  }

  async function _ftGoToPdfPage(pageNum) {
    if (!_ftPdfCurrentDoc) return;
    const toolbar = overlay.querySelector('#ftPdfToolbar');
    const canvasOuter = overlay.querySelector('#ftPdfCanvasOuter');
    const canvas = overlay.querySelector('#ftPdfCanvas');
    const textLayer = overlay.querySelector('#ftPdfTextLayer');
    if (!canvas || !textLayer) return;
    _ftPdfCurrentPage = pageNum;
    const piEl = toolbar ? toolbar.querySelector('#ftPdfPageInput') : null;
    if (piEl) piEl.value = pageNum;
    textLayer.innerHTML = `<div style="padding:16px;color:#666">Caricamento pag. ${pageNum}…</div>`;
    canvas.width = 0; canvas.height = 0;
    try {
      await _ftRenderPdfPage(_ftPdfCurrentDoc, pageNum, _ftPdfCurrentQuery, canvas, textLayer, canvasOuter, undefined, undefined);
    } catch(e) {
      textLayer.innerHTML = `<div style="padding:16px;color:red">Errore: ${esc(String(e))}</div>`;
    }
  }

  function _ftResetPdfSearch() {
    _ftPdfMatches = []; _ftPdfMatchIdx = -1; _ftPdfCurrentQuery = '';
    _ftPdfCurrentPage = 1; _ftPdfCurrentNumPages = 0; _ftPdfCurrentFileRec = null;
    const rp = overlay.querySelector('#ftPdfResultsPanel');
    const vw = overlay.querySelector('#ftPdfViewerWrap');
    const countEl = overlay.querySelector('#ftSearchCount');
    if (rp) { rp.style.display = ''; rp.innerHTML = `<p class="ft-pdf-hint">${t('searchPdfHint') || 'Digita almeno 2 caratteri per cercare nei PDF.'}</p>`; }
    if (vw) { vw.style.display = 'none'; }
    if (countEl) countEl.textContent = '';
    if (_ftPdfCurrentDoc) { try { _ftPdfCurrentDoc.destroy(); } catch(e2) {} _ftPdfCurrentDoc = null; }
  }

  const ftPdfBtn = overlay.querySelector('#ftPdfSearchBtn');
  ftPdfBtn.onclick = async () => {
    _ftPdfMode = !_ftPdfMode;
    const pdfPane = overlay.querySelector('#ftPdfPane');
    const ftBody = overlay.querySelector('#ftFullBody');
    if (_ftPdfMode) {
      ftPdfBtn.classList.add('active');
      if (pdfPane) pdfPane.style.display = 'flex';
      if (ftBody) ftBody.classList.add('ft-split-active');
      if (_ftPdfIndex === null && !_ftPdfIndexing) _ftBuildIndex();
      const q = ftInput.value.trim();
      if (q.length >= 2 && _ftPdfIndex !== null) _ftSearchInPdfs(q);
      else {
        const rp = overlay.querySelector('#ftPdfResultsPanel');
        if (rp && !_ftPdfIndexing) rp.innerHTML = `<p class="ft-pdf-hint">${t('searchPdfHint') || 'Digita almeno 2 caratteri per cercare nei PDF.'}</p>`;
      }
    } else {
      ftPdfBtn.classList.remove('active');
      if (pdfPane) pdfPane.style.display = 'none';
      if (ftBody) ftBody.classList.remove('ft-split-active');
      if (_ftPdfCurrentDoc) { try { _ftPdfCurrentDoc.destroy(); } catch(e2) {} _ftPdfCurrentDoc = null; }
    }
  };

  ftInput.addEventListener('input', () => {
    if (_ftPdfMode) {
      clearTimeout(_ftPdfSearchTimer2);
      _ftPdfSearchTimer2 = setTimeout(() => {
        const q = ftInput.value.trim();
        if (q.length >= 2) _ftSearchInPdfs(q);
        else _ftResetPdfSearch();
      }, 400);
    }
  });

  document.body.appendChild(overlay);
  _ftFullModalOverlay = overlay;
  const body = overlay.querySelector('#ftFullBody');
  const htmlPane = overlay.querySelector('#ftHtmlPane');
  let blobData = htmlFile ? htmlFile.blob : null;
  if (!blobData && htmlFile && htmlFile.storagePath) {
    try {
      let dir = (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) ? FS_DIR_HANDLE : null;
      if (!dir && typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) dir = FS_FILES_HANDLE;
      if (dir) {
        const parts = htmlFile.storagePath.split('/').filter(Boolean);
        for (const part of parts) dir = await dir.getDirectoryHandle(part);
        const fName = htmlFile.diskFileName || htmlFile.fileName;
        const fh = await dir.getFileHandle(fName);
        const file = await fh.getFile();
        blobData = new Uint8Array(await file.arrayBuffer());
      }
    } catch(e) { console.warn('FT FS read fallback error:', e); }
  }
  if (!blobData) {
    htmlPane.innerHTML = `<p class="hint" style="padding:24px">${t('previewNotAvailable')}</p>`;
    return;
  }
  try {
    const rawBytes = blobData instanceof Uint8Array ? blobData : new Uint8Array(blobData);
    let htmlText;
    try { htmlText = new TextDecoder('windows-1252').decode(rawBytes); } catch(e) {
      try { htmlText = new TextDecoder('iso-8859-1').decode(rawBytes); } catch(e2) {
        htmlText = new TextDecoder('utf-8').decode(rawBytes);
      }
    }
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlText, 'text/html');
    const pageTitle = (doc.title || (htmlFile ? htmlFile.fileName : '') || '').trim();
    overlay.querySelector('.ft-full-title').textContent = pageTitle || (dossier ? dossier.title : '');
    const bodyClone = doc.body ? doc.body.cloneNode(true) : document.createElement('body');
    bodyClone.querySelectorAll('script').forEach(el => el.remove());
    bodyClone.querySelectorAll('table').forEach(tbl => tbl.classList.add('ft-table'));
    bodyClone.querySelectorAll('a[href]').forEach(a => {
      const href = (a.getAttribute('href') || '').replace(/&amp;/g, '&').trim();
      if (href && !href.startsWith('http') && !href.startsWith('#') && !href.startsWith('mailto:')) {
        const btn = document.createElement('button');
        btn.className = 'ft-doc-link';
        btn.dataset.ftHref = href;
        btn.title = href;
        btn.textContent = (a.textContent || '').trim() || href.split('/').pop();
        a.replaceWith(btn);
      }
    });
    const rendered = bodyClone.innerHTML.trim();
    htmlPane.innerHTML = rendered || `<p class="hint" style="padding:24px">${t('previewNotAvailable')}</p>`;
    htmlPane.querySelectorAll('.ft-doc-link').forEach(btn => {
      btn.addEventListener('click', () => _ftOpenExtractedDoc(btn.dataset.ftHref));
    });
  } catch(e) {
    console.error('FT modal error:', e);
    htmlPane.innerHTML = `<p class="hint" style="padding:24px">${t('previewNotAvailable')}</p>`;
  }
}

async function _ftOpenExtractedDoc(href) {
  const files = _ftExtractFiles || [];
  const hrefName = (href.split('/').pop() || href).trim();
  const hrefNameLow = hrefName.toLowerCase();
  let match = files.find(f => f.fileName === hrefName);
  if (!match) match = files.find(f => (f.fileName || '').toLowerCase() === hrefNameLow);
  if (!match) { alert(t('zipFtDocNotFound')); return; }

  // Se il modale FT è aperto e il file è un PDF, aprilo inline nel pannello PDF
  const isPdf = /\.pdf$/i.test(match.fileName || '');
  if (isPdf && _ftFullModalOverlay) {
    const pdfPane = _ftFullModalOverlay.querySelector('#ftPdfPane');
    const ftBody = _ftFullModalOverlay.querySelector('#ftFullBody');
    const toolbar = _ftFullModalOverlay.querySelector('#ftPdfToolbar');
    const viewerWrap = _ftFullModalOverlay.querySelector('#ftPdfViewerWrap');
    const resultsPanel = _ftFullModalOverlay.querySelector('#ftPdfResultsPanel');
    const canvas = _ftFullModalOverlay.querySelector('#ftPdfCanvas');
    const textLayer = _ftFullModalOverlay.querySelector('#ftPdfTextLayer');
    const canvasOuter = _ftFullModalOverlay.querySelector('#ftPdfCanvasOuter');
    if (pdfPane && canvas && textLayer && toolbar) {
      pdfPane.style.display = 'flex';
      if (ftBody) ftBody.classList.add('ft-split-active');
      if (viewerWrap) viewerWrap.style.display = 'flex';
      if (resultsPanel) resultsPanel.style.display = 'none';
      toolbar.innerHTML = `
        <span class="ft-pdf-tb-filename" title="${esc(match.fileName)}">📄 ${esc(match.fileName)}</span>
        <span class="ft-pdf-tb-page">Caricamento…</span>
        <button class="ft-pdf-tb-btn ft-pdf-tb-ext" id="ftPdfOpenExtDirect" title="Apri in nuova finestra">&#8599;</button>`;
      textLayer.innerHTML = `<div style="padding:16px;color:#666">Caricamento…</div>`;
      canvas.width = 0; canvas.height = 0;
      let blobDataInline = match.blob;
      if (!blobDataInline && match.storagePath) {
        try {
          let dir = (typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) ? FS_FILES_HANDLE
                  : (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) ? FS_DIR_HANDLE : null;
          if (dir) {
            const parts = match.storagePath.split('/').filter(Boolean);
            for (const part of parts) dir = await dir.getDirectoryHandle(part);
            const fh = await dir.getFileHandle(match.diskFileName || match.fileName);
            const file = await fh.getFile();
            blobDataInline = new Uint8Array(await file.arrayBuffer());
          }
        } catch(e) { console.warn('FT inline PDF read error:', e); }
      }
      if (!blobDataInline) { textLayer.innerHTML = `<div style="padding:16px;color:red">${t('zipFtDocNotFound')}</div>`; return; }
      // onclick registrato dopo la risoluzione dei byte, così usa sempre blobDataInline
      toolbar.querySelector('#ftPdfOpenExtDirect').onclick = () => {
        const blob2 = new Blob([blobDataInline], { type: 'application/pdf' });
        const u2 = URL.createObjectURL(blob2);
        window.open(u2, '_blank');
        setTimeout(() => URL.revokeObjectURL(u2), 30000);
      };
      try {
        if (typeof pdfjsLib === 'undefined') return;
        if (pdfjsLib.GlobalWorkerOptions) pdfjsLib.GlobalWorkerOptions.workerSrc = 'js/pdf.worker.min.js';
        const rawBytes = blobDataInline instanceof Uint8Array ? blobDataInline : new Uint8Array(blobDataInline);
        const pdfDoc = await pdfjsLib.getDocument({ data: rawBytes.slice(0) }).promise;
        const numPages = pdfDoc.numPages;
        const pageNumEl = toolbar.querySelector('.ft-pdf-tb-page');
        if (pageNumEl) pageNumEl.textContent = `Pag. 1 / ${numPages}`;
        // Add page nav buttons
        const navDiv = document.createElement('div');
        navDiv.className = 'ft-pdf-tb-nav';
        let currentPage = 1;
        const prevBtn = document.createElement('button');
        prevBtn.className = 'ft-pdf-tb-btn'; prevBtn.textContent = '◄'; prevBtn.title = 'Pagina precedente';
        const nextBtn = document.createElement('button');
        nextBtn.className = 'ft-pdf-tb-btn'; nextBtn.textContent = '►'; nextBtn.title = 'Pagina successiva';
        const countSpan = document.createElement('span');
        countSpan.className = 'ft-pdf-tb-count'; countSpan.textContent = `1 / ${numPages}`;
        navDiv.append(prevBtn, countSpan, nextBtn);
        toolbar.insertBefore(navDiv, toolbar.querySelector('.ft-pdf-tb-ext'));
        async function gotoPage(pn) {
          pn = Math.max(1, Math.min(numPages, pn));
          currentPage = pn;
          countSpan.textContent = `${pn} / ${numPages}`;
          if (pageNumEl) pageNumEl.textContent = `Pag. ${pn} / ${numPages}`;
          const page = await pdfDoc.getPage(pn);
          const w = (canvasOuter ? canvasOuter.clientWidth : 760) || 760;
          const uvp = page.getViewport({ scale: 1 });
          const scale = Math.min(2.5, Math.max(0.8, (w - 32) / uvp.width));
          const vp = page.getViewport({ scale });
          canvas.width = Math.round(vp.width); canvas.height = Math.round(vp.height);
          await page.render({ canvasContext: canvas.getContext('2d'), viewport: vp }).promise;
          textLayer.innerHTML = '';
          textLayer.style.width = canvas.width + 'px'; textLayer.style.height = canvas.height + 'px';
          const tc = await page.getTextContent();
          tc.items.forEach(item => {
            if (!item.str || !item.str.trim()) return;
            const [sx, ky, kx, sy, tx, ty] = item.transform;
            const fs = Math.sqrt(sx * sx + ky * ky) * scale;
            const span = document.createElement('span');
            span.className = 'ft-pdf-tl-span';
            span.style.cssText = `left:${tx*scale}px;top:${vp.height-ty*scale-fs}px;font-size:${Math.round(fs)}px;${item.width>0?'width:'+Math.round(item.width*scale)+'px;':''}`;
            span.textContent = item.str;
            textLayer.appendChild(span);
          });
        }
        prevBtn.onclick = () => gotoPage(currentPage - 1);
        nextBtn.onclick = () => gotoPage(currentPage + 1);
        await gotoPage(1);
      } catch(e) {
        textLayer.innerHTML = `<div style="padding:16px;color:red">Errore: ${esc(String(e))}</div>`;
      }
      return;
    }
  }

  // Fallback: apri in nuova finestra (non-PDF o modale non aperto)
  const win = window.open('', '_blank');
  let blobData = match.blob;
  if (!blobData && match.storagePath) {
    try {
      let dir = null;
      if (typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) dir = FS_FILES_HANDLE;
      else if (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) dir = FS_DIR_HANDLE;
      if (dir) {
        const parts = match.storagePath.split('/').filter(Boolean);
        for (const part of parts) dir = await dir.getDirectoryHandle(part);
        const fh = await dir.getFileHandle(match.diskFileName || match.fileName);
        const file = await fh.getFile();
        blobData = new Uint8Array(await file.arrayBuffer());
      }
    } catch(e) { console.warn('FT FS read error:', e); }
  }
  if (!blobData) { if (win) win.close(); alert(t('zipFtDocNotFound')); return; }
  const mimeType = match.fileType || 'application/octet-stream';
  const blob = new Blob([blobData], { type: mimeType });
  const url = URL.createObjectURL(blob);
  if (win) { win.location.href = url; } else { window.open(url, '_blank'); }
  setTimeout(() => URL.revokeObjectURL(url), 30000);
}

function _initFascResizeHandle(handle, fileList, fileViewer) {
  let isDragging = false;
  function onMouseDown(e) {
    e.preventDefault();
    isDragging = true;
    handle.classList.add('active');
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }
  function onMouseMove(e) {
    if (!isDragging) return;
    const rect = fileViewer.getBoundingClientRect();
    const totalWidth = rect.width;
    if (totalWidth <= 0) return;
    const offsetX = e.clientX - rect.left;
    let pct = (offsetX / totalWidth) * 100;
    if (pct < 15) pct = 15;
    if (pct > 80) pct = 80;
    fileList.style.width = pct + '%';
  }
  function stopDrag() {
    if (!isDragging) return;
    isDragging = false;
    handle.classList.remove('active');
    document.body.style.cursor = '';
    document.body.style.userSelect = '';
  }
  function cleanup() {
    stopDrag();
    handle.removeEventListener('mousedown', onMouseDown);
    document.removeEventListener('mousemove', onMouseMove);
    document.removeEventListener('mouseup', stopDrag);
    window.removeEventListener('blur', stopDrag);
  }
  handle.addEventListener('mousedown', onMouseDown);
  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup', stopDrag);
  window.addEventListener('blur', stopDrag);
  return cleanup;
}

/* ===== DOSSIER DETAIL MODAL (two-column) ===== */
let _dossDetail = null;
let _alldigCards = [];
let _dossDetailZip = null;
let _dossDetailZipChoiceState = null;

function _closeDossDetail() {
  if (!_dossDetail) return;
  if (_dossDetail.resizeCleanup) { _dossDetail.resizeCleanup(); _dossDetail.resizeCleanup = null; }
  if (_dossDetail.overlay) _dossDetail.overlay.remove();
  _dossDetail = null;
  _dossDetailZip = null;
  _dossDetailZipChoiceState = null;
}

async function _openDossierDetailModal(dossierId, opts) {
  _closeDossDetail();
  const readOnly = !!(opts && opts.readOnly);
  const [dossier, allFiles] = await Promise.all([
    DB.getDossier(dossierId),
    DB.getEntityFiles('dossier', dossierId)
  ]);
  if (!dossier) return;
  const origLang = dossier.origLang || 'it';
  const hasCert = !!dossier.hasCertTranslation;
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay doss-detail-overlay';
  _dossDetail = { overlay, dossierId, dossier, allFiles, origLang, hasCert, viewMode: 'orig', editMode: false, readOnly, resizeCleanup: null, selectedFTFileId: null, factId: (opts && opts.factId) ? opts.factId : null };
  overlay.innerHTML = `
    <div class="doss-detail-modal">
      <div class="doss-detail-header">
        <div class="doss-detail-header-left">
          <span class="doss-detail-icon">📁</span>
          <h3 class="doss-detail-title">${esc(dossier.title)}</h3>
          <span class="file-lang-badge file-lang-${origLang}" style="font-size:11px;margin-left:4px">${origLang.toUpperCase()}</span>
        </div>
        <div class="doss-detail-header-right">
          ${hasCert ? `<button class="btn btn-sm doss-detail-view-toggle" id="dossDetailToggleBtn" data-testid="button-doss-toggle-view">${t('fascViewCert')}</button>` : ''}
          ${!readOnly ? `<button class="btn btn-sm doss-detail-edit-btn" id="dossDetailEditBtn" data-testid="button-doss-edit-mode">${t('fascEditMode')}</button>` : ''}
          ${!readOnly ? `<button class="btn btn-sm btn-danger" id="dossDetailDeleteBtn" data-testid="button-delete-dossier-from-modal" style="display:none">🗑 ${currentLang==='en'?'Delete all files':'Elimina tutti i file'}</button>` : ''}
          <button class="fact-analysis-close" id="dossDetailCloseBtn" data-testid="button-close-doss-detail">&times;</button>
        </div>
      </div>
      <div class="doss-detail-body">
        <div class="doss-detail-files" id="dossDetailFiles"></div>
        <div class="doss-detail-resize" id="dossDetailResize"></div>
        <div class="doss-detail-preview" id="dossDetailPreview">
          <p class="hint" style="padding:32px;text-align:center">${t('selectFileToPreview')}</p>
        </div>
      </div>
    </div>`;
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  document.body.appendChild(overlay);
  overlay.querySelector('#dossDetailCloseBtn').onclick = () => _closeDossDetail();
  const toggleBtn = overlay.querySelector('#dossDetailToggleBtn');
  if (toggleBtn) toggleBtn.onclick = () => _dossDetailToggleView();
  const editBtn = overlay.querySelector('#dossDetailEditBtn');
  if (editBtn) editBtn.onclick = () => _dossDetailToggleEdit();
  const deleteModalBtn = overlay.querySelector('#dossDetailDeleteBtn');
  if (deleteModalBtn) deleteModalBtn.onclick = () => _dossDetailDeleteAllFiles(dossierId);
  _renderDossDetailFiles();
  const filesCol = overlay.querySelector('#dossDetailFiles');
  const body = overlay.querySelector('.doss-detail-body');
  const resizeHandle = overlay.querySelector('#dossDetailResize');
  if (filesCol && body && resizeHandle) {
    _dossDetail.resizeCleanup = _initFascResizeHandle(resizeHandle, filesCol, body);
  }
  if (opts && typeof opts.afterOpen === 'function') {
    setTimeout(() => opts.afterOpen(), 0);
  }
}

function _dossDetailToggleView() {
  if (!_dossDetail) return;
  _dossDetail.viewMode = _dossDetail.viewMode === 'orig' ? 'cert' : 'orig';
  _dossDetail.editMode = false;
  const toggleBtn = _dossDetail.overlay.querySelector('#dossDetailToggleBtn');
  if (toggleBtn) {
    toggleBtn.textContent = _dossDetail.viewMode === 'orig' ? t('fascViewCert') : t('fascViewOrig');
    toggleBtn.classList.toggle('cert-active', _dossDetail.viewMode === 'cert');
  }
  const editBtn = _dossDetail.overlay.querySelector('#dossDetailEditBtn');
  if (editBtn) { editBtn.textContent = t('fascEditMode'); editBtn.classList.remove('edit-active'); }
  const deleteBtn2 = _dossDetail.overlay.querySelector('#dossDetailDeleteBtn');
  if (deleteBtn2) deleteBtn2.style.display = 'none';
  const preview = document.getElementById('dossDetailPreview');
  if (preview) preview.innerHTML = `<p class="hint" style="padding:32px;text-align:center">${t('selectFileToPreview')}</p>`;
  _renderDossDetailFiles();
}

function _dossDetailToggleEdit() {
  if (!_dossDetail) return;
  _dossDetail.editMode = !_dossDetail.editMode;
  const editBtn = _dossDetail.overlay.querySelector('#dossDetailEditBtn');
  if (editBtn) {
    editBtn.textContent = _dossDetail.editMode ? t('fascEditModeDone') : t('fascEditMode');
    editBtn.classList.toggle('edit-active', _dossDetail.editMode);
  }
  const deleteBtn = _dossDetail.overlay.querySelector('#dossDetailDeleteBtn');
  if (deleteBtn) deleteBtn.style.display = _dossDetail.editMode ? '' : 'none';
  _renderDossDetailFiles();
}

function _renderDossDetailFiles() {
  if (!_dossDetail) return;
  const { allFiles, viewMode, origLang, editMode, readOnly, dossierId } = _dossDetail;
  const certLang = origLang === 'it' ? 'en' : 'it';
  const activeLang = viewMode === 'orig' ? origLang : certLang;
  const mainFiles = allFiles.filter(f => {
    if ((f.lang || 'it') !== activeLang) return false;
    if (viewMode === 'orig') return f.fileRole === 'doss_orig' || !f.fileRole;
    return f.fileRole === 'doss_cert';
  });
  const allExtractFiles = allFiles.filter(f => (f.lang || 'it') === activeLang && f.fileRole === 'doss_extract');
  const alldigFiles = allFiles.filter(f => f.fileRole === 'doss_alldig');
  const sectionLabel = viewMode === 'orig' ? t('fascOrigSection') : t('fascCertSection');
  const langLabel = activeLang.toUpperCase();
  const selectedZipId = _dossDetail.selectedZipId || null;
  const legacyExtracts = allExtractFiles.filter(f => f.sourceFileId == null);
  const filteredExtracts = selectedZipId != null
    ? (() => {
        const linked = allExtractFiles.filter(f => f.sourceFileId === selectedZipId);
        return linked.length > 0 ? linked : (legacyExtracts.length > 0 ? legacyExtracts : []);
      })()
    : legacyExtracts;
  function renderItem(f, canDel) {
    const delBtn = (!readOnly && editMode && canDel)
      ? `<button class="btn btn-xs btn-danger doss-del-btn" onclick="event.stopPropagation();_dossDetailDeleteFile(${f.id})" data-testid="button-doss-del-${f.id}">🗑</button>`
      : '';
    const isFTHtml = f.fileRole === 'doss_extract' && /\.(html|htm)$/i.test(f.fileName || '');
    const ftHint = isFTHtml
      ? `<span style="display:block;font-size:10px;color:#2563eb;margin-top:2px;font-weight:500">▶ ${t('selectToOpenFT') || 'Seleziona per aprire il Fascicolo Telematico'}</span>`
      : '';
    const isSelectedZip = f.fileRole !== 'doss_extract' && f.id === selectedZipId;
    const zipBorder = isSelectedZip ? 'border-left:3px solid #3b82f6;' : '';
    return `<div class="doss-detail-file-item" data-file-id="${f.id}" style="${zipBorder}" onclick="_dossDetailSelectFile(${f.id},this)" data-testid="file-item-doss-${f.id}">
      <span class="doss-detail-file-icon">${_dossFileIcon(f.fileType, f.fileName)}</span>
      <span class="doss-detail-file-name" title="${esc(f.fileName)}">${esc(f.fileName)}${ftHint}</span>
      <span class="doss-detail-file-size">${formatSize(f.fileSize)}</span>
      <button class="btn btn-xs btn-action-download" onclick="event.stopPropagation();downloadFile(${f.id})" data-testid="button-doss-download-${f.id}">⬇</button>
      ${delBtn}
    </div>`;
  }
  let html = `<div class="doss-detail-file-section">
    <div class="doss-detail-section-header"><span>${sectionLabel}</span><span>${langLabel}</span></div>
    ${mainFiles.length ? mainFiles.map(f => renderItem(f, true)).join('') : `<p class="hint" style="padding:10px 12px;font-size:12px">${t('fascNoFiles')}</p>`}
  </div>`;
  if (allExtractFiles.length > 0) {
    const selectedZipName = selectedZipId != null ? (allFiles.find(f => f.id === selectedZipId) || {}).fileName : null;
    const extractHeader = selectedZipName
      ? `${t('fascExtractSection')} — <span style="font-weight:400;font-size:11px;opacity:.8">${esc(selectedZipName)}</span>`
      : `${t('fascExtractSection')}`;
    html += `<div class="doss-detail-file-section">
      <div class="doss-detail-section-header">${extractHeader}<span>${langLabel}</span></div>
      ${filteredExtracts.map(f => renderItem(f, false)).join('')}
    </div>`;
  }
  if (alldigFiles.length) {
    const alldigGroups = {};
    for (const f of alldigFiles) {
      const m = (f.storagePath || '').match(/_DDP(\d+)/);
      const key = m ? m[1] : '???';
      if (!alldigGroups[key]) alldigGroups[key] = { key, label: 'DDP' + key, desc: f.notes || '', files: [] };
      alldigGroups[key].files.push(f);
    }
    html += `<div class="doss-detail-file-section">
      <div class="doss-detail-section-header"><span>📀 ${t('dossAlldigSection')}</span></div>`;
    for (const gk of Object.keys(alldigGroups).sort()) {
      const grp = alldigGroups[gk];
      const groupId = 'dossAlldigGrp_' + gk;
      const delBtn = (!readOnly && editMode)
        ? `<button class="btn btn-xs btn-danger" onclick="event.stopPropagation();_dossDetailDeleteAlldig('${gk}')" data-testid="button-doss-alldig-del-${gk}">🗑</button>`
        : '';
      html += `<div class="doss-alldig-accordion-group">
        <div class="doss-alldig-accordion-header" onclick="_dossDetailToggleAlldig('${groupId}')" data-testid="alldig-accordion-${gk}">
          <span class="doss-alldig-accordion-arrow" id="${groupId}_arrow">▶</span>
          <span class="doss-alldig-accordion-label">${grp.label}</span>
          ${grp.desc ? `<span class="doss-alldig-accordion-desc">${esc(grp.desc)}</span>` : ''}
          <span class="doss-alldig-accordion-count">${grp.files.length}</span>
          ${delBtn}
        </div>
        <div class="doss-alldig-accordion-body" id="${groupId}" style="display:none">
          ${grp.files.map(f => renderItem(f, false)).join('')}
        </div>
      </div>`;
    }
    html += `</div>`;
  }
  const container = document.getElementById('dossDetailFiles');
  if (container) container.innerHTML = html;
}

function _dossDetailToggleAlldig(groupId) {
  const body = document.getElementById(groupId);
  const arrow = document.getElementById(groupId + '_arrow');
  if (!body) return;
  const isOpen = body.style.display !== 'none';
  body.style.display = isOpen ? 'none' : 'block';
  if (arrow) arrow.textContent = isOpen ? '▶' : '▼';
}

async function _dossDetailActFromPdf(fileId) {
  if (!_dossDetail) return;
  const f = await DB.getFile(fileId);
  if (!f) return;
  let blobData = f.blob;
  if (!blobData && f.storagePath) {
    try {
      let dir = (typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) ? FS_FILES_HANDLE
              : (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) ? FS_DIR_HANDLE : null;
      if (dir) {
        const parts = f.storagePath.split('/').filter(Boolean);
        for (const part of parts) dir = await dir.getDirectoryHandle(part);
        const fh = await dir.getFileHandle(f.diskFileName || f.fileName);
        const file = await fh.getFile();
        blobData = new Uint8Array(await file.arrayBuffer());
      }
    } catch(e) { console.warn('Act-from-PDF read error:', e); }
  }
  if (!blobData) { alert(t('previewNotAvailable')); return; }
  const rawBytes = blobData instanceof Uint8Array ? blobData : new Uint8Array(blobData);
  _dossDetail.actPdfFileId = fileId;
  _dossDetail.actPdfFileName = f.fileName;
  _dossDetail.actPdfBytes = rawBytes;
  _dossDetail.actSelectedPages = new Set();
  const previewEl = document.getElementById('dossDetailPreview');
  if (!previewEl) return;
  previewEl.style.padding = '0';
  previewEl.innerHTML = `<div style="padding:32px;text-align:center;color:var(--text-secondary)">${t('loadingPages')}</div>`;
  if (typeof pdfjsLib === 'undefined') {
    previewEl.innerHTML = `<div style="padding:32px;color:var(--danger)">PDF.js non disponibile</div>`; return;
  }
  if (pdfjsLib.GlobalWorkerOptions) pdfjsLib.GlobalWorkerOptions.workerSrc = 'js/pdf.worker.min.js';
  let pdfDoc;
  try {
    pdfDoc = await pdfjsLib.getDocument({ data: rawBytes.slice(0) }).promise;
  } catch(e) {
    previewEl.innerHTML = `<div style="padding:32px;color:var(--danger)">${t('pdfLoadError')}</div>`; return;
  }
  _dossDetail.actPdfDoc = pdfDoc;
  const numPages = pdfDoc.numPages;
  previewEl.innerHTML = `
    <div class="doss-act-pdf-header">
      <span class="doss-act-pdf-filename" title="${esc(f.fileName)}">📄 ${esc(f.fileName)}</span>
      <span class="doss-act-pdf-pagecount">${numPages} ${t('pageCount')}</span>
      <button class="btn btn-xs" onclick="_dossDetailCancelActFromPdf()" data-testid="button-cancel-act-pdf">${t('cancel')}</button>
    </div>
    <div class="doss-act-pdf-hint">${t('selectPagesHint')}</div>
    <div class="doss-act-pdf-grid" id="actPdfPageGrid"></div>
    <div class="doss-act-pdf-bar" id="actPdfBar">
      <span id="actPdfSelCount">0 ${t('pagesSelected')}</span>
      <button class="btn btn-primary btn-sm" id="actPdfContinue" onclick="_dossDetailActContinue()" disabled data-testid="button-act-pdf-continue">${t('continueBtn')}</button>
    </div>`;
  const grid = document.getElementById('actPdfPageGrid');
  if (!grid) return;
  for (let pageNum = 1; pageNum <= numPages; pageNum++) {
    const thumbDiv = document.createElement('div');
    thumbDiv.className = 'doss-act-pdf-thumb';
    thumbDiv.dataset.page = pageNum;
    thumbDiv.setAttribute('data-testid', `act-pdf-thumb-${pageNum}`);
    thumbDiv.innerHTML = `<div class="doss-act-pdf-thumb-loading">${pageNum}</div>`;
    thumbDiv.onclick = () => _dossDetailTogglePage(pageNum, thumbDiv);
    grid.appendChild(thumbDiv);
    (async (pn, el) => {
      try {
        const page = await pdfDoc.getPage(pn);
        const vp = page.getViewport({ scale: 0.3 });
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(vp.width);
        canvas.height = Math.round(vp.height);
        const ctx = canvas.getContext('2d');
        await page.render({ canvasContext: ctx, viewport: vp }).promise;
        el.innerHTML = '';
        el.appendChild(canvas);
        const numEl = document.createElement('span');
        numEl.className = 'doss-act-pdf-thumb-num';
        numEl.textContent = pn;
        el.appendChild(numEl);
      } catch(e) {
        el.innerHTML = `<span class="doss-act-pdf-thumb-err">!</span><span class="doss-act-pdf-thumb-num">${pn}</span>`;
      }
    })(pageNum, thumbDiv);
  }
}

function _dossDetailTogglePage(pageNum, el) {
  if (!_dossDetail || !_dossDetail.actSelectedPages) return;
  const sel = _dossDetail.actSelectedPages;
  if (sel.has(pageNum)) { sel.delete(pageNum); el.classList.remove('selected'); }
  else { sel.add(pageNum); el.classList.add('selected'); }
  const count = sel.size;
  const countEl = document.getElementById('actPdfSelCount');
  if (countEl) countEl.textContent = `${count} ${t('pagesSelected')}`;
  const btn = document.getElementById('actPdfContinue');
  if (btn) btn.disabled = count === 0;
}

function _dossDetailCancelActFromPdf() {
  if (!_dossDetail) return;
  delete _dossDetail.actPdfFileId;
  delete _dossDetail.actPdfFileName;
  delete _dossDetail.actPdfBytes;
  delete _dossDetail.actSelectedPages;
  delete _dossDetail.actPdfDoc;
  const previewEl = document.getElementById('dossDetailPreview');
  if (previewEl) {
    previewEl.style.padding = '';
    previewEl.innerHTML = `<p class="hint" style="padding:32px;text-align:center">${t('selectFileToPreview')}</p>`;
  }
}

async function _dossDetailActContinue() {
  if (!_dossDetail || !_dossDetail.actSelectedPages || _dossDetail.actSelectedPages.size === 0) return;
  const previewEl = document.getElementById('dossDetailPreview');
  if (!previewEl) return;
  previewEl.style.padding = '0';
  const baseName = (_dossDetail.actPdfFileName || '').replace(/\.[^/.]+$/, '');
  const selectedCount = _dossDetail.actSelectedPages.size;
  const pageList = [..._dossDetail.actSelectedPages].sort((a,b)=>a-b).join(', ');
  const dossFacts = _dossDetail.dossierId ? await DB.getFactsByDossier(_dossDetail.dossierId) : [];
  dossFacts.sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || a.id - b.id);
  const factOptions = dossFacts.map(f => `<option value="${f.id}">${esc(f.title)}</option>`).join('');
  const _noFacts = dossFacts.length === 0;
  const _dossierId = _dossDetail.dossierId;
  const factSelectorHtml = _noFacts
    ? `<div class="form-group" style="margin-top:8px;padding:10px 12px;border-radius:6px;background:var(--bg-warning,#fef3c7);border:1px solid var(--warning,#f59e0b)" data-testid="notice-no-facts">
        <div style="font-size:12px;color:var(--text-primary);font-weight:600;margin-bottom:6px">⚠️ ${currentLang==='en' ? 'No Facts in this Dossier' : 'Nessun Fatto in questo Fascicolo'}</div>
        <div style="font-size:12px;color:var(--text-secondary);margin-bottom:8px">${currentLang==='en' ? 'Acts must be linked to a Fact. Create a Fact first, then come back to create this act.' : 'Gli atti devono essere collegati a un Fatto. Crea prima un Fatto, poi torna qui per creare l\'atto.'}</div>
        <button class="btn btn-xs btn-primary" onclick="showAnalysisContextModal(${_dossierId})" data-testid="button-create-fact-from-pdf">${currentLang==='en' ? '+ Create Fact' : '+ Crea Fatto'}</button>
      </div>`
    : `<div class="form-group" style="margin-top:8px">
        <label style="font-weight:600;color:var(--danger)">${currentLang==='en' ? 'Related Fact *' : 'Fatto di riferimento *'}</label>
        <select id="actPdfFactId" style="width:100%" data-testid="select-act-pdf-fact" required>
          <option value="">${currentLang==='en' ? '— select a fact —' : '— seleziona un fatto —'}</option>
          ${factOptions}
        </select>
      </div>`;
  previewEl.innerHTML = `
    <div class="doss-act-pdf-header">
      <button class="btn btn-xs" onclick="_dossDetailActFromPdf(${_dossDetail.actPdfFileId})" data-testid="button-act-back">← ${t('zipFtBack').replace('← ','') || 'Indietro'}</button>
      <span class="doss-act-pdf-filename">📋 ${t('createActFromFile')}</span>
      <span class="doss-act-pdf-pagecount">${selectedCount} ${t('pagesSelected')}</span>
    </div>
    <div style="padding:6px 12px;font-size:12px;color:var(--text-secondary)">${t('selectedPagesLabel')}: <b>${pageList}</b></div>
    <div class="doss-act-pdf-form">
      <div style="display:flex;gap:6px;align-items:flex-end">
        <div class="form-group" style="flex:1;margin-bottom:0">
          <label>${t('actTitle')} IT *</label>
          <input id="actPdfTitle" value="${esc(baseName)}" style="width:100%" data-testid="input-act-pdf-title-it" />
        </div>
        <div style="display:flex;flex-direction:column;gap:2px;padding-bottom:2px">
          ${_renderTransArrow('actPdfTitle','actPdfTitleEN','it','en')}
          ${_renderTransArrow('actPdfTitleEN','actPdfTitle','en','it')}
        </div>
        <div class="form-group" style="flex:1;margin-bottom:0">
          <label>${t('actTitle')} EN</label>
          <input id="actPdfTitleEN" style="width:100%" data-testid="input-act-pdf-title-en" />
        </div>
      </div>
      ${_buildActTypeSubtypeSelects('actPdf', '', '')}
      ${factSelectorHtml}
      <div style="display:flex;gap:8px;margin-top:6px">
        <button class="btn btn-primary btn-sm" id="btnActPdfSave" onclick="_dossDetailActSaveFromPdf()" data-testid="button-act-pdf-save" ${_noFacts ? 'disabled' : ''}>${t('saveAct')}</button>
        <button class="btn btn-sm" onclick="_dossDetailCancelActFromPdf()" data-testid="button-act-pdf-cancel">${t('cancel')}</button>
      </div>
      <div id="actPdfSaveStatus" style="display:none;margin-top:8px;font-size:12px;padding:6px 8px;border-radius:4px;background:var(--bg-secondary)"></div>
    </div>`;
}

async function _dossDetailActSaveFromPdf() {
  if (!_dossDetail || !_dossDetail.actPdfBytes || !_dossDetail.actSelectedPages) return;
  const title = (document.getElementById('actPdfTitle')?.value || '').trim();
  if (!title) { document.getElementById('actPdfTitle')?.focus(); return; }
  const titleEN = (document.getElementById('actPdfTitleEN')?.value || '').trim();
  const type = document.getElementById('actPdfType')?.value || '';
  const subtype = document.getElementById('actPdfSubtype')?.value || '';
  const dossierId = _dossDetail.dossierId;
  const factIdRaw = document.getElementById('actPdfFactId')?.value || '';
  const factId = factIdRaw ? parseInt(factIdRaw, 10) : null;
  if (!factId) {
    const sel = document.getElementById('actPdfFactId');
    if (sel) { sel.style.outline = '2px solid var(--danger)'; sel.focus(); }
    return;
  }
  const statusEl = document.getElementById('actPdfSaveStatus');
  const saveBtn = document.getElementById('btnActPdfSave');
  if (saveBtn) saveBtn.disabled = true;
  if (statusEl) { statusEl.style.display = ''; statusEl.textContent = t('extractingPages'); }
  try {
    const { jsPDF } = window.jspdf;
    const selectedPages = [..._dossDetail.actSelectedPages].sort((a,b)=>a-b);
    const pdfDoc = _dossDetail.actPdfDoc;
    const firstPage = await pdfDoc.getPage(selectedPages[0]);
    const vpFirst = firstPage.getViewport({ scale: 1 });
    const isLandscape = vpFirst.width > vpFirst.height;
    const newDoc = new jsPDF({ orientation: isLandscape ? 'landscape' : 'portrait', unit: 'mm', format: 'a4' });
    const a4W = isLandscape ? 297 : 210;
    const a4H = isLandscape ? 210 : 297;
    for (let i = 0; i < selectedPages.length; i++) {
      if (statusEl) statusEl.textContent = `${t('extractingPages')} (${i+1}/${selectedPages.length})`;
      const pageNum = selectedPages[i];
      const page = await pdfDoc.getPage(pageNum);
      const scale = 2.0;
      const vp = page.getViewport({ scale });
      const canvas = document.createElement('canvas');
      canvas.width = Math.round(vp.width);
      canvas.height = Math.round(vp.height);
      const ctx = canvas.getContext('2d');
      await page.render({ canvasContext: ctx, viewport: vp }).promise;
      const imgData = canvas.toDataURL('image/jpeg', 0.85);
      if (i > 0) newDoc.addPage([a4W, a4H], isLandscape ? 'landscape' : 'portrait');
      newDoc.addImage(imgData, 'JPEG', 0, 0, a4W, a4H);
    }
    if (statusEl) statusEl.textContent = t('savingAct');
    const pdfBlob = newDoc.output('blob');
    const safeName = title.replace(/[^a-zA-Z0-9À-ÿ\s\-_]/g, '').trim().substring(0, 60) || 'atto';
    const pdfFile = new File([pdfBlob], `${safeName}.pdf`, { type: 'application/pdf' });
    // factId passato per coerenza di contesto (refresh UI), ma
    // _skipFactRelation:true assicura che l'atto nasca ORFANO. L'utente
    // crea la relazione fatto-atto esplicitamente via drag-and-drop.
    const newAct = await DB.createAct({ title, titleEN, type, subtype, factId, dossierId, _skipFactRelation: true, _isFromDossier: true });
    const hierarchy = await _resolveFileHierarchy('act', dossierId);
    await storeFileForEntity(pdfFile, 'act', newAct.id, 'it', hierarchy);
    if (statusEl) { statusEl.textContent = `✓ ${t('actCreatedSuccess')}`; statusEl.style.color = 'var(--success,#22c55e)'; }
    setTimeout(() => { _dossDetailCancelActFromPdf(); }, 2000);
  } catch(e) {
    console.error('_dossDetailActSaveFromPdf error:', e);
    if (statusEl) { statusEl.textContent = `❌ ${e.message || 'Errore'}`; statusEl.style.color = 'var(--danger)'; }
    if (saveBtn) saveBtn.disabled = false;
  }
}

async function _dossDetailDeleteAlldig(groupKey) {
  if (!_dossDetail) return;
  if (!confirm(t('confirmDelete'))) return;
  const toDelete = _dossDetail.allFiles.filter(f => {
    if (f.fileRole !== 'doss_alldig') return false;
    const m = (f.storagePath || '').match(/_DDP(\d+)/);
    return m && m[1] === groupKey;
  });
  for (const f of toDelete) {
    if (FS_FILES_HANDLE) {
      try { await deleteFileFromFS(f); } catch(e) { console.warn('FS delete error', e); }
    }
    await DB.deleteFile(f.id);
  }
  _dossDetail.allFiles = await DB.getEntityFiles('dossier', _dossDetail.dossierId);
  _renderDossDetailFiles();
  const preview = document.getElementById('dossDetailPreview');
  if (preview) preview.innerHTML = `<p class="hint" style="padding:32px;text-align:center">${t('selectFileToPreview')}</p>`;
}

function _dossFileIcon(fileType, fileName) {
  const s = ((fileType || '') + (fileName || '')).toLowerCase();
  if (s.includes('pdf')) return '📄';
  if (s.includes('zip') || s.includes('rar')) return '📦';
  if (s.startsWith('image/') || /\.(jpg|jpeg|png|gif|webp|bmp|svg)/.test(s)) return '🖼';
  if (s.startsWith('video/') || /\.(mp4|avi|mov|mkv|webm)/.test(s)) return '🎬';
  if (s.startsWith('audio/') || /\.(mp3|wav|ogg|m4a|flac)/.test(s)) return '🎵';
  if (s.includes('word') || /\.(doc|docx|odt|rtf)/.test(s)) return '📝';
  if (/\.(html|htm)/.test(s)) return '🌐';
  return '📎';
}

function _dossDetailUpdateFTBtn(file) {
  const ftBtn = document.getElementById('dossFTBtn');
  if (!ftBtn) return;
  const isHTMLExtract = file && file.fileRole === 'doss_extract' && /\.(html|htm)$/i.test(file.fileName || '');
  if (isHTMLExtract) {
    ftBtn.disabled = false;
    ftBtn.style.opacity = '1';
    ftBtn.style.cursor = 'pointer';
    ftBtn.title = file.fileName || '';
    if (_dossDetail) _dossDetail.selectedFTFileId = file.id;
  } else {
    ftBtn.disabled = true;
    ftBtn.style.opacity = '0.45';
    ftBtn.style.cursor = 'not-allowed';
    ftBtn.title = t('selectHTMLFileFirst') || 'Seleziona prima un file HTML del fascicolo';
    if (_dossDetail) _dossDetail.selectedFTFileId = null;
  }
}

async function _dossDetailOpenSelectedFT() {
  if (!_dossDetail) return;
  const allHTMLExtracts = _dossDetail.allFiles.filter(f => f.fileRole === 'doss_extract' && /\.(html|htm)$/i.test(f.fileName || ''));
  if (allHTMLExtracts.length === 0) return;
  const extractFiles = _dossDetail.allFiles.filter(f => f.fileRole === 'doss_extract');
  if (allHTMLExtracts.length === 1 || _dossDetail.selectedFTFileId) {
    const htmlFile = _dossDetail.allFiles.find(f => f.id === (_dossDetail.selectedFTFileId || allHTMLExtracts[0].id));
    if (htmlFile) await _openFascicoloTelematicModal(_dossDetail.dossierId, htmlFile, extractFiles);
    return;
  }
  const existing = document.getElementById('_ftPickerOverlay');
  if (existing) existing.remove();
  const ov = document.createElement('div');
  ov.id = '_ftPickerOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:100001;display:flex;align-items:center;justify-content:center';
  ov.innerHTML = `<div style="background:#fff;border-radius:10px;padding:24px;min-width:320px;max-width:480px;box-shadow:0 8px 32px rgba(0,0,0,.3)">
    <h3 style="margin:0 0 14px;font-size:15px">📋 ${t('chooseFTFile') || 'Scegli il file del Fascicolo Telematico'}</h3>
    <div id="_ftPickerList" style="display:flex;flex-direction:column;gap:6px;max-height:300px;overflow-y:auto"></div>
    <button style="margin-top:14px;padding:6px 16px;border:1px solid #d1d5db;border-radius:6px;background:#fff;cursor:pointer" onclick="document.getElementById('_ftPickerOverlay').remove()">✕ ${t('cancel') || 'Annulla'}</button>
  </div>`;
  document.body.appendChild(ov);
  const list = ov.querySelector('#_ftPickerList');
  for (const f of allHTMLExtracts) {
    const btn = document.createElement('button');
    btn.style.cssText = 'text-align:left;padding:10px 14px;border:1px solid #d1d5db;border-radius:6px;background:#f8fafc;cursor:pointer;font-size:13px;display:flex;align-items:center;gap:8px';
    btn.innerHTML = `<span>🌐</span><span style="word-break:break-all">${esc(f.fileName)}</span>`;
    btn.onclick = async () => {
      ov.remove();
      if (_dossDetail) _dossDetail.selectedFTFileId = f.id;
      await _openFascicoloTelematicModal(_dossDetail.dossierId, f, extractFiles);
    };
    list.appendChild(btn);
  }
  ov.addEventListener('click', e => { if (e.target === ov) ov.remove(); });
}

function _dossDetailSelectFile(fileId, itemEl) {
  const container = document.getElementById('dossDetailFiles');
  if (container) container.querySelectorAll('.doss-detail-file-item').forEach(el => el.classList.remove('active'));
  if (itemEl) itemEl.classList.add('active');
  const preview = document.getElementById('dossDetailPreview');
  if (!preview) return;
  preview.innerHTML = `<p class="hint" style="padding:16px">${t('loadingPreview')}</p>`;
  DB.getFile(fileId).then(async file => {
    if (!file) { preview.innerHTML = `<p class="hint" style="padding:16px">${t('previewNotAvailable')}</p>`; return; }
    const isZip = /\.zip$/i.test(file.fileName || '') ||
      file.fileType === 'application/zip' ||
      file.fileType === 'application/x-zip-compressed';
    if (_dossDetail && (file.fileRole === 'doss_orig' || file.fileRole === 'doss_cert' || !file.fileRole)) {
      if (isZip) {
        _dossDetail.selectedZipId = fileId;
      } else {
        _dossDetail.selectedZipId = null;
      }
      _renderDossDetailFiles();
      const newEl = document.querySelector(`[data-file-id="${fileId}"]`);
      if (newEl) newEl.classList.add('active');
    }
    if (isZip && typeof JSZip !== 'undefined') {
      try {
        let buf;
        if (file.blob) {
          const rawBlob = new Blob([file.blob]);
          buf = await rawBlob.arrayBuffer();
        } else {
          preview.innerHTML = `<p class="hint" style="padding:16px">${t('previewNotAvailable')}</p>`;
          return;
        }
        const zip = await JSZip.loadAsync(buf);
        const htmlEntries = Object.keys(zip.files).filter(p => {
          if (zip.files[p].dir) return false;
          const parts = p.split('/').filter(Boolean);
          if (parts.length !== 1) return false;
          const name = parts[0].toLowerCase();
          return name.endsWith('.html') || name.endsWith('.htm');
        });
        if (htmlEntries.length > 0) {
          _dossDetailShowZipChoice(file, zip, htmlEntries, preview);
        } else {
          _dossDetailShowZipExplorer(zip, preview);
        }
      } catch (e) {
        console.error('ZIP detect error:', e);
        preview.innerHTML = `<p class="hint" style="padding:16px">${t('previewNotAvailable')}</p>`;
      }
      return;
    }
    if (file.blob) {
      const blob = new Blob([file.blob], { type: file.fileType });
      const url = URL.createObjectURL(blob);
      preview.innerHTML = _buildPreviewInner(url, file);
    } else {
      const cid = 'dd_fp_' + fileId;
      preview.innerHTML = `<div id="${cid}" class="file-preview"><p class="hint">${t('loadingPreview')}</p></div>`;
      loadPreviewFromFS(file, cid);
    }
  });
}

/* ===== ZIP DB EXPLORER MODAL ===== */

async function _openZipExplorerModal(fileId) {
  const zipFile = await DB.getFile(fileId);
  if (!zipFile) return;

  const extractedFiles = await DB.getFilesBySourceId(fileId);
  extractedFiles.sort((a, b) => (a.fileName || '').localeCompare(b.fileName || ''));

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.style.cssText = 'z-index:9998';

  const noFilesHtml = extractedFiles.length === 0
    ? `<p class="hint" style="padding:20px 16px;font-size:13px">${t('zipDbExploreNoFiles') || 'Nessun file estratto trovato.'}</p>`
    : extractedFiles.map((f, i) => {
        const icon = _dossFileIcon(f.fileType, f.fileName);
        const canPrev = _isPreviewable(f.fileType, f.fileName);
        return `<div class="zip-db-explorer-item" data-idx="${i}" onclick="_zipDbExplorerSelect(${f.id}, this)" data-testid="zip-dbitem-${f.id}">
          <span class="zip-db-explorer-icon">${icon}</span>
          <span class="zip-db-explorer-name" title="${esc(f.fileName)}">${esc(f.fileName)}</span>
          <span class="zip-db-explorer-size">${formatSize(f.fileSize)}</span>
          ${canPrev ? `<span class="zip-db-explorer-prev-hint">👁</span>` : ''}
        </div>`;
      }).join('');

  overlay.innerHTML = `
    <div class="modal-content zip-db-explorer-modal" data-testid="modal-zip-explorer">
      <div class="zip-db-explorer-header">
        <span class="zip-db-explorer-title">🗜 ${esc(zipFile.fileName || '')}</span>
        <div style="display:flex;align-items:center;gap:8px;flex-shrink:0">
          <span class="hint" style="font-size:11px">${extractedFiles.length} ${extractedFiles.length === 1 ? 'file' : 'file'}</span>
          <button class="btn btn-xs" onclick="this.closest('.modal-overlay').remove()" data-testid="button-zip-explorer-close">✕</button>
        </div>
      </div>
      <div class="zip-db-explorer-body">
        <div class="zip-db-explorer-list" id="zipDbExplorerList">
          ${noFilesHtml}
        </div>
        <div class="zip-db-explorer-preview" id="zipDbExplorerPreview">
          <p class="hint" style="padding:24px 16px;text-align:center;font-size:13px">
            ${extractedFiles.length > 0 ? (t('zipDbExploreHint') || 'Seleziona un file per l\'anteprima') : ''}
          </p>
        </div>
      </div>
    </div>`;

  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  document.body.appendChild(overlay);
}

async function _zipDbExplorerSelect(fileId, itemEl) {
  const list = document.getElementById('zipDbExplorerList');
  if (list) list.querySelectorAll('.zip-db-explorer-item').forEach(el => el.classList.remove('active'));
  if (itemEl) itemEl.classList.add('active');

  const preview = document.getElementById('zipDbExplorerPreview');
  if (!preview) return;
  preview.innerHTML = `<p class="hint" style="padding:24px 16px;text-align:center">${t('loadingPreview') || 'Caricamento...'}</p>`;

  const f = await DB.getFile(fileId);
  if (!f) { preview.innerHTML = `<p class="hint" style="padding:24px 16px;text-align:center">${t('zipDbExploreNoPreview') || 'Anteprima non disponibile.'}</p>`; return; }

  let blobData = f.blob;
  if (!blobData && f.storagePath) {
    try {
      let dir = (typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) ? FS_FILES_HANDLE
              : (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) ? FS_DIR_HANDLE : null;
      if (dir) {
        const parts = f.storagePath.split('/').filter(Boolean);
        for (const part of parts) dir = await dir.getDirectoryHandle(part);
        const fh = await dir.getFileHandle(f.diskFileName || f.fileName);
        const file = await fh.getFile();
        blobData = new Uint8Array(await file.arrayBuffer());
      }
    } catch(e) { console.warn('ZIP explorer FS read:', e); }
  }

  if (!blobData) {
    preview.innerHTML = `<p class="hint" style="padding:24px 16px;text-align:center">${t('zipDbExploreNoPreview') || 'Anteprima non disponibile.'}</p>`;
    return;
  }

  const mediaType = _isPreviewable(f.fileType, f.fileName);
  const mimeGuess = f.fileType && f.fileType !== 'application/octet-stream' ? f.fileType
    : mediaType === 'pdf' ? 'application/pdf'
    : mediaType === 'image' ? 'image/' + (f.fileName || '').split('.').pop().toLowerCase()
    : mediaType === 'video' ? 'video/mp4'
    : 'audio/mpeg';
  const rawBytes = blobData instanceof Uint8Array ? blobData : new Uint8Array(blobData);
  const blob = new Blob([rawBytes], { type: mimeGuess });
  const url = URL.createObjectURL(blob);

  let mediaHtml;
  if (mediaType === 'image') {
    mediaHtml = `<div style="overflow:auto;text-align:center;padding:12px;height:100%;box-sizing:border-box;background:var(--bg-secondary)"><img src="${url}" alt="${esc(f.fileName)}" style="max-width:100%;max-height:calc(80vh - 80px);object-fit:contain;border-radius:4px;box-shadow:0 2px 12px rgba(0,0,0,.18)"></div>`;
  } else if (mediaType === 'video') {
    mediaHtml = `<div style="padding:12px;background:#000;height:100%;box-sizing:border-box"><video controls src="${url}" style="width:100%;max-height:calc(80vh - 80px);display:block;margin:auto;border-radius:4px"></video></div>`;
  } else if (mediaType === 'audio') {
    mediaHtml = `<div style="padding:48px 24px;text-align:center;background:var(--bg-secondary);height:100%;box-sizing:border-box"><div style="font-size:48px;margin-bottom:16px">🎵</div><p style="font-size:13px;color:var(--text-muted);margin-bottom:16px">${esc(f.fileName)}</p><audio controls src="${url}" style="width:100%;max-width:440px"></audio></div>`;
  } else if (mediaType) {
    mediaHtml = `<iframe src="${url}" style="width:100%;height:100%;border:none;background:#fff;display:block"></iframe>`;
  } else {
    preview.innerHTML = `<p class="hint" style="padding:24px 16px;text-align:center">${t('zipDbExploreNoPreview') || 'Anteprima non disponibile.'}</p>`;
    return;
  }

  const nameBar = `<div style="display:flex;align-items:center;gap:8px;padding:8px 12px;background:var(--bg-secondary);border-bottom:1px solid var(--border);font-size:12px;flex-shrink:0">
    <span style="font-size:16px">${_dossFileIcon(f.fileType, f.fileName)}</span>
    <span style="font-weight:600;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(f.fileName)}">${esc(f.fileName)}</span>
    <span class="hint">${formatSize(f.fileSize)}</span>
    <button class="btn btn-xs" onclick="downloadFile(${f.id})" data-testid="button-zip-preview-dl-${f.id}">⬇</button>
  </div>`;

  preview.innerHTML = `<div style="display:flex;flex-direction:column;height:100%">${nameBar}<div style="flex:1;overflow:auto;min-height:0">${mediaHtml}</div></div>`;
}

/* ===== ZIP / FASCICOLO TELEMATICO VIEWER ===== */

function _dossDetailShowZipChoice(file, zip, htmlEntries, previewEl) {
  _dossDetailZip = zip;
  _dossDetailZipChoiceState = { file, htmlEntries };
  const el = previewEl || document.getElementById('dossDetailPreview');
  if (!el) return;
  el.innerHTML = `
    <div class="zip-choice-panel">
      <div class="zip-choice-filename">🗜 ${esc(file.fileName || '')}</div>
      <p class="zip-choice-subtitle">${t('zipTypeChoiceTitle')}</p>
      <div class="zip-choice-buttons">
        <button class="zip-choice-btn" onclick="_dossDetailShowZipExplorer(null, document.getElementById('dossDetailPreview'))" data-testid="button-zip-explore">
          <span class="zip-choice-btn-icon">🗂</span>
          <span class="zip-choice-btn-label">${t('zipChoiceExplore')}</span>
          <span class="zip-choice-btn-hint">${t('zipChoiceExploreHint')}</span>
        </button>
        <button class="zip-choice-btn ft-btn" onclick="_dossDetailOpenFascicoloTelematico(null, document.getElementById('dossDetailPreview'))" data-testid="button-zip-fasc">
          <span class="zip-choice-btn-icon">📋</span>
          <span class="zip-choice-btn-label">${t('zipChoiceFasc')}</span>
          <span class="zip-choice-btn-hint">${t('zipChoiceFascHint')}</span>
        </button>
      </div>
    </div>`;
}

async function _dossDetailShowZipExplorer(zip, previewEl) {
  const z = zip || _dossDetailZip;
  const el = previewEl || document.getElementById('dossDetailPreview');
  if (!z || !el) return;
  const entries = Object.entries(z.files).filter(([, e]) => !e.dir).sort(([a], [b]) => a.localeCompare(b));
  const folders = {};
  for (const [path] of entries) {
    const parts = path.split('/');
    if (parts.length > 1) {
      const folder = parts.slice(0, -1).join('/');
      if (!folders[folder]) folders[folder] = [];
      folders[folder].push(path);
    } else {
      if (!folders['']) folders[''] = [];
      folders[''].push(path);
    }
  }
  const hasChoice = !!_dossDetailZipChoiceState;
  let itemsHtml = '';
  for (const [folder, paths] of Object.entries(folders).sort()) {
    if (folder) {
      itemsHtml += `<div class="zip-explorer-folder">📁 ${esc(folder)}/</div>`;
    }
    for (const path of paths) {
      const entry = z.files[path];
      const fname = path.split('/').pop();
      const size = entry._data ? (entry._data.uncompressedSize || 0) : 0;
      const icon = _dossFileIcon(_guessFileType(fname), fname);
      const safeId = path.replace(/[^a-z0-9]/gi, '_');
      itemsHtml += `<div class="zip-explorer-item" onclick="_ftOpenDoc('${path.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}')" data-testid="zip-item-${safeId}">
        <span class="zip-explorer-icon">${icon}</span>
        <span class="zip-explorer-path">${esc(fname)}</span>
        <span class="zip-explorer-size">${size ? formatSize(size) : ''}</span>
      </div>`;
    }
  }
  el.innerHTML = `
    <div class="zip-explorer">
      <div class="zip-explorer-header">
        <span>🗜 ${t('zipExploreTitle')}</span>
        ${hasChoice ? `<button class="btn btn-xs" onclick="_dossDetailRestoreZipChoice(document.getElementById('dossDetailPreview'))" data-testid="button-zip-back">${t('zipFtBack')}</button>` : ''}
      </div>
      <div class="zip-explorer-list">
        ${itemsHtml || `<p class="hint" style="padding:16px">${t('zipExploreNoFiles')}</p>`}
      </div>
    </div>`;
}

async function _dossDetailOpenFascicoloTelematico(htmlEntry, previewEl) {
  const z = _dossDetailZip;
  const el = previewEl || document.getElementById('dossDetailPreview');
  if (!z || !el) return;
  const entry = htmlEntry || (_dossDetailZipChoiceState && _dossDetailZipChoiceState.htmlEntries && _dossDetailZipChoiceState.htmlEntries[0]);
  if (!entry) return;
  el.innerHTML = `<p class="hint" style="padding:16px">${t('zipFtLoading')}</p>`;
  try {
    const bytes = await z.files[entry].async('uint8array');
    let htmlText;
    try { htmlText = new TextDecoder('windows-1252').decode(bytes); } catch(e) {
      try { htmlText = new TextDecoder('iso-8859-1').decode(bytes); } catch(e2) {
        htmlText = new TextDecoder('utf-8').decode(bytes);
      }
    }
    const parser = new DOMParser();
    const doc = parser.parseFromString(htmlText, 'text/html');
    const pageTitle = (doc.title || entry.split('/').pop()).trim();
    const tables = Array.from(doc.querySelectorAll('table'));
    let tablesHtml = '';
    for (const tbl of tables) {
      let tblHtml = '<table class="ft-table">';
      const rows = Array.from(tbl.querySelectorAll('tr'));
      for (const row of rows) {
        const cells = Array.from(row.querySelectorAll('th, td'));
        const isHeader = cells.length > 0 && cells[0].tagName === 'TH';
        tblHtml += isHeader ? '<tr>' : '<tr>';
        for (const cell of cells) {
          const tag = cell.tagName.toLowerCase();
          const colspan = cell.getAttribute('colspan') ? ` colspan="${cell.getAttribute('colspan')}"` : '';
          const rowspan = cell.getAttribute('rowspan') ? ` rowspan="${cell.getAttribute('rowspan')}"` : '';
          let cellContent = '';
          for (const child of Array.from(cell.childNodes)) {
            if (child.nodeType === Node.TEXT_NODE) {
              cellContent += esc(child.textContent);
            } else if (child.nodeType === Node.ELEMENT_NODE) {
              if (child.tagName === 'A') {
                const href = child.getAttribute('href') || '';
                if (href && !href.startsWith('http') && !href.startsWith('#') && !href.startsWith('mailto')) {
                  const safeHref = href.replace(/&amp;/g, '&');
                  const label = (child.textContent || '').trim() || href.split('/').pop();
                  cellContent += `<button class="ft-doc-link" data-ft-href="${esc(safeHref)}" title="${esc(safeHref)}">${esc(label)}</button>`;
                } else {
                  cellContent += esc(child.textContent);
                }
              } else if (child.tagName === 'BR') {
                cellContent += '<br>';
              } else {
                cellContent += esc(child.textContent);
              }
            }
          }
          tblHtml += `<${tag}${colspan}${rowspan}>${cellContent}</${tag}>`;
        }
        tblHtml += '</tr>';
      }
      tblHtml += '</table>';
      tablesHtml += tblHtml;
    }
    if (!tablesHtml) {
      const bodyText = doc.body ? doc.body.innerText || doc.body.textContent : '';
      tablesHtml = `<div class="ft-raw-content">${esc(bodyText)}</div>`;
    }
    const hasChoice = !!_dossDetailZipChoiceState;
    el.innerHTML = `
      <div class="ft-viewer">
        <div class="ft-viewer-header">
          <span>📋</span>
          <span class="ft-viewer-title">${esc(pageTitle)}</span>
          ${hasChoice ? `<button class="btn btn-xs" onclick="_dossDetailRestoreZipChoice(document.getElementById('dossDetailPreview'))" data-testid="button-ft-back">${t('zipFtBack')}</button>` : ''}
        </div>
        <div class="ft-viewer-body">
          ${tablesHtml}
        </div>
      </div>`;
    el.querySelectorAll('.ft-doc-link').forEach(btn => {
      btn.addEventListener('click', () => _ftOpenDoc(btn.dataset.ftHref));
    });
  } catch(e) {
    console.error('FT parse error:', e);
    el.innerHTML = `<p class="hint" style="padding:16px">${t('previewNotAvailable')}</p>`;
  }
}

function _dossDetailRestoreZipChoice(previewEl) {
  if (!_dossDetailZipChoiceState || !_dossDetailZip) return;
  const { file, htmlEntries } = _dossDetailZipChoiceState;
  _dossDetailShowZipChoice(file, _dossDetailZip, htmlEntries, previewEl);
}

async function _ftOpenDoc(href) {
  if (!_dossDetailZip || !href) return;
  const normalized = href.replace(/\\/g, '/').replace(/^\.\//, '');
  let entry = null;
  if (_dossDetailZip.files[normalized] && !_dossDetailZip.files[normalized].dir) {
    entry = _dossDetailZip.files[normalized];
  }
  if (!entry) {
    const lower = normalized.toLowerCase();
    for (const [path, zipEntry] of Object.entries(_dossDetailZip.files)) {
      if (!zipEntry.dir && path.toLowerCase() === lower) { entry = zipEntry; break; }
    }
  }
  if (!entry) {
    const fname = normalized.split('/').pop().toLowerCase();
    for (const [path, zipEntry] of Object.entries(_dossDetailZip.files)) {
      if (!zipEntry.dir && path.split('/').pop().toLowerCase() === fname) { entry = zipEntry; break; }
    }
  }
  if (!entry) {
    alert((t('zipFtDocNotFound') || 'Documento non trovato') + ': ' + href);
    return;
  }
  try {
    const buf = await entry.async('arraybuffer');
    const fileName = normalized.split('/').pop();
    const mimeType = _guessFileType(fileName);
    const blob = new Blob([buf], { type: mimeType });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
  } catch(e) {
    console.error('_ftOpenDoc error:', e);
    alert(t('zipFtDocNotFound') + ': ' + href);
  }
}

/* ===== FINE ZIP / FASCICOLO TELEMATICO VIEWER ===== */

async function _dossDetailDeleteFile(fileId) {
  if (!_dossDetail) return;
  const _L = currentLang === 'en';
  const f = await DB.getFile(fileId);
  if (!f) return;
  // Blocca se il file è collegato ad altre entità
  const proofRefs = await DB.getFilesBySourceId(fileId);
  const certFiles = await DB.getFilesByLinkedOrigId(fileId);
  const blockers = [];
  if (proofRefs.length > 0)
    blockers.push(_L
      ? `used as source for ${proofRefs.length} proof file(s)`
      : `usato come sorgente da ${proofRefs.length} prova${proofRefs.length > 1 ? 'e' : ''}`);
  if (certFiles.length > 0)
    blockers.push(_L
      ? `has ${certFiles.length} linked certified translation(s)`
      : `ha ${certFiles.length} traduzione${certFiles.length > 1 ? 'i' : ''} certificata collegata${certFiles.length > 1 ? '' : ''}`);
  if (blockers.length > 0) {
    alert(_L
      ? `Cannot delete \u201c${f.fileName}\u201d: it is ${blockers.join(' and ')}. Remove links first.`
      : `Impossibile eliminare \u201c${f.fileName}\u201d: \xc3\xa8 ${blockers.join(' e ')}. Rimuovi prima i collegamenti.`);
    return;
  }
  const msg = _L
    ? `Permanently delete \u201c${f.fileName}\u201d from database and filesystem?`
    : `Eliminare definitivamente \u201c${f.fileName}\u201d dal database e dal filesystem?`;
  if (!confirm(msg)) return;
  if (FS_FILES_HANDLE && !f.sourceFileId) {
    try { await deleteFileFromFS(f); } catch(e) { console.warn('FS delete error', e); }
  }
  await DB.deleteFile(fileId);
  _dossDetail.allFiles = await DB.getEntityFiles('dossier', _dossDetail.dossierId);
  _renderDossDetailFiles();
  const preview = document.getElementById('dossDetailPreview');
  if (preview) preview.innerHTML = `<p class="hint" style="padding:32px;text-align:center">${t('selectFileToPreview')}</p>`;
}


async function _dossDetailDeleteAllFiles(dossierId) {
  if (!_dossDetail) return;
  const _L = currentLang === 'en';
  const [files, acts, facts] = await Promise.all([
    DB.getEntityFiles('dossier', dossierId),
    DB.getActs(dossierId),
    DB.getFactsByDossier(dossierId)
  ]);
  const blockers = [];
  if (acts && acts.length > 0)
    blockers.push(_L ? `${acts.length} act(s)` : `${acts.length} atto${acts.length > 1 ? 'i' : ''}`);
  if (facts && facts.length > 0)
    blockers.push(_L ? `${facts.length} fact(s)` : `${facts.length} fatto${facts.length > 1 ? 'i' : ''}`);
  if (blockers.length > 0) {
    alert(_L
      ? `Cannot delete files: the dossier still contains ${blockers.join(' and ')}. Remove them first.`
      : `Impossibile eliminare i file: il fascicolo contiene ancora ${blockers.join(' e ')}. Rimuovili prima.`);
    return;
  }
  if (!files || files.length === 0) {
    alert(_L ? 'No files to delete.' : 'Nessun file da eliminare.');
    return;
  }
  // Verifica che nessun file sia collegato a prove o traduzioni certificate
  const linkedFiles = [];
  for (const chk of files) {
    if (chk.sourceFileId != null) continue; // skip refs secondari
    const proofRefs = await DB.getFilesBySourceId(chk.id);
    const certLinks = await DB.getFilesByLinkedOrigId(chk.id);
    const reasons = [];
    if (proofRefs.length > 0)
      reasons.push(_L
        ? `source for ${proofRefs.length} proof file(s)`
        : `sorgente di ${proofRefs.length} prova${proofRefs.length > 1 ? 'e' : ''}`);
    if (certLinks.length > 0)
      reasons.push(_L
        ? `has ${certLinks.length} certified translation(s)`
        : `ha ${certLinks.length} traduzione${certLinks.length > 1 ? 'i' : ''} certificata${certLinks.length > 1 ? '' : ''}`);
    if (reasons.length > 0)
      linkedFiles.push(`• ${chk.fileName} (${reasons.join(', ')})`);
  }
  if (linkedFiles.length > 0) {
    const detail = linkedFiles.join('\n');
    alert(_L
      ? `Cannot delete all files: ${linkedFiles.length} file(s) are still linked:\n${detail}\n\nRemove the links first or delete them individually.`
      : `Impossibile eliminare tutti i file: ${linkedFiles.length} file sono ancora collegati a prove o traduzioni:\n${detail}\n\nRimuovi prima i collegamenti o eliminali singolarmente.`);
    return;
  }
  const msg = _L
    ? `Delete all ${files.length} file(s) from the dossier?\n\nThe dossier itself will be preserved.`
    : `Eliminare tutti i ${files.length} file dal fascicolo?\n\nIl fascicolo stesso verrà conservato.`;
  if (!confirm(msg)) return;
  for (const f of files) {
    if (f.sourceFileId == null && typeof deleteFileFromFS === 'function') {
      try { await deleteFileFromFS(f); } catch(e) { console.warn('FS delete error', e); }
    }
    await DB.deleteFile(f.id);
  }
  _dossDetail.allFiles = await DB.getEntityFiles('dossier', dossierId);
  _renderDossDetailFiles();
  const preview = document.getElementById('dossDetailPreview');
  if (preview) preview.innerHTML = `<p class="hint" style="padding:32px;text-align:center">${t('selectFileToPreview')}</p>`;
}

function _factItemDragOver(event) {
  event.preventDefault();
  event.dataTransfer.dropEffect = 'link';
  const item = event.currentTarget;
  if (!item.classList.contains('drag-over')) item.classList.add('drag-over');
}

function _factItemDragLeave(event) {
  event.currentTarget.classList.remove('drag-over');
}

async function _proofDropOnFact(event, factId) {
  event.preventDefault();
  event.currentTarget.classList.remove('drag-over');
  if (_isMemoContext) return;
  const actIdStr = event.dataTransfer.getData('application/act-id');
  const actId = parseInt(actIdStr, 10);
  if (actId && !isNaN(actId)) {
    const existingRels = await DB.getFactActRelations(factId);
    if (existingRels.some(r => r.actId === actId)) {
      alert('Questo atto è già collegato al fatto.');
      return;
    }
    _showRelationTypeModal(['afferma','contraddice','omette','travisa','non_pronuncia'], tFactPosition, async (posizioneAtto) => {
      await DB.createFactActRelation({ factId, actId, posizioneAtto });
      if (_factAnalysisSelectedId) await _updateFactAnalysisColumns(_factAnalysisSelectedId);
    });
    return;
  }
  const proofIdStr = event.dataTransfer.getData('application/proof-id');
  const proofId = parseInt(proofIdStr, 10);
  if (proofId && !isNaN(proofId)) {
    _showRelationTypeModal(['confirms','contradicts','integrates','ignored'], tProofRelType, async (relationType) => {
      await DB.createFactProofRelation({ factId, proofId, relationType });
      if (_factAnalysisSelectedId) await _updateFactAnalysisColumns(_factAnalysisSelectedId);
    });
    return;
  }
  const dossierIdStr = event.dataTransfer.getData('application/dossier-id');
  const dossierId = parseInt(dossierIdStr, 10);
  if (dossierId && !isNaN(dossierId)) {
    _showRelationTypeModal(['confirms','contradicts','integrates','ignored'], tProofRelType, async (relationType) => {
      await DB.createFactDossierRelation({ factId, dossierId, relationType });
      if (_factAnalysisSelectedId) await _updateFactAnalysisColumns(_factAnalysisSelectedId);
    });
    return;
  }
}

async function _proofDropOnAct(event, actId) {
  event.preventDefault();
  event.currentTarget.classList.remove('drag-over');
  event.currentTarget.classList.remove('act-reorder-over');
  // Riordino card atto: se in corso un drag di reorder, gestiscilo qui
  // e ritorna senza creare relazioni.
  const reorderIdStr = event.dataTransfer.getData('application/act-reorder');
  const reorderId = _actReorderDraggedId || parseInt(reorderIdStr, 10);
  if (reorderId && !isNaN(reorderId)) {
    const factId = _factAnalysisSelectedId;
    await _actReorderDrop(event, actId, factId);
    return;
  }
  if (_isMemoContext) {
    const factId = _factAnalysisSelectedId;
    const memoProofIdStr = event.dataTransfer.getData('application/memo-proof-id');
    const memoProofId = parseInt(memoProofIdStr, 10);
    if (memoProofId && !isNaN(memoProofId)) {
      const existing = await DB.getMemoActProofRels(factId);
      if (existing.some(r => r.archivioActId === actId && r.archivioProofId === memoProofId)) {
        alert('Questa prova è già collegata all\'atto.');
        return;
      }
      _showRelationTypeModal(['cita_a_supporto','cita_a_contrario','non_considera'], tActProofRelType, async (relationType) => {
        await DB.createMemoActProofRel(actId, memoProofId, relationType);
        await _updateFactAnalysisColumns(factId);
      });
      return;
    }
    const memoActIdBStr = event.dataTransfer.getData('application/memo-act-id');
    const memoActIdB = parseInt(memoActIdBStr, 10);
    if (memoActIdB && !isNaN(memoActIdB) && memoActIdB !== actId) {
      const existing = await DB.getMemoActActRels(factId);
      if (existing.some(r => (r.archivioActIdA === actId && r.archivioActIdB === memoActIdB) || (r.archivioActIdA === memoActIdB && r.archivioActIdB === actId))) {
        alert('Questi atti sono già collegati.');
        return;
      }
      _showRelationTypeModal(['richiama','contraddice','conferma','modifica','annulla','impugna'], tActActRelType, async (relationType) => {
        await DB.createMemoActActRel(actId, memoActIdB, relationType);
        await _updateFactAnalysisColumns(factId);
      });
    }
    return;
  }
  const actIdBStr = event.dataTransfer.getData('application/act-id');
  const actIdB = parseInt(actIdBStr, 10);
  if (actIdB && !isNaN(actIdB)) {
    if (actIdB === actId) return;
    const existing = await DB.getActActRelations(actId);
    const already = existing.some(r => (r.actIdA === actId && r.actIdB === actIdB) || (r.actIdA === actIdB && r.actIdB === actId));
    if (already) { alert('Questi atti sono già collegati.'); return; }
    _showRelationTypeModal(['richiama','contraddice','conferma','modifica','annulla','impugna'], tActActRelType, async (relationType) => {
      await DB.addActActRelation({ actIdA: actId, actIdB, relationType });
      if (_factAnalysisSelectedId) await _updateActsColumn(_factAnalysisSelectedId);
    });
    return;
  }
  const proofIdStr = event.dataTransfer.getData('application/proof-id');
  const proofId = parseInt(proofIdStr, 10);
  if (!proofId || isNaN(proofId)) return;
  _showRelationTypeModal(['cita_a_supporto','cita_a_contrario','non_considera'], tActProofRelType, async (relationType) => {
    await DB.createActProofRelation({ actId, proofId, relationType });
    if (_factAnalysisSelectedId) await _updateFactAnalysisColumns(_factAnalysisSelectedId);
  });
}

function _actDragStart(event, actId) {
  event.dataTransfer.setData('application/act-id', String(actId));
  event.dataTransfer.effectAllowed = 'link';
}

function _actDropOver(event) {
  event.preventDefault();
  if (_actReorderDraggedId !== null) {
    event.dataTransfer.dropEffect = 'move';
    const item = event.currentTarget;
    if (!item.classList.contains('act-reorder-over')) {
      document.querySelectorAll('.act-reorder-over').forEach(el => el.classList.remove('act-reorder-over'));
      item.classList.add('act-reorder-over');
    }
  } else {
    _factItemDragOver(event);
  }
}

let _actReorderDraggedId = null;

function _actReorderDragStart(event, actId) {
  event.stopPropagation();
  _actReorderDraggedId = actId;
  event.dataTransfer.setData('application/act-reorder', String(actId));
  event.dataTransfer.effectAllowed = 'move';
  const card = event.currentTarget.closest('.fact-column-item');
  if (card) card.classList.add('act-reorder-dragging');
}

function _actReorderDragEnd(event) {
  _actReorderDraggedId = null;
  document.querySelectorAll('.act-reorder-dragging').forEach(el => el.classList.remove('act-reorder-dragging'));
  document.querySelectorAll('.act-reorder-over').forEach(el => el.classList.remove('act-reorder-over'));
}

async function _actReorderDrop(event, targetActId, factId) {
  if (_actReorderDraggedId === null) return false;
  event.preventDefault();
  event.stopPropagation();
  const draggedId = _actReorderDraggedId;
  _actReorderDraggedId = null;
  document.querySelectorAll('.act-reorder-over').forEach(el => el.classList.remove('act-reorder-over'));
  if (draggedId === targetActId) return true;
  const allCards = [...document.querySelectorAll('#factColActsBody [data-testid^="act-item-"]')];
  const ids = allCards.map(el => parseInt(el.getAttribute('data-testid').replace('act-item-', ''), 10)).filter(n => !isNaN(n));
  const fromIdx = ids.indexOf(draggedId);
  const toIdx = ids.indexOf(targetActId);
  if (fromIdx === -1 || toIdx === -1) return true;
  ids.splice(fromIdx, 1);
  const insertIdx = toIdx > fromIdx ? toIdx - 1 : toIdx;
  ids.splice(insertIdx, 0, draggedId);
  await Promise.all(ids.map((id, i) => DB.updateAct(id, { sortOrder: i * 10 })));
  if (factId) await _updateActsColumn(factId);
  return true;
}

function _renderInDossierBadge(isFrom) {
  if (isFrom === undefined || isFrom === null) return '';
  if (isFrom) {
    return `<span class="tree-badge" style="font-size:9px;background:#dcfce7;color:#166534;border:1px solid #86efac" title="${t('badgeInDossier') || 'In fascicolo'}">📁 ${t('badgeInDossier') || 'In fascicolo'}</span>`;
  }
  return `<span class="tree-badge" style="font-size:9px;background:#fef9c3;color:#854d0e;border:1px solid #fde047" title="${t('badgeExternal') || 'Esterna'}">${t('badgeExternal') || 'Esterna'}</span>`;
}

function _renderProvenienzaBadge(provenance) {
  if (provenance === true || provenance === false || provenance === undefined || provenance === null) {
    return _renderInDossierBadge(provenance);
  }
  if (provenance === 'pec') {
    return `<span class="tree-badge" style="font-size:9px;background:#e0f2fe;color:#0369a1;border:1px solid #7dd3fc" title="${t('badgePec') || 'Da PEC'}">📧 ${t('badgePec') || 'Da PEC'}</span>`;
  }
  if (provenance === 'dossier') {
    return `<span class="tree-badge" style="font-size:9px;background:#dcfce7;color:#166534;border:1px solid #86efac" title="${t('badgeInDossier') || 'In fascicolo'}">📁 ${t('badgeInDossier') || 'In fascicolo'}</span>`;
  }
  return `<span class="tree-badge" style="font-size:9px;background:#fef9c3;color:#854d0e;border:1px solid #fde047" title="${t('badgeExternal') || 'Esterna'}">${t('badgeExternal') || 'Esterna'}</span>`;
}

async function _buildFromDossierFlags(entityType, items) {
  if (!items || items.length === 0) return [];
  const out = new Array(items.length);
  for (let i = 0; i < items.length; i++) {
    try { out[i] = await DB.getEntityHasSourceFile(entityType, items[i].id); }
    catch (_) { out[i] = false; }
  }
  return out;
}

function _renderActsSublist(acts, unlinkOpts, rels, fromDossierFlags, filesById) {
  if (!acts || acts.length === 0) return '';
  const items = acts.map((a, idx) => {
    let unlinkBtn = '';
    if (_proofEditActive && unlinkOpts && unlinkOpts.circId) {
      unlinkBtn = `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkActFromCircumstance(${a.id},${unlinkOpts.circId})" data-testid="button-unlink-circ-act-${a.id}" title="${t('unlink')}">✂</button>`;
    }
    const rel = rels && rels[idx];
    const relType = rel?.posizioneAtto || rel?.relationType || '';
    const relLabel = relType ? tFactPosition(relType) : '';
    const _caBadge = relType ? factPositionBadge(relType) : { cls: 'tree-badge-neutral', label: '○' };
    const relBadge = relLabel ? `<span class="tree-badge ${_caBadge.cls}" style="font-size:9px;flex-shrink:0">${esc(relLabel)}</span>` : '';
    const _caTypeLabel = actTypeBadge(a.type, a.subtype);
    const pos = relType || 'afferma';
    const clickHandler = _isMemoContext ? '' : `onclick="event.stopPropagation(); openViewActModal(${a.id}, '${pos}')"`;
    const cursorStyle = _isMemoContext ? 'default' : 'pointer';
    const inDossBadge = (fromDossierFlags && idx < fromDossierFlags.length) ? _renderProvenienzaBadge(fromDossierFlags[idx]) : '';
    // Icone download: presenti sulle card atti/prove del fatto, assenti
    // sulle card circostanza (unlinkOpts.circId valorizzato).
    const _files = filesById && filesById[a.id];
    const _dlIcons = (unlinkOpts && unlinkOpts.circId) ? '' : _renderEntityFileDownloadIcons(_files, 'act', a.id);
    return `<div class="proof-sublist-item" style="display:flex;align-items:center;gap:4px;cursor:${cursorStyle}" ${clickHandler}>
      ${relBadge}
      <span style="flex:1;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(a.title || '')}</span>
      ${inDossBadge}
      ${_caTypeLabel ? `<span class="tree-badge tree-badge-neutral" style="font-size:9px;flex-shrink:0">${esc(_caTypeLabel)}</span>` : ''}
      ${unlinkBtn}
      ${_dlIcons}
    </div>`;
  }).join('');
  return `<div class="fact-item-proofs-row"><div class="proof-sublist-header">${t('circActsLinkedHeader')}</div>${items}</div>`;
}

// Costruisce un gruppo di icone "scarica file" (una per ciascun file
// allegato a una prova o a un atto), da apporre all'estrema destra delle
// card sublist nel modale Analisi fatto.
// - files: array di entityFile records (può essere undefined/vuoto -> '').
// - kind: 'proof' | 'act' (solo per data-testid).
// - parentId: id dell'entita (proof.id / act.id), per data-testid.
// L'estensione del file si ricava dal nome per il title; il click ha
// event.stopPropagation per evitare di aprire il dettaglio della card.
function _renderEntityFileDownloadIcons(files, kind, parentId) {
  if (!files || files.length === 0) return '';
  // Filtra record malformati (null/undefined/id non finito): IndexedDB
  // locale puo` contenere dati inconsistenti dopo import/migrazioni e un
  // singolo record sporco non deve rompere il render dell'intera card.
  // Ordinamento stabile per id crescente (icone in posizione costante
  // tra rerender successivi).
  const _safe = files
    .filter(f => f && Number.isFinite(Number(f.id)))
    .slice()
    .sort((a, b) => Number(a.id) - Number(b.id));
  if (_safe.length === 0) return '';
  return `<span class="proof-file-dl-group" style="display:inline-flex;align-items:center;gap:1px;flex-shrink:0;margin-left:auto">` +
    _safe.map(f => {
      const _name = (f.fileName != null && f.fileName !== '') ? String(f.fileName) : ('file_' + f.id);
      const _ext = _name.includes('.') ? _name.split('.').pop().toLowerCase() : '';
      const _isPdf = _ext === 'pdf';
      const _color = _isPdf ? '#b91c1c' : '#1d4ed8';
      return `<button class="proof-file-dl-mini" onclick="event.stopPropagation();downloadFile(${f.id})" data-testid="button-dl-${kind}-${parentId}-file-${f.id}" title="${esc(_name)}" style="background:transparent;border:none;cursor:pointer;padding:0 2px;font-size:12px;line-height:1;color:${_color}">⬇</button>`;
    }).join('') +
  `</span>`;
}

function _renderDossiersSublist(dossiers, unlinkOpts, rels) {
  if (!dossiers || dossiers.length === 0) return '';
  const items = dossiers.map((d, idx) => {
    const rel = rels && rels[idx];
    let relBadge = '';
    if (rel?.relationType) {
      const labelFn = unlinkOpts?.type === 'circDossier' ? tCircProofRelType : tProofRelType;
      const relCls = rel.relationType === 'confirms' ? 'tree-badge-confirm' : rel.relationType === 'contradicts' ? 'tree-badge-deny' : 'tree-badge-neutral';
      relBadge = `<span class="tree-badge ${relCls}" style="font-size:9px">${labelFn(rel.relationType)}</span>`;
    }
    const relId = rel?.id || 0;
    let unlinkBtn = '';
    if (_proofEditActive && unlinkOpts) {
      if (unlinkOpts.type === 'circDossier') {
        unlinkBtn = `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkDossierFromCircumstance(${relId}, ${unlinkOpts.factId})" data-testid="button-unlink-circ-dossier-${d.id}" title="${t('fascUnlink')}">✂</button>`;
      }
    }
    return `<div class="proof-sublist-item" style="display:flex;align-items:center;gap:4px"><span>📁</span>${relBadge}<span class="proof-sublist-title" style="flex:1;cursor:pointer;text-decoration:none" onmouseover="this.style.textDecoration='underline'" onmouseout="this.style.textDecoration='none'" onclick="event.stopPropagation();_openFascConsultaModal(${d.id})" data-testid="button-fasc-title-${d.id}">${esc(d.title || '')}</span>${unlinkBtn}</div>`;
  }).join('');
  if (unlinkOpts?.bare) return items;
  if (unlinkOpts?.indented) return `<div style="padding-left:12px"><div class="proof-sublist-header" style="font-size:9px;color:var(--text-muted)">${t('fascLinkedDossiers')}</div>${items}</div>`;
  return `<div class="fact-item-proofs-row"><div class="proof-sublist-header">${t('fascLinkedDossiers')}</div>${items}</div>`;
}

async function _unlinkDossierFromFact(relId, factId) {
  await DB.deleteFactDossierRelation(relId);
  if (_factAnalysisSelectedId) await _updateFactAnalysisColumns(_factAnalysisSelectedId);
}

async function _unlinkDossierFromCircumstance(relId, factId) {
  await DB.deleteCircumstanceDossierRelation(relId);
  if (_factAnalysisSelectedId) await _updateFactAnalysisColumns(_factAnalysisSelectedId);
}

function _renderProofsSublist(proofs, unlinkOpts, rels, fromDossierFlags, filesById) {
  if (!proofs || proofs.length === 0) return '';
  const mtLabels = { document: t('mediaDocument'), image: t('mediaImage'), audio: t('mediaAudio'), video: t('mediaVideo'), pec: t('mediaPec') };
  const items = proofs.map((pr, idx) => {
    const mt = pr.mediaType || 'document';
    let unlinkBtn = '';
    if (_proofEditActive && unlinkOpts) {
      if (unlinkOpts.type === 'actProof') {
        unlinkBtn = `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkProofFromAct(${pr.id},${unlinkOpts.parentId})" data-testid="button-unlink-act-proof-${pr.id}" title="${t('unlink')}">✂</button>`;
      } else if (unlinkOpts.type === 'factProof') {
        unlinkBtn = `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkProofFromFact(${pr.id},${unlinkOpts.parentId})" data-testid="button-unlink-fact-proof-${pr.id}" title="${t('unlink')}">✂</button>`;
      } else if (unlinkOpts.type === 'circProof') {
        unlinkBtn = `<button class="btn-unlink" onclick="event.stopPropagation();_unlinkProofFromCircumstance(${pr.id},${unlinkOpts.parentId},${unlinkOpts.factId})" data-testid="button-unlink-circ-proof-${pr.id}" title="${t('unlink')}">✂</button>`;
      }
    }
    const rel = rels && rels[idx];
    let relBadge = '';
    if (rel?.relationType) {
      let labelFn = tProofRelType;
      if (unlinkOpts?.type === 'actProof') labelFn = tActProofRelType;
      else if (unlinkOpts?.type === 'circProof') labelFn = tCircProofRelType;
      const relCls = (rel.relationType === 'confirms' || rel.relationType === 'supports' || rel.relationType === 'cita_a_supporto') ? 'tree-badge-confirm' : (rel.relationType === 'contradicts' || rel.relationType === 'cita_a_contrario') ? 'tree-badge-deny' : 'tree-badge-neutral';
      relBadge = `<span class="tree-badge ${relCls}" style="font-size:9px">${labelFn(rel.relationType)}</span>`;
    }
    const relTypeVal = rel?.relationType || 'confirms';
    const clickAttr = (!_isMemoContext || unlinkOpts?.type !== 'circProof')
      ? `onclick="event.stopPropagation(); openViewProofModal(${pr.id}, '${relTypeVal}')"`
      : '';
    const inDossBadge = (fromDossierFlags && idx < fromDossierFlags.length) ? _renderProvenienzaBadge(fromDossierFlags[idx]) : '';
    // Icone download: presenti sulle card prove del fatto, assenti
    // sulle card circostanza (unlinkOpts.type === 'circProof').
    const _files = filesById && filesById[pr.id];
    const _dlIcons = (unlinkOpts && (unlinkOpts.type === 'circProof' || unlinkOpts.type === 'factProof')) ? '' : _renderEntityFileDownloadIcons(_files, 'proof', pr.id);
    return `<div class="proof-sublist-item" style="display:flex;align-items:center;gap:4px;${clickAttr ? 'cursor:pointer' : ''}" ${clickAttr}>${relBadge}<span class="proof-sublist-title" style="flex:1">${esc(pr.title || '')}</span>${inDossBadge}<span class="tree-badge tree-badge-neutral" style="font-size:9px;flex-shrink:0">${mtLabels[mt] || t('mediaDocument')}</span>${unlinkBtn}${_dlIcons}</div>`;
  }).join('');
  if (unlinkOpts?.noWrapper) return items;
  return `<div class="fact-item-proofs-row"><div class="proof-sublist-header">${t('linkedProofsHeader')}</div>${items}</div>`;
}

function _renderTipoProveSection(proofsHtml, dossiersHtml) {
  if (!proofsHtml && !dossiersHtml) return '';
  return `<div class="fact-item-proofs-row"><div class="proof-sublist-header">${t('tipoProveCollegate')}</div>${proofsHtml || ''}${dossiersHtml || ''}</div>`;
}

function _renderNormsSublist(normaRels, opts, subjectLinksMap) {
  const addBtn = '';
  if (!normaRels || normaRels.length === 0) {
    if (!_proofEditActive) return '';
    return `<div class="fact-item-proofs-row sublist-danger"><div class="proof-sublist-header">${t('circumstanceNormsHeader')}${addBtn}</div></div>`;
  }

  const groups = {};
  for (const nr of normaRels) {
    const links = subjectLinksMap ? (subjectLinksMap[nr.id] || []) : [];
    let unlinkBtn = '';
    if (_proofEditActive && opts && opts.circId) {
      unlinkBtn = `<button class="btn-unlink" onclick="event.stopPropagation();_removeCircumstanceNorm(${nr.id},${opts.circId},${opts.factId})" data-testid="button-unlink-circ-norm-${nr.id}" title="${t('unlink')}">✂</button>`;
    }
    const _circTipo = opts && opts.circTipo;
    const _circTipoBadge = (_circTipo === 'aggravante' || _circTipo === 'attenuante')
      ? `<span class="tree-badge tree-badge-neutral" style="font-size:9px;flex-shrink:0">${t('circumstance' + _circTipo.charAt(0).toUpperCase() + _circTipo.slice(1))}</span>`
      : '';
    const _rif = nr.riferimento || '';
    const _rifHtml = _proofEditActive
      ? `<input type="text" class="norm-rif-input" placeholder="${esc(t('normRifPlaceholder'))}" value="${esc(_rif)}" onclick="event.stopPropagation()" onchange="_saveCircNormRiferimento(${nr.id}, this.value, ${opts && opts.factId ? opts.factId : 'null'})" data-testid="input-circ-norm-rif-${nr.id}" title="${esc(t('normRifTitle'))}" style="width:110px;font-size:10px;padding:1px 4px;border:1px solid #d1d5db;border-radius:3px;flex-shrink:0" />`
      : (_rif ? `<span class="norm-rif-display" style="font-size:10px;color:#6b7280;flex-shrink:0">${esc(t('normRifPrefix'))} ${esc(_rif)}</span>` : '');
    const itemHtml = `<div class="proof-sublist-item" style="display:flex;align-items:center;gap:4px;cursor:pointer;flex-wrap:wrap" onclick="event.stopPropagation(); _viewCircumstanceNorm(${nr.normaId})">
      <span class="viol-norm-placeholder" data-nid="${nr.normaId}" data-code="${esc(String(nr.normaCode || ''))}" data-etype="circNorm" data-eid="${nr.id}"><span class="tree-badge tree-badge-neutral" style="font-size:9px">art.&#160;${esc(nr.normaCode || '')}</span></span>
      <span class="proof-sublist-title" style="flex:1">${esc(nr.normaTitle || '')}</span>
      ${_rifHtml}
      ${_circTipoBadge}
      ${unlinkBtn}
    </div>`;
    if (links.length === 0) {
      const key = '__none__';
      if (!groups[key]) groups[key] = { label: t('violationSubjectNone'), items: [], sortKey: 'zzz' };
      groups[key].items.push(itemHtml);
    } else {
      for (const link of links) {
        const name = [link.subject?.firstName, link.subject?.lastName].filter(Boolean).join(' ') || `#${link.subjectId}`;
        const roleLabel = link.roleCode ? tRole(link.roleCode) : null;
        const label = roleLabel ? `${name} — ${roleLabel}` : name;
        const key = `${link.subjectId}:${link.roleId || 0}`;
        if (!groups[key]) groups[key] = { label, items: [], sortKey: label };
        if (!groups[key].items.includes(itemHtml)) groups[key].items.push(itemHtml);
      }
    }
  }

  const namedKeys = Object.keys(groups).filter(k => k !== '__none__').sort((a,b) => groups[a].sortKey.localeCompare(groups[b].sortKey));
  const hasSubjects = namedKeys.length > 0;

  if (!hasSubjects) {
    const flatItems = (groups['__none__']?.items || []).join('');
    return `<div class="fact-item-proofs-row sublist-danger"><div class="proof-sublist-header">${t('circumstanceNormsHeader')}${addBtn}</div>${flatItems}</div>`;
  }

  if (groups['__none__']) namedKeys.push('__none__');
  let groupsHtml = '';
  for (const key of namedKeys) {
    const g = groups[key];
    const isNone = key === '__none__';
    groupsHtml += `<div class="viol-subject-group">
      <div class="viol-subject-group-header">${isNone ? '⚠️' : '👤'} ${esc(g.label)}</div>
      ${g.items.join('')}
    </div>`;
  }
  return `<div class="fact-item-proofs-row sublist-danger"><div class="proof-sublist-header">${t('circumstanceNormsHeader')}${addBtn}</div>${groupsHtml}</div>`;
}

async function _renderViolationsSublist(violations, factId, opts) {
  const _hideHeader = !!(opts && opts.hideHeader);
  const _hideGroupIcon = !!(opts && opts.hideGroupIcon);
  const _hideUnlink = !!(opts && opts.hideUnlink);
  const _headerHtml = _hideHeader ? '' : `<div class="proof-sublist-header">${t('factViolationsHeader')}</div>`;
  const addBtn = '';
  if (!violations || violations.length === 0) {
    if (!_proofEditActive) return '';
    return `<div class="fact-item-proofs-row sublist-danger">${_headerHtml}${addBtn}</div>`;
  }
  const _factForPresc = await DB.getFact(factId);
  const _factDate = _factForPresc ? _factForPresc.factDate : null;
  const groups = {};
  for (const v of violations) {
    const links = await DB.getNormSubjectLinks('violation', v.id);
    if (links.length === 0) {
      const key = '__none__';
      if (!groups[key]) groups[key] = { label: t('violationSubjectNone'), violations: [], sortKey: 'zzz' };
      groups[key].violations.push(v);
    } else {
      for (const link of links) {
        const name = [link.subject?.firstName, link.subject?.lastName].filter(Boolean).join(' ') || `#${link.subjectId}`;
        const roleLabel = link.roleCode ? tRole(link.roleCode) : null;
        const label = roleLabel ? `${name} — ${roleLabel}` : name;
        const key = `${link.subjectId}:${link.roleId || 0}`;
        if (!groups[key]) groups[key] = { label, violations: [], sortKey: label };
        if (!groups[key].violations.find(gv => gv.id === v.id)) groups[key].violations.push(v);
      }
    }
  }
  const sortedKeys = Object.keys(groups).filter(k => k !== '__none__').sort((a,b) => groups[a].sortKey.localeCompare(groups[b].sortKey));
  if (groups['__none__']) sortedKeys.push('__none__');

  let groupsHtml = '';
  for (const key of sortedKeys) {
    const g = groups[key];
    const isNone = key === '__none__';
    groupsHtml += `<div class="viol-subject-group">
      <div class="viol-subject-group-header">${_hideGroupIcon ? '' : (isNone ? '⚠️ ' : '👤 ')}${esc(g.label)}</div>`;
    for (const v of g.violations) {
      let removeBtn = '';
      if (_proofEditActive && !_hideGroupIcon && !_hideUnlink) {
        removeBtn = `<button class="btn-unlink" onclick="event.stopPropagation();_removeFactCardViolation(${v.id},${factId})" data-testid="button-remove-fact-violation-${v.id}" title="${t('unlink')}">✂</button>`;
      }
      let prescBadge = '';
      if (v.normaId) {
        try {
          const _meta = await NormDB.getMetadatiPenali(v.normaId);
          const _anni = _meta ? NormDB.calcolaPrescrizione(_meta) : null;
          if (_anni && _factDate) {
            const _scad = new Date(_factDate);
            _scad.setFullYear(_scad.getFullYear() + _anni);
            const _isScad = _scad < new Date();
            const _scadStr = _scad.toLocaleDateString('it-IT', {day:'2-digit',month:'2-digit',year:'numeric'});
            prescBadge = `<span class="tree-badge ${_isScad ? 'tree-badge-deny' : 'tree-badge-confirm'}" style="font-size:8px;padding:1px 3px;flex-shrink:0" title="${t('normPrescrizioneLabel') || 'Prescrizione'}: ${_anni} ${t('years') || 'anni'}">${_isScad ? t('normPrescrizioneScaduta') : t('normPrescrizioneInCorso')} ${_scadStr}</span>`;
          } else if (_anni && !_factDate) {
            prescBadge = `<span class="tree-badge tree-badge-neutral" style="font-size:8px;padding:1px 3px;flex-shrink:0" title="${t('normPrescrizioneLabel') || 'Prescrizione'}: ${_anni} ${t('years') || 'anni'} — ${t('noFactDate') || 'data fatto mancante'}">n/a</span>`;
          }
        } catch(e) { /* skip */ }
      }
      const _vRif = v.riferimento || '';
      const _vRifHtml = _proofEditActive
        ? `<input type="text" class="norm-rif-input" placeholder="${esc(t('normRifPlaceholder'))}" value="${esc(_vRif)}" onclick="event.stopPropagation()" onchange="_saveViolationRiferimento(${v.id}, this.value, ${factId})" data-testid="input-violation-rif-${v.id}" title="${esc(t('normRifTitle'))}" style="width:110px;font-size:10px;padding:1px 4px;border:1px solid #d1d5db;border-radius:3px;flex-shrink:0" />`
        : (_vRif ? `<span class="norm-rif-display" style="font-size:10px;color:#6b7280;flex-shrink:0">${esc(t('normRifPrefix'))} ${esc(_vRif)}</span>` : '');
      groupsHtml += `<div class="proof-sublist-item" style="display:flex;align-items:center;gap:4px;cursor:pointer;flex-wrap:wrap" onclick="event.stopPropagation(); _viewCircumstanceNorm(${v.normaId})">
        <span class="viol-norm-placeholder" data-nid="${v.normaId}" data-code="${esc(String(v.normaCode || ''))}" data-etype="violation" data-eid="${v.id}"><span class="tree-badge tree-badge-neutral" style="font-size:9px">art.&#160;${esc(v.normaCode || '')}</span></span>
        <span class="proof-sublist-title" style="flex:1">${esc(v.normaTitle || '')}</span>
        ${_vRifHtml}
        ${prescBadge}
        ${removeBtn}
      </div>`;
    }
    groupsHtml += `</div>`;
  }
  return `<div class="fact-item-proofs-row sublist-danger">${_headerHtml}${groupsHtml}</div>`;
}

async function _openFactCardNormSearch(factId) {
  _openNormPickerWithSubjectPre('fact-card', factId);
}

async function _searchFactCardNorms(query, factId) {
  const resultsDiv = document.getElementById('factCardNormSearchResults');
  if (!resultsDiv) return;
  if (!query || query.length < 2) {
    resultsDiv.style.display = 'none';
    resultsDiv.innerHTML = '';
    return;
  }
  const norms = await NormDB.searchNodi(query);
  if (!norms.length) {
    resultsDiv.style.display = 'block';
    resultsDiv.innerHTML = `<div class="violation-result-empty hint">${t('noResults')}</div>`;
    return;
  }
  resultsDiv.style.display = 'block';
  const lang = currentLang;
  state._factCardNormSearchResults = {};
  const fontePromises = norms.slice(0, 20).map(n => _getFonteInfo(n.id_fonte));
  const fonteInfos = await Promise.all(fontePromises);
  resultsDiv.innerHTML = norms.slice(0, 20).map((n, i) => {
    const label = (lang === 'en' && n.rubrica_en) ? n.rubrica_en : (n.rubrica || '');
    const code = n.numero || '';
    state._factCardNormSearchResults[n.id] = { normaId: n.id, normaCode: code, normaTitle: label };
    return `<div class="violation-result-item" onclick="_openNormPreviewModal(${n.id}, 'fact-card', ${factId})" data-testid="fact-card-norm-result-${n.id}">
      ${_fonteBadgeHtml(fonteInfos[i])}
      <span class="violation-result-code">${esc(code)}</span>
      <span class="violation-result-label">${esc(label)}</span>
    </div>`;
  }).join('');
}

async function _addFactCardViolation(normaId, factId) {
  const existing = await DB.getViolationsByFact(factId);
  if (existing.find(v => v.normaId === normaId)) {
    _closeNormPreviewModal();
    const searchOverlay = document.querySelector('.fact-card-norm-search-overlay');
    if (searchOverlay) searchOverlay.remove();
    return;
  }
  let normaCode = '';
  let normaTitle = '';
  const cached = state._factCardNormSearchResults && state._factCardNormSearchResults[normaId];
  if (cached) {
    normaCode = cached.normaCode;
    normaTitle = cached.normaTitle;
  } else {
    const nodo = await NormDB.getNodo(normaId);
    if (nodo) {
      normaCode = nodo.numero || '';
      normaTitle = (currentLang === 'en' && nodo.rubrica_en) ? nodo.rubrica_en : (nodo.rubrica || '');
    }
  }
  await DB.createViolation({ factId, normaId, normaCode, normaTitle, description: '' });
  _closeNormPreviewModal();
  const searchOverlay = document.querySelector('.fact-card-norm-search-overlay');
  if (searchOverlay) searchOverlay.remove();
  if (factId) await _updateFactAnalysisColumns(factId);
}

async function _removeFactCardViolation(violationId, factId) {
  await DB.deleteViolation(violationId);
  await _updateFactAnalysisColumns(factId);
}

