function _proofDragStart(event, proofId) {
  event.dataTransfer.setData('application/proof-id', String(proofId));
  event.dataTransfer.effectAllowed = 'link';
}

let _proofReorderDraggedId = null;

function _proofReorderDragStart(event, proofId) {
  _proofReorderDraggedId = proofId;
  event.dataTransfer.setData('application/proof-reorder', String(proofId));
  event.dataTransfer.setData('application/proof-id', String(proofId));
  event.dataTransfer.effectAllowed = 'linkMove';
  event.currentTarget.classList.add('proof-reorder-dragging');
}

function _proofReorderDragEnd(event) {
  _proofReorderDraggedId = null;
  event.currentTarget.classList.remove('proof-reorder-dragging');
  document.querySelectorAll('.proof-reorder-over').forEach(el => el.classList.remove('proof-reorder-over'));
}

function _proofColumnDragOver(event) {
  const isReorder = event.dataTransfer.types.includes('application/proof-reorder');
  if (!isReorder) return;
  event.preventDefault();
  event.dataTransfer.dropEffect = 'move';
  const item = event.currentTarget;
  if (!item.classList.contains('proof-reorder-over')) {
    document.querySelectorAll('.proof-reorder-over').forEach(el => el.classList.remove('proof-reorder-over'));
    item.classList.add('proof-reorder-over');
  }
}

function _proofColumnDragLeave(event) {
  event.currentTarget.classList.remove('proof-reorder-over');
}

async function _proofColumnDrop(event, proofId, factId) {
  event.preventDefault();
  event.currentTarget.classList.remove('proof-reorder-over');

  const reorderIdStr = event.dataTransfer.getData('application/proof-reorder');
  const draggedProofId = parseInt(reorderIdStr, 10);
  if (draggedProofId && !isNaN(draggedProofId) && draggedProofId !== proofId) {
    const allCards = [...document.querySelectorAll('#factColProofsBody .fact-col-detail-item[data-proof-id]')];
    const ids = allCards.map(el => parseInt(el.dataset.proofId, 10));
    const fromIdx = ids.indexOf(draggedProofId);
    const toIdx = ids.indexOf(proofId);
    if (fromIdx !== -1 && toIdx !== -1) {
      ids.splice(fromIdx, 1);
      const insertIdx = toIdx > fromIdx ? toIdx - 1 : toIdx;
      ids.splice(insertIdx, 0, draggedProofId);
      await Promise.all(ids.map((id, i) => DB.updateProof(id, { sortOrder: i * 10 })));
      await _updateProofsColumn(factId);
    }
    return;
  }
}

function _memoProofDragStart(event, proofId) {
  event.dataTransfer.setData('application/memo-proof-id', String(proofId));
  event.dataTransfer.effectAllowed = 'link';
}

function _memoActDragStart(event, actId) {
  event.dataTransfer.setData('application/memo-act-id', String(actId));
  event.dataTransfer.effectAllowed = 'link';
}

async function _memoProofItemDrop(event, proofId, factId) {
  event.preventDefault();
  event.currentTarget.classList.remove('drag-over');
  const memoActIdStr = event.dataTransfer.getData('application/memo-act-id');
  const memoActId = parseInt(memoActIdStr, 10);
  if (!memoActId || isNaN(memoActId)) return;
  const existing = await DB.getMemoActProofRels(factId);
  if (existing.some(r => r.archivioActId === memoActId && r.archivioProofId === proofId)) {
    alert('Questo atto è già collegato alla prova.');
    return;
  }
  _showRelationTypeModal(['cita_a_supporto','cita_a_contrario','non_considera'], tActProofRelType, async (relationType) => {
    await DB.createMemoActProofRel(memoActId, proofId, relationType);
    await _updateFactAnalysisColumns(factId);
  });
}

