function _dossierDragStart(event, dossierId) {
  event.dataTransfer.setData('application/dossier-id', String(dossierId));
  event.dataTransfer.effectAllowed = 'link';
}

let _circReorderDraggedId = null;

function _circReorderDragStart(event, circId) {
  _circReorderDraggedId = circId;
  event.dataTransfer.setData('application/circ-reorder', String(circId));
  event.dataTransfer.effectAllowed = 'move';
  event.currentTarget.classList.add('circ-reorder-dragging');
}

function _circReorderDragEnd(event) {
  _circReorderDraggedId = null;
  event.currentTarget.classList.remove('circ-reorder-dragging');
  document.querySelectorAll('.circ-reorder-over').forEach(el => el.classList.remove('circ-reorder-over'));
}

function _circDragOver(event) {
  event.preventDefault();
  const isReorder = _circReorderDraggedId !== null;
  if (isReorder) {
    event.dataTransfer.dropEffect = 'move';
    const item = event.currentTarget;
    if (!item.classList.contains('circ-reorder-over')) {
      document.querySelectorAll('.circ-reorder-over').forEach(el => el.classList.remove('circ-reorder-over'));
      item.classList.add('circ-reorder-over');
    }
  } else {
    event.dataTransfer.dropEffect = 'link';
    const item = event.currentTarget;
    if (!item.classList.contains('drag-over')) item.classList.add('drag-over');
  }
}

function _circDragLeave(event) {
  event.currentTarget.classList.remove('drag-over');
  event.currentTarget.classList.remove('circ-reorder-over');
}

async function _circDrop(event, circId, factId) {
  event.preventDefault();
  event.currentTarget.classList.remove('drag-over');
  event.currentTarget.classList.remove('circ-reorder-over');

  const reorderIdStr = event.dataTransfer.getData('application/circ-reorder');
  const draggedCircId = _circReorderDraggedId || parseInt(reorderIdStr, 10);
  _circReorderDraggedId = null;
  if (draggedCircId && !isNaN(draggedCircId) && draggedCircId !== circId) {
    const allCards = [...document.querySelectorAll('#factColCircBody .fact-col-detail-item[data-circ-id]')];
    const ids = allCards.map(el => parseInt(el.dataset.circId, 10));
    const fromIdx = ids.indexOf(draggedCircId);
    const toIdx = ids.indexOf(circId);
    if (fromIdx !== -1 && toIdx !== -1) {
      ids.splice(fromIdx, 1);
      const insertIdx = toIdx > fromIdx ? toIdx - 1 : toIdx;
      ids.splice(insertIdx, 0, draggedCircId);
      await Promise.all(ids.map((id, i) => DB.updateCircumstance(id, { sortOrder: i * 10 })));
      await _updateFactAnalysisColumns(factId);
    }
    return;
  }

  if (_isMemoContext) {
    const memoProofIdStr = event.dataTransfer.getData('application/memo-proof-id');
    const memoProofId = parseInt(memoProofIdStr, 10);
    if (memoProofId && !isNaN(memoProofId)) {
      const existing = await DB.getMemoCircProofRels(factId);
      if (existing.some(r => r.archivioCircId === circId && r.archivioProofId === memoProofId)) {
        alert('Questa prova è già collegata alla circostanza.');
        return;
      }
      _showRelationTypeModal(['confirms','contradicts','describes'], tCircProofRelType, async (relationType) => {
        await DB.createMemoCircProofRel(circId, memoProofId, relationType);
        await _updateFactAnalysisColumns(factId);
      });
      return;
    }
    const memoActIdStr = event.dataTransfer.getData('application/memo-act-id');
    const memoActId = parseInt(memoActIdStr, 10);
    if (memoActId && !isNaN(memoActId)) {
      const existing = await DB.getMemoCircActRels(factId);
      if (existing.some(r => r.archivioCircId === circId && r.archivioActId === memoActId)) {
        alert('Questo atto è già collegato alla circostanza.');
        return;
      }
      _showRelationTypeModal(['afferma','contraddice','omette','travisa','non_pronuncia'], tFactPosition, async (posizioneAtto) => {
        await DB.createMemoCircActRel(circId, memoActId, posizioneAtto);
        await _updateFactAnalysisColumns(factId);
      });
    }
    return;
  }

  const proofIdStr = event.dataTransfer.getData('application/proof-id');
  const proofId = parseInt(proofIdStr, 10);
  if (proofId && !isNaN(proofId)) {
    _showRelationTypeModal(['confirms','contradicts','describes'], tCircProofRelType, async (relationType) => {
      await DB.createCircumstanceProofRelation({ circumstanceId: circId, proofId, relationType });
      await _updateFactAnalysisColumns(factId);
    });
    return;
  }
  const actIdStr = event.dataTransfer.getData('application/act-id');
  const actId = parseInt(actIdStr, 10);
  if (actId && !isNaN(actId)) {
    _showRelationTypeModal(['afferma','contraddice','omette','travisa','non_pronuncia'], tFactPosition, async (posizioneAtto) => {
      await DB.createCircumstanceActRelation({ circumstanceId: circId, actId, posizioneAtto });
      await _updateFactAnalysisColumns(factId);
    });
    return;
  }
  const dossierIdStr = event.dataTransfer.getData('application/dossier-id');
  const dossierId = parseInt(dossierIdStr, 10);
  if (dossierId && !isNaN(dossierId)) {
    _showRelationTypeModal(['confirms','contradicts','describes'], tCircProofRelType, async (relationType) => {
      await DB.createCircumstanceDossierRelation({ circumstanceId: circId, dossierId, relationType });
      await _updateFactAnalysisColumns(factId);
    });
    return;
  }
}

