async function deleteFactFromTree(factId) {
  const circumstances = await DB.getCircumstances(factId);
  const proofs = await DB.getProofs(factId);
  if (circumstances.length > 0 || proofs.length > 0) {
    alert(t('cannotDeleteFactHasLinked'));
    return;
  }
  if (!confirm(t('confirmDelete'))) return;
  if (_factAnalysisSelectedId === factId) {
    _closeFactAnalysis();
  }
  await DB.deleteFact(factId);
  state.selection = null;
  await renderAll();
}

async function showProofDetail(id) {
  const pr = await DB.getProof(id);
  if (!pr) return;
  const panel = document.getElementById('detailView');
  const factRels = await DB.getProofFactRelations(id);

  let linkedFactsHtml = '';
  if (factRels.length > 0) {
    linkedFactsHtml = `<div class="detail-field"><div class="detail-field-label">${t('entityFact')}</div><div class="detail-field-value">` +
      factRels.map(rel => {
        const f = rel.fact;
        if (!f) return '';
        const relLabel = tProofRelType(rel.relationType || 'confirms');
        const relCls = rel.relationType === 'confirms' ? 'tree-badge-confirm' : rel.relationType === 'contradicts' ? 'tree-badge-deny' : 'tree-badge-neutral';
        return `<div class="proof-link-item" onclick="selectItem('fact', ${f.id})" style="cursor:pointer">
          <span class="tree-badge ${relCls}" style="font-size:10px">${relLabel}</span>
          <span>${esc(f.title)}</span>
        </div>`;
      }).join('') + '</div></div>';
  }

  const entityFiles = await getDisplayFiles('proof', id);
  const fileHtml = renderMultiFileDisplay(entityFiles, 'proof', id);

  const dTitle = proofTitle(pr);
  const dNotes = proofNotes(pr);

  const mtLabel = pr.mediaType === 'image' ? t('mediaImage') : pr.mediaType === 'audio' ? t('mediaAudio') : pr.mediaType === 'video' ? t('mediaVideo') : t('mediaDocument');
  const mtIcon = pr.mediaType === 'image' ? '🖼️' : pr.mediaType === 'audio' ? '🎧' : pr.mediaType === 'video' ? '🎬' : '📄';

  let imgDescHtml = '';
  if (pr.mediaType === 'image' && (pr.imageDescriptionIt || pr.imageDescriptionEn)) {
    const descIt = currentLang === 'en' ? (pr.imageDescriptionEn || pr.imageDescriptionIt || '') : (pr.imageDescriptionIt || '');
    imgDescHtml = `<div class="detail-field"><div class="detail-field-label">${t('imageDescriptionIt').replace(' (IT)','')}</div><div class="detail-field-value" style="white-space:pre-wrap">${esc(descIt)}</div></div>`;
  }
  let vidDescHtml = '';
  if (pr.mediaType === 'video' && (pr.videoDescriptionIt || pr.videoDescriptionEn)) {
    const descIt = currentLang === 'en' ? (pr.videoDescriptionEn || pr.videoDescriptionIt || '') : (pr.videoDescriptionIt || '');
    vidDescHtml = `<div class="detail-field"><div class="detail-field-label">${t('videoDescriptionIt').replace(' (IT)','')}</div><div class="detail-field-value" style="white-space:pre-wrap">${esc(descIt)}</div></div>`;
  }
  let transcriptHtml = '';
  if ((pr.mediaType === 'audio' || pr.mediaType === 'video') && (pr.transcriptIt || pr.transcriptEn)) {
    const trText = currentLang === 'en' ? (pr.transcriptEn || pr.transcriptIt || '') : (pr.transcriptIt || '');
    transcriptHtml = `<div class="detail-field"><div class="detail-field-label">${t('proofTranscriptIt').replace(' IT','')}</div><div class="detail-field-value" style="white-space:pre-wrap">${esc(trText)}</div></div>`;
  }

  panel.innerHTML = `
    <div class="detail-panel">
      <div class="detail-header">
        <h2>${esc(dTitle)}${pr.protocol ? ` <span class="tree-badge tree-badge-neutral" style="font-size:10px;margin-left:8px" data-testid="text-proof-protocol">Prot. ${esc(pr.protocol)}</span>` : ''} <span class="tree-badge" style="font-size:10px;margin-left:4px" data-testid="text-proof-media-type">${mtIcon} ${mtLabel}</span></h2>
        ${pr.proofDate ? `<div class="hint" style="font-size:12px;margin-top:2px">${t('proofDate')}: ${_fmtDateShort(pr.proofDate)}${pr.proofTime ? ' — ' + pr.proofTime : ''}</div>` : (pr.proofTime ? `<div class="hint" style="font-size:12px;margin-top:2px">${t('proofTime')}: ${pr.proofTime}</div>` : '')}
        <div class="detail-header-actions">
          ${creatorOnly(`<button class="btn btn-sm" onclick="openForm('proof', null, ${id})">${t('edit')}</button>`)}
          ${creatorOnly(`<button class="btn btn-sm btn-danger" onclick="deleteEntity('proof', ${id})">${t('delete')}</button>`)}
        </div>
      </div>
      ${linkedFactsHtml}
      ${dNotes ? `<div class="detail-field"><div class="detail-field-label">${t('proofNotes')}</div><div class="detail-field-value">${esc(dNotes)}</div></div>` : ''}
      ${imgDescHtml}
      ${vidDescHtml}
      ${transcriptHtml}
      <div class="detail-section">
        <div class="detail-section-header"><h3>${t('fileSection')}</h3></div>
        ${fileHtml}
      </div>
    </div>
  `;
  showLinkedSection('proof', id);
}

/* ========== FILE HANDLING ========== */
async function _resolveFileHierarchy(entityType, parentId) {
  if (entityType === 'act' || entityType === 'fact') {
    const doss = parentId ? await DB.getDossier(parentId) : null;
    if (!doss) return { dossierId: parentId };
    const proc = doss.proceedingId ? await DB.getProceeding(doss.proceedingId) : null;
    return { caseId: proc ? proc.caseId : null, proceedingId: doss.proceedingId, dossierId: parentId };
  }
  if (entityType === 'proof') {
    const fact = parentId ? await DB.getFact(parentId) : null;
    if (!fact) return {};
    let _proofDossId = fact.dossierId || null;
    // Fallback: se il fatto non ha dossierId diretto, cerca in factDossierRelations
    // (stessa logica di buildAllegatiPath('fact') e _updateActsColumn).
    if (!_proofDossId) {
      const _fdr = await DB.getFactDossierRelations(fact.id);
      if (_fdr && _fdr.length > 0) _proofDossId = _fdr[0].dossierId;
    }
    if (!_proofDossId) return {};
    const doss = await DB.getDossier(_proofDossId);
    if (!doss) return { dossierId: _proofDossId };
    const proc = doss.proceedingId ? await DB.getProceeding(doss.proceedingId) : null;
    return { caseId: proc ? proc.caseId : null, proceedingId: doss.proceedingId, dossierId: _proofDossId };
  }
  return {};
}

function _isZipFile(file) {
  const name = (file.name || '').toLowerCase();
  return name.endsWith('.zip') || file.type === 'application/zip' || file.type === 'application/x-zip-compressed';
}

function _isZipFileName(name) {
  return (name || '').toLowerCase().endsWith('.zip');
}

function _sanitizeFileSystemName(name) {
  if (!name) return '_file';
  const lastDot = name.lastIndexOf('.');
  const base = lastDot > 0 ? name.slice(0, lastDot) : name;
  const ext  = lastDot > 0 ? name.slice(lastDot) : '';
  const cleanBase = base
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[\\/:*?"<>|\x00-\x1f]/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_')
    .replace(/^[._]+|[. _]+$/g, '')
    .substring(0, 120) || '_file';
  const cleanExt = ext.replace(/[\\/:*?"<>|\x00-\x1f]/g, '').substring(0, 10);
  const reserved = /^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$/i;
  const safeName = reserved.test(cleanBase) ? '_' + cleanBase : cleanBase;
  return safeName + cleanExt;
}

function _guessFileType(fileName) {
  const ext = (fileName || '').split('.').pop().toLowerCase();
  const map = {
    pdf: 'application/pdf', jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png',
    gif: 'image/gif', webp: 'image/webp', doc: 'application/msword',
    docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    xls: 'application/vnd.ms-excel',
    xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    txt: 'text/plain', xml: 'application/xml', html: 'text/html', htm: 'text/html'
  };
  return map[ext] || 'application/octet-stream';
}

async function _extractAndStoreDossierZip(buf, lang, dossierId, storagePath, hierarchy, fileIdx, origBaseName, sourceFileId) {
  if (typeof JSZip === 'undefined') return;
  const h = hierarchy || {};
  const parentSegments = storagePath ? storagePath.split('/') : [];
  const idxStr = String(fileIdx || 1).padStart(3, '0');
  const basePart = origBaseName ? '_' + (origBaseName.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-zA-Z0-9_\- ]/g, '').replace(/\s+/g, '_').replace(/_+/g, '_').slice(0, 25)) : '';
  const extractFolder = 'EXT_' + (lang || 'it').toUpperCase() + idxStr + basePart;
  const extractSegments = [...parentSegments, extractFolder];
  try {
    const zip = await JSZip.loadAsync(buf);
    let extractDir = null;
    if (FS_FILES_HANDLE && parentSegments.length > 0) {
      try { extractDir = await _getOrCreateNestedDir(FS_FILES_HANDLE, extractSegments); } catch (_) {}
    }
    const entries = Object.entries(zip.files).filter(([, e]) => !e.dir && e.name.split('/').pop());
    for (let i = 0; i < entries.length; i++) {
      const [path, zipEntry] = entries[i];
      const rawFileName = path.split('/').pop();
      if (!rawFileName) continue;
      const safeDiskName = _sanitizeFileSystemName(rawFileName);
      const fileArrayBuf = await zipEntry.async('arraybuffer');
      const hashBuf = await crypto.subtle.digest('SHA-256', fileArrayBuf);
      const fHash = Array.from(new Uint8Array(hashBuf)).map(b => b.toString(16).padStart(2, '0')).join('');
      let fStoragePath = '';
      let fDiskFileName = safeDiskName;
      let savedToDisk = false;
      if (extractDir) {
        try {
          const fh = await extractDir.getFileHandle(safeDiskName, { create: true });
          const wr = await fh.createWritable();
          await wr.write(fileArrayBuf);
          await wr.close();
          fStoragePath = extractSegments.join('/');
          savedToDisk = true;
        } catch (e) {
          console.warn('_extractAndStoreDossierZip: write failed for', safeDiskName, e);
        }
      }
      // Persistenza obbligatoria sul disco: se l'estrazione del file
      // dallo ZIP del fascicolo fallisce, NON salviamo il blob nel
      // database (comportamento legacy abolito su richiesta utente:
      // i file fisici devono vivere solo nella cartella collegata).
      if (!savedToDisk) {
        console.warn('_extractAndStoreDossierZip: skipping DB record for', rawFileName, '- file not written to disk');
        continue;
      }
      const blobToStore = null;
      await DB.createFile({
        entityType: 'dossier',
        entityId: dossierId,
        lang,
        actId: 0,
        caseId: h.caseId || null,
        proceedingId: h.proceedingId || null,
        dossierId,
        fileName: rawFileName,
        fileSize: fileArrayBuf.byteLength,
        fileType: _guessFileType(rawFileName),
        hash: fHash,
        storagePath: fStoragePath,
        diskFileName: fDiskFileName,
        blob: blobToStore,
        fileRole: 'doss_extract',
        sourceFileId: sourceFileId || null,
        createdAt: (zipEntry.date && zipEntry.date instanceof Date && zipEntry.date.getTime() > 0) ? zipEntry.date.getTime() : Date.now()
      });
      if (i % 5 === 4) await new Promise(r => setTimeout(r, 0));
    }
  } catch (e) {
    console.error('_extractAndStoreDossierZip error:', e);
  }
}

/* ===== FILE DATE EXTRACTION FROM INTERNAL METADATA ===== */
async function _extractDateJpeg(file) {
  try {
    const buf = await file.slice(0, 65536).arrayBuffer();
    const view = new DataView(buf);
    if (view.getUint16(0) !== 0xFFD8) return null;
    let pos = 2;
    while (pos < view.byteLength - 4) {
      const marker = view.getUint16(pos);
      const segLen = view.getUint16(pos + 2);
      if (marker === 0xFFE1) {
        const hdr = String.fromCharCode(view.getUint8(pos+4), view.getUint8(pos+5), view.getUint8(pos+6), view.getUint8(pos+7));
        if (hdr === 'Exif') {
          const text = new TextDecoder('latin1').decode(buf.slice(pos + 4, pos + 2 + segLen));
          for (const m of text.matchAll(/(\d{4}):(\d{2}):(\d{2}) (\d{2}):(\d{2}):(\d{2})/g)) {
            const yr = +m[1];
            if (yr < 1990 || yr > 2100) continue;
            const d = new Date(yr, +m[2]-1, +m[3], +m[4], +m[5], +m[6]);
            if (!isNaN(d.getTime())) return d.getTime();
          }
        }
      }
      if ((marker & 0xFF00) !== 0xFF00 || marker === 0xFFDA || segLen < 2) break;
      pos += 2 + segLen;
    }
  } catch (e) {}
  return null;
}

function _findMvhdDate(buf) {
  const MAC_OFFSET = 2082844800;
  const bytes = new Uint8Array(buf);
  const view = new DataView(buf);
  for (let i = 0; i < bytes.length - 24; i++) {
    if (bytes[i]===0x6D && bytes[i+1]===0x76 && bytes[i+2]===0x68 && bytes[i+3]===0x64) {
      const version = view.getUint8(i + 4);
      let ts;
      if (version === 1) {
        const hi = view.getUint32(i + 8, false);
        const lo = view.getUint32(i + 12, false);
        ts = hi * 4294967296 + lo;
      } else {
        ts = view.getUint32(i + 8, false);
      }
      if (ts > MAC_OFFSET && ts < MAC_OFFSET + 4102444800) return (ts - MAC_OFFSET) * 1000;
    }
  }
  return null;
}

async function _extractDateMp4(file) {
  try {
    const CHUNK = 524288;
    // 1) Primi 512KB — moov all'inizio (file ottimizzati per streaming)
    const head = await file.slice(0, CHUNK).arrayBuffer();
    const r1 = _findMvhdDate(head);
    if (r1) return r1;
    // 2) Ultimi 512KB — moov alla fine (file grezzi da fotocamera/recorder)
    if (file.size > CHUNK) {
      const tailStart = Math.max(CHUNK, file.size - CHUNK);
      const tail = await file.slice(tailStart).arrayBuffer();
      const r2 = _findMvhdDate(tail);
      if (r2) return r2;
    }
  } catch (e) {}
  return null;
}

async function _extractDatePdf(file) {
  try {
    const buf = await file.slice(0, 65536).arrayBuffer();
    const text = new TextDecoder('latin1').decode(buf);
    const m = text.match(/\/CreationDate\s*\(D:(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})/);
    if (m && +m[1] > 1990) {
      const d = new Date(+m[1], +m[2]-1, +m[3], +m[4], +m[5], +m[6]);
      if (!isNaN(d.getTime())) return d.getTime();
    }
  } catch (e) {}
  return null;
}

async function _extractDateOoxml(file) {
  try {
    if (typeof JSZip === 'undefined') return null;
    const zip = await JSZip.loadAsync(await file.arrayBuffer());
    const core = zip.file('docProps/core.xml');
    if (!core) return null;
    const xml = await core.async('string');
    const m = xml.match(/<dcterms:created[^>]*>([^<]+)<\/dcterms:created>/);
    if (m) {
      const d = new Date(m[1].trim());
      if (!isNaN(d.getTime())) return d.getTime();
    }
  } catch (e) {}
  return null;
}

async function _extractDateMp3(file) {
  try {
    const buf = await file.slice(0, 4096).arrayBuffer();
    const bytes = new Uint8Array(buf);
    if (bytes[0] !== 0x49 || bytes[1] !== 0x44 || bytes[2] !== 0x33) return null;
    const view = new DataView(buf);
    const id3Size = ((bytes[6]&0x7F)<<21)|((bytes[7]&0x7F)<<14)|((bytes[8]&0x7F)<<7)|(bytes[9]&0x7F);
    let offset = 10;
    const end = Math.min(offset + id3Size, buf.byteLength - 10);
    while (offset < end) {
      const frameId = String.fromCharCode(bytes[offset], bytes[offset+1], bytes[offset+2], bytes[offset+3]);
      if (frameId === '\0\0\0\0') break;
      const frameSize = view.getUint32(offset + 4, false);
      if (frameSize <= 0 || frameSize > 4000) break;
      if (frameId === 'TDRC' || frameId === 'TYER') {
        const enc = bytes[offset + 10];
        const text = new TextDecoder(enc === 1 || enc === 2 ? 'utf-16' : 'latin1')
          .decode(buf.slice(offset + 11, offset + 10 + frameSize)).replace(/\0/g, '').trim();
        const d = new Date(text);
        if (!isNaN(d.getTime()) && d.getFullYear() > 1900) return d.getTime();
        const yr = parseInt(text.slice(0, 4));
        if (yr > 1900 && yr < 2100) return new Date(yr, 0, 1).getTime();
      }
      offset += 10 + frameSize;
    }
  } catch (e) {}
  return null;
}

/* ===== DEVICE INFO EXTRACTION ===== */
async function _extractDeviceJpeg(file) {
  try {
    const buf = await file.slice(0, 65536).arrayBuffer();
    const view = new DataView(buf);
    if (view.getUint16(0) !== 0xFFD8) return null;
    let pos = 2;
    while (pos < view.byteLength - 4) {
      const marker = view.getUint16(pos);
      const segLen = view.getUint16(pos + 2);
      if (marker === 0xFFE1) {
        const hdr = String.fromCharCode(view.getUint8(pos+4),view.getUint8(pos+5),view.getUint8(pos+6),view.getUint8(pos+7));
        if (hdr === 'Exif') {
          const exifBase = pos + 10;
          const ev = new DataView(buf, exifBase);
          const le = ev.getUint16(0) === 0x4949;
          const ifdOff = ev.getUint32(4, le);
          const nEntries = ev.getUint16(ifdOff, le);
          const readExifStr = (e) => {
            const count = ev.getUint32(e + 4, le);
            let str = '';
            if (count <= 4) {
              for (let j = 0; j < Math.min(count - 1, 4); j++) str += String.fromCharCode(ev.getUint8(e + 8 + j));
            } else {
              const off = ev.getUint32(e + 8, le);
              for (let j = 0; j < count - 1 && off + j < ev.byteLength; j++) str += String.fromCharCode(ev.getUint8(off + j));
            }
            return str.replace(/\0/g, '').trim();
          };
          let make = '', model = '', serial = '';
          // IFD0
          for (let i = 0; i < nEntries; i++) {
            const e = ifdOff + 2 + i * 12;
            if (e + 12 > ev.byteLength) break;
            const tag = ev.getUint16(e, le);
            if (tag === 0x010F) make = readExifStr(e);           // Make
            else if (tag === 0x0110) model = readExifStr(e);      // Model
            else if (tag === 0xA431) serial = readExifStr(e);     // BodySerialNumber (EXIF 2.3)
            else if (tag === 0xC62F && !serial) serial = readExifStr(e); // CameraSerialNumber (DNG)
          }
          // SubIFD (ExifIFD pointer a tag 0x8769)
          for (let i = 0; i < nEntries; i++) {
            const e = ifdOff + 2 + i * 12;
            if (e + 12 > ev.byteLength) break;
            if (ev.getUint16(e, le) !== 0x8769) continue;
            const subOff = ev.getUint32(e + 8, le);
            const subN = ev.getUint16(subOff, le);
            for (let k = 0; k < subN; k++) {
              const se = subOff + 2 + k * 12;
              if (se + 12 > ev.byteLength) break;
              const stag = ev.getUint16(se, le);
              if (stag === 0xA431 && !serial) serial = readExifStr(se); // BodySerialNumber in SubIFD
              else if (stag === 0xC62F && !serial) serial = readExifStr(se);
            }
            break;
          }
          const device = (make && model && !model.startsWith(make)) ? `${make} ${model}` : (model || make);
          return { device: device || null, serial: serial || null };
        }
      }
      if ((marker & 0xFF00) !== 0xFF00 || marker === 0xFFDA || segLen < 2) break;
      pos += 2 + segLen;
    }
  } catch (e) {}
  return { device: null, serial: null };
}

async function _extractDeviceMp4(file) {
  try {
    const CHUNK = 524288;
    const headBuf = await file.slice(0, CHUNK).arrayBuffer();
    const tailBuf = file.size > CHUNK ? await file.slice(Math.max(CHUNK, file.size - CHUNK)).arrayBuffer() : null;
    const totalLen = headBuf.byteLength + (tailBuf ? tailBuf.byteLength : 0);
    const combined = new Uint8Array(totalLen);
    combined.set(new Uint8Array(headBuf), 0);
    if (tailBuf) combined.set(new Uint8Array(tailBuf), headBuf.byteLength);
    const bytes = combined;
    const view = new DataView(combined.buffer);

    const info = { manufacturer: '', model: '', os: '', extra: '', serial: '' };
    const readStr = (start, len) => {
      let s = '';
      for (let j = 0; j < len && start + j < bytes.length; j++) {
        const c = bytes[start + j];
        if (c >= 0x20 && c < 0x7F) s += String.fromCharCode(c);
      }
      return s.replace(/\0/g, '').trim();
    };

    // 1) Firme box proprietarie → deduzione produttore
    // Samsung: smrd, smta, smDH, smDS (prefisso 'sm' = 0x73 0x6D)
    // GoPro: GoPr, GPMF
    // Panasonic: PANA, leic (Leica/Panasonic)
    // DJI: DJMD, djmd
    // Sony: SonY, SOMC
    // Canon: CNTH, CNCV, CNDA
    // Nikon: NKGI, ncdt
    // Huawei: HW__, hwum
    const BOX4 = { GoPr:'GoPro', GPMF:'GoPro', Pana:'Panasonic', PANA:'Panasonic', LEIC:'Leica',
                   DJMD:'DJI', djmd:'DJI', SonY:'Sony', SOMC:'Sony', CNTH:'Canon', CNCV:'Canon',
                   CNDA:'Canon', NKGI:'Nikon', ncdt:'Nikon', HW__:'Huawei', hwum:'Huawei' };
    for (let i = 4; i < bytes.length - 8 && !info.manufacturer; i++) {
      const tag = String.fromCharCode(bytes[i],bytes[i+1],bytes[i+2],bytes[i+3]);
      if (BOX4[tag]) { info.manufacturer = BOX4[tag]; break; }
      // Prefisso 2 caratteri: sm* → Samsung
      if (bytes[i]===0x73 && bytes[i+1]===0x6D) {
        info.manufacturer = 'Samsung';
        if (bytes[i+2]===0x72 && bytes[i+3]===0x64) { // smrd: codice dispositivo
          const sz = view.getUint32(i - 4);
          if (sz >= 8 && sz <= 256) { const v = readStr(i + 4, sz - 8); if (v) info.extra = v; }
        }
        break;
      }
    }

    // 2) QuickTime keys/ilst — chiavi note di tutti i produttori
    // Namespace noti: com.apple.quicktime.*, com.android.*, com.huawei.*,
    //                 com.dji.*, com.sony.*, com.lg.*, com.xiaomi.*, com.oppo.*,
    //                 com.oneplus.*, com.vivo.*, com.motorola.*, com.nokia.*
    const NS_MFR = {
      'com.apple.quicktime': 'Apple', 'com.apple': 'Apple',
      'com.huawei': 'Huawei', 'com.honor': 'Honor',
      'com.dji': 'DJI',
      'com.sony': 'Sony',
      'com.lg': 'LG',
      'com.xiaomi': 'Xiaomi', 'com.miui': 'Xiaomi',
      'com.oppo': 'OPPO', 'com.coloros': 'OPPO',
      'com.oneplus': 'OnePlus',
      'com.vivo': 'vivo',
      'com.motorola': 'Motorola', 'com.moto': 'Motorola',
      'com.nokia': 'Nokia',
      'com.gopro': 'GoPro',
      'com.samsung': 'Samsung',
    };
    for (let i = 4; i < bytes.length - 8; i++) {
      if (bytes[i]!==0x6B||bytes[i+1]!==0x65||bytes[i+2]!==0x79||bytes[i+3]!==0x73) continue;
      const boxSize = view.getUint32(i - 4);
      if (boxSize < 16 || boxSize > 65536) continue;
      const keyCount = view.getUint32(i + 8);
      if (keyCount === 0 || keyCount > 100) continue;
      const keyMap = {};
      let kOff = i + 12;
      for (let k = 0; k < keyCount; k++) {
        if (kOff + 8 > bytes.length) break;
        const kSize = view.getUint32(kOff);
        if (kSize < 8 || kOff + kSize > bytes.length) break;
        let ks = '';
        for (let j = 8; j < kSize; j++) ks += String.fromCharCode(bytes[kOff + j]);
        keyMap[k + 1] = ks.replace(/\0/g, '').toLowerCase();
        kOff += kSize;
      }
      for (let j = Math.max(4, i - 300); j < Math.min(bytes.length - 8, i + boxSize + 600); j++) {
        if (bytes[j]!==0x69||bytes[j+1]!==0x6C||bytes[j+2]!==0x73||bytes[j+3]!==0x74) continue;
        const ilstBase = j - 4;
        const ilstSize = view.getUint32(ilstBase);
        if (ilstSize < 8 || ilstSize > 65536) continue;
        let iOff = j + 4;
        const ilstEnd = ilstBase + ilstSize;
        while (iOff + 16 < ilstEnd && iOff < bytes.length) {
          const itemSize = view.getUint32(iOff);
          if (itemSize < 16 || iOff + itemSize > bytes.length) break;
          const itemIdx = view.getUint32(iOff + 4);
          const dataOff = iOff + 8;
          if (dataOff + 16 <= bytes.length) {
            const dataSize = view.getUint32(dataOff);
            const dType = String.fromCharCode(bytes[dataOff+4],bytes[dataOff+5],bytes[dataOff+6],bytes[dataOff+7]);
            if (dType === 'data' && dataSize > 16) {
              const val = readStr(dataOff + 16, dataSize - 16);
              const key = keyMap[itemIdx] || '';
              if (val) {
                // Namespace → produttore
                if (!info.manufacturer) {
                  for (const [ns, mfr] of Object.entries(NS_MFR)) {
                    if (key.startsWith(ns)) { info.manufacturer = mfr; break; }
                  }
                }
                // Campi specifici
                if (key.includes('manufacturer') || (key.includes('make') && !key.includes('quicktime')))
                  info.manufacturer = info.manufacturer || val;
                else if (key.endsWith('.make') || key === 'com.apple.quicktime.make')
                  info.manufacturer = info.manufacturer || val;
                else if (key.includes('model') && !key.includes('color'))
                  info.model = info.model || val;
                else if (key.includes('device') && !key.includes('id'))
                  info.model = info.model || val;
                else if (key.includes('version') && val.includes('.'))
                  info.os = info.os || (key.includes('android') ? 'Android ' + val : val);
                else if (key.includes('software') || key.includes('firmware'))
                  info.os = info.os || val;
                // Numero di serie / ID univoco dispositivo
                else if (key.includes('serial') || key.includes('serialnumber') || key.includes('serial-number'))
                  info.serial = info.serial || val;
                else if ((key.includes('imei') || key.includes('unique-id') || key.includes('uniqueid')) && !info.serial)
                  info.serial = val;
              }
            }
          }
          iOff += itemSize;
        }
        break;
      }
      break;
    }

    // 3) Atomi QuickTime ©mak / ©mod / ©swr / ©ser nell'udta (0xA9 = ©)
    for (let i = 0; i < bytes.length - 8 && (!info.manufacturer || !info.model || !info.serial); i++) {
      if (bytes[i] !== 0xA9) continue;
      const tag = String.fromCharCode(bytes[i+1], bytes[i+2], bytes[i+3]);
      if (tag !== 'mak' && tag !== 'mod' && tag !== 'swr' && tag !== 'ser') continue;
      // Struttura: size(4)+©tag(4)+[size(2)+lang(2)+text] — il testo inizia a offset 12 dall'inizio box
      let s = readStr(i + 8, Math.min(64, bytes.length - i - 8));
      if (s.length > 1) {
        if (tag === 'mak' && !info.manufacturer) info.manufacturer = s;
        else if (tag === 'mod' && !info.model) info.model = s;
        else if (tag === 'swr' && !info.os) info.os = s;
        else if (tag === 'ser' && !info.serial) info.serial = s;
      }
    }

    const parts = [];
    if (info.manufacturer) parts.push(info.manufacturer);
    if (info.model && info.model !== info.manufacturer) parts.push(info.model);
    if (info.os) parts.push(info.os);
    if (info.extra) parts.push(parts.length ? '(' + info.extra + ')' : info.extra);
    const device = parts.length ? parts.join(' ') : null;
    return { device, serial: info.serial || null };
  } catch (e) {}
  return { device: null, serial: null };
}

async function _extractDeviceInfo(file) {
  try {
    const name = (file.name || '').toLowerCase();
    const type = (file.type || '').toLowerCase();
    if (name.endsWith('.jpg') || name.endsWith('.jpeg') || type.includes('jpeg')) return await _extractDeviceJpeg(file);
    if (name.endsWith('.mp4') || name.endsWith('.mov') || name.endsWith('.m4v') || type.includes('mp4') || type.includes('quicktime')) return await _extractDeviceMp4(file);
  } catch (e) {}
  return { device: null, serial: null };
}
/* ===== END DEVICE INFO EXTRACTION ===== */

async function _extractFileDate(file) {
  try {
    const name = (file.name || '').toLowerCase();
    const type = (file.type || '').toLowerCase();
    let ms = null;
    if (name.endsWith('.jpg') || name.endsWith('.jpeg') || type.includes('jpeg'))
      ms = await _extractDateJpeg(file);
    else if (name.endsWith('.mp4') || name.endsWith('.mov') || name.endsWith('.m4v') || type.includes('mp4') || type.includes('quicktime'))
      ms = await _extractDateMp4(file);
    else if (name.endsWith('.pdf') || type.includes('pdf'))
      ms = await _extractDatePdf(file);
    else if (name.endsWith('.docx') || name.endsWith('.xlsx') || name.endsWith('.pptx'))
      ms = await _extractDateOoxml(file);
    else if (name.endsWith('.mp3') || type.includes('mpeg'))
      ms = await _extractDateMp3(file);
    if (ms && ms > 0 && ms < Date.now() + 86400000 * 365) return ms;
  } catch (e) {
    console.warn('_extractFileDate:', e);
  }
  return (file.lastModified && file.lastModified > 0) ? file.lastModified : Date.now();
}
/* ===== END FILE DATE EXTRACTION ===== */

async function storeFileForEntity(file, entityType, entityId, lang, hierarchy, fileRole, extraFields) {
  let buf;
  try {
    buf = await file.arrayBuffer();
  } catch (e) {
    console.error('storeFileForEntity: cannot read file', file.name, e);
    return;
  }
  try {
    const hashBuf = await crypto.subtle.digest('SHA-256', buf);
    const hash = Array.from(new Uint8Array(hashBuf)).map(b => b.toString(16).padStart(2, '0')).join('');

    let storagePath = '';
    let diskFileName = '';

    let fileIdx = 1;
    if (entityType === 'dossier' && (fileRole === 'doss_orig' || fileRole === 'doss_cert')) {
      const existing = await DB.getEntityFiles('dossier', entityId);
      fileIdx = existing.filter(f => f.lang === lang && f.fileRole === fileRole).length + 1;
    }

    // Persistenza obbligatoria sul disco: i file allegati a una qualsiasi
    // entita` (prove, atti, fatti, fascicoli, ecc.) devono finire nella
    // cartella fisica predefinita gestita da File System Access API.
    // Se la cartella non e` collegata in questa sessione, prova a chiederla
    // automaticamente; se l'utente la nega o connectFS fallisce, il
    // salvataggio viene abortito con un alert esplicito invece di lasciare
    // il file solo come blob nel database (comportamento legacy che
    // generava confusione: il file appariva in app ma non c'era sul disco).
    if (!FS_FILES_HANDLE && typeof connectFS === 'function') {
      try { await connectFS(); } catch (_) {}
    }
    if (!FS_FILES_HANDLE) {
      alert(t('fsRequired'));
      return null;
    }
    const fsOpts = (fileRole === 'doss_orig' || fileRole === 'doss_cert') ? { fileIdx, origName: file.name } : {};
    if (extraFields && extraFields.sourceFileId) {
      // Non promuovere la prova/atto a PF/AF se il sourceFileId punta a un
      // file della STESSA entita' (derivato interno: es. PDF metadati/hash
      // di un'immagine prova esterna). hasSource = true solo per puntatori
      // a file di entita' diverse (tipicamente file del fascicolo).
      let _isExternalSrc = true;
      try {
        const _src = await DB.getFile(extraFields.sourceFileId);
        if (_src && _src.entityType === entityType && _src.entityId === entityId) _isExternalSrc = false;
      } catch (_) {}
      if (_isExternalSrc) fsOpts.hasSource = true;
    }
    if (extraFields && extraFields.attachIdx != null) fsOpts.attachIdx = extraFields.attachIdx;
    if (extraFields && extraFields.accIdx != null) fsOpts.accIdx = extraFields.accIdx;
    if (extraFields && extraFields.delIdx != null) fsOpts.delIdx = extraFields.delIdx;
    // Passa dossierId dalla hierarchy come fallback per prove/atti senza relazioni
    if (hierarchy && hierarchy.dossierId) fsOpts.dossierId = hierarchy.dossierId;
    const result = await saveFileToFS(file, entityType, entityId, lang, fileRole || null, fsOpts, buf);
    if (result) {
      storagePath = result.storagePath;
      diskFileName = result.diskFileName;
    } else {
      console.error('saveFileToFS failed for', file.name, entityType, entityId, '- aborting file persistence');
      alert(t('fsRequired'));
      return null;
    }

    const h = hierarchy || {};
    const fileData = {
      entityType,
      entityId,
      lang,
      actId: entityType === 'act' ? entityId : 0,
      caseId: h.caseId || null,
      proceedingId: h.proceedingId || null,
      dossierId: h.dossierId || null,
      fileName: file.name,
      fileSize: file.size,
      fileType: file.type || 'application/octet-stream',
      hash,
      storagePath,
      diskFileName,
      blob: storagePath ? null : new Uint8Array(buf),
      createdAt: await _extractFileDate(file),
    };
    const _di = await _extractDeviceInfo(file);
    fileData.deviceInfo = (_di && _di.device) || null;
    fileData.serialInfo = (_di && _di.serial) || null;
    if (fileRole) fileData.fileRole = fileRole;
    if (extraFields && typeof extraFields === 'object') {
      const _ef = { ...extraFields };
      delete _ef.attachIdx;
      Object.assign(fileData, _ef);
    }
    const savedFile = await DB.createFile(fileData);
    const savedFileId = savedFile && savedFile.id != null ? savedFile.id : null;

    if (entityType === 'dossier' && (fileRole === 'doss_orig' || fileRole === 'doss_cert') && _isZipFile(file)) {
      const origBaseName = file.name.replace(/\.[^/.]+$/, '');
      const _buf = buf, _lang = lang, _id = entityId, _sp = storagePath, _hier = hierarchy, _idx = fileIdx, _bn = origBaseName, _sfid = savedFileId;
      setTimeout(() => _extractAndStoreDossierZip(_buf, _lang, _id, _sp, _hier, _idx, _bn, _sfid).catch(e => console.error('ZIP extract bg error:', e)), 50);
    }
    return savedFileId;
  } catch (e) {
    console.error('storeFileForEntity: unexpected error for', file.name, entityType, entityId, e);
    return null;
  }
}

function _isPreviewable(fileType, fileName) {
  const ft = (fileType || '').toLowerCase();
  const ext = ((fileName || '').split('.').pop() || '').toLowerCase();
  if (ft.startsWith('image/') || ['jpg','jpeg','png','gif','webp','bmp','svg','tiff','tif'].includes(ext)) return 'image';
  if (ft.startsWith('video/') || ['mp4','webm','ogg','ogv','avi','mov','mkv','m4v'].includes(ext)) return 'video';
  if (ft.startsWith('audio/') || ['mp3','wav','ogg','oga','flac','aac','m4a','opus'].includes(ext)) return 'audio';
  if (ft === 'application/pdf' || ext === 'pdf') return 'pdf';
  return null;
}

async function _openFilePreviewModal(fileId) {
  const f = await DB.getFile(fileId);
  if (!f) return;
  const mediaType = _isPreviewable(f.fileType, f.fileName);
  if (!mediaType) return;
  // Modale consenso per file allegati a prove con flag sensitiveImage
  try { if (typeof _maybeConsentForFile === 'function' && !(await _maybeConsentForFile(f))) return; } catch(_){}
  let blobData = f.blob;
  if (!blobData && f.storagePath) {
    try {
      let dir = (typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) ? FS_FILES_HANDLE
              : (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) ? FS_DIR_HANDLE : null;
      if (dir) {
        const parts = f.storagePath.split('/').filter(Boolean);
        for (const part of parts) dir = await dir.getDirectoryHandle(part);
        const fh = await dir.getFileHandle(f.diskFileName || f.fileName);
        const file = await fh.getFile();
        blobData = new Uint8Array(await file.arrayBuffer());
      }
    } catch(e) { console.warn('Preview FS read error:', e); }
  }
  if (!blobData) { alert(t('previewNotAvailable')); return; }
  const rawBytes = blobData instanceof Uint8Array ? blobData : new Uint8Array(blobData);
  const mimeGuess = f.fileType && f.fileType !== 'application/octet-stream' ? f.fileType
    : mediaType === 'pdf' ? 'application/pdf'
    : mediaType === 'image' ? 'image/' + (f.fileName || '').split('.').pop().toLowerCase()
    : mediaType === 'video' ? 'video/mp4'
    : 'audio/mpeg';
  const blob = new Blob([rawBytes], { type: mimeGuess });
  const url = URL.createObjectURL(blob);
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  // z-index alto: il preview file deve restare SOPRA gli altri modali
  // che possono chiamarlo (View Proof = 10001, ecc.).
  overlay.style.cssText = 'z-index:20000';
  let mediaHtml;
  if (mediaType === 'image') {
    mediaHtml = `<div style="flex:1;min-height:0;overflow:auto;text-align:center;padding:16px;background:var(--bg-secondary);display:flex;align-items:center;justify-content:center"><img src="${url}" alt="${esc(f.fileName)}" style="max-width:100%;max-height:100%;object-fit:contain;border-radius:4px;box-shadow:0 2px 12px rgba(0,0,0,.18)"></div>`;
  } else if (mediaType === 'video') {
    mediaHtml = `<div style="flex:1;min-height:0;overflow:auto;padding:16px;background:#000;display:flex;align-items:center;justify-content:center"><video controls src="${url}" style="max-width:100%;max-height:100%;border-radius:4px;display:block;margin:auto"></video></div>`;
  } else if (mediaType === 'audio') {
    mediaHtml = `<div style="flex:1;min-height:0;padding:48px 24px;text-align:center;background:var(--bg-secondary);display:flex;flex-direction:column;align-items:center;justify-content:center"><div style="font-size:48px;margin-bottom:16px">🎵</div><p style="font-size:13px;color:var(--text-muted);margin-bottom:16px">${esc(f.fileName)}</p><audio controls src="${url}" style="width:100%;max-width:480px"></audio></div>`;
  } else if (mediaType === 'pdf') {
    mediaHtml = `
      <div style="flex:1;min-height:0;display:flex;flex-direction:column;overflow:hidden;background:var(--bg-secondary)">
        <div id="fpvPdfToolbar" style="display:flex;align-items:center;gap:8px;padding:6px 12px;background:var(--bg-primary);border-bottom:1px solid var(--border);flex-shrink:0;font-size:13px">
          <button id="fpvPdfPrev" class="btn btn-xs" data-testid="button-fpv-pdf-prev" title="${t('prevPage')||'Pagina precedente'}">&#9664;</button>
          <span id="fpvPdfCount" style="min-width:72px;text-align:center;font-variant-numeric:tabular-nums">—</span>
          <button id="fpvPdfNext" class="btn btn-xs" data-testid="button-fpv-pdf-next" title="${t('nextPage')||'Pagina successiva'}">&#9654;</button>
          <button id="fpvPdfZoomOut" class="btn btn-xs" data-testid="button-fpv-pdf-zoomout" title="Zoom −">－</button>
          <button id="fpvPdfZoomIn" class="btn btn-xs" data-testid="button-fpv-pdf-zoomin" title="Zoom +">＋</button>
          <span id="fpvPdfZoomLevel" style="font-size:11px;color:var(--text-muted);min-width:40px">100%</span>
          <div style="flex:1"></div>
          <button id="fpvPdfOpenExt" class="btn btn-xs" data-testid="button-fpv-pdf-openext" title="${t('openExternal')||'Apri in nuova finestra'}">&#8599; ${t('openExternal')||'Nuova finestra'}</button>
        </div>
        <div id="fpvPdfOuter" style="flex:1;overflow:auto;position:relative;display:flex;justify-content:center;padding:12px">
          <div style="position:relative;display:inline-block">
            <canvas id="fpvPdfCanvas" style="display:block;box-shadow:0 2px 12px rgba(0,0,0,.2)"></canvas>
            <div id="fpvPdfTextLayer" class="ft-pdf-textlayer" style="position:absolute;top:0;left:0;pointer-events:none"></div>
          </div>
        </div>
      </div>`;
  } else {
    mediaHtml = `<iframe src="${url}" style="flex:1;min-height:0;width:100%;height:100%;border:none;background:#fff;display:block"></iframe>`;
  }
  overlay.innerHTML = `
    <div class="modal-content" style="width:95vw;max-width:none;height:95vh;max-height:none;padding:0;display:flex;flex-direction:column;overflow:hidden;border-radius:10px;box-shadow:0 12px 48px rgba(0,0,0,0.35)">
      <div style="display:flex;align-items:center;gap:10px;padding:12px 16px;background:var(--bg-primary);border-bottom:2px solid var(--border);flex-shrink:0;min-height:52px">
        <span style="font-size:20px;flex-shrink:0">${mediaType==='image'?'🖼':mediaType==='video'?'🎬':mediaType==='audio'?'🎵':'📄'}</span>
        <div style="flex:1;min-width:0">
          <div style="font-weight:700;font-size:14px;color:var(--text-primary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(f.fileName)}">${esc(f.fileName)}</div>
          <div style="font-size:11px;color:var(--text-muted);margin-top:1px">${formatSize(f.fileSize)}${f.fileType ? ' · ' + esc(f.fileType) : ''}</div>
        </div>
        <div style="display:flex;align-items:center;gap:8px;flex-shrink:0">
          <button class="btn btn-primary" style="font-size:12px;padding:5px 12px;display:flex;align-items:center;gap:5px" onclick="downloadFile(${f.id})" data-testid="button-preview-download-${f.id}">⬇ ${t('download')}</button>
          <button id="filePreviewClose" data-testid="button-preview-close" style="background:none;border:1px solid var(--border);border-radius:6px;width:32px;height:32px;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;color:var(--text-primary);line-height:1">&times;</button>
        </div>
      </div>
      <div style="flex:1;min-height:0;display:flex;flex-direction:column;overflow:hidden">${mediaHtml}</div>
    </div>`;
  const close = () => { URL.revokeObjectURL(url); overlay.remove(); };
  overlay.querySelector('#filePreviewClose').onclick = close;
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  document.body.appendChild(overlay);

  // Viewer PDF canvas+text-layer con navigazione pagine
  if (mediaType === 'pdf') {
    const canvas = overlay.querySelector('#fpvPdfCanvas');
    const textLayer = overlay.querySelector('#fpvPdfTextLayer');
    const outer = overlay.querySelector('#fpvPdfOuter');
    const countEl = overlay.querySelector('#fpvPdfCount');
    const zoomEl = overlay.querySelector('#fpvPdfZoomLevel');
    let pdfDoc = null;
    let currentPage = 1;
    let userScale = 1.0; // moltiplicatore zoom utente

    async function fpvRenderPage(pn) {
      if (!pdfDoc) return;
      pn = Math.max(1, Math.min(pdfDoc.numPages, pn));
      currentPage = pn;
      if (countEl) countEl.textContent = `${pn} / ${pdfDoc.numPages}`;
      const page = await pdfDoc.getPage(pn);
      const containerWidth = (outer ? outer.clientWidth - 24 : 740) || 740;
      const unscaledVp = page.getViewport({ scale: 1 });
      const autoScale = Math.min(2.5, Math.max(0.4, (containerWidth) / unscaledVp.width));
      const scale = autoScale * userScale;
      if (zoomEl) zoomEl.textContent = Math.round(userScale * 100) + '%';
      const vp = page.getViewport({ scale });
      canvas.width = Math.round(vp.width);
      canvas.height = Math.round(vp.height);
      await page.render({ canvasContext: canvas.getContext('2d'), viewport: vp }).promise;
      textLayer.innerHTML = '';
      textLayer.style.width = canvas.width + 'px';
      textLayer.style.height = canvas.height + 'px';
      let pos = 0;
      const tc = await page.getTextContent();
      tc.items.forEach(item => {
        const str = item.str || '';
        if (!str) { pos += 1; return; }
        const [sx, ky, , sy, tx, ty] = item.transform;
        const fontSize = Math.sqrt(sx * sx + ky * ky) * scale;
        const span = document.createElement('span');
        span.className = 'ft-pdf-tl-span';
        span.style.cssText = `left:${tx*scale}px;top:${vp.height-ty*scale-fontSize}px;font-size:${Math.round(fontSize)}px;${item.width>0?'width:'+Math.round(item.width*scale)+'px;':''}`;
        span.textContent = str;
        textLayer.appendChild(span);
        pos += str.length + 1;
      });
    }

    overlay.querySelector('#fpvPdfPrev').onclick = () => fpvRenderPage(currentPage - 1);
    overlay.querySelector('#fpvPdfNext').onclick = () => fpvRenderPage(currentPage + 1);
    overlay.querySelector('#fpvPdfZoomOut').onclick = () => { userScale = Math.max(0.25, userScale - 0.25); fpvRenderPage(currentPage); };
    overlay.querySelector('#fpvPdfZoomIn').onclick  = () => { userScale = Math.min(4.0, userScale + 0.25); fpvRenderPage(currentPage); };
    overlay.querySelector('#fpvPdfOpenExt').onclick = () => {
      const extUrl = URL.createObjectURL(new Blob([rawBytes], { type: 'application/pdf' }));
      window.open(extUrl, '_blank');
      setTimeout(() => URL.revokeObjectURL(extUrl), 30000);
    };

    // Navigazione tastiera mentre il modale è aperto
    function fpvKeydown(e) {
      if (!document.body.contains(overlay)) { document.removeEventListener('keydown', fpvKeydown); return; }
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); fpvRenderPage(currentPage + 1); }
      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); fpvRenderPage(currentPage - 1); }
      else if (e.key === 'Escape') { close(); document.removeEventListener('keydown', fpvKeydown); }
    }
    document.addEventListener('keydown', fpvKeydown);
    overlay.querySelector('#filePreviewClose').addEventListener('click', () => document.removeEventListener('keydown', fpvKeydown));

    (async () => {
      try {
        if (typeof pdfjsLib === 'undefined') return;
        if (pdfjsLib.GlobalWorkerOptions) pdfjsLib.GlobalWorkerOptions.workerSrc = 'js/pdf.worker.min.js';
        pdfDoc = await pdfjsLib.getDocument({ data: rawBytes.slice(0) }).promise;
        overlay.addEventListener('remove-fpv', () => { try { pdfDoc.destroy(); } catch(_){} });
        await fpvRenderPage(1);
      } catch(e) {
        if (textLayer) textLayer.innerHTML = `<div style="padding:16px;color:red">Errore PDF: ${esc(String(e))}</div>`;
      }
    })();
  }
}

async function downloadFile(fileId) {
  const f = await DB.getFile(fileId);
  if (!f) return;
  await downloadFileFromFS(f);
}

async function _openFileMetaModal(fileId) {
  const f = await DB.getFile(fileId);
  if (!f) return;
  const _L = currentLang === 'en';
  const _dateLoc = _L ? 'en-GB' : 'it-IT';
  const dateStr = f.createdAt
    ? new Date(f.createdAt).toLocaleString(_dateLoc, { dateStyle: 'long', timeStyle: 'medium' })
    : '—';
  const rows = [
    { label: _L ? 'File name' : 'Nome file', value: f.fileName, mono: false },
    { label: _L ? 'Type' : 'Tipo MIME', value: f.fileType || '—', mono: true },
    { label: _L ? 'Size' : 'Dimensione', value: formatSize(f.fileSize), mono: false },
    { label: _L ? 'Acquisition date' : 'Data Acquisizione', value: dateStr, mono: false },
    f.deviceInfo ? { label: _L ? 'Device' : 'Dispositivo', value: f.deviceInfo, mono: false } : null,
    (f.deviceInfo && f.serialInfo) ? { label: _L ? 'Serial number' : 'Numero di serie', value: f.serialInfo, mono: true } : null,
    f.storagePath ? { label: 'File', value: f.storagePath + '/' + (f.diskFileName || f.fileName), mono: true } : null,
    f.hash ? { label: 'Hash SHA-256', value: f.hash, mono: true } : null,
  ].filter(Boolean);
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.innerHTML = `
    <div class="file-meta-modal">
      <div class="file-meta-header">
        <span>🏷️ ${_L ? 'File Metadata' : 'Metadati File'}</span>
        <button class="btn btn-sm file-meta-header-close" onclick="this.closest('.modal-overlay').remove()" data-testid="button-close-file-meta">${_L ? 'Close' : 'Chiudi'}</button>
      </div>
      <div class="file-meta-body">
        ${rows.map(r => `
          <div class="file-meta-row">
            <div class="file-meta-label">${esc(r.label)}</div>
            <div class="file-meta-value${r.mono ? ' file-meta-value-mono' : ''}">${esc(r.value)}</div>
          </div>`).join('')}
      </div>
    </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
}

async function _renameFile(fileId) {
  const f = await DB.getFile(fileId);
  if (!f) return;
  const _L = currentLang === 'en';
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  // Separa nome ed estensione per facilitare la modifica
  const dotIdx = f.fileName.lastIndexOf('.');
  const baseName = dotIdx > 0 ? f.fileName.slice(0, dotIdx) : f.fileName;
  const ext     = dotIdx > 0 ? f.fileName.slice(dotIdx) : '';
  overlay.innerHTML = `
    <div class="file-meta-modal" style="max-width:420px">
      <div class="file-meta-header">
        <span>✏️ ${_L ? 'Rename file' : 'Rinomina file'}</span>
        <button class="modal-close" onclick="this.closest('.modal-overlay').remove()" data-testid="button-close-rename">✕</button>
      </div>
      <div class="file-meta-body" style="padding:16px 20px">
        <div style="margin-bottom:10px;font-size:12px;color:var(--text-secondary)">
          ${_L ? 'Current name:' : 'Nome attuale:'} <code style="font-size:11px">${esc(f.fileName)}</code>
        </div>
        <div style="display:flex;align-items:center;gap:6px">
          <input id="_renameInput" type="text" class="form-input" value="${esc(baseName)}"
            style="flex:1;font-size:13px;padding:6px 8px"
            data-testid="input-rename-file"
            placeholder="${_L ? 'New name (without extension)' : 'Nuovo nome (senza estensione)'}" />
          <span style="font-size:13px;color:var(--text-secondary);white-space:nowrap">${esc(ext)}</span>
        </div>
      </div>
      <div class="file-meta-footer" style="gap:8px">
        <button class="btn btn-sm" onclick="this.closest('.modal-overlay').remove()" data-testid="button-cancel-rename">
          ${_L ? 'Cancel' : 'Annulla'}
        </button>
        <button class="btn btn-sm btn-primary" id="_renameSaveBtn" data-testid="button-save-rename">
          ${_L ? 'Save' : 'Salva'}
        </button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  const input = overlay.querySelector('#_renameInput');
  input.focus();
  input.select();
  const doSave = async () => {
    const newBase = (input.value || '').trim();
    if (!newBase) { input.focus(); return; }
    const newName = newBase + ext;
    let newDiskFileName = f.diskFileName;
    if (FS_FILES_HANDLE && f.storagePath) {
      try {
        const segments = f.storagePath.split('/');
        const dir = await _resolveNestedDir(FS_FILES_HANDLE, segments);
        const oldDiskName = f.diskFileName || f.fileName;
        const sanitizedNewName = _sanitizeFsName(newName);
        const oldHandle = await dir.getFileHandle(oldDiskName);
        const buf = await (await oldHandle.getFile()).arrayBuffer();
        const newHandle = await dir.getFileHandle(sanitizedNewName, { create: true });
        const writable = await newHandle.createWritable();
        await writable.write(buf);
        await writable.close();
        await dir.removeEntry(oldDiskName);
        newDiskFileName = sanitizedNewName;
      } catch (e) {
        console.warn('Rename su disco fallito:', e.message);
      }
    }
    await DB.updateFile(fileId, { fileName: newName, diskFileName: newDiskFileName });
    overlay.remove();
    await showDetail(f.entityType, f.entityId);
  };
  overlay.querySelector('#_renameSaveBtn').addEventListener('click', doSave);
  input.addEventListener('keydown', e => { if (e.key === 'Enter') doSave(); else if (e.key === 'Escape') overlay.remove(); });
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
}

async function deleteFileAndRefresh(fileId, entityType, entityId) {
  const f = await DB.getFile(fileId);
  if (!f) { await DB.deleteFile(fileId); await showDetail(entityType, entityId); return; }
  const _L = currentLang === 'en';

  const linkedCerts = await DB.getFilesByLinkedOrigId(fileId);
  const extractedChildren = await DB.getFilesBySourceId(fileId);

  const blocks = [];
  if (linkedCerts.length > 0) {
    const names = linkedCerts.map(c => esc(c.fileName)).join(', ');
    blocks.push(_L
      ? `<b>Linked certified translations (${linkedCerts.length}):</b><br><span style="font-size:12px">${names}</span>`
      : `<b>Traduzioni certificate collegate (${linkedCerts.length}):</b><br><span style="font-size:12px">${names}</span>`);
  }
  if (extractedChildren.length > 0) {
    const names = extractedChildren.map(c => esc(c.fileName)).join(', ');
    blocks.push(_L
      ? `<b>Files extracted from this archive (${extractedChildren.length}):</b><br><span style="font-size:12px">${names}</span>`
      : `<b>File estratti da questo archivio (${extractedChildren.length}):</b><br><span style="font-size:12px">${names}</span>`);
  }

  if (blocks.length > 0) {
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `
      <div class="file-meta-modal" style="max-width:460px">
        <div class="file-meta-header" style="background:var(--danger,#c0392b);color:#fff">
          <span>🔗 ${_L ? 'File linked — cannot delete' : 'File collegato — impossibile cancellare'}</span>
          <button class="modal-close" onclick="this.closest('.modal-overlay').remove()" style="color:#fff">✕</button>
        </div>
        <div class="file-meta-body" style="padding:16px 20px">
          <div style="margin-bottom:10px;font-size:13px">
            <b>${esc(f.fileName)}</b><br>
            <span style="color:var(--text-secondary);font-size:12px">${_L ? 'This file cannot be deleted because it is linked to:' : 'Questo file non può essere cancellato perché è collegato a:'}</span>
          </div>
          <div style="background:var(--bg-secondary,#f5f5f5);border-radius:6px;padding:10px 12px;font-size:13px;line-height:1.7">
            ${blocks.join('<hr style="margin:6px 0;border:none;border-top:1px solid var(--border)">')}
          </div>
          <div style="margin-top:10px;font-size:12px;color:var(--text-secondary)">
            ${_L ? 'Delete the links to this file first, then you can delete it.' : 'Elimina prima i collegamenti al file, poi potrai cancellarlo.'}
          </div>
        </div>
        <div class="file-meta-footer">
          <button class="btn btn-sm btn-primary" onclick="this.closest('.modal-overlay').remove()" data-testid="button-close-link-block">OK</button>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    overlay.addEventListener('click', (e) => { e.stopPropagation(); });
    return;
  }

  // Nessun collegamento → procedi con cancellazione normale
  if (FS_FILES_HANDLE && !f.sourceFileId) {
    await deleteFileFromFS(f);
  }
  await DB.deleteFile(fileId);
  await showDetail(entityType, entityId);
}

