/* ========== FORMS ========== */
function openForm(type, parentId, editId) {
  state.pendingFiles = { it: [], en: [] };
  state.pendingFilesOrigin = { it: [], en: [] };
  state.openForm = { type, parentId: parentId || null, editId: editId || null };
  hideAllPanels();
  document.getElementById('formView').style.display = 'block';

  if (type === 'case') showCaseForm(editId);
  else if (type === 'proceeding') showProceedingForm(parentId, editId);
  else if (type === 'dossier') showDossierForm(parentId, editId);
  else if (type === 'act') showActForm(parentId, editId);
  else if (type === 'fact') showFactForm(parentId, editId);
  else if (type === 'subject') showSubjectForm(editId);
  else if (type === 'circumstance') showCircumstanceForm(parentId, editId);
}

async function showCaseForm(editId) {
  const isEdit = !!editId;
  const existing = isEdit ? await DB.getCase(editId) : null;
  const existingFiles = isEdit ? await DB.getEntityFiles('case', editId) : [];
  const existingFileIt = existingFiles.find(f => f.lang === 'it') || null;
  const existingFileEn = existingFiles.find(f => f.lang === 'en') || null;

  let caseIdx = null;
  let _caseBadgeNum = null;
  const _allCasesForBadge = await DB.getCases();
  _allCasesForBadge.sort((a, b) => a.id - b.id);
  if (isEdit) {
    caseIdx = _allCasesForBadge.findIndex(c => c.id === editId) + 1;
    if (caseIdx > 0) _caseBadgeNum = String(caseIdx).padStart(3, '0');
  } else {
    _caseBadgeNum = String(_allCasesForBadge.length + 1).padStart(3, '0');
  }
  const _L = currentLang === 'en';
  const _caseBadge = _caseBadgeNum
    ? `<span class="tree-badge tree-badge-K" style="font-size:9px;font-weight:700;letter-spacing:0.04em;white-space:nowrap;padding:1px 6px">${_L ? 'Case' : 'Caso'} ${_caseBadgeNum}</span>`
    : '';

  const panel = document.getElementById('formView');
  const _hasSubIt = !!(existing?.subtitle || '').trim();
  const _hasSubEn = !!(existing?.subtitleEn || '').trim();
  const _hasDescIt = !!(existing?.descrIt || '').trim();
  const _hasDescEn = !!(existing?.descrEn || '').trim();
  panel.innerHTML = `
    <div class="form-panel case-form-v2">
      <div class="case-form-header">
        <div class="case-form-header-titleblock">
          <div style="display:flex;flex-direction:column;align-items:center;gap:5px;flex-shrink:0">
            ${_caseBadge}
            <span class="proc-form-icon">🏛️</span>
          </div>
          <h2 style="margin:0">${t(isEdit ? 'editCase' : 'newCase')}</h2>
        </div>
        <div class="case-form-header-actions">
          <button class="btn" onclick="cancelForm()" data-testid="button-cancel-case">${t('cancel')}</button>
          <button class="btn btn-primary" onclick="saveCase(${editId || 'null'})" data-testid="button-save-case">${t('save')}</button>
        </div>
      </div>

      <fieldset class="case-form-section">
        <legend>${t('caseSectionTitle')}</legend>
        <div class="case-title-row">
          <div class="form-group case-title-cell">
            <label>${t('caseTitleIt')} <span class="form-required">*</span></label>
            <input id="fCaseTitle" value="${esc(existing?.title || '')}" required data-testid="input-case-title-it" oninput="_caseUpdateCounter('fCaseTitle')">
            <div class="char-word-counter" id="cnt-fCaseTitle"></div>
          </div>
          <div class="case-title-arrows">
            ${_renderTransArrow('fCaseTitle','fCaseTitleEn','it','en')}
            ${_renderTransArrow('fCaseTitleEn','fCaseTitle','en','it')}
          </div>
          <div class="form-group case-title-cell">
            <label>${t('caseTitleEn')}</label>
            <input id="fCaseTitleEn" value="${esc(existing?.titleEn || '')}" data-testid="input-case-title-en" oninput="_caseUpdateCounter('fCaseTitleEn')">
            <div class="char-word-counter" id="cnt-fCaseTitleEn"></div>
          </div>
        </div>
      </fieldset>

      <fieldset class="case-form-section">
        <legend>${t('caseSectionSubnarr')}</legend>
        <div class="case-tabs-bar">
          <div class="case-tabs">
            <button type="button" class="case-tab active" data-case-tab="sub-it" onclick="_caseSwitchTab('sub','it')" data-testid="tab-case-sub-it"><span class="form-lang-badge form-lang-badge-it">IT</span> ${t('caseTabSubItShort')} <span class="case-tab-dot" id="dot-fCaseSubtitle" style="${_hasSubIt?'':'visibility:hidden'}">●</span></button>
            <button type="button" class="case-tab" data-case-tab="sub-en" onclick="_caseSwitchTab('sub','en')" data-testid="tab-case-sub-en"><span class="form-lang-badge form-lang-badge-en">EN</span> ${t('caseTabSubEnShort')} <span class="case-tab-dot" id="dot-fCaseSubtitleEn" style="${_hasSubEn?'':'visibility:hidden'}">●</span></button>
          </div>
          <button type="button" class="btn btn-xs case-translate-btn" id="btnCaseTransSub" onclick="_caseTranslateActive('sub')" data-testid="button-case-translate-sub"></button>
        </div>
        <div class="case-tab-panel active" id="pane-sub-it">
          <textarea id="fCaseSubtitle" data-rte="1" rows="4" data-testid="input-case-subtitle-it" class="case-fullwidth-textarea case-fullwidth-textarea-sm" oninput="_caseUpdateCounter('fCaseSubtitle');_caseUpdateDot('fCaseSubtitle')">${esc(existing?.subtitle || '')}</textarea>
          <div class="char-word-counter" id="cnt-fCaseSubtitle"></div>
        </div>
        <div class="case-tab-panel" id="pane-sub-en" style="display:none">
          <textarea id="fCaseSubtitleEn" data-rte="1" rows="4" data-testid="input-case-subtitle-en" class="case-fullwidth-textarea case-fullwidth-textarea-sm" oninput="_caseUpdateCounter('fCaseSubtitleEn');_caseUpdateDot('fCaseSubtitleEn')">${esc(existing?.subtitleEn || '')}</textarea>
          <div class="char-word-counter" id="cnt-fCaseSubtitleEn"></div>
        </div>
      </fieldset>

      <fieldset class="case-form-section">
        <legend>${t('caseSectionNarr')}</legend>
        <div class="case-tabs-bar">
          <div class="case-tabs">
            <button type="button" class="case-tab active" data-case-tab="desc-it" onclick="_caseSwitchTab('desc','it')" data-testid="tab-case-desc-it"><span class="form-lang-badge form-lang-badge-it">IT</span> ${t('caseTabNarrItShort')} <span class="form-required">*</span> <span class="case-tab-dot" id="dot-fCaseDescrIt" style="${_hasDescIt?'':'visibility:hidden'}">●</span></button>
            <button type="button" class="case-tab" data-case-tab="desc-en" onclick="_caseSwitchTab('desc','en')" data-testid="tab-case-desc-en"><span class="form-lang-badge form-lang-badge-en">EN</span> ${t('caseTabNarrEnShort')} <span class="case-tab-dot" id="dot-fCaseDescrEn" style="${_hasDescEn?'':'visibility:hidden'}">●</span></button>
          </div>
          <button type="button" class="btn btn-xs case-translate-btn" id="btnCaseTransDesc" onclick="_caseTranslateActive('desc')" data-testid="button-case-translate-desc"></button>
        </div>
        <div class="case-tab-panel active" id="pane-desc-it">
          <textarea id="fCaseDescrIt" data-rte="1" rows="13" required data-testid="input-case-descr-it" class="case-fullwidth-textarea" oninput="_caseUpdateCounter('fCaseDescrIt');_caseUpdateDot('fCaseDescrIt')">${esc(existing?.descrIt || '')}</textarea>
          <div class="char-word-counter" id="cnt-fCaseDescrIt"></div>
        </div>
        <div class="case-tab-panel" id="pane-desc-en" style="display:none">
          <textarea id="fCaseDescrEn" data-rte="1" rows="13" data-testid="input-case-descr-en" class="case-fullwidth-textarea" oninput="_caseUpdateCounter('fCaseDescrEn');_caseUpdateDot('fCaseDescrEn')">${esc(existing?.descrEn || '')}</textarea>
          <div class="char-word-counter" id="cnt-fCaseDescrEn"></div>
        </div>
      </fieldset>

      ${caseFileUploadZones(existingFileIt, existingFileEn, caseIdx)}
    </div>
  `;
  // Init contatori e label pulsanti traduzione
  state._caseTabState = { sub: 'it', desc: 'it' };
  ['fCaseTitle','fCaseTitleEn','fCaseSubtitle','fCaseSubtitleEn','fCaseDescrIt','fCaseDescrEn'].forEach(id => _caseUpdateCounter(id));
  _caseRefreshTransBtn('sub');
  _caseRefreshTransBtn('desc');
}

function _caseSwitchTab(group, lang) {
  if (!state._caseTabState) state._caseTabState = { sub: 'it', desc: 'it' };
  state._caseTabState[group] = lang;
  document.querySelectorAll(`.case-tab[data-case-tab^="${group}-"]`).forEach(b => {
    b.classList.toggle('active', b.dataset.caseTab === `${group}-${lang}`);
  });
  const showId = `pane-${group}-${lang}`;
  const hideId = `pane-${group}-${lang === 'it' ? 'en' : 'it'}`;
  const sh = document.getElementById(showId); if (sh) { sh.style.display = ''; sh.classList.add('active'); }
  const hd = document.getElementById(hideId); if (hd) { hd.style.display = 'none'; hd.classList.remove('active'); }
  _caseRefreshTransBtn(group);
  // Focus al campo del tab attivo
  const inp = sh && sh.querySelector('input,textarea'); if (inp) try { inp.focus(); } catch (_e) {}
}

function _caseRefreshTransBtn(group) {
  const lang = (state._caseTabState && state._caseTabState[group]) || 'it';
  const btnId = group === 'sub' ? 'btnCaseTransSub' : 'btnCaseTransDesc';
  const btn = document.getElementById(btnId);
  if (!btn) return;
  const srcId = group === 'sub' ? (lang === 'it' ? 'fCaseSubtitle' : 'fCaseSubtitleEn') : (lang === 'it' ? 'fCaseDescrIt' : 'fCaseDescrEn');
  const src = document.getElementById(srcId);
  const hasText = !!(src && src.value && src.value.trim());
  btn.disabled = !hasText;
  btn.style.opacity = hasText ? '' : '0.5';
  btn.style.cursor = hasText ? '' : 'not-allowed';
  btn.classList.remove('case-translate-to-en','case-translate-to-it');
  if (lang === 'it') {
    btn.classList.add('case-translate-to-en');
    btn.innerHTML = `→ ${t('caseTransToEn')}`;
  } else {
    btn.classList.add('case-translate-to-it');
    btn.innerHTML = `← ${t('caseTransToIt')}`;
  }
}

async function _caseTranslateActive(group) {
  const lang = (state._caseTabState && state._caseTabState[group]) || 'it';
  const btnId = group === 'sub' ? 'btnCaseTransSub' : 'btnCaseTransDesc';
  const btn = document.getElementById(btnId);
  let srcId, dstId, fromLang, toLang;
  if (group === 'sub') {
    srcId = lang === 'it' ? 'fCaseSubtitle' : 'fCaseSubtitleEn';
    dstId = lang === 'it' ? 'fCaseSubtitleEn' : 'fCaseSubtitle';
  } else {
    srcId = lang === 'it' ? 'fCaseDescrIt' : 'fCaseDescrEn';
    dstId = lang === 'it' ? 'fCaseDescrEn' : 'fCaseDescrIt';
  }
  fromLang = lang;
  toLang = lang === 'it' ? 'en' : 'it';
  if (typeof _autoTranslateField === 'function') {
    await _autoTranslateField(srcId, dstId, fromLang, toLang, btn);
    _caseUpdateCounter(dstId);
    _caseUpdateDot(dstId);
    _caseRefreshTransBtn(group);
  }
}

function _caseUpdateCounter(id) {
  const el = document.getElementById(id);
  const cnt = document.getElementById('cnt-' + id);
  if (!el || !cnt) return;
  const v = el._rteApi ? (el._rteApi.editor.innerText || '') : String(el.value || '');
  const chars = v.length;
  const words = v.trim() ? v.trim().split(/\s+/).length : 0;
  const lang = (typeof state !== 'undefined' && state.lang) ? state.lang : 'it';
  const fmt = (n) => {
    try { return new Intl.NumberFormat(lang === 'en' ? 'en-US' : 'it-IT').format(n); } catch (_e) { return String(n); }
  };
  cnt.textContent = `${fmt(chars)} ${t('charsLabel')} · ${fmt(words)} ${t('wordsLabel')}`;
  // Aggiorna anche stato pulsante traduzione se questo campo ne è sorgente
  if (id === 'fCaseSubtitle' || id === 'fCaseSubtitleEn') _caseRefreshTransBtn('sub');
  if (id === 'fCaseDescrIt' || id === 'fCaseDescrEn') _caseRefreshTransBtn('desc');
}

function _caseUpdateDot(id) {
  const el = document.getElementById(id);
  const dot = document.getElementById('dot-' + id);
  if (!el || !dot) return;
  const v = el._rteApi ? (el._rteApi.editor.innerText || '') : (el.value || '');
  dot.style.visibility = v.trim() ? 'visible' : 'hidden';
}

if (typeof window !== 'undefined') {
  window._caseSwitchTab = _caseSwitchTab;
  window._caseTranslateActive = _caseTranslateActive;
  window._caseUpdateCounter = _caseUpdateCounter;
  window._caseUpdateDot = _caseUpdateDot;
}

async function saveCase(editId) {
  const title = document.getElementById('fCaseTitle').value.trim();
  if (!title) { document.getElementById('fCaseTitle').focus(); return; }
  const descrIt = document.getElementById('fCaseDescrIt').value.trim();
  if (!descrIt) {
    if (typeof _caseSwitchTab === 'function') _caseSwitchTab('desc', 'it');
    setTimeout(() => { const el = document.getElementById('fCaseDescrIt'); if (el) el.focus(); }, 30);
    return;
  }

  const data = {
    title,
    titleEn: document.getElementById('fCaseTitleEn').value.trim(),
    subtitle: document.getElementById('fCaseSubtitle').value.trim(),
    subtitleEn: document.getElementById('fCaseSubtitleEn').value.trim(),
    descrIt,
    descrEn: document.getElementById('fCaseDescrEn').value.trim()
  };

  let entityId;
  if (editId) {
    await DB.updateCase(editId, data);
    entityId = editId;
    state.selection = { type: 'case', id: editId };
  } else {
    const c = await DB.createCase(data);
    entityId = c.id;
    state.selection = { type: 'case', id: c.id };
    state.expanded['case_' + c.id] = true;
  }

  const allCases = await DB.getCases();
  allCases.sort((a, b) => a.id - b.id);
  const caseIdx = allCases.findIndex(c => c.id === entityId) + 1;

  if (state.pendingFiles.it.length > 0) {
    const origFile = state.pendingFiles.it[0];
    const renamedName = _buildCaseFileName('it', caseIdx);
    const renamed = new File([origFile], renamedName, { type: 'application/pdf' });
    await storeFileForEntity(renamed, 'case', entityId, 'it', { caseId: entityId });
  }
  if (state.pendingFiles.en.length > 0) {
    const origFile = state.pendingFiles.en[0];
    const renamedName = _buildCaseFileName('en', caseIdx);
    const renamed = new File([origFile], renamedName, { type: 'application/pdf' });
    await storeFileForEntity(renamed, 'case', entityId, 'en', { caseId: entityId });
  }

  state.pendingFiles = { it: [], en: [] };
  state.openForm = null;
  await renderAll();
}

/* ========== PROCEEDING FORM (TABBED) ========== */
async function showProceedingForm(caseId, editId) {
  try {
  const isEdit = !!editId;
  const existing = isEdit ? await DB.getProceeding(editId) : null;
  const types = ['penale', 'civile', 'amministrativo', 'esecuzione', 'altro'];
  const grades = ['procura', 'primo_grado', 'appello', 'cassazione'];
  const statuses = ['attivo', 'archiviato', 'definito', 'sospeso'];
  const modelliProcura = ['mod21', 'mod44', 'mod45', 'mod21bis'];
  const sd = existing?.specificData || {};
  const _grpPresetType = (!existing && state._procGroupType) ? state._procGroupType : null;
  if (_grpPresetType) state._procGroupType = null;
  const curType = existing?.type || _grpPresetType || '';
  const curGrado = existing?.grado || '';
  const curRgType = existing?.rgType || '';

  let initPhases = [];
  if (existing && sd.phases && Array.isArray(sd.phases) && sd.phases.length > 0) {
    initPhases = sd.phases;
  } else if (existing) {
    const regs = sd.registrations;
    if (Array.isArray(regs) && regs.length > 0) {
      initPhases = regs.map((r, i) => ({
        id: 'phase_' + i,
        tipo: r.grado || '',
        ufficio: '',
        numeroRegistro: r.rgNumber || '',
        anno: r.year || '',
        magistratoPrincipale: '',
        altriMagistrati: '',
        events: []
      }));
    } else if (existing.rgNumber) {
      initPhases = [{
        id: 'phase_0',
        tipo: existing.grado || '',
        ufficio: '',
        numeroRegistro: existing.rgNumber || '',
        anno: existing.year || '',
        magistratoPrincipale: '',
        altriMagistrati: '',
        events: []
      }];
    }
  }
  state.currentProceeding = existing || null;
  state.editCaseId = caseId || null;
  state.procPhases = initPhases;

  // Init civil-specific data (grado libero, indipendente da phases penali)
  state.civil = null;
  if (existing && existing.type === 'civile') {
    const cExist = sd.civil || {};
    const fp0 = (sd.phases && sd.phases[0]) || {};
    const _legacyPhaseToGrado = {
      fase_primo_grado_civile: 'primo_grado',
      fase_appello_civile: 'appello',
      fase_cassazione_civile: 'cassazione',
      fase_mediazione: 'mediazione'
    };
    const _legacyGrado = _legacyPhaseToGrado[fp0.tipo] || _legacyPhaseToGrado[existing.grado] || '';
    const _legacyUff = (() => {
      const aut = (existing.autoritaProcedente || fp0.ufficio || '').toLowerCase();
      if (!aut) return '';
      if (aut.includes('cassazione')) return 'cassazione';
      if (aut.includes('mediazione') || aut.includes('organismo')) return 'organismo_mediazione';
      if (aut.includes('appello')) return 'corte_appello';
      if (aut.includes('giudice di pace') || aut.includes('gdp')) return 'giudice_pace';
      if (aut.includes('tribunale')) return 'tribunale_civile';
      return '';
    })();
    state.civil = {
      grado: cExist.grado || _legacyGrado,
      ufficio: cExist.ufficio || _legacyUff,
      sezione: cExist.sezione || '',
      rgNumber: cExist.rgNumber || existing.rgNumber || fp0.numeroRegistro || '',
      year: cExist.year || existing.year || fp0.anno || '',
      dataIscrizione: cExist.dataIscrizione || existing.dataIscrizioneRuolo || fp0.dataIscrizione || '',
      organismoMediazione: cExist.organismoMediazione || '',
      sede: cExist.sede || existing.citta || '',
      tribunale: cExist.tribunale || existing.tribunale || '',
      corteAppello: cExist.corteAppello || existing.distrettoAppello || '',
      provincia: cExist.provincia || existing.provincia || '',
      regione: cExist.regione || existing.regione || '',
      stato: cExist.stato || existing.stato || '',
      giudici: Array.isArray(cExist.giudici) ? cExist.giudici : [],
      avvocati: cExist.avvocati || { attore: [], convenuto: [], terzo: [], creditore_procedente: [], debitore_esecutato: [], terzo_pignorato: [] },
      decretoIngiuntivo: cExist.decretoIngiuntivo || null
    };
  }
  state.activePhaseIdx = initPhases.length > 0 ? initPhases.length - 1 : -1;
  state.editProcId = editId || null;
  state.availableActs = [];
  if (editId) { loadProceedingActs(); }

  let initEvents = [];
  if (existing && sd.events && Array.isArray(sd.events)) {
    initEvents = sd.events;
  } else if (existing && sd.phases) {
    for (const ph of (sd.phases || [])) {
      if (ph.events && ph.events.length > 0) {
        for (const ev of ph.events) {
          if (!initEvents.some(e => e.autoId && e.autoId === ev.autoId)) {
            initEvents.push({ ...ev, phaseRef: ph.tipo || '' });
          }
        }
      }
    }
  }
  state.procEvents = initEvents;

  state.activeTab = 'authority';
  if (isEdit && curType === 'penale') {
    const existingLinks = await DB.getEntitySubjects('proceeding', editId);
    const magCodes = new Set(Object.values(PHASE_TO_MAGISTRATE_ROLE));
    magCodes.add('magistrato');
    const nonMagRoles = PROCEDURAL_ROLES.filter(r => !magCodes.has(r));
    const nonMagLabelsIt = nonMagRoles.map(r => (I18N.it['procRole_' + r] || r).toLowerCase());
    const nonMagLabelsEn = nonMagRoles.map(r => (I18N.en['procRole_' + r] || r).toLowerCase());
    const indagatiLinks = existingLinks.filter(l => {
      if (!l.role) return false;
      const rLower = l.role.toLowerCase();
      if (rLower.startsWith('indagato')) return true;
      return nonMagLabelsIt.some(p => rLower.startsWith(p)) || nonMagLabelsEn.some(p => rLower.startsWith(p));
    });
    state.indagati = indagatiLinks.map(l => {
      const entry = { subjectId: l.subjectId, label: `${l.subject.lastName} ${l.subject.firstName}` };
      if (l.qualificaProcessuale) {
        entry.procRole = l.qualificaProcessuale;
      } else if (l.role) {
        const roleLower = l.role.toLowerCase();
        for (const pr of PROCEDURAL_ROLES) {
          const labelIt = (I18N.it['procRole_' + pr] || '').toLowerCase();
          const labelEn = (I18N.en['procRole_' + pr] || '').toLowerCase();
          if (roleLower.startsWith(labelIt) || roleLower.startsWith(labelEn)) {
            entry.procRole = pr;
            break;
          }
        }
        if (!entry.procRole && roleLower.startsWith('indagato')) entry.procRole = 'indagato';
      }
      if (l.dataQualifica) entry.dataQualifica = l.dataQualifica;
      if (l.role && l.role.includes(' | ')) {
        entry.roleLabel = l.role.split(' | ').slice(1).join(' | ');
      }
      return entry;
    });
  } else {
    state.indagati = Array.isArray(sd.indagati) ? [...sd.indagati] : [];
  }

  await _loadCPArticles();

  const allProcs = await DB.getAllProceedings();
  const otherProcs = allProcs.filter(p => !editId || p.id !== editId);

  const buildAutoTitle = (existing) => {
    if (!existing?.rgNumber || !existing?.year) return '';
    return buildProcTitle(existing);
  };
  const initTitle = (existing ? buildAutoTitle(existing) : '') || existing?.title || '';

  const _procOriginFiles = isEdit ? await DB.getEntityFiles('proceeding_origin', editId) : [];
  const _specContent = renderSpecificFormTabContents(curType, sd, _procOriginFiles);
  const _isPenaleObj = curType === 'penale' && _specContent && typeof _specContent === 'object';
  const _specIndagatiHtml = _isPenaleObj ? _specContent.indagati : (typeof _specContent === 'string' ? _specContent : '');
  const _specOrigineAttoHtml = _isPenaleObj ? _specContent.origineAtto : '';
  const _specDirittiHtml = _isPenaleObj ? (_specContent.dirittiProcessuali || '') : '';

  if (typeof switchSubjectTab === 'function') switchSubjectTab('all');
  const panel = document.getElementById('formView');
  panel.innerHTML = `
    <div class="form-panel">
      <input type="hidden" id="fProcCaseId" value="${caseId || existing?.caseId || ''}">
      <input type="hidden" id="fProcTitle" value="${esc(initTitle)}">
      <input type="hidden" id="fProcFase" value="${esc(existing?.fase || '')}">

      <div class="proc-form-header">
        <div style="flex:1;display:flex;flex-direction:column;gap:4px">
          <div class="proc-form-header-title ${initTitle ? 'has-title' : ''}" id="procAutoTitleBar">
            <span class="proc-form-icon">⚖️</span>
            <span id="procAutoTitleText">${initTitle ? esc(initTitle) : t(isEdit ? 'editProceeding' : 'newProceeding')}</span>
          </div>
          <div id="procFolderPathPreview" style="font-family:monospace;font-size:12px;color:#6b21a8;background:#f5f3ff;border:1px solid #e9d5ff;border-radius:4px;padding:4px 8px;display:none" data-testid="text-folder-path-preview">
            <span style="color:#9ca3af;font-weight:600">${t('folderPathPreview') || 'Percorso fascicolo'}:</span> <span id="procFolderPathPreviewValue"></span>
          </div>
        </div>
        <div class="proc-form-header-controls">
          <button class="btn btn-sm proc-header-btn proc-header-btn-save" onclick="saveProceeding(${editId || 'null'})" data-testid="button-save-proceeding">💾 ${t('save')}</button>
          <button class="btn btn-sm proc-header-btn proc-header-btn-cancel" onclick="cancelForm()" data-testid="button-cancel-proceeding">✕ ${t('cancel')}</button>
        </div>
      </div>
      <div class="proc-form-meta">
        <div class="proc-form-header-type">
          <select id="fProcType" onchange="onProcTypeChange()" ${_grpPresetType ? 'disabled style="opacity:.7;pointer-events:none" title="Tipo determinato dal contenitore"' : ''}>
            ${!curType ? `<option value="">${t('selectType')}</option>` : ''}
            ${types.map(tp => `<option value="${tp}" ${curType === tp ? 'selected' : ''}>${t(tp)}</option>`).join('')}
          </select>
        </div>
        <div class="proc-form-header-origine" id="origineProcRow" style="${curType === 'penale' ? '' : 'display:none'}">
          <select id="fOrigineProc" onchange="onOrigineProcChange()" data-testid="select-origine-proc">
            <option value="">— ${t('origineProc')} —</option>
            ${['ufficio','denuncia','querela','istanza','esposto','integrazione'].map(o => `<option value="${o}" ${sd.origineProc === o ? 'selected' : ''}>${t('origineProc_' + o)}</option>`).join('')}
          </select>
        </div>
             <div class="proc-form-header-notiignoti" id="notiIgnotiRow" style="${curType === 'penale' ? '' : 'display:none'}">
               <label class="pnir-opt"><input type="radio" name="soggettiTipoUI" value="noti" ${(sd.soggettiTipo || 'noti') === 'noti' ? 'checked' : ''} onchange="setNotiIgnoti('noti')"> ${t('soggettiNoti')}</label>
               <label class="pnir-opt"><input type="radio" name="soggettiTipoUI" value="ignoti" ${sd.soggettiTipo === 'ignoti' ? 'checked' : ''} onchange="setNotiIgnoti('ignoti')"> ${t('soggettiIgnoti')}</label>
             </div>
             <div class="proc-form-header-integrazione" id="procHeaderIntLabel" style="${sd.origineProc === 'integrazione' ? '' : 'display:none'}">${t('origineProc_perIntegrazione')}</div>
        <div class="proc-form-header-viol" id="procHeaderViolBadge" style="${sd.origineProc === 'integrazione' ? '' : 'display:none'}">${t('origineProc_illegittimo')}</div>
        <div class="proc-form-header-parent" id="procPadreRow" style="${sd.origineProc === 'integrazione' ? '' : 'display:none'}">
          <select id="fProcPadre">
            <option value="">— ${t('procPadre')} —</option>
            ${allProcs.filter(p => !editId || p.id !== editId).map(p => `<option value="${p.id}" ${(existing?.parentProceedingId || '') == p.id ? 'selected' : ''}>${esc(buildProcTitle(p))}</option>`).join('')}
          </select>
        </div>
      </div>

      <div id="authVigilanceChain" class="form-section-group" style="display:none;margin-bottom:10px">
        <div class="phase-section-label" style="margin-bottom:8px">${t('catenaVigilanza')}</div>
        <div id="authVigilanceContent"></div>
      </div>

      <div id="procFormBody" class="${curType ? '' : 'hidden'}">

      <div class="form-block" id="formCivileBlock" style="${(curType !== 'civile' && curType !== 'esecuzione') ? 'display:none' : ''}"></div>

      <div id="acc-indagati-anchor"></div>
      ${_specIndagatiHtml}

      <div class="form-section-group">
        <div class="phase-section-label" style="margin-bottom:8px">${t('tabLuogo')}</div>
        <div class="form-grid">
          <div class="form-group">
            <label>${t('luogoFatti')}</label>
            <input id="fProcLuogoFatti" value="${esc(existing?.luogoFatti || '')}">
          </div>
          <div class="form-group autocomplete-wrap">
            <label>${t('citta')}</label>
            <input id="fProcCitta" value="${esc(existing?.citta || '')}" autocomplete="off" data-testid="input-proc-citta">
            <div id="fProcCittaSuggestions" class="autocomplete-list"></div>
          </div>
        </div>
        <div class="form-grid form-grid-3">
          <div class="form-group">
            <label>${t('provincia')}</label>
            <input id="fProcProvincia" value="${esc(existing?.provincia || '')}">
          </div>
          <div class="form-group">
            <label>${t('regione')}</label>
            <input id="fProcRegione" value="${esc(existing?.regione || '')}">
          </div>
          <div class="form-group">
            <label>${t('stato_geo')}</label>
            <input id="fProcStato" value="${esc(existing?.stato || '')}">
          </div>
        </div>
      </div>
      <div id="acc-luogo"></div>

      ${_specOrigineAttoHtml}

      <div class="form-block" id="formPhasesBlock" style="margin-top:28px;${(curType !== 'penale') ? 'display:none' : ''}">
        <div class="phases-section-header">
          <h3 class="form-block-label" style="margin:0">${t('fasiProcedimentali')}</h3>
        </div>
        <div id="phasesContainer"></div>
      </div>

      <div class="form-block" id="formRolesBlock" style="${curType !== 'penale' ? 'display:none' : ''}">
        <h3 class="form-block-label">${t('procRolesTitle')}</h3>
        <div id="formProcRolesContainer"><p class="hint">${t('noProcRoles')}</p></div>
      </div>

      <div class="form-block" id="procEventsFormBlock" style="${curType === 'penale' ? 'display:none' : ''}">
        <h3 class="form-block-label">${t('eventsTimelineTitle')}</h3>
        <div id="procEventsContainer"></div>
      </div>

      ${_specDirittiHtml}

      </div>
    </div>
  `;
  if (editId) renderFormProcRoles(editId);
  if (curType === 'penale') renderIndagatiList();
  if (curType === 'civile' || curType === 'esecuzione') renderCivileSection();
  if (curType) {
    if (curType === 'penale' && (!state.procPhases || state.procPhases.length === 0)) {
      state.procPhases = [createNewPhase('fase_procura')];
      state.activePhaseIdx = 0;
    }
    renderPhasesSection();
    updateFaseOptions(true);
    renderProcEventsSection();
  }
  console.log('showProceedingForm: calling setupCittaAutocomplete');
  setupCittaAutocomplete('fProcCitta', 'fProcCittaSuggestions', {
    provincia: 'fProcProvincia',
    regione: 'fProcRegione',
    stato: 'fProcStato'
  });
  setupCittaAutocomplete('fSpecCittaDeposito', 'fSpecCittaDepositoSuggestions', {}, {
    formatValue: function(c) { return c.comune + (c.provincia ? ' (' + c.provincia + ')' : ''); }
  });
  if (curType === 'penale') {
    setupIndagatoAutocomplete();
    onOrigineProcChange();
  }
  } catch (e) {
    console.error('showProceedingForm error:', e);
    alert('Errore apertura form: ' + e.message);
  }
}

