async function _plAvvSearch(phaseIdx, plIdx, val) {
  const sugg = document.getElementById(`plAvvSugg_${phaseIdx}_${plIdx}`);
  if (!sugg) return;
  if (!val || val.length < 2) { sugg.innerHTML = ''; return; }
  const subjects = await DB.getSubjects();
  const lower = val.toLowerCase();
  const matches = subjects.filter(s => {
    const full = ((s.lastName || '') + ' ' + (s.firstName || '')).toLowerCase();
    return full.includes(lower);
  }).slice(0, 8);
  sugg.innerHTML = matches.length === 0
    ? `<div class="autocomplete-item" style="color:#9ca3af;pointer-events:none">Nessun avvocato trovato</div>`
    : matches.map(s =>
        `<div class="autocomplete-item" onclick="_plAvvSelect(${phaseIdx}, ${plIdx}, ${s.id}, '${esc((s.lastName + ' ' + s.firstName).trim())}')">` +
        `🎓 ${s.salutation ? esc(s.salutation) + ' ' : ''}${esc(s.firstName)} ${esc(s.lastName)}</div>`
      ).join('');
}

