async function ensureCaseLink(subjectId, proceedingId, role) {
  const proc = await DB.getProceeding(proceedingId);
  if (!proc || !proc.caseId) return;
  const caseLinks = await DB.getEntitySubjects('case', proc.caseId);
  const alreadyLinked = caseLinks.some(l => l.subjectId === subjectId);
  if (!alreadyLinked) {
    await DB.linkSubject({ entityType: 'case', entityId: proc.caseId, subjectId, role: role || '' });
  }
}

// Shadow-sync: scrive in entitySubjects (con linkKind) i soggetti che oggi vivono
// in proceedings.vigilanceSubjects e nelle fasi annidate (magistrati/personeLese/indagatiReati).
// Lo schema legacy resta sorgente primaria di verità; questo crea un indice
// unificato per la vista 7-categorie senza rompere niente.
// Vigilanza con storico: cambio magistrato = chiusura riga vecchia (dataFine) + nuova riga.
async function syncProceedingShadowLinks(proceedingId, data) {
  if (!data) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const existing = await DB.getEntitySubjects('proceeding', proceedingId);
    const existingByKind = {};
    for (const link of existing) {
      if (!link.linkKind) continue;
      (existingByKind[link.linkKind] = existingByKind[link.linkKind] || []).push(link);
    }

    // Vigilanza (con storico)
    const vmap = data.vigilanceSubjects || {};
    const vigDate = data.dataIscrizioneRuolo || today;
    const vigExisting = existingByKind.vigilanza || [];
    for (const vKey of Object.keys(vmap)) {
      const desiredSubjId = vmap[vKey];
      if (!desiredSubjId) continue;
      const active = vigExisting.find(l => l.vigKey === vKey && !l.dataFine);
      if (active) {
        if (active.subjectId !== desiredSubjId) {
          await DB.updateSubjectLink(active.id, { dataFine: today });
          await DB.linkSubject({
            entityType: 'proceeding', entityId: proceedingId,
            subjectId: desiredSubjId, linkKind: 'vigilanza', vigKey: vKey,
            role: 'vigilanza_' + vKey, qualificaProcessuale: '',
            dataInizio: today, dataFine: ''
          });
        }
      } else {
        const anyRow = vigExisting.find(l => l.vigKey === vKey && l.subjectId === desiredSubjId);
        if (!anyRow) {
          await DB.linkSubject({
            entityType: 'proceeding', entityId: proceedingId,
            subjectId: desiredSubjId, linkKind: 'vigilanza', vigKey: vKey,
            role: 'vigilanza_' + vKey, qualificaProcessuale: '',
            dataInizio: vigDate, dataFine: ''
          });
        }
      }
    }
    // Chiudi righe vigilanza la cui chiave è stata rimossa dalla mappa
    for (const link of vigExisting) {
      if (link.dataFine) continue;
      if (link.vigKey && !vmap[link.vigKey]) {
        await DB.updateSubjectLink(link.id, { dataFine: today });
      }
    }

    // Magistrati di fase (inquirente / giudicante)
    const phases = (data.specificData && data.specificData.phases) || [];
    const desiredMag = [];
    for (const ph of phases) {
      const sid = ph.magistratoSubjectId;
      if (!sid) continue;
      const roleCode = PHASE_TO_MAGISTRATE_ROLE[ph.tipo] || 'magistrato';
      const kind = (roleCode === 'pm') ? 'inquirente' : 'giudicante';
      desiredMag.push({ subjectId: sid, kind, faseId: ph.id || ph.tipo, faseTipo: ph.tipo, roleCode });
    }
    for (const kind of ['inquirente', 'giudicante']) {
      const existingK = existingByKind[kind] || [];
      const desiredK = desiredMag.filter(d => d.kind === kind);
      const desiredKeys = new Set(desiredK.map(d => d.subjectId + '|' + d.faseId));
      for (const link of existingK) {
        const key = link.subjectId + '|' + (link.faseId || '');
        if (!desiredKeys.has(key)) await DB.unlinkSubject(link.id);
      }
      const existingKeys = new Set(existingK.map(l => l.subjectId + '|' + (l.faseId || '')));
      for (const d of desiredK) {
        const key = d.subjectId + '|' + d.faseId;
        if (existingKeys.has(key)) continue;
        await DB.linkSubject({
          entityType: 'proceeding', entityId: proceedingId,
          subjectId: d.subjectId, linkKind: d.kind,
          faseId: d.faseId, faseTipo: d.faseTipo,
          role: d.roleCode, qualificaProcessuale: d.roleCode
        });
      }
    }

    // Persone lese di fase + Indagati di fase (con faseId; quelli senza faseId
    // restano gestiti da syncIndagatiLinks via state.indagati)
    const desiredPL = [], desiredIR = [];
    for (const ph of phases) {
      for (const pl of (ph.personeLese || [])) {
        if (!pl.subjectId) continue;
        desiredPL.push({ subjectId: pl.subjectId, faseId: ph.id || ph.tipo, faseTipo: ph.tipo, avvocati: pl.avvocati || [] });
      }
      for (const ir of (ph.indagatiReati || [])) {
        if (!ir.subjectId) continue;
        desiredIR.push({ subjectId: ir.subjectId, faseId: ph.id || ph.tipo, faseTipo: ph.tipo, reati: ir.reati || [], avvocati: ir.avvocati || [] });
      }
    }
    async function _reconcileFasedKind(kind, desiredArr) {
      const existingK = (existingByKind[kind] || []).filter(l => l.faseId);
      const desiredKeys = new Set(desiredArr.map(d => d.subjectId + '|' + d.faseId));
      for (const link of existingK) {
        const key = link.subjectId + '|' + (link.faseId || '');
        if (!desiredKeys.has(key)) await DB.unlinkSubject(link.id);
      }
      const existingMap = {};
      for (const l of existingK) existingMap[l.subjectId + '|' + l.faseId] = l;
      for (const d of desiredArr) {
        const key = d.subjectId + '|' + d.faseId;
        const exi = existingMap[key];
        const payload = {
          entityType: 'proceeding', entityId: proceedingId,
          subjectId: d.subjectId, linkKind: kind,
          faseId: d.faseId, faseTipo: d.faseTipo,
          avvocati: d.avvocati || [],
          qualificaProcessuale: kind === 'parteOffesa' ? 'persona_offesa' : 'indagato'
        };
        if (kind === 'indagatoImputato') payload.reati = d.reati || [];
        if (exi) await DB.updateSubjectLink(exi.id, payload);
        else await DB.linkSubject(payload);
      }
    }
    await _reconcileFasedKind('parteOffesa', desiredPL);
    await _reconcileFasedKind('indagatoImputato', desiredIR);
  } catch (e) {
    console.warn('[shadow-sync] failed for proceeding', proceedingId, e);
  }
}

async function syncIndagatiLinks(proceedingId) {
  const existing = await DB.getEntitySubjects('proceeding', proceedingId);
  const magCodes = new Set(Object.values(PHASE_TO_MAGISTRATE_ROLE));
  magCodes.add('magistrato');
  const nonMagRoles = PROCEDURAL_ROLES.filter(r => !magCodes.has(r));
  const nonMagLabelsIt = nonMagRoles.map(r => (I18N.it['procRole_' + r] || r).toLowerCase());
  const nonMagLabelsEn = nonMagRoles.map(r => (I18N.en['procRole_' + r] || r).toLowerCase());
  const existingIndagati = existing.filter(l => {
    if (!l.role) return false;
    const rLower = l.role.toLowerCase();
    if (rLower.startsWith('indagato')) return true;
    return nonMagLabelsIt.some(p => rLower.startsWith(p)) || nonMagLabelsEn.some(p => rLower.startsWith(p));
  });
  const existingMap = {};
  for (const link of existingIndagati) existingMap[link.subjectId] = link;
  const newIds = state.indagati.map(i => i.subjectId);

  for (const link of existingIndagati) {
    if (!newIds.includes(link.subjectId)) {
      await DB.unlinkSubject(link.id);
    }
  }

  await _loadAllLists();
  function buildRoleStr(entry) {
    const procLabel = entry.procRole ? t('procRole_' + entry.procRole) : t('procRole_indagato');
    let qualStr = '';
    if (entry.role) {
      if (entry.role.roleId) { const rl = _allRoles.find(r => r.id === entry.role.roleId); if (rl) qualStr = _labelFor(rl); }
      else if (entry.role.subcategoryId) { const sub = _allSubcategories.find(s => s.id === entry.role.subcategoryId); if (sub) qualStr = _labelFor(sub); }
      else if (entry.role.categoryId) { const cat = _allCategories.find(c => c.id === entry.role.categoryId); if (cat) qualStr = _labelFor(cat); }
    }
    return qualStr ? `${procLabel} | ${t('asRole')} ${qualStr}` : procLabel;
  }

  for (const entry of state.indagati) {
    const roleStr = buildRoleStr(entry);
    const qualifica = entry.procRole || 'indagato';
    const dataQ = entry.dataQualifica || new Date().toISOString().slice(0, 10);
    const existingLink = existingMap[entry.subjectId];
    const linkKind = _deriveLinkKindFromProcRole(qualifica);
    if (existingLink) {
      if (existingLink.role !== roleStr || existingLink.qualificaProcessuale !== qualifica || existingLink.linkKind !== linkKind) {
        await DB.unlinkSubject(existingLink.id);
        await DB.linkSubject({ entityType: 'proceeding', entityId: proceedingId, subjectId: entry.subjectId, role: roleStr, qualificaProcessuale: qualifica, dataQualifica: dataQ, linkKind });
      }
    } else {
      await DB.linkSubject({ entityType: 'proceeding', entityId: proceedingId, subjectId: entry.subjectId, role: roleStr, qualificaProcessuale: qualifica, dataQualifica: dataQ, linkKind });
      await ensureCaseLink(entry.subjectId, proceedingId, roleStr);
    }
  }
}

async function syncProceedingRoles(proceedingId, type) {
  const existingRoles = await DB.getProceedingRoles(proceedingId);

  if (type === 'penale') {
    const indagatiRoleCodes = ['indagato', 'imputato', 'persona_offesa'];
    const existingIndagatiRoles = existingRoles.filter(r => indagatiRoleCodes.includes(r.roleCode));
    const existingIndagatiMap = {};
    for (const r of existingIndagatiRoles) existingIndagatiMap[r.subjectId] = r;

    const newIndagatiIds = state.indagati.map(i => i.subjectId);
    for (const r of existingIndagatiRoles) {
      if (!newIndagatiIds.includes(r.subjectId)) {
        await DB.removeProceedingRole(r.id);
      }
    }

    for (const entry of state.indagati) {
      const roleCode = entry.procRole || 'indagato';
      const existing = existingIndagatiMap[entry.subjectId];
      if (existing) {
        if (existing.roleCode !== roleCode) {
          await DB.updateProceedingRole(existing.id, { roleCode });
        }
      } else {
        const startDate = entry.dataQualifica || new Date().toISOString().slice(0, 10);
        await DB.addProceedingRole({
          proceedingId, subjectId: entry.subjectId, roleCode,
          startDate, endDate: '', roleStatus: 'active', notes: ''
        });
      }
    }
  }

  const phases = state.procPhases || [];
  const magRoleCodes = Object.values(PHASE_TO_MAGISTRATE_ROLE);
  magRoleCodes.push('magistrato');
  const existingMagRoles = existingRoles.filter(r => magRoleCodes.includes(r.roleCode));
  const existingMagMap = {};
  for (const r of existingMagRoles) {
    const key = r.subjectId + '_' + r.roleCode;
    existingMagMap[key] = r;
  }

  const neededMagRoles = {};
  for (const ph of phases) {
    if (!ph.magistratoPrincipale) continue;
    let subjectId = ph.magistratoSubjectId || null;

    if (!subjectId) {
      const inputNorm = ph.magistratoPrincipale.trim().replace(/\s+/g, ' ').toLowerCase();
      if (inputNorm.length >= 3) {
        const allSubjects = await DB.getSubjects();
        const found = allSubjects.find(s => {
          const fullA = ((s.lastName || '') + ' ' + (s.firstName || '')).trim().replace(/\s+/g, ' ').toLowerCase();
          const fullB = ((s.firstName || '') + ' ' + (s.lastName || '')).trim().replace(/\s+/g, ' ').toLowerCase();
          const sal = (s.salutation || '').trim().toLowerCase();
          const fullC = sal ? (sal + ' ' + fullA).replace(/\s+/g, ' ') : '';
          const fullD = sal ? (sal + ' ' + fullB).replace(/\s+/g, ' ') : '';
          return fullA === inputNorm || fullB === inputNorm || fullC === inputNorm || fullD === inputNorm;
        });
        if (found) {
          subjectId = found.id;
          ph.magistratoSubjectId = found.id;
        }
      }
    }

    if (!subjectId) continue;

    const roleCode = PHASE_TO_MAGISTRATE_ROLE[ph.tipo] || 'magistrato';
    const key = subjectId + '_' + roleCode;
    neededMagRoles[key] = { subjectId, roleCode, phaseType: ph.tipo };
  }

  const magSeenKeys = {};
  for (const r of existingMagRoles) {
    const key = r.subjectId + '_' + r.roleCode;
    if (!neededMagRoles[key] || magSeenKeys[key]) {
      await DB.removeProceedingRole(r.id);
    } else {
      magSeenKeys[key] = true;
    }
  }

  for (const key in neededMagRoles) {
    if (!magSeenKeys[key]) {
      const { subjectId, roleCode } = neededMagRoles[key];
      await DB.addProceedingRole({
        proceedingId, subjectId, roleCode,
        startDate: '', endDate: '', roleStatus: 'active', notes: ''
      });
    }
  }

  const hasProcuraPhase = phases.some(p => p.tipo === 'fase_procura');
  const vigChainKeys = ['procuratoreRepubblica', 'presidenteTribunale', 'presidenteCorteAppello', 'procuratoreGenerale'];
  const vigRoleCodes = ['responsabile_vigilanza', ...vigChainKeys];

  const existingVigRoles = existingRoles.filter(r => vigRoleCodes.includes(r.roleCode));

  const neededVigRoles = {};
  if (hasProcuraPhase && state._vigilanceSubjectIds) {
    for (const vKey of vigChainKeys) {
      const sid = state._vigilanceSubjectIds[vKey];
      if (sid) {
        const key = sid + '_' + vKey;
        neededVigRoles[key] = { subjectId: sid, roleCode: vKey };
      }
    }
  }

  const vigSeenKeys = {};
  for (const r of existingVigRoles) {
    const key = r.subjectId + '_' + r.roleCode;
    if (!neededVigRoles[key] || vigSeenKeys[key]) {
      await DB.removeProceedingRole(r.id);
    } else {
      vigSeenKeys[key] = true;
    }
  }
  for (const key in neededVigRoles) {
    if (!vigSeenKeys[key]) {
      const { subjectId, roleCode } = neededVigRoles[key];
      await DB.addProceedingRole({
        proceedingId, subjectId, roleCode,
        startDate: '', endDate: '', roleStatus: 'active', notes: ''
      });
    }
  }

  const existingEntityLinks = await DB.getEntitySubjects('proceeding', proceedingId);
  const _allManagedRoleCodes = [...magRoleCodes, ...vigRoleCodes];
  const _allManagedLabelsBoth = [];
  _allManagedRoleCodes.forEach(rc => {
    _allManagedLabelsBoth.push(tLang('procRole_' + rc, 'it'));
    _allManagedLabelsBoth.push(tLang('procRole_' + rc, 'en'));
  });

  const existingManagedEntityLinks = existingEntityLinks.filter(l => {
    if (!l.role) return false;
    return _allManagedLabelsBoth.some(label => l.role === label);
  });

  const allNeededRoles = { ...neededMagRoles };
  for (const key in neededVigRoles) {
    allNeededRoles[key] = neededVigRoles[key];
  }

  const neededSubjectRoleKeys = new Set();
  for (const key in allNeededRoles) neededSubjectRoleKeys.add(key);

  for (const link of existingManagedEntityLinks) {
    const linkRoleLabelIt = _allManagedLabelsBoth.find(lb => lb === link.role);
    if (!linkRoleLabelIt) continue;
    const matchedRoleCode = _allManagedRoleCodes.find(rc =>
      tLang('procRole_' + rc, 'it') === link.role || tLang('procRole_' + rc, 'en') === link.role
    );
    if (!matchedRoleCode) continue;
    const linkKey = link.subjectId + '_' + matchedRoleCode;
    if (!neededSubjectRoleKeys.has(linkKey)) {
      await DB.unlinkSubject(link.id);
    }
  }

  for (const key in allNeededRoles) {
    const { subjectId, roleCode } = allNeededRoles[key];
    const roleLabel = t('procRole_' + roleCode);
    const roleLabelIt = tLang('procRole_' + roleCode, 'it');
    const roleLabelEn = tLang('procRole_' + roleCode, 'en');
    const isPmRole = roleCode === 'pm';
    const alreadyLinked = existingEntityLinks.some(l => l.subjectId === subjectId && l.role && (l.role === roleLabelIt || l.role === roleLabelEn));
    if (alreadyLinked) {
      const existing = existingEntityLinks.find(l => l.subjectId === subjectId && l.role && (l.role === roleLabelIt || l.role === roleLabelEn));
      if (existing && (existing.role !== roleLabel || (isPmRole && !existing.qualificaProcessuale))) {
        await DB.unlinkSubject(existing.id);
        await DB.linkSubject({ entityType: 'proceeding', entityId: proceedingId, subjectId, role: roleLabel, ...(isPmRole ? { qualificaProcessuale: 'pm' } : {}) });
      }
      await _autoFuncQualifica(subjectId, proceedingId, roleLabel);
    } else {
      await DB.linkSubject({ entityType: 'proceeding', entityId: proceedingId, subjectId, role: roleLabel, ...(isPmRole ? { qualificaProcessuale: 'pm' } : {}) });
      await _autoFuncQualifica(subjectId, proceedingId, roleLabel);
    }
  }
}

async function syncAvvocatiLinks(proceedingId) {
  const existing = await DB.getEntitySubjects('proceeding', proceedingId);
  const existingAvv = existing.filter(l => l.qualificaProcessuale === 'avvocato_costituito');
  const existingMap = {};
  for (const link of existingAvv) existingMap[link.subjectId] = link;

  // Collect all current avvocati from phases (deduplicated by subjectId)
  const newAvvMap = {};
  for (const ph of (state.procPhases || [])) {
    for (const pl of (ph.personeLese || [])) {
      for (const av of (pl.avvocati || [])) {
        if (av.subjectId && !newAvvMap[av.subjectId]) {
          newAvvMap[av.subjectId] = av;
        }
      }
    }
    for (const ir of (ph.indagatiReati || [])) {
      for (const av of (ir.avvocati || [])) {
        if (av.subjectId && !newAvvMap[av.subjectId]) {
          newAvvMap[av.subjectId] = av;
        }
      }
    }
  }
  // Civil: collect avvocati from civil parti
  if (state.civil && state.civil.avvocati) {
    for (const parte of ['attore', 'convenuto', 'terzo', 'creditore_procedente', 'debitore_esecutato', 'terzo_pignorato']) {
      for (const av of (state.civil.avvocati[parte] || [])) {
        if (av.subjectId && !newAvvMap[av.subjectId] && !av.dataRevoca) {
          newAvvMap[av.subjectId] = av;
        }
      }
    }
  }

  // Remove stale links
  for (const link of existingAvv) {
    if (!newAvvMap[link.subjectId]) {
      await DB.unlinkSubject(link.id);
    }
  }

  // Create new links
  const roleLabel = t('procRole_avvocato_costituito');
  for (const av of Object.values(newAvvMap)) {
    if (!existingMap[av.subjectId]) {
      await DB.linkSubject({
        entityType: 'proceeding',
        entityId: proceedingId,
        subjectId: av.subjectId,
        role: roleLabel,
        qualificaProcessuale: 'avvocato_costituito'
      });
      await ensureCaseLink(av.subjectId, proceedingId, roleLabel);
    }
  }
}

async function saveProceeding(editId) {
  try {
  const type = document.getElementById('fProcType').value;
  const caseId = parseInt(document.getElementById('fProcCaseId').value);
  if (!type) { alert('Type required'); return; }
  if (isNaN(caseId)) { alert('Case ID missing'); return; }

  const isCivile = type === 'civile';
  const phases = isCivile ? [] : (state.procPhases || []);
  const title = document.getElementById('fProcTitle').value.trim();
  const firstPhase = phases[0] || {};
  let rgNumber, year;
  if (isCivile) {
    const cs = _getCivilState();
    rgNumber = (cs.rgNumber || '').trim();
    year = (cs.year || '').toString().trim();
    if (!rgNumber || !year) {
      alert(t('civilRgRequired'));
      return;
    }
  } else if (type === 'esecuzione') {
    const _rgeRaw = (document.getElementById('fSpecRGE')?.value || '').trim();
    const _annoEseRaw = (document.getElementById('fSpecAnnoEse')?.value || '').trim();
    const _dataPignRaw = (document.getElementById('fSpecDataPign')?.value || '').trim();
    if (_rgeRaw.includes('/')) {
      const _parts = _rgeRaw.split('/');
      rgNumber = _parts[0].trim();
      const _yPart = (_parts[1] || '').trim();
      year = _annoEseRaw || (_yPart.length === 2 ? '20' + _yPart : _yPart);
    } else {
      rgNumber = _rgeRaw;
      year = _annoEseRaw || (_dataPignRaw ? _dataPignRaw.slice(0, 4) : '') || (firstPhase.anno || '');
    }
    if (!rgNumber || !year) {
      alert(t('eseRGE') + ' + ' + t('year') + ' required');
      return;
    }
  } else {
    rgNumber = firstPhase.numeroRegistro || '';
    year = firstPhase.anno || '';
    if (!rgNumber || !year) {
      alert(t('rgNumber') + ' + ' + t('year') + ' required');
      return;
    }
  }

  const origineProc = document.getElementById('fOrigineProc')?.value || '';
  const padreVal = document.getElementById('fProcPadre')?.value || '';
  if (origineProc === 'integrazione' && !padreVal) {
    alert(t('integrazionePadreRequired'));
    return;
  }
  let _existingGroupId = null;
  if (editId) {
    const _existingProc = await DB.getProceeding(editId);
    _existingGroupId = _existingProc?.proceedingGroupId || null;
  }
  const useCivilBlock = isCivile || (type === 'esecuzione');
  const cs = useCivilBlock ? _getCivilState() : null;
  const civilSpecific = useCivilBlock ? {
    civil: { ...cs }
  } : {};
  const data = {
    title: title || `${rgNumber}/${year}`, type, caseId,
    proceedingGroupId: state._procGroupId || _existingGroupId || null,
    rgType: '',
    rgNumber,
    year,
    grado: isCivile ? (cs.grado || '') : (cs && cs.grado ? cs.grado : (firstPhase.tipo || '')),
    fase: document.getElementById('fProcFase')?.value || '',
    modelloProcura: '',
    parentProceedingId: null,
    stato: useCivilBlock ? (cs.stato || '') : (document.getElementById('fProcStato')?.value?.trim() || ''),
    regione: useCivilBlock ? (cs.regione || '') : (document.getElementById('fProcRegione')?.value?.trim() || ''),
    provincia: useCivilBlock ? (cs.provincia || '') : (document.getElementById('fProcProvincia')?.value?.trim() || ''),
    citta: useCivilBlock ? (cs.sede || '') : (document.getElementById('fProcCitta')?.value?.trim() || ''),
    luogoFatti: document.getElementById('fProcLuogoFatti')?.value?.trim() || '',
    status: isCivile ? '' : (_derivePenaleStatus(state.procPhases) || ''),
    autoritaProcedente: useCivilBlock ? (cs.ufficio ? t('civilUff_' + cs.ufficio) : '') : (_getF1Field('ufficio') || ''),
    tribunale: useCivilBlock ? (cs.tribunale || '') : (_getF1GeoField('tribunale') || ''),
    distrettoAppello: useCivilBlock ? (cs.corteAppello || '') : (_getF1GeoField('corteAppello') || ''),
    dataIscrizioneRuolo: useCivilBlock ? (cs.dataIscrizione || '') : (_getF1Field('dataIscrizione') || ''),
    vigilanceSubjects: state._vigilanceSubjectIds || {},
    specificData: { ...collectSpecificData(type), ...civilSpecific, phases, events: state.procEvents || [] }
  };

  data.protocol = await _assignProtocol(caseId, data.dataIscrizioneRuolo, 'proceeding', editId || null);

  for (const ph of data.specificData.phases) {
    const autoId = 'auto_iscrizione_' + ph.id;
    const events = data.specificData.events;
    const existingIdx = events.findIndex(e => e.autoId === autoId);
    if (ph.dataIscrizione) {
      const uffProc = ph.ufficio ? ' (' + ph.ufficio + ')' : '';
      const evObj = { autoId, date: ph.dataIscrizione, title: t('iscrizioneRuoloEvento') + uffProc, magistrate: ph.magistratoPrincipale || '', description: '', phaseRef: ph.tipo || '' };
      if (existingIdx >= 0) {
        events[existingIdx] = { ...events[existingIdx], ...evObj };
      } else {
        events.push(evObj);
      }
    } else if (existingIdx >= 0) {
      events.splice(existingIdx, 1);
    }
  }

  // Evento automatico per tutti i pmEvents di tutte le fasi
  for (const ph of data.specificData.phases) {
    const pmEvs = ph.pmEvents || [];
    const events = data.specificData.events;
    // Rimuovi eventi auto PM obsoleti per questa fase
    const _validAutoIds = new Set();
    pmEvs.forEach((pmEv, evIdx) => {
      if (pmEv.date) _validAutoIds.add('auto_pmev_' + ph.id + '_' + evIdx);
    });
    for (let _i = events.length - 1; _i >= 0; _i--) {
      const _ev = events[_i];
      if (_ev.autoId && _ev.autoId.startsWith('auto_pmev_' + ph.id + '_') && !_validAutoIds.has(_ev.autoId)) {
        events.splice(_i, 1);
      }
    }
    pmEvs.forEach((pmEv, evIdx) => {
      if (!pmEv.date) return;
      const autoId = 'auto_pmev_' + ph.id + '_' + evIdx;
      const existingIdx = events.findIndex(e => e.autoId === autoId);
      const evObj = {
        autoId,
        date: pmEv.date,
        title: t(pmEv.sottoTipo) || t(pmEv.tipo) || '\u2014',
        magistrate: ph.magistratoPrincipale || '',
        description: pmEv.notes || '',
        phaseRef: ph.tipo || 'fase_procura',
        sottoTipo: pmEv.sottoTipo || '',
        pmTipo: pmEv.tipo || ''
      };
      if (existingIdx >= 0) {
        events[existingIdx] = { ...events[existingIdx], ...evObj };
      } else {
        events.push(evObj);
      }
    });
  }

  let entityId;
  if (editId) {
    await DB.updateProceeding(editId, data);
    entityId = editId;
    state.selection = { type: 'proceeding', id: editId };
  } else {
    const p = await DB.createProceeding(data);
    entityId = p.id;
    state._procGroupId = null;
    state.selection = { type: 'proceeding', id: p.id };
    state.expanded['case_' + caseId] = true;
    state.expanded['proceeding_' + p.id] = true;
  }

  if (type === 'penale') {
    await syncIndagatiLinks(entityId);
  }
  await syncProceedingRoles(entityId, type);
  await syncAvvocatiLinks(entityId);
  if (type === 'penale') {
    await syncProceedingShadowLinks(entityId, data);
  }

  const _procHier = { caseId, proceedingId: entityId };
  for (const f of state.pendingFilesOrigin.it) await storeFileForEntity(f, 'proceeding_origin', entityId, 'it', _procHier);
  for (const f of state.pendingFilesOrigin.en) await storeFileForEntity(f, 'proceeding_origin', entityId, 'en', _procHier);

  state.pendingFiles = { it: [], en: [] };
  state.pendingFilesOrigin = { it: [], en: [] };
  state.openForm = null;
  await renderAll();
  showLinkedSection('proceeding', entityId);
  await renderCaseTimeline(caseId);
  // Aggiorna timeline procedimento con i nuovi eventi PM auto-sincronizzati
  const _savedProc = await DB.getProceeding(entityId);
  if (_savedProc && _savedProc.specificData) {
    renderProceedingTimeline(_savedProc.specificData);
  }
  } catch (e) {
    console.error('saveProceeding error:', e);
    alert('Errore salvataggio: ' + e.message);
  }
}

