function checkDossStep1Btn() {
  const titleEl = document.getElementById('fDossTitle');
  const btnEl = document.getElementById('fDossNextBtn');
  if (!titleEl || !btnEl) return;
  const hasTitle = titleEl.value.trim().length > 0;
  const hasLang = !!state.dossWizard.origLang;
  btnEl.disabled = !(hasTitle && hasLang);
}

function _dossSelectLang(lang, btn) {
  state.dossWizard.origLang = lang;
  document.querySelectorAll('.doss-lang-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  checkDossStep1Btn();
}

async function _dossStep1Next() {
  const titleEl = document.getElementById('fDossTitle');
  const title = titleEl ? titleEl.value.trim() : '';
  if (!title || !state.dossWizard.origLang) return;
  const certEl = document.getElementById('fDossCertTransl');
  state.dossWizard.hasCertTransl = certEl ? certEl.checked : false;
  state.dossWizard.title = title;
  state.dossWizard.step = 2;
  const procId = document.getElementById('fDossProcId')?.value || state.dossWizard.proceedingId || '';
  const editId = state.dossWizard.editId;
  const origLang = state.dossWizard.origLang;
  const transLang = origLang === 'it' ? 'en' : 'it';
  let existingOrigFiles = [];
  let existingTranslFiles = [];
  _alldigCards = [];
  if (editId) {
    const allFiles = (await DB.getEntityFiles('dossier', editId)) || [];
    existingOrigFiles = allFiles.filter(f => f.fileRole === 'doss_orig' || (!f.fileRole && f.lang === origLang));
    existingTranslFiles = allFiles.filter(f => f.fileRole === 'doss_cert');
    const alldigFiles = allFiles.filter(f => f.fileRole === 'doss_alldig');
    const alldigGroups = {};
    for (const f of alldigFiles) {
      const m = (f.storagePath || '').match(/_DDP(\d+)/);
      const key = m ? m[1] : '???';
      if (!alldigGroups[key]) alldigGroups[key] = { id: Date.now() + Math.random(), desc: f.notes || '', files: [], existing: [] };
      alldigGroups[key].existing.push(f);
    }
    for (const key of Object.keys(alldigGroups).sort()) {
      _alldigCards.push(alldigGroups[key]);
    }
  }
  _showDossStep2(procId, editId, existingOrigFiles, existingTranslFiles);
  if ((state.pendingFiles[origLang] || []).length > 0) _updateFileDropList(origLang);
  if ((state.pendingFiles[transLang] || []).length > 0) _updateFileDropList(transLang);
}

function _dossStep2Back() {
  state.dossWizard.step = 1;
  const procId = state.dossWizard.proceedingId || '';
  _showDossStep1(procId, state.dossWizard.editId, null);
}

function _dossShowSaveProgress(current, total, fileName) {
  const el = document.getElementById('dossSaveProgress');
  const txt = document.getElementById('dossSaveProgressText');
  const actions = document.getElementById('dossSaveActions');
  if (el) el.style.display = 'flex';
  if (actions) Array.from(actions.querySelectorAll('button')).forEach(b => b.disabled = true);
  if (txt) txt.textContent = total > 0
    ? `${t('savingFile')} ${current}/${total}${fileName ? ' — ' + fileName : ''}…`
    : `${t('saving')}…`;
}

async function saveDossier(editId) {
  const titleEl = document.getElementById('fDossTitle');
  const title = (titleEl ? titleEl.value.trim() : '') || state.dossWizard.title.trim();
  if (!title) return;

  const origLang = document.getElementById('fDossOrigLang')?.value || state.dossWizard.origLang || 'it';
  const hasCertTransl = (document.getElementById('fDossHasCertTransl')?.value === '1') || state.dossWizard.hasCertTransl;
  const transLang = origLang === 'it' ? 'en' : 'it';

  const origPending = state.pendingFiles[origLang] || [];
  if (origPending.length === 0) {
    if (editId) {
      const existingOrig = await DB.getEntityFile('dossier', editId, origLang);
      if (!existingOrig) { alert(t('dossOrigFileRequired')); return; }
    } else {
      alert(t('dossOrigFileRequired'));
      return;
    }
  }

  const transPending = hasCertTransl ? (state.pendingFiles[transLang] || []) : [];
  const newAlldigCards = _alldigCards.filter(c => !c.existing && c.files.length > 0);
  const alldigFileCount = newAlldigCards.reduce((s, c) => s + c.files.length, 0);
  const totalFiles = origPending.length + transPending.length + alldigFileCount;
  let savedCount = 0;

  _dossShowSaveProgress(0, totalFiles, '');

  const proceedingId = parseInt(document.getElementById('fDossProcId').value);
  const data = { title, proceedingId, origLang, hasCertTranslation: hasCertTransl };

  let entityId;
  if (editId) {
    await DB.updateDossier(editId, data);
    entityId = editId;
    state.selection = { type: 'dossier', id: editId };
  } else {
    const d = await DB.createDossier(data);
    entityId = d.id;
    state.selection = { type: 'dossier', id: d.id };
    state.expanded['proceeding_' + proceedingId] = true;
    state.expanded['dossier_' + d.id] = true;
  }

  const _dossProc = await DB.getProceeding(proceedingId);
  const _dossHier = { caseId: _dossProc ? _dossProc.caseId : null, proceedingId, dossierId: entityId };

  for (const f of origPending) {
    savedCount++;
    _dossShowSaveProgress(savedCount, totalFiles, f.name);
    await storeFileForEntity(f, 'dossier', entityId, origLang, _dossHier, 'doss_orig');
  }
  for (const f of transPending) {
    savedCount++;
    _dossShowSaveProgress(savedCount, totalFiles, f.name);
    await storeFileForEntity(f, 'dossier', entityId, transLang, _dossHier, 'doss_cert');
  }

  if (newAlldigCards.length > 0) {
    const existingAlldigFiles = await DB.getEntityFiles('dossier', entityId).then(fs => fs.filter(f => f.fileRole === 'doss_alldig'));
    const existingNums = new Set();
    for (const f of existingAlldigFiles) {
      const m = (f.storagePath || '').match(/_DDP(\d+)/);
      if (m) existingNums.add(parseInt(m[1], 10));
    }
    let nextNum = existingNums.size > 0 ? (Math.max(...existingNums) + 1) : 1;
    for (const card of newAlldigCards) {
      const alldigNum = String(nextNum).padStart(3, '0');
      nextNum++;
      for (const f of card.files) {
        savedCount++;
        _dossShowSaveProgress(savedCount, totalFiles, f.name);
        await _storeAlldigFile(f, entityId, origLang, _dossHier, alldigNum, card.desc);
      }
    }
  }

  state.pendingFiles = { it: [], en: [] };
  _alldigCards = [];
  state.dossWizard = { step: 1, origLang: null, hasCertTransl: false, proceedingId: null, editId: null, title: '' };
  state.openForm = null;
  await renderAll();
}

async function syncBlobFilesToDisk() {
  if (!FS_FILES_HANDLE) {
    alert(t('syncDiskNoFolder') || 'Collega prima una cartella di lavoro.'); return;
  }
  const allFiles = await db.files.toArray();
  const unsync = allFiles.filter(f => f.blob && f.blob.byteLength > 0 && (!f.storagePath || f.storagePath === ''));
  if (unsync.length === 0) {
    let freed = 0;
    for (const f of allFiles) {
      if (f.blob && f.blob.byteLength > 0 && f.storagePath && f.storagePath !== '') {
        try { await DB.updateFile(f.id, { blob: null }); freed++; } catch (_) {}
      }
    }
    alert(freed > 0
      ? '✅ Tutti i file sono su disco.\n🗑️ ' + freed + ' blob liberati dalla memoria browser.'
      : (t('syncDiskNone') || '✅ Tutti i file sono già su disco e la memoria è pulita.'));
    return;
  }

  const ddpMap = {};
  for (const f of allFiles) {
    if (f.fileRole === 'doss_alldig' && f.storagePath) {
      const m = f.storagePath.match(/_DDP(\d+)/i);
      if (m && f.dossierId) {
        if (!ddpMap[f.dossierId]) ddpMap[f.dossierId] = new Set();
        ddpMap[f.dossierId].add(parseInt(m[1], 10));
      }
    }
  }

  let done = 0; let failed = 0;
  const total = unsync.length;
  const origIdxMap = {};

  for (const f of unsync) {
    try {
      const rawBuf = f.blob instanceof Uint8Array ? f.blob.buffer : f.blob;
      const fileObj = new File([rawBuf], f.fileName || 'file', { type: f.fileType || 'application/octet-stream' });
      let extraOpts = {};

      if ((f.fileRole === 'doss_orig' || f.fileRole === 'doss_cert') && f.dossierId) {
        const roleKey = f.fileRole + '_' + f.dossierId;
        if (!origIdxMap[roleKey]) origIdxMap[roleKey] = 1;
        extraOpts = { origName: f.fileName, fileIdx: origIdxMap[roleKey]++ };
      } else if (f.fileRole === 'doss_alldig' && f.dossierId) {
        if (!ddpMap[f.dossierId]) ddpMap[f.dossierId] = new Set();
        let nextNum = ddpMap[f.dossierId].size > 0 ? Math.max(...ddpMap[f.dossierId]) + 1 : 1;
        ddpMap[f.dossierId].add(nextNum);
        extraOpts = { alldigNum: String(nextNum).padStart(3, '0') };
      }

      const result = await saveFileToFS(fileObj, f.entityType || 'dossier', f.entityId, f.lang || 'it', f.fileRole, extraOpts, rawBuf);
      if (result) {
        await DB.updateFile(f.id, { storagePath: result.storagePath, diskFileName: result.diskFileName, blob: null });
        done++;
      } else {
        failed++;
      }
    } catch (err) {
      console.error('syncBlobFilesToDisk: errore su file', f.id, f.fileName, err);
      failed++;
    }
  }

  let freed = 0;
  const alreadySynced = allFiles.filter(f => f.blob && f.blob.byteLength > 0 && f.storagePath && f.storagePath !== '' && !unsync.find(u => u.id === f.id));
  for (const f of alreadySynced) {
    try { await DB.updateFile(f.id, { blob: null }); freed++; } catch (_) {}
  }

  const parts = [];
  if (done > 0) parts.push('✅ ' + done + ' ' + (t('syncDiskDone') || 'file sincronizzati su disco'));
  if (freed > 0) parts.push('🗑️ ' + freed + ' blob liberati dalla memoria browser');
  if (failed > 0) parts.push('⚠️ ' + failed + ' errori (controlla la console)');
  if (parts.length === 0) parts.push('✅ Memoria browser già pulita.');
  alert(parts.join('\n'));
}

async function _storeAlldigFile(file, entityId, lang, hierarchy, alldigNum, notes, depositDate, notesEn) {
  const buf = await file.arrayBuffer();
  const hashBuf = await crypto.subtle.digest('SHA-256', buf);
  const hash = Array.from(new Uint8Array(hashBuf)).map(b => b.toString(16).padStart(2, '0')).join('');
  // Persistenza obbligatoria sul disco (vedi storeFileForEntity): mai
  // salvare il file fisico come blob nel database.
  if (!FS_FILES_HANDLE && typeof connectFS === 'function') {
    try { await connectFS(); } catch (_) {}
  }
  if (!FS_FILES_HANDLE) {
    alert(t('fsRequired'));
    return null;
  }
  const result = await saveFileToFS(file, 'dossier', entityId, lang, 'doss_alldig', { alldigNum });
  if (!result) {
    console.error('saveFileToFS failed for', file.name, '- aborting alldig file persistence');
    alert(t('fsRequired'));
    return null;
  }
  const storagePath = result.storagePath;
  const diskFileName = result.diskFileName;
  const h = hierarchy || {};
  const newId = await DB.createFile({
    entityType: 'dossier', entityId, lang,
    actId: 0,
    caseId: h.caseId || null, proceedingId: h.proceedingId || null, dossierId: h.dossierId || null,
    fileName: file.name, fileSize: file.size, fileType: file.type || 'application/octet-stream',
    hash, storagePath, diskFileName,
    blob: null,
    fileRole: 'doss_alldig',
    notes: notes || '',
    notesEn: notesEn || '',
    depositDate: depositDate || '',
    createdAt: await _extractFileDate(file),
    ...await (async () => { const r = await _extractDeviceInfo(file); return { deviceInfo: (r&&r.device)||null, serialInfo: (r&&r.serial)||null }; })()
  });
  return newId;
}

