  const certLang = origLang === 'it' ? 'en' : 'it';
  const lang = (role === 'cert' || role === 'ddp_cert') ? certLang : origLang;
  state.pendingFiles = { it: [], en: [] };
  _alldigCards = [];
  const _L = currentLang === 'en';
  let titleText, bodyHtml;
