const _FONTE_SHORT_NAMES = {
  101: { short: 'Cost.', css: 'fonte-cost' },
  102: { short: 'C.P.', css: 'fonte-penale' },
  103: { short: 'C.P.P.', css: 'fonte-proc-pen' },
  104: { short: 'C.C.', css: 'fonte-civile' },
  105: { short: 'C.P.C.', css: 'fonte-proc-civ' },
  201: { short: 'TFUE', css: 'fonte-ue' },
  202: { short: 'TUE', css: 'fonte-ue' },
  203: { short: 'CDFUE', css: 'fonte-ue' },
  301: { short: 'CEDU', css: 'fonte-cedu' },
  401: { short: 'ONU', css: 'fonte-onu' },
  501: { short: 'CPI', css: 'fonte-cpi' },
};

if (!state._fontiCache) state._fontiCache = {};

async function _getFonteInfo(idFonte) {
  if (!idFonte) return { short: '?', css: '', name: '' };
  if (state._fontiCache[idFonte]) return state._fontiCache[idFonte];
  const known = _FONTE_SHORT_NAMES[idFonte];
  if (known) {
    const fonte = await NormDB.getFonte(idFonte);
    const info = { short: known.short, css: known.css, name: fonte ? (currentLang === 'en' && fonte.nome_en ? fonte.nome_en : fonte.nome) : known.short };
    state._fontiCache[idFonte] = info;
    return info;
  }
  const fonte = await NormDB.getFonte(idFonte);
  if (!fonte) { state._fontiCache[idFonte] = { short: '?', css: '', name: '?' }; return state._fontiCache[idFonte]; }
  const name = currentLang === 'en' && fonte.nome_en ? fonte.nome_en : fonte.nome;
  const short = name.length > 10 ? name.substring(0, 8) + '.' : name;
  const css = fonte.id_sistema === 1 ? '' : (fonte.id_sistema === 2 ? 'fonte-ue' : (fonte.id_sistema === 3 ? 'fonte-cedu' : ((idFonte >= 400 && idFonte < 500) ? 'fonte-onu' : ((idFonte >= 500 && idFonte < 600) ? 'fonte-cpi' : 'fonte-int'))));
  state._fontiCache[idFonte] = { short, css, name };
  return state._fontiCache[idFonte];
}

function _fonteBadgeHtml(fonteInfo) {
  const css = fonteInfo.css || '';
  const jur = css === 'fonte-ue' ? 'UE' : css === 'fonte-cedu' ? 'CEDU' : css === 'fonte-onu' ? 'ONU' : css === 'fonte-cpi' ? 'CPI' : css === 'fonte-int' ? 'INT' : 'IT';
  return `<span class="violation-fonte-jur vfj-${jur.toLowerCase()}">${jur}</span><span class="violation-fonte-badge ${css}" title="${esc(fonteInfo.name)}">${esc(fonteInfo.short)}</span>`;
}

function _violationBadgesHtml(fonteInfo, normaCode) {
  const css = fonteInfo.css || '';
  const jur = css === 'fonte-ue' ? 'UE' : css === 'fonte-cedu' ? 'CEDU' : css === 'fonte-onu' ? 'ONU' : css === 'fonte-cpi' ? 'CPI' : css === 'fonte-int' ? 'INT' : 'IT';
  return `<span class="violation-fonte-jur vfj-${jur.toLowerCase()}">${jur}</span><span class="violation-fonte-badge ${css}" title="${esc(fonteInfo.name)}">${esc(fonteInfo.short)}</span>`;
}

async function _enrichViolNormBadges(container) {
  const placeholders = (container || document).querySelectorAll('.viol-norm-placeholder[data-nid]:not([data-enriched])');
  for (const el of placeholders) {
    const normaId = parseInt(el.dataset.nid);
    const code = el.dataset.code || '';
    if (!normaId) continue;
    el.setAttribute('data-enriched', '1');
    try {
      const nodo = await NormDB.getNodo(normaId);
      if (!nodo || !nodo.id_fonte) continue;
      const fonteInfo = await _getFonteInfo(nodo.id_fonte);
      const html = _violationBadgesHtml(fonteInfo, code);
      el.innerHTML = html;
    } catch(e) { /* skip */ }
  }
}

function _fonteFullName(fonteInfo) {
  return fonteInfo.name || fonteInfo.short || '?';
}

function _fonteCssSync(fonte) {
  const known = _FONTE_SHORT_NAMES[fonte.id];
  if (known) return known.css;
  if (fonte.id_sistema === 2) return 'fonte-ue';
  if (fonte.id_sistema === 3) return 'fonte-cedu';
  const fid = fonte.id || 0;
  if (fid >= 400 && fid < 500) return 'fonte-onu';
  if (fid >= 500 && fid < 600) return 'fonte-cpi';
  if (fonte.id_sistema && fonte.id_sistema > 1) return 'fonte-int';
  return '';
}

function _closeNormPickerModal() {
  const overlay = document.querySelector('.norm-picker-overlay');
  if (overlay) overlay.remove();
}

function _normPickerAddLabel(context) {
  if (context === 'circ-norm') return t('add') || 'Aggiungi';
  return t('addViolation') || 'Aggiungi violazione';
}

async function _openNormPickerModal(context, factId, circId) {
  _closeNormPickerModal();
  state._normPickerContext = context;
  state._normPickerFactId = factId || null;
  state._normPickerCircId = circId || null;
  state._normPickerSelectedNodeId = null;
  state._normPickerExpandedNodes = new Set();
  state._normPickerSearchQuery = '';
  state._normPickerLang = (currentLang === 'en') ? 'en' : 'it';

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay norm-picker-overlay';
  const modal = document.createElement('div');
  modal.className = 'modal-content norm-picker-modal';
  modal.innerHTML = `
    <div class="norm-picker-header">
      <h3 style="margin:0;flex:1">${t('normPickerModalTitle')}</h3>
      <div class="np-lang-toggle" id="npLangToggle" style="display:inline-flex;gap:4px;margin-right:12px">
        <button class="btn btn-xs" id="npLangIt" onclick="_normPickerSetLang('it')" data-testid="btn-norm-picker-lang-it">IT</button>
        <button class="btn btn-xs" id="npLangEn" onclick="_normPickerSetLang('en')" data-testid="btn-norm-picker-lang-en">EN</button>
      </div>
      <button class="btn btn-sm btn-primary" id="npAddBtn" onclick="_normPickerDoAdd()" disabled data-testid="btn-norm-picker-add" style="margin-right:8px">${esc(_normPickerAddLabel(context))}</button>
      <button class="norm-picker-close-btn" onclick="_closeNormPickerModal()" data-testid="btn-close-norm-picker-x" title="${t('close')}">&#10005;</button>
    </div>
    <div class="norme-layout" style="flex:1;min-height:0">
      <div class="norme-sidebar" style="width:420px">
        <div class="norme-search">
          <input type="text" id="npSearchInput" placeholder="${t('normeSearch')}" oninput="_normPickerOnSearch(this.value)" data-testid="input-norm-picker-search" />
        </div>
        <div class="norme-tree" id="npTree">
          <p class="hint" style="padding:12px">${t('normPickerLoadingCorpus') || 'Caricamento…'}</p>
        </div>
      </div>
      <div class="norme-detail" id="npDetail">
        <div class="norme-empty"><p>${t('normeNoArticle') || 'Seleziona un nodo'}</p></div>
      </div>
    </div>
  `;
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });

  if (!_normeState.allNodi || _normeState.allNodi.length === 0) {
    _normeState.allNodi = await NormDB.getAllNodi();
  }
  _normPickerRenderLangToggle();
  _normPickerRenderTree();
}

function _normPickerRenderLangToggle() {
  const itBtn = document.getElementById('npLangIt');
  const enBtn = document.getElementById('npLangEn');
  if (!itBtn || !enBtn) return;
  const lang = state._normPickerLang || 'it';
  itBtn.classList.toggle('btn-primary', lang === 'it');
  itBtn.classList.toggle('btn-secondary', lang !== 'it');
  enBtn.classList.toggle('btn-primary', lang === 'en');
  enBtn.classList.toggle('btn-secondary', lang !== 'en');
}

function _normPickerSetLang(lang) {
  state._normPickerLang = lang;
  _normPickerRenderLangToggle();
  if (state._normPickerSelectedNodeId) _normPickerRenderDetail();
}

function _normPickerOnSearch(val) {
  state._normPickerSearchQuery = val || '';
  _normPickerRenderTree();
  const inp = document.getElementById('npSearchInput');
  if (inp) { inp.focus(); inp.setSelectionRange(val.length, val.length); }
}

function _normPickerToggleNode(id) {
  const exp = state._normPickerExpandedNodes;
  if (exp.has(id)) exp.delete(id); else exp.add(id);
  _normPickerRenderTree();
}

function _normPickerToggleAndSelect(id) {
  const exp = state._normPickerExpandedNodes;
  if (exp.has(id)) exp.delete(id); else exp.add(id);
  _normPickerSelectNode(id);
}

function _normPickerSelectNode(id) {
  state._normPickerSelectedNodeId = id;
  const node = _normeState.allNodi.find(n => n.id === id);
  if (node) {
    let cur = node;
    while (cur && cur.id_padre) {
      state._normPickerExpandedNodes.add(cur.id_padre);
      cur = _normeState.allNodi.find(n => n.id === cur.id_padre);
    }
  }
  _normPickerRenderTree();
  _normPickerRenderDetail();
  _normPickerUpdateAddBtn();
}

function _normPickerUpdateAddBtn() {
  const btn = document.getElementById('npAddBtn');
  if (!btn) return;
  const id = state._normPickerSelectedNodeId;
  const node = id ? _normeState.allNodi.find(n => n.id === id) : null;
  const ok = node && (node.tipo_nodo === 'articolo' || node.tipo_nodo === 'sentenza');
  btn.disabled = !ok;
}

function _normPickerDoAdd() {
  const id = state._normPickerSelectedNodeId;
  if (!id) return;
  const ctx = state._normPickerContext;
  const factId = state._normPickerFactId;
  const circId = state._normPickerCircId;
  if (ctx === 'fact-card') return _addFactCardViolationFromPicker(id, factId);
  if (ctx === 'circ-norm') return _addCircumstanceNormFromPicker(id, circId);
  if (ctx === 'fact-edit') return _addEditFactViolationFromPicker(id, factId);
  if (ctx === 'analysis') return _addViolationFromPicker(id);
  if (ctx === 'fact') return _addFactViolationFromPicker(id, factId);
}

function _normPickerRenderTreeNode(node, depth) {
  const allNodi = _normeState.allNodi;
  const children = allNodi.filter(n => n.id_padre === node.id);
  const hasChildren = children.length > 0;
  const isRoot = node.tipo_nodo === 'sistema';
  const isExpanded = state._normPickerExpandedNodes.has(node.id);
  const sel = node.id === state._normPickerSelectedNodeId ? ' norme-node-selected' : '';
  const inactive = node.vigente === false ? ' norme-node-inactive' : '';
  const rowClick = hasChildren ? `_normPickerToggleAndSelect(${node.id})` : `_normPickerSelectNode(${node.id})`;
  let html = `<div class="norme-tree-item${sel}${inactive}${isRoot ? ' norme-tree-sistema' : ''}" style="padding-left:${depth * 18 + 6}px" onclick="${rowClick}" data-testid="np-tree-node-${node.id}">`;
  if (hasChildren) {
    html += `<span class="norme-toggle">${isExpanded ? '▼' : '▶'}</span>`;
  } else {
    html += `<span class="norme-toggle-placeholder"></span>`;
  }
  html += `<span class="norme-node-label">`;
  const _artLbl = _normeArticleLabel(node, allNodi);
  const _flag = depth === 0 ? _sistemaFlag(node.rubrica) : null;
  if (_artLbl) {
    html += `<span class="norme-node-badge norme-badge-articolo">${esc(_normeNodeTypeLabel('articolo'))}</span> `;
    html += `${esc(_artLbl)}`;
  } else if (_flag) {
    html += `<span class="norme-node-badge norme-badge-sistema" style="font-size:14px;background:none;border:none;padding:0 2px;box-shadow:none">${_flag}</span> `;
    html += `${esc(node.numero ? node.numero + '. ' : '')}${esc(_nn(node))}`;
  } else {
    html += `<span class="norme-node-badge norme-badge-${node.tipo_nodo || 'default'}">${esc(node.badge || _normeNodeTypeLabel(node.tipo_nodo))}</span> `;
    html += `${esc(node.numero ? node.numero + '. ' : '')}${esc(_nn(node))}`;
  }
  html += `</span></div>`;
  if (isExpanded && hasChildren) {
    if (!isRoot) {
      children.sort((a, b) => (a.numero || '').localeCompare(b.numero || '', undefined, {numeric: true}));
    }
    children.forEach(c => { html += _normPickerRenderTreeNode(c, depth + 1); });
  }
  return html;
}

function _normPickerRenderTree() {
  const tree = document.getElementById('npTree');
  if (!tree) return;
  const q = (state._normPickerSearchQuery || '').trim();
  let html = '';
  if (q) {
    const tokens = q.toLowerCase().split(/\s+/).filter(Boolean);
    const allNodi = _normeState.allNodi;
    const nodeSearchText = new Map();
    allNodi.forEach(n => {
      const parts = [(n.rubrica||''), (n.rubrica_en||''), (n.numero||''), (n.tipo_nodo||''), (n.badge||''), (n.testo_it||'').substring(0, 300), (n.testo_en||'').substring(0, 300)];
      let cur = n.id_padre ? allNodi.find(x => x.id === n.id_padre) : null;
      while (cur) {
        parts.push(cur.rubrica||'', cur.tipo_nodo||'', cur.badge||'', cur.numero||'');
        cur = cur.id_padre ? allNodi.find(x => x.id === cur.id_padre) : null;
      }
      nodeSearchText.set(n.id, parts.join(' ').toLowerCase());
    });
    const matches = allNodi.filter(n => tokens.every(tok => nodeSearchText.get(n.id).includes(tok)));
    if (matches.length === 0) {
      html += `<p class="hint" style="padding:12px">${t('normeNoResults') || 'Nessun risultato'}</p>`;
    } else {
      matches.forEach(n => {
        const lang = state._normPickerLang || 'it';
        const desc = lang === 'en' ? (n.testo_en || n.testo_it || '') : (n.testo_it || n.testo_en || '');
        const descPreview = desc.length > 120 ? desc.substring(0, 120) + '…' : desc;
        const _srchSrc = _getNodeSourceLabel(n, allNodi);
        const rootFlag = _getNodeRootFlag(n, allNodi);
        const sel = n.id === state._normPickerSelectedNodeId ? ' norme-node-selected' : '';
        html += `<div class="norme-search-result${sel}" onclick="_normPickerSelectNode(${n.id})" data-testid="np-search-result-${n.id}">`;
        html += `<div class="norme-search-result-row">`;
        if (rootFlag) html += `<span class="norme-search-flag" style="flex-shrink:0">${rootFlag}</span>`;
        html += `<span class="norme-node-badge" style="flex-shrink:0">${esc(n.badge || _normeNodeTypeLabel(n.tipo_nodo))}</span>`;
        if (_srchSrc) html += `<span class="norme-source-badge ${_srchSrc.cls}" style="flex-shrink:0">${esc(_srchSrc.label)}</span>`;
        html += `<strong style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(_nn(n))}</strong>`;
        html += `</div>`;
        if (descPreview) html += `<div class="norme-path-hint">${esc(descPreview)}</div>`;
        html += `</div>`;
      });
    }
  } else {
    const roots = _normeState.allNodi.filter(n => !n.id_padre);
    const sistemaOrder = { 'unione europea': 1, 'consiglio d\'europa': 2, 'organizzazione delle nazioni unite': 3, 'corte penale internazionale': 4, 'italia': 5 };
    roots.sort((a, b) => {
      const oa = sistemaOrder[(a.rubrica || '').toLowerCase()] || 3;
      const ob = sistemaOrder[(b.rubrica || '').toLowerCase()] || 3;
      return oa - ob;
    });
    roots.forEach(n => { html += _normPickerRenderTreeNode(n, 0); });
    if (roots.length === 0) html += `<p class="hint" style="padding:12px">${t('normeNoNodes') || 'Nessun nodo'}</p>`;
  }
  tree.innerHTML = html;
}

function _normPickerRenderDetail() {
  const panel = document.getElementById('npDetail');
  if (!panel) return;
  const id = state._normPickerSelectedNodeId;
  if (!id) {
    panel.innerHTML = `<div class="norme-empty"><p>${t('normeNoArticle') || 'Seleziona un nodo'}</p></div>`;
    return;
  }
  const allNodi = _normeState.allNodi;
  const node = allNodi.find(n => n.id === id);
  if (!node) {
    panel.innerHTML = `<div class="norme-empty"><p>${t('normeNoArticle') || 'Nodo non trovato'}</p></div>`;
    return;
  }
  const lang = state._normPickerLang || 'it';
  const path = NormDB.buildNodoPath(node, allNodi, lang);
  let html = `<div class="norme-detail-content">`;
  html += `<div class="norme-detail-header">`;
  html += `<div class="norme-path-breadcrumb">${esc(path)}</div>`;
  const _detailArtLbl = _normeArticleLabel(node, allNodi);
  const _detailFlag = _getNodeRootFlag(node, allNodi);
  const _flagHtml = _detailFlag ? `<span class="norme-detail-flag">${_detailFlag}</span>` : '';
  const _srcLabel = _getNodeSourceLabel(node, allNodi);
  const _srcBadge = _srcLabel ? `<span class="norme-source-badge ${_srcLabel.cls}">${esc(_srcLabel.label)}</span>` : '';
  if (_detailArtLbl) {
    html += `<h2>${_flagHtml}${esc(_detailArtLbl)}</h2>`;
    html += `<div class="norme-detail-badges"><span class="norme-node-badge norme-badge-articolo">${esc(_normeNodeTypeLabel('articolo'))}</span>${_srcBadge}</div>`;
  } else {
    html += `<h2>${_flagHtml}${esc(node.numero ? node.numero + '. ' : '')}${esc(_nn(node))}</h2>`;
    html += `<div class="norme-detail-badges"><span class="norme-node-badge norme-badge-${node.tipo_nodo || 'default'}">${esc(node.badge || _normeNodeTypeLabel(node.tipo_nodo))}</span>${_srcBadge}</div>`;
  }
  html += `<div class="norme-meta-row">`;
  if (node.data_inizio_vigenza) html += `<span class="norme-meta-tag">${t('normeNodeStartDate')}: ${esc(node.data_inizio_vigenza)}</span>`;
  if (node.vigente === false) html += `<span class="norme-meta-tag norme-tag-inactive">${t('normeInactive')}</span>`;
  html += `</div></div>`;
  const txt = lang === 'en' ? (node.testo_en || node.descrizione_en || '') : (node.testo_it || node.descrizioneIt || '');
  html += `<div class="norme-text-block">`;
  html += `<div class="norme-text-section">`;
  html += `<div class="norme-text-header"><span class="norme-text-lang-label${lang === 'en' ? ' norme-text-alt' : ''}">${lang.toUpperCase()}</span></div>`;
  html += txt ? `<pre>${esc(txt)}</pre>` : `<p class="hint">${t('translationNotAvailable') || 'Traduzione non disponibile'}</p>`;
  html += `</div></div>`;
  if (node.tipo_nodo === 'sentenza') {
    html += `<div class="norme-linked-refs" id="normeLinkedRefs"></div>`;
    setTimeout(() => _renderSentenzaLinkedArticles(node.id), 0);
  }
  if (node.tipo_nodo === 'articolo') {
    html += `<div class="norme-article-sections" id="normeArticleSections"></div>`;
    setTimeout(() => _renderNormeArticleSections(node), 0);
    if (_isUnderCedu(node)) {
      html += `<div class="norme-linked-refs" id="normeLinkedSentenze"></div>`;
      setTimeout(() => _renderArticleLinkedSentenze(node.id), 0);
    }
  }
  html += `</div>`;
  panel.innerHTML = html;
}


async function _getSubjectsWithRolesForFact(factId) {
  const result = [];
  try {
    if (factId) {
      const fact = await DB.getFact(factId);
      if (fact && fact.dossierId) {
        const dossier = await DB.getDossier(fact.dossierId);
        if (dossier && dossier.proceedingId) {
          const roles = await DB.getProceedingRoles(dossier.proceedingId);
          const map = {};
          for (const r of roles) {
            if (!r.subject) continue;
            if (!map[r.subject.id]) map[r.subject.id] = { subject: r.subject, roles: [] };
            map[r.subject.id].roles.push({ roleId: r.id, roleCode: r.roleCode });
          }
          for (const sid of Object.keys(map)) result.push(map[sid]);
        }
      }
    }
  } catch(e) { /* skip */ }
  return result;
}

async function _showSubjectPickerBeforePicker(factId, callback) {
  const subjectsWithRoles = await _getSubjectsWithRolesForFact(factId);
  if (!subjectsWithRoles.length) {
    state._normPickerPreSelectedSubjectIds = [];
    callback();
    return;
  }

  const existingOverlay = document.querySelector('.np-subject-pre-overlay');
  if (existingOverlay) existingOverlay.remove();

  const linkedPairs = [];
  let selectedSubjectId = null;

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay np-subject-pre-overlay';
  overlay.style.cssText = 'z-index:10100;display:flex;align-items:center;justify-content:center';

  function renderModal() {
    const subjectItems = subjectsWithRoles.map(sw => {
      const s = sw.subject;
      const name = [s.firstName, s.lastName].filter(Boolean).join(' ');
      const isLinked = linkedPairs.some(p => p.subjectId === s.id);
      const isSel = selectedSubjectId === s.id;
      return `<div class="np-sr-subject-item${isSel ? ' np-sr-selected' : ''}${isLinked ? ' np-sr-linked' : ''}" data-sid="${s.id}" data-testid="np-sr-subject-${s.id}">
        <span>${esc(name)}</span>
        ${isLinked ? '<span class="np-sr-check">✓</span>' : ''}
      </div>`;
    }).join('');

    let rolePanel = `<div class="np-sr-role-empty"><p>${t('subjectPickerSelectSubject')}</p></div>`;
    if (selectedSubjectId) {
      const sw = subjectsWithRoles.find(sw => sw.subject.id === selectedSubjectId);
      if (sw && sw.roles.length > 0) {
        const roleItems = sw.roles.map(r => {
          const isRoleLinked = linkedPairs.some(p => p.subjectId === selectedSubjectId && p.roleId === r.roleId);
          return `<div class="np-sr-role-item${isRoleLinked ? ' np-sr-role-linked' : ''}" data-rid="${r.roleId}" data-sid="${selectedSubjectId}" data-testid="np-sr-role-${r.roleId}">
            <span>${esc(tRole(r.roleCode))}</span>
            ${isRoleLinked ? `<span class="np-sr-check">${t('subjectPickerLinked')}</span>` : `<button class="btn btn-xs btn-primary np-sr-link-btn" data-testid="np-sr-link-${r.roleId}">${t('linkSubjectRoleBtn')}</button>`}
          </div>`;
        }).join('');
        rolePanel = `<div class="np-sr-role-list">${roleItems}</div>`;
      } else {
        rolePanel = `<div class="np-sr-role-empty"><p>${t('subjectPickerNoRoles')}</p></div>`;
      }
    }

    overlay.innerHTML = `
      <div class="np-sr-modal" data-testid="np-sr-modal">
        <div class="np-sr-header">
          <span class="np-sr-title">${t('selectSubjectFirst')}</span>
        </div>
        <div class="np-sr-hint">${t('selectSubjectFirstNorm')}</div>
        <div class="np-sr-columns">
          <div class="np-sr-col np-sr-col-subjects">
            <div class="np-sr-col-title">
              <span>${t('subjectPickerSubjects')}</span>
            </div>
            <div class="np-sr-col-body">${subjectItems}</div>
          </div>
          <div class="np-sr-col np-sr-col-roles">
            <div class="np-sr-col-title">${t('subjectPickerRoles')}</div>
            <div class="np-sr-col-body">${rolePanel}</div>
          </div>
        </div>
        <div class="np-sr-footer">
          <button class="btn btn-xs" id="btnNoSubjectPre" data-testid="btn-no-subject-pre">${t('noSubjectBtn')}</button>
          <button class="btn btn-xs btn-primary" id="btnContinueSubjectPre" data-testid="btn-continue-subject-pre">${t('continueBtn')}</button>
        </div>
      </div>
    `;

    overlay.querySelectorAll('.np-sr-subject-item').forEach(el => {
      el.addEventListener('click', () => {
        selectedSubjectId = parseInt(el.dataset.sid);
        renderModal();
      });
    });

    overlay.querySelectorAll('.np-sr-link-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const item = btn.closest('.np-sr-role-item');
        const sid = parseInt(item.dataset.sid);
        const rid = parseInt(item.dataset.rid);
        if (!linkedPairs.some(p => p.subjectId === sid && p.roleId === rid)) {
          linkedPairs.push({ subjectId: sid, roleId: rid });
        }
        renderModal();
      });
    });

    const newSubjBtn = document.getElementById('btnNewSubjectInPicker');
    if (newSubjBtn) {
      newSubjBtn.addEventListener('click', () => {
        _openNewSubjectInline(async (newId, newSubject) => {
          const refreshed = await _getSubjectsWithRolesForFact(factId);
          const alreadyIn = refreshed.some(sw => sw.subject.id === newId);
          if (!alreadyIn) {
            refreshed.push({ subject: { ...newSubject, id: newId }, roles: [] });
          }
          subjectsWithRoles.length = 0;
          for (const item of refreshed) subjectsWithRoles.push(item);
          selectedSubjectId = newId;
          renderModal();
        });
      });
    }

    document.getElementById('btnNoSubjectPre').addEventListener('click', () => {
      state._normPickerPreSelectedSubjectIds = [];
      overlay.remove();
      callback();
    });
    document.getElementById('btnContinueSubjectPre').addEventListener('click', () => {
      state._normPickerPreSelectedSubjectIds = linkedPairs.length > 0 ? linkedPairs : [];
      overlay.remove();
      callback();
    });
  }

  document.body.appendChild(overlay);
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  renderModal();
}

async function _openNormPickerWithSubjectPre(context, factId, circId) {
  if (context === 'analysis' || !factId) {
    state._normPickerPreSelectedSubjectIds = [];
    _openNormPickerModal(context, factId, circId);
    return;
  }
  await _showSubjectPickerBeforePicker(factId, () => {
    _openNormPickerModal(context, factId, circId);
  });
}

async function _openNewSubjectInline(onSaved) {
  await _loadAllLists();

  const existing = document.querySelector('.np-new-subject-overlay');
  if (existing) existing.remove();

  const _localRoles = [];
  const ROLES_CONTAINER = 'nsiSubjectRolesContainer';

  function _nsiRenderRoles() {
    const container = document.getElementById(ROLES_CONTAINER);
    if (!container) return;
    if (_localRoles.length === 0) {
      container.innerHTML = '<p class="hint">' + t('noRolesAssigned') + '</p>';
      return;
    }
    container.innerHTML = _localRoles.map((r, idx) => {
      const currentLabel = _getCurrentRoleLabel ? _getCurrentRoleLabel(r) : (r._roleLabel || '');
      return `
      <div class="repeatable-group">
        <div class="repeatable-group-header">
          <span class="repeatable-group-num">#${idx + 1}</span>
          <button class="btn btn-xs btn-danger" onclick="_nsiRemoveRole(${idx})">${t('removeRole')}</button>
        </div>
        <div class="form-row form-row-5col">
          <div class="form-group form-group-fifth">
            <label>${t('startDate')} (IN)</label>
            <input type="date" value="${r.startDate || ''}" onchange="_nsiRoleChange(${idx},'startDate',this.value)">
          </div>
          <div class="form-group form-group-fifth">
            <label>${t('endDate')} (OUT)</label>
            <input type="date" value="${r.endDate || ''}" onchange="_nsiRoleChange(${idx},'endDate',this.value)">
          </div>
          <div class="form-group form-group-fifth autocomplete-wrap" style="flex:2 1 0">
            <label>${t('subjectRole')}</label>
            <input id="nsiRole_role_${idx}" value="${esc(currentLabel)}" autocomplete="off" placeholder="${t('searchRolePlaceholder')}">
            <div id="nsiRole_role_${idx}_suggestions" class="autocomplete-list"></div>
          </div>
          <div class="form-group form-group-fifth autocomplete-wrap">
            <label>${t('sede')}</label>
            <input value="${esc(r.citta || '')}" autocomplete="off" placeholder="${t('citta')}..." onchange="_nsiRoleChange(${idx},'citta',this.value)">
          </div>
        </div>
      </div>`;
    }).join('');
    _localRoles.forEach((r, idx) => {
      setupRoleAutocomplete(`nsiRole_role_${idx}`, `nsiRole_role_${idx}_suggestions`, _localRoles, idx, _nsiRenderRoles);
    });
  }
  window._nsiRemoveRole = (idx) => { _localRoles.splice(idx, 1); _nsiRenderRoles(); };
  window._nsiRoleChange = (idx, field, val) => { if (_localRoles[idx]) _localRoles[idx][field] = val; };

  const ol = document.createElement('div');
  ol.className = 'modal-overlay np-new-subject-overlay';
  ol.style.cssText = 'z-index:10200;display:flex;align-items:center;justify-content:center';
  ol.innerHTML = `
    <div class="np-sr-modal" style="max-width:560px;max-height:85vh" data-testid="np-new-subject-modal">
      <div class="np-sr-header"><span class="np-sr-title">${t('newSubject')}</span></div>
      <div style="overflow-y:auto;flex:1;padding:16px">
        <div class="form-row">
          <div class="form-group" style="flex:0 0 182px;position:relative">
            <label>${t('salutation')}</label>
            <input id="nsiSubSalutation" autocomplete="off" data-testid="nsi-input-salutation">
            <div id="nsiSubSalutationList" class="autocomplete-list"></div>
          </div>
          <div class="form-group form-group-half">
            <label>${t('firstName')}</label>
            <input id="nsiSubFirst" required data-testid="nsi-input-first">
          </div>
          <div class="form-group form-group-half">
            <label>${t('lastName')}</label>
            <input id="nsiSubLast" required data-testid="nsi-input-last">
          </div>
          <div class="form-group" style="flex:0 0 160px;position:relative">
            <label>${t('origin')}</label>
            <input id="nsiSubOrigin" autocomplete="off" data-testid="nsi-input-origin">
            <div id="nsiSubOriginList" class="autocomplete-list"></div>
          </div>
        </div>
        <div style="display:flex;gap:12px">
          <div class="form-group" style="flex:1">
            <label>${t('descrIt')}</label>
            <textarea id="nsiSubDescrIt" data-rte="1" rows="2"></textarea>
          </div>
          <div style="display:flex;flex-direction:column;gap:4px;justify-content:center;padding-top:16px">
            ${_renderTransArrow('nsiSubDescrIt','nsiSubDescrEn','it','en')}
            ${_renderTransArrow('nsiSubDescrEn','nsiSubDescrIt','en','it')}
          </div>
          <div class="form-group" style="flex:1">
            <label>${t('descrEn')}</label>
            <textarea id="nsiSubDescrEn" data-rte="1" rows="2"></textarea>
          </div>
        </div>
        <div class="form-section-header">
          <h3>${t('rolesSection')}</h3>
          <button class="btn btn-xs btn-primary" id="nsiAddRoleBtn" data-testid="nsi-btn-add-role">${t('addRole')}</button>
        </div>
        <div id="${ROLES_CONTAINER}"></div>
      </div>
      <div class="np-sr-footer">
        <button class="btn btn-xs" id="nsiCancelBtn" data-testid="nsi-btn-cancel">${t('cancel')}</button>
        <button class="btn btn-xs btn-primary" id="nsiSaveBtn" data-testid="nsi-btn-save">${t('save')}</button>
      </div>
    </div>
  `;
  document.body.appendChild(ol);
  _nsiRenderRoles();

  try {
    setupSalutationAutocomplete('nsiSubSalutation', 'nsiSubSalutationList');
    setupCittaAutocomplete('nsiSubOrigin', 'nsiSubOriginList', {});
  } catch(e) { /* skip */ }

  ol.querySelector('#nsiAddRoleBtn').addEventListener('click', () => {
    _localRoles.push({ categoryId: null, subcategoryId: null, roleId: null, startDate: '', endDate: '', citta: '' });
    _nsiRenderRoles();
  });
  ol.querySelector('#nsiCancelBtn').addEventListener('click', () => {
    delete window._nsiRemoveRole;
    delete window._nsiRoleChange;
    ol.remove();
  });
  ol.querySelector('#nsiSaveBtn').addEventListener('click', async () => {
    const firstName = (ol.querySelector('#nsiSubFirst')?.value || '').trim();
    const lastName = (ol.querySelector('#nsiSubLast')?.value || '').trim();
    if (!firstName) { ol.querySelector('#nsiSubFirst')?.focus(); return; }
    if (!lastName) { ol.querySelector('#nsiSubLast')?.focus(); return; }
    const data = {
      firstName,
      lastName,
      salutation: (ol.querySelector('#nsiSubSalutation')?.value || '').trim(),
      origin: (ol.querySelector('#nsiSubOrigin')?.value || '').trim(),
      descriptionIt: (ol.querySelector('#nsiSubDescrIt')?.value || '').trim(),
      descriptionEn: (ol.querySelector('#nsiSubDescrEn')?.value || '').trim(),
      roles: _localRoles
    };
    const result = await DB.createSubject(data);
    const newId = result.id;
    _cachedSubjects = null;
    delete window._nsiRemoveRole;
    delete window._nsiRoleChange;
    ol.remove();
    if (onSaved) onSaved(newId, result);
  });
}

async function _linkPreSelectedSubjects(entityType, entityId) {
  const pairs = state._normPickerPreSelectedSubjectIds;
  if (pairs && pairs.length) {
    for (const p of pairs) {
      if (typeof p === 'object' && p.subjectId) {
        await DB.linkSubjectToNorm(entityType, entityId, p.subjectId, p.roleId || null);
      } else if (typeof p === 'number') {
        await DB.linkSubjectToNorm(entityType, entityId, p);
      }
    }
  }
  state._normPickerPreSelectedSubjectIds = [];
}

async function _addFactCardViolationFromPicker(normaId, factId) {
  const existing = await DB.getViolationsByFact(factId);
  const dup = existing.find(v => v.normaId === normaId);
  if (dup) {
    await _linkPreSelectedSubjects('violation', dup.id);
    _closeNormPickerModal();
    if (factId) await _updateFactAnalysisColumns(factId);
    return;
  }
  const cached = state._normPickerResults && state._normPickerResults[normaId];
  let normaCode = '', normaTitle = '';
  if (cached) { normaCode = cached.normaCode; normaTitle = cached.normaTitle; }
  else { const nodo = await NormDB.getNodo(normaId); if (nodo) { normaCode = nodo.numero || ''; normaTitle = (currentLang === 'en' && nodo.rubrica_en) ? nodo.rubrica_en : (nodo.rubrica || ''); } }
  const violation = await DB.createViolation({ factId, normaId, normaCode, normaTitle, description: '' });
  await _linkPreSelectedSubjects('violation', violation.id);
  _closeNormPickerModal();
  if (factId) await _updateFactAnalysisColumns(factId);
}

