  const funcLinks = links.filter(l => l.qualificaFunzionale);
  const highlightRoleIndices = new Set();
  for (const fl of funcLinks) {
    if (!fl.role) continue;
    roles.forEach((r, idx) => {
      const ri = _findItem(_allRoles, r.roleId) || _findItem(_allSubcategories, r.subcategoryId) || _findItem(_allCategories, r.categoryId);
      if (!ri) return;
      const labelIt = DB.getItemLabel(ri, 'it');
      const labelEn = DB.getItemLabel(ri, 'en');
      if (fl.role !== labelIt && fl.role !== labelEn) return;
      if (fl.dataQualifica) {
        const inRange = (!r.startDate || fl.dataQualifica >= r.startDate) && (!r.endDate || fl.dataQualifica <= r.endDate);
        if (inRange) highlightRoleIndices.add(idx);
      } else {
        highlightRoleIndices.add(idx);
      }
    });
  }
  const rolesHtml = _buildRolesTable(roles, highlightRoleIndices);
