      if (document.getElementById('rcIntAudio')?.checked) lines.push({ chk: true, txt: 'Copia delle registrazioni audio su supporto digitale' });
      if (document.getElementById('rcIntTelematiche')?.checked) lines.push({ chk: true, txt: 'Copia delle intercettazioni telematiche e dei flussi informatici' });
