function _depositTypeChanged() {
  const isLawyer = document.querySelector('input[name="depositoType"]:checked')?.value === 'lawyer';
  const foroGroup = document.getElementById('depositoForoGroup');
  if (foroGroup) foroGroup.style.display = isLawyer ? '' : 'none';
}

async function _generateDepositPackage() {
  const d = _depositAllData;
  const depositType = document.querySelector('input[name="depositoType"]:checked')?.value || 'lawyer';
  const depositName = document.getElementById('depositoNameInput')?.value || '';
  const depositTitle = document.getElementById('depositoTitleInput')?.value || '';
  const depositForo = document.getElementById('depositoForoInput')?.value || '';
  const depositDate = document.getElementById('depositoDateInput')?.value || new Date().toISOString().split('T')[0];
  const depositPlace = document.getElementById('depositoPlaceInput')?.value || '';

  if (!depositName.trim()) {
    alert(t('depositoName') + '!');
    return;
  }

  const selFactIds = new Set(d.facts.filter(f => _depositSelection['fact_' + f.id]).map(f => f.id));
  const linkedActIds = new Set(d.factActRelations.filter(r => selFactIds.has(r.factId)).map(r => r.actId));
  const selActIds = new Set(d.acts.filter(a => _depositSelection['act_' + a.id] || linkedActIds.has(a.id)).map(a => a.id));
  const selProofIds = new Set((d.factProofRelations || []).filter(r => selFactIds.has(r.factId)).map(r => r.proofId));
  const selProcIds = new Set(d.proceedings.filter(p => _depositSelection['proc_' + p.id]).map(p => p.id));
  const selCaseIds = new Set(d.cases.filter(c => _depositSelection['case_' + c.id]).map(c => c.id));

  const body = document.querySelector('.deposit-body');
  if (body) {
    body.innerHTML = `<div class="deposit-progress">
      <div class="deposit-progress-text">${t('depositoGenerating')}</div>
    </div>`;
  }

  // Overlay di progresso bloccante con bottone Annulla. Estende l'UX
  // del finder PEC anche al deposito: l'utente vede file/atto in lavorazione,
  // percentuale e può interrompere prima del salvataggio.
  const overlay = _uxProgressOverlay({
    title: t('depositoProgressTitle') || 'Generazione pacchetto deposito…',
    total: 1,
  });
  const isCancelled = () => overlay.isCancelled();
  // Yield al browser così l'overlay si aggiorna realmente fra una fase e l'altra.
  const _yield = () => new Promise(r => setTimeout(r, 0));

  try {
    const zip = new JSZip();
    const fileManifest = [];
    let fileCount = 0;
    const missingFiles = [];

    const selDossierIds = new Set(d.dossiers.filter(ds => {
      const _dsF = new Set((d.factDossierRelations || []).filter(r => r.dossierId === ds.id).map(r => r.factId));
      const _dsA = new Set((d.factActRelations || []).filter(r => _dsF.has(r.factId)).map(r => r.actId));
      const hasActs = d.acts.some(a => _dsA.has(a.id) && selActIds.has(a.id));
      const hasFacts = d.facts.some(f => _dsF.has(f.id) && selFactIds.has(f.id));
      return hasActs || hasFacts;
    }).map(ds => ds.id));

    const relevantFilesRaw = d.files.filter(f => {
      if (f.entityType === 'case' && selCaseIds.has(f.entityId)) return true;
      if ((f.entityType === 'proceeding' || f.entityType === 'proceeding_origin') && selProcIds.has(f.entityId)) return true;
      if (f.entityType === 'dossier' && selDossierIds.has(f.entityId)) return true;
      if (f.entityType === 'act' && selActIds.has(f.entityId)) return true;
      if (f.entityType === 'fact' && selFactIds.has(f.entityId)) return true;
      if (f.entityType === 'proof' && selProofIds.has(f.entityId)) return true;
      return false;
    });
    // Politica privacy prove-image: l'esclusione dell'originale a favore
    // dell'omissis si applica SOLO se la prova e' marcata `sensitiveImage`.
    // Per prove non sensibili l'omissis e' un semplice file derivato e
    // l'originale resta nel deposito (no alterazione silenziosa della
    // selezione probatoria). Calcolo su TUTTI i d.files per coprire anche
    // originali fuori dalla selezione corrente nel main FS path.
    const _sensitiveProofIds = new Set((d.proofs || []).filter(p => p && p.sensitiveImage).map(p => p.id));
    const _omissisOriginalIds = new Set(
      (d.files || [])
        .filter(f => f.entityType === 'proof' && f.fileRole === 'image_omissis' && f.sourceFileId != null && _sensitiveProofIds.has(f.entityId))
        .map(f => f.sourceFileId)
    );
    const relevantFiles = relevantFilesRaw.filter(f => !_omissisOriginalIds.has(f.id));
    // Disclaimer: prove sensibili PRESENTI nella selezione ma SENZA omissis.
    // Si raccolgono per essere segnalate nel manifest del deposito.
    const _sensitiveNoOmissisProofIds = new Set();
    for (const pid of _sensitiveProofIds) {
      if (!selProofIds.has(pid)) continue;
      const hasOm = (d.files || []).some(f => f.entityType === 'proof' && f.entityId === pid && f.fileRole === 'image_omissis');
      if (!hasOm) _sensitiveNoOmissisProofIds.add(pid);
    }
    // Mappa esatta path-canonico -> fileRec per matching deterministico nel
    // traversal FS (no false positive/negative da `includes(storagePath)`).
    const _normFsPath = (p) => String(p || '').replace(/\\/g,'/').replace(/^\/+|\/+$/g,'').replace(/\/+/g,'/').toLowerCase();
    const _fsPathToRec = new Map();
    for (const f of (d.files || [])) {
      if (!f || !f.storagePath) continue;
      const name = f.diskFileName || f.fileName;
      if (!name) continue;
      _fsPathToRec.set(_normFsPath(f.storagePath + '/' + name), f);
    }

    // === Filtro deposito su selezione esplicita (task #347) ===
    // Solo i file il cui record DB ha entityType 'fact' o 'dossier' e id
    // ESATTAMENTE spuntato dall'utente nell'albero di selezione finiscono
    // nello ZIP. Nessuna espansione transitiva: selezionare un fatto non
    // include i file degli altri fatti dello stesso fascicolo, e selezionare
    // un fascicolo non include i file dei fatti collegati a quel fascicolo.
    const relevantFactIds = new Set(d.facts.filter(f => _depositSelection['fact_' + f.id]).map(f => f.id));
    const relevantDossierIds = new Set(d.dossiers.filter(ds => _depositSelection['dossier_' + ds.id]).map(ds => ds.id));
    // Predicato sul file fisico: usa _fsPathToRec per recuperare il record DB
    // e accetta solo entityType fact/dossier con id nei rispettivi insiemi.
    function _isFsEntryRelevant(zipPrefix, name) {
      const rec = _fsPathToRec.get(_normFsPath(zipPrefix + '/' + name));
      if (!rec) return false;
      if (rec.entityType === 'fact' && relevantFactIds.has(rec.entityId)) return true;
      if (rec.entityType === 'dossier' && relevantDossierIds.has(rec.entityId)) return true;
      return false;
    }

    // Conta i file presenti nella DOC_ESP del filesystem per stimare il totale
    // dell'overlay quando l'utente ha collegato la cartella di lavoro.
    // Filtra in base al predicato fact<->dossier cosi' il totale mostrato
    // corrisponde al numero reale di file che finiranno nello ZIP.
    async function _countFsTree(dirHandle, zipPrefix) {
      let n = 0;
      for await (const entry of dirHandle.values()) {
        if (isCancelled()) return n;
        if (entry.kind === 'file') {
          if (_isFsEntryRelevant(zipPrefix, entry.name)) n++;
        } else if (entry.kind === 'directory') {
          try {
            const sub = await dirHandle.getDirectoryHandle(entry.name);
            n += await _countFsTree(sub, zipPrefix + '/' + entry.name);
          } catch (_) {}
        }
      }
      return n;
    }

    async function _addFsTreeToZip(dirHandle, zipPrefix, zip, fileManifest, d, totalFiles) {
      for await (const entry of dirHandle.values()) {
        if (isCancelled()) return;
        if (entry.kind === 'file') {
          try {
            // Filtro deposito (task #347): salta i file il cui record DB non
            // ha entityType 'fact'/'dossier' con id esplicitamente spuntato in
            // _depositSelection. Evita di aprire il file fisico se non serve.
            if (!_isFsEntryRelevant(zipPrefix, entry.name)) continue;
            const fileHandle = await dirHandle.getFileHandle(entry.name);
            const file = await fileHandle.getFile();
            const filePath = zipPrefix + '/' + entry.name;
            // Filtro privacy: se il file fisico corrisponde a un originale
            // di una prova-image che ha sibling `image_omissis`, escludilo
            // (verra' incluso solo l'omissis rasterizzato). Usa matching
            // esatto su path canonico per evitare collisioni storagePath.
            const _exactRec = _fsPathToRec.get(_normFsPath(filePath));
            if (_exactRec && _omissisOriginalIds.has(_exactRec.id)) {
              continue;
            }
            // Hash: calcolato solo per file ≤200 MB per evitare OOM
            let hashHex = '';
            const _HASH_LIMIT = 200 * 1024 * 1024;
            if (file.size <= _HASH_LIMIT) {
              try {
                const _hBuf = await file.arrayBuffer();
                const _hDigest = await crypto.subtle.digest('SHA-256', _hBuf);
                hashHex = Array.from(new Uint8Array(_hDigest)).map(b => b.toString(16).padStart(2,'0')).join('');
              } catch (e) { hashHex = 'N/A'; }
            } else {
              hashHex = '(file > 200 MB – non calcolato)';
            }
            // Passa File/Blob (non ArrayBuffer): JSZip lo legge solo durante generateAsync
            // evitando di tenere tutti i file in RAM contemporaneamente.
            zip.file(filePath, file);
            fileCount++;
            const tot = Math.max(totalFiles || 0, fileCount) + 6;
            overlay.update(fileCount, tot, `${t('depositoPhaseReading') || t('depositoProgress')} ${fileCount}/${totalFiles || '?'}: ${entry.name}`);

            // Manifest: usa _exactRec (match canonico esatto) come fonte
            // primaria; ripiega sull'euristico solo se assente, per evitare
            // associazioni errate in presenza di storagePath annidati o
            // nomi file duplicati (task #347, raccomandazione code review).
            const matchingRec = _exactRec || d.files.find(f => (f.diskFileName === entry.name || f.fileName === entry.name) && f.storagePath && filePath.includes(f.storagePath));
            let entityLabel = '';
            if (matchingRec) {
              if (matchingRec.entityType === 'case') {
                const cs = d.cases.find(c => c.id === matchingRec.entityId);
                entityLabel = (cs ? (cs.title || cs.descriptionIt) : 'Caso') + ' (ID:' + matchingRec.entityId + ')';
              } else if (matchingRec.entityType === 'proceeding' || matchingRec.entityType === 'proceeding_origin') {
                const pr = d.proceedings.find(pp => pp.id === matchingRec.entityId);
                entityLabel = (pr ? (pr.title || 'Procedimento') : 'Procedimento') + ' (ID:' + matchingRec.entityId + ')';
              } else if (matchingRec.entityType === 'dossier') {
                const ds = d.dossiers.find(dd => dd.id === matchingRec.entityId);
                entityLabel = (ds ? ds.title : 'Fascicolo') + ' (ID:' + matchingRec.entityId + ')';
              } else if (matchingRec.entityType === 'act') {
                const act = d.acts.find(a => a.id === matchingRec.entityId);
                entityLabel = (act ? act.title : 'Atto') + ' (ID:' + matchingRec.entityId + ')';
              } else if (matchingRec.entityType === 'fact') {
                const fact = d.facts.find(f => f.id === matchingRec.entityId);
                entityLabel = (fact ? fact.title : 'Fatto') + ' (ID:' + matchingRec.entityId + ')';
              } else if (matchingRec.entityType === 'proof') {
                const proof = d.proofs.find(pr => pr.id === matchingRec.entityId);
                entityLabel = (proof ? proof.title : 'Prova') + ' (ID:' + matchingRec.entityId + ')';
              }
            }

            fileManifest.push({
              num: fileCount,
              fileName: matchingRec ? matchingRec.fileName : entry.name,
              path: filePath,
              entity: entityLabel || filePath,
              entityType: matchingRec ? matchingRec.entityType : '',
              entityId: matchingRec ? matchingRec.entityId : 0,
              size: file.size || 0,
              hash: hashHex,
              date: matchingRec ? (matchingRec.createdAt || '') : ''
            });
          } catch (e) {
            console.warn('Could not read file:', entry.name, e);
          }
        } else if (entry.kind === 'directory') {
          try {
            const subDir = await dirHandle.getDirectoryHandle(entry.name);
            await _addFsTreeToZip(subDir, zipPrefix + '/' + entry.name, zip, fileManifest, d, totalFiles);
          } catch (e) {
            console.warn('Could not read directory:', entry.name, e);
          }
        }
      }
    }

    let allegatiCopied = false;
    if (FS_FILES_HANDLE) {
      try {
        const allegatiDir = await FS_FILES_HANDLE.getDirectoryHandle('DOC_ESP');
        overlay.update(0, 1, t('depositoPhaseScanFs') || 'Scansione cartella di lavoro…');
        await _yield();
        let totalFiles = 0;
        try { totalFiles = await _countFsTree(allegatiDir, 'DOC_ESP'); } catch (_) { totalFiles = 0; }
        if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
        overlay.update(0, Math.max(totalFiles, 1) + 6, `${t('depositoPhaseReading') || t('depositoProgress')} 0/${totalFiles}`);
        await _addFsTreeToZip(allegatiDir, 'DOC_ESP', zip, fileManifest, d, totalFiles);
        if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
        allegatiCopied = true;
      } catch (e) {
        console.log('No allegati folder found in filesystem, falling back to DB records');
      }
    }

    if (!allegatiCopied) {
      const totalFiles = relevantFiles.length;
      overlay.update(0, Math.max(totalFiles, 1) + 6, `${t('depositoPhaseReading') || t('depositoProgress')} 0/${totalFiles}`);
      for (const fileRec of relevantFiles) {
        if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
        fileCount++;
        overlay.update(fileCount, totalFiles + 6, `${t('depositoPhaseReading') || t('depositoProgress')} ${fileCount}/${totalFiles}: ${fileRec.fileName}`);

        let fileData = null;
        let filePath = '';

        if (fileRec.storagePath) {
          filePath = fileRec.storagePath + '/' + (fileRec.diskFileName || fileRec.fileName);
          try {
            const file = await loadPreviewFileFromFS(fileRec);
            if (file) {
              fileData = file; // File/Blob – non convertire in ArrayBuffer
            }
          } catch (e) {
            console.warn('Could not read file from FS:', fileRec.fileName, e);
          }
        }

        if (!fileData && fileRec.blob) {
          filePath = filePath || ('DOC_ESP/' + (fileRec.diskFileName || fileRec.fileName));
          fileData = fileRec.blob;
        }

        if (!fileData && fileRec.id) {
          try {
            const freshRec = await DB.getFile(fileRec.id);
            if (freshRec && freshRec.blob) {
              filePath = filePath || ('DOC_ESP/' + (freshRec.diskFileName || freshRec.fileName));
              fileData = freshRec.blob;
            }
          } catch (e) {}
        }

        if (!fileData) {
          missingFiles.push(fileRec.fileName);
        }

        if (fileData) {
          zip.file(filePath, fileData);

          let hashHex = '';
          try {
            const _sz2 = fileData instanceof Blob ? fileData.size : (fileData instanceof ArrayBuffer ? fileData.byteLength : 0);
            if (_sz2 > 0 && _sz2 <= 200 * 1024 * 1024) {
              const _buf2 = fileData instanceof ArrayBuffer ? fileData : await fileData.arrayBuffer();
              const _dig2 = await crypto.subtle.digest('SHA-256', _buf2);
              hashHex = Array.from(new Uint8Array(_dig2)).map(b => b.toString(16).padStart(2,'0')).join('');
            } else if (_sz2 > 200 * 1024 * 1024) {
              hashHex = '(file > 200 MB – non calcolato)';
            } else {
              hashHex = 'N/A';
            }
          } catch (e) {
            hashHex = 'N/A';
          }

          let entityLabel = fileRec.entityType;
          if (fileRec.entityType === 'case') {
            const cs = d.cases.find(c => c.id === fileRec.entityId);
            entityLabel = (cs ? (cs.title || cs.descriptionIt) : 'Caso') + ' (ID:' + fileRec.entityId + ')';
          } else if (fileRec.entityType === 'proceeding' || fileRec.entityType === 'proceeding_origin') {
            const pr = d.proceedings.find(pp => pp.id === fileRec.entityId);
            entityLabel = (pr ? (pr.title || 'Procedimento') : 'Procedimento') + ' (ID:' + fileRec.entityId + ')';
          } else if (fileRec.entityType === 'dossier') {
            const ds = d.dossiers.find(dd => dd.id === fileRec.entityId);
            entityLabel = (ds ? ds.title : 'Fascicolo') + ' (ID:' + fileRec.entityId + ')';
          } else if (fileRec.entityType === 'act') {
            const act = d.acts.find(a => a.id === fileRec.entityId);
            entityLabel = (act ? act.title : 'Atto') + ' (ID:' + fileRec.entityId + ')';
          } else if (fileRec.entityType === 'fact') {
            const fact = d.facts.find(f => f.id === fileRec.entityId);
            entityLabel = (fact ? fact.title : 'Fatto') + ' (ID:' + fileRec.entityId + ')';
          } else if (fileRec.entityType === 'proof') {
            const proof = d.proofs.find(pr => pr.id === fileRec.entityId);
            entityLabel = (proof ? proof.title : 'Prova') + ' (ID:' + fileRec.entityId + ')';
          }

          fileManifest.push({
            num: fileCount,
            fileName: fileRec.fileName,
            path: filePath,
            entity: entityLabel,
            entityType: fileRec.entityType,
            entityId: fileRec.entityId,
            size: fileRec.fileSize || 0,
            hash: hashHex,
            date: fileRec.createdAt || ''
          });
        }
      }
    }

    const opts = {
      depositType, depositName, depositTitle, depositForo, depositDate, depositPlace,
      selActIds, selFactIds, selProofIds, selProcIds, selCaseIds, fileManifest,
      sensitiveNoOmissisProofIds: _sensitiveNoOmissisProofIds
    };

    const baseDone = fileCount;
    const totalUnits = baseDone + 6;

    if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
    overlay.update(baseDone, totalUnits, t('depositoPhaseHtml') || 'Generazione pagine HTML del pacchetto…');
    await _yield();
    const htmlPages = _generateDepositHTML(d, opts);
    for (const [filename, html] of Object.entries(htmlPages)) {
      zip.file(filename, html);
    }

    if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
    overlay.update(baseDone + 1, totalUnits, t('depositoPhaseManifest') || 'Generazione manifesto integrità (PDF)…');
    await _yield();
    const manifestPdf = _genManifestPDF(fileManifest, d, opts);
    zip.file('manifesto_integrita.pdf', manifestPdf);

    if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
    overlay.update(baseDone + 2, totalUnits, t('depositoPhaseAttest') || 'Generazione attestazione conformità (PDF)…');
    await _yield();
    const attestPdf = _genAttestPDF(opts);
    zip.file('attestazione_conformita.pdf', attestPdf);

    if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
    overlay.update(baseDone + 3, totalUnits, t('depositoPhaseRelata') || 'Generazione relata di deposito (PDF)…');
    await _yield();
    const relataPdf = _genRelataDepositoPDF(d, opts);
    zip.file('relata_deposito.pdf', relataPdf);

    if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
    overlay.update(baseDone + 4, totalUnits, t('depositoPhaseLista') || 'Generazione lista di deposito (PDF)…');
    await _yield();
    const listaPdf = _genListaDepositoPDF(d, opts);
    zip.file('lista_deposito.pdf', listaPdf);

    if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
    const zipPhaseLabel = t('depositoPhaseZip') || 'Compressione archivio ZIP';
    overlay.update(baseDone + 5, totalUnits, zipPhaseLabel + ' 0%');
    const blob = await zip.generateAsync({ type: 'blob' }, metadata => {
      // Aggiorna l'overlay con la percentuale di compressione (last unit del totale).
      const pct = Math.round(metadata.percent || 0);
      overlay.update(baseDone + 5, totalUnits, `${zipPhaseLabel} ${pct}%`);
    });
    if (isCancelled()) { overlay.close(); _renderDepositCancelled(body); return; }
    overlay.update(totalUnits, totalUnits, t('depositoPhaseSaving') || 'Salvataggio file…');
    await _yield();

    const firstCase = d.cases.find(c => selCaseIds.has(c.id));
    const now = new Date();
    const dateStr = now.getFullYear() + String(now.getMonth() + 1).padStart(2, '0') + String(now.getDate()).padStart(2, '0');
    const timeStr = String(now.getHours()).padStart(2, '0') + String(now.getMinutes()).padStart(2, '0');
    const zipName = 'Deposito_' + dateStr + '_' + timeStr + '.zip';

    const blobUrl = URL.createObjectURL(blob);

    if (body) {
      let successMsg = t('depositoComplete');
      if (missingFiles.length > 0) {
        successMsg += `<div class="deposit-warning" style="margin-top:12px;padding:8px 12px;background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;color:#92400e;font-size:12px;text-align:left">
          <strong>${t('depositoMissingFilesTitle')}</strong> (${missingFiles.length})<br>
          ${missingFiles.map(f => esc(f)).join('<br>')}
        </div>`;
      }
      const dlLabel = t('depositoDownload') || (currentLang === 'en' ? 'Download ZIP' : 'Scarica ZIP');
      body.innerHTML = `<div class="deposit-progress">
        <div class="deposit-progress-text deposit-success">${successMsg}</div>
        <div style="text-align:center;margin-top:16px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
          <a class="btn btn-primary" href="${blobUrl}" download="${esc(zipName)}" data-testid="button-deposit-download">\u2B07 ${esc(dlLabel)} (${esc(zipName)})</a>
          <button class="btn" onclick="try{URL.revokeObjectURL('${blobUrl}');}catch(_){}document.getElementById('depositModal').remove()" data-testid="button-deposit-close">${t('close')}</button>
        </div>
      </div>`;
    }
  } catch (e) {
    console.error('Deposit generation error:', e);
    if (body) {
      body.innerHTML = `<div class="deposit-progress">
        <div class="deposit-progress-text deposit-error">${t('depositoError')}: ${esc(e.message)}</div>
        <div style="text-align:center;margin-top:16px"><button class="btn" onclick="document.getElementById('depositModal').remove()" data-testid="button-deposit-error-close">${t('close')}</button></div>
      </div>`;
    }
  } finally {
    try { overlay.close(); } catch (_) {}
  }
}

// Renderizza nel modale del deposito il messaggio di annullamento utente:
// l'overlay si è già chiuso (premendo Annulla) e nessun file è stato scritto
// né su disco né scaricato. Il pacchetto può essere ricreato dallo stesso
// modale senza dover riselezionare l'albero.
function _renderDepositCancelled(body) {
  if (!body) return;
  body.innerHTML = `<div class="deposit-progress">
    <div class="deposit-progress-text" style="color:#92400e">${t('depositoCancelled') || 'Generazione annullata.'}</div>
    <div style="text-align:center;margin-top:16px">
      <button class="btn" onclick="document.getElementById('depositModal').remove()" data-testid="button-deposit-cancelled-close">${t('close')}</button>
    </div>
  </div>`;
}

function _generateDepositHTML(d, opts) {
  const { selActIds, selFactIds, selProcIds, selCaseIds, fileManifest } = opts;
  const _e = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  const selCases = d.cases.filter(c => selCaseIds.has(c.id));
  const selProcs = d.proceedings.filter(p => selProcIds.has(p.id));

  const pages = [];
  let treeHtml = '';
  let allSubjectsHtml = '';
  let firstSlider = 'dashboard.html';

  const totalProcs = selProcs.length;
  let totalDossiers = 0, totalActs = 0, totalFacts = 0;
  for (const p of selProcs) {
    const dossiers = d.dossiers.filter(ds => ds.proceedingId === p.id);
    totalDossiers += dossiers.length;
    for (const ds of dossiers) {
      const _dsF3 = new Set((d.factDossierRelations || []).filter(r => r.dossierId === ds.id).map(r => r.factId));
      const _dsA3 = new Set((d.factActRelations || []).filter(r => _dsF3.has(r.factId)).map(r => r.actId));
      totalActs += d.acts.filter(a => _dsA3.has(a.id) && opts.selActIds.has(a.id)).length;
      totalFacts += d.facts.filter(f => _dsF3.has(f.id) && opts.selFactIds.has(f.id)).length;
    }
  }

  const allEvents = [];
  const tlColors = { penale: '#3b82f6', civile: '#22c55e', esecuzione: '#ef4444', amministrativo: '#eab308', altro: '#8b5cf6' };
  for (const proc of selProcs) {
    const sd = proc.specificData || {};
    const phases = sd.phases || [];
    const caseObj = selCases.find(cc => cc.id === proc.caseId);
    const cTitle = caseObj ? ((currentLang === 'en' && caseObj.titleEn) ? caseObj.titleEn : (caseObj.title || '')) : '';
    for (const ph of phases) {
      for (const ev of (ph.events || [])) {
        if (ev.data || ev.date) {
          allEvents.push({ date: ev.data || ev.date, title: ev.title || ev.tipo || '', procType: proc.type || 'altro', procTitle: proc.title || '', caseTitle: cTitle });
        }
      }
    }
  }
  allEvents.sort((a, b) => a.date.localeCompare(b.date));

  let timelineHtml = '';
  if (allEvents.length > 0) {
    const minD = new Date(allEvents[0].date);
    const maxD = new Date(allEvents[allEvents.length - 1].date);
    const totalMs = Math.max(maxD - minD, 86400000);
    const groupedByCase = {};
    for (const ev of allEvents) {
      const key = ev.caseTitle || '?';
      if (!groupedByCase[key]) groupedByCase[key] = {};
      if (!groupedByCase[key][ev.procType]) groupedByCase[key][ev.procType] = [];
      groupedByCase[key][ev.procType].push(ev);
    }
    let lanesHtml = '';
    for (const [caseName, typeGroups] of Object.entries(groupedByCase)) {
      lanesHtml += `<div style="font-size:11px;font-weight:700;color:#64748b;padding:8px 0 2px;text-transform:uppercase;letter-spacing:0.5px">${_e(caseName)}</div>`;
      for (const [tp, events] of Object.entries(typeGroups)) {
        const color = tlColors[tp] || tlColors.altro;
        const lbl = t('timeline' + tp.charAt(0).toUpperCase() + tp.slice(1)) || tp;
        const dots = events.map(ev => {
          const pos = ((new Date(ev.date) - minD) / totalMs) * 100;
          return `<div style="position:absolute;left:${pos}%;top:50%;transform:translate(-50%,-50%);width:10px;height:10px;border-radius:50%;background:${color};border:2px solid #fff" title="${_e(_depFmtDate(ev.date) + ' — ' + (ev.title || ev.procTitle))}"></div>`;
        }).join('');
        lanesHtml += `<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px">
          <div style="width:90px;font-size:11px;color:${color};font-weight:600;flex-shrink:0">${_e(lbl)}</div>
          <div style="flex:1;position:relative;height:20px;background:#f1f5f9;border-radius:3px">
            <div style="position:absolute;top:50%;left:0;right:0;height:2px;background:${color};transform:translateY(-50%)"></div>
            ${dots}
          </div>
        </div>`;
      }
    }
    const minLabel = _depFmtDate(allEvents[0].date);
    const maxLabel = _depFmtDate(allEvents[allEvents.length - 1].date);
    timelineHtml = `<div class="detail-section"><div class="detail-section-header"><h3>${t('globalTimelineTitle')}</h3></div>
      <div style="padding:8px 0">${lanesHtml}
        <div style="display:flex;justify-content:space-between;font-size:10px;color:#94a3b8;margin-top:4px"><span>${_e(minLabel)}</span><span>${_e(maxLabel)}</span></div>
      </div></div>`;
  }

  let dashContent = `<section class="detail-panel dep-detail-section">
    <div class="detail-header"><h2>${t('dashboardTitle')}</h2></div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px">
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;text-align:center"><div style="font-size:28px;font-weight:700;color:#7c3aed">${selCases.length}</div><div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:600;letter-spacing:0.5px">${t('dashboardCases')}</div></div>
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;text-align:center"><div style="font-size:28px;font-weight:700;color:#7c3aed">${totalProcs}</div><div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:600;letter-spacing:0.5px">${t('dashboardProceedings')}</div></div>
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;text-align:center"><div style="font-size:28px;font-weight:700;color:#7c3aed">${totalActs}</div><div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:600;letter-spacing:0.5px">${t('dashboardActs')}</div></div>
      <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:16px;text-align:center"><div style="font-size:28px;font-weight:700;color:#7c3aed">${totalFacts}</div><div style="font-size:11px;color:#64748b;text-transform:uppercase;font-weight:600;letter-spacing:0.5px">${t('depositoFacts')}</div></div>
    </div>
    ${timelineHtml}
  </section>`;
  pages.push({ filename: 'dashboard.html', content: dashContent });

  for (const c of selCases) {
    const caseDisplayTitle = (currentLang === 'en' && c.titleEn) ? c.titleEn : (c.title || '');
    const caseFilename = `case_${c.id}.html`;
    treeHtml += `<details class="tree-acc tree-acc-case" open><summary class="tree-acc-summary tree-case-link"><a href="slider/${caseFilename}" target="mainframe" class="tree-link"><span class="tree-badge tree-badge-K">${t('caso')}</span> <span class="tree-link-title">${_e(caseDisplayTitle)}</span></a></summary>`;

    const caseDescr = currentLang === 'it' ? (c.descrIt || '') : (c.descrEn || c.descrIt || '');
    const caseFiles = d.files.filter(f => f.entityType === 'case' && f.entityId === c.id);
    let caseFileHtml = '';
    if (caseFiles.length > 0) {
      caseFileHtml = `<div class="detail-section"><div class="detail-section-header"><h3>${t('docIntroduttivoCaso')}</h3></div><div class="dep-files">`;
      for (const f of caseFiles) {
        const mf = opts.fileManifest.find(m => m.entityType === f.entityType && m.entityId === f.entityId && m.fileName === f.fileName);
        const href = mf ? '../' + mf.path : f.fileName;
        caseFileHtml += `<a href="${_e(href)}" target="_blank" class="dep-file-link">${_e(f.fileName)}</a> `;
      }
      caseFileHtml += '</div></div>';
    }
    pages.push({
      filename: caseFilename,
      content: `<section class="detail-panel dep-detail-section">
        <div class="detail-header"><h2>${_e(caseDisplayTitle)}</h2></div>
        ${caseDescr ? `<div class="detail-field"><div class="detail-field-label">${t('description')}</div><div class="detail-field-value">${_e(caseDescr)}</div></div>` : ''}
        ${caseFileHtml}
      </section>`
    });

    const _latestPmDateDep = (pp) => {
      let best = '';
      for (const ph of ((pp.specificData || {}).phases || [])) {
        for (const ev of (ph.pmEvents || [])) {
          if (ev.date && ev.date > best) best = ev.date;
        }
      }
      return best || pp.dataIscrizioneRuolo || '';
    };
    const caseProcs = selProcs
      .filter(p => p.caseId === c.id && !p.parentProceedingId)
      .sort((a, b) => _latestPmDateDep(b).localeCompare(_latestPmDateDep(a)));

    // Raggruppamento per contenitore procedimentale (come renderTree live).
    // I procedimenti con proceedingGroupId valido vengono incapsulati in
    // un <details> con badge tipo+seq e titolo del contenitore. Gli altri
    // restano al livello del caso.
    const _caseGroupsAll = (d.proceedingGroups || []).filter(g => g.caseId === c.id);
    const _groupOfProc = new Map();
    for (const p of caseProcs) {
      if (p.proceedingGroupId) {
        const g = _caseGroupsAll.find(gg => gg.id === p.proceedingGroupId);
        if (g) _groupOfProc.set(p.id, g);
      }
    }
    const _typePrefix = { penale: 'PP', civile: 'PC', amministrativo: 'PA', esecuzione: 'PE', altro: 'PX' };
    const _typeToBadge = { penale: 'P', civile: 'C', amministrativo: 'A', esecuzione: 'E', altro: 'X' };
    const _usedGroupIds = new Set();
    for (const p of caseProcs) {
      const g = _groupOfProc.get(p.id);
      if (g && !_usedGroupIds.has(g.id)) _usedGroupIds.add(g.id);
    }
    // Ordina i contenitori per refDate ASC (i piu' vecchi in alto, come live).
    const _activeGroups = _caseGroupsAll
      .filter(g => _usedGroupIds.has(g.id))
      .map(g => {
        const grpProcs = caseProcs.filter(p => p.proceedingGroupId === g.id);
        return { g, refDate: _computeContainerRefDate(g, grpProcs), grpProcs };
      })
      .sort((a, b) => {
        const ra = a.refDate || '';
        const rb = b.refDate || '';
        if (ra && rb) { if (ra !== rb) return ra.localeCompare(rb); }
        else if (ra) return -1;
        else if (rb) return 1;
        return ((a.g.sortOrder ?? a.g.id) - (b.g.sortOrder ?? b.g.id));
      });

    for (const { g, grpProcs } of _activeGroups) {
      const grpType = g.type || 'altro';
      const grpSortIdx = g.sortOrder || 1;
      const grpSeqNum = (_typePrefix[grpType] || 'PX') + String(grpSortIdx).padStart(3, '0');
      const grpBadgeCls = 'tree-badge-' + (_typeToBadge[grpType] || 'X');
      const grpTypeShort = t('procTypeShort_' + grpType) || t(grpType) || grpType;
      const grpCustomTitle = (currentLang === 'en' ? (g.titleEN || g.title) : g.title) || '';
      const grpMainProc = grpProcs.slice().sort((a, b) => _latestPmDateDep(b).localeCompare(_latestPmDateDep(a)))[0];
      let grpAutoTitle = '';
      if (grpMainProc) {
        const _bestDate = _latestPmDateDep(grpMainProc);
        let _mag = '';
        for (const _ph of (grpMainProc.specificData?.phases || [])) {
          for (const _ev of (_ph.pmEvents || [])) {
            if (_ev.date === _bestDate && _ph.magistratoPrincipale) { _mag = _ph.magistratoPrincipale; break; }
          }
          if (_mag) break;
        }
        if (!_mag) _mag = grpMainProc.specificData?.phases?.[0]?.magistratoPrincipale || '';
        const _uff = grpMainProc.autoritaProcedente || '';
        grpAutoTitle = [_uff, _mag ? 'PM ' + _mag : ''].filter(Boolean).join(' \u2014 ');
      }
      const grpTitle = grpCustomTitle || grpAutoTitle || '';

      treeHtml += `<details class="tree-acc tree-acc-grp" open><summary class="tree-acc-summary tree-grp-summary"><span class="tree-badge ${grpBadgeCls}">${_e(grpSeqNum)} ${_e(grpTypeShort)}</span>${grpTitle ? ` <span class="tree-grp-title">${_e(grpTitle)}</span>` : ''}</summary>`;
      for (const p of grpProcs) {
        const res = _genDepositProcTree(p, c, d, opts, _e);
        treeHtml += res.tree;
        for (const pg of res.pages) pages.push(pg);
        allSubjectsHtml += res.subjects;
      }
      treeHtml += '</details>';
    }
    // Procedimenti non raggruppati: al livello del caso, in coda ai contenitori.
    for (const p of caseProcs) {
      if (_groupOfProc.has(p.id)) continue;
      const res = _genDepositProcTree(p, c, d, opts, _e);
      treeHtml += res.tree;
      for (const pg of res.pages) pages.push(pg);
      allSubjectsHtml += res.subjects;
    }
    treeHtml += '</details>';
  }

  const seenSubjIds = new Set();
  const selProcList = d.proceedings.filter(p => selProcIds.has(p.id));
  for (const p of selProcList) {
    const procRoles = d.proceedingRoles.filter(r => r.proceedingId === p.id);
    for (const role of procRoles) {
      const subj = role.subject;
      if (!subj || seenSubjIds.has(subj.id)) continue;
      seenSubjIds.add(subj.id);
      const fullName = (subj.salutation ? subj.salutation + ' ' : '') + (subj.firstName || '') + ' ' + (subj.lastName || '');
      let subjContent = `<section class="detail-panel dep-detail-section">
        <div class="detail-header"><h2>${_e(fullName)}</h2></div>`;
      subjContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('subjectData')}</h3></div>`;
      if (subj.fiscalCode) subjContent += `<div class="detail-field"><div class="detail-field-label">${t('fiscalCode')}</div><div class="detail-field-value">${_e(subj.fiscalCode)}</div></div>`;
      if (subj.birthDate) subjContent += `<div class="detail-field"><div class="detail-field-label">${t('birthDate')}</div><div class="detail-field-value">${_e(subj.birthDate)}</div></div>`;
      if (subj.birthPlace) subjContent += `<div class="detail-field"><div class="detail-field-label">${t('birthPlace')}</div><div class="detail-field-value">${_e(subj.birthPlace)}</div></div>`;
      if (subj.gender) subjContent += `<div class="detail-field"><div class="detail-field-label">${t('gender')}</div><div class="detail-field-value">${_e(t(subj.gender) || subj.gender)}</div></div>`;
      if (subj.address) subjContent += `<div class="detail-field"><div class="detail-field-label">${t('address')}</div><div class="detail-field-value">${_e(subj.address)}</div></div>`;
      if (subj.notes) subjContent += `<div class="detail-field"><div class="detail-field-label">${t('notes')}</div><div class="detail-field-value">${_e(subj.notes)}</div></div>`;
      subjContent += '</div>';
      const subjRoles = d.proceedingRoles.filter(r => r.subjectId === subj.id && selProcIds.has(r.proceedingId));
      if (subjRoles.length > 0) {
        subjContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('proceedingRoles')}</h3></div><div class="proof-links-list">`;
        for (const sr of subjRoles) {
          const proc = d.proceedings.find(pp => pp.id === sr.proceedingId);
          const procTitle = proc ? (proc.title || '') : '';
          const roleLabel = t(sr.roleCode) || sr.roleCode || '';
          subjContent += `<div class="proof-link-item"><a href="proc_${sr.proceedingId}.html">${_e(procTitle)}</a> <span class="tree-badge tree-badge-neutral">${_e(roleLabel)}</span>`;
          if (sr.qualification) subjContent += ` <span style="color:#64748b;font-size:11px">${_e(sr.qualification)}</span>`;
          if (sr.dateFrom) subjContent += ` <span style="color:#94a3b8;font-size:10px">${_e(_depFmtDate(sr.dateFrom))}${sr.dateTo ? ' — ' + _e(_depFmtDate(sr.dateTo)) : ''}</span>`;
          subjContent += '</div>';
        }
        subjContent += '</div></div>';
      }
      subjContent += '</section>';
      pages.push({ filename: `subj_${subj.id}.html`, content: subjContent });
    }
  }

  const css = _getDepositCSS();
  const sliderCss = _getSliderCSS();
  const genDate = new Date().toLocaleDateString(currentLang === 'it' ? 'it-IT' : 'en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  const caseTitle = _e(selCases[0]?.title || selCases[0]?.descriptionIt || '');

  const indexHtml = `<!DOCTYPE html>
<html lang="${currentLang}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${caseTitle}</title>
<style>${css}</style>
</head>
<body>
<header class="dep-header">
  <div class="dep-header-info">
    <h1>${caseTitle}</h1>
    <p>${t('depositoGenerated')}: ${genDate}</p>
  </div>
  <a href="slider/dashboard.html" target="mainframe" class="dep-header-home" title="Home">&#x2302; Home</a>
</header>
<div class="app-layout">
  <aside class="sidebar-left">
    <div class="sidebar-section">
      <div class="sidebar-section-header"><h3>${t('navTitle')}</h3></div>
      <div class="tree-nav">${treeHtml}</div>
    </div>
  </aside>
  <iframe name="mainframe" class="main-panel" src="slider/${firstSlider}" frameborder="0"></iframe>
  <aside class="sidebar-right">
    <div class="sidebar-section">
      <div class="sidebar-section-header"><h3>${t('depositoSectionSubjects')}</h3></div>
      ${allSubjectsHtml || '<p class="hint">' + t('depositoNoData') + '</p>'}
    </div>
  </aside>
</div>
</body>
</html>`;

  const result = {};
  result['index.html'] = indexHtml;
  for (const pg of pages) {
    result['slider/' + pg.filename] = `<!DOCTYPE html>
<html lang="${currentLang}">
<head>
<meta charset="UTF-8">
<style>${sliderCss}</style>
</head>
<body>
<div class="zoom-bar"><a href="${pg.filename}" target="_blank" class="zoom-link" title="Zoom">&#x26F6; Zoom</a></div>
${pg.content}
</body>
</html>`;
  }
  return result;
}

function _depFmtDate(dateStr) {
  if (!dateStr) return '-';
  const d = (dateStr instanceof Date) ? dateStr : new Date(dateStr);
  if (isNaN(d.getTime())) return String(dateStr);
  const monKeys = ['monJan','monFeb','monMar','monApr','monMay','monJun','monJul','monAug','monSep','monOct','monNov','monDec'];
  const mon = t(monKeys[d.getMonth()]);
  const dd = String(d.getDate()).padStart(2, '0');
  const yyyy = d.getFullYear();
  if (currentLang === 'en') return `${mon} ${dd}, ${yyyy}`;
  return `${dd} ${mon} ${yyyy}`;
}

function _depDetailField(label, value, _e) {
  return `<div class="detail-field"><div class="detail-field-label">${label}</div><div class="detail-field-value">${_e(value || '-')}</div></div>`;
}

function _depGetPhaseRegLabel(phaseType) {
  const map = { 'fase_procura': 'RGNR', 'fase_gip_fase': 'RG GIP', 'fase_gup': 'RG GUP', 'fase_dibattimento_fase': 'RGT', 'fase_appello_penale': 'RGA', 'fase_cassazione_penale': 'RG Cass.', 'fase_esecuzione_penale': 'SIEP' };
  return map[phaseType] || '';
}

function _depPhaseMagRole(phaseType) {
  const map = { 'fase_procura': 'pm', 'fase_gip_fase': 'gip', 'fase_gup': 'gup', 'fase_dibattimento_fase': 'giudice_dibattimento', 'fase_appello_penale': 'giudice_appello', 'fase_cassazione_penale': 'giudice_cassazione', 'fase_esecuzione_penale': 'magistrato', 'fase_appello_civile': 'giudice_appello', 'fase_cassazione_civile': 'giudice_cassazione' };
  return map[phaseType] || 'magistrato';
}

function _depAccSection(title, fieldsHtml) {
  return `<details class="dep-phase-details"><summary class="dep-phase-summary">${title}</summary><div class="dep-phase-body">${fieldsHtml}</div></details>`;
}

function _genDepositSpecificData(type, sd, d, _e) {
  if (type === 'penale') {
    const isUfficio = sd.origineProc === 'ufficio';
    let html = '';
    if (!isUfficio) {
      if (sd.indagati && sd.indagati.length > 0) {
        const soggettiLabel = t('tabIndagati') + (sd.soggettiTipo === 'ignoti' ? ' — ' + t('soggettiIgnoti') : '');
        let indHtml = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">';
        for (let i = 0; i < sd.indagati.length; i++) {
          const entry = sd.indagati[i];
          const subj = entry.subjectId ? d.subjects.find(s => s.id === entry.subjectId) : null;
          const name = subj ? `${subj.salutation ? subj.salutation + ' ' : ''}${subj.firstName || ''} ${subj.lastName || ''}` : (entry.label || '-');
          let qualLabel = '';
          if (entry.qualitaDi === 'privato_cittadino') qualLabel = t('privatoCittadino');
          else if (entry.roleLabel) { const parts = entry.roleLabel.split(' > '); qualLabel = parts[parts.length - 1].trim(); }
          indHtml += `<div class="dep-indagato-card"><div style="font-weight:600">N.${i + 1} ${_e(name)}</div>${qualLabel ? `<div style="margin-top:2px;font-size:11px;color:#64748b">${_e(qualLabel)}</div>` : ''}</div>`;
        }
        indHtml += '</div>';
        html += `<div class="detail-section"><div class="detail-section-header"><h3>${soggettiLabel}</h3></div>${sd.soggettiTipo === 'ignoti' ? '' : indHtml}</div>`;
      }
      html += `<div class="detail-section"><div class="detail-section-header"><h3>${t('tabOrigineAtto')}</h3></div>
        <div class="detail-grid"><div class="detail-grid-row detail-grid-row-4">
          ${_depDetailField(t('penaleTipoAtto'), sd.tipoAtto ? t(sd.tipoAtto) : '-', _e)}
          ${_depDetailField(t('canaleRicezione'), sd.canaleRicezione ? t(sd.canaleRicezione) : '-', _e)}
          ${_depDetailField(t('dataDeposito'), _depFmtDate(sd.dataDeposito), _e)}
          ${_depDetailField(t('cittaDeposito'), sd.cittaDeposito, _e)}
        </div></div>
      </div>`;
    }
    return html;
  }
  if (type === 'civile') {
    return _depAccSection(t('tabParti'),
        _depDetailField(t('civileTipo'), sd.tipoCivile ? t(sd.tipoCivile) : '-', _e) +
        _depDetailField(t('civileAttore'), sd.attore, _e) +
        _depDetailField(t('civileConvenuto'), sd.convenuto, _e)
      ) +
      _depAccSection(t('tabIstruttoria'),
        _depDetailField(t('civileCTU'), sd.ctu, _e) +
        _depDetailField(t('civileDataCTU'), _depFmtDate(sd.dataCTU), _e) +
        _depDetailField(t('civileArticolo'), sd.articolo, _e)
      ) +
      _depAccSection(t('tabDecisione'),
        _depDetailField(t('civileDecisione'), sd.decisione ? t(sd.decisione) : '-', _e) +
        _depDetailField(t('civileDataPubbl'), _depFmtDate(sd.dataPubbl), _e) +
        _depDetailField(t('civileDataComun'), _depFmtDate(sd.dataComun), _e)
      );
  }
  if (type === 'amministrativo') {
    return _depAccSection(t('tabRicorso'),
        _depDetailField(t('ammTAR'), sd.tar, _e) +
        _depDetailField(t('ammRG'), sd.rgTar, _e) +
        _depDetailField(t('ammTipoRicorso'), sd.tipoRicorso, _e) +
        _depDetailField(t('ammProvvedimento'), sd.provvedimento, _e) +
        _depDetailField(t('ammDataNotifica'), _depFmtDate(sd.dataNotifica), _e)
      ) +
      _depAccSection(t('tabCautelare'),
        _depDetailField(t('ammSospensiva'), sd.sospensiva ? t('si') : t('no'), _e) +
        _depDetailField(t('ammOrdinanzaCaut'), sd.ordinanzaCaut, _e)
      ) +
      _depAccSection(t('tabAppelloAmm'),
        _depDetailField(t('ammAppelloCS'), sd.appelloCS ? t('si') : t('no'), _e)
      );
  }
  if (type === 'esecuzione') {
    return _depAccSection(t('tabPignoramento'),
        _depDetailField(t('eseRGE'), sd.rge, _e) +
        _depDetailField(t('eseTipo'), sd.tipoEse ? t(sd.tipoEse) : '-', _e) +
        _depDetailField(t('esePignoramento'), _depFmtDate(sd.dataPignoramento), _e)
      ) +
      _depAccSection(t('tabSoggetti'),
        _depDetailField(t('eseGiudice'), sd.giudice, _e) +
        _depDetailField(t('eseCreditore'), sd.creditore, _e) +
        _depDetailField(t('eseDebitore'), sd.debitore, _e) +
        _depDetailField(t('eseCustode'), sd.custode, _e) +
        _depDetailField(t('eseDelegato'), sd.delegato, _e)
      ) +
      _depAccSection(t('tabVendita'),
        _depDetailField(t('eseDataAsta'), _depFmtDate(sd.dataAsta), _e) +
        _depDetailField(t('eseStatoVendita'), sd.statoVendita, _e)
      ) +
      _depAccSection(t('tabPerizia'),
        _depDetailField(t('esePerizia'), sd.perizia, _e)
      );
  }
  return '';
}

function _genDepositProcTree(p, c, d, opts, _e) {
  const { selActIds, selFactIds, selProcIds } = opts;
  const sd = p.specificData || {};
  let tree = '';
  const pages = [];
  let subjects = '';

  const procBadge = typeToBadge(p.type, p.specificData?.origineProc);
  tree += `<details class="tree-acc tree-acc-proc" open><summary class="tree-acc-summary"><a href="slider/proc_${p.id}.html" target="mainframe" class="tree-link"><span class="tree-badge ${procBadge.cls}">${_e(procBadge.label)}</span> <span class="tree-link-title">${_e(p.title || '')}</span></a></summary>`;

  let parentProcHdr = '';
  if (p.parentProceedingId) {
    const parentP = d.proceedings.find(pp => pp.id === p.parentProceedingId);
    if (parentP) parentProcHdr = `<div class="proc-header-info-item"><span class="proc-header-info-label">${t('procPadre')}:</span> ${_e(parentP.title || '')}</div>`;
  }

  let procContent = `<section class="detail-panel dep-detail-section">
    <div class="proc-form-header">
      <div class="proc-form-header-title has-title">${_e(p.title || '')}
        ${sd.origineProc === 'integrazione' ? `<div class="proc-form-header-integrazione">${t('origineProc_perIntegrazione')}</div>` : ''}
      </div>
      <div class="proc-form-header-controls">
        ${parentProcHdr}
        <div class="proc-header-info-item"><span class="tree-badge ${procBadge.cls}" style="font-size:11px">${_e(procBadge.label)}</span> ${_e(t(p.type) || p.type || '')}</div>
        ${p.status ? `<div class="proc-header-info-item"><span class="proc-header-status-val">${_e(t(p.status) || p.status || '')}</span></div>` : ''}
        ${p.rgType ? `<div class="proc-header-info-item">${_e(p.rgType)} ${_e(p.rgNumber || '')}/${_e(p.year || '')}</div>` : ''}
      </div>
    </div>`;

  const specificDataHtml = _genDepositSpecificData(p.type, sd, d, _e);
  if (specificDataHtml) procContent += specificDataHtml;

  if (p.luogoFatti || p.citta || p.provincia || p.regione || p.stato) {
    procContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('tabLuogo')}</h3></div>
      <div class="detail-grid"><div class="detail-grid-row detail-grid-row-5">
        <div class="detail-field"><div class="detail-field-label">${t('luogoFatti')}</div><div class="detail-field-value">${_e(p.luogoFatti || '-')}</div></div>
        <div class="detail-field"><div class="detail-field-label">${t('citta')}</div><div class="detail-field-value">${_e(p.citta || '-')}</div></div>
        <div class="detail-field"><div class="detail-field-label">${t('provincia')}</div><div class="detail-field-value">${_e(p.provincia || '-')}</div></div>
        <div class="detail-field"><div class="detail-field-label">${t('regione')}</div><div class="detail-field-value">${_e(p.regione || '-')}</div></div>
        <div class="detail-field"><div class="detail-field-label">${t('stato_geo')}</div><div class="detail-field-value">${_e(p.stato || '-')}</div></div>
      </div></div>
    </div>`;
  }

  if (sd.phases && sd.phases.length > 0) {
    procContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('fasiProcedimentali')}</h3></div>`;
    for (let idx = 0; idx < sd.phases.length; idx++) {
      const phase = sd.phases[idx];
      const phaseLabel = t(phase.tipo) || t(phase.type) || phase.tipo || phase.type || '';
      const regLabel = _depGetPhaseRegLabel(phase.tipo);
      const regNumberLabel = regLabel ? `N. ${regLabel}` : t('phaseRegNumber');
      const magRoleLabel = t('procRole_' + (_depPhaseMagRole(phase.tipo) || 'magistrato'));

      procContent += `<details class="dep-phase-details" open><summary class="dep-phase-summary"><span class="dep-phase-num">F${idx + 1}</span> ${_e(phaseLabel)}</summary><div class="dep-phase-body">`;

      let magDisplay = phase.magistratoPrincipale || '';
      if (magDisplay && phase.magistratoSubjectId) {
        const magSubj = d.subjects.find(s => s.id === phase.magistratoSubjectId);
        if (magSubj && magSubj.salutation) magDisplay = magSubj.salutation + ' ' + magDisplay;
      }

      procContent += `<div class="detail-grid"><div class="detail-grid-row detail-grid-row-6">
        ${_depDetailField(t('phaseOffice'), phase.ufficio, _e)}
        ${_depDetailField(regNumberLabel, phase.numeroRegistro ? phase.numeroRegistro + (phase.anno ? '/' + phase.anno : '') : '-', _e)}
        ${_depDetailField(t('modelloProcura'), phase.modello ? (t(phase.modello + '_short') || t(phase.modello) || phase.modello) : '-', _e)}
        ${_depDetailField(magRoleLabel, magDisplay, _e)}
        ${_depDetailField(t('dataIscrizione'), _depFmtDate(phase.dataIscrizione), _e)}
        ${_depDetailField(t('termineIndagini'), _depFmtDate(phase.termineIndagini), _e)}
      </div></div>`;

      if (phase.altriMagistrati) {
        procContent += `<div class="detail-grid"><div class="detail-grid-row">${_depDetailField(t('phaseOtherMagistrates'), phase.altriMagistrati, _e)}</div></div>`;
      }

      if (phase.tipo === 'fase_procura') {
        const plList = phase.personeLese || [];
        if (plList.length > 0) {
          procContent += `<div class="dep-sub-section"><div class="dep-sub-section-label">${t('personaLesa')}</div>`;
          for (const pl of plList) {
            const subj = pl.subjectId ? d.subjects.find(s => s.id === pl.subjectId) : null;
            const name = subj ? `${subj.salutation ? subj.salutation + ' ' : ''}${subj.firstName || ''} ${subj.lastName || ''}` : (pl.name || '-');
            procContent += `<div style="padding:2px 0">${_e(name)}</div>`;
          }
          procContent += '</div>';
        }

        const irList = phase.indagatiReati || [];
        if (irList.length > 0) {
          procContent += `<div class="dep-sub-section"><div class="dep-sub-section-label">${t('indagatiReatiSection')}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">`;
          for (let i = 0; i < irList.length; i++) {
            const ir = irList[i];
            const subj = ir.subjectId ? d.subjects.find(s => s.id === ir.subjectId) : null;
            const name = subj ? `${subj.salutation ? subj.salutation + ' ' : ''}${subj.firstName || ''} ${subj.lastName || ''}` : '-';
            const reati = (ir.reati || []).filter(r => r).map(r => `<span class="badge badge-outline">${_e(r)}</span>`).join(' ');
            procContent += `<div class="dep-indagato-card"><div style="font-weight:600">N.${i + 1} ${_e(name)}</div>${reati ? `<div style="margin-top:4px">${reati}</div>` : ''}</div>`;
          }
          procContent += '</div></div>';
        }

        const pmEvts = phase.pmEvents || [];
        if (pmEvts.length > 0) {
          procContent += `<div class="dep-sub-section"><div class="dep-sub-section-label">${t('pmEventsSection')}</div>`;
          for (const ev of pmEvts) {
            const tipoLabel = ev.tipo ? (t(ev.tipo) || ev.tipo) : '-';
            const sottoLabel = ev.sottoTipo ? (t(ev.sottoTipo) || ev.sottoTipo) : '-';
            procContent += `<div class="dep-pm-event"><div class="detail-grid"><div class="detail-grid-row detail-grid-row-3">
              ${_depDetailField(t('pmEventDate'), _depFmtDate(ev.date), _e)}
              ${_depDetailField(t('pmTipoIntervento'), tipoLabel, _e)}
              ${_depDetailField(t('pmSottoTipo'), sottoLabel, _e)}
            </div></div>`;
            const evNotes = currentLang === 'en' ? (ev.notesEn || '') : (ev.notes || '');
            if (evNotes) procContent += `${_depDetailField(t('pmEventNotes'), evNotes, _e)}`;
            if (ev.linkedActIds && ev.linkedActIds.length > 0) {
              const actBadges = ev.linkedActIds.map(actId => {
                const act = d.acts.find(a => a.id === actId);
                const label = act ? (act.title || t('act')) : t('act') + ' #' + actId;
                return `<a href="act_${actId}.html" class="badge badge-outline" style="margin:2px;text-decoration:none">${_e(label)}</a>`;
              }).join('');
              procContent += `<div style="margin-top:4px"><span style="font-size:11px;font-weight:600">${t('linkedActs')}:</span> ${actBadges}</div>`;
            }
            procContent += '</div>';
          }
          procContent += '</div>';
        }
      }

      const events = phase.events || phase.eventi || [];
      if (events.length > 0) {
        procContent += '<table class="dep-events-table"><thead><tr><th>' + t('type') + '</th><th>' + t('date') + '</th><th>' + t('notes') + '</th></tr></thead><tbody>';
        for (const ev of events) {
          const evType = ev.tipo || ev.type || '';
          const evSubType = ev.sottoTipo || ev.subType || '';
          const evLabel = (t(evType) || evType) + (evSubType ? ' — ' + (t(evSubType) || evSubType) : '');
          procContent += `<tr><td>${_e(evLabel)}</td><td>${_e(_depFmtDate(ev.data || ev.date || ''))}</td><td>${_e(ev.note || ev.notes || '')}</td></tr>`;
        }
        procContent += '</tbody></table>';
      }

      procContent += '</div></details>';
    }
    procContent += '</div>';
  }

  const procRoles = d.proceedingRoles.filter(r => r.proceedingId === p.id);
  if (procRoles.length > 0) {
    procContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('procRolesTitle')}</h3></div><div class="proof-links-list">`;
    for (const role of procRoles) {
      const subj = role.subject;
      if (!subj) continue;
      const fullName = (subj.salutation ? subj.salutation + ' ' : '') + (subj.firstName || '') + ' ' + (subj.lastName || '');
      const roleLabel = t(role.roleCode) || role.roleCode || '';
      procContent += `<div class="proof-link-item"><a href="subj_${subj.id}.html">${_e(fullName)}</a> <span class="tree-badge tree-badge-neutral">${_e(roleLabel)}</span>`;
      if (role.qualification) procContent += ` <span style="color:#64748b;font-size:11px">${_e(role.qualification)}</span>`;
      if (role.dateFrom) procContent += ` <span style="color:#94a3b8;font-size:10px">${_e(_depFmtDate(role.dateFrom))}${role.dateTo ? ' — ' + _e(_depFmtDate(role.dateTo)) : ''}</span>`;
      procContent += '</div>';
    }
    procContent += '</div></div>';
  }

  const procFileList = d.files.filter(f => (f.entityType === 'proceeding' || f.entityType === 'proceeding_origin') && f.entityId === p.id);
  if (procFileList.length > 0) {
    procContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('fileSection')}</h3></div><div class="dep-files">`;
    for (const f of procFileList) {
      const mf = opts.fileManifest.find(m => m.entityType === f.entityType && m.entityId === f.entityId && m.fileName === f.fileName);
      const href = mf ? '../' + mf.path : f.fileName;
      procContent += `<a href="${_e(href)}" target="_blank" class="dep-file-link">${_e(f.fileName)}</a> `;
    }
    procContent += '</div></div>';
  }
  procContent += '</section>';
  let procSubjects = '';
  const procEntitySubjects = (d.entitySubjects || []).filter(es => es.proceedingId === p.id);
  if (procEntitySubjects.length > 0) {
    // Task #212 fase 3 — classificazione via linkKind con fallback legacy.
    // Vigilanza: include sia righe shadow (vigKey) sia link primari coi
    // ruoli di vertice (procuratore, presidenti, ecc.). Soggetti
    // processuali: tutti gli altri kind, esclusi avvocati e qualifiche
    // funzionali (gestite separatamente nella sidebar).
    const vigLinks = _subjectsByKind(procEntitySubjects, [LINK_KIND.VIGILANZA], { dedupeBy: 'subject' });
    const procLinks = _subjectsByKind(procEntitySubjects, [
      LINK_KIND.INQUIRENTE, LINK_KIND.GIUDICANTE, LINK_KIND.SEGNALATO,
      LINK_KIND.PARTE_OFFESA, LINK_KIND.INDAGATO_IMPUTATO, LINK_KIND.COINVOLTO
    ], { dedupeBy: 'subject' });

    const _vigRoleLbls = new Set([
      tLang('procRole_procuratoreRepubblica','it'), tLang('procRole_procuratoreRepubblica','en'),
      tLang('procRole_presidenteTribunale','it'), tLang('procRole_presidenteTribunale','en'),
      tLang('procRole_presidenteCorteAppello','it'), tLang('procRole_presidenteCorteAppello','en'),
      tLang('procRole_procuratoreGenerale','it'), tLang('procRole_procuratoreGenerale','en'),
      tLang('procRole_responsabile_vigilanza','it'), tLang('procRole_responsabile_vigilanza','en')
    ].filter(Boolean));
    const _isVigRoleDep = (r) => !!r && _vigRoleLbls.has(r);
    const _isDecedutaLinkDep = (l) => {
      if (l.qualificaProcessuale !== 'persona_offesa') return false;
      const r = (l.role || '').toString().toLowerCase();
      return r.includes('decedut') || r.includes('deceased');
    };
    const renderSubjCard = (l) => {
      const subj = l.subject;
      if (!subj) return '';
      const fullName = (subj.salutation ? subj.salutation + ' ' : '') + (subj.firstName || '') + ' ' + (subj.lastName || '');
      let roleBadge = '';
      if (l.qualificaProcessuale === 'persona_offesa') {
        roleBadge = _isDecedutaLinkDep(l)
          ? `<span class="badge-parte-offesa-deceduta">\u271D ${_e(t('parteOffesaDecedutaBadge'))}</span>`
          : `<span class="badge-parte-offesa">${_e(t('parteOffesaBadge'))}</span>`;
      } else {
        const cls = _isVigRoleDep(l.role) ? 'badge-role-vigilanza-purple' : _roleToBadgeCss(l.role);
        roleBadge = `<span class="${cls}">${l.role ? _e(_translateRoleLabel(l.role)) : '\u2014'}</span>`;
      }
      const typeBadge = _subjectTypeBadgeHtml(subj.subjectType) || '';
      return `<div class="subject-card">
        <div class="subj-card-name-row">${roleBadge}${typeBadge}</div>
        <a href="slider/subj_${subj.id}.html" target="mainframe" class="subject-card-name subject-card-link">${_e(fullName.trim())}</a>
      </div>`;
    };

    procSubjects += `<div class="linked-section-title">${_e(p.title || t('depositoProceeding'))}</div>`;
    if (vigLinks.length > 0) {
      procSubjects += `<div class="linked-section-title" style="font-size:10px;color:#7c3aed">${t('catenaVigilanza')}</div>`;
      procSubjects += vigLinks.map(renderSubjCard).join('');
    }
    if (procLinks.length > 0) {
      procSubjects += `<div class="linked-section-title" style="font-size:10px;color:#7c3aed">${t('soggettiProcessuali')}</div>`;
      procSubjects += procLinks.map(renderSubjCard).join('');
    }
    subjects += `<div class="dep-subj-group">${procSubjects}</div>`;
  }

  pages.push({ filename: `proc_${p.id}.html`, content: procContent, subjects: procSubjects });

  const dossiers = d.dossiers.filter(ds => ds.proceedingId === p.id);
  for (const ds of dossiers) {
    const _dsFR = new Set((d.factDossierRelations || []).filter(r => r.dossierId === ds.id).map(r => r.factId));
    const _dsAR = new Set((d.factActRelations || []).filter(r => _dsFR.has(r.factId)).map(r => r.actId));
    const dsActs = d.acts.filter(a => _dsAR.has(a.id) && selActIds.has(a.id));
    const dsFacts = d.facts.filter(f => _dsFR.has(f.id) && selFactIds.has(f.id))
      .sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0) || a.id - b.id);
    const dossierFiles = d.files.filter(f => f.entityType === 'dossier' && f.entityId === ds.id);

    tree += `<details class="tree-acc tree-acc-dossier" open><summary class="tree-acc-summary tree-dossier-label"><a href="slider/dossier_${ds.id}.html" target="mainframe" class="tree-link tree-link-dossier"><span class="tree-badge tree-badge-F">${t('fascBadge')}</span> <span class="tree-link-title">${_e(ds.title || t('depositoDossier'))}</span></a></summary>`;

    let dossierContent = `<section class="detail-panel dep-detail-section">
      <div class="detail-header"><h2>${_e(ds.title || t('depositoDossier'))}</h2></div>`;
    if (ds.description) dossierContent += `<div class="detail-field"><div class="detail-field-label">${t('description')}</div><div class="detail-field-value">${_e(ds.description)}</div></div>`;
    if (dossierFiles.length > 0) {
      dossierContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('fileSection')}</h3></div><div class="dep-files">`;
      for (const f of dossierFiles) {
        const mf = opts.fileManifest.find(m => m.entityType === f.entityType && m.entityId === f.entityId && m.fileName === f.fileName);
        const href = mf ? '../' + mf.path : f.fileName;
        const fHash = f.hash || f.hashSha256 || f.sha256 || '';
        dossierContent += `<div class="dep-file-row"><a href="${_e(href)}" target="_blank" class="dep-file-link">${_e(f.fileName)}</a>${fHash ? `<div class="dep-file-hash">SHA-256: ${_e(fHash)}</div>` : ''}</div>`;
      }
      dossierContent += '</div></div>';
    }
    if (dsActs.length > 0) {
      dossierContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('depositoActs')} (${dsActs.length})</h3></div><div class="proof-links-list">`;
      for (const a of dsActs) {
        const badgeCls = 'act-badge act-badge-' + (a.type || '');
        dossierContent += `<div class="proof-link-item"><a href="act_${a.id}.html"><span class="${badgeCls}">${_e(actTypeLabel(a.type))}</span>${a.subtype ? ` <span class="tree-badge tree-badge-neutral">${_e(actSubtypeBadgeLabel(a.subtype))}</span>` : ''} ${_e(a.title || '')}</a></div>`;
      }
      dossierContent += '</div></div>';
    }
    if (dsFacts.length > 0) {
      dossierContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('depositoFacts')} (${dsFacts.length})</h3></div><div class="proof-links-list">`;
      for (const f of dsFacts) {
        const factRels = d.factActRelations.filter(r => r.factId === f.id);
        const factProofRels = (d.factProofRelations || []).filter(r => r.factId === f.id);
        const factProofs = factProofRels.map(r => { const p = d.proofs.find(pp => pp.id === r.proofId); return p ? { ...p, relationType: r.relationType } : null; }).filter(Boolean);
        const ls = DB.computeLogicalState(factRels, factProofs);
        const lsCls = ls === 'INCOHERENCE' ? 'logic-badge-incoherence' : ls === 'OMISSION' ? 'logic-badge-omission' : ls === 'COHERENT' ? 'logic-badge-coherent' : ls === 'HAS_PROOFS' ? 'logic-badge-hasproofs' : 'logic-badge-noproofs';
        const lsLbl = ls === 'INCOHERENCE' ? t('factIncoherence') : ls === 'OMISSION' ? t('factOmission') : ls === 'COHERENT' ? t('factCoherent') : ls === 'HAS_PROOFS' ? t('factHasProofs') : ls === 'NO_ACTS' ? t('factNoActs') : t('factNoProofs');
        dossierContent += `<div class="proof-link-item"><a href="fact_${f.id}.html">${_e(f.title || '')}</a> <span class="logic-badge ${lsCls}">${_e(lsLbl)}</span></div>`;
      }
      dossierContent += '</div></div>';
    }
    dossierContent += '</section>';
    pages.push({ filename: `dossier_${ds.id}.html`, content: dossierContent });

    if (dsActs.length > 0) {
      for (const a of dsActs) {
        const badgeCls = 'act-badge act-badge-' + (a.type || '');
        const actRels = d.factActRelations.filter(r => r.actId === a.id);
        const linkedFacts = actRels.filter(r => selFactIds.has(r.factId));

        let actWorstState = null;
        if (actRels.length > 0) {
          actWorstState = 'COHERENT';
          for (const rel of actRels) {
            const relFact = d.facts.find(ff => ff.id === rel.factId);
            if (!relFact) continue;
            const fProofRels = (d.factProofRelations || []).filter(r => r.factId === relFact.id);
            const fProofs = fProofRels.map(r => { const p = d.proofs.find(pp => pp.id === r.proofId); return p ? { ...p, relationType: r.relationType } : null; }).filter(Boolean);
            const fRels = d.factActRelations.filter(r => r.factId === relFact.id);
            const fState = DB.computeLogicalState(fRels, fProofs);
            if (fState === 'INCOHERENCE') { actWorstState = 'INCOHERENCE'; break; }
            if (fState === 'OMISSION' && actWorstState !== 'INCOHERENCE') actWorstState = 'OMISSION';
          }
        }
        const actStateBadgeCls = actWorstState === 'INCOHERENCE' ? 'logic-badge-incoherence' : actWorstState === 'OMISSION' ? 'logic-badge-omission' : actWorstState === 'COHERENT' ? 'logic-badge-coherent' : '';
        const actStateLabel = actWorstState === 'INCOHERENCE' ? t('factIncoherence') : actWorstState === 'OMISSION' ? t('factOmission') : actWorstState === 'COHERENT' ? t('factCoherent') : '';
        const actStateBadge = actWorstState ? `<span class="logic-badge ${actStateBadgeCls}" style="margin-left:8px">${_e(actStateLabel)}</span>` : '';

        let actContent = `<section class="detail-panel dep-detail-section">
          <div class="detail-header"><h2><span class="${badgeCls}">${_e(actTypeLabel(a.type))}</span>${a.subtype ? ` <span class="tree-badge tree-badge-neutral">${_e(actSubtypeBadgeLabel(a.subtype))}</span>` : ''} ${_e(a.title || '')}${actStateBadge}</h2></div>`;

        if (a.parentId) {
          const parentAct = d.acts.find(pa => pa.id === a.parentId);
          if (parentAct) actContent += `<div class="detail-field"><div class="detail-field-label">${t('actParent')}</div><div class="detail-field-value">${_e(parentAct.title || '')}</div></div>`;
        }

        const actFiles = d.files.filter(f => f.entityType === 'act' && f.entityId === a.id);
        if (actFiles.length > 0) {
          actContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('fileSection')}</h3></div><div class="dep-files">`;
          for (const f of actFiles) {
            const mf = opts.fileManifest.find(m => m.entityType === f.entityType && m.entityId === f.entityId && m.fileName === f.fileName);
            const href = mf ? '../' + mf.path : f.fileName;
            actContent += `<a href="${_e(href)}" target="_blank" class="dep-file-link">${_e(f.fileName)}</a> `;
          }
          actContent += '</div></div>';
        }

        if (linkedFacts.length > 0) {
          actContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('viewerFactsForAct')}</h3></div><div class="proof-links-list">`;
          for (const rel of linkedFacts) {
            const fact = d.facts.find(f => f.id === rel.factId);
            if (fact) {
              const posLabel = rel.posizioneAtto ? (t('factPos' + rel.posizioneAtto.charAt(0).toUpperCase() + rel.posizioneAtto.slice(1)) || rel.posizioneAtto) : '-';
              actContent += `<div class="proof-link-item"><a href="fact_${fact.id}.html">${_e(fact.title || '')}</a> <span class="tree-badge tree-badge-neutral">${_e(posLabel)}</span></div>`;
            }
          }
          actContent += '</div></div>';
        }
        actContent += '</section>';
        pages.push({ filename: `act_${a.id}.html`, content: actContent, subjects: procSubjects });
      }
    }

    if (dsFacts.length > 0) {
      for (const [fIdx, f] of dsFacts.entries()) {
        const factRels = d.factActRelations.filter(r => r.factId === f.id);
        const factProofRels2 = (d.factProofRelations || []).filter(r => r.factId === f.id);
        const factProofs = factProofRels2.map(r => { const p = d.proofs.find(pp => pp.id === r.proofId); return p ? { ...p, relationType: r.relationType } : null; }).filter(Boolean);
        const factCirc = d.circumstances.filter(ci => ci.factId === f.id);
        const logicState = DB.computeLogicalState(factRels, factProofs);
        const lsBadgeCls = logicState === 'INCOHERENCE' ? 'logic-badge-incoherence' : logicState === 'OMISSION' ? 'logic-badge-omission' : logicState === 'COHERENT' ? 'logic-badge-coherent' : 'logic-badge-noproofs';
        const lsLabel = logicState === 'INCOHERENCE' ? t('factIncoherence') : logicState === 'OMISSION' ? t('factOmission') : logicState === 'COHERENT' ? t('factCoherent') : logicState === 'HAS_PROOFS' ? t('factHasProofs') : logicState === 'NO_ACTS' ? t('factNoActs') : t('factNoProofs');
        const fSeqLabel = t('factBadge') + ' ' + String(fIdx + 1).padStart(3, '0');

        let factDateStr = '';
        if (f.factDate) { factDateStr = _depFmtDate(f.factDate); if (f.factTime) factDateStr += ' ' + f.factTime; }
        tree += `<div class="tree-leaf tree-fact"><a href="slider/fact_${f.id}.html" target="mainframe" class="tree-link"><span class="tree-badge tree-badge-fact-type">${_e(fSeqLabel)}</span> ${_e(f.title || '')}${factDateStr ? ' <span style="font-size:10px;color:#94a3b8">' + _e(factDateStr) + '</span>' : ''} <span class="logic-badge ${lsBadgeCls}">${_e(lsLabel)}</span></a></div>`;

        let factContent = `<section class="detail-panel dep-detail-section">
          <div class="detail-header"><h2>${_e(f.title || '')}</h2><div class="detail-header-actions"><span class="logic-badge ${lsBadgeCls}">${_e(lsLabel)}</span></div></div>`;

        factContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('factSectionId')}</h3></div>`;
        if (f.description) factContent += `<div class="detail-field"><div class="detail-field-label">${t('factDescription')}</div><div class="detail-field-value rte-content" style="text-align:justify">${_renderRichForView(f.description)}</div></div>`;
        if (f.factDate || f.date) factContent += `<div class="detail-field"><div class="detail-field-label">${t('factDate')}</div><div class="detail-field-value">${_e(_depFmtDate(f.factDate || f.date))}${f.factTime ? ' — ' + _e(f.factTime) : ''}</div></div>`;
        if (f.place || f.luogo) factContent += `<div class="detail-field"><div class="detail-field-label">${t('factPlace')}</div><div class="detail-field-value">${_e(f.place || f.luogo)}</div></div>`;
        factContent += '</div>';

        if (factCirc.length > 0) {
          factContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('factSectionCircumstances')}</h3></div><div class="proof-links-list">`;
          for (const ci of factCirc) {
            const typeLabel = ci.tipo ? (t('circumstance' + ci.tipo.charAt(0).toUpperCase() + ci.tipo.slice(1)) || ci.tipo) : (t(ci.type) || ci.type || '');
            const ciDescrRaw = ci.descrizione || ci.description || '';
            const ciTitleRaw = ci.title || '';
            const ciTitleHtml = ciTitleRaw ? `<span>${_e(ciTitleRaw)}</span>` : '';
            const ciDescrHtml = ciDescrRaw ? `<div class="rte-content" style="text-align:justify;width:100%;${ciTitleRaw ? 'margin-top:4px' : ''}">${_renderRichForView(ciDescrRaw)}</div>` : '';
            factContent += `<div class="proof-link-item" style="flex-wrap:wrap"><span class="tree-badge tree-badge-neutral">${_e(typeLabel)}</span>${ciTitleHtml}${ciDescrHtml}</div>`;
          }
          factContent += '</div></div>';
        }

        if (factProofs.length > 0) {
          factContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('factSectionProofs')}</h3></div><div class="proof-links-list">`;
          for (const pr of factProofs) {
            const relCls = pr.relationType === 'confirms' ? 'tree-badge-confirm' : pr.relationType === 'contradicts' ? 'tree-badge-deny' : 'tree-badge-neutral';
            const relLabel = pr.relationType ? (t('proofRel' + pr.relationType.charAt(0).toUpperCase() + pr.relationType.slice(1)) || pr.relationType) : '';
            factContent += `<div class="proof-link-item"><span class="tree-badge ${relCls}">${_e(relLabel)}</span> <span>${_e(pr.title || '')}</span>`;
            if (pr.notes) factContent += `<div style="font-size:11px;color:#64748b;margin-top:2px">${_e(pr.notes)}</div>`;
            const proofFiles = d.files.filter(pf => pf.entityType === 'proof' && pf.entityId === pr.id);
            if (proofFiles.length > 0) {
              factContent += '<div class="dep-files" style="margin-top:4px">';
              for (const pf of proofFiles) {
                const mf = opts.fileManifest.find(m => m.entityType === pf.entityType && m.entityId === pf.entityId && m.fileName === pf.fileName);
                const href = mf ? '../' + mf.path : pf.fileName;
                factContent += `<a href="${_e(href)}" target="_blank" class="dep-file-link">${_e(pf.fileName)}</a> `;
              }
              factContent += '</div>';
            }
            factContent += '</div>';
          }
          factContent += '</div></div>';
        }

        const linkedActs = factRels.filter(r => selActIds.has(r.actId));
        if (linkedActs.length > 0) {
          factContent += `<div class="detail-section"><div class="detail-section-header"><h3>${t('factSectionPosition')}</h3></div><div class="proof-links-list">`;
          for (const rel of linkedActs) {
            const act = d.acts.find(a => a.id === rel.actId);
            if (act) {
              const posLabel = rel.posizioneAtto ? (t('factPos' + rel.posizioneAtto.charAt(0).toUpperCase() + rel.posizioneAtto.slice(1)) || rel.posizioneAtto) : '-';
              factContent += `<div class="proof-link-item"><a href="act_${act.id}.html">${_e(act.title || '')}</a> <span class="tree-badge tree-badge-neutral">${_e(posLabel)}</span></div>`;
            }
          }
          factContent += '</div></div>';
        }
        factContent += '</section>';
        pages.push({ filename: `fact_${f.id}.html`, content: factContent, subjects: procSubjects });
      }
    }
    tree += '</details>';
  }

  const childProcs = d.proceedings.filter(cp => cp.parentProceedingId === p.id && selProcIds.has(cp.id));
  for (const cp of childProcs) {
    const childRes = _genDepositProcTree(cp, c, d, opts, _e);
    tree += childRes.tree;
    for (const pg of childRes.pages) pages.push(pg);
    subjects += childRes.subjects;
  }

  tree += '</details>';
  return { tree, pages, subjects };
}

function _genStandaloneDocCSS() {
  return `
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; font-size: 14px; color: #1e293b; background: #fff; padding: 40px; max-width: 900px; margin: 0 auto; }
    .doc-header { border-bottom: 3px solid #1e293b; padding-bottom: 16px; margin-bottom: 24px; display: flex; align-items: center; gap: 16px; }
    .doc-logo { background: #7c3aed; color: #fff; font-weight: 700; font-size: 18px; padding: 6px 12px; border-radius: 6px; }
    .doc-header h1 { font-size: 1.2rem; color: #1e293b; }
    .doc-header p { font-size: 0.85rem; color: #64748b; }
    .doc-note { font-style: italic; color: #64748b; margin-bottom: 20px; font-size: 0.85rem; }
    .doc-table { width: 100%; border-collapse: collapse; margin-bottom: 16px; font-size: 0.85rem; }
    .doc-table th, .doc-table td { padding: 8px 10px; border: 1px solid #e2e8f0; text-align: left; }
    .doc-table thead th { background: #f1f5f9; font-weight: 600; color: #334155; }
    .doc-table tbody tr:nth-child(even) { background: #f8fafc; }
    .doc-hash { font-family: monospace; font-size: 0.7rem; word-break: break-all; color: #64748b; }
    .doc-path { font-family: monospace; font-size: 0.75rem; word-break: break-all; }
    .doc-back { display: inline-block; margin-top: 20px; color: #7c3aed; text-decoration: none; font-size: 0.85rem; }
    .doc-attest-body { border: 2px solid #1e293b; border-radius: 8px; padding: 40px; margin-top: 20px; }
    .doc-attest-text { text-align: justify; line-height: 1.8; margin-bottom: 40px; font-size: 1rem; }
    .doc-attest-fields { display: flex; flex-wrap: wrap; gap: 32px; margin-bottom: 48px; }
    .doc-attest-field { display: flex; gap: 8px; }
    .doc-attest-label { font-weight: 600; color: #64748b; }
    .doc-attest-value { color: #1e293b; }
    .doc-attest-sign { margin-top: 48px; text-align: right; }
    .doc-attest-sign-line { width: 300px; border-bottom: 1px solid #1e293b; margin: 80px 0 8px auto; }
    .doc-attest-sign-name { font-style: italic; color: #64748b; }
    .doc-print-btn { display: none; }
    @media print {
      .doc-print-btn, .doc-back { display: none !important; }
      body { padding: 20px; }
      .doc-header { border-bottom: 3px solid #000; }
      .doc-logo { background: #000; }
      .doc-attest-body { border: 2px solid #000; }
    }
  `;
}

function _genManifestStandaloneHTML(fileManifest, d, opts) {
  const _e = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const selCases = d.cases.filter(c => opts.selCaseIds.has(c.id));
  const caseTitle = selCases[0]?.title || selCases[0]?.descriptionIt || '';
  const genDate = new Date().toLocaleDateString(currentLang === 'it' ? 'it-IT' : 'en-US', { year: 'numeric', month: 'long', day: 'numeric' });

  let tableRows = '';
  if (fileManifest.length === 0) {
    tableRows = `<tr><td colspan="5" style="text-align:center;color:#64748b">${t('depositoNoData')}</td></tr>`;
  } else {
    for (const m of fileManifest) {
      tableRows += `<tr>
        <td>${m.num}</td>
        <td>${_e(m.fileName)}</td>
        <td>${_e(m.entity)}</td>
        <td>${_formatFileSize(m.size)}</td>
        <td class="doc-hash">${_e(m.hash)}</td>
      </tr>`;
    }
  }

  return `<!DOCTYPE html>
<html lang="${currentLang}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${t('depositoManifestTitle')} — ${_e(caseTitle)}</title>
<style>${_genStandaloneDocCSS()}</style>
</head>
<body>
  <div class="doc-header">
    <div class="doc-logo">UXG</div>
    <div>
      <h1>${t('depositoManifestTitle')}</h1>
      <p>${_e(caseTitle)} — ${genDate}</p>
    </div>
  </div>

  <p class="doc-note">${t('depositoHashNote')}</p>

  <table class="doc-table">
    <thead><tr>
      <th>${t('depositoManifestNum')}</th>
      <th>${t('depositoManifestFile')}</th>
      <th>${t('depositoManifestEntity')}</th>
      <th>${t('depositoManifestSize')}</th>
      <th>${t('depositoManifestHash')}</th>
    </tr></thead>
    <tbody>${tableRows}</tbody>
  </table>

  <p style="margin-top:16px;font-size:0.8rem;color:#64748b">${t('depositoManifestTotal')}: <strong>${fileManifest.length}</strong> ${fileManifest.length === 1 ? 'file' : 'files'}</p>

  ${(opts.sensitiveNoOmissisProofIds && opts.sensitiveNoOmissisProofIds.size > 0) ? `
  <div style="margin-top:18px;padding:12px 14px;background:#fff7ed;border:1px solid #f59e0b;border-radius:6px;color:#92400e;font-size:0.85rem">
    <strong>${t('depositoSensitiveDisclaimerTitle')||'Avviso — immagini sensibili senza oscuramento'}</strong>
    <div style="margin-top:6px">${t('depositoSensitiveDisclaimerBody')||'Il pacchetto contiene immagini marcate come sensibili per le quali non è stato applicato alcun omissis vettoriale. Verificare prima del deposito.'}</div>
    <div style="margin-top:6px;font-size:0.78rem">ID prove: ${[...opts.sensitiveNoOmissisProofIds].join(', ')}</div>
  </div>` : ''}

  <a href="index.html" class="doc-back">&larr; ${t('depositoBackToIndex')}</a>
</body>
</html>`;
}

function _genAttestStandaloneHTML(opts) {
  const { depositType, depositName, depositTitle, depositForo, depositDate, depositPlace } = opts;
  const _e = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const fullName = (depositTitle ? depositTitle + ' ' : '') + depositName;
  const selCases = _depositAllData.cases.filter(c => opts.selCaseIds.has(c.id));
  const caseTitle = selCases[0]?.title || selCases[0]?.descriptionIt || '';

  let attestText = '';
  if (depositType === 'lawyer') {
    attestText = t('depositoAttestLawyer').replace('{name}', _e(fullName)).replace('{foro}', _e(depositForo));
  } else {
    attestText = t('depositoAttestPrivate').replace('{name}', _e(fullName));
  }

  return `<!DOCTYPE html>
<html lang="${currentLang}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${t('depositoAttestTitle')} — ${_e(caseTitle)}</title>
<style>${_genStandaloneDocCSS()}</style>
</head>
<body>
  <div class="doc-header">
    <div class="doc-logo">UXG</div>
    <div>
      <h1>${t('depositoAttestTitle')}</h1>
      <p>${_e(caseTitle)}</p>
    </div>
  </div>

  <div class="doc-attest-body">
    <p class="doc-attest-text">${attestText}</p>
    <div class="doc-attest-fields">
      <div class="doc-attest-field">
        <span class="doc-attest-label">${t('depositoAttestPlace')}:</span>
        <span class="doc-attest-value">${_e(depositPlace)}</span>
      </div>
      <div class="doc-attest-field">
        <span class="doc-attest-label">${t('depositoAttestDate')}:</span>
        <span class="doc-attest-value">${_e(depositDate)}</span>
      </div>
    </div>
    <div class="doc-attest-sign">
      <span class="doc-attest-label">${t('depositoAttestSign')}</span>
      <div class="doc-attest-sign-line"></div>
      <span class="doc-attest-sign-name">${_e(fullName)}</span>
    </div>
  </div>

  <a href="index.html" class="doc-back">&larr; ${t('depositoBackToIndex')}</a>
</body>
</html>`;
}

function _genManifestPDF(fileManifest, d, opts) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const pw = doc.internal.pageSize.getWidth();
  const ph = doc.internal.pageSize.getHeight();
  const ml = 15, mr = 15, mt = 15;
  const usable = pw - ml - mr;
  const selCases = d.cases.filter(c => opts.selCaseIds.has(c.id));
  const caseTitle = selCases[0]?.title || selCases[0]?.descriptionIt || '';
  const genDate = new Date().toLocaleDateString(currentLang === 'it' ? 'it-IT' : 'en-US', { year: 'numeric', month: 'long', day: 'numeric' });

  doc.setFillColor(30, 41, 59);
  doc.rect(0, 0, pw, 18, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('UXG', ml, 11);
  doc.setFontSize(11);
  doc.text(t('depositoManifestTitle'), ml + 18, 8);
  doc.setFontSize(8);
  doc.setFont('helvetica', 'normal');
  doc.text(caseTitle + ' \u2014 ' + genDate, ml + 18, 13);

  let y = 26;
  doc.setTextColor(100, 116, 139);
  doc.setFontSize(7);
  doc.text(t('depositoHashNote'), ml, y);
  y += 8;

  const cols = [
    { label: t('depositoManifestNum'), w: usable * 0.05 },
    { label: t('depositoManifestFile'), w: usable * 0.28 },
    { label: t('depositoManifestEntity'), w: usable * 0.18 },
    { label: t('depositoManifestSize'), w: usable * 0.08 },
    { label: t('depositoManifestHash'), w: usable * 0.41 }
  ];

  function drawHeader(yPos) {
    doc.setFillColor(241, 245, 249);
    doc.rect(ml, yPos - 4, usable, 6, 'F');
    doc.setTextColor(30, 41, 59);
    doc.setFontSize(6.5);
    doc.setFont('helvetica', 'bold');
    let cx = ml + 1;
    for (const col of cols) {
      doc.text(col.label, cx, yPos);
      cx += col.w;
    }
    doc.setFont('helvetica', 'normal');
    return yPos + 5;
  }

  y = drawHeader(y);

  doc.setFontSize(6);
  doc.setTextColor(30, 41, 59);

  for (const m of fileManifest) {
    if (y > ph - 15) {
      doc.addPage();
      y = mt;
      y = drawHeader(y);
      doc.setFontSize(6);
      doc.setTextColor(30, 41, 59);
    }
    let cx = ml + 1;
    const row = [
      String(m.num),
      m.fileName || '',
      m.entity || '',
      _formatFileSize(m.size),
      m.hash || ''
    ];
    for (let i = 0; i < cols.length; i++) {
      const cellW = cols[i].w - 2;
      const lines = doc.splitTextToSize(row[i], cellW);
      doc.text(lines[0] || '', cx, y);
      cx += cols[i].w;
    }
    if ((fileManifest.indexOf(m) % 2) === 0) {
      doc.setFillColor(248, 250, 252);
      doc.rect(ml, y - 3.2, usable, 4.2, 'F');
      cx = ml + 1;
      for (let i = 0; i < cols.length; i++) {
        const cellW = cols[i].w - 2;
        const lines = doc.splitTextToSize(row[i], cellW);
        doc.text(lines[0] || '', cx, y);
        cx += cols[i].w;
      }
    }
    y += 4.5;
  }

  y += 4;
  doc.setFontSize(7);
  doc.setTextColor(100, 116, 139);
  doc.text(t('depositoManifestTotal') + ': ' + fileManifest.length + (fileManifest.length === 1 ? ' file' : ' files'), ml, y);

  // Disclaimer immagini sensibili senza omissis
  try {
    const ids = opts && opts.sensitiveNoOmissisProofIds;
    if (ids && ids.size > 0) {
      y += 8;
      doc.setFontSize(9);
      doc.setTextColor(146, 64, 14);
      const title = t('depositoSensitiveDisclaimerTitle') || 'Avviso — immagini sensibili senza oscuramento';
      doc.text(title, ml, y);
      y += 5;
      doc.setFontSize(8);
      doc.setTextColor(60, 60, 60);
      const body = t('depositoSensitiveDisclaimerBody') || 'Il pacchetto contiene immagini marcate come sensibili per le quali non e\' stato applicato alcun omissis vettoriale. Verificare prima del deposito.';
      const lines = doc.splitTextToSize(body, doc.internal.pageSize.getWidth() - 40);
      doc.text(lines, ml, y);
      y += lines.length * 4 + 2;
      doc.text('ID prove: ' + [...ids].join(', '), ml, y);
    }
  } catch(_) {}

  return doc.output('arraybuffer');
}

function _genAttestPDF(opts) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const pw = doc.internal.pageSize.getWidth();
  const ml = 20, mr = 20;
  const usable = pw - ml - mr;
  const { depositType, depositName, depositTitle, depositForo, depositDate, depositPlace } = opts;
  const fullName = (depositTitle ? depositTitle + ' ' : '') + depositName;
  const selCases = _depositAllData.cases.filter(c => opts.selCaseIds.has(c.id));
  const caseTitle = selCases[0]?.title || selCases[0]?.descriptionIt || '';

  doc.setFillColor(30, 41, 59);
  doc.rect(0, 0, pw, 22, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(16);
  doc.setFont('helvetica', 'bold');
  doc.text('UXG', ml, 13);
  doc.setFontSize(13);
  doc.text(t('depositoAttestTitle'), ml + 20, 10);
  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.text(caseTitle, ml + 20, 16);

  let y = 40;

  let attestText = '';
  if (depositType === 'lawyer') {
    attestText = t('depositoAttestLawyer').replace('{name}', fullName).replace('{foro}', depositForo);
  } else {
    attestText = t('depositoAttestPrivate').replace('{name}', fullName);
  }
  attestText = attestText.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#039;/g, "'");

  doc.setTextColor(30, 41, 59);
  doc.setFontSize(10);
  const lines = doc.splitTextToSize(attestText, usable);
  doc.text(lines, ml, y);
  y += lines.length * 5 + 15;

  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.text(t('depositoAttestPlace') + ':', ml, y);
  doc.setFont('helvetica', 'normal');
  doc.text(depositPlace || '', ml + 30, y);
  y += 8;
  doc.setFont('helvetica', 'bold');
  doc.text(t('depositoAttestDate') + ':', ml, y);
  doc.setFont('helvetica', 'normal');
  doc.text(depositDate || '', ml + 30, y);
  y += 25;

  doc.setFont('helvetica', 'bold');
  doc.text(t('depositoAttestSign'), pw - mr - 60, y);
  y += 20;
  doc.setDrawColor(30, 41, 59);
  doc.line(pw - mr - 70, y, pw - mr, y);
  y += 5;
  doc.setFontSize(9);
  doc.setFont('helvetica', 'italic');
  doc.setTextColor(100, 116, 139);
  doc.text(fullName, pw - mr - 70, y);

  return doc.output('arraybuffer');
}

// =====================================================================
// _genRelataDepositoPDF — Relata di deposito (Task: relata in pacchetto)
// ---------------------------------------------------------------------
// Documento di accompagnamento al pacchetto di deposito: dichiara
// l'esponente/difensore, il caso, l'oggetto del deposito, il riepilogo
// quantitativo del contenuto e attesta integrità via i PDF tecnici.
// Va letto insieme a manifesto_integrita.pdf (SHA-256 file-by-file)
// e attestazione_conformita.pdf (dichiarazione di conformità).
// =====================================================================
function _genRelataDepositoPDF(d, opts) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const pw = doc.internal.pageSize.getWidth();
  const ml = 20, mr = 20;
  const usable = pw - ml - mr;
  const { depositType, depositName, depositTitle, depositForo, depositDate, depositPlace, fileManifest } = opts;
  const fullName = (depositTitle ? depositTitle + ' ' : '') + (depositName || '');
  const selCases = (d?.cases || []).filter(c => opts.selCaseIds.has(c.id));
  const caseTitle = selCases[0]?.title || selCases[0]?.descriptionIt || '';
  const isLawyer = depositType === 'lawyer';

  // Header banner
  doc.setFillColor(30, 41, 59);
  doc.rect(0, 0, pw, 22, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(16); doc.setFont('helvetica', 'bold');
  doc.text('UXG', ml, 13);
  doc.setFontSize(13);
  doc.text(t('depositoRelataTitle') || 'RELATA DI DEPOSITO', ml + 20, 10);
  doc.setFontSize(9); doc.setFont('helvetica', 'normal');
  doc.text(caseTitle, ml + 20, 16);

  let y = 36;
  doc.setTextColor(30, 41, 59);

  doc.setFontSize(11); doc.setFont('helvetica', 'bold');
  doc.text(t('depositoRelataIntest') || 'Esponente / Difensore', ml, y); y += 6;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const intest = [
    fullName,
    isLawyer
      ? (t('depositoRelataLawyerLine') || 'Avvocato iscritto al Foro di {foro}').replace('{foro}', depositForo || '—')
      : (t('depositoRelataPrivateLine') || 'In proprio (autotutela ai sensi dell\'art. 24 Cost.)')
  ].filter(Boolean);
  intest.forEach(line => { doc.text(line, ml, y); y += 5; });
  y += 4;

  doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.text(t('depositoRelataBodyTitle') || 'Oggetto del deposito', ml, y); y += 6;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const bodyTpl = t('depositoRelataBody') || 'Il sottoscritto deposita il presente pacchetto telematico contenente i documenti, gli atti e le prove di seguito elencati e dettagliati nella lista_deposito.pdf, attestandone la conformità agli originali e l\'integrità mediante le impronte SHA-256 riportate in manifesto_integrita.pdf e l\'attestazione di conformità in attestazione_conformita.pdf.';
  const corpo = bodyTpl
    .replace('{name}', fullName)
    .replace('{date}', depositDate || '')
    .replace('{place}', depositPlace || '')
    .replace('{case}', caseTitle || '');
  const wrap = doc.splitTextToSize(corpo, usable);
  doc.text(wrap, ml, y); y += wrap.length * 5 + 6;

  doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
  doc.text(t('depositoRelataCounts') || 'Riepilogo contenuto', ml, y); y += 6;
  doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
  const counts = [
    [t('cases') || 'Casi', opts.selCaseIds?.size || 0],
    [t('proceedings') || 'Procedimenti', opts.selProcIds?.size || 0],
    [t('facts') || 'Fatti', opts.selFactIds?.size || 0],
    [t('acts') || 'Atti', opts.selActIds?.size || 0],
    [t('proofs') || 'Prove', opts.selProofIds?.size || 0],
    [t('files') || 'File allegati', (fileManifest || []).length],
  ];
  counts.forEach(([k, v]) => {
    doc.setFont('helvetica', 'bold'); doc.text(k + ':', ml, y);
    doc.setFont('helvetica', 'normal'); doc.text(String(v), ml + 60, y);
    y += 5;
  });
  y += 6;

  if (y > 240) { doc.addPage(); y = 30; }
  doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
  doc.text((t('depositoAttestPlace') || 'Luogo') + ':', ml, y);
  doc.setFont('helvetica', 'normal'); doc.text(depositPlace || '—', ml + 30, y); y += 6;
  doc.setFont('helvetica', 'bold'); doc.text((t('depositoAttestDate') || 'Data') + ':', ml, y);
  doc.setFont('helvetica', 'normal'); doc.text(depositDate || '—', ml + 30, y); y += 16;

  doc.setFont('helvetica', 'bold');
  doc.text(t('depositoAttestSign') || 'Firma', pw - mr - 60, y);
  y += 18;
  doc.setDrawColor(30, 41, 59); doc.line(pw - mr - 70, y, pw - mr, y); y += 5;
  doc.setFontSize(9); doc.setFont('helvetica', 'italic');
  doc.setTextColor(100, 116, 139);
  doc.text(fullName || '—', pw - mr - 70, y);

  // Footer
  doc.setTextColor(120); doc.setFontSize(8);
  const ts = new Date().toISOString().replace('T', ' ').substring(0, 19);
  doc.text((t('depositoRelataFooter') || 'Documento redatto dal sottoscritto in data {ts}.').replace('{ts}', ts), ml, 290);

  return doc.output('arraybuffer');
}

function _genListaDepositoPDF(d, opts) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const pw = doc.internal.pageSize.getWidth();
  const ph = doc.internal.pageSize.getHeight();
  const ml = 20, mr = 20;
  const usable = pw - ml - mr;
  const { selActIds, selFactIds, selProcIds, selCaseIds } = opts;
  const selCases = d.cases.filter(c => selCaseIds.has(c.id));
  const selProcs = d.proceedings.filter(p => selProcIds.has(p.id));
  const genDate = new Date().toLocaleDateString(currentLang === 'it' ? 'it-IT' : 'en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  const caseTitle = selCases[0]?.title || selCases[0]?.descriptionIt || '';

  doc.setFillColor(30, 41, 59);
  doc.rect(0, 0, pw, 22, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(16);
  doc.setFont('helvetica', 'bold');
  doc.text('UXG', ml, 13);
  doc.setFontSize(13);
  doc.text(t('depositoDocSection'), ml + 20, 10);
  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.text(caseTitle + ' \u2014 ' + genDate, ml + 20, 16);

  let y = 32;

  function checkPage(need) {
    if (y + need > ph - 15) { doc.addPage(); y = 20; }
  }

  function printLine(text, indent, bold, fontSize, color) {
    checkPage(6);
    doc.setFontSize(fontSize || 9);
    doc.setFont('helvetica', bold ? 'bold' : 'normal');
    doc.setTextColor(color ? color[0] : 30, color ? color[1] : 41, color ? color[2] : 59);
    const x = ml + (indent || 0);
    const lines = doc.splitTextToSize(text, usable - (indent || 0));
    doc.text(lines, x, y);
    y += lines.length * (fontSize ? fontSize * 0.45 : 4) + 1.5;
  }

  for (const c of selCases) {
    const title = (currentLang === 'en' && c.titleEn) ? c.titleEn : (c.title || '');
    printLine(title, 0, true, 11);
    y += 2;

    const caseProcs = selProcs.filter(p => p.caseId === c.id && !p.parentProceedingId);
    for (const p of caseProcs) {
      _printProcTreePDF(doc, d, opts, p, 4, printLine, checkPage);
    }
  }

  y += 6;
  checkPage(20);
  doc.setDrawColor(226, 232, 240);
  doc.line(ml, y, pw - mr, y);
  y += 6;
  printLine(t('depositoSectionManifest') + '  \u2014  manifesto_integrita.pdf', 0, false, 8, [100, 116, 139]);
  printLine(t('depositoSectionAttest') + '  \u2014  attestazione_conformita.pdf', 0, false, 8, [100, 116, 139]);

  return doc.output('arraybuffer');
}

// =====================================================================
// _genSubjectSchedaPDF / _downloadSubjectSchedaPDF
// ---------------------------------------------------------------------
// Scheda PDF del soggetto scaricabile dal dettaglio. Composizione:
//   pag 1: copertina con dati anagrafici completi + indice (con numeri
//          di pagina di ogni sezione)
//   pag 2+: Note (lingua attiva IT o EN, fallback IT se EN vuota)
//   pag 3+: Ruoli professionali
//   pag 4+: Fatti soggettivi
//   pag 5+: Circostanze soggettive
// Le sezioni rimangono su pagina propria; se eccedono, ulteriori pagine
// sono aggiunte e tutte vengono numerate "X di N" / "X of N" in basso.
// La pagina 1 viene riempita per ultima cosi' da poter inserire i numeri
// di pagina reali nell'indice.
// =====================================================================
async function _genSubjectSchedaPDF(subjectId) {
  const s = await DB.getSubject(subjectId);
  if (!s) return null;
  await _loadAllLists();
  const lang = currentLang;
  const T = (it, en) => (lang === 'en' ? en : it);
  const fmtDate = (iso) => iso ? iso.split('-').reverse().join('/') : '';

  const roles = s.roles || [];
  const factEntries = (await DB.getSubjectFacts(subjectId)) || [];
  const circEntries = (await DB.getSubjectCircumstances(subjectId)) || [];
  const note = lang === 'it' ? (s.descriptionIt || '') : (s.descriptionEn || s.descriptionIt || '');

  const fullName = `${s.salutation ? s.salutation + ' ' : ''}${s.firstName || ''} ${s.lastName || ''}`.trim();

  const _shortCode = await _subjectShortCode(s);
  const _hdrTag = _shortCode || 'UXG';

  // ---- Raccolta link soggetto + casi collegati ----
  const _allSubjLinks = (await DB.getSubjectLinks(subjectId)) || [];

  // Raccolta CASI: via link diretti su 'case' + via procedimenti
  const casiRows = [];
  const _seenCase = new Set();
  for (const l of _allSubjLinks) {
    let _caseId = null;
    if (l.entityType === 'case') {
      _caseId = l.entityId;
    } else if (l.entityType === 'proceeding') {
      const _p = await DB.getProceeding(l.entityId);
      if (_p && _p.caseId != null) _caseId = _p.caseId;
    }
    if (_caseId == null || _seenCase.has(_caseId)) continue;
    _seenCase.add(_caseId);
    const _c = await DB.getCase(_caseId);
    if (!_c) continue;
    const _title = (lang === 'en' ? (_c.titleEn || _c.titleIt || _c.title) : (_c.titleIt || _c.title || _c.titleEn)) || ('Caso #' + _caseId);
    casiRows.push({ id: _caseId, title: _title });
  }

  // Raccolta "Capo Ufficio" (soggetto come PM)
  const capoUfficioRows = [];
  const _seenCU = new Set();

  // Mappa sigla provincia (2 lettere) → nome esteso, costruita una sola volta
  let _provSiglaMap = null;
  async function _getProvSiglaMap() {
    if (_provSiglaMap) return _provSiglaMap;
    _provSiglaMap = {};
    try {
      const _comuni = (await GeoDB.getAllComuni()) || [];
      for (const c of _comuni) {
        if (c.provincia && c.provinciaNome && !_provSiglaMap[c.provincia.toUpperCase()]) {
          _provSiglaMap[c.provincia.toUpperCase()] = c.provinciaNome;
        }
      }
    } catch (_e) { /* GeoDB non disponibile: lascia mappa vuota */ }
    return _provSiglaMap;
  }

  // Strippa prefissi tipo "P.d.R.", "P.G.R.", "Procura della Repubblica di",
  // "Tribunale di", ecc. e, se rimane una sigla provincia, la espande in nome.
  async function _normalizeSede(raw) {
    if (!raw) return '';
    let s = String(raw).trim();
    const _stripPatterns = [
      /^\s*Procura Generale della Repubblica presso la Corte d['']Appello di\s+/i,
      /^\s*Procura Generale della Repubblica di\s+/i,
      /^\s*Procura della Repubblica presso il Tribunale di\s+/i,
      /^\s*Procura della Repubblica di\s+/i,
      /^\s*P\.?\s*G\.?\s*R\.?\s+/i,
      /^\s*P\.?\s*d\.?\s*R\.?\s+/i,
      /^\s*Tribunale di\s+/i,
      /^\s*Trib\.?\s+/i,
      /^\s*Corte d['']Appello di\s+/i,
      /^\s*C\.?\s*d\.?\s*A\.?\s+/i,
    ];
    for (const re of _stripPatterns) {
      if (re.test(s)) { s = s.replace(re, '').trim(); break; }
    }
    if (/^[A-Z]{2}$/.test(s)) {
      const _m = await _getProvSiglaMap();
      if (_m[s]) return _m[s];
    }
    return s;
  }

  for (const l of _allSubjLinks) {
    if (l.entityType !== 'proceeding' || l.qualificaProcessuale !== 'pm') continue;
    const _proc = await DB.getProceeding(l.entityId);
    if (!_proc) continue;
    const _pdrId = _proc.vigilanceSubjects && _proc.vigilanceSubjects.procuratoreRepubblica;
    if (!_pdrId) continue;
    const _ph0 = ((_proc.specificData && _proc.specificData.phases) || [])[0] || {};
    const _rawSede = _ph0.tribunale || _proc.autoritaProcedente || '';
    const _sede = await _normalizeSede(_rawSede);
    const _dedup = _pdrId + '|' + _sede;
    if (_seenCU.has(_dedup)) continue;
    _seenCU.add(_dedup);
    const _pdr = await DB.getSubject(_pdrId);
    if (!_pdr) continue;
    const _pdrName = ((_pdr.salutation ? _pdr.salutation + ' ' : '') + (_pdr.firstName || '') + ' ' + (_pdr.lastName || '')).trim();
    capoUfficioRows.push({ sede: _sede, pdrName: _pdrName });
  }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const pw = doc.internal.pageSize.getWidth();
  const ph = doc.internal.pageSize.getHeight();
  const ml = 18, mr = 18, mb = 16;
  const usable = pw - ml - mr;

  function drawHeader(title) {
    doc.setFillColor(30, 41, 59);
    doc.rect(0, 0, pw, 14, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(10);
    doc.setFont('helvetica', 'bold');
    doc.text(T('Scheda Soggetto', 'Subject Sheet') + ': ' + _hdrTag, ml, 9);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    const nameLine = fullName.length > 60 ? fullName.slice(0, 57) + '…' : fullName;
    doc.text(nameLine, pw - mr, 9, { align: 'right' });
    doc.setTextColor(0, 0, 0);
    if (title) {
      doc.setFontSize(14);
      doc.setFont('helvetica', 'bold');
      doc.text(title, ml, 22);
      doc.setDrawColor(30, 41, 59);
      doc.setLineWidth(0.4);
      doc.line(ml, 24, pw - mr, 24);
    }
  }

  function ensure(y, h) {
    if (y + h > ph - mb) {
      doc.addPage();
      drawHeader('');
      return 22;
    }
    return y;
  }

  function writeWrapped(text, y, opts) {
    opts = opts || {};
    const fontSize = opts.fontSize || 10;
    doc.setFontSize(fontSize);
    doc.setFont('helvetica', opts.bold ? 'bold' : (opts.italic ? 'italic' : 'normal'));
    const lines = doc.splitTextToSize(String(text || ''), opts.width || usable);
    const lh = fontSize * 0.42 + 1;
    for (const ln of lines) {
      y = ensure(y, lh);
      doc.text(ln, opts.x != null ? opts.x : ml, y);
      y += lh;
    }
    return y;
  }

  // ===== Pagina 1 (placeholder, dipinta dopo) =====
  drawHeader('');
  const coverPage = 1;

  // Cover: titolo + nome
  doc.setTextColor(0, 0, 0);
  doc.setFontSize(20);
  doc.setFont('helvetica', 'bold');
  doc.text(T('Scheda Soggetto', 'Subject Sheet'), ml, 30);
  doc.setFontSize(15);
  doc.setFont('helvetica', 'normal');
  doc.text(fullName || '—', ml, 39);

  // ===== DATI ANAGRAFICI (pagina 1) =====
  let cy = 50;
  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.setFillColor(241, 245, 249);
  doc.rect(ml, cy - 5, usable, 7, 'F');
  doc.text(T('DATI ANAGRAFICI', 'PERSONAL DATA'), ml + 2, cy);
  cy += 8;

  const luogoNasc = [s.birthCity, s.birthProvince, s.birthCountry].filter(Boolean).join(', ');
  const residenza = [s.resCity, s.resProvince, s.resCountry].filter(Boolean).join(', ');
  const dataRows = [
    [T('Appellativo', 'Salutation'), s.salutation || '—'],
    [T('Nome', 'First name'), s.firstName || '—'],
    [T('Cognome', 'Last name'), s.lastName || '—'],
    [T('Sesso', 'Sex'), s.sesso || '—'],
    [T('Codice Fiscale', 'Fiscal Code'), s.fiscalCode || '—'],
    [T('Data di Nascita', 'Date of Birth'), fmtDate(s.birthDate) || '—'],
    [T('Luogo di Nascita', 'Place of Birth'), luogoNasc || '—'],
    [T('Indirizzo', 'Address'), s.address || '—'],
    [T('Residenza/Domicilio', 'Residence/Domicile'), residenza || '—'],
    [T('Telefono', 'Phone'), s.phone || '—'],
    ['PEC', s.pec || '—']
  ];
  const lblW = 50;
  doc.setFontSize(9);
  for (const [k, v] of dataRows) {
    doc.setFont('helvetica', 'bold');
    doc.text(k + ':', ml, cy);
    doc.setFont('helvetica', 'normal');
    const lns = doc.splitTextToSize(String(v), usable - lblW);
    doc.text(lns, ml + lblW, cy);
    cy += Math.max(5, lns.length * 4.2);
  }

  // ===== Raccolta PARTE OFFESA (soggetti parte offesa nei procedimenti collegati) =====
  // L'esponente (profilo dell'app) viene sottolineato.
  let _esponenteCF = '';
  try {
    const _prof = (typeof DB.getUserProfile === 'function') ? (await DB.getUserProfile()) : null;
    _esponenteCF = (_prof && _prof.fiscalCode ? String(_prof.fiscalCode) : '').trim().toUpperCase();
  } catch (e) {}
  const parteOffesaRows = [];
  const _seenPO = new Set();
  for (const l of _allSubjLinks) {
    if (l.entityType !== 'proceeding') continue;
    const _procLinks = (await DB.getEntitySubjects('proceeding', l.entityId)) || [];
    for (const pl of _procLinks) {
      const _kind = (typeof _effectiveLinkKind === 'function') ? _effectiveLinkKind(pl) : pl.linkKind;
      if (_kind !== 'parteOffesa') continue;
      if (pl.subjectId == null || _seenPO.has(pl.subjectId)) continue;
      const _subj = await DB.getSubject(pl.subjectId);
      if (!_subj) continue;
      _seenPO.add(pl.subjectId);
      const _nm = ((_subj.salutation ? _subj.salutation + ' ' : '') + (_subj.firstName || '') + ' ' + (_subj.lastName || '')).trim()
        || _subj.denominazione || ('#' + pl.subjectId);
      const _isEsp = !!(_esponenteCF && _subj.fiscalCode && String(_subj.fiscalCode).trim().toUpperCase() === _esponenteCF);
      parteOffesaRows.push({ id: pl.subjectId, name: _nm, isEsponente: _isEsp });
    }
  }

  // ===== Riserva spazio INDICE (in fondo a pagina 1) =====
  let INDEX_RESERVED_H = 56;
  if (capoUfficioRows.length > 0) INDEX_RESERVED_H += 7;
  if (casiRows.length > 0) INDEX_RESERVED_H += 7;
  if (parteOffesaRows.length > 0) INDEX_RESERVED_H += 7;
  const indexTopReserved = ph - mb - INDEX_RESERVED_H;

  // ===== RUOLI PROFESSIONALI (tabella, in pagina 1, con overflow) =====
  cy += 4;
  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.setFillColor(241, 245, 249);
  doc.rect(ml, cy - 5, usable, 7, 'F');
  doc.text(T('RUOLI PROFESSIONALI', 'PROFESSIONAL ROLES'), ml + 2, cy);
  cy += 6;

  let rolesPage; // '1' oppure '1–N'
  let rolesEndPage = 1;

  if (roles.length === 0) {
    doc.setFontSize(9);
    doc.setFont('helvetica', 'italic');
    doc.setTextColor(100, 116, 139);
    doc.text(T('Nessun ruolo professionale assegnato.', 'No professional roles assigned.'), ml, cy);
    doc.setTextColor(0, 0, 0);
    cy += 5;
    rolesPage = '1';
  } else {
    const colW = [usable * 0.45, usable * 0.25, usable * 0.15, usable * 0.15];
    const colX = [ml, ml + colW[0], ml + colW[0] + colW[1], ml + colW[0] + colW[1] + colW[2]];
    const headerLabels = [T('Ruolo', 'Role'), T('Luogo', 'Place'), T('Dal', 'From'), T('Al', 'To')];
    const rowH = 5.5;

    function drawRolesTblHeader(yy) {
      doc.setFillColor(226, 232, 240);
      doc.rect(ml, yy, usable, 6, 'F');
      doc.setFontSize(9);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(0, 0, 0);
      for (let i = 0; i < 4; i++) doc.text(headerLabels[i], colX[i] + 1.5, yy + 4);
      doc.setFont('helvetica', 'normal');
      return yy + 6;
    }
    function drawRoleRow(r, yy) {
      const ri = _findItem(_allRoles, r.roleId) || _findItem(_allSubcategories, r.subcategoryId) || _findItem(_allCategories, r.categoryId);
      const lbl = ri ? DB.getItemLabel(ri, lang) : '—';
      const luogo = r.citta || r.sede || r.subOrgName || r.orgName || '—';
      const dal = r.startDate ? _formatDate(r.startDate) : '—';
      const isOngoing = !r.endDate;
      const al = isOngoing ? T('in corso', 'current') : _formatDate(r.endDate);
      doc.setDrawColor(220, 220, 220);
      doc.setLineWidth(0.1);
      doc.line(ml, yy + rowH, ml + usable, yy + rowH);
      doc.setFontSize(9);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(0, 0, 0);
      const lblTrunc = doc.splitTextToSize(String(lbl), colW[0] - 3)[0] || '';
      const luogoTrunc = doc.splitTextToSize(String(luogo), colW[1] - 3)[0] || '';
      doc.text(lblTrunc, colX[0] + 1.5, yy + 4);
      doc.text(luogoTrunc, colX[1] + 1.5, yy + 4);
      doc.text(dal, colX[2] + 1.5, yy + 4);
      if (isOngoing) {
        doc.setFont('helvetica', 'italic');
        doc.setTextColor(34, 139, 34);
        doc.text(al, colX[3] + 1.5, yy + 4);
        doc.setTextColor(0, 0, 0);
        doc.setFont('helvetica', 'normal');
      } else {
        doc.text(al, colX[3] + 1.5, yy + 4);
      }
      return yy + rowH;
    }

    cy = drawRolesTblHeader(cy);
    let rolesRendered = 0;
    for (let i = 0; i < roles.length; i++) {
      if (cy + rowH > indexTopReserved) break;
      cy = drawRoleRow(roles[i], cy);
      rolesRendered++;
    }
    const _cyAfterRolesPage1 = cy;

    if (rolesRendered < roles.length) {
      const remaining = roles.slice(rolesRendered);
      doc.addPage();
      drawHeader(T('Ruoli Professionali (segue)', 'Professional Roles (cont.)'));
      rolesEndPage = doc.getNumberOfPages();
      let oy = 32;
      oy = drawRolesTblHeader(oy);
      for (const r of remaining) {
        if (oy + rowH > ph - mb) {
          doc.addPage();
          drawHeader(T('Ruoli Professionali (segue)', 'Professional Roles (cont.)'));
          rolesEndPage = doc.getNumberOfPages();
          oy = 32;
          oy = drawRolesTblHeader(oy);
        }
        oy = drawRoleRow(r, oy);
      }
      rolesPage = rolesEndPage > 1 ? ('1–' + rolesEndPage) : '1';
      // Torna a pagina 1 per continuare con CAPO UFFICIO
      doc.setPage(1);
      cy = _cyAfterRolesPage1;
    } else {
      rolesPage = '1';
    }
  }

  // ===== CAPO UFFICIO (pagina 1 + eventuali pagine "(segue)") =====
  let capoUfficioPage = null;
  let capoUfficioEndPage = doc.getNumberOfPages();
  if (capoUfficioRows.length > 0) {
    cy += 4;
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.setFillColor(241, 245, 249);
    doc.rect(ml, cy - 5, usable, 7, 'F');
    doc.setTextColor(0, 0, 0);
    doc.text(T('CAPO UFFICIO', 'HEAD OFFICE'), ml + 2, cy);
    cy += 7;

    function _drawCuRow(row, yy) {
      doc.setFontSize(10);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(0, 0, 0);
      const _prefix = row.sede
        ? T('Procuratore della Repubblica di ', 'Public Prosecutor of ') + row.sede + ' '
        : T('Procuratore della Repubblica ', 'Public Prosecutor ');
      doc.text(_prefix, ml, yy);
      const _prefixW = doc.getTextWidth(_prefix);
      doc.setFont('helvetica', 'bold');
      doc.text(row.pdrName, ml + _prefixW, yy);
      doc.setFont('helvetica', 'normal');
      return yy + 4.5 + 1.5;
    }
    function _cuRowH(_row) { return 4.5 + 1.5; }

    const _cuStartPage = doc.getCurrentPageInfo().pageNumber;
    let _renderedCU = 0;
    for (const row of capoUfficioRows) {
      if (cy + _cuRowH(row) > indexTopReserved) break;
      cy = _drawCuRow(row, cy);
      _renderedCU++;
    }
    const _cyAfterCuPage1 = cy;
    capoUfficioEndPage = _cuStartPage;

    if (_renderedCU < capoUfficioRows.length) {
      const remaining = capoUfficioRows.slice(_renderedCU);
      doc.addPage();
      drawHeader(T('Capo Ufficio (segue)', 'Head Office (cont.)'));
      capoUfficioEndPage = doc.getNumberOfPages();
      let oy = 32;
      for (const row of remaining) {
        if (oy + _cuRowH(row) > ph - mb) {
          doc.addPage();
          drawHeader(T('Capo Ufficio (segue)', 'Head Office (cont.)'));
          capoUfficioEndPage = doc.getNumberOfPages();
          oy = 32;
        }
        oy = _drawCuRow(row, oy);
      }
      // Torna a pagina 1 per continuare con CASO
      doc.setPage(1);
      cy = _cyAfterCuPage1;
    }

    capoUfficioPage = capoUfficioEndPage > _cuStartPage
      ? (_cuStartPage + '–' + capoUfficioEndPage)
      : String(_cuStartPage);
  }

  // ===== CASO (pagina 1 + eventuali pagine "(segue)") =====
  let casiPage = null;
  let casiEndPage = doc.getNumberOfPages();
  if (casiRows.length > 0) {
    cy += 4;
    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.setFillColor(241, 245, 249);
    doc.rect(ml, cy - 5, usable, 7, 'F');
    doc.setTextColor(0, 0, 0);
    doc.text(T('CASO', 'CASE'), ml + 2, cy);
    cy += 7;

    function _drawCaseRow(row, yy) {
      doc.setFontSize(10);
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(0, 0, 0);
      const _line = doc.splitTextToSize(String(row.title), usable)[0] || '';
      doc.text(_line, ml, yy);
      return yy + 4.5 + 1.0;
    }
    function _caseRowH() { return 4.5 + 1.0; }

    const _caseStartPage = doc.getCurrentPageInfo().pageNumber;
    let _renderedCase = 0;
    for (const row of casiRows) {
      if (cy + _caseRowH() > indexTopReserved) break;
      cy = _drawCaseRow(row, cy);
      _renderedCase++;
    }
    const _cyAfterCasePage1 = cy;
    casiEndPage = _caseStartPage;

    if (_renderedCase < casiRows.length) {
      const remaining = casiRows.slice(_renderedCase);
      doc.addPage();
      drawHeader(T('Caso (segue)', 'Case (cont.)'));
      casiEndPage = doc.getNumberOfPages();
      let oy = 32;
      for (const row of remaining) {
        if (oy + _caseRowH() > ph - mb) {
          doc.addPage();
          drawHeader(T('Caso (segue)', 'Case (cont.)'));
          casiEndPage = doc.getNumberOfPages();
          oy = 32;
        }
        oy = _drawCaseRow(row, oy);
      }
      // Torna a pagina 1 per continuare con PARTE OFFESA
      doc.setPage(1);
      cy = _cyAfterCasePage1;
    }

    casiPage = casiEndPage > _caseStartPage
      ? (_caseStartPage + '–' + casiEndPage)
      : String(_caseStartPage);
  }

  // ===== PARTE OFFESA (sezione unica, niente "(segue)") =====
  // Se tutta la lista entra nello spazio rimanente di pagina 1 viene resa lì,
  // altrimenti l'intero blocco (titolo + righe) viene spostato su una pagina
  // dedicata. Eventuali pagine successive necessarie ripetono solo il titolo
  // di sezione, senza suffisso "(segue)".
  let parteOffesaPage = null;
  let parteOffesaEndPage = doc.getNumberOfPages();
  if (parteOffesaRows.length > 0) {
    function _drawPoRow(row, yy) {
      doc.setFontSize(10);
      doc.setFont('helvetica', row.isEsponente ? 'bold' : 'normal');
      doc.setTextColor(0, 0, 0);
      const _line = doc.splitTextToSize(String(row.name), usable)[0] || '';
      doc.text(_line, ml, yy);
      if (row.isEsponente) {
        const _w = doc.getTextWidth(_line);
        doc.setLineWidth(0.3);
        doc.setDrawColor(0, 0, 0);
        doc.line(ml, yy + 0.8, ml + _w, yy + 0.8);
      }
      return yy + 4.5 + 1.0;
    }
    function _drawPoHeader(yy) {
      doc.setFontSize(11);
      doc.setFont('helvetica', 'bold');
      doc.setFillColor(241, 245, 249);
      doc.rect(ml, yy - 5, usable, 7, 'F');
      doc.setTextColor(0, 0, 0);
      doc.text(T('PARTE OFFESA', 'INJURED PARTY'), ml + 2, yy);
      return yy + 7;
    }
    const _poRowH = 4.5 + 1.0;
    const _poBlockH = 4 + 7 + parteOffesaRows.length * _poRowH;

    if (cy + _poBlockH <= indexTopReserved) {
      // Cabe tutto su pagina 1
      cy += 4;
      cy = _drawPoHeader(cy);
      for (const row of parteOffesaRows) cy = _drawPoRow(row, cy);
      parteOffesaPage = String(doc.getCurrentPageInfo().pageNumber);
      parteOffesaEndPage = doc.getNumberOfPages();
    } else {
      // Pagina dedicata (più pagine se necessario, senza "(segue)")
      doc.addPage();
      drawHeader(T('Parte Offesa', 'Injured Party'));
      const _poStartPage = doc.getNumberOfPages();
      let oy = 32;
      oy = _drawPoHeader(oy);
      parteOffesaEndPage = _poStartPage;
      for (const row of parteOffesaRows) {
        if (oy + _poRowH > ph - mb) {
          doc.addPage();
          drawHeader(T('Parte Offesa', 'Injured Party'));
          parteOffesaEndPage = doc.getNumberOfPages();
          oy = 32;
          oy = _drawPoHeader(oy);
        }
        oy = _drawPoRow(row, oy);
      }
      parteOffesaPage = parteOffesaEndPage > _poStartPage
        ? (_poStartPage + '–' + parteOffesaEndPage)
        : String(_poStartPage);
    }
  }

  // ===== Pagina Note =====
  doc.addPage();
  drawHeader(T('Note', 'Notes'));
  const notesPage = doc.getNumberOfPages();
  let y = 32;
  doc.setFontSize(9);
  doc.setFont('helvetica', 'italic');
  doc.setTextColor(100, 116, 139);
  doc.text(T('Lingua: ', 'Language: ') + (lang === 'en' ? 'EN' : 'IT'), ml, y);
  doc.setTextColor(0, 0, 0);
  y += 6;
  if (note && note.trim()) {
    y = writeWrapped(note, y, { fontSize: 11 });
  } else {
    y = writeWrapped(T('Nessuna nota.', 'No notes.'), y, { fontSize: 10, italic: true });
  }

  // ===== Pagina Ruoli in Procedimenti (lista a card) =====
  doc.addPage();
  drawHeader(T('Ruoli in Procedimenti', 'Roles in Proceedings'));
  const proceduralPage = doc.getNumberOfPages();
  y = 32;

  const procLinksPdf = _allSubjLinks.filter(l => l.entityType === 'proceeding' && l.qualificaProcessuale);

  if (procLinksPdf.length === 0) {
    y = writeWrapped(T('Nessun ruolo processuale collegato.', 'No procedural roles linked.'), y, { fontSize: 10, italic: true });
  } else {
    // Carica dati procedimenti/casi e info ausiliarie
    const enriched = [];
    const procCache = {};
    const caseCache = {};
    const pmInfoCache = {};
    const procIndCache = {};
    const procOffCache = {};
    const pdrCache = {};
    const myReatiCache = {};

    for (const l of procLinksPdf) {
      let proc = procCache[l.entityId];
      if (proc === undefined) { proc = (await DB.getProceeding(l.entityId)) || null; procCache[l.entityId] = proc; }
      let caseObj = null;
      if (proc && proc.caseId != null) {
        caseObj = caseCache[proc.caseId];
        if (caseObj === undefined) { caseObj = (await DB.getCase(proc.caseId)) || null; caseCache[proc.caseId] = caseObj; }
      }
      enriched.push({ link: l, proc, caseObj });
    }

    // PM per procedimento
    for (const e of enriched) {
      if (!e.proc || pmInfoCache[e.proc.id] !== undefined) continue;
      const procSubjs = (await DB.getEntitySubjects('proceeding', e.proc.id)) || [];
      const pmLink = procSubjs.find(ps => ps.qualificaProcessuale === 'pm');
      if (pmLink) {
        const pmSubj = await DB.getSubject(pmLink.subjectId);
        pmInfoCache[e.proc.id] = pmSubj
          ? { name: ((pmSubj.salutation ? pmSubj.salutation + ' ' : '') + (pmSubj.firstName || '') + ' ' + (pmSubj.lastName || '')).trim() }
          : null;
      } else {
        pmInfoCache[e.proc.id] = null;
      }
    }

    // Per i link PM: indagati / parti offese / Procuratore della Repubblica
    for (const e of enriched) {
      if (!e.proc || e.link.qualificaProcessuale !== 'pm') continue;
      if (procIndCache[e.proc.id] !== undefined) continue;
      const indagatiArr = (e.proc.specificData && e.proc.specificData.indagati) || [];
      const inds = [], offs = [];
      for (const entry of indagatiArr) {
        let nm = entry.label || '';
        if (entry.subjectId) {
          const subj = await DB.getSubject(entry.subjectId);
          if (subj) nm = ((subj.lastName || '') + ' ' + (subj.firstName || '')).trim() || nm;
        }
        if (!nm) continue;
        if (entry.procRole === 'persona_offesa') offs.push(nm);
        else inds.push(nm);
      }
      procIndCache[e.proc.id] = inds;
      procOffCache[e.proc.id] = offs;
      const pdrId = e.proc.vigilanceSubjects && e.proc.vigilanceSubjects.procuratoreRepubblica;
      if (pdrId) {
        const pdr = await DB.getSubject(pdrId);
        if (pdr) pdrCache[e.proc.id] = ((pdr.salutation ? pdr.salutation + ' ' : '') + (pdr.firstName || '') + ' ' + (pdr.lastName || '')).trim();
      }
    }

    // Reati per il soggetto (quando è indagato/imputato)
    for (const e of enriched) {
      if (!e.proc || e.link.qualificaProcessuale === 'pm') continue;
      if (myReatiCache[e.proc.id] !== undefined) continue;
      const reati = [];
      for (const phase of (e.proc.specificData && e.proc.specificData.phases) || []) {
        for (const ir of (phase.indagatiReati || [])) {
          if (ir.subjectId === subjectId) {
            for (const r of (ir.reati || [])) {
              const rr = (r || '').trim ? r.trim() : r;
              if (rr && !reati.includes(rr)) reati.push(rr);
            }
          }
        }
      }
      const indEntry = ((e.proc.specificData && e.proc.specificData.indagati) || []).find(en => en.subjectId === subjectId);
      if (indEntry) {
        for (const re of (indEntry.reatiEsponente || [])) {
          if (re.label && !reati.includes(re.label)) reati.push(re.label);
        }
      }
      myReatiCache[e.proc.id] = reati;
    }

    // Raggruppa per caso
    const caseGroups = new Map();
    for (const e of enriched) {
      const key = (e.caseObj && e.caseObj.id != null) ? e.caseObj.id : 'no-case';
      if (!caseGroups.has(key)) caseGroups.set(key, { caseObj: e.caseObj, items: [] });
      caseGroups.get(key).items.push(e);
    }

    // Helpers di disegno
    function drawBadgeRight(txt, rx, by, rgb) {
      doc.setFontSize(7.5);
      doc.setFont('helvetica', 'normal');
      const tw = doc.getTextWidth(txt) + 4;
      doc.setFillColor(rgb[0], rgb[1], rgb[2]);
      doc.roundedRect(rx - tw, by - 3.5, tw, 4.8, 1, 1, 'F');
      doc.setTextColor(255, 255, 255);
      doc.text(txt, rx - tw + 2, by);
      doc.setTextColor(0, 0, 0);
      return rx - tw - 1.5;
    }
    function drawBadge(txt, x, by, rgb) {
      doc.setFontSize(7.5);
      doc.setFont('helvetica', 'normal');
      const tw = doc.getTextWidth(txt) + 4;
      doc.setFillColor(rgb[0], rgb[1], rgb[2]);
      doc.roundedRect(x, by - 3.5, tw, 4.8, 1, 1, 'F');
      doc.setTextColor(255, 255, 255);
      doc.text(txt, x + 2, by);
      doc.setTextColor(0, 0, 0);
      return x + tw + 1.5;
    }
    function drawChip(txt, x, by, maxRight) {
      doc.setFontSize(7.5);
      doc.setFont('helvetica', 'normal');
      const lns = doc.splitTextToSize(String(txt), maxRight - x - 3);
      const showTxt = lns[0] + (lns.length > 1 ? '…' : '');
      const tw = doc.getTextWidth(showTxt) + 3;
      doc.setFillColor(241, 245, 249);
      doc.roundedRect(x, by - 3.5, tw, 4.8, 1, 1, 'F');
      doc.setTextColor(50, 50, 50);
      doc.text(showTxt, x + 1.5, by);
      doc.setTextColor(0, 0, 0);
      return x + tw + 1.5;
    }
    function statusBadgeColor(status) {
      if (!status) return [148, 163, 184];
      if (['pen_archiviato', 'archiviato'].includes(status)) return [100, 116, 139];
      if (['pen_condanna', 'pen_assoluzione', 'pen_patteggiamento', 'pen_prescritto', 'pen_definito', 'definito'].includes(status)) return [37, 99, 235];
      return [22, 163, 74];
    }
    function qualBadgeColor(qual) {
      if (['indagato', 'imputato'].includes(qual)) return [220, 38, 38];
      if (['avvocato_costituito', 'avvocato'].includes(qual)) return [124, 58, 237];
      if (qual === 'pm') return [217, 119, 6];
      if (['gip', 'gup', 'giudice_dibattimento', 'giudice_appello', 'giudice_cassazione', 'magistrato'].includes(qual)) return [37, 99, 235];
      if (['persona_offesa', 'parte_civile'].includes(qual)) return [219, 39, 119];
      return [100, 116, 139];
    }

    for (const grp of caseGroups.values()) {
      const caseTitle = grp.caseObj ? (_caseDisplayTitle(grp.caseObj) || '—') : T('Senza caso', 'No case');
      y = ensure(y, 12);
      y += 2;
      doc.setFillColor(248, 250, 252);
      doc.rect(ml, y - 4.5, usable, 6, 'F');
      doc.setFontSize(11);
      doc.setFont('helvetica', 'bold');
      doc.text(T('Caso: ', 'Case: ') + caseTitle, ml + 2, y);
      y += 5;

      // Descrizione del caso
      const caseDescr = grp.caseObj
        ? (lang === 'en' ? (grp.caseObj.descrEn || grp.caseObj.descrIt) : (grp.caseObj.descrIt || grp.caseObj.descrEn)) || ''
        : '';
      if (caseDescr) {
        doc.setFontSize(9);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(0, 0, 0);
        const dLns = doc.splitTextToSize(caseDescr, usable - 4);
        for (let di = 0; di < dLns.length; di++) {
          y = ensure(y, 4.2);
          const isLast = di === dLns.length - 1;
          doc.text(dLns[di], ml + 2, y, isLast ? undefined : { align: 'justify', maxWidth: usable - 4 });
          y += 4.2;
        }
        y += 1;
      }

      for (const item of grp.items) {
        const proc = item.proc;
        const link = item.link;
        const procTitle = proc ? buildProcTitle(proc) : '—';
        const qual = link.qualificaProcessuale;
        const qualLabel = (typeof t === 'function' ? t('procRole_' + qual) : null) || qual;
        const statusKey = (proc && proc.status) || '';
        const statusLbl = statusKey ? ((typeof t === 'function' ? t(statusKey) : null) || statusKey) : T('In corso', 'In progress');
        const dataIscr = (proc && proc.dataIscrizioneRuolo) ? _formatDate(proc.dataIscrizioneRuolo) : '';
        const pmInfo = (proc && pmInfoCache[proc.id]) || null;

        const row2Chips = [];
        if (qual === 'pm') {
          const inds = (proc && procIndCache[proc.id]) || [];
          const offs = (proc && procOffCache[proc.id]) || [];
          if (inds.length) row2Chips.push(T('Indagati: ', 'Defendants: ') + inds.slice(0, 4).join(', ') + (inds.length > 4 ? '…' : ''));
          if (offs.length) row2Chips.push(T('Parti offese: ', 'Victims: ') + offs.slice(0, 4).join(', ') + (offs.length > 4 ? '…' : ''));
        } else if (['indagato', 'imputato'].includes(qual)) {
          const reati = (proc && myReatiCache[proc.id]) || [];
          if (reati.length) row2Chips.push(T('Reati: ', 'Crimes: ') + reati.join(' · '));
        }
        const pdrName = (proc && pdrCache[proc.id]) || '';

        // Stima altezza card
        const titleLines = doc.splitTextToSize(procTitle, usable - 60).length;
        let cardH = 4.5 + titleLines * 4 + 7; // riga titolo + riga 2 badge
        if (row2Chips.length > 1) cardH += (row2Chips.length - 1) * 5;
        if (pdrName && qual === 'pm') cardH += 5;
        cardH += 2;

        y = ensure(y, cardH + 2);

        // Bordo card
        doc.setDrawColor(203, 213, 225);
        doc.setLineWidth(0.2);
        doc.roundedRect(ml, y, usable, cardH, 1.5, 1.5);

        let cyc = y + 4.5;
        // Riga 1: titolo a sx, status/data/PM a dx
        doc.setFontSize(10);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(0, 0, 0);
        const titleLns = doc.splitTextToSize(procTitle, usable - 62);
        for (let ti = 0; ti < titleLns.length; ti++) {
          doc.text(titleLns[ti], ml + 2, cyc + ti * 4);
        }

        let rx = ml + usable - 2;
        rx = drawBadgeRight(statusLbl, rx, cyc, statusBadgeColor(statusKey));
        if (dataIscr) {
          doc.setFontSize(7.5);
          doc.setFont('helvetica', 'normal');
          const dw = doc.getTextWidth(dataIscr);
          doc.setTextColor(80, 80, 80);
          doc.text(dataIscr, rx - dw, cyc);
          doc.setTextColor(0, 0, 0);
          rx -= dw + 1.5;
        }
        if (qual !== 'pm' && pmInfo && pmInfo.name) {
          const pmTxt = 'PM: ' + pmInfo.name;
          doc.setFontSize(7.5);
          const pw2 = doc.getTextWidth(pmTxt) + 3;
          doc.setFillColor(241, 245, 249);
          doc.roundedRect(rx - pw2, cyc - 3.5, pw2, 4.8, 1, 1, 'F');
          doc.setTextColor(50, 50, 50);
          doc.text(pmTxt, rx - pw2 + 1.5, cyc);
          doc.setTextColor(0, 0, 0);
        }

        cyc += titleLns.length * 4 + 2;

        // Riga 2: badge qualifica + chip
        const qualSuffix = link.dataQualifica ? (' · ' + T('dal ', 'since ') + _formatDate(link.dataQualifica)) : '';
        let cx = ml + 2;
        cx = drawBadge(qualLabel + qualSuffix, cx, cyc, qualBadgeColor(qual));
        const rightLimit = ml + usable - 2;
        for (const chip of row2Chips) {
          doc.setFontSize(7.5);
          const need = doc.getTextWidth(chip) + 4;
          if (cx + need > rightLimit) {
            cyc += 5;
            cx = ml + 2;
          }
          cx = drawChip(chip, cx, cyc, rightLimit);
        }

        // Riga PdR per PM
        if (pdrName && qual === 'pm') {
          cyc += 5;
          doc.setFontSize(8);
          doc.setFont('helvetica', 'italic');
          doc.setTextColor(60, 60, 60);
          const pdrLine = T(
            'Procuratore della Repubblica ' + pdrName + ' quale Capo Ufficio del PM ' + fullName,
            'Public Prosecutor ' + pdrName + ' as Head of Office of PM ' + fullName
          );
          const lns = doc.splitTextToSize(pdrLine, usable - 4);
          for (const ln of lns) {
            doc.text(ln, ml + 2, cyc);
            cyc += 4;
          }
          doc.setTextColor(0, 0, 0);
          doc.setFont('helvetica', 'normal');
        }

        y += cardH + 2;
      }
      y += 2;
    }
  }

  // ===== Pagina Fatti soggettivi =====
  doc.addPage();
  drawHeader(T('Fatti Soggettivi', 'Subjective Facts'));
  const factsPage = doc.getNumberOfPages();
  y = 32;
  if (factEntries.length === 0) {
    y = writeWrapped(T('Nessun fatto collegato.', 'No linked facts.'), y, { fontSize: 10, italic: true });
  } else {
    for (const entry of factEntries) {
      const f = entry.fact;
      if (!f) continue;
      const title = f.title || '—';
      const date = fmtDate(f.factDate);
      const dossier = entry.dossierTitle || '';
      const role = entry.roleLabel || '';
      y = ensure(y, 14);
      y = writeWrapped('• ' + title + (date ? ' (' + date + ')' : ''), y, { fontSize: 11, bold: true });
      if (role) y = writeWrapped(T('Ruolo: ', 'Role: ') + role, y, { fontSize: 9 });
      if (dossier) y = writeWrapped(T('Fascicolo: ', 'Dossier: ') + dossier, y, { fontSize: 9 });
      y += 2;
    }
  }

  // ===== Pagina Circostanze soggettive =====
  doc.addPage();
  drawHeader(T('Circostanze Soggettive', 'Subjective Circumstances'));
  const circsPage = doc.getNumberOfPages();
  y = 32;
  if (circEntries.length === 0) {
    y = writeWrapped(T('Nessuna circostanza soggettiva collegata.', 'No linked subjective circumstances.'), y, { fontSize: 10, italic: true });
  } else {
    for (const entry of circEntries) {
      const c = entry.circ;
      if (!c) continue;
      const tipoKey = 'circumstance' + (c.tipo || '').charAt(0).toUpperCase() + (c.tipo || '').slice(1);
      const typeLabel = t(tipoKey) || c.tipo || '';
      const role = entry.roleLabel || '';
      const fatto = entry.factTitle || '';
      y = ensure(y, 14);
      y = writeWrapped('• [' + typeLabel + '] ' + (c.title || '—'), y, { fontSize: 11, bold: true });
      if (fatto) y = writeWrapped(T('Fatto: ', 'Fact: ') + fatto, y, { fontSize: 9 });
      if (role) y = writeWrapped(T('Ruolo: ', 'Role: ') + role, y, { fontSize: 9 });
      y += 2;
    }
  }

  // ===== Indice in pagina 1 (in fondo) =====
  doc.setPage(coverPage);
  let icy = ph - mb - INDEX_RESERVED_H + 6;
  doc.setFontSize(11);
  doc.setFont('helvetica', 'bold');
  doc.setFillColor(241, 245, 249);
  doc.rect(ml, icy - 5, usable, 7, 'F');
  doc.setTextColor(0, 0, 0);
  doc.text(T('INDICE', 'TABLE OF CONTENTS'), ml + 2, icy);
  icy += 9;
  doc.setFontSize(10);
  const idx = [
    [T('Dati Anagrafici', 'Personal Data'), '1'],
    [T('Ruoli Professionali', 'Professional Roles'), String(rolesPage)],
    ...(capoUfficioPage ? [[T('Capo Ufficio', 'Head Office'), String(capoUfficioPage)]] : []),
    ...(casiPage ? [[T('Caso', 'Case'), String(casiPage)]] : []),
    ...(parteOffesaPage ? [[T('Parte Offesa', 'Injured Party'), String(parteOffesaPage)]] : []),
    [T('Note', 'Notes') + ' (' + lang.toUpperCase() + ')', String(notesPage)],
    [T('Ruoli in Procedimenti', 'Roles in Proceedings'), String(proceduralPage)],
    [T('Fatti Soggettivi', 'Subjective Facts'), String(factsPage)],
    [T('Circostanze Soggettive', 'Subjective Circumstances'), String(circsPage)]
  ];
  for (const [name, page] of idx) {
    doc.setFont('helvetica', 'normal');
    doc.text(name, ml, icy);
    const pageStr = String(page);
    const nameW = doc.getTextWidth(name);
    const pageStrW = doc.getTextWidth(pageStr);
    const dotsAvail = usable - nameW - pageStrW - 4;
    let dots = '';
    while (doc.getTextWidth(dots + ' .') < dotsAvail) dots += ' .';
    doc.setTextColor(150, 150, 150);
    doc.text(dots, ml + nameW + 1, icy);
    doc.setTextColor(0, 0, 0);
    doc.text(pageStr, pw - mr, icy, { align: 'right' });
    icy += 7;
  }

  // Numerazione "X di N" su tutte le pagine
  const total = doc.getNumberOfPages();
  for (let i = 1; i <= total; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(100, 116, 139);
    doc.text(`${i} ${T('di', 'of')} ${total}`, pw - mr, ph - 8, { align: 'right' });
    doc.text(fullName, ml, ph - 8);
    doc.setTextColor(0, 0, 0);
  }

  return doc.output('arraybuffer');
}

async function _downloadSubjectSchedaPDF(subjectId) {
  try {
    const buf = await _genSubjectSchedaPDF(subjectId);
    if (!buf) return;
    const s = await DB.getSubject(subjectId);
    const safe = (str) => String(str || '').replace(/[^A-Za-z0-9\-_]+/g, '_').replace(/^_+|_+$/g, '');
    const fname = `Scheda_${safe(s.lastName) || 'Soggetto'}_${safe(s.firstName)}.pdf`.replace(/_+/g, '_');
    const blob = new Blob([buf], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fname;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 5000);
  } catch (e) {
    console.error('subject sheet pdf', e);
    alert((currentLang === 'en' ? 'Error generating PDF: ' : 'Errore generazione PDF: ') + (e && e.message ? e.message : e));
  }
}
window._downloadSubjectSchedaPDF = _downloadSubjectSchedaPDF;

async function _printSubjectSchedaPDF(subjectId) {
  try {
    const buf = await _genSubjectSchedaPDF(subjectId);
    if (!buf) return;
    const blob = new Blob([buf], { type: 'application/pdf' });
    const url = URL.createObjectURL(blob);
    const w = window.open(url, '_blank');
    if (!w) {
      alert(currentLang === 'en' ? 'Pop-up blocked: enable pop-ups to print.' : 'Pop-up bloccato: abilita i pop-up per stampare.');
      setTimeout(() => URL.revokeObjectURL(url), 5000);
      return;
    }
    const tryPrint = () => { try { w.focus(); w.print(); } catch (_) {} };
    w.addEventListener('load', tryPrint);
    setTimeout(tryPrint, 1200);
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  } catch (e) {
    console.error('subject sheet print', e);
    alert((currentLang === 'en' ? 'Error printing PDF: ' : 'Errore stampa PDF: ') + (e && e.message ? e.message : e));
  }
}
window._printSubjectSchedaPDF = _printSubjectSchedaPDF;

function _printProcTreePDF(doc, d, opts, p, indent, printLine, checkPage) {
  const { selActIds, selFactIds, selProcIds } = opts;
  const typeLabel = t(p.type) || p.type || '';
  printLine('[' + typeLabel + '] ' + (p.title || ''), indent, true, 9);

  const dossiers = d.dossiers.filter(ds => ds.proceedingId === p.id);
  for (const ds of dossiers) {
    const _dsFP = new Set((d.factDossierRelations || []).filter(r => r.dossierId === ds.id).map(r => r.factId));
    const _dsAP = new Set((d.factActRelations || []).filter(r => _dsFP.has(r.factId)).map(r => r.actId));
    const dsActs = d.acts.filter(a => _dsAP.has(a.id) && selActIds.has(a.id));
    const dsFacts = d.facts.filter(f => _dsFP.has(f.id) && selFactIds.has(f.id));
    if (dsActs.length === 0 && dsFacts.length === 0) continue;

    printLine(ds.title || t('depositoDossier'), indent + 4, false, 8, [71, 85, 105]);

    if (dsActs.length > 0) {
      printLine(t('depositoActs') + ':', indent + 8, false, 7.5, [100, 116, 139]);
      for (const a of dsActs) {
        const actType = t(a.type) || a.type || '';
        printLine('[' + actType + '] ' + (a.title || ''), indent + 12, false, 8);
      }
    }
    if (dsFacts.length > 0) {
      printLine(t('depositoFacts') + ':', indent + 8, false, 7.5, [100, 116, 139]);
      for (const f of dsFacts) {
        const factRels = d.factActRelations.filter(r => r.factId === f.id);
        const factProofRels3 = (d.factProofRelations || []).filter(r => r.factId === f.id);
        const factProofs = factProofRels3.map(r => { const p = d.proofs.find(pp => pp.id === r.proofId); return p ? { ...p, relationType: r.relationType } : null; }).filter(Boolean);
        const logicState = DB.computeLogicalState(factRels, factProofs);
        const lsLabel = logicState === 'INCOHERENCE' ? t('factIncoherence') : logicState === 'OMISSION' ? t('factOmission') : logicState === 'COHERENT' ? t('factCoherent') : logicState === 'HAS_PROOFS' ? t('factHasProofs') : logicState === 'NO_ACTS' ? t('factNoActs') : t('factNoProofs');
        printLine((f.title || '') + '  [' + lsLabel + ']', indent + 12, false, 8);
      }
    }
  }

  const childProcs = d.proceedings.filter(cp => cp.parentProceedingId === p.id && selProcIds.has(cp.id));
  for (const cp of childProcs) {
    _printProcTreePDF(doc, d, opts, cp, indent + 6, printLine, checkPage);
  }
}

