async function _amfSaveFactForm(editId) {
  const g = id => document.getElementById(id);
  const title = (g('amfFTitle') || {}).value?.trim() || '';
  if (!title) { alert(t('titleRequired') || 'Il titolo è obbligatorio'); return; }
  const data = {
    title,
    titleEN: (g('amfFTitleEN') || {}).value?.trim() || '',
    factDate: (g('amfFDate') || {}).value || null,
    factTime: (g('amfFTime') || {}).value || null,
    factDateEnd: (g('amfFDateEnd') || {}).value || null,
    factTimeEnd: (g('amfFTimeEnd') || {}).value || null,
    chronoType: (g('amfFChronoType') || {}).value || 'istantaneo',
    place: (g('amfFPlace') || {}).value?.trim() || '',
    placeEN: (g('amfFPlaceEN') || {}).value?.trim() || '',
    description: (g('amfFDescr') || {}).value?.trim() || '',
    descriptionEN: (g('amfFDescrEN') || {}).value?.trim() || ''
  };
  if (editId) {
    await DB.updateMemoFatto(editId, data);
  } else {
    const newId = await DB.createMemoFatto(data);
    _archivioMemoSelectedId = newId;
  }
  if (typeof saveDatabaseToFS === 'function') await saveDatabaseToFS();
  document.querySelector('.amf-fact-form-overlay')?.remove();
  await _amfRenderList();
  if (_archivioMemoSelectedId) await _amfShowDetail(_archivioMemoSelectedId);
}

async function _amfDeleteFatto(id) {
  if (!confirm(t('confirmDelete') || 'Eliminare questo fatto e tutti i suoi dati?')) return;
  await DB.deleteMemoFatto(id);
  if (typeof saveDatabaseToFS === 'function') await saveDatabaseToFS();
  if (_archivioMemoSelectedId === id) _archivioMemoSelectedId = null;
  await _amfRenderList();
  const detail = document.getElementById('amfDetail');
  if (detail) detail.innerHTML = `<p class="hint" style="text-align:center;padding:40px 0;color:#9ca3af">${t('selectFact') || 'Seleziona un fatto dalla lista'}</p>`;
}

