function _amfShowProofForm(fattoId, editId) {
  const isEdit = !!editId;
  const overlay = document.createElement('div');
  overlay.className = 'amf-fact-form-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:3200;display:flex;align-items:center;justify-content:center';
  const box = document.createElement('div');
  box.style.cssText = 'background:#fff;border-radius:10px;padding:20px;max-width:540px;width:98%;box-shadow:0 8px 32px rgba(0,0,0,.3)';
  box.innerHTML = `
    <h3 style="margin:0 0 14px;font-size:14px;font-weight:700">${isEdit ? (t('edit') || 'Modifica') : (t('addProof') || 'Aggiungi')} Prova</h3>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
      <div style="grid-column:1/3">
        <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px">TIPO MEDIA</label>
        <div style="display:flex;gap:6px">
          ${['document','image','audio','video'].map(mt =>
            `<label style="display:flex;align-items:center;gap:4px;font-size:12px;cursor:pointer">
              <input type="radio" name="amfPMediaType" value="${mt}" ${mt==='document'?'checked':''} style="cursor:pointer">
              ${{document:'📄',image:'🖼',audio:'🎵',video:'🎬'}[mt]} ${mt}
            </label>`
          ).join('')}
        </div>
      </div>
      <div>
        <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px">TITOLO (IT)</label>
        <input id="amfPTitle" style="width:100%;padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px" placeholder="Titolo prova">
      </div>
      <div>
        <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px">TITLE (EN)</label>
        <input id="amfPTitleEN" style="width:100%;padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px" placeholder="Proof title">
      </div>
      <div style="grid-column:1/3">
        <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px">NOTE (IT)</label>
        <textarea id="amfPNotes" rows="2" style="width:100%;padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:13px;resize:vertical"></textarea>
      </div>
    </div>
    <div style="display:flex;justify-content:flex-end;gap:8px;margin-top:12px">
      <button onclick="this.closest('.amf-fact-form-overlay').remove()" class="btn btn-sm">${t('cancel') || 'Annulla'}</button>
      <button onclick="_amfSaveProof(${fattoId}, ${editId || 'null'})" class="btn btn-sm btn-primary">💾 ${t('save') || 'Salva'}</button>
    </div>
  `;
  overlay.appendChild(box);
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  document.body.appendChild(overlay);
  if (isEdit) {
    DB.getMemoProof(editId).then(p => {
      if (!p) return;
      const g = id => document.getElementById(id);
      if (g('amfPTitle')) g('amfPTitle').value = p.title || '';
      if (g('amfPTitleEN')) g('amfPTitleEN').value = p.titleEN || '';
      if (g('amfPNotes')) g('amfPNotes').value = p.notes || '';
      document.querySelectorAll('input[name="amfPMediaType"]').forEach(r => { r.checked = r.value === (p.mediaType || 'document'); });
    });
  }
}

async function _amfSaveProof(fattoId, editId) {
  const g = id => document.getElementById(id);
  const mt = document.querySelector('input[name="amfPMediaType"]:checked')?.value || 'document';
  const data = {
    archivioFattoId: fattoId,
    mediaType: mt,
    title: (g('amfPTitle') || {}).value?.trim() || '',
    titleEN: (g('amfPTitleEN') || {}).value?.trim() || '',
    notes: (g('amfPNotes') || {}).value?.trim() || ''
  };
  if (editId) {
    await DB.updateMemoProof(editId, data);
  } else {
    await DB.createMemoProof(data);
  }
  if (typeof saveDatabaseToFS === 'function') await saveDatabaseToFS();
  document.querySelector('.amf-fact-form-overlay')?.remove();
  await _amfShowDetail(fattoId);
}

async function _amfDeleteCircostanza(circId, factId) {
  if (!confirm(t('confirmDelete') || 'Eliminare?')) return;
  await DB.deleteMemoCircostanza(circId);
  if (typeof saveDatabaseToFS === 'function') await saveDatabaseToFS();
  if (_factAnalysisSelectedId === factId) await _updateFactAnalysisColumns(factId);
  else await _amfShowDetail(factId);
}

async function _amfDeleteProof(proofId, factId) {
  if (!confirm(t('confirmDelete') || 'Eliminare?')) return;
  await DB.deleteMemoProof(proofId);
  if (typeof saveDatabaseToFS === 'function') await saveDatabaseToFS();
  if (_factAnalysisSelectedId === factId) await _updateFactAnalysisColumns(factId);
  else await _amfShowDetail(factId);
}

async function openSubjectArchiveModal() {
  const existing = document.getElementById('subjectArchiveOverlay');
  if (existing) { existing.remove(); return; }
  await _loadAllLists();
  _subjectArchiveState = { mode: 'export', subjects: [], selected: new Set(), highlightedIdx: -1 };
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.id = 'subjectArchiveOverlay';
  overlay.innerHTML = `
    <div class="modal-content subject-archive-modal" onclick="event.stopPropagation()">
      <div class="modal-header">
        <h3>&#128203; ${t('archivioSoggetti')}</h3>
        <button class="modal-close" onclick="document.getElementById('subjectArchiveOverlay').remove()">&#10005;</button>
      </div>
      <div class="subject-archive-modes">
        <button class="btn btn-sm subject-archive-mode-btn active" id="saModeExport" onclick="_setSubjectArchiveMode('export')">${t('exportSubjects')}</button>
        <button class="btn btn-sm subject-archive-mode-btn" id="saModeImport" onclick="_setSubjectArchiveMode('import')">${t('importSubjects')}</button>
      </div>
      <div id="subjectArchiveBody"></div>
    </div>
  `;
  overlay.addEventListener('click', (e) => { e.stopPropagation(); });
  document.body.appendChild(overlay);
  await _renderSubjectArchiveBody();
}

async function _setSubjectArchiveMode(mode) {
  _subjectArchiveState.mode = mode;
  _subjectArchiveState.subjects = [];
  _subjectArchiveState.selected = new Set();
  _subjectArchiveState.highlightedIdx = -1;
  const btnExport = document.getElementById('saModeExport');
  const btnImport = document.getElementById('saModeImport');
  if (btnExport) btnExport.classList.toggle('active', mode === 'export');
  if (btnImport) btnImport.classList.toggle('active', mode === 'import');
  await _renderSubjectArchiveBody();
}

async function _renderSubjectArchiveBody() {
  const body = document.getElementById('subjectArchiveBody');
  if (!body) return;
  if (_subjectArchiveState.mode === 'export') {
    await _showSubjectExportPanel(body);
  } else {
    _showSubjectImportIntro(body);
  }
}

async function _showSubjectExportPanel(body) {
  const subjects = await DB.getSubjects();
  _subjectArchiveState.subjects = subjects;
  if (subjects.length === 0) {
    body.innerHTML = `<p class="hint" style="padding:16px">${t('noSubjects')}</p>`;
    return;
  }
  _renderSubjectArchiveTwoCol(body, subjects, 'export');
}

function _showSubjectImportIntro(body) {
  body.innerHTML = `
    <div class="subject-archive-import-intro">
      <p class="hint">${t('importSubjectsHint')}</p>
      <label class="btn btn-primary btn-sm" style="cursor:pointer;display:inline-flex;align-items:center;gap:6px">
        &#128194; ${t('selectFileJson')}
        <input type="file" accept=".json" style="display:none" onchange="_onSubjectArchiveFileChosen(this)">
      </label>
    </div>
  `;
}

async function _onSubjectArchiveFileChosen(input) {
  const file = input.files[0];
  if (!file) return;
  try {
    const text = await file.text();
    const data = JSON.parse(text);
    let subjects = Array.isArray(data) ? data : (data.subjects || []);
    if (!Array.isArray(subjects) || subjects.length === 0) {
      alert(t('importFileEmpty'));
      return;
    }
    subjects = subjects.map(function(s) { const c = Object.assign({}, s); delete c.id; return c; });
    _subjectArchiveState.subjects = subjects;
    _subjectArchiveState.selected = new Set();
    _subjectArchiveState.highlightedIdx = -1;
    const body = document.getElementById('subjectArchiveBody');
    if (body) _renderSubjectArchiveTwoCol(body, subjects, 'import');
  } catch (e) {
    alert(t('importJsonInvalid'));
  }
}

function _renderSubjectArchiveTwoCol(body, subjects, mode) {
  const st = _subjectArchiveState;
  const allSelected = subjects.length > 0 && st.selected.size === subjects.length;
  const listItems = subjects.map(function(s, idx) {
    const name = (s.salutation ? esc(s.salutation) + ' ' : '') + esc(s.firstName || '') + ' ' + esc(s.lastName || '');
    const sType = s.subjectType || _computeSubjectType(s.roles || []);
    const badgeHtml = _renderSubjectTypeBadge(sType);
    const isSelected = st.selected.has(idx);
    const isHighlighted = st.highlightedIdx === idx;
    return `<div class="subject-archive-item${isSelected ? ' selected' : ''}${isHighlighted ? ' active' : ''}" onclick="_subjectArchiveHighlight(${idx})">
      <input type="checkbox" class="subject-archive-chk" ${isSelected ? 'checked' : ''} onchange="_subjectArchiveToggle(${idx}, event)" onclick="event.stopPropagation()">
      <span class="subject-archive-name">${name} ${badgeHtml}</span>
    </div>`;
  }).join('');

  const rightHintKey = mode === 'import' ? 'importSubjectsSelectHint' : 'exportSubjectsHint';
  const rightHtml = st.highlightedIdx >= 0
    ? _buildSubjectArchiveDetail(subjects[st.highlightedIdx])
    : `<p class="hint" style="padding:16px">${t(rightHintKey)}</p>`;

  const actionLabel = mode === 'export' ? t('exportSelected') : t('importSelected');
  const actionIcon = mode === 'export' ? '&#11015;' : '&#11014;';
  const actionFn = mode === 'export' ? '_doSubjectExport()' : '_doSubjectImport()';

  const changeFileBtn = mode === 'import'
    ? `<label class="btn btn-xs" style="cursor:pointer;display:inline-flex;align-items:center;gap:4px">&#128194; ${t('selectFileJson')}<input type="file" accept=".json" style="display:none" onchange="_onSubjectArchiveFileChosen(this)"></label>`
    : '';

  body.innerHTML = `
    <div class="subject-archive-two-col">
      <div class="subject-archive-col-left">
        <div class="subject-archive-toolbar">
          <label style="cursor:pointer;display:flex;align-items:center;gap:6px">
            <input type="checkbox" id="saSelectAll" ${allSelected ? 'checked' : ''} onchange="_subjectArchiveToggleAll(this.checked)">
            ${t('allSubjectsTab')}
          </label>
          <span style="display:flex;align-items:center;gap:6px"><span id="saCount">${st.selected.size}/${subjects.length}</span>${changeFileBtn}</span>
        </div>
        <div class="subject-archive-list">${listItems}</div>
      </div>
      <div class="subject-archive-col-right" id="saRightCol">${rightHtml}</div>
    </div>
    <div class="subject-archive-footer">
      <button class="btn btn-primary btn-sm" id="saActionBtn" onclick="${actionFn}">${actionIcon} ${actionLabel} (${st.selected.size})</button>
    </div>
  `;
}

function _buildSubjectArchiveDetail(s) {
  if (!s) return '';
  const name = (s.salutation ? esc(s.salutation) + ' ' : '') + esc(s.firstName || '') + ' ' + esc(s.lastName || '');
  const sType = s.subjectType || _computeSubjectType(s.roles || []);
  const badgeHtml = _renderSubjectTypeBadge(sType);
  const rolesTable = _buildRolesTable(s.roles || []);
  const rolesHtml = rolesTable || `<p class="hint">${t('noRolesAssigned')}</p>`;
  return `<div style="padding:14px">
    <div style="font-weight:600;font-size:14px;margin-bottom:8px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">${name} ${badgeHtml}</div>
    ${s.origin ? `<div style="font-size:12px;color:var(--text-secondary);margin-bottom:10px">${esc(s.origin)}</div>` : ''}
    ${rolesHtml}
  </div>`;
}

function _subjectArchiveHighlight(idx) {
  const st = _subjectArchiveState;
  st.highlightedIdx = idx;
  document.querySelectorAll('.subject-archive-item').forEach(function(el, i) {
    el.classList.toggle('active', i === idx);
  });
  const rightCol = document.getElementById('saRightCol');
  if (rightCol) rightCol.innerHTML = _buildSubjectArchiveDetail(st.subjects[idx]);
}

function _subjectArchiveToggle(idx, event) {
  const st = _subjectArchiveState;
  if (st.selected.has(idx)) { st.selected.delete(idx); } else { st.selected.add(idx); }
  const items = document.querySelectorAll('.subject-archive-item');
  if (items[idx]) items[idx].classList.toggle('selected', st.selected.has(idx));
  _updateSubjectArchiveCount();
}

function _subjectArchiveToggleAll(checked) {
  const st = _subjectArchiveState;
  if (checked) { st.subjects.forEach(function(_, i) { st.selected.add(i); }); }
  else { st.selected.clear(); }
  document.querySelectorAll('.subject-archive-item').forEach(function(el, i) {
    el.classList.toggle('selected', st.selected.has(i));
    const chk = el.querySelector('.subject-archive-chk');
    if (chk) chk.checked = st.selected.has(i);
  });
  _updateSubjectArchiveCount();
}

function _updateSubjectArchiveCount() {
  const st = _subjectArchiveState;
  const counterEl = document.getElementById('saCount');
  if (counterEl) counterEl.textContent = `${st.selected.size}/${st.subjects.length}`;
  const btn = document.getElementById('saActionBtn');
  if (btn) {
    const label = st.mode === 'export' ? t('exportSelected') : t('importSelected');
    const icon = st.mode === 'export' ? '&#11015;' : '&#11014;';
    btn.innerHTML = `${icon} ${label} (${st.selected.size})`;
  }
  const selectAllChk = document.getElementById('saSelectAll');
  if (selectAllChk) selectAllChk.checked = st.subjects.length > 0 && st.selected.size === st.subjects.length;
}

async function _doSubjectExport() {
  const st = _subjectArchiveState;
  if (st.selected.size === 0) { alert(t('noSubjectsSelected')); return; }
  const toExport = Array.from(st.selected).map(function(i) {
    const s = st.subjects[i];
    return {
      salutation: s.salutation || '',
      firstName: s.firstName || '',
      lastName: s.lastName || '',
      origin: s.origin || '',
      descriptionIt: s.descriptionIt || '',
      descriptionEn: s.descriptionEn || '',
      roles: Array.isArray(s.roles) ? s.roles : [],
      subjectType: s.subjectType || _computeSubjectType(s.roles || [])
    };
  });
  const json = JSON.stringify(toExport, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'soggetti_export.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

async function _doSubjectImport() {
  const st = _subjectArchiveState;
  if (st.selected.size === 0) { alert(t('noSubjectsSelected')); return; }
  let count = 0;
  let errors = 0;
  for (const idx of Array.from(st.selected)) {
    const s = st.subjects[idx];
    const data = {
      salutation: s.salutation || '',
      firstName: s.firstName || '',
      lastName: s.lastName || '',
      origin: s.origin || '',
      descriptionIt: s.descriptionIt || '',
      descriptionEn: s.descriptionEn || '',
      roles: Array.isArray(s.roles) ? s.roles : [],
      subjectType: s.subjectType || _computeSubjectType(s.roles || [])
    };
    try { await DB.createSubject(data); count++; }
    catch (e) { console.error('Import subject error:', e); errors++; }
  }
  _cachedSubjects = null;
  await renderSubjects();
  const baseMsg = t('importSuccess').replace('{n}', count);
  const errSuffix = errors > 0 ? ` (${t('importErrors').replace('{n}', errors)})` : '';
  alert(baseMsg + errSuffix);
  const overlay = document.getElementById('subjectArchiveOverlay');
  if (overlay) overlay.remove();
}
