// MODULO ARCHIVIO PEC (Task #167) - rev2
// File-roles: pec_msg (corpo), pec_acc (ricevuta accettazione),
//             pec_del (ricevuta consegna), pec_attach (allegato)
// ============================================================
let _pecSearchTerm = '';
let _pecYearFilter = '';
let _pecSubjectFilter = '';
let _pecSelectedId = null;
let _pecDetailView = 'message'; // 'message' | 'acc' | 'del' | 'technical' — Task #196 estende #194
let _pecDetailDelFileId = null; // id del pec_del correntemente selezionato (per consegne multiple) — Task #196
async function _pecAllSubjects() { try { return await DB.getSubjects(); } catch (_) { return []; } }
function _pecSubjectLabel(s) {
  if (!s) return '?';
  const fn = (s.firstName || '').trim();
  const ln = (s.lastName || '').trim();
  const name = (fn + ' ' + ln).trim();
  return name || s.denominazione || s.email || s.codiceFiscale || `#${s.id}`;
}

function _pecYearFromDate(iso) {
  if (!iso) return new Date().getFullYear();
  const m = String(iso).match(/^(\d{4})/);
  return m ? parseInt(m[1], 10) : new Date().getFullYear();
}

async function openArchivioPecModal() {
  document.querySelectorAll('.fact-analysis-overlay').forEach(o => o.remove());
  _pecSearchTerm = '';
  _pecYearFilter = '';
  _pecSubjectFilter = '';
  const ov = document.createElement('div');
  ov.className = 'fact-analysis-overlay';
  ov.id = 'archivioPecOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:center;justify-content:center;';
  const all = await DB.getPecMessages();
  const years = [...new Set(all.map(p => p.year).filter(Boolean))].sort((a, b) => b - a);
  const subjects = await _pecAllSubjects();
  ov.innerHTML = `
    <div style="background:#fff;width:min(1280px,96vw);height:min(860px,94vh);border-radius:10px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.4)">
      <div style="display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid #e5e7eb;background:#2563eb;color:#fff">
        <span style="font-size:22px">📧</span>
        <h2 style="margin:0;font-size:18px;flex:1">${t('archivioPecTitle') || "Archivio PEC dell'esponente"}</h2>
        <button class="btn btn-xs" style="background:#fff;color:#2563eb;border:none;font-weight:600" onclick="_pecShowForm(null)" data-testid="button-pec-new">+ ${t('newPec') || 'Nuova PEC'}</button>
        <button class="btn btn-xs" style="background:#fff;color:#2563eb;border:none;font-weight:600" onclick="_pecMboxImportFlow()" data-testid="button-pec-mbox-import" title="${t('pecImportMboxTitle') || 'Import bulk PEC da file .mbox'}">📥 ${t('pecImportMboxBtn') || 'Importa .mbox'}</button>
        <button class="btn btn-xs" style="background:#fff;color:#2563eb;border:none;font-weight:600" onclick="_pecEmlFolderImportFlow()" data-testid="button-pec-eml-folder-import" title="${t('pecImportEmlTitle') || 'Import bulk PEC da cartella .eml'}">📁 ${t('pecImportEmlBtn') || 'Importa cartella .eml'}</button>
        <button class="btn btn-xs" style="background:#fff;color:#2563eb;border:none;font-weight:600" onclick="_pecZipImportFlow()" data-testid="button-pec-zip-import" title="${t('pecImportZipTitle') || 'Import bulk PEC da archivio .zip dei gestori (Aruba/Postacert/Legalmail)'}">🗜️ ${t('pecImportZipBtn') || 'Importa .zip'}</button>
        <button class="btn btn-xs" style="background:#0d9488;color:#fff;border:none;font-weight:600" onclick="_pecBatchRecomputeMetadata()" data-testid="button-pec-recompute-batch" title="${t('pecRecomputeBatchTitleAttr') || 'Rilegge daticert.xml dalle ricevute archiviate e aggiorna mittente/oggetto/data REALI per le PEC importate prima del fix (es. quando il mittente mostrato è posta-certificata@gestore invece del mittente vero).'}">🔄 ${t('pecRecomputeBatchBtn') || 'Aggiorna mittenti reali'}</button>
        <button class="btn btn-xs" style="background:#1e3a8a;color:#fff;border:none;font-weight:600" onclick="_pecBatchRecheckSmime()" data-testid="button-pec-recheck-smime-all" title="Riverifica la firma S/MIME di TUTTE le PEC archiviate (utile dopo aggiornamenti del verificatore: per esempio il fallback CRLF/LF recupera ricevute autentiche marcate come non valide perché il file .eml aveva subito una conversione di terminatori di riga).">🔍 Riverifica firme tutte</button>
        <button class="btn btn-xs" style="background:#7f1d1d;color:#fff;border:1px solid #fecaca;font-weight:600" onclick="_pecWipeShowConfirm()" data-testid="button-pec-wipe-all" title="${t('pecWipeBtnTitle') || 'Cancella TUTTI i messaggi PEC e i file fisici (irreversibile)'}">🗑️ ${t('pecWipeBtn') || 'Svuota archivio PEC'}</button>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('archivioPecOverlay').remove()" data-testid="button-pec-close">✕</button>
      </div>
      <div style="display:grid;grid-template-columns:380px 1fr;flex:1;overflow:hidden">
        <div style="border-right:1px solid #e5e7eb;display:flex;flex-direction:column;overflow:hidden">
          <div style="padding:10px;border-bottom:1px solid #e5e7eb;display:flex;flex-direction:column;gap:6px">
            <input type="text" id="pecSearchInput" placeholder="${t('searchPec') || 'Cerca per oggetto, mittente, destinatario...'}" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px" data-testid="input-pec-search" oninput="_pecSearchTerm=this.value;_pecRenderList()">
            <select id="pecYearFilter" style="width:100%;padding:6px;border:1px solid #d1d5db;border-radius:6px" data-testid="select-pec-year" onchange="_pecYearFilter=this.value;_pecRenderList()">
              <option value="">${t('allYears') || 'Tutti gli anni'}</option>
              ${years.map(y => `<option value="${y}">${y}</option>`).join('')}
            </select>
            <select id="pecSubjectFilter" style="width:100%;padding:6px;border:1px solid #d1d5db;border-radius:6px" data-testid="select-pec-subject-filter" onchange="_pecSubjectFilter=this.value;_pecRenderList()">
              <option value="">${t('allSubjectsFilter') || 'Tutti i soggetti'}</option>
              ${subjects.map(s => `<option value="${s.id}">${esc(_pecSubjectLabel(s))}</option>`).join('')}
            </select>
            <div title="${esc(t('pecDirFilterTitle') || 'Filtra per direzione')}" style="display:flex;gap:4px" data-testid="group-pec-direction-filter">
              ${(() => {
                const opts = [
                  { v: '',         lbl: t('pecDirFilterAll') || 'Tutte' },
                  { v: 'sent',     lbl: t('pecDirFilterSent') || '📤 Inviate' },
                  { v: 'received', lbl: t('pecDirFilterReceived') || '📥 Ricevute' },
                ];
                return opts.map(o => {
                  const active = (_pecDirectionFilter || '') === o.v;
                  const bg = active ? '#2563eb' : '#fff';
                  const fg = active ? '#fff' : '#374151';
                  const bd = active ? '#1e3a8a' : '#d1d5db';
                  const tid = 'button-pec-dir-filter-' + (o.v || 'all');
                  return `<button type="button" onclick="_pecSetDirectionFilter('${o.v}')" data-testid="${tid}" style="flex:1;padding:5px 6px;border:1px solid ${bd};background:${bg};color:${fg};border-radius:6px;font-size:11px;font-weight:600;cursor:pointer">${esc(o.lbl)}</button>`;
                }).join('');
              })()}
            </div>
          </div>
          <div id="pecListContainer" style="flex:1;overflow-y:auto;padding:6px"></div>
        </div>
        <div id="pecDetailPane" style="overflow-y:auto;padding:18px;background:#f9fafb">
          <div style="color:#6b7280;text-align:center;margin-top:80px;font-size:14px">${t('pecSelectHint') || 'Seleziona una PEC dalla lista o creane una nuova'}</div>
        </div>
      </div>
    </div>`;
  document.body.appendChild(ov);
  if (typeof _pecArchiveAttachDnD === 'function') _pecArchiveAttachDnD();
  await _pecRenderList();
}

// Navigazione da tastiera nella lista PEC: frecce ↑/↓ scorrono le card,
// Home/End saltano alla prima/ultima. Listener registrato una sola volta a
// livello document; inattivo se l'archivio PEC non è aperto o se il focus è
// in un input / textarea / select / elemento editabile (così non interferisce
// con ricerca, filtri, ecc.).
function _pecAttachKeyboardNavOnce() {
  if (window._pecKbdNavAttached) return;
  window._pecKbdNavAttached = true;
  document.addEventListener('keydown', (ev) => {
    if (ev.key !== 'ArrowUp' && ev.key !== 'ArrowDown' && ev.key !== 'Home' && ev.key !== 'End') return;
    const cnt = document.getElementById('pecListContainer');
    if (!cnt) return;
    const tgt = ev.target;
    const tag = (tgt && tgt.tagName) ? tgt.tagName.toLowerCase() : '';
    if (tag === 'input' || tag === 'textarea' || tag === 'select') return;
    if (tgt && tgt.isContentEditable) return;
    // Non interferire se è aperto un modale/overlay sopra l'archivio (form PEC, ecc.).
    const topOverlay = document.querySelector('#pecFormOverlay, #pecMboxOverlay, #pecRecomputeOverlay');
    if (topOverlay) return;
    const cards = cnt.querySelectorAll('[data-testid^="card-pec-"]');
    if (!cards.length) return;
    const ids = Array.from(cards).map(el => {
      const m = (el.getAttribute('data-testid') || '').match(/^card-pec-(\d+)$/);
      return m ? parseInt(m[1], 10) : null;
    }).filter(x => x != null);
    if (!ids.length) return;
    let idx = ids.indexOf(_pecSelectedId || -1);
    if (ev.key === 'ArrowDown') idx = idx < 0 ? 0 : Math.min(ids.length - 1, idx + 1);
    else if (ev.key === 'ArrowUp') idx = idx < 0 ? 0 : Math.max(0, idx - 1);
    else if (ev.key === 'Home') idx = 0;
    else if (ev.key === 'End') idx = ids.length - 1;
    const nextId = ids[idx];
    if (nextId == null || nextId === _pecSelectedId) { ev.preventDefault(); return; }
    ev.preventDefault();
    if (typeof _pecShowDetail === 'function') {
      Promise.resolve(_pecShowDetail(nextId)).then(() => {
        const el = cnt.querySelector(`[data-testid="card-pec-${nextId}"]`);
        if (el && typeof el.scrollIntoView === 'function') el.scrollIntoView({ block: 'nearest' });
      });
    }
  });
}

async function _pecRenderList() {
  const cnt = document.getElementById('pecListContainer');
  if (!cnt) return;
  _pecAttachKeyboardNavOnce();
  let all = await DB.getPecMessages();
  const yearSel = document.getElementById('pecYearFilter');
  if (yearSel) {
    const years = [...new Set(all.map(p => p.year).filter(Boolean))].sort((a, b) => b - a);
    const current = _pecYearFilter || '';
    yearSel.innerHTML = `<option value="">${t('allYears') || 'Tutti gli anni'}</option>` + years.map(y => `<option value="${y}"${String(y) === String(current) ? ' selected' : ''}>${y}</option>`).join('');
  }
  const q = _pecSearchTerm.trim().toLowerCase();
  if (q) {
    all = all.filter(p =>
      (p.oggetto || '').toLowerCase().includes(q) ||
      (p.mittente || '').toLowerCase().includes(q) ||
      (p.destinatario || '').toLowerCase().includes(q) ||
      (p.dataInvio || '').toLowerCase().includes(q) ||
      (p.dataAccettazione || '').toLowerCase().includes(q) ||
      (p.dataConsegna || '').toLowerCase().includes(q) ||
      (Array.isArray(p.destinatari) && p.destinatari.some(d => (d || '').toLowerCase().includes(q))));
  }
  if (_pecYearFilter) all = all.filter(p => String(p.year) === String(_pecYearFilter));
  if (_pecSubjectFilter) {
    const sid = parseInt(_pecSubjectFilter, 10);
    all = all.filter(p => Array.isArray(p.soggettiCollegati) && p.soggettiCollegati.includes(sid));
  }
  // Task #195: filtro direzione (sent/received) — calcola al volo per i record
  // legacy che non hanno data.direction.
  const profilePecForFilter = await _pecGetProfilePec();
  const dirCache = new Map();
  const dirOf = (p) => {
    if (dirCache.has(p.id)) return dirCache.get(p.id);
    const d = _pecComputeDirectionFromRecord(p, profilePecForFilter);
    dirCache.set(p.id, d);
    return d;
  };
  if (_pecDirectionFilter === 'sent' || _pecDirectionFilter === 'received') {
    all = all.filter(p => dirOf(p).direction === _pecDirectionFilter);
  }
  all.sort((a, b) => (b.dataInvio || '').localeCompare(a.dataInvio || ''));
  if (all.length === 0) {
    cnt.innerHTML = `<div style="color:#9ca3af;text-align:center;padding:30px;font-size:13px">${t('noPec') || 'Nessuna PEC in archivio'}</div>`;
    return;
  }
  cnt.innerHTML = all.map(p => {
    const sel = p.id === _pecSelectedId ? 'background:#dbeafe;border-color:#2563eb' : 'background:#fff';
    const d = dirOf(p);
    const dirBadge = _pecDirectionBadge(d.direction, d.reason, { small: true, recordId: p.id });
    return `<div onclick="_pecShowDetail(${p.id})" style="${sel};border:1px solid #e5e7eb;border-radius:6px;padding:10px;margin-bottom:6px;cursor:pointer" data-testid="card-pec-${p.id}">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:6px">
        <div style="font-size:11px;color:#2563eb;font-weight:600">📧 ${esc(p.dataInvio || '')} · ${p.year || ''}</div>
        ${dirBadge}
      </div>
      <div style="font-weight:600;font-size:13px;margin-top:3px">${esc(p.oggetto || '(senza oggetto)')}</div>
      ${(() => {
        // Per le inviate mostriamo SOLO i destinatari (tutti — li conosciamo
        // dal daticert dell'accettazione); per le ricevute mostriamo solo il
        // mittente reale. Questo evita la ridondanza con il tuo profilo PEC
        // sempre presente come mittente delle inviate.
        if (d.direction === 'sent') {
          const destsArr = Array.isArray(p.destinatari) && p.destinatari.length
            ? p.destinatari
            : (p.destinatario ? [p.destinatario] : []);
          if (!destsArr.length) {
            return `<div style="font-size:11px;color:#6b7280;margin-top:3px">→ —</div>`;
          }
          const items = destsArr.map(d => `<li style="margin:0;padding:0">${esc(d)}</li>`).join('');
          return `<ul style="font-size:11px;color:#6b7280;margin:3px 0 0 0;padding-left:16px;list-style:'→ '">${items}</ul>`;
        }
        if (d.direction === 'received') {
          return `<div style="font-size:11px;color:#6b7280;margin-top:3px">← ${esc(p.mittente || '—')}</div>`;
        }
        // direzione sconosciuta: comportamento legacy
        return `<div style="font-size:11px;color:#6b7280;margin-top:3px">${esc(p.mittente || '')} → ${esc(p.destinatario || '')}</div>`;
      })()}
    </div>`;
  }).join('');
}

async function _pecListUsage(pecId) {
  const ownFiles = await DB.getEntityFiles('pec', pecId);
  const entitiesMap = new Map(); // key: entityType|entityId
  for (const f of ownFiles) {
    const refs = await DB.getFilesBySourceId(f.id);
    for (const r of refs) {
      const k = r.entityType + '|' + r.entityId;
      if (!entitiesMap.has(k)) entitiesMap.set(k, { entityType: r.entityType, entityId: r.entityId });
    }
  }
  const dossierCache = new Map();
  const factCache = new Map();
  const getDossierLabel = async (did) => {
    if (did == null) return '';
    if (dossierCache.has(did)) return dossierCache.get(did);
    let lab = '';
    try {
      const d = await DB.getDossier(did);
      if (d) lab = d.titleIt || d.titleEn || d.numero || `Fascicolo #${did}`;
    } catch (_) {}
    dossierCache.set(did, lab);
    return lab;
  };
  const getFact = async (fid) => {
    if (factCache.has(fid)) return factCache.get(fid);
    let f = null;
    try { f = await DB.getFact(fid); } catch (_) {}
    factCache.set(fid, f);
    return f;
  };
  const out = [];
  for (const v of entitiesMap.values()) {
    let entityLabel = '';
    let factRels = [];
    if (v.entityType === 'act') {
      const a = await DB.getAct(v.entityId);
      entityLabel = a ? (a.titleIt || a.titleEn || `Atto #${v.entityId}`) : `Atto #${v.entityId}`;
      try { factRels = await DB.getActFactRelations(v.entityId); } catch (_) {}
    } else if (v.entityType === 'proof') {
      const p = await DB.getProof(v.entityId);
      entityLabel = p ? (p.titleIt || p.titleEn || `Prova #${v.entityId}`) : `Prova #${v.entityId}`;
      try { factRels = await DB.getProofFactRelations(v.entityId); } catch (_) {}
    } else {
      out.push({ entityType: v.entityType, entityId: v.entityId, label: `${v.entityType} #${v.entityId}`, factId: null, factLabel: '', dossierId: null, dossierLabel: '' });
      continue;
    }
    if (!factRels.length) {
      out.push({ entityType: v.entityType, entityId: v.entityId, label: entityLabel, factId: null, factLabel: '', dossierId: null, dossierLabel: '' });
      continue;
    }
    for (const rel of factRels) {
      const f = await getFact(rel.factId);
      const factLabel = f ? (f.titleIt || f.titleEn || `Fatto #${rel.factId}`) : `Fatto #${rel.factId}`;
      const dossierId = f && f.dossierId != null ? f.dossierId : null;
      const dossierLabel = dossierId != null ? await getDossierLabel(dossierId) : '';
      out.push({
        entityType: v.entityType,
        entityId: v.entityId,
        label: entityLabel,
        factId: rel.factId,
        factLabel,
        dossierId,
        dossierLabel,
        position: rel.posizioneAtto || rel.relationType || '',
      });
    }
  }
  out.sort((a, b) => {
    const fa = a.factId == null ? Infinity : a.factId;
    const fb = b.factId == null ? Infinity : b.factId;
    if (fa !== fb) return fa - fb;
    if (a.entityType !== b.entityType) return a.entityType.localeCompare(b.entityType);
    return (a.entityId || 0) - (b.entityId || 0);
  });
  out.forEach(o => { if (!('position' in o)) o.position = ''; });
  return out;
}

async function _pecShowDetail(id) {
  try {
    return await _pecShowDetailInner(id);
  } catch (e) {
    console.error('_pecShowDetail error', e);
    const pane = document.getElementById('pecDetailPane');
    if (pane) {
      pane.innerHTML = `<div style="color:#dc2626;background:#fee2e2;border:1px solid #fecaca;border-radius:8px;padding:14px;margin:20px;font-size:13px">
        <b>⚠️ Errore caricamento PEC #${id}</b><br><br>
        <code style="font-size:11px;white-space:pre-wrap;word-break:break-word">${esc((e && (e.stack || e.message)) || String(e))}</code>
      </div>`;
    }
  }
}

async function _pecShowDetailInner(id) {
  if (_pecSelectedId !== id) {
    _pecDetailView = 'message';
    _pecDetailDelFileId = null;
    if (window._pecMsgAttCache) {
      Object.keys(window._pecMsgAttCache).forEach(k => {
        if (String(k) !== String(id)) delete window._pecMsgAttCache[k];
      });
    }
  }
  _pecSelectedId = id;
  await _pecGetProfilePec(); // popola la cache per il calcolo direzione nella vista
  await _pecRenderList();
  const pec = await DB.getPecMessage(id);
  const pane = document.getElementById('pecDetailPane');
  if (!pane) return;
  if (!pec) {
    pane.innerHTML = `<div style="color:#dc2626;padding:20px;text-align:center">PEC #${id} non trovata nel database (potrebbe essere stata eliminata).</div>`;
    return;
  }
  const files = await DB.getEntityFiles('pec', id);
  const usage = await _pecListUsage(id);
  const fileRow = (f) => {
    const roleLabel = { pec_msg: '✉️ Messaggio', pec_acc: '📥 Accettazione', pec_del: '✅ Consegna', pec_attach: '📎 Allegato' }[f.fileRole] || '📎 ' + (f.fileRole || 'File');
    const hashShort = f.hash ? f.hash.slice(0, 8) : '—';
    const disk = f.diskFileName ? ` · disco:${esc(f.diskFileName)}` : (f.storagePath ? ` · ${esc(f.storagePath)}` : ' · in-DB');
    return `<div style="display:flex;align-items:center;gap:10px;padding:8px;border:1px solid #e5e7eb;border-radius:6px;margin-bottom:6px;background:#fff">
      <span style="font-size:11px;background:#2563eb;color:#fff;padding:2px 6px;border-radius:4px">${roleLabel}</span>
      <span style="flex:1;font-size:13px">${esc(f.fileName)} <span style="color:#9ca3af;font-size:11px">#${f.id} · ${(f.fileSize/1024).toFixed(1)} KB · hash:${hashShort}${disk}</span></span>
      <button class="btn btn-xs" onclick="openFilePreviewModal(${f.id})" data-testid="button-pec-preview-${f.id}">👁️</button>
    </div>`;
  };
  const destinatari = Array.isArray(pec.destinatari) && pec.destinatari.length > 0 ? pec.destinatari.join(', ') : (pec.destinatario || '');
  let subjLabels = '';
  if (Array.isArray(pec.soggettiCollegati) && pec.soggettiCollegati.length > 0) {
    const allSubj = await _pecAllSubjects();
    const map = new Map(allSubj.map(s => [s.id, s]));
    subjLabels = pec.soggettiCollegati.map(sid => esc(_pecSubjectLabel(map.get(sid)))).join(', ');
  }
  // Task #196: file ricevute disponibili per il segmented control
  const accFile = files.find(f => f.fileRole === 'pec_acc') || null;
  const delFiles = files.filter(f => f.fileRole === 'pec_del');
  // Etichette dropdown consegne: parsiamo daticert.xml di ogni pec_del per
  // estrarre destinatario reale + data; ordinamento cronologico.
  let delOptions = [];
  if (delFiles.length) {
    delOptions = await Promise.all(delFiles.map(async f => {
      let dest = '', dateIso = '';
      try {
        const bytes = await _pecLoadFileBytes(f);
        if (bytes && bytes.length) {
          const root = _emlParsePart(new TextDecoder('latin1').decode(bytes));
          const dcXml = _pecExtractDaticertXml(root);
          if (dcXml) {
            const dc = _pecParseDaticert(dcXml);
            if (dc) {
              // Preferenza: <consegna> (destinatario specifico di QUESTA ricevuta,
              // quando il gestore rispetta strettamente lo schema AgID).
              dest = dc.consegnaDest || '';
              dateIso = dc.dateIso || '';
            }
          }
          // Fallback affidabile: parse del body della ricevuta. Il testo standard
          // AgID contiene 'ed indirizzato a "<email>"' — unico modo per
          // distinguere il destinatario specifico quando il daticert di un gestore
          // (es. InfoCert) elenca TUTTI i destinatari originali senza isolare
          // quello di questa singola ricevuta.
          // Cerchiamo direttamente nel raw decoded dell'eml: funziona anche con
          // S/MIME-signed dove _emlExtract può non restituire textPlain del body.
          if (!dest) {
            const tryMatch = (s) => {
              if (!s) return '';
              // Pattern AgID stretto: l'unica frase presente SOLO nel body
              // della ricevuta di consegna (non nel postacert embedded) è
              // 'indirizzato a "X" è stato consegnato'. Richiedere entrambe
              // le parti evita falsi match dentro il messaggio originale.
              let m = s.match(/indirizzato a\s+["']?([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})["']?[\s\S]{0,80}?è stato consegnato/i);
              if (m) return m[1].toLowerCase();
              // Pattern AgID stretto variante EN (alcuni gestori):
              // 'addressed to "X" has been delivered'
              m = s.match(/addressed to\s+["']?([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})["']?[\s\S]{0,80}?has been delivered/i);
              if (m) return m[1].toLowerCase();
              return '';
            };
            try {
              const ext = _emlExtract(root);
              dest = tryMatch((ext && ext.textPlain) || '');
            } catch (_) {}
            if (!dest) {
              // Fallback 2: cerca nel raw decoded dell'eml (contiene il body
              // plain della ricevuta anche quando S/MIME-signed).
              const raw = new TextDecoder('latin1').decode(bytes);
              dest = tryMatch(raw);
              if (!dest) {
                // Fallback 3: decodifica QP del raw per gestire body encoded.
                try {
                  const qp = raw
                    .replace(/=\r?\n/g, '')
                    .replace(/=([0-9A-Fa-f]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
                  dest = tryMatch(qp);
                } catch (_) {}
              }
            }
          }
          // Ulteriore fallback: primo destinatario certificato dal daticert
          // (mai esterni: sono mail ordinarie, non ricevono ricevute PEC).
          if (!dest && dcXml) {
            try {
              const dc2 = _pecParseDaticert(dcXml);
              if (dc2 && dc2.destinatariCertificati && dc2.destinatariCertificati[0]) {
                dest = dc2.destinatariCertificati[0];
              }
            } catch (_) {}
          }
          // Ultimo fallback: header To: del file .eml.
          if (!dest) {
            const toHdr = _emlDecodeMimeWord(_emlGetHeader(root.headers, 'to') || '');
            const addrs = _emlExtractAddresses(toHdr);
            dest = addrs[0] || toHdr || '';
          }
          if (!dateIso) {
            const dateHdr = _emlGetHeader(root.headers, 'date');
            const dt = _emlParseDate(dateHdr);
            if (dt) dateIso = dt;
          }
        }
      } catch (_) {}
      return { fileId: f.id, fileName: f.fileName, fileSize: f.fileSize || 0, dest, dateIso };
    }));
    delOptions.sort((a, b) => (a.dateIso || '').localeCompare(b.dateIso || ''));
  }
  // Validazione stato corrente: se la vista attiva non è disponibile, fallback
  if (_pecDetailView === 'acc' && !accFile) _pecDetailView = 'message';
  if (_pecDetailView === 'del' && !delOptions.length) _pecDetailView = 'message';
  if (_pecDetailView === 'del') {
    if (!_pecDetailDelFileId || !delOptions.some(o => o.fileId === _pecDetailDelFileId)) {
      _pecDetailDelFileId = delOptions[0].fileId;
    }
  } else {
    _pecDetailDelFileId = null;
  }

  const segBtn = (key, icon, lbl, ttl, disabled, extraOnclick) => {
    const active = _pecDetailView === key;
    const bg = active ? '#7c3aed' : '#fff';
    const color = active ? '#fff' : (disabled ? '#9ca3af' : '#7c3aed');
    const border = disabled ? '1px solid #e5e7eb' : '1px solid #7c3aed';
    const cursor = disabled ? 'not-allowed' : 'pointer';
    const onclick = disabled ? '' : (extraOnclick || `_pecSetDetailView(${id},'${key}')`);
    return `<button class="btn btn-xs" ${disabled ? 'disabled' : ''} style="flex:0 0 auto;white-space:nowrap;background:${bg};color:${color};border:${border};cursor:${cursor};font-weight:${active ? '700' : '500'}" ${onclick ? `onclick="${onclick}"` : ''} data-testid="button-pec-view-${key}-${id}" title="${esc(ttl)}">${icon} ${esc(lbl)}</button>`;
  };
  const accDisabled = !accFile;
  const delDisabled = !delOptions.length;
  const accTitle = accDisabled ? (t('pecViewAccUnavail') || 'Ricevuta di accettazione non presente nell\'archivio.') : (t('pecViewAccTitle') || 'Mostra la ricevuta di accettazione (pec_acc) con header dal daticert.xml, badge S/MIME e corpo leggibile.');
  const delTitle = delDisabled ? (t('pecViewDelUnavail') || 'Nessuna ricevuta di consegna presente nell\'archivio.') : (t('pecViewDelTitle') || 'Mostra la ricevuta di consegna selezionata (pec_del). Per consegne multiple, scegli il destinatario dal menu a discesa.');
  const msgTitle = t('pecViewMessageBtnTitle') || 'Mostra il messaggio originale come si leggerebbe in un client mail (estratto da postacert.eml se assente standalone).';
  const techTitle = t('pecViewTechnicalBtnTitle') || 'Mostra la busta tecnica della PEC: stato firma S/MIME, gestore AgID, ricevute .eml e header tecnici.';

  const formatDelLabel = (o) => {
    return o.dest || (t('unknownRecipient') || 'destinatario sconosciuto');
  };

  let delControl;
  if (delOptions.length <= 1) {
    delControl = segBtn('del', '✅', t('pecViewDelBtn') || 'Consegna', delTitle, delDisabled, !delDisabled ? `_pecSetDetailView(${id},'del',${delOptions[0].fileId})` : '');
  } else {
    const active = _pecDetailView === 'del';
    const bg = active ? '#7c3aed' : '#fff';
    const color = active ? '#fff' : '#7c3aed';
    const lblBtn = t('pecViewDelBtn') || 'Consegna';
    const opts = delOptions.map(o => `<option value="${o.fileId}"${o.fileId === _pecDetailDelFileId ? ' selected' : ''}>${esc(formatDelLabel(o))}</option>`).join('');
    delControl = `<span style="flex:1 1 auto;min-width:0;display:flex;align-items:stretch;border:1px solid #7c3aed;border-radius:6px;overflow:hidden" data-testid="group-pec-view-del-${id}">
      <button class="btn btn-xs" style="flex:0 0 auto;white-space:nowrap;background:${bg};color:${color};border:none;border-radius:0;font-weight:${active ? '700' : '500'}" onclick="_pecSetDetailView(${id},'del',${_pecDetailDelFileId || delOptions[0].fileId})" data-testid="button-pec-view-del-${id}" title="${esc(delTitle)}">✅ ${esc(lblBtn)} (${delOptions.length})</button>
      <select style="flex:1 1 auto;min-width:0;width:100%;border:none;border-left:1px solid ${active ? '#a78bfa' : '#ddd6fe'};background:${bg};color:${color};font-size:11px;padding:2px 4px;cursor:pointer" onchange="_pecSetDetailView(${id},'del',parseInt(this.value,10))" data-testid="select-pec-view-del-${id}" title="${esc(t('pecDelSelectTitle') || 'Scegli la ricevuta di consegna')}">${opts}</select>
    </span>`;
  }

  const segmented = `<span style="display:flex;gap:4px;width:100%" data-testid="group-pec-views-${id}">
    ${segBtn('message', '✉️', t('pecViewMessageBtn') || 'Messaggio', msgTitle, false)}
    ${segBtn('acc', '📥', t('pecViewAccBtn') || 'Accettazione', accTitle, accDisabled)}
    ${delControl}
    ${segBtn('technical', '🔧', t('pecViewTechnicalBtn') || 'Busta tecnica', techTitle, false)}
  </span>`;

  pane.innerHTML = `
    <div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end;align-items:center;margin-bottom:8px" data-testid="toolbar-pec-actions-${id}">
      <button class="btn btn-xs" onclick="_pecShowForm(${id})" data-testid="button-pec-edit-${id}">✏️ ${t('edit') || 'Modifica'}</button>
      <button class="btn btn-xs" style="background:#1e3a8a;color:#fff" onclick="_pecRecheckSmime(${id})" data-testid="button-pec-recheck-smime-${id}" title="${esc(t('pecRecheckSmimeTitle') || 'Rilegge le ricevute pec_acc/pec_del archiviate ed esegue di nuovo la verifica S/MIME (utile per le PEC importate prima dell\'introduzione del controllo, o dopo aver aggiornato la trust list AgID).')}">🔍 ${pec.smimeStatus ? (t('pecRecheckSmime') || 'Riverifica firma') : (t('pecVerifySmime') || 'Verifica firma')}</button>
      <button class="btn btn-xs" style="background:#1e40af;color:#fff" onclick="_pecOpenSubjectFinder(${id})" data-testid="button-pec-find-subject-${id}" title="${esc(t('pecFinderBtnTitle') || 'Cerca fra i soggetti dell\'esponente quelli che compaiono in questa PEC (mittente, destinatari, oggetto, corpo, file .eml originale) e proponili come collegamenti. Ri-eseguibile dopo l\'aggiunta di nuovi soggetti.')}">🔎 ${esc(t('pecFinderBtn') || 'Trova soggetto')}</button>
      <button class="btn btn-xs" style="background:#0d9488;color:#fff" onclick="_pecGenerateFullDossierPdf(${id})" data-testid="button-pec-full-pdf-${id}" title="${esc(t('pecFullPdfBtnTitle') || 'Genera un PDF unico con copertina, messaggio, ricevute, allegati e relata finale. Se ci sono allegati non incorporabili (Office, audio, video) il pacchetto viene generato come ZIP.')}">📑 ${t('pecGenerateFullPdf') || 'Genera fascicolo PDF'}</button>
      <button class="btn btn-xs" style="background:#0f766e;color:#fff" onclick="_pecGenerateRelataPdf(${id})" data-testid="button-pec-relata-${id}" title="${esc(t('pecGenerateRelataTitle') || 'Genera la sola relata di notifica (PDF breve con dati certificati e impronte SHA-256 delle ricevute).')}">📄 ${t('pecGenerateRelata') || 'Solo relata'}</button>
      <button class="btn btn-xs" style="background:#475569;color:#fff" onclick="_pecDownloadEml(${id})" data-testid="button-pec-download-eml-${id}" title="${esc(t('pecDownloadEmlTitle') || 'Scarica TUTTO il pacchetto PEC come ZIP (messaggio, ricevute, allegati + README con metadati e SHA-256).')}">📦 ${t('pecDownloadEml') || 'Scarica PEC (ZIP)'}</button>
      <button class="btn btn-xs" style="background:#dc2626;color:#fff" onclick="_pecDeleteMessage(${id})" data-testid="button-pec-delete-${id}">🗑️ ${t('delete') || 'Elimina'}</button>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;padding:8px 10px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:10px" data-testid="toolbar-pec-detail-${id}">
      ${segmented}
    </div>
    ${_pecDetailView === 'technical' ? `<div style="margin-bottom:14px">
      <div style="flex:1">
        <div style="font-size:11px;color:#2563eb;font-weight:600">📧 ${esc(pec.dataInvio || '')} · Anno ${pec.year || ''} · ${esc(pec.lingua || 'it').toUpperCase()}</div>
        <h3 style="margin:6px 0 4px;font-size:18px">${esc(pec.oggetto || '(senza oggetto)')}</h3>
        <div style="font-size:13px;color:#374151"><b>${t('mittente') || 'Mittente'}:</b> ${esc(pec.mittente || '')}</div>
        <div style="font-size:13px;color:#374151"><b>${t('destinatario') || 'Destinatario'}:</b> ${esc(destinatari)}</div>
        ${subjLabels ? `<div style="font-size:13px;color:#374151"><b>${t('soggettiCollegati') || 'Soggetti collegati'}:</b> ${subjLabels}</div>` : ''}
        ${pec.dataAccettazione ? `<div style="font-size:13px;color:#374151"><b>${t('dataAccettazione') || 'Accettazione'}:</b> ${esc(pec.dataAccettazione)}</div>` : ''}
        ${pec.dataConsegna ? `<div style="font-size:13px;color:#374151"><b>${t('dataConsegna') || 'Consegna'}:</b> ${esc(pec.dataConsegna)}</div>` : ''}
        ${pec.messageId ? `<div style="font-size:11px;color:#6b7280">Message-ID: ${esc(pec.messageId)}</div>` : ''}
        ${(() => { const d = _pecComputeDirectionFromRecord(pec, _pecProfileAddrCache || ''); return `<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">${_pecDirectionBadge(d.direction, d.reason)}${pec.smimeStatus ? _pecSmimeBadge(pec.smimeStatus, pec.smimeAgidProvider, d.direction) : ''}</div>`; })()}
        ${pec.corpoTesto ? `<div style="margin-top:10px;padding:10px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;font-size:13px;white-space:pre-wrap">${esc(pec.corpoTesto)}</div>` : ''}
        ${pec.note ? `<div style="margin-top:8px;font-size:13px;color:#374151;white-space:pre-wrap"><b>${t('note') || 'Note'}:</b> ${esc(pec.note)}</div>` : ''}
      </div>
    </div>` : ''}
    ${(_pecDetailView === 'message' || _pecDetailView === 'acc' || _pecDetailView === 'del') ? (() => { const d = _pecComputeDirectionFromRecord(pec, _pecProfileAddrCache || ''); return `<div style="margin-bottom:10px;display:flex;gap:6px;flex-wrap:wrap">${_pecDirectionBadge(d.direction, d.reason)}${pec.smimeStatus ? _pecSmimeBadge(pec.smimeStatus, pec.smimeAgidProvider, d.direction) : ''}</div>`; })() : ''}
    ${_pecDetailView === 'message' ? `<div id="pecOriginalMessageView_${id}" style="border-top:1px solid #e5e7eb;padding-top:12px;margin-top:4px">
      <div style="font-size:12px;color:#6b7280;padding:6px">${t('loading') || 'Caricamento…'}</div>
    </div>` : ''}
    ${_pecDetailView === 'acc' ? `<div id="pecReceiptView_${id}" style="border-top:1px solid #e5e7eb;padding-top:12px;margin-top:4px" data-testid="container-pec-receipt-acc-${id}">
      <div style="font-size:12px;color:#6b7280;padding:6px">${t('loading') || 'Caricamento…'}</div>
    </div>` : ''}
    ${_pecDetailView === 'del' ? `<div id="pecReceiptView_${id}" style="border-top:1px solid #e5e7eb;padding-top:12px;margin-top:4px" data-testid="container-pec-receipt-del-${id}">
      <div style="font-size:12px;color:#6b7280;padding:6px">${t('loading') || 'Caricamento…'}</div>
    </div>` : ''}
    ${_pecDetailView === 'technical' ? `<div style="border-top:1px solid #e5e7eb;padding-top:12px">
      <h4 style="margin:0 0 8px;font-size:14px">📎 ${t('attachments') || 'File'} (${files.length})</h4>
      ${files.length === 0 ? `<div style="color:#9ca3af;font-size:13px">${t('noAttachments') || 'Nessun file'}</div>` : files.map(fileRow).join('')}
    </div>` : ''}
    ${_pecDetailView === 'technical' ? (() => {
      const emlFiles = files.filter(f => f.fileRole === 'pec_msg' || f.fileRole === 'pec_acc' || f.fileRole === 'pec_del');
      if (!emlFiles.length) return '';
      const lblMsg = t('pecEmlPreview') || 'Anteprima messaggio';
      const lblRcpt = t('pecEmlPreviewReceipt') || 'Anteprima ricevuta';
      const roleIcon = { pec_msg: '✉️', pec_acc: '📥', pec_del: '✅' };
      const roleSuffix = { pec_acc: ' · ' + (t('pecAccFile') || 'Accettazione'), pec_del: ' · ' + (t('pecDelFile') || 'Consegna') };
      return `<div style="border-top:1px solid #e5e7eb;padding-top:12px;margin-top:14px">
        ${emlFiles.map(f => {
          const cid = `pecArchEmlPreview_${id}_${f.id}`;
          const isMsg = f.fileRole === 'pec_msg';
          const lblPrev = isMsg ? lblMsg : lblRcpt;
          const icon = roleIcon[f.fileRole] || '👁️';
          const suffix = roleSuffix[f.fileRole] || '';
          return `<details style="margin-top:8px;background:#fff;border:1px solid #bfdbfe;border-radius:6px;padding:6px 8px" data-testid="container-archived-eml-preview-${f.id}" ontoggle="if(this.open)_pecRenderArchivedEmlPreview(${f.id},'${cid}')">
            <summary style="cursor:pointer;font-size:12px;font-weight:600;color:#1e40af">${icon} ${esc(lblPrev)}${esc(suffix)} — ${esc(f.fileName)} <span style="color:#9ca3af;font-weight:400">(${(f.fileSize/1024).toFixed(1)} KB)</span></summary>
            <div id="${cid}" style="margin-top:6px"></div>
          </details>`;
        }).join('')}
      </div>`;
    })() : ''}
    ${usage.length > 0 ? `<div style="border-top:1px solid #e5e7eb;padding-top:12px;margin-top:14px">
      <h4 style="margin:0 0 8px;font-size:14px">🔗 ${t('pecUsageList') || 'Dove è usata'} (${usage.length})</h4>
      ${usage.map(u => {
        const tipo = u.entityType === 'act' ? (t('atto') || 'Atto') : (u.entityType === 'proof' ? (t('prova') || 'Prova') : u.entityType);
        const badgeColor = u.entityType === 'act' ? '#1d4ed8' : (u.entityType === 'proof' ? '#059669' : '#6b7280');
        const clickable = u.factId != null;
        const args = `${u.factId},'${u.entityType}',${u.entityId},'${(u.position || '').replace(/'/g, "")}'`;
        const onClick = clickable ? `onclick="_pecGotoFromUsage(${args})"` : '';
        const btnClick = clickable ? `onclick="event.stopPropagation();_pecGotoFromUsage(${args})"` : '';
        const cursor = clickable ? 'cursor:pointer' : '';
        const hover = clickable ? 'onmouseover="this.style.background=\'#eef2ff\'" onmouseout="this.style.background=\'#fff\'"' : '';
        const factLine = u.factLabel ? `<div style="font-size:12px;color:#374151;margin-top:2px"><b>${t('fatto') || 'Fatto'}:</b> ${esc(u.factLabel)}</div>` : `<div style="font-size:11px;color:#9ca3af;margin-top:2px;font-style:italic">${t('pecUsageNoFact') || 'Non collegato a un Fatto'}</div>`;
        const dossLine = u.dossierLabel ? `<div style="font-size:11px;color:#6b7280"><b>${t('fascicolo') || 'Fascicolo'}:</b> ${esc(u.dossierLabel)}</div>` : '';
        const goBtn = clickable ? `<button class="btn btn-xs" style="margin-left:auto" ${btnClick} data-testid="button-pec-usage-goto-${u.entityType}-${u.entityId}-${u.factId}">→ ${t('open') || 'Apri'}</button>` : '';
        return `<div ${onClick} ${hover} style="padding:8px 10px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;margin-bottom:4px;font-size:13px;${cursor}" data-testid="row-pec-usage-${u.entityType}-${u.entityId}-${u.factId ?? 'none'}">
          <div style="display:flex;align-items:center;gap:8px">
            <span style="font-size:10px;background:${badgeColor};color:#fff;padding:2px 6px;border-radius:4px;font-weight:600">${esc(tipo)}</span>
            <span style="flex:1">${esc(u.label)}</span>
            ${goBtn}
          </div>
          ${factLine}
          ${dossLine}
        </div>`;
      }).join('')}
    </div>` : ''}`;
  // Task #194: vista messaggio = caricamento async del postacert.eml
  if (_pecDetailView === 'message') {
    _pecRenderOriginalMessageView(id, files).catch(e => {
      console.error('original msg view error', e);
      const c = document.getElementById('pecOriginalMessageView_' + id);
      if (c) c.innerHTML = `<div style="color:#dc2626;background:#fee2e2;border:1px solid #fecaca;border-radius:8px;padding:12px;font-size:12px"><b>⚠️ Errore vista messaggio</b><br><code style="font-size:11px;white-space:pre-wrap;word-break:break-word">${esc((e && (e.stack || e.message)) || String(e))}</code></div>`;
    });
  }
  // Task #196: viste accettazione / consegna = caricamento async della ricevuta
  if (_pecDetailView === 'acc' && accFile) {
    _pecRenderReceiptView(id, accFile.id, 'acc').catch(e => {
      console.error('receipt acc view error', e);
      const c = document.getElementById('pecReceiptView_' + id);
      if (c) c.innerHTML = `<div style="color:#dc2626;background:#fee2e2;border:1px solid #fecaca;border-radius:8px;padding:12px;font-size:12px"><b>⚠️ Errore vista ricevuta</b><br><code style="font-size:11px;white-space:pre-wrap;word-break:break-word">${esc((e && (e.stack || e.message)) || String(e))}</code></div>`;
    });
  }
  if (_pecDetailView === 'del' && _pecDetailDelFileId) {
    _pecRenderReceiptView(id, _pecDetailDelFileId, 'del').catch(e => {
      console.error('receipt del view error', e);
      const c = document.getElementById('pecReceiptView_' + id);
      if (c) c.innerHTML = `<div style="color:#dc2626;background:#fee2e2;border:1px solid #fecaca;border-radius:8px;padding:12px;font-size:12px"><b>⚠️ Errore vista ricevuta</b><br><code style="font-size:11px;white-space:pre-wrap;word-break:break-word">${esc((e && (e.stack || e.message)) || String(e))}</code></div>`;
    });
  }
}

// Task #196: render unificato per vista Accettazione / Consegna.
// Mostra header semantici dal daticert.xml + badge S/MIME + corpo leggibile.
async function _pecRenderReceiptView(pecId, fileId, kind) {
  const cont = document.getElementById('pecReceiptView_' + pecId);
  if (!cont) return;
  const f = await DB.getFile(fileId);
  if (!f) {
    cont.innerHTML = `<div style="color:#dc2626;font-size:13px;padding:8px">${esc(t('previewNotAvailable') || 'Anteprima non disponibile')}</div>`;
    return;
  }
  const bytes = await _pecLoadFileBytes(f);
  if (!bytes || !bytes.length) {
    cont.innerHTML = `<div style="color:#dc2626;font-size:13px;padding:8px">${esc(t('previewNotAvailable') || 'Anteprima non disponibile')}: ${esc(f.fileName)}</div>`;
    return;
  }
  const raw = new TextDecoder('latin1').decode(bytes);
  const root = _emlParsePart(raw);
  const get = n => _emlDecodeMimeWord(_emlGetHeader(root.headers, n) || '');
  const from = get('from');
  const to = get('to');
  const cc = get('cc');
  const subj = get('subject');
  const dateStr = _emlGetHeader(root.headers, 'date');
  const messageId = (_emlGetHeader(root.headers, 'message-id') || '').trim().replace(/^<|>$/g, '');
  const extracted = _emlExtract(root);

  // daticert.xml — fonte verità per i metadati semantici
  let dc = null;
  try {
    const dcXml = _pecExtractDaticertXml(root);
    if (dcXml) dc = _pecParseDaticert(dcXml);
  } catch (_) { dc = null; }

  // S/MIME del singolo file
  let smimeRes = null;
  try { await _loadAgidTrustList(); } catch (_) {}
  try { smimeRes = _smimeVerifyPecReceipt(raw); } catch (_) { smimeRes = null; }

  const titleLbl = kind === 'acc'
    ? (t('pecReceiptAccTitle') || '📥 Ricevuta di accettazione')
    : (t('pecReceiptDelTitle') || '✅ Ricevuta di consegna');

  const tipoLabel = (tp) => {
    const m = {
      'accettazione': t('pecDcTipoAccettazione') || 'accettazione',
      'non-accettazione': t('pecDcTipoNonAccettazione') || 'non accettazione',
      'preavviso-errore-consegna': t('pecDcTipoPreavvisoErrore') || 'preavviso errore consegna',
      'presa-in-carico': t('pecDcTipoPresaInCarico') || 'presa in carico',
      'avvenuta-consegna': t('pecDcTipoConsegna') || 'avvenuta consegna',
      'errore-consegna': t('pecDcTipoErroreConsegna') || 'errore consegna',
      'rilevazione-virus': t('pecDcTipoVirus') || 'rilevazione virus',
    };
    return m[tp] || tp;
  };

  const dcDateFmt = dc && dc.dateIso ? new Date(dc.dateIso).toLocaleString() : '';
  const dcRow = (lbl, val, testid) => val ? `<tr><td style="padding:3px 8px 3px 0;color:#6b7280;white-space:nowrap;vertical-align:top;font-size:12px">${esc(lbl)}</td><td style="padding:3px 0;color:#111;word-break:break-all;font-size:13px" data-testid="${testid}">${esc(val)}</td></tr>` : '';

  // Classificazione del tipo daticert per gerarchia visiva legalmente corretta:
  // - tipi "collettivi" (accettazione): la ricevuta certifica un evento per
  //   TUTTI i destinatari → mostriamo l'elenco completo con nota esplicativa.
  // - tipi "individuali" (avvenuta-consegna, errore-consegna, preavviso-errore-
  //   consegna, rilevazione-virus): la ricevuta certifica un evento per UN
  //   destinatario specifico (in <consegna>) → quel destinatario va in
  //   evidenza, la lista completa resta sotto come contesto del messaggio.
  // Vincolo legale: nessun campo del daticert viene nascosto, solo
  // gerarchizzato visivamente (DPR 68/2005 art. 6, DM 2/11/2005 allegato).
  const dcTipo = (dc && dc.tipo) ? String(dc.tipo).toLowerCase() : '';
  const isAcceptanceType = dcTipo === 'accettazione' || dcTipo === 'non-accettazione';
  const isDeliveryType = dcTipo === 'avvenuta-consegna' || dcTipo === 'errore-consegna' || dcTipo === 'preavviso-errore-consegna' || dcTipo === 'rilevazione-virus';
  // Manteniamo il valore verbatim per il display (vincolo probatorio: il
  // contenuto certificato non va alterato) e una copia normalizzata solo
  // per il matching/highlight all'interno della lista destinatari.
  const consegnaDest = dc && dc.consegnaDest ? String(dc.consegnaDest) : '';
  const consegnaDestKey = consegnaDest.toLowerCase();

  // Badge stato per il destinatario evidenziato (varia per tipo ricevuta)
  const consegnaBadgeFor = (tp) => {
    if (tp === 'avvenuta-consegna') return { label: t('pecDcConsegnaCertOk') || '✅ certificato — consegna avvenuta', bg: '#dcfce7', border: '#16a34a', fg: '#14532d' };
    if (tp === 'errore-consegna')   return { label: t('pecDcConsegnaCertErr') || '❌ certificato — errore consegna', bg: '#fee2e2', border: '#dc2626', fg: '#7f1d1d' };
    if (tp === 'preavviso-errore-consegna') return { label: t('pecDcConsegnaCertWarn') || '⚠️ certificato — preavviso errore', bg: '#fef3c7', border: '#d97706', fg: '#78350f' };
    if (tp === 'rilevazione-virus') return { label: t('pecDcConsegnaCertVirus') || '☣️ certificato — virus rilevato', bg: '#fee2e2', border: '#dc2626', fg: '#7f1d1d' };
    return { label: t('pecDcConsegnaCertGeneric') || '✅ certificato', bg: '#dcfce7', border: '#16a34a', fg: '#14532d' };
  };

  // Tooltip normativi (info icon)
  const lawTip = esc(t('pecDcLawTip') || 'Riferimento normativo: DPR 68/2005 art. 6 e DM 2/11/2005 allegato. La ricevuta di accettazione attesta la presa in carico per TUTTI i destinatari; le ricevute di consegna sono UNA per ciascun destinatario certificato e fanno fede solo per il destinatario indicato in <consegna>.');
  const infoIcon = `<span style="display:inline-block;margin-left:4px;color:#0369a1;cursor:help;font-size:11px" title="${lawTip}">ℹ️</span>`;

  // Riga "destinatario certificato di QUESTA ricevuta" (solo per ricevute individuali)
  const dcConsegnaHighlightRow = (() => {
    if (!isDeliveryType || !consegnaDest) return '';
    const b = consegnaBadgeFor(dcTipo);
    return `<tr><td colspan="2" style="padding:6px 0">
      <div style="background:${b.bg};border:2px solid ${b.border};border-left-width:5px;border-radius:6px;padding:8px 10px" data-testid="container-pec-dc-consegna-${pecId}-${fileId}">
        <div style="font-size:11px;color:${b.fg};font-weight:700;margin-bottom:3px;text-transform:uppercase;letter-spacing:.3px">
          ${esc(t('pecDcConsegnaLabel') || 'Destinatario di questa ricevuta')}${infoIcon}
        </div>
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <span style="font-size:14px;font-weight:700;color:${b.fg};word-break:break-all" data-testid="text-pec-dc-consegna-${pecId}-${fileId}">${esc(consegnaDest)}</span>
          <span style="display:inline-block;background:#fff;border:1px solid ${b.border};color:${b.fg};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600">${esc(b.label)}</span>
        </div>
      </div>
    </td></tr>`;
  })();

  // Riga "destinatari" — etichetta e nota descrittiva variano per tipo
  const dcDestRow = (dcObj, testid) => {
    const list = Array.isArray(dcObj && dcObj.destinatari) ? dcObj.destinatari : [];
    if (!list.length) return '';
    const esterniSet = new Set((dcObj && dcObj.destinatariEsterni) || []);
    const html = list.map(addr => {
      const a = String(addr || '');
      const isExt = esterniSet.has(a.toLowerCase());
      const isHighlighted = consegnaDestKey && a.toLowerCase() === consegnaDestKey;
      // Quando siamo in una ricevuta di consegna, evidenziamo l'indirizzo
      // certificato di QUESTA ricevuta anche dentro la lista completa, per
      // riconoscimento immediato (verde scuro grassetto su sfondo verde chiaro).
      if (isHighlighted) {
        return `<div style="padding:2px 6px;margin:1px 0;background:#dcfce7;border-left:3px solid #16a34a;border-radius:3px;font-weight:700;color:#14532d">${esc(a)} <span style="font-size:10px;font-weight:600;color:#15803d">← ${esc(t('pecDcConsegnaInline') || 'destinatario di questa ricevuta')}</span></div>`;
      }
      return `<div style="padding:1px 0">${esc(a)}${isExt ? ' <span style="color:#92400e;font-size:11px">(esterno)</span>' : ''}</div>`;
    }).join('');
    let label, note = '';
    if (isAcceptanceType) {
      label = t('pecDcDestAcc') || 'Destinatari del messaggio';
      note = `<div style="font-size:11px;color:#6b7280;font-style:italic;margin-bottom:4px">${esc(t('pecDcDestAccNote') || 'L\'accettazione attesta la presa in carico del messaggio per tutti i destinatari elencati.')}${infoIcon}</div>`;
    } else if (isDeliveryType) {
      label = t('pecDcDestDel') || 'Destinatari originali del messaggio (contesto)';
      note = `<div style="font-size:11px;color:#6b7280;font-style:italic;margin-bottom:4px">${esc(t('pecDcDestDelNote') || 'Lista completa dei destinatari della PEC originale. Questa ricevuta fa fede solo per il destinatario evidenziato sopra.')}</div>`;
    } else {
      label = t('destinatari') || 'Destinatari';
    }
    return `<tr><td style="padding:3px 8px 3px 0;color:#6b7280;white-space:nowrap;vertical-align:top;font-size:12px">${esc(label)}</td><td style="padding:3px 0;color:#111;word-break:break-all;font-size:13px" data-testid="${testid}">${note}${html}</td></tr>`;
  };

  const dcBlock = dc ? `<div style="background:#ecfdf5;border:1px solid #6ee7b7;border-radius:8px;padding:10px 12px;margin-bottom:10px" data-testid="container-pec-receipt-daticert-${pecId}-${fileId}">
    <div style="font-size:11px;color:#047857;font-weight:700;margin-bottom:6px">📜 ${esc(t('pecDaticertTitle') || 'Dati certificati (daticert.xml)')}</div>
    <table style="width:100%;border-collapse:collapse"><tbody>
      ${dcRow(t('pecDcTipo') || 'Tipo', tipoLabel(dc.tipo), `text-pec-dc-tipo-${pecId}-${fileId}`)}
      ${dcRow(t('mittente') || 'Mittente', dc.mittente, `text-pec-dc-mittente-${pecId}-${fileId}`)}
      ${dcConsegnaHighlightRow}
      ${dcDestRow(dc, `text-pec-dc-destinatari-${pecId}-${fileId}`)}
      ${dcRow(t('oggetto') || 'Oggetto', dc.oggetto, `text-pec-dc-oggetto-${pecId}-${fileId}`)}
      ${dcRow(t('data') || 'Data', dcDateFmt, `text-pec-dc-data-${pecId}-${fileId}`)}
      ${dcRow(t('pecDcGestore') || 'Gestore emittente', dc.gestoreEmittente, `text-pec-dc-gestore-${pecId}-${fileId}`)}
      ${dcRow('Message-ID', dc.messageId, `text-pec-dc-msgid-${pecId}-${fileId}`)}
    </tbody></table>
  </div>` : `<div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;padding:8px 12px;margin-bottom:10px;font-size:12px;color:#92400e" data-testid="warn-pec-receipt-no-daticert-${pecId}-${fileId}">⚠️ ${esc(t('pecDaticertMissing') || 'daticert.xml non trovato in questa ricevuta — header semantici non disponibili.')}</div>`;

  // Anteprima EML completa (header tecnici, S/MIME, corpo) riusando l'helper esistente
  const previewHtml = _pecBuildEmlPreviewHtml({
    filename: f.fileName,
    sizeKb: ((f.fileSize || bytes.length) / 1024).toFixed(1),
    from, to, cc, subject: subj, date: dateStr || '', messageId,
    returnPath: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'return-path') || ''),
    replyTo: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'reply-to') || ''),
    authResults: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'authentication-results') || ''),
    receivedSpf: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'received-spf') || ''),
    dkim: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'dkim-signature') || ''),
    bodyText: extracted.textPlain || '',
    // Task #196: per le ricevute PEC preferiamo SEMPRE text/plain quando
    // disponibile (è la forma certificata leggibile dei daticert.xml e dello
    // schema standard delle ricevute AgID); ricadiamo su HTML sanificato
    // solo se il plain è assente.
    bodyHtml: (extracted.textPlain && extracted.textPlain.trim()) ? '' : (extracted.textHtml || ''),
    smimeStatus: smimeRes ? smimeRes.status : null,
    smimeDetails: smimeRes ? smimeRes.details : '',
    smimeSigner: smimeRes ? smimeRes.signer : '',
    smimeAgidProvider: smimeRes ? (smimeRes.agidProvider || '') : '',
  }, { wrapDetails: false });

  cont.innerHTML = `<h4 style="margin:0 0 10px;font-size:15px">${esc(titleLbl)} <span style="color:#6b7280;font-size:11px;font-weight:400">— ${esc(f.fileName)} (${((f.fileSize || bytes.length) / 1024).toFixed(1)} KB)</span></h4>
    ${dcBlock}
    <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:10px 12px">${previewHtml}</div>`;
}
window._pecRenderReceiptView = _pecRenderReceiptView;

function _pecSetDetailView(id, view, delFileId) {
  try {
    if (view !== 'message' && view !== 'acc' && view !== 'del' && view !== 'technical') return;
    if (view === 'del' && typeof delFileId === 'number' && !isNaN(delFileId)) {
      _pecDetailDelFileId = delFileId;
    }
    if (_pecDetailView === view && view !== 'del') return;
    _pecDetailView = view;
    const p = _pecShowDetail(id);
    if (p && typeof p.catch === 'function') p.catch(e => console.error('_pecSetDetailView showDetail error', e));
  } catch (e) {
    console.error('_pecSetDetailView error', e);
    alert('Errore cambio vista: ' + (e && e.message || e));
  }
}

function _pecToggleDetailView(id) {
  try {
    _pecDetailView = (_pecDetailView === 'message') ? 'technical' : 'message';
    const p = _pecShowDetail(id);
    if (p && typeof p.catch === 'function') p.catch(e => console.error('_pecToggleDetailView showDetail error', e));
  } catch (e) {
    console.error('_pecToggleDetailView error', e);
    alert('Errore toggle vista: ' + (e.message || e));
  }
}

// Task #194: estrae il messaggio originale leggibile dalla PEC e lo renderizza
// nel container `pecOriginalMessageView_<id>`. Sorgente in ordine di preferenza:
//   1) pec_msg standalone (busta di trasporto in entrata, oppure messaggio
//      dalla cartella Inviata) → estrae postacert.eml interno se presente,
//      altrimenti usa il messaggio stesso.
//   2) postacert.eml dentro pec_del (per le PEC inviate importate solo come
//      ricevute) → marcato come "ricostruito da consegna".
// Niente chiamate di rete, tutto via _pecLoadFileBytes + _emlParsePart.
async function _pecRenderOriginalMessageView(pecId, files) {
  const cont = document.getElementById('pecOriginalMessageView_' + pecId);
  if (!cont) return;
  // Registro centrale degli allegati estratti dal postacert.eml: una sola entry
  // per PEC, sostituita ad ogni rendering. Niente moltiplicazione di handler
  // globali per ogni allegato.
  if (!window._pecMsgAttCache) window._pecMsgAttCache = {};
  // Reset del cache per questa PEC (e cleanup di vecchi handler legacy).
  delete window._pecMsgAttCache[pecId];
  try {
    for (const k of Object.keys(window)) {
      if (k.indexOf('_pecMsgAttDownload_') === 0) { try { delete window[k]; } catch (_) { window[k] = undefined; } }
    }
  } catch (_) { /* ignore */ }
  const escH = s => (s == null ? '' : String(s).replace(/[<>&"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c])));
  const lblTitle = t('pecMsgViewTitle') || 'Messaggio originale';
  const lblNoSource = t('pecMsgViewNoSource') || 'Nessun file .eml presente: il messaggio originale non può essere mostrato. Apri la "Busta tecnica" per il dettaglio dei file disponibili.';
  const lblReconstructed = t('pecMsgViewReconstructed') || 'Messaggio ricostruito dalla ricevuta di consegna (postacert.eml)';
  const lblFromMsg = t('pecMsgViewFromMsg') || 'Messaggio originale dal file .eml standalone';
  const lblFromPostacert = t('pecMsgViewFromPostacert') || 'Messaggio originale estratto da postacert.eml dentro la busta di trasporto';
  const lblAttach = t('pecMsgViewAttachments') || 'Allegati';
  const lblOpen = t('open') || 'Apri';
  const lblDownload = t('download') || 'Scarica';
  const lblErr = t('pecMsgViewError') || 'Errore lettura del messaggio originale';

  const pecMsg = files.find(f => f.fileRole === 'pec_msg');
  const pecDels = files.filter(f => f.fileRole === 'pec_del');
  const pecAccs = files.filter(f => f.fileRole === 'pec_acc');

  let sourceFile = null;
  let extractMode = ''; // 'msg-standalone' | 'msg-postacert' | 'del-postacert' | 'acc-postacert'
  let root = null;
  let inner = null;

  try {
    if (pecMsg) {
      const bytes = await _pecLoadFileBytes(pecMsg);
      if (bytes && bytes.length) {
        const raw = new TextDecoder('latin1').decode(bytes);
        root = _emlParsePart(raw);
        const pcInside = _pecExtractPostacertEml(root);
        if (pcInside) {
          inner = pcInside;
          sourceFile = pecMsg;
          extractMode = 'msg-postacert';
        } else {
          inner = root;
          sourceFile = pecMsg;
          extractMode = 'msg-standalone';
        }
      }
    }
    if (!inner && pecDels.length) {
      for (const del of pecDels) {
        const bytes = await _pecLoadFileBytes(del);
        if (!bytes || !bytes.length) continue;
        const raw = new TextDecoder('latin1').decode(bytes);
        const droot = _emlParsePart(raw);
        const pc = _pecExtractPostacertEml(droot);
        if (pc) {
          inner = pc;
          sourceFile = del;
          extractMode = 'del-postacert';
          break;
        }
      }
    }
    // Fallback finale: postacert.eml dentro pec_acc (es. PEC inviate importate
    // con la sola accettazione del proprio gestore).
    if (!inner && pecAccs.length) {
      for (const acc of pecAccs) {
        const bytes = await _pecLoadFileBytes(acc);
        if (!bytes || !bytes.length) continue;
        const raw = new TextDecoder('latin1').decode(bytes);
        const aroot = _emlParsePart(raw);
        const pc = _pecExtractPostacertEml(aroot);
        if (pc) {
          inner = pc;
          sourceFile = acc;
          extractMode = 'acc-postacert';
          break;
        }
      }
    }
  } catch (e) {
    console.error('original message extract error', e);
    cont.innerHTML = `<h4 style="margin:0 0 8px;font-size:14px">✉️ ${escH(lblTitle)}</h4><div style="color:#dc2626;font-size:13px;padding:8px;background:#fef2f2;border:1px solid #fecaca;border-radius:6px">${escH(lblErr)}: ${escH(e.message || e)}</div>`;
    return;
  }

  if (!inner) {
    cont.innerHTML = `<h4 style="margin:0 0 8px;font-size:14px">✉️ ${escH(lblTitle)}</h4><div style="color:#92400e;font-size:13px;padding:8px;background:#fef3c7;border:1px solid #fde68a;border-radius:6px">${escH(lblNoSource)}</div>`;
    return;
  }

  const get = n => _emlDecodeMimeWord(_emlGetHeader(inner.headers, n) || '');
  const from = get('from');
  const to = get('to');
  const cc = get('cc');
  const subj = get('subject');
  const dateStr = _emlGetHeader(inner.headers, 'date') || '';
  const messageId = (_emlGetHeader(inner.headers, 'message-id') || '').trim().replace(/^<|>$/g, '');
  const ext = _emlExtract(inner);
  const safeHtml = ext.textHtml ? _emlSanitizeHtml(ext.textHtml) : '';
  const attachments = ext.attachments || [];

  const lblFromAcc = t('pecMsgViewFromAcc') || 'Messaggio ricostruito dall\'accettazione del proprio gestore (postacert.eml)';
  // Se la ricevuta sorgente è firmata S/MIME validamente, il postacert.eml
  // interno è legalmente equivalente all'originale: nessun badge di avviso.
  // Il badge ambra appare solo quando la provenienza NON è utilizzabile legalmente
  // (firma assente / invalida / errore di verifica).
  let _pecRec = null;
  try { _pecRec = await DB.getPecMessage(pecId); } catch (_) { _pecRec = null; }
  const _smimeValid = !!(_pecRec && _pecRec.smimeStatus === 'valid');
  const sourceBadge = extractMode === 'acc-postacert'
    ? (_smimeValid ? '' : `<span style="display:inline-block;font-size:11px;background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:4px;border:1px solid #fde68a;margin-bottom:8px" title="${escH(lblFromAcc)}" data-testid="badge-msg-from-acc-${pecId}">⚠ ${escH(lblFromAcc)}</span>`)
    : extractMode === 'del-postacert'
    ? ((_smimeValid || pecAccs.length) ? '' : `<span style="display:inline-block;font-size:11px;background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:4px;border:1px solid #fde68a;margin-bottom:8px" title="${escH(lblReconstructed)}" data-testid="badge-msg-reconstructed-${pecId}">⚠ ${escH(lblReconstructed)}</span>`)
    : extractMode === 'msg-postacert'
      ? `<span style="display:inline-block;font-size:11px;background:#dbeafe;color:#1e40af;padding:2px 8px;border-radius:4px;border:1px solid #bfdbfe;margin-bottom:8px" title="${escH(lblFromPostacert)}" data-testid="badge-msg-from-postacert-${pecId}">📨 ${escH(lblFromPostacert)}</span>`
      : `<span style="display:inline-block;font-size:11px;background:#dcfce7;color:#166534;padding:2px 8px;border-radius:4px;border:1px solid #bbf7d0;margin-bottom:8px" title="${escH(lblFromMsg)}" data-testid="badge-msg-standalone-${pecId}">✉️ ${escH(lblFromMsg)}</span>`;

  const headerRow = (label, val) => val ? `<tr><td style="padding:3px 8px 3px 0;color:#6b7280;white-space:nowrap;vertical-align:top;font-size:12px">${escH(label)}</td><td style="padding:3px 0;color:#111;word-break:break-all;font-size:13px">${escH(val)}</td></tr>` : '';
  const headersTable = `<table style="width:100%;border-collapse:collapse;margin-bottom:10px"><tbody>
    ${headerRow('From:', from)}
    ${headerRow('To:', to)}
    ${headerRow('Cc:', cc)}
    ${headerRow('Subject:', subj)}
    ${headerRow('Date:', dateStr)}
    ${headerRow('Message-ID:', messageId)}
  </tbody></table>`;

  const bodyBlock = safeHtml
    ? `<iframe sandbox="" srcdoc="${escH('<style>body{font-family:sans-serif;font-size:14px;color:#111;margin:10px;line-height:1.5}img{max-width:100%}a{color:#1e40af}</style>' + safeHtml)}" style="width:100%;height:360px;border:1px solid #e5e7eb;border-radius:6px;background:#fff" data-testid="iframe-pec-msg-body-${pecId}"></iframe>`
    : `<pre style="white-space:pre-wrap;font-family:ui-sans-serif,system-ui,sans-serif;font-size:13px;color:#111;background:#fff;border:1px solid #e5e7eb;border-radius:6px;padding:12px;max-height:360px;overflow:auto;margin:0;line-height:1.5" data-testid="text-pec-msg-body-${pecId}">${escH(ext.textPlain || '(corpo vuoto)')}</pre>`;

  // Allegati: registriamo le bytes nel cache centrale, gli handler download/preview
  // sono funzioni globali che leggono il cache. Niente Blob URL persistenti per
  // gli allegati non-aperti.
  if (attachments.length) {
    window._pecMsgAttCache[pecId] = attachments.map(a => ({
      filename: a.filename || '',
      contentType: a.contentType || 'application/octet-stream',
      bytes: a.bytes,
    }));
  }
  const lblPreview = t('pecMsgViewPreview') || 'Anteprima';
  const attachBlock = attachments.length ? `<div style="margin-top:12px">
    <h5 style="margin:0 0 6px;font-size:12px;color:#374151">📎 ${escH(lblAttach)} (${attachments.length})</h5>
    ${attachments.map((a, i) => {
      const sizeKb = (a.bytes.length / 1024).toFixed(1);
      const ct = (a.contentType || '').toLowerCase();
      const fn = (a.filename || '').toLowerCase();
      const previewable = ct.startsWith('image/') || ct === 'application/pdf' || ct.startsWith('text/') || ct === 'application/json' || ct === 'application/xml' || /\.(pdf|png|jpe?g|gif|bmp|webp|svg|txt|log|csv|json|xml|html?|md)$/.test(fn);
      const previewBtn = previewable ? `<button class="btn btn-xs" style="background:#1e40af;color:#fff" onclick="_pecMsgAttPreview(${pecId},${i})" data-testid="button-pec-msg-attachment-preview-${pecId}-${i}">👁️ ${escH(lblPreview)}</button>` : '';
      return `<div style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;margin-bottom:4px" data-testid="row-pec-msg-attachment-${pecId}-${i}">
        <span style="font-size:12px;background:#6b7280;color:#fff;padding:2px 6px;border-radius:4px">📎</span>
        <span style="flex:1;font-size:13px">${escH(a.filename)} <span style="color:#9ca3af;font-size:11px">(${sizeKb} KB · ${escH(a.contentType || 'application/octet-stream')})</span></span>
        ${previewBtn}
        <button class="btn btn-xs" onclick="_pecMsgAttDownload(${pecId},${i})" data-testid="button-pec-msg-attachment-download-${pecId}-${i}">⬇️ ${escH(lblDownload)}</button>
      </div>`;
    }).join('')}
  </div>` : '';

  const sourceFileLine = sourceFile ? `<div style="font-size:11px;color:#6b7280;margin-top:8px">${escH(t('pecMsgViewSourceFile') || 'Fonte')}: ${escH(sourceFile.fileName)} <span style="color:#9ca3af">(${((sourceFile.fileSize || 0) / 1024).toFixed(1)} KB)</span></div>` : '';

  cont.innerHTML = `<h4 style="margin:0 0 8px;font-size:14px">✉️ ${escH(lblTitle)}</h4>
    ${sourceBadge}
    <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:12px" data-testid="container-pec-original-message-${pecId}">
      ${headersTable}
      ${bodyBlock}
      ${attachBlock}
      ${sourceFileLine}
    </div>`;
}

