// Verifica coerenza tra ricevuta di accettazione e ricevuta di consegna
// confrontando i daticert.xml AgID. Ritorna { errors, warnings }.
// errors → blocco salvataggio. warnings → conferma utente.
async function _pecCheckReceiptsCoherence(accBytes, delBytes) {
  const out = { errors: [], warnings: [] };
  if (!accBytes || !delBytes) {
    out.warnings.push((typeof t === 'function' && t('pecCohNoBytes')) || 'Impossibile leggere una delle ricevute: coerenza non verificabile.');
    return out;
  }
  const safeParse = (bytes) => {
    try {
      const root = _emlParsePart(new TextDecoder('latin1').decode(bytes));
      const xml = _pecExtractDaticertXml(root);
      return xml ? _pecParseDaticert(xml) : null;
    } catch (_) { return null; }
  };
  const accDc = safeParse(accBytes);
  const delDc = safeParse(delBytes);
  if (!accDc || !delDc) {
    out.warnings.push((typeof t === 'function' && t('pecCohNoDaticert')) || 'Una o entrambe le ricevute non contengono un daticert.xml AgID leggibile (può essere un .msg Outlook o un export non standard): coerenza non verificabile automaticamente.');
    return out;
  }
  // Controllo tipo busta: acc deve essere "accettazione", del "avvenuta-consegna"
  if (accDc.tipo && !/accett/i.test(accDc.tipo)) {
    out.errors.push(((typeof t === 'function' && t('pecCohWrongAccType')) || 'Il file caricato come Accettazione ha tipo "{0}" invece di "accettazione".').replace('{0}', accDc.tipo));
  }
  if (delDc.tipo && !/conseg/i.test(delDc.tipo)) {
    out.errors.push(((typeof t === 'function' && t('pecCohWrongDelType')) || 'Il file caricato come Consegna ha tipo "{0}" invece di "avvenuta-consegna".').replace('{0}', delDc.tipo));
  }
  // Message-ID identico → stesso messaggio originale
  if (accDc.messageId && delDc.messageId && accDc.messageId !== delDc.messageId) {
    out.errors.push(((typeof t === 'function' && t('pecCohMsgIdMismatch')) || 'Message-ID differente: accettazione "{0}", consegna "{1}". Le due ricevute si riferiscono a messaggi PEC diversi.').replace('{0}', accDc.messageId).replace('{1}', delDc.messageId));
  }
  // Mittente identico
  if (accDc.mittente && delDc.mittente && accDc.mittente !== delDc.mittente) {
    out.errors.push(((typeof t === 'function' && t('pecCohSenderMismatch')) || 'Mittente differente tra accettazione ({0}) e consegna ({1}).').replace('{0}', accDc.mittente).replace('{1}', delDc.mittente));
  }
  // Oggetto identico
  if (accDc.oggetto && delDc.oggetto && accDc.oggetto !== delDc.oggetto) {
    out.errors.push(((typeof t === 'function' && t('pecCohSubjectMismatch')) || 'Oggetto differente tra accettazione ("{0}") e consegna ("{1}").').replace('{0}', accDc.oggetto).replace('{1}', delDc.oggetto));
  }
  // Ordine cronologico: data consegna ≥ data accettazione
  if (accDc.dateIso && delDc.dateIso) {
    const dAcc = new Date(accDc.dateIso), dDel = new Date(delDc.dateIso);
    if (!isNaN(dAcc.getTime()) && !isNaN(dDel.getTime()) && dDel.getTime() < dAcc.getTime()) {
      out.errors.push(((typeof t === 'function' && t('pecCohDateOrder')) || 'Data consegna ({0}) precedente alla data accettazione ({1}): incongruenza temporale.').replace('{0}', delDc.dateIso).replace('{1}', accDc.dateIso));
    }
  }
  return out;
}

async function _pecSaveForm(editId) {
  const destStr = document.getElementById('pecF_destinatario').value.trim();
  const destinatari = destStr.split(/[;,]+/).map(s => s.trim()).filter(Boolean);
  const data = {
    mittente: document.getElementById('pecF_mittente').value.trim(),
    destinatario: destinatari[0] || '',
    destinatari,
    dataInvio: document.getElementById('pecF_dataInvio').value,
    dataAccettazione: document.getElementById('pecF_dataAcc').value || null,
    dataConsegna: document.getElementById('pecF_dataDel').value || null,
    messageId: document.getElementById('pecF_messageId').value.trim(),
    oggetto: document.getElementById('pecF_oggetto').value.trim(),
    note: document.getElementById('pecF_note').value,
    corpoTesto: document.getElementById('pecF_corpo').value,
    lingua: document.getElementById('pecF_lingua').value || 'it',
    soggettiCollegati: Array.from(document.getElementById('pecF_subjects').selectedOptions).map(o => parseInt(o.value, 10)).filter(n => !isNaN(n)),
  };
  if (!data.mittente || !destinatari.length || !data.dataInvio || !data.oggetto) {
    alert(t('pecMissingFields') || 'Compila i campi obbligatori (mittente, destinatario, data, oggetto)');
    return;
  }
  // Validazione obbligatorietà ricevute: senza accettazione e consegna non
  // ha senso archiviare la PEC (la prova legale richiede entrambe). In
  // modifica accettiamo come "presenti" anche i file già archiviati.
  const accInpVal = document.getElementById('pecF_acc');
  const delInpVal = document.getElementById('pecF_del');
  const accSel = !!(accInpVal && accInpVal.files && accInpVal.files[0]);
  const delSel = !!(delInpVal && delInpVal.files && delInpVal.files[0]);
  let hasExistingAcc = false, hasExistingDel = false;
  if (editId) {
    const exFiles = await DB.getEntityFiles('pec', editId);
    hasExistingAcc = exFiles.some(x => x.fileRole === 'pec_acc');
    hasExistingDel = exFiles.some(x => x.fileRole === 'pec_del');
  }
  if (!(accSel || hasExistingAcc) || !(delSel || hasExistingDel)) {
    alert(t('pecMissingReceipts') || 'Per archiviare una PEC sono obbligatorie sia la ricevuta di accettazione sia quella di consegna (.eml/.msg). I file vengono archiviati così come sono, byte per byte, senza alcuna alterazione che possa comprometterne la validità legale.');
    return;
  }
  // Verifica coerenza acc↔del PRIMA di salvare (su bytes appena caricati o
  // sui file già archiviati in modifica). Errori → blocco; warning → conferma.
  try {
    let accBytes = null, delBytes = null;
    if (accSel) accBytes = new Uint8Array(await accInpVal.files[0].arrayBuffer());
    else if (editId && hasExistingAcc) {
      const ex = (await DB.getEntityFiles('pec', editId)).find(x => x.fileRole === 'pec_acc');
      if (ex) accBytes = await _pecLoadFileBytes(ex);
    }
    if (delSel) delBytes = new Uint8Array(await delInpVal.files[0].arrayBuffer());
    else if (editId && hasExistingDel) {
      const ex = (await DB.getEntityFiles('pec', editId)).find(x => x.fileRole === 'pec_del');
      if (ex) delBytes = await _pecLoadFileBytes(ex);
    }
    const coh = await _pecCheckReceiptsCoherence(accBytes, delBytes);
    if (coh.errors.length) {
      alert(((t('pecCohBlockTitle') || '❌ Le due ricevute NON sono coerenti tra loro:') + '\n\n' + coh.errors.map(e => '• ' + e).join('\n') + '\n\n' + (t('pecCohBlockHelp') || 'Verifica che accettazione e consegna provengano dalla STESSA PEC originale e ricarica i file corretti.')));
      return;
    }
    if (coh.warnings.length) {
      const proceed = confirm(((t('pecCohWarnTitle') || '⚠️ Avvisi di coerenza tra le ricevute:') + '\n\n' + coh.warnings.map(w => '• ' + w).join('\n') + '\n\n' + (t('pecCohWarnHelp') || 'Vuoi salvare comunque?')));
      if (!proceed) return;
    }
  } catch (e) {
    console.warn('Coherence check failed', e);
    // Non blocchiamo per errori interni del controllo (es. file binari): l'integrità byte-per-byte resta garantita.
  }
  data.year = _pecYearFromDate(data.dataInvio);
  // Task #195: calcola direzione anche per le PEC create/aggiornate manualmente
  try {
    const profilePec = await _pecGetProfilePec();
    const dir = _pecComputeDirectionFromRecord(Object.assign({}, data, { destinatari }), profilePec);
    data.direction = dir.direction;
    data.directionReason = dir.reason;
  } catch (_) {}
  let pecId = editId;
  if (editId) {
    await DB.updatePecMessage(editId, data);
  } else {
    pecId = await DB.createPecMessage(data); // FIX: ritorna id numerico
  }
  const lang = data.lingua;
  const uploadOne = async (inputId, role) => {
    const inp = document.getElementById(inputId);
    if (inp && inp.files && inp.files[0]) {
      await storeFileForEntity(inp.files[0], 'pec', pecId, lang, {}, role);
    }
  };
  await uploadOne('pecF_acc', 'pec_acc');
  await uploadOne('pecF_del', 'pec_del');
  // Allegati estratti automaticamente dal file .eml/.msg importato in alto
  // (postacert.eml dentro le ricevute, oppure allegati MSG di Outlook).
  let existingAtt = (await DB.getEntityFiles('pec', pecId)).filter(x => x.fileRole === 'pec_attach').length;
  const extracted = window._pecExtractedAttachments || [];
  if (extracted.length) {
    let i = 0;
    for (const a of extracted) {
      i++;
      const file = new File([a.blob], a.filename, { type: a.contentType || 'application/octet-stream' });
      await storeFileForEntity(file, 'pec', pecId, lang, {}, 'pec_attach', { attachIdx: existingAtt + i });
    }
  }
  // Se è stato importato un .eml/.msg con l'utility in alto, salvalo come
  // file messaggio (pec_msg) se non già presente.
  const emlInp = document.getElementById('pecF_eml');
  if (emlInp && emlInp.files && emlInp.files[0]) {
    const alreadyMsg = (await DB.getEntityFiles('pec', pecId)).some(x => x.fileRole === 'pec_msg');
    if (!alreadyMsg) {
      await storeFileForEntity(emlInp.files[0], 'pec', pecId, lang, {}, 'pec_msg');
    }
  }
  window._pecExtractedAttachments = [];
  document.getElementById('pecFormOverlay').remove();
  _pecSelectedId = pecId;
  await _pecRenderList();
  await _pecShowDetail(pecId);
}

async function _pecDeleteMessage(id) {
  const usage = await _pecListUsage(id);
  const lines = usage.map(u => `• ${u.entityType.toUpperCase()} #${u.entityId} — ${u.label}`).join('\n');
  const head = (t('confirmDeletePec') || 'Eliminare questa PEC e i suoi file?');
  let msg = head;
  if (usage.length > 0) {
    msg += '\n\n' + (t('pecUsageWarning') || `ATTENZIONE: ${usage.length} entità collegate perderanno gli allegati richiamati:`).replace('{n}', usage.length) + '\n' + lines;
  }
  if (!confirm(msg)) return;
  await DB.deletePecMessage(id);
  _pecSelectedId = null;
  await _pecRenderList();
  const pane = document.getElementById('pecDetailPane');
  if (pane) pane.innerHTML = `<div style="color:#6b7280;text-align:center;margin-top:80px;font-size:14px">${t('pecSelectHint') || 'Seleziona una PEC dalla lista o creane una nuova'}</div>`;
  if (typeof _decoratePecBadges === 'function') setTimeout(_decoratePecBadges, 100);
}

// ---------- Picker per richiamare PEC dentro un Fatto ----------
async function _pecPickerForFact(factId, defaultMode) {
  document.querySelectorAll('#pecPickerOverlay').forEach(o => o.remove());
  const all = (await DB.getPecMessages()).sort((a, b) => (b.dataInvio || '').localeCompare(a.dataInvio || ''));
  const ov = document.createElement('div');
  ov.id = 'pecPickerOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10010;display:flex;align-items:center;justify-content:center';
  const cards = all.length === 0
    ? `<div style="color:#9ca3af;text-align:center;padding:40px">${t('noPecCreate') || "Nessuna PEC in archivio. Apri prima l'Archivio PEC e creane una."}</div>`
    : all.map(p => `
      <div style="border:1px solid #e5e7eb;border-radius:6px;padding:10px;margin-bottom:8px">
        <div style="display:flex;align-items:center;gap:10px">
          <div style="flex:1">
            <div style="font-size:11px;color:#2563eb;font-weight:600">📧 ${esc(p.dataInvio || '')}</div>
            <div style="font-weight:600;font-size:13px">${esc(p.oggetto || '')}</div>
            <div style="font-size:11px;color:#6b7280">${esc(p.mittente || '')} → ${esc(p.destinatario || '')}</div>
          </div>
          <select id="pecLang_${p.id}" style="padding:4px;border:1px solid #d1d5db;border-radius:4px" data-testid="select-pec-lang-${p.id}">
            <option value="it">IT</option><option value="en">EN</option>
          </select>
        </div>
        <div style="display:flex;gap:6px;margin-top:8px;justify-content:flex-end">
          <button class="btn btn-xs" style="background:#1d4ed8;color:#fff" onclick="_pecCreateFromMessage(${p.id},${factId},'act',document.getElementById('pecLang_${p.id}').value)" data-testid="button-pec-pick-${p.id}-act">${t('createOnlyAct') || '→ Crea solo Atto'}</button>
          <button class="btn btn-xs" style="background:#059669;color:#fff" onclick="_pecCreateFromMessage(${p.id},${factId},'proof',document.getElementById('pecLang_${p.id}').value)" data-testid="button-pec-pick-${p.id}-proof">${t('createOnlyProof') || '→ Crea solo Prova'}</button>
          <button class="btn btn-xs" style="background:#2563eb;color:#fff" onclick="_pecCreateFromMessage(${p.id},${factId},'both',document.getElementById('pecLang_${p.id}').value)" data-testid="button-pec-pick-${p.id}-both">${t('createBoth') || '→ Atto + Prova'}</button>
        </div>
      </div>`).join('');
  ov.innerHTML = `
    <div style="background:#fff;width:min(900px,95vw);max-height:88vh;border-radius:10px;display:flex;flex-direction:column;overflow:hidden">
      <div style="padding:14px 18px;border-bottom:1px solid #e5e7eb;background:#2563eb;color:#fff;display:flex;align-items:center;justify-content:space-between">
        <h3 style="margin:0;font-size:16px">📧 ${t('pecPickerTitle') || 'Richiama PEC'}</h3>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('pecPickerOverlay').remove()">✕</button>
      </div>
      <div style="padding:8px 18px;background:#f3f4f6;font-size:12px;color:#374151">
        ${t('pecPickerHint') || "Per ogni PEC scegli se creare l'Atto (corpo della PEC), la Prova (ricevute) o entrambi. I file fisici non vengono duplicati: vengono creati puntatori al file originale in 00_PEC."}
      </div>
      <div style="overflow-y:auto;padding:14px;flex:1">${cards}</div>
    </div>`;
  document.body.appendChild(ov);
}

// ruoli file da clonare per ciascuna entità derivata
function _pecGotoFromUsage(factId, entityType, entityId, position) {
  if (factId == null) return;
  document.querySelectorAll('#archivioPecOverlay').forEach(o => o.remove());
  if (typeof openFactAnalysisModal !== 'function') return;
  openFactAnalysisModal(factId);
  if (entityType && entityId != null) {
    const trySelector = entityType === 'act'
      ? `[data-testid="act-item-${entityId}"]`
      : (entityType === 'proof' ? `[data-testid="proof-item-${entityId}"]` : null);
    if (!trySelector) return;
    let attempts = 0;
    const tick = () => {
      attempts++;
      const el = document.querySelector(trySelector);
      if (el) {
        try { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_) {}
        const prev = el.style.boxShadow;
        el.style.transition = 'box-shadow .25s';
        el.style.boxShadow = '0 0 0 3px #2563eb';
        setTimeout(() => { el.style.boxShadow = prev || ''; }, 1800);
        if (entityType === 'act' && typeof _factAnalysisViewAct === 'function') {
          try { _factAnalysisViewAct(entityId, position || 'afferma'); } catch (_) {}
        }
      } else if (attempts < 20) {
        setTimeout(tick, 150);
      }
    };
    setTimeout(tick, 250);
  }
}

async function _pecGenerateRelataPdf(pecId) {
  try {
    const pec = await DB.getPecMessage(pecId);
    if (!pec) { alert(t('pecNotFound') || 'PEC non trovata'); return; }
    const files = await DB.getEntityFiles('pec', pecId);
    const accFile = files.find(f => f.fileRole === 'pec_acc');
    const delFiles = files.filter(f => f.fileRole === 'pec_del');
    if (!accFile || delFiles.length === 0) {
      const missing = [];
      if (!accFile) missing.push(t('pecAccFile') || 'ricevuta di accettazione');
      if (delFiles.length === 0) missing.push(t('pecDelFile') || 'ricevuta di consegna');
      alert((t('pecRelataNoReceipts') || 'Per la relata probatoria servono entrambe le ricevute (accettazione e consegna).') + '\n\n' + (t('missing') || 'Mancante') + ': ' + missing.join(', '));
      return;
    }
    const profile = (typeof DB.getUserProfile === 'function') ? await DB.getUserProfile() : null;
    if (!window.jspdf || !window.jspdf.jsPDF) { alert('jsPDF non disponibile'); return; }
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    const pageW = 210;
    const margin = 18;
    let y = margin;
    const isIt = (pec.lingua || 'it') === 'it';
    const L = (it, en) => isIt ? it : en;

    // Intestazione esponente
    doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    const intestaz = [];
    if (profile) {
      const nm = [(profile.firstName || ''), (profile.lastName || '')].filter(Boolean).join(' ').trim() || profile.denominazione || '';
      if (nm) intestaz.push(nm);
      if (profile.codiceFiscale) intestaz.push('C.F. ' + profile.codiceFiscale);
      const addr = [profile.indirizzo, profile.cap, profile.comune, profile.provincia].filter(Boolean).join(' ');
      if (addr) intestaz.push(addr);
      if (profile.pec) intestaz.push('PEC: ' + profile.pec);
      if (profile.email) intestaz.push('Email: ' + profile.email);
    }
    intestaz.forEach(line => { doc.text(line, margin, y); y += 5; });
    if (intestaz.length === 0) { doc.text(L('Esponente', 'Petitioner'), margin, y); y += 5; }
    y += 3;
    doc.setDrawColor(120); doc.line(margin, y, pageW - margin, y); y += 6;

    // Titolo
    doc.setFont('helvetica', 'bold'); doc.setFontSize(15);
    doc.text(L('RELATA DI NOTIFICA A MEZZO PEC', 'PEC NOTIFICATION CERTIFICATE'), pageW / 2, y, { align: 'center' });
    y += 8;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    doc.text(L(
      "Generata automaticamente da UX GIUSTIZIA sulla base delle ricevute della PEC archiviata.",
      "Auto-generated by UX GIUSTIZIA from the archived PEC receipts."
    ), pageW / 2, y, { align: 'center' });
    y += 8;

    // Dati PEC
    doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    doc.text(L('Dati della comunicazione', 'Communication data'), margin, y); y += 6;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
    const destinatari = Array.isArray(pec.destinatari) && pec.destinatari.length ? pec.destinatari.join(', ') : (pec.destinatario || '');
    const rows = [
      [L('Oggetto', 'Subject'), pec.oggetto || ''],
      [L('Mittente', 'Sender'), pec.mittente || ''],
      [L('Destinatario/i', 'Recipient(s)'), destinatari],
      [L('Data invio', 'Send date'), pec.dataInvio || '—'],
      [L('Data accettazione', 'Acceptance date'), pec.dataAccettazione || '—'],
      [L('Data consegna', 'Delivery date'), pec.dataConsegna || '—'],
      [L('Message-ID', 'Message-ID'), pec.messageId || '—'],
    ];
    const labelW = 50;
    rows.forEach(([k, v]) => {
      doc.setFont('helvetica', 'bold'); doc.text(k + ':', margin, y);
      doc.setFont('helvetica', 'normal');
      const wrapped = doc.splitTextToSize(String(v || '—'), pageW - margin - labelW - margin);
      doc.text(wrapped, margin + labelW, y);
      y += Math.max(5, wrapped.length * 5);
      if (y > 260) { doc.addPage(); y = margin; }
    });
    y += 4;

    // Ricevute con hash
    doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    doc.text(L('Ricevute allegate (impronte SHA-256)', 'Attached receipts (SHA-256 hashes)'), margin, y); y += 6;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
    const printReceipt = (label, f) => {
      if (!f) {
        doc.setTextColor(150);
        doc.text(label + ': ' + L('non fornita', 'not provided'), margin, y); y += 5;
        doc.setTextColor(0);
        return;
      }
      doc.setFont('helvetica', 'bold'); doc.text(label + ':', margin, y); y += 4;
      doc.setFont('helvetica', 'normal');
      doc.text(L('File', 'File') + ': ' + (f.fileName || ''), margin + 4, y); y += 4;
      doc.text(L('Dimensione', 'Size') + ': ' + ((f.fileSize || 0) / 1024).toFixed(1) + ' KB', margin + 4, y); y += 4;
      const hashStr = f.hash ? String(f.hash) : L('(hash non calcolato)', '(hash not computed)');
      const wh = doc.splitTextToSize('SHA-256: ' + hashStr, pageW - margin * 2 - 4);
      doc.text(wh, margin + 4, y); y += wh.length * 4 + 2;
      if (y > 260) { doc.addPage(); y = margin; }
    };
    // Parsing daticert per evidenziare il destinatario certificato di QUESTA
    // ricevuta di consegna (DPR 68/2005 art. 6: la ricevuta di avvenuta
    // consegna fa fede solo per il destinatario indicato in <consegna>).
    const parseReceiptDaticert = async (f) => {
      try {
        const bytes = await _pecLoadFileBytes(f);
        if (!bytes) return null;
        const raw = new TextDecoder('latin1').decode(bytes);
        const root = _emlParsePart(raw);
        const xml = _pecExtractDaticertXml(root);
        if (!xml) return null;
        return _pecParseDaticert(xml);
      } catch (eDc) { console.warn('relata daticert parse', eDc); return null; }
    };
    const accDc = await parseReceiptDaticert(accFile);
    const delDcs = [];
    for (const d of delFiles) delDcs.push(await parseReceiptDaticert(d));

    printReceipt(L('Ricevuta di ACCETTAZIONE', 'ACCEPTANCE receipt'), accFile);
    if (accDc && Array.isArray(accDc.destinatari) && accDc.destinatari.length) {
      doc.setFont('helvetica', 'italic'); doc.setFontSize(8); doc.setTextColor(80);
      const accNote = L(
        'Destinatari del messaggio (presa in carico per tutti): ' + accDc.destinatari.join(', '),
        'Message recipients (acceptance for all): ' + accDc.destinatari.join(', ')
      );
      const wAcc = doc.splitTextToSize(accNote, pageW - margin * 2 - 4);
      doc.text(wAcc, margin + 4, y); y += wAcc.length * 4 + 2;
      doc.setTextColor(0);
      if (y > 260) { doc.addPage(); y = margin; }
    }
    // Una sezione per OGNI ricevuta di consegna: il DPR 68/2005 prevede
    // una ricevuta di avvenuta consegna per ciascun destinatario certificato.
    const totalDel = delFiles.length;
    delFiles.forEach((delFile, idx) => {
      const delDc = delDcs[idx];
      const baseLbl = L('Ricevuta di CONSEGNA', 'DELIVERY receipt');
      const label = totalDel > 1 ? (baseLbl + ' ' + (idx + 1) + '/' + totalDel) : baseLbl;
      printReceipt(label, delFile);
      if (delDc && delDc.consegnaDest) {
        doc.setFont('helvetica', 'bold'); doc.setFontSize(9); doc.setTextColor(20, 83, 45);
        const certLbl = L('Destinatario certificato di QUESTA ricevuta', 'Certified recipient of THIS receipt') + ': ';
        const wCert = doc.splitTextToSize(certLbl + delDc.consegnaDest, pageW - margin * 2 - 4);
        doc.text(wCert, margin + 4, y); y += wCert.length * 4 + 1;
        doc.setTextColor(0);
        if (y > 260) { doc.addPage(); y = margin; }
      }
    });
    // Contesto unico (destinatari originali del messaggio) preso dalla prima
    // ricevuta che lo riporta — vale per tutte le consegne.
    const ctxDc = delDcs.find(d => d && Array.isArray(d.destinatari) && d.destinatari.length);
    if (ctxDc) {
      doc.setFont('helvetica', 'italic'); doc.setFontSize(8); doc.setTextColor(80);
      const ctxNote = L(
        'Destinatari originali del messaggio (contesto): ' + ctxDc.destinatari.join(', '),
        'Original message recipients (context): ' + ctxDc.destinatari.join(', ')
      );
      const wCtx = doc.splitTextToSize(ctxNote, pageW - margin * 2 - 4);
      doc.text(wCtx, margin + 4, y); y += wCtx.length * 4 + 2;
      doc.setTextColor(0);
      if (y > 260) { doc.addPage(); y = margin; }
    }
    y += 4;

    // Allegati e messaggio
    const msgFile = files.find(f => f.fileRole === 'pec_msg');
    const attaches = files.filter(f => f.fileRole === 'pec_attach');
    if (msgFile || attaches.length) {
      doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
      doc.text(L('Altri file della PEC', 'Other PEC files'), margin, y); y += 6;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
      const printOther = (lab, f) => {
        const h = f.hash ? ' — SHA-256: ' + String(f.hash).substring(0, 24) + '…' : '';
        const line = '• ' + lab + ' ' + (f.fileName || '') + h;
        const w = doc.splitTextToSize(line, pageW - margin * 2);
        doc.text(w, margin, y); y += w.length * 4 + 1;
        if (y > 270) { doc.addPage(); y = margin; }
      };
      if (msgFile) printOther(L('Messaggio:', 'Message:'), msgFile);
      attaches.forEach(a => printOther(L('Allegato:', 'Attachment:'), a));
      y += 4;
    }

    // Footer
    if (y > 250) { doc.addPage(); y = margin; }
    doc.setDrawColor(120); doc.line(margin, y, pageW - margin, y); y += 6;
    doc.setFont('helvetica', 'italic'); doc.setFontSize(8);
    const ts = new Date().toISOString().replace('T', ' ').substring(0, 19);
    doc.text(L(
      'Documento generato il ' + ts + ' da UX GIUSTIZIA. Le impronte SHA-256 garantiscono l\'integrità delle ricevute.',
      'Document generated on ' + ts + ' by UX GIUSTIZIA. SHA-256 hashes ensure receipt integrity.'
    ), margin, y, { maxWidth: pageW - margin * 2 });

    // Salva come pec_attach
    const blob = doc.output('blob');
    const slug = (pec.oggetto || 'pec').replace(/[^a-zA-Z0-9]+/g, '_').substring(0, 40) || 'pec';
    const fileName = 'Relata_PEC_' + (pec.year || new Date().getFullYear()) + '_' + slug + '.pdf';
    const pdfFile = new File([blob], fileName, { type: 'application/pdf' });
    const existingAtt = files.filter(x => x.fileRole === 'pec_attach').length;
    await storeFileForEntity(pdfFile, 'pec', pecId, pec.lingua || 'it', {}, 'pec_attach', { attachIdx: existingAtt + 1, isRelata: true });

    // Download immediato del PDF nella cartella Download del browser
    try {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (eDl) {
      console.warn('relata download err', eDl);
    }

    alert(t('pecRelataGenerated') || 'Relata PDF generata, salvata come allegato della PEC e scaricata.');
    await _pecRenderList();
    await _pecShowDetail(pecId);
  } catch (e) {
    console.error('relata pdf err', e);
    alert((t('pecRelataError') || 'Errore generazione relata') + ': ' + (e.message || e));
  }
}

// =====================================================================
// _pecDownloadEml — Task #197
// ---------------------------------------------------------------------
// Scarica TUTTO il pacchetto PEC come ZIP: messaggio originale, ricevute
// di accettazione e consegna, allegati estratti, eventuali altri file
// archiviati. Include un README.txt con i metadati certificati estratti
// dai daticert.xml AgID e l'impronta SHA-256 di ogni file (per verifica
// integrità byte-per-byte). Tutti i file sono salvati così come sono,
// senza alterazioni che possano comprometterne la validità legale.
async function _pecDownloadEml(pecId) {
  try {
    const pec = await DB.getPecMessage(pecId);
    if (!pec) { alert(t('pecNotFound') || 'PEC non trovata'); return; }
    const files = await DB.getEntityFiles('pec', pecId);
    if (!files.length) {
      alert(t('pecNoEmlFiles') || 'Nessun file archiviato per questa PEC.');
      return;
    }
    if (typeof JSZip === 'undefined') { alert('JSZip non disponibile'); return; }
    const zip = new JSZip();
    const roleDir = {
      pec_msg: '01_messaggio',
      pec_acc: '02_ricevuta_accettazione',
      pec_del: '03_ricevuta_consegna',
      pec_attach: '04_allegati'
    };
    const sha256Hex = async (bytes) => {
      try {
        const h = await crypto.subtle.digest('SHA-256', bytes);
        return Array.from(new Uint8Array(h)).map(b => b.toString(16).padStart(2, '0')).join('');
      } catch (_) { return ''; }
    };
    const isIt = (pec.lingua || 'it') === 'it';
    const L = (it, en) => isIt ? it : en;
    const readme = [];
    readme.push(L('PACCHETTO PEC — UX GIUSTIZIA', 'PEC PACKAGE — UX GIUSTIZIA'));
    readme.push('='.repeat(60));
    readme.push(L('Oggetto', 'Subject') + ': ' + (pec.oggetto || '—'));
    readme.push(L('Mittente', 'Sender') + ': ' + (pec.mittente || '—'));
    readme.push(L('Destinatari', 'Recipients') + ': ' + ((pec.destinatari || []).join(', ') || '—'));
    readme.push(L('Data invio', 'Send date') + ': ' + (pec.dataInvio || '—'));
    readme.push(L('Message-ID', 'Message-ID') + ': ' + (pec.messageId || '—'));
    if (pec.smimeStatus) readme.push(L('Stato firma S/MIME', 'S/MIME signature status') + ': ' + pec.smimeStatus);
    readme.push('');
    readme.push(L('CONTENUTO DEL PACCHETTO', 'PACKAGE CONTENTS'));
    readme.push('-'.repeat(60));

    // Ordina i file per ruolo (msg, acc, del, attach, altro) e per nome
    const order = { pec_msg: 1, pec_acc: 2, pec_del: 3, pec_attach: 4 };
    const sorted = files.slice().sort((a, b) => {
      const oa = order[a.fileRole] || 9, ob = order[b.fileRole] || 9;
      if (oa !== ob) return oa - ob;
      return String(a.fileName || '').localeCompare(String(b.fileName || ''));
    });
    for (const f of sorted) {
      const bytes = await _pecLoadFileBytes(f);
      if (!bytes) continue;
      const sub = roleDir[f.fileRole] || '05_altro';
      const name = f.fileName || ('file_' + f.id);
      zip.file(sub + '/' + name, bytes);
      const hash = f.hash || await sha256Hex(bytes);
      readme.push('• ' + sub + '/' + name);
      readme.push('  ' + L('Dimensione', 'Size') + ': ' + (bytes.length || 0) + ' bytes');
      readme.push('  SHA-256: ' + (hash || L('non calcolato', 'not computed')));
      readme.push('');
    }
    readme.push('-'.repeat(60));
    const ts = new Date().toISOString().replace('T', ' ').substring(0, 19);
    readme.push(L(
      'Pacchetto generato il ' + ts + ' da UX GIUSTIZIA. I file sono archiviati così come sono, byte per byte, senza alterazioni: la firma digitale S/MIME del gestore PEC e la validità legale della prova restano integre. Le impronte SHA-256 sopra riportate consentono la verifica di integrità.',
      'Package generated on ' + ts + ' by UX GIUSTIZIA. Files are archived as-is, byte for byte, without alterations: the S/MIME digital signature of the PEC provider and the legal validity of the evidence remain intact. The SHA-256 hashes above allow integrity verification.'
    ));
    zip.file('00_README.txt', readme.join('\n'));

    const blob = await zip.generateAsync({ type: 'blob' });
    const slug = (pec.oggetto || 'pec').replace(/[^a-zA-Z0-9]+/g, '_').substring(0, 40) || 'pec';
    const fileName = 'PEC_' + (pec.year || new Date().getFullYear()) + '_' + slug + '.zip';
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = fileName;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  } catch (e) {
    console.error('pec download zip err', e);
    alert((t('pecDownloadEmlError') || 'Errore download pacchetto PEC') + ': ' + (e.message || e));
  }
}
window._pecDownloadEml = _pecDownloadEml;
async function _pecRenderDetail(id) {
  _pecSelectedId = id;
  await _pecRenderList();
}

// =====================================================================
// _isP7m / _p7mUnwrapPdf — sniffing e sbustamento CAdES (PKCS#7)
// ---------------------------------------------------------------------
// Per il fascicolo PDF cartaceo che va al giudice, gli allegati firmati
// in formato CAdES (.pdf.p7m) vanno sbustati e incorporati come
// pagine PDF: la firma resta provata dal .eml originale (prova primaria
// firmata S/MIME dal gestore PEC). Lo sbustamento NON valida la firma
// CAdES (catena cert/OCSP/CRL) — è solo estrazione del contenuto
// firmato per renderlo leggibile a occhio.
// =====================================================================

function _isP7m(name, mime) {
  const n = String(name || '').toLowerCase();
  const m = String(mime || '').toLowerCase();
  if (/\.p7m$/.test(n)) return true;
  if (/^application\/(x-)?pkcs7-mime$/.test(m)) return true;
  return false;
}

// Estrae il contenuto sbustato da un PKCS#7 SignedData (CAdES).
// Restituisce { ok: true, bytes, signerCN, signerO, signingTime } oppure
// { ok: false, error } se il parsing/sbustamento fallisce o se eContent
// è assente (firma detached: non c'è contenuto da sbustare).
function _p7mUnwrapPdf(p7mBytes) {
  if (typeof forge === 'undefined' || !forge.asn1) {
    return { ok: false, error: 'forge non disponibile' };
  }
  if (!p7mBytes || !p7mBytes.length) return { ok: false, error: 'bytes vuoti' };
  try {
    // forge.asn1.fromDer accetta sia ByteStringBuffer sia binary string.
    let binStr = '';
    const u8 = p7mBytes instanceof Uint8Array ? p7mBytes : new Uint8Array(p7mBytes);
    // Se è PEM (-----BEGIN PKCS7-----), decodifica base64 → DER.
    const head = new TextDecoder('latin1').decode(u8.slice(0, 80));
    let der;
    if (/-----BEGIN/i.test(head)) {
      const txt = new TextDecoder('latin1').decode(u8);
      const m = txt.match(/-----BEGIN[^-]+-----([\s\S]+?)-----END/);
      if (!m) return { ok: false, error: 'PEM malformato' };
      der = forge.util.decode64(m[1].replace(/\s+/g, ''));
    } else {
      // DER puro: converti in binary string per forge.
      let s = '';
      for (let i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i]);
      der = s;
    }
    // Parse non-strict per tollerare BER indefinite length usato da alcuni firmatari.
    const asn1 = forge.asn1.fromDer(der, false);
    if (!asn1 || !asn1.value || asn1.value.length < 2) return { ok: false, error: 'ContentInfo malformato' };
    // ContentInfo: [0] OID contentType, [1] [0] EXPLICIT content
    const ctOid = forge.asn1.derToOid(asn1.value[0].value);
    if (ctOid !== '1.2.840.113549.1.7.2') return { ok: false, error: 'non SignedData (oid=' + ctOid + ')' };
    const sd = asn1.value[1].value[0]; // SignedData SEQUENCE
    const sdv = sd.value;
    // sdv: version, digestAlgorithms SET, encapContentInfo SEQUENCE, [0] certs?, [1] crls?, signerInfos SET
    // encapContentInfo è il primo SEQUENCE dopo il SET digestAlgorithms.
    let encap = null;
    for (let i = 0; i < sdv.length; i++) {
      const n = sdv[i];
      if (n.type === forge.asn1.Type.SEQUENCE && n.tagClass === forge.asn1.Class.UNIVERSAL) {
        encap = n; break;
      }
    }
    if (!encap) return { ok: false, error: 'encapContentInfo assente' };
    // encap: SEQUENCE [eContentType OID, [0] EXPLICIT eContent OPTIONAL]
    if (encap.value.length < 2) return { ok: false, error: 'firma detached (eContent assente)' };
    const eContentExplicit = encap.value[1];
    // eContent può essere OCTET STRING singola o SEQUENCE/composite di OCTET STRING (BER chunked).
    // Concatena i byte di tutti gli OCTET STRING trovati (DFS).
    const collected = [];
    const collect = (node) => {
      if (!node) return;
      if (node.type === forge.asn1.Type.OCTETSTRING && typeof node.value === 'string' && node.value.length) {
        collected.push(node.value);
        return;
      }
      if (Array.isArray(node.value)) {
        for (const c of node.value) collect(c);
      } else if (typeof node.value === 'string' && node.value.length && node.tagClass === forge.asn1.Class.CONTEXT_SPECIFIC) {
        // [0] EXPLICIT con valore primitivo: contiene già i bytes (caso DER definito).
        collected.push(node.value);
      }
    };
    collect(eContentExplicit);
    if (!collected.length) return { ok: false, error: 'eContent vuoto' };
    const binContent = collected.join('');
    const out = new Uint8Array(binContent.length);
    for (let i = 0; i < binContent.length; i++) out[i] = binContent.charCodeAt(i) & 0xff;

    // Estrai metadati firmatario dal primo SignerInfo (best-effort, non blocca).
    let signerCN = '', signerO = '', signingTime = '';
    try {
      const certs = [];
      for (const n of sdv) {
        if (n.tagClass === forge.asn1.Class.CONTEXT_SPECIFIC && n.type === 0) {
          for (const c of (n.value || [])) {
            try { certs.push(forge.pki.certificateFromAsn1(c)); } catch (_) {}
          }
        }
      }
      if (certs.length) {
        const c = certs[0];
        const cn = c.subject.getField('CN'); if (cn) signerCN = cn.value;
        const o = c.subject.getField('O'); if (o) signerO = o.value;
      }
      // signingTime tra signedAttrs del primo signerInfo
      const signerInfos = sdv[sdv.length - 1];
      if (signerInfos && signerInfos.value && signerInfos.value.length) {
        const si = signerInfos.value[0];
        for (const n of (si.value || [])) {
          if (n.tagClass === forge.asn1.Class.CONTEXT_SPECIFIC && n.type === 0) {
            for (const attr of (n.value || [])) {
              try {
                const oid = forge.asn1.derToOid(attr.value[0].value);
                if (oid === '1.2.840.113549.1.9.5') {
                  const v = attr.value[1].value[0];
                  let s = v && v.value ? String(v.value) : '';
                  if (s) {
                    // UTCTime YYMMDDHHMMSSZ → ISO; GeneralizedTime YYYYMMDDHHMMSSZ → ISO
                    if (/^\d{12,13}Z?$/.test(s)) {
                      const yy = parseInt(s.substring(0, 2), 10);
                      const yyyy = yy >= 50 ? 1900 + yy : 2000 + yy;
                      signingTime = `${yyyy}-${s.substring(2,4)}-${s.substring(4,6)} ${s.substring(6,8)}:${s.substring(8,10)}:${s.substring(10,12)} UTC`;
                    } else if (/^\d{14}Z?$/.test(s)) {
                      signingTime = `${s.substring(0,4)}-${s.substring(4,6)}-${s.substring(6,8)} ${s.substring(8,10)}:${s.substring(10,12)}:${s.substring(12,14)} UTC`;
                    } else {
                      signingTime = s;
                    }
                  }
                }
              } catch (_) {}
            }
          }
        }
      }
    } catch (_) { /* metadata best-effort */ }

    return { ok: true, bytes: out, signerCN, signerO, signingTime };
  } catch (e) {
    return { ok: false, error: (e && e.message) || String(e) };
  }
}

// =====================================================================
// _pecGenerateFullDossierPdf — fascicolo PEC completo per il giudice
// ---------------------------------------------------------------------
// Genera un PDF unico, impaginato e leggibile, contenente:
//   1. Copertina (intestazione esponente, dati PEC, indice, badge AgID)
//   2. Messaggio originale (header + corpo + lista allegati con hash)
//   3. Ricevuta di accettazione (stile Aruba, dati daticert.xml)
//   4. Una pagina per ciascuna ricevuta di consegna (stile Aruba)
//   5. Allegati: PDF embedati pagina-per-pagina via PDF.js, immagini
//      inserite full-width. Allegati non incorporabili (.docx, .xlsx,
//      .eml, .zip, audio, video, ecc.) sono elencati nell'indice
//      con nome + dimensione + hash + nota "vedi file esterno".
//   6. Relata finale (tabella SHA-256 di TUTTI i file, dichiarazione
//      esponente, data/ora generazione).
//
// Output:
//   - se TUTTI gli allegati sono incorporabili (pdf/img) → scarica
//     direttamente il PDF.
//   - altrimenti → genera uno ZIP che contiene il PDF principale +
//     cartella `allegati_originali/` con i file non-incorporabili.
//
// Tutto offline: jsPDF + PDF.js + JSZip già bundlati nell'app.
// =====================================================================
async function _pecGenerateFullDossierPdf(pecId) {
  try {
    const pec = await DB.getPecMessage(pecId);
    if (!pec) { alert(t('pecNotFound') || 'PEC non trovata'); return; }
    const files = await DB.getEntityFiles('pec', pecId);
    const accFile = files.find(f => f.fileRole === 'pec_acc');
    const delFiles = files.filter(f => f.fileRole === 'pec_del');
    const msgFile = files.find(f => f.fileRole === 'pec_msg');
    const attaches = files.filter(f => f.fileRole === 'pec_attach' && !f.isRelata);
    if (!accFile && delFiles.length === 0) {
      alert(t('pecFullPdfNoReceipts') || 'Servono almeno una ricevuta (accettazione o consegna) per generare il fascicolo PEC.');
      return;
    }
    if (!window.jspdf || !window.jspdf.jsPDF) { alert('jsPDF non disponibile'); return; }
    if (typeof pdfjsLib === 'undefined') { alert('PDF.js non disponibile'); return; }
    if (pdfjsLib.GlobalWorkerOptions) pdfjsLib.GlobalWorkerOptions.workerSrc = 'js/pdf.worker.min.js';

    const profile = (typeof DB.getUserProfile === 'function') ? await DB.getUserProfile() : null;
    const isIt = (pec.lingua || 'it') === 'it';
    const L = (it, en) => isIt ? it : en;

    // Helpers
    const sha256Hex = async (bytes) => {
      try {
        const h = await crypto.subtle.digest('SHA-256', bytes);
        return Array.from(new Uint8Array(h)).map(b => b.toString(16).padStart(2, '0')).join('');
      } catch (_) { return ''; }
    };
    const isImage = (mime, name) => /^image\//i.test(mime || '') || /\.(png|jpe?g|gif|webp|bmp)$/i.test(name || '');
    const isPdfRaw = (mime, name) => /pdf/i.test(mime || '') || /\.pdf$/i.test(name || '');
    // Sniffing PDF sui bytes sbustati (magic %PDF-)
    const looksLikePdfBytes = (u8) => {
      if (!u8 || u8.length < 5) return false;
      return u8[0] === 0x25 && u8[1] === 0x50 && u8[2] === 0x44 && u8[3] === 0x46 && u8[4] === 0x2d;
    };

    // Pre-carica bytes + hash di TUTTI i file rilevanti (per relata finale)
    const loadInfo = async (f) => {
      const b = await _pecLoadFileBytes(f);
      const hash = b ? (f.hash || await sha256Hex(b)) : (f.hash || '');
      return { rec: f, bytes: b, hash };
    };
    const accInfo = accFile ? await loadInfo(accFile) : null;
    const delInfos = [];
    for (const d of delFiles) delInfos.push(await loadInfo(d));
    const msgInfo = msgFile ? await loadInfo(msgFile) : null;
    const attachInfos = [];
    for (const a of attaches) attachInfos.push(await loadInfo(a));

    // Estrazione allegati embedded nelle ricevute (postacert.eml interno).
    // Le ricevute "complete" (consegna, accettazione) trasportano il
    // messaggio originale come parte message/rfc822 ("postacert.eml") che
    // a sua volta contiene gli allegati originali. Quando l'utente ha
    // importato solo le ricevute (senza il pec_msg standalone), questi
    // allegati altrimenti non comparirebbero nel fascicolo. Li estraiamo
    // qui e li uniamo agli `attachInfos` con dedup per hash.
    const seenHashes = new Set(attachInfos.map(a => a.hash).filter(Boolean));
    const seenNameSize = new Set(attachInfos.map(a => `${(a.rec.fileName || '').toLowerCase()}|${a.rec.fileSize || 0}`));
    const extractFromReceipt = async (info, srcLabel) => {
      if (!info || !info.bytes) return;
      try {
        const txt = new TextDecoder('latin1').decode(info.bytes);
        const root = _emlParsePart(txt);
        const inner = _pecExtractPostacertEml(root);
        if (!inner) return;
        const ext = _emlExtract(inner);
        const innerAtts = ext && ext.attachments ? ext.attachments : [];
        for (const at of innerAtts) {
          if (!at.bytes || !at.bytes.length) continue;
          const fname = at.filename || 'allegato';
          // Skippa parti tecniche (smime/daticert) — non sono allegati utente.
          const fl = fname.toLowerCase();
          if (fl === 'smime.p7s' || fl === 'smime.p7m' || fl === 'daticert.xml' || fl === 'postacert.eml') continue;
          const hash = await sha256Hex(at.bytes);
          const key = `${fl}|${at.bytes.length}`;
          if ((hash && seenHashes.has(hash)) || seenNameSize.has(key)) continue;
          if (hash) seenHashes.add(hash);
          seenNameSize.add(key);
          attachInfos.push({
            rec: { fileName: fname, fileType: at.contentType || 'application/octet-stream', fileSize: at.bytes.length },
            bytes: at.bytes,
            hash,
            fromReceipt: srcLabel,
          });
        }
      } catch (_) { /* ricevuta non parsabile: ignora */ }
    };
    // Estrai prima dalla consegna (la sorgente probatoria primaria del recapito),
    // poi dall'accettazione come fallback (in caso di consegna senza postacert.eml).
    for (let i = 0; i < delInfos.length; i++) {
      await extractFromReceipt(delInfos[i], delInfos.length > 1 ? `consegna ${i + 1}/${delInfos.length}` : 'consegna');
    }
    if (accInfo) await extractFromReceipt(accInfo, 'accettazione');

    // Sbustamento CAdES (.pdf.p7m) → embed inline come PDF.
    // Per ogni allegato p7m: tenta lo sbusto; se il contenuto è un PDF
    // valido, sostituisci `bytes`/`embedName`/`embedMime` con il PDF
    // sbustato e annota i metadati firmatario in `cades`. I bytes
    // originali restano in `originalBytes`/`originalHash` (per la relata).
    for (const a of attachInfos) {
      if (!_isP7m(a.rec.fileName, a.rec.fileType)) continue;
      a.originalBytes = a.bytes;
      a.originalHash = a.hash;
      if (!a.bytes) { a.cadesError = 'bytes non disponibili'; continue; }
      const r = _p7mUnwrapPdf(a.bytes);
      if (!r.ok) { a.cadesError = r.error; continue; }
      if (!looksLikePdfBytes(r.bytes)) { a.cadesError = (t('pecCadesNotPdf') || 'contenuto sbustato non è un PDF'); continue; }
      a.bytes = r.bytes;
      a.embedName = String(a.rec.fileName || '').replace(/\.p7m$/i, '');
      a.embedMime = 'application/pdf';
      a.cades = { signerCN: r.signerCN || '', signerO: r.signerO || '', signingTime: r.signingTime || '' };
    }

    const isEmbeddableInfo = (a) => {
      if (a.cades) return true; // p7m sbustato come PDF
      return isImage(a.rec.fileType, a.rec.fileName) || isPdfRaw(a.rec.fileType, a.rec.fileName);
    };
    const isPdfInfo = (a) => {
      if (a.cades) return true;
      return isPdfRaw(a.rec.fileType, a.rec.fileName);
    };

    const nonEmbedAttaches = attachInfos.filter(a => !isEmbeddableInfo(a));
    const needsZip = nonEmbedAttaches.length > 0;

    // Estrai daticert dalle ricevute (stile Aruba)
    const parseReceiptDaticert = (info) => {
      if (!info || !info.bytes) return null;
      try {
        const txt = new TextDecoder('latin1').decode(info.bytes);
        const root = _emlParsePart(txt);
        const dcXml = _pecExtractDaticertXml(root);
        if (!dcXml) return null;
        return _pecParseDaticert(dcXml);
      } catch (_) { return null; }
    };
    const accDc = parseReceiptDaticert(accInfo);
    const delDcs = delInfos.map(parseReceiptDaticert);

    // ---- Inizio PDF ----
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
    try {
      doc.setProperties({
        title: L('Fascicolo PEC', 'PEC dossier') + ' — ' + (pec.oggetto || ''),
        subject: L('Documento informatico unitario per il deposito processuale', 'Single electronic document for court filing'),
        author: (profile && ([(profile.firstName || ''), (profile.lastName || '')].filter(Boolean).join(' ').trim() || profile.denominazione)) || 'UX GIUSTIZIA',
        creator: 'UX GIUSTIZIA',
        keywords: ['PEC', 'fascicolo', 'deposito', pec.messageId || ''].filter(Boolean).join(', ')
      });
    } catch (_) {}
    const pageW = 210, pageH = 297, margin = 18, contentW = pageW - margin * 2;

    const ensureSpace = (y, needed) => {
      if (y + needed > pageH - 18) { doc.addPage(); _drawFooter(); return margin; }
      return y;
    };
    const _drawFooter = () => {
      // La numerazione "pag X di Y" viene applicata in un secondo pass
      // alla fine, quando il numero totale di pagine è noto.
      doc.setFont('helvetica', 'italic'); doc.setFontSize(8); doc.setTextColor(120);
      doc.text(L('Fascicolo PEC — UX GIUSTIZIA', 'PEC dossier — UX GIUSTIZIA'), margin, pageH - 10);
      doc.setTextColor(0);
    };
    const _stampPageNumbers = () => {
      const total = doc.internal.getNumberOfPages();
      for (let i = 1; i <= total; i++) {
        doc.setPage(i);
        doc.setFont('helvetica', 'italic'); doc.setFontSize(8); doc.setTextColor(120);
        doc.text(L(`pag. ${i} di ${total}`, `p. ${i} of ${total}`), pageW - margin, pageH - 10, { align: 'right' });
        doc.setTextColor(0);
      }
    };
    const sectionTitle = (y, txt) => {
      y = ensureSpace(y, 14);
      doc.setFillColor(124, 58, 237); doc.rect(margin, y, contentW, 9, 'F');
      doc.setFont('helvetica', 'bold'); doc.setFontSize(12); doc.setTextColor(255);
      doc.text(txt, margin + 3, y + 6);
      doc.setTextColor(0);
      return y + 14;
    };
    const kv = (y, k, v) => {
      const label = String(k) + ':';
      doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
      const labelW = doc.getTextWidth(label);
      const gap = 2;
      const minColW = 50;
      // Se la label entra nella colonna, valore a margin+colW; altrimenti colonna allargata fino a labelW+gap
      const colW = Math.max(minColW, labelW + gap);
      if (colW + 20 >= contentW) {
        // Label troppo larga: valore a capo sotto la label
        const needLbl = 5;
        y = ensureSpace(y, needLbl + 5);
        doc.text(label, margin, y); y += needLbl;
        doc.setFont('helvetica', 'normal');
        const wrapped = doc.splitTextToSize(String(v == null ? '—' : v), contentW - 4);
        const need = Math.max(5, wrapped.length * 5);
        y = ensureSpace(y, need);
        doc.text(wrapped, margin + 4, y);
        return y + need + 1;
      }
      const wrapped = doc.splitTextToSize(String(v == null ? '—' : v), contentW - colW);
      const need = Math.max(5, wrapped.length * 5);
      y = ensureSpace(y, need);
      doc.text(label, margin, y);
      doc.setFont('helvetica', 'normal'); doc.text(wrapped, margin + colW, y);
      return y + need;
    };

    // ---- 1) COPERTINA ----
    let y = margin;
    // Intestazione esponente
    doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
    if (profile) {
      const nm = [(profile.firstName || ''), (profile.lastName || '')].filter(Boolean).join(' ').trim() || profile.denominazione || '';
      if (nm) { doc.text(nm, margin, y); y += 5; }
      if (profile.codiceFiscale) { doc.setFont('helvetica', 'normal'); doc.text('C.F. ' + profile.codiceFiscale, margin, y); y += 5; }
      const addr = [profile.indirizzo, profile.cap, profile.comune, profile.provincia].filter(Boolean).join(' ');
      if (addr) { doc.setFont('helvetica', 'normal'); doc.text(addr, margin, y); y += 5; }
      if (profile.pec) { doc.setFont('helvetica', 'normal'); doc.text('PEC: ' + profile.pec, margin, y); y += 5; }
    }
    y += 2;
    doc.setDrawColor(120); doc.line(margin, y, pageW - margin, y); y += 8;

    // Titolo principale
    doc.setFont('helvetica', 'bold'); doc.setFontSize(18);
    doc.text(L('FASCICOLO PEC', 'PEC DOSSIER'), pageW / 2, y, { align: 'center' }); y += 8;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(10); doc.setTextColor(100);
    doc.text(L('Documento informatico unitario per il deposito processuale', 'Single electronic document for court filing'), pageW / 2, y, { align: 'center' });
    doc.setTextColor(0); y += 10;

    // Riepilogo PEC
    y = sectionTitle(y, L('Dati della comunicazione PEC', 'PEC communication data'));
    const destStr = Array.isArray(pec.destinatari) && pec.destinatari.length ? pec.destinatari.join(', ') : (pec.destinatario || '');
    y = kv(y, L('Oggetto', 'Subject'), pec.oggetto || L('(senza oggetto)', '(no subject)'));
    y = kv(y, L('Mittente', 'Sender'), pec.mittente || '');
    y = kv(y, L('Destinatario/i', 'Recipient(s)'), destStr);
    y = kv(y, L('Data invio', 'Send date'), pec.dataInvio || '—');
    y = kv(y, L('Data accettazione', 'Acceptance date'), pec.dataAccettazione || '—');
    y = kv(y, L('Data consegna', 'Delivery date'), pec.dataConsegna || '—');
    y = kv(y, 'Message-ID', pec.messageId || '—');
    if (pec.smimeStatus) {
      const lbl = { agid: '✓✓ ' + L('Gestore accreditato AgID', 'AgID accredited provider'), valid: '✓ ' + L('Firma S/MIME valida', 'Valid S/MIME signature'), invalid: '✗ ' + L('Firma S/MIME non valida', 'Invalid S/MIME signature'), unverifiable: '⚠ ' + L('Firma non verificabile', 'Unverifiable signature') }[pec.smimeStatus] || pec.smimeStatus;
      y = kv(y, L('Verifica firma', 'Signature check'), lbl + (pec.smimeAgidProvider ? ' — ' + pec.smimeAgidProvider : ''));
    }
    y += 4;

    // Indice (sommario): ogni voce viene tracciata con la pagina del
    // disegno (idxPage/y) e una chiave; alla fine del documento, quando
    // sono note tutte le pagine target, riempiamo il numero di pagina a
    // destra in stile TOC con leader a puntini.
    const indexEntries = [];
    const indexTargets = {};
    y = sectionTitle(y, L('Indice del fascicolo', 'Dossier index'));
    doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
    const idxItems = [];
    const attachLbl = attachInfos.length ? L(` (con ${attachInfos.length} allegato/i incorporato/i)`, ` (with ${attachInfos.length} embedded attachment(s))`) : '';
    idxItems.push({ label: L('1. Messaggio originale', '1. Original message') + attachLbl, key: 'msg' });
    if (accInfo) idxItems.push({ label: L('2. Ricevuta di accettazione', '2. Acceptance receipt'), key: 'acc' });
    delInfos.forEach((di, i) => idxItems.push({
      label: L(`${accInfo ? 3 : 2}.${i + 1} Ricevuta di consegna — `, `${accInfo ? 3 : 2}.${i + 1} Delivery receipt — `) + ((delDcs[i] && delDcs[i].consegnaDest) || (delDcs[i] && delDcs[i].destinatari[0]) || L('destinatario', 'recipient')),
      key: `del-${i}`
    }));
    idxItems.push({ label: L(`${accInfo ? 4 : 3}. Relata finale e impronte SHA-256`, `${accInfo ? 4 : 3}. Final certificate and SHA-256 hashes`), key: 'relata' });
    idxItems.forEach(it => {
      y = ensureSpace(y, 5);
      doc.text('• ' + it.label, margin + 3, y);
      indexEntries.push({ key: it.key, page: doc.internal.getNumberOfPages(), y, label: it.label });
      y += 5;
    });

    // Indice allegati (mostrato solo se ce ne sono)
    if (attachInfos.length) {
      y += 4;
      y = sectionTitle(y, L('Indice degli allegati', 'Attachment index'));
      doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
      attachInfos.forEach((a, i) => {
        const sz = ((a.rec.fileSize || 0) / 1024).toFixed(1);
        const displayName = a.embedName || a.rec.fileName;
        let stato;
        if (a.cades) stato = L('incorporato — CAdES', 'embedded — CAdES');
        else if (isEmbeddableInfo(a)) stato = L('incorporato', 'embedded');
        else stato = L('in ZIP esterno', 'in external ZIP');
        const prov = a.fromReceipt ? L(` · da ${a.fromReceipt}`, ` · from ${a.fromReceipt}`) : '';
        const label = L(`Allegato ${i + 1}: `, `Attachment ${i + 1}: `) + `${displayName} (${sz} KB) — ${stato}${prov}`;
        const w = doc.splitTextToSize(label, contentW - 4);
        y = ensureSpace(y, w.length * 5);
        doc.text(w, margin + 3, y);
        // Riferimento di pagina ancorato alla PRIMA riga della voce.
        indexEntries.push({ key: `att-${i}`, page: doc.internal.getNumberOfPages(), y, label });
        y += w.length * 5;
      });
    }

    _drawFooter();

    // ---- 2) MESSAGGIO ORIGINALE ----
    doc.addPage(); y = margin; _drawFooter();
    indexTargets['msg'] = doc.internal.getNumberOfPages();
    y = sectionTitle(y, L('1. Messaggio originale', '1. Original message'));
    y = kv(y, L('Da', 'From'), pec.mittente || '');
    y = kv(y, L('A', 'To'), destStr);
    y = kv(y, L('Data', 'Date'), pec.dataInvio || '—');
    y = kv(y, L('Oggetto', 'Subject'), pec.oggetto || '');
    y += 3;
    doc.setDrawColor(200); doc.line(margin, y, pageW - margin, y); y += 5;
    if (pec.corpoTesto) {
      doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
      const lines = doc.splitTextToSize(String(pec.corpoTesto), contentW);
      lines.forEach(ln => { y = ensureSpace(y, 5); doc.text(ln, margin, y); y += 5; });
      y += 4;
    } else {
      doc.setFont('helvetica', 'italic'); doc.setFontSize(10); doc.setTextColor(120);
      doc.text(L('(corpo testo non disponibile)', '(body text not available)'), margin, y); doc.setTextColor(0); y += 6;
    }
    if (attachInfos.length) {
      y = ensureSpace(y, 12);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
      doc.text(L('Allegati al messaggio:', 'Message attachments:'), margin, y); y += 5;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
      attachInfos.forEach((a, i) => {
        const sz = ((a.rec.fileSize || 0) / 1024).toFixed(1);
        const hashShort = a.hash ? a.hash.substring(0, 16) + '…' : '—';
        const embedded = isEmbeddableInfo(a);
        let tag;
        if (a.cades) tag = L(' [' + (t('pecCadesEmbedded') || 'incorporato — firmato CAdES') + ']', ' [' + (tLang('pecCadesEmbedded', 'en') || 'embedded — CAdES signed') + ']');
        else if (embedded) tag = L(' [incorporato]', ' [embedded]');
        else if (a.cadesError) {
          // Distingui "contenuto non-PDF" (informativa) da "parser failure" (warning).
          const isNotPdf = a.cadesError === (t('pecCadesNotPdf') || 'contenuto sbustato non è un PDF') || a.cadesError === 'contenuto sbustato non è un PDF';
          const reasonIt = isNotPdf ? (t('pecCadesNotPdf') || 'contenuto sbustato non è un PDF') : ((t('pecCadesUnwrapFailed') || 'sbustamento fallito') + ': ' + a.cadesError);
          const reasonEn = isNotPdf ? (tLang('pecCadesNotPdf', 'en') || 'unwrapped content is not a PDF') : ((tLang('pecCadesUnwrapFailed', 'en') || 'unwrap failed') + ': ' + a.cadesError);
          tag = L(' [in ZIP esterno — ' + reasonIt + ']', ' [in external ZIP — ' + reasonEn + ']');
        }
        else tag = L(' [in ZIP esterno]', ' [in external ZIP]');
        const provTag = a.fromReceipt ? L(`  (da ${a.fromReceipt})`, `  (from ${a.fromReceipt})`) : '';
        const line = `${i + 1}. ${a.rec.fileName} (${sz} KB)${tag}${provTag} — SHA-256: ${hashShort}`;
        const w = doc.splitTextToSize(line, contentW);
        y = ensureSpace(y, w.length * 4 + 1);
        doc.text(w, margin, y); y += w.length * 4 + 1;
      });
      y += 2;

      // Embed inline degli allegati incorporabili (PDF/immagine) subito dopo il messaggio
      for (let i = 0; i < attachInfos.length; i++) {
        const a = attachInfos[i];
        const embeddable = isEmbeddableInfo(a);
        if (!embeddable) continue;
        const sz = ((a.rec.fileSize || 0) / 1024).toFixed(1);
        const displayName = a.embedName || a.rec.fileName;

        // ===== Copertina dedicata "ALLEGATO N" (pagina intera) =====
        doc.addPage(); _drawFooter();
        indexTargets[`att-${i}`] = doc.internal.getNumberOfPages();
        const cy = pageH / 2 - 30;
        doc.setFont('helvetica', 'bold'); doc.setFontSize(36); doc.setTextColor(13, 148, 136);
        doc.text(L(`ALLEGATO ${i + 1}`, `ATTACHMENT ${i + 1}`), pageW / 2, cy, { align: 'center' });
        doc.setTextColor(120); doc.setFont('helvetica', 'normal'); doc.setFontSize(12);
        doc.text(L(`di ${attachInfos.length}`, `of ${attachInfos.length}`), pageW / 2, cy + 10, { align: 'center' });
        // Nome file (wrap)
        doc.setTextColor(0); doc.setFont('helvetica', 'bold'); doc.setFontSize(13);
        const nameWrap = doc.splitTextToSize(displayName, contentW - 10);
        doc.text(nameWrap, pageW / 2, cy + 24, { align: 'center' });
        let cy2 = cy + 24 + nameWrap.length * 6 + 4;
        // Metadati centrati
        doc.setFont('helvetica', 'normal'); doc.setFontSize(10); doc.setTextColor(80);
        doc.text(`${sz} KB`, pageW / 2, cy2, { align: 'center' }); cy2 += 5;
        const hashShortCover = a.hash ? a.hash.substring(0, 32) + '…' : '—';
        doc.text('SHA-256: ' + hashShortCover, pageW / 2, cy2, { align: 'center' }); cy2 += 5;
        if (a.fromReceipt) {
          doc.setFont('helvetica', 'italic');
          doc.text(L(`(estratto da ${a.fromReceipt})`, `(extracted from ${a.fromReceipt})`), pageW / 2, cy2, { align: 'center' }); cy2 += 5;
        }
        if (a.cades) {
          doc.setFillColor(217, 119, 6); doc.setDrawColor(217, 119, 6);
          const badgeW = 90; const bx = (pageW - badgeW) / 2;
          doc.rect(bx, cy2 + 4, badgeW, 8, 'F');
          doc.setFont('helvetica', 'bold'); doc.setFontSize(10); doc.setTextColor(255);
          doc.text(t('pecCadesBadge') || '🔏 Firma digitale CAdES', pageW / 2, cy2 + 9.5, { align: 'center' });
          doc.setTextColor(0);
        }

        // ===== Pagina di intestazione/dettagli (come prima) =====
        doc.addPage(); y = margin; _drawFooter();
        doc.setFillColor(13, 148, 136); doc.rect(margin, y, contentW, 10, 'F');
        doc.setFont('helvetica', 'bold'); doc.setFontSize(11); doc.setTextColor(255);
        const titleLine = L(`Allegato ${i + 1}/${attachInfos.length}: `, `Attachment ${i + 1}/${attachInfos.length}: `) + displayName;
        const titleWrapped = doc.splitTextToSize(titleLine, contentW - 6);
        doc.text(titleWrapped[0], margin + 3, y + 7);
        doc.setTextColor(0); y += 14;
        doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
        const hLine = `${sz} KB · SHA-256: ${a.hash || '—'}`;
        const hWrap = doc.splitTextToSize(hLine, contentW);
        doc.text(hWrap, margin, y); y += hWrap.length * 4 + 2;

        // Badge CAdES per allegati sbustati
        if (a.cades) {
          const badgeH = 7;
          y = ensureSpace(y, badgeH + 6);
          doc.setFillColor(217, 119, 6); doc.rect(margin, y, contentW, badgeH, 'F');
          doc.setFont('helvetica', 'bold'); doc.setFontSize(9); doc.setTextColor(255);
          doc.text(t('pecCadesBadge') || '🔏 Firma digitale CAdES', margin + 3, y + 5);
          doc.setTextColor(0); y += badgeH + 2;
          doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
          if (a.cades.signerCN) { y = kv(y, t('pecCadesSigner') || 'Firmatario', a.cades.signerCN); }
          if (a.cades.signerO) { y = kv(y, t('pecCadesOrg') || 'Organizzazione', a.cades.signerO); }
          if (a.cades.signingTime) { y = kv(y, t('pecCadesSigningTime') || 'Data firma', a.cades.signingTime); }
          if (a.originalHash) { y = kv(y, L('SHA-256 .p7m originale', '.p7m original SHA-256'), a.originalHash); }
          doc.setFont('helvetica', 'italic'); doc.setFontSize(8); doc.setTextColor(110);
          const noteWrap = doc.splitTextToSize(t('pecCadesNote') || 'Contenuto sbustato dal contenitore PKCS#7. La firma originale è conservata nel file .eml della PEC (prova primaria).', contentW);
          y = ensureSpace(y, noteWrap.length * 4 + 2);
          doc.text(noteWrap, margin, y); y += noteWrap.length * 4 + 2;
          doc.setTextColor(0);
        }

        if (!a.bytes) {
          doc.setFont('helvetica', 'italic'); doc.setTextColor(150);
          doc.text(L('(byte non disponibili)', '(bytes not available)'), margin, y); doc.setTextColor(0);
          continue;
        }
        if (isPdfInfo(a)) {
          try {
            const pdfDoc = await pdfjsLib.getDocument({ data: a.bytes.slice(0) }).promise;
            for (let p = 1; p <= pdfDoc.numPages; p++) {
              const page = await pdfDoc.getPage(p);
              const vp = page.getViewport({ scale: 2 });
              const canvas = document.createElement('canvas');
              canvas.width = vp.width; canvas.height = vp.height;
              const ctx = canvas.getContext('2d');
              await page.render({ canvasContext: ctx, viewport: vp }).promise;
              const imgData = canvas.toDataURL('image/jpeg', 0.85);
              if (p > 1 || y > margin + 20) { doc.addPage(); _drawFooter(); }
              const ratio = vp.width / vp.height;
              let w = contentW, h = w / ratio;
              if (h > pageH - margin * 2 - 10) { h = pageH - margin * 2 - 10; w = h * ratio; }
              doc.addImage(imgData, 'JPEG', margin + (contentW - w) / 2, margin, w, h);
              doc.setFont('helvetica', 'italic'); doc.setFontSize(7); doc.setTextColor(120);
              doc.text(L(`pag. ${p}/${pdfDoc.numPages} dell'allegato`, `p. ${p}/${pdfDoc.numPages} of attachment`), margin, pageH - 14);
              doc.setTextColor(0);
            }
          } catch (ePdf) {
            doc.setFont('helvetica', 'italic'); doc.setTextColor(180, 0, 0);
            doc.text(L('Errore rendering PDF: ', 'PDF render error: ') + (ePdf.message || ''), margin, y); doc.setTextColor(0);
          }
        } else if (isImage(a.rec.fileType, a.rec.fileName)) {
          try {
            const ext = (a.rec.fileName || '').split('.').pop().toLowerCase();
            const mime = a.rec.fileType || ('image/' + (ext === 'jpg' ? 'jpeg' : ext));
            const blob = new Blob([a.bytes], { type: mime });
            const dataUrl = await new Promise((res, rej) => {
              const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(blob);
            });
            const img = await new Promise((res, rej) => {
              const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = dataUrl;
            });
            const ratio = img.width / img.height;
            let w = contentW, h = w / ratio;
            if (h > pageH - margin * 2 - 20) { h = pageH - margin * 2 - 20; w = h * ratio; }
            doc.addImage(dataUrl, /jpe?g/i.test(ext) ? 'JPEG' : 'PNG', margin + (contentW - w) / 2, y, w, h);
          } catch (eImg) {
            doc.setFont('helvetica', 'italic'); doc.setTextColor(180, 0, 0);
            doc.text(L('Errore rendering immagine: ', 'Image render error: ') + (eImg.message || ''), margin, y); doc.setTextColor(0);
          }
        }
      }

      if (nonEmbedAttaches.length) {
        doc.addPage(); y = margin; _drawFooter();
        doc.setFont('helvetica', 'bold'); doc.setFontSize(11);
        doc.text(L('Allegati non incorporabili', 'Non-embeddable attachments'), margin, y); y += 7;
        doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
        const note = doc.splitTextToSize(L(
          'I seguenti allegati (Office, audio, video, ecc.) non sono incorporabili nel PDF e sono inclusi nello ZIP esterno nella cartella "allegati_originali/" con lo stesso nome originale.',
          'The following attachments (Office, audio, video, etc.) cannot be embedded in the PDF and are included in the external ZIP under "allegati_originali/" with the same original name.'
        ), contentW);
        doc.text(note, margin, y); y += note.length * 5 + 2;
        doc.setFont('helvetica', 'normal'); doc.setFontSize(9);
        nonEmbedAttaches.forEach((a, i) => {
          const sz = ((a.rec.fileSize || 0) / 1024).toFixed(1);
          let suffix = '';
          if (a.cadesError) {
            const isNotPdf = a.cadesError === (t('pecCadesNotPdf') || 'contenuto sbustato non è un PDF') || a.cadesError === 'contenuto sbustato non è un PDF';
            const reason = isNotPdf
              ? L(t('pecCadesNotPdf') || 'contenuto sbustato non è un PDF', tLang('pecCadesNotPdf', 'en') || 'unwrapped content is not a PDF')
              : L((t('pecCadesUnwrapFailed') || 'sbustamento fallito') + ': ' + a.cadesError,
                  (tLang('pecCadesUnwrapFailed', 'en') || 'unwrap failed') + ': ' + a.cadesError);
            suffix = L(`  [.p7m — ${reason}]`, `  [.p7m — ${reason}]`);
          }
          const line = `• ${a.rec.fileName} (${sz} KB) — SHA-256: ${a.hash || '—'}${suffix}`;
          const w = doc.splitTextToSize(line, contentW);
          y = ensureSpace(y, w.length * 4 + 1);
          doc.text(w, margin, y); y += w.length * 4 + 1;
        });
      }
    }

    // ---- 3) RICEVUTA ACCETTAZIONE (stile Aruba) ----
    const renderAruba = (info, dc, kind, idx) => {
      doc.addPage(); y = margin; _drawFooter();
      indexTargets[kind === 'acc' ? 'acc' : `del-${idx - 1}`] = doc.internal.getNumberOfPages();
      const titoloIt = kind === 'acc' ? 'Ricevuta di ACCETTAZIONE' : (`Ricevuta di AVVENUTA CONSEGNA${delInfos.length > 1 ? ' (' + idx + '/' + delInfos.length + ')' : ''}`);
      const titoloEn = kind === 'acc' ? 'ACCEPTANCE receipt' : (`DELIVERY receipt${delInfos.length > 1 ? ' (' + idx + '/' + delInfos.length + ')' : ''}`);
      doc.setFillColor(30, 64, 175); doc.rect(margin, y, contentW, 14, 'F');
      doc.setFont('helvetica', 'bold'); doc.setFontSize(14); doc.setTextColor(255);
      doc.text(L(titoloIt, titoloEn), pageW / 2, y + 9, { align: 'center' });
      doc.setTextColor(0); y += 18;

      // Riquadro dati certificati
      doc.setDrawColor(30, 64, 175); doc.setLineWidth(0.5);
      const boxStart = y;
      y += 4;
      doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
      doc.text(L('Dati di certificazione (daticert.xml)', 'Certification data (daticert.xml)'), margin + 3, y); y += 6;
      doc.setLineWidth(0.2);

      if (dc) {
        const tipoLabel = dc.tipo || (kind === 'acc' ? 'accettazione' : 'avvenuta-consegna');
        y = kv(y, L('Tipo ricevuta', 'Receipt type'), tipoLabel);
        y = kv(y, L('Gestore emittente', 'Issuing provider'), dc.gestoreEmittente || '—');
        y = kv(y, L('Data certificata', 'Certified date'), dc.dateIso ? new Date(dc.dateIso).toLocaleString() : '—');
        y = kv(y, L('Mittente', 'Sender'), dc.mittente || '—');
        if (kind === 'del' && dc.consegnaDest) {
          // Ricevuta individuale: il destinatario certificato di QUESTA
          // ricevuta va in evidenza (DPR 68/2005 art. 6). La lista completa
          // dei destinatari originali resta sotto come contesto del messaggio.
          y = kv(y, L('Destinatario certificato di QUESTA ricevuta', 'Certified recipient of THIS receipt'), dc.consegnaDest);
          if (Array.isArray(dc.destinatari) && dc.destinatari.length) {
            y = kv(y, L('Destinatari originali del messaggio (contesto)', 'Original message recipients (context)'), dc.destinatari.join(', '));
          }
        } else {
          // Accettazione: l'evento certificato è collettivo, mostriamo l'elenco completo.
          y = kv(y, L('Destinatari del messaggio (presa in carico per tutti)', 'Message recipients (acceptance for all)'), (dc.destinatari || []).join(', ') || '—');
        }
        y = kv(y, L('Oggetto', 'Subject'), dc.oggetto || '—');
        y = kv(y, 'Message-ID', dc.messageId || '—');
      } else {
        doc.setFont('helvetica', 'italic'); doc.setFontSize(9); doc.setTextColor(150);
        doc.text(L('(daticert.xml non disponibile)', '(daticert.xml not available)'), margin + 3, y); doc.setTextColor(0); y += 6;
      }
      doc.setDrawColor(30, 64, 175); doc.setLineWidth(0.5);
      doc.rect(margin, boxStart, contentW, y - boxStart + 2);
      doc.setLineWidth(0.2);
      y += 8;

      // Hash file .eml
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
      doc.text(L('File originale firmato', 'Original signed file') + ':', margin, y); y += 4;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
      const fn = info.rec.fileName || '';
      const sz = ((info.rec.fileSize || 0) / 1024).toFixed(1) + ' KB';
      doc.text(`${fn} (${sz})`, margin + 3, y); y += 4;
      const hStr = 'SHA-256: ' + (info.hash || L('non calcolato', 'not computed'));
      const wh = doc.splitTextToSize(hStr, contentW - 3);
      doc.text(wh, margin + 3, y); y += wh.length * 4;
    };
    if (accInfo) renderAruba(accInfo, accDc, 'acc', 1);
    delInfos.forEach((di, i) => renderAruba(di, delDcs[i], 'del', i + 1));

    // ---- 5) RELATA FINALE ----
    doc.addPage(); y = margin; _drawFooter();
    indexTargets['relata'] = doc.internal.getNumberOfPages();
    y = sectionTitle(y, L((accInfo ? '4' : '3') + '. Relata finale e impronte SHA-256', (accInfo ? '4' : '3') + '. Final certificate and SHA-256 hashes'));
    doc.setFont('helvetica', 'normal'); doc.setFontSize(10);
    const ts = new Date().toISOString().replace('T', ' ').substring(0, 19);
    const decl = L(
      `Il sottoscritto attesta che il presente fascicolo PEC è stato generato in data ${ts} dall'applicativo UX GIUSTIZIA sulla base del messaggio PEC archiviato e delle relative ricevute. Le impronte SHA-256 riportate nella tabella seguente garantiscono l'integrità di ciascun file componente il fascicolo. Le ricevute .eml originali, firmate digitalmente S/MIME dal gestore PEC, costituiscono la prova primaria ai sensi del DPR 68/2005.`,
      `The undersigned certifies that this PEC dossier was generated on ${ts} by UX GIUSTIZIA based on the archived PEC message and its receipts. The SHA-256 hashes in the table below ensure the integrity of each file in the dossier. The original .eml receipts, digitally signed S/MIME by the PEC provider, are the primary evidence per Italian DPR 68/2005.`
    );
    const declLines = doc.splitTextToSize(decl, contentW);
    declLines.forEach(ln => { y = ensureSpace(y, 5); doc.text(ln, margin, y); y += 5; });
    y += 4;

    doc.setFont('helvetica', 'bold'); doc.setFontSize(10);
    y = ensureSpace(y, 7);
    doc.text(L('Tabella impronte SHA-256', 'SHA-256 hash table'), margin, y); y += 6;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
    const allItems = [];
    if (msgInfo) allItems.push({ k: L('Messaggio', 'Message'), n: msgInfo.rec.fileName, sz: msgInfo.rec.fileSize, h: msgInfo.hash });
    if (accInfo) allItems.push({ k: L('Accettazione', 'Acceptance'), n: accInfo.rec.fileName, sz: accInfo.rec.fileSize, h: accInfo.hash });
    delInfos.forEach((di, i) => allItems.push({ k: L('Consegna ' + (i + 1), 'Delivery ' + (i + 1)), n: di.rec.fileName, sz: di.rec.fileSize, h: di.hash }));
    attachInfos.forEach((a, i) => allItems.push({ k: L('Allegato ' + (i + 1), 'Attachment ' + (i + 1)), n: a.rec.fileName, sz: a.rec.fileSize, h: a.hash }));
    allItems.forEach(it => {
      const sz = ((it.sz || 0) / 1024).toFixed(1) + ' KB';
      const line1 = `${it.k}: ${it.n} (${sz})`;
      const line2 = '   SHA-256: ' + (it.h || L('non calcolato', 'not computed'));
      const w1 = doc.splitTextToSize(line1, contentW);
      const w2 = doc.splitTextToSize(line2, contentW);
      y = ensureSpace(y, (w1.length + w2.length) * 4 + 2);
      doc.setFont('helvetica', 'bold'); doc.text(w1, margin, y); y += w1.length * 4;
      doc.setFont('helvetica', 'normal'); doc.text(w2, margin, y); y += w2.length * 4 + 2;
    });

    // Riempi i numeri di pagina nell'indice (sommario stile TOC con
    // leader a puntini): per ogni voce torniamo sulla pagina della
    // copertina e scriviamo il numero target a destra, con una guida
    // di puntini tra fine testo e numero.
    if (indexEntries.length) {
      const pageNumX = pageW - margin;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(10); doc.setTextColor(60);
      const dotW = doc.getTextWidth('.');
      for (const e of indexEntries) {
        const tgt = indexTargets[e.key];
        if (!tgt) continue;
        doc.setPage(e.page);
        doc.setFont('helvetica', 'normal'); doc.setFontSize(10); doc.setTextColor(60);
        const numStr = String(tgt);
        const numW = doc.getTextWidth(numStr);
        // Misura larghezza del bullet + label (prima riga) per posizionare i puntini
        const firstLine = '• ' + (doc.splitTextToSize(e.label, contentW - 4)[0] || e.label);
        const labelW = doc.getTextWidth(firstLine);
        const dotsStartX = margin + 3 + labelW + 2;
        const dotsEndX = pageNumX - numW - 2;
        if (dotsEndX > dotsStartX + dotW * 2) {
          const dotCount = Math.max(0, Math.floor((dotsEndX - dotsStartX) / (dotW * 1.5)));
          if (dotCount > 0) {
            doc.setTextColor(160);
            doc.text('.'.repeat(dotCount), dotsStartX, e.y);
            doc.setTextColor(60);
          }
        }
        doc.text(numStr, pageNumX, e.y, { align: 'right' });
      }
      doc.setTextColor(0);
    }

    // Numerazione finale "pag X di Y" su tutte le pagine
    _stampPageNumbers();

    // ---- Output ----
    const blob = doc.output('blob');
    const slug = (pec.oggetto || 'pec').replace(/[^a-zA-Z0-9]+/g, '_').substring(0, 40) || 'pec';
    const baseName = 'Fascicolo_PEC_' + (pec.year || new Date().getFullYear()) + '_' + slug;

    if (needsZip) {
      const z = new JSZip();
      z.file(baseName + '.pdf', blob);
      const folder = z.folder('allegati_originali');
      for (const a of nonEmbedAttaches) {
        if (a.bytes) folder.file(a.rec.fileName, a.bytes);
      }
      // Includi anche le ricevute .eml originali (prova primaria)
      const provFolder = z.folder('ricevute_originali');
      if (accInfo && accInfo.bytes) provFolder.file(accInfo.rec.fileName, accInfo.bytes);
      delInfos.forEach(di => { if (di.bytes) provFolder.file(di.rec.fileName, di.bytes); });
      const zipBlob = await z.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(zipBlob);
      const aDl = document.createElement('a');
      aDl.href = url; aDl.download = baseName + '.zip';
      document.body.appendChild(aDl); aDl.click(); document.body.removeChild(aDl);
      setTimeout(() => URL.revokeObjectURL(url), 1500);
      alert(L(
        'Fascicolo PEC generato come ZIP (contiene PDF principale + allegati originali non incorporabili + ricevute .eml).',
        'PEC dossier generated as ZIP (contains main PDF + non-embeddable original attachments + .eml receipts).'
      ));
    } else {
      const url = URL.createObjectURL(blob);
      const aDl = document.createElement('a');
      aDl.href = url; aDl.download = baseName + '.pdf';
      document.body.appendChild(aDl); aDl.click(); document.body.removeChild(aDl);
      setTimeout(() => URL.revokeObjectURL(url), 1500);
      alert(L('Fascicolo PEC generato e scaricato.', 'PEC dossier generated and downloaded.'));
    }
  } catch (e) {
    console.error('full pec pdf err', e);
    alert((t('pecFullPdfError') || 'Errore generazione fascicolo PEC') + ': ' + (e.message || e));
  }
}
window._pecGenerateFullDossierPdf = _pecGenerateFullDossierPdf;

// Riverifica on-demand della firma S/MIME di una PEC già archiviata.
// Rilegge le ricevute pec_acc/pec_del dal disco/IndexedDB, rilancia la
// verifica via _smimeVerifyPecReceipt, aggiorna pec.smimeStatus +
// smimeAgidProvider e prepende un blocco datato alle note (storico).
async function _pecRecheckSmime(pecId) {
  const pec = await DB.getPecMessage(pecId);
  if (!pec) return;
  const files = await DB.getEntityFiles('pec', pecId);
  const accFiles = files.filter(f => f.fileRole === 'pec_acc');
  const delFiles = files.filter(f => f.fileRole === 'pec_del');
  if (accFiles.length === 0 && delFiles.length === 0) {
    alert(t('pecSmimeNoReceipts') || 'Nessuna ricevuta firmata trovata per questa PEC.');
    return;
  }
  // Garantisci la disponibilità della trust list AgID prima del lookup.
  try { await _loadAgidTrustList(); } catch (_) {}

  const targets = [];
  for (const a of accFiles) targets.push({ kind: 'acc', file: a });
  for (const d of delFiles) targets.push({ kind: 'del', file: d });

  const results = [];
  for (const tg of targets) {
    try {
      const bytes = await _pecLoadFileBytes(tg.file);
      if (!bytes) throw new Error('byte non disponibili (file offline o handle FS non attivo)');
      const txt = new TextDecoder('latin1').decode(bytes);
      const r = _smimeVerifyPecReceipt(txt);
      results.push({ kind: tg.kind, ...r });
    } catch (e) {
      results.push({ kind: tg.kind, ok: null, status: 'error', details: 'lettura ricevuta fallita: ' + (e.message || e), signer: '' });
    }
  }

  // Aggregazione identica a _smimeVerifyGroup (acc + del → stato unico).
  const oks = results.filter(r => r.ok === true).length;
  const bads = results.filter(r => r.ok === false).length;
  const agidProviders = results.map(r => r.agidProvider).filter(Boolean);
  const allAgid = results.length > 0 && agidProviders.length === results.length;
  let agg;
  if (results.length && oks === results.length) agg = allAgid ? 'agid' : 'valid';
  else if (bads > 0) agg = 'invalid';
  else agg = 'unverifiable';
  const uniqProviders = Array.from(new Set(agidProviders));
  const aggProvider = uniqProviders.length === 1 ? uniqProviders[0] : (uniqProviders[0] || null);

  const lblAcc = t('pecSmimeNoteAcc') || 'Accettazione';
  const lblDel = t('pecSmimeNoteDel') || 'Consegna';
  const lines = results.map(r => `${r.kind === 'acc' ? lblAcc : lblDel}: ${r.details || ''}${r.signer ? ' [' + r.signer + ']' : ''}`);
  const badgeText = {
    agid: t('pecSmimeStatusAgid') || '✓✓ gestore accreditato AgID',
    valid: t('pecSmimeStatusValid') || '✓ firma valida',
    invalid: t('pecSmimeStatusInvalid') || '✗ firma non valida',
    unverifiable: t('pecSmimeStatusUnverifiable') || '⚠ firma non verificabile',
    absent: t('pecSmimeStatusAbsent') || '— nessuna ricevuta firmata'
  }[agg] || agg;
  const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
  const head = `[${t('pecSmimeNoteHeader') || 'S/MIME riverifica'} ${stamp}] ${badgeText}${aggProvider ? ' — ' + aggProvider : ''}`;
  const block = lines.length ? `${head}\n${lines.join('\n')}` : head;
  const newNote = pec.note ? `${block}\n\n${pec.note}` : block;

  await DB.updatePecMessage(pecId, {
    smimeStatus: agg,
    smimeAgidProvider: aggProvider || '',
    note: newNote
  });
  await _pecShowDetail(pecId);
  alert((t('pecSmimeRechecked') || 'Verifica firma completata.') + '\n\n' + head);
}
window._pecRecheckSmime = _pecRecheckSmime;

// Batch one-shot: rilancia _pecRecheckSmime su TUTTE le PEC archiviate.
// Utile dopo un aggiornamento del verificatore (es. fallback CRLF/LF) per
// recuperare ricevute autentiche marcate come non valide. Mostra una
// finestrella di progresso e un riepilogo finale dei cambi di stato.
async function _pecBatchRecheckSmime() {
  const all = await DB.getPecMessages();
  if (!all.length) { alert('Nessuna PEC in archivio.'); return; }
  const conf = confirm(`Riverifica firma S/MIME su ${all.length} PEC?\n\nQuesta operazione rilegge tutte le ricevute pec_acc/pec_del archiviate e applica il verificatore aggiornato (incluso il fallback CRLF/LF).\n\nLe note esistenti NON verranno cancellate: ad ogni PEC verrà aggiunto un blocco datato con l'esito.`);
  if (!conf) return;

  // Trust list AgID caricata una sola volta per tutto il batch.
  try { await _loadAgidTrustList(); } catch (_) {}

  // Toast progress (semplice, non blocca interazione: l'utente però è in modal)
  let prog = document.getElementById('pecBatchSmimeProg');
  if (!prog) {
    prog = document.createElement('div');
    prog.id = 'pecBatchSmimeProg';
    prog.style.cssText = 'position:fixed;bottom:18px;right:18px;background:#1e3a8a;color:#fff;padding:12px 16px;border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.3);z-index:99999;font-size:13px;min-width:280px';
    document.body.appendChild(prog);
  }

  const counts = { agid: 0, valid: 0, invalid: 0, unverifiable: 0, absent: 0, error: 0 };
  const transitions = []; // { id, oggetto, before, after }
  let recovered = 0; // invalid → valid|agid grazie alla riverifica

  for (let i = 0; i < all.length; i++) {
    const pec = all[i];
    prog.textContent = `Riverifica firma ${i + 1}/${all.length} — ${(pec.oggetto || '').slice(0, 50)}`;
    try {
      const before = pec.smimeStatus || 'absent';
      const files = await DB.getEntityFiles('pec', pec.id);
      const accFiles = files.filter(f => f.fileRole === 'pec_acc');
      const delFiles = files.filter(f => f.fileRole === 'pec_del');
      if (!accFiles.length && !delFiles.length) {
        counts.absent++;
        continue;
      }
      const targets = [];
      for (const a of accFiles) targets.push({ kind: 'acc', file: a });
      for (const d of delFiles) targets.push({ kind: 'del', file: d });
      const results = [];
      for (const tg of targets) {
        try {
          const bytes = await _pecLoadFileBytes(tg.file);
          if (!bytes) throw new Error('byte non disponibili');
          const txt = new TextDecoder('latin1').decode(bytes);
          const r = _smimeVerifyPecReceipt(txt);
          results.push({ kind: tg.kind, ...r });
        } catch (e) {
          results.push({ kind: tg.kind, ok: null, status: 'error', details: 'lettura fallita: ' + (e.message || e), signer: '', agidProvider: null });
        }
      }
      const oks = results.filter(r => r.ok === true).length;
      const bads = results.filter(r => r.ok === false).length;
      const agidProviders = results.map(r => r.agidProvider).filter(Boolean);
      const allAgid = results.length > 0 && agidProviders.length === results.length;
      let agg;
      if (results.length && oks === results.length) agg = allAgid ? 'agid' : 'valid';
      else if (bads > 0) agg = 'invalid';
      else agg = 'unverifiable';
      const uniqProv = Array.from(new Set(agidProviders));
      const aggProv = uniqProv.length === 1 ? uniqProv[0] : (uniqProv[0] || null);

      counts[agg] = (counts[agg] || 0) + 1;
      if (before !== agg) transitions.push({ id: pec.id, oggetto: pec.oggetto, before, after: agg });
      if (before === 'invalid' && (agg === 'valid' || agg === 'agid')) recovered++;

      const lblAcc = t('pecSmimeNoteAcc') || 'Accettazione';
      const lblDel = t('pecSmimeNoteDel') || 'Consegna';
      const lines = results.map(r => `${r.kind === 'acc' ? lblAcc : lblDel}: ${r.details || ''}${r.signer ? ' [' + r.signer + ']' : ''}`);
      const badgeText = { agid: '✓✓ gestore accreditato AgID', valid: '✓ firma valida', invalid: '✗ firma non valida', unverifiable: '⚠ firma non verificabile' }[agg] || agg;
      const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
      const head = `[S/MIME riverifica batch ${stamp}] ${badgeText}${aggProv ? ' — ' + aggProv : ''}${before !== agg ? ` · stato precedente: ${before}` : ''}`;
      const block = lines.length ? `${head}\n${lines.join('\n')}` : head;
      const newNote = pec.note ? `${block}\n\n${pec.note}` : block;
      await DB.updatePecMessage(pec.id, { smimeStatus: agg, smimeAgidProvider: aggProv || '', note: newNote });
    } catch (e) {
      counts.error++;
      console.error('Batch recheck PEC ' + pec.id + ':', e);
    }
  }

  prog.remove();

  // Riepilogo
  const lines = [];
  lines.push(`Riverifica completata su ${all.length} PEC.`);
  lines.push('');
  lines.push(`✓✓ AgID: ${counts.agid}`);
  lines.push(`✓ valida: ${counts.valid}`);
  lines.push(`✗ non valida: ${counts.invalid}`);
  lines.push(`⚠ non verificabile: ${counts.unverifiable}`);
  lines.push(`— senza ricevute: ${counts.absent}`);
  if (counts.error) lines.push(`⚠ errori di lettura: ${counts.error}`);
  lines.push('');
  if (recovered > 0) {
    lines.push(`🎉 Recuperate ${recovered} PEC che prima risultavano "non valida" e ora sono valide (probabile fix CRLF/LF).`);
  }
  if (transitions.length) {
    lines.push('');
    lines.push(`Cambi di stato: ${transitions.length}`);
    for (const tr of transitions.slice(0, 12)) {
      lines.push(`  • "${(tr.oggetto || '').slice(0, 60)}": ${tr.before} → ${tr.after}`);
    }
    if (transitions.length > 12) lines.push(`  ...e altri ${transitions.length - 12}`);
  }
  alert(lines.join('\n'));

  // Refresh elenco visualizzato
  try { _pecRenderList && _pecRenderList(); } catch (_) {}
}
window._pecBatchRecheckSmime = _pecBatchRecheckSmime;

// ──────────────────────────────────────────────────────────────────────────
// Ricalcola mittente/destinatari/oggetto/data del record PEC leggendo il
// daticert.xml dalle ricevute pec_acc/pec_del archiviate. Utile per le PEC
// importate prima dell'introduzione del parser daticert (versioni precedenti
// salvavano il mittente del provider — es. "posta-certificata@gestore" —
// invece del mittente reale del messaggio originale).
//
// Restituisce: { changed: bool, fields: ['mittente','oggetto',...], reason }
// `reason` è valorizzato solo quando changed === false.
// ──────────────────────────────────────────────────────────────────────────
async function _pecRecomputeMetadataFromReceipts(pecId, opts) {
  opts = opts || {};
  const pec = await DB.getPecMessage(pecId);
  if (!pec) return { changed: false, reason: 'record-not-found', fields: [] };
  const files = await DB.getEntityFiles('pec', pecId);
  const accFile = files.find(f => f.fileRole === 'pec_acc');
  const delFile = files.find(f => f.fileRole === 'pec_del');
  const recFile = accFile || delFile;
  if (!recFile) return { changed: false, reason: 'no-receipts', fields: [] };
  let dc = null;
  try {
    const bytes = await _pecLoadFileBytes(recFile);
    if (!bytes) return { changed: false, reason: 'bytes-unavailable', fields: [] };
    const txt = new TextDecoder('latin1').decode(bytes);
    const root = _emlParsePart(txt);
    const dcXml = _pecExtractDaticertXml(root);
    if (!dcXml) return { changed: false, reason: 'no-daticert', fields: [] };
    dc = _pecParseDaticert(dcXml);
    if (!dc) return { changed: false, reason: 'parse-failed', fields: [] };
  } catch (e) {
    return { changed: false, reason: 'read-error: ' + (e.message || e), fields: [] };
  }
  const updates = {};
  const fields = [];
  if (dc.mittente && dc.mittente !== (pec.mittente || '').toLowerCase()) {
    updates.mittente = dc.mittente; fields.push('mittente');
  }
  if (dc.destinatari.length) {
    const newDest = dc.destinatari[0];
    if (newDest && newDest !== (pec.destinatario || '').toLowerCase()) {
      updates.destinatario = newDest; fields.push('destinatario');
    }
    const oldList = Array.isArray(pec.destinatari) ? pec.destinatari.map(s => (s || '').toLowerCase()) : [];
    if (JSON.stringify(oldList.sort()) !== JSON.stringify([...dc.destinatari].sort())) {
      updates.destinatari = dc.destinatari; fields.push('destinatari');
    }
  }
  if (dc.oggetto && dc.oggetto !== (pec.oggetto || '')) {
    updates.oggetto = dc.oggetto; fields.push('oggetto');
  }
  if (dc.dateIso) {
    const dt = new Date(dc.dateIso);
    if (!isNaN(dt.getTime())) {
      const newIso = dt.toISOString();
      if (newIso !== (pec.dataInvio || '')) {
        updates.dataInvio = newIso;
        updates.year = _pecYearFromDate(newIso);
        fields.push('dataInvio');
      }
    }
  }
  if (dc.messageId && dc.messageId !== (pec.messageId || '')) {
    updates.messageId = dc.messageId; fields.push('messageId');
  }
  if (!fields.length) return { changed: false, reason: 'already-up-to-date', fields: [] };
  await DB.updatePecMessage(pecId, updates);
  return { changed: true, fields, reason: '' };
}
window._pecRecomputeMetadataFromReceipts = _pecRecomputeMetadataFromReceipts;

// Ricalcolo BATCH per tutte le PEC dell'archivio. Mostra un modal con
// progress bar e un riepilogo finale.
async function _pecBatchRecomputeMetadata() {
  if (document.getElementById('pecRecomputeOverlay')) return;
  const all = await DB.getPecMessages();
  if (!all.length) { alert(t('noPec') || 'Nessuna PEC in archivio'); return; }
  const confirmMsg = (t('pecRecomputeBatchConfirm') || 'Ricalcola mittenti / oggetti / date REALI per tutte le {0} PEC archiviate, leggendo il daticert.xml dalle ricevute pec_acc/pec_del? Operazione sicura: aggiorna solo i campi diversi dai dati attuali.').replace('{0}', all.length);
  if (!confirm(confirmMsg)) return;
  const ov = document.createElement('div');
  ov.id = 'pecRecomputeOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:11500;display:flex;align-items:center;justify-content:center';
  ov.innerHTML = `
    <div style="background:#fff;width:min(720px,94vw);max-height:88vh;border-radius:10px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.4)" data-testid="modal-pec-recompute">
      <div style="padding:14px 18px;border-bottom:1px solid #e5e7eb;background:#0d9488;color:#fff;display:flex;align-items:center;gap:10px">
        <span style="font-size:20px">🔄</span>
        <h3 style="margin:0;font-size:16px;flex:1">${t('pecRecomputeBatchTitle') || 'Aggiornamento mittenti reali da daticert.xml'}</h3>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('pecRecomputeOverlay').remove();_pecRenderList&&_pecRenderList();" data-testid="button-pec-recompute-close">✕</button>
      </div>
      <div style="padding:16px;overflow:auto;flex:1">
        <div data-testid="text-pec-recompute-progress" style="color:#374151;font-size:13px">${t('pecRecomputeProgress') || 'Elaborazione…'} <span id="pecRecomputeCount">0 / ${all.length}</span></div>
        <div style="margin-top:10px;background:#e5e7eb;border-radius:6px;height:10px;overflow:hidden"><div id="pecRecomputeFill" style="height:100%;width:0%;background:#0d9488;transition:width .15s"></div></div>
        <ul id="pecRecomputeLog" style="margin-top:12px;padding-left:18px;font-size:12px;color:#374151;max-height:50vh;overflow:auto"></ul>
      </div>
    </div>`;
  document.body.appendChild(ov);

  let updated = 0, unchanged = 0, errors = 0;
  for (let i = 0; i < all.length; i++) {
    const p = all[i];
    try {
      const r = await _pecRecomputeMetadataFromReceipts(p.id);
      if (r.changed) {
        updated++;
        const li = document.createElement('li');
        li.style.color = '#0d9488';
        li.textContent = `✓ ${p.oggetto || '(senza oggetto)'} — aggiornati: ${r.fields.join(', ')}`;
        document.getElementById('pecRecomputeLog').appendChild(li);
      } else {
        unchanged++;
      }
    } catch (e) {
      errors++;
      const li = document.createElement('li');
      li.style.color = '#dc2626';
      li.textContent = `✗ ${p.oggetto || p.id}: ${e.message || e}`;
      document.getElementById('pecRecomputeLog').appendChild(li);
    }
    const pct = Math.round(((i + 1) / all.length) * 100);
    const fill = document.getElementById('pecRecomputeFill');
    const cnt = document.getElementById('pecRecomputeCount');
    if (fill) fill.style.width = pct + '%';
    if (cnt) cnt.textContent = `${i + 1} / ${all.length}`;
    if (i % 5 === 4) await new Promise(r => setTimeout(r, 0));
  }
  const summary = document.createElement('div');
  summary.style.cssText = 'margin-top:14px;padding:10px;background:#f0fdfa;border:1px solid #99f6e4;border-radius:6px;color:#0f766e;font-weight:600';
  summary.dataset.testid = 'text-pec-recompute-result';
  summary.textContent = (t('pecRecomputeBatchResult') || 'Aggiornamento completato: {0} aggiornate, {1} già corrette, {2} con errori.')
    .replace('{0}', updated).replace('{1}', unchanged).replace('{2}', errors);
  document.getElementById('pecRecomputeLog').parentElement.appendChild(summary);
}
window._pecBatchRecomputeMetadata = _pecBatchRecomputeMetadata;

// ──────────────────────────────────────────────────────────────────────────
// Trova soggetto collegato (singola PEC) — Task #193
// Cerca, dentro i testi della singola PEC selezionata, i soggetti
// dell'esponente che vi compaiono e li propone all'utente come candidati al
// collegamento. Niente scansione massiva: agisce solo sulla PEC corrente,
// ed è ri-eseguibile (nuovi soggetti aggiunti dopo entrano nelle ricerche
// successive).
// ──────────────────────────────────────────────────────────────────────────

function _pecNormalizeText(s) {
  if (!s) return '';
  try {
    return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  } catch (_) {
    return String(s).toLowerCase();
  }
}

function _pecBuildSubjectTokens(subject) {
  // Restituisce token normalizzati (lowercase + senza accenti) di lunghezza
  // minima 3 da cercare per quel soggetto. Aggiunge anche il "nome cognome"
  // intero come token, perché trovarlo tutto insieme è il segnale più forte.
  if (!subject) return [];
  const raw = [];
  const fn = (subject.firstName || '').trim();
  const ln = (subject.lastName || '').trim();
  if (fn) raw.push(fn);
  if (ln) raw.push(ln);
  if (fn && ln) {
    raw.push(fn + ' ' + ln);
    raw.push(ln + ' ' + fn);
  }
  if (subject.denominazione) raw.push(subject.denominazione);
  // Volutamente NON aggiungiamo email/pec ai token testuali "ampi": gli
  // indirizzi sono confrontati a parte nel livello "address" (mittente,
  // destinatari, Cc del messaggio). Tenerli qui produrrebbe doppi match
  // e badge "menzione" fuorvianti per messaggi in cui l'indirizzo è già
  // stato individuato come prova certa.
  if (subject.codiceFiscale) raw.push(subject.codiceFiscale);
  if (subject.partitaIva) raw.push(subject.partitaIva);
  const seen = new Set();
  const out = [];
  for (const r of raw) {
    const t = _pecNormalizeText(r).trim();
    if (!t || t.length < 3) continue;
    if (seen.has(t)) continue;
    seen.add(t);
    out.push(t);
  }
  // Ordina per lunghezza decrescente: trovare prima il match più lungo
  // produce snippet più informativi (es. "mario rossi" prima di "mario").
  out.sort((a, b) => b.length - a.length);
  return out;
}

function _pecFindMatchInText(rawText, normalizedText, tokens) {
  // Cerca il primo token che appare nel testo già normalizzato e restituisce
  // { token, snippet } usando il testo originale per l'estratto leggibile.
  // Lavora su normalizedText per il match (case+accent insensitive) ma
  // estrae lo snippet dal rawText alla stessa posizione (gli indici
  // coincidono: NFD+lowercase non altera la lunghezza per i caratteri
  // ASCII/latin-1 comuni nelle PEC italiane; se diverge, lo snippet
  // resta comunque correttamente ancorato perché tagliamo per offset).
  if (!normalizedText) return null;
  for (const tok of tokens) {
    const idx = normalizedText.indexOf(tok);
    if (idx < 0) continue;
    const ctxStart = Math.max(0, idx - 40);
    const ctxEnd = Math.min(rawText.length, idx + tok.length + 60);
    const before = rawText.slice(ctxStart, idx);
    const hit = rawText.slice(idx, idx + tok.length);
    const after = rawText.slice(idx + tok.length, ctxEnd);
    const prefix = ctxStart > 0 ? '…' : '';
    const suffix = ctxEnd < rawText.length ? '…' : '';
    return {
      token: tok,
      snippet: prefix + before + '\u0000MATCH_OPEN\u0000' + hit + '\u0000MATCH_CLOSE\u0000' + after + suffix
    };
  }
  return null;
}

function _pecRenderSnippetSafe(snippet) {
  if (!snippet) return '';
  return esc(snippet)
    .replace(/\u0000MATCH_OPEN\u0000/g, '<mark style="background:#fef08a;color:#713f12;padding:0 2px;border-radius:2px">')
    .replace(/\u0000MATCH_CLOSE\u0000/g, '</mark>');
}

function _pecStripHtml(html) {
  if (!html) return '';
  return String(html).replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ').trim();
}

async function _pecExtractEmlBodyText(pecMsgFile) {
  // Legge il file pec_msg archiviato e ne estrae il testo del corpo
  // (textPlain + textHtml strip). Restituisce '' se non possibile (file
  // su disco senza handle FS attivo, parser fallito, ecc.).
  const meta = await _pecExtractEmlBodyAndAddresses(pecMsgFile);
  return meta.body;
}

// Normalizza un indirizzo email per confronto case-insensitive.
function _pecNormalizeEmail(s) {
  if (!s) return '';
  return String(s).toLowerCase().trim();
}

// Estrae uno o più indirizzi da una stringa "Nome Cognome <a@b>, c@d; e@f".
// Tollerante a separatori `,` e `;`, parsing `Nome <indirizzo>`, dedupe.
function _pecExtractEmailAddresses(raw) {
  if (!raw) return [];
  return String(raw)
    .split(/[,;]/)
    .map(p => {
      const m = p.match(/<([^>]+)>/);
      return _pecNormalizeEmail(m ? m[1] : p);
    })
    .filter(s => s && s.indexOf('@') > 0);
}

// Legge il file pec_msg e ritorna in un'unica passata sia il testo del
// corpo (per il match a livello "menzione") sia gli indirizzi from/to/cc
// (per il match a livello "indirizzo"). I campi Cc esistono solo qui:
// nel record pecMessages non sono memorizzati separatamente.
async function _pecExtractEmlBodyAndAddresses(pecMsgFile) {
  const result = { body: '', addresses: { from: [], to: [], cc: [] } };
  if (!pecMsgFile) return result;
  try {
    const bytes = await _pecLoadFileBytes(pecMsgFile);
    if (!bytes) return result;
    const txt = new TextDecoder('latin1').decode(bytes);
    const root = _emlParsePart(txt);
    const inner = _pecExtractPostacertEml(root) || root;
    const ext = _emlExtract(inner);
    const plain = ext.textPlain || '';
    const html = _pecStripHtml(ext.textHtml || '');
    result.body = (plain + '\n' + html).trim();
    const get = n => _emlDecodeMimeWord(_emlGetHeader(inner.headers, n) || '');
    const fromH = get('from'), toH = get('to'), ccH = get('cc');
    if (fromH) result.addresses.from.push(..._pecExtractEmailAddresses(fromH));
    if (toH) result.addresses.to.push(..._pecExtractEmailAddresses(toH));
    if (ccH) result.addresses.cc.push(..._pecExtractEmailAddresses(ccH));
  } catch (e) {
    console.warn('_pecExtractEmlBodyAndAddresses error:', e);
  }
  return result;
}

// Combina gli indirizzi del record pecMessages con quelli letti dall'.eml,
// dedupli normalizzati. Returns { from: [], to: [], cc: [] }.
function _pecBuildMessageAddresses(pec, emlAddresses) {
  const from = [];
  const to = [];
  const cc = [];
  if (pec) {
    if (pec.mittente) from.push(..._pecExtractEmailAddresses(pec.mittente));
    const dests = Array.isArray(pec.destinatari) && pec.destinatari.length
      ? pec.destinatari
      : (pec.destinatario ? [pec.destinatario] : []);
    for (const d of dests) to.push(..._pecExtractEmailAddresses(d));
  }
  if (emlAddresses) {
    from.push(...(emlAddresses.from || []));
    to.push(...(emlAddresses.to || []));
    cc.push(...(emlAddresses.cc || []));
  }
  return {
    from: Array.from(new Set(from)),
    to: Array.from(new Set(to)),
    cc: Array.from(new Set(cc)),
  };
}

// Helper riusabile per la ricerca duale soggetto↔PEC con DUE LIVELLI di
// affidabilità. Dato un soggetto e una PEC (con body .eml opzionale +
// indirizzi from/to/cc già pre-estratti), ritorna:
//   - { level: 'address', role: 'sender'|'recipient', matchedField, matchedAddress, snippet, score }
//     quando l'indirizzo PEC (o l'email) del soggetto compare in From/To/Cc:
//     prova OGGETTIVA che il soggetto ha scritto o ricevuto la PEC.
//   - { level: 'mention', matchedField, token, snippet, score }
//     quando l'indirizzo non corrisponde ma nome/cognome/CF/PIVA appaiono
//     in oggetto/corpo/.eml: solo INDIZIO testuale, da confermare a mano.
//   - null se nessun match.
// Usato sia da _pecFindSubjectCandidates sia da _subjectFindPecs: la
// pipeline è identica nelle due direzioni per garantire simmetria.
function _pecMatchSubjectAgainstPec(subj, pec, emlBody, msgAddresses) {
  // ====== LIVELLO 1 — match per indirizzo PEC (certo) ======
  if (msgAddresses) {
    const addrs = new Set();
    if (subj.pec) addrs.add(_pecNormalizeEmail(subj.pec));
    if (subj.email) addrs.add(_pecNormalizeEmail(subj.email));
    addrs.delete('');
    if (addrs.size > 0) {
      for (const a of (msgAddresses.from || [])) {
        if (addrs.has(a)) return { level: 'address', role: 'sender', matchedField: 'from', matchedAddress: a, snippet: a, score: 10000 + a.length };
      }
      for (const a of (msgAddresses.to || [])) {
        if (addrs.has(a)) return { level: 'address', role: 'recipient', matchedField: 'to', matchedAddress: a, snippet: a, score: 9000 + a.length };
      }
      for (const a of (msgAddresses.cc || [])) {
        if (addrs.has(a)) return { level: 'address', role: 'recipient', matchedField: 'cc', matchedAddress: a, snippet: a, score: 8000 + a.length };
      }
    }
  }
  // ====== LIVELLO 2 — match testuale (menzione, da confermare) ======
  const tokens = _pecBuildSubjectTokens(subj);
  if (!tokens.length) return null;
  const fields = [
    { key: 'mittente', raw: pec.mittente || '' },
    { key: 'destinatari', raw: (Array.isArray(pec.destinatari) && pec.destinatari.length ? pec.destinatari.join(' · ') : (pec.destinatario || '')) },
    { key: 'oggetto', raw: pec.oggetto || '' },
    { key: 'corpoTesto', raw: pec.corpoTesto || '' },
    { key: 'emlBody', raw: emlBody || '' },
  ].filter(f => f.raw && f.raw.trim().length > 0)
   .map(f => ({ ...f, norm: _pecNormalizeText(f.raw) }));
  let best = null;
  for (const f of fields) {
    const m = _pecFindMatchInText(f.raw, f.norm, tokens);
    if (m && (!best || m.token.length > best.token.length)) {
      best = { level: 'mention', matchedField: f.key, token: m.token, snippet: m.snippet, score: m.token.length };
    }
  }
  return best;
}

// Overlay modale di avanzamento riusabile per ricerche lunghe (Trova PEC,
// Trova soggetto). Cattura tutti i click sotto (backdrop a tutto schermo
// con pointer-events:auto) finché l'utente non annulla o la ricerca finisce.
// Ritorna { update(done, label?), close(), isCancelled() } e accetta un
// callback onCancel che la ricerca può ispezionare via flag condiviso.
function _uxProgressOverlay(opts) {
  opts = opts || {};
  // total è ricalcolato dinamicamente al primo update se la funzione che
  // aggiorna il progresso conosce il totale solo dopo la prima iterazione.
  let total = Math.max(1, Number(opts.total || 1));
  const title = opts.title || (t('uxProgressTitle') || 'Operazione in corso…');
  const cancelLabel = t('uxProgressCancel') || 'Annulla';
  const ctrl = { _cancelled: false, _done: false };
  // Rimuovi eventuali overlay precedenti per evitare sovrapposizioni.
  document.querySelectorAll('#uxProgressOverlay').forEach(o => o.remove());
  const ov = document.createElement('div');
  ov.id = 'uxProgressOverlay';
  ov.setAttribute('role', 'dialog');
  ov.setAttribute('aria-modal', 'true');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.55);z-index:99999;display:flex;align-items:center;justify-content:center;pointer-events:auto';
  // Blocca tutti gli eventi sotto: click, keyboard, wheel, touch.
  const stop = e => { e.stopPropagation(); };
  ['click','mousedown','mouseup','keydown','keyup','keypress','wheel','touchstart','touchmove','touchend','contextmenu'].forEach(ev => ov.addEventListener(ev, stop, true));
  ov.innerHTML = `
    <div style="background:#fff;border-radius:10px;min-width:340px;max-width:520px;width:90%;box-shadow:0 20px 50px rgba(0,0,0,.35);overflow:hidden">
      <div style="background:#1e3a8a;color:#fff;padding:12px 16px;font-size:15px;font-weight:600">⏳ ${esc(title)}</div>
      <div style="padding:18px 18px 14px">
        <div id="uxProgLabel" title="" style="font-size:13px;color:#374151;margin-bottom:10px;height:18px;line-height:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%"></div>
        <div style="background:#e5e7eb;border-radius:6px;height:14px;overflow:hidden;border:1px solid #cbd5e1">
          <div id="uxProgBar" style="height:100%;width:0%;background:linear-gradient(90deg,#1e40af,#3b82f6);transition:width .12s ease"></div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:8px;font-size:12px;color:#475569">
          <span id="uxProgPct" data-testid="text-ux-progress-pct">0%</span>
          <span id="uxProgCount" data-testid="text-ux-progress-count">0 / ${total}</span>
        </div>
      </div>
      <div style="padding:10px 16px 14px;display:flex;justify-content:flex-end;border-top:1px solid #e5e7eb;background:#f8fafc">
        <button type="button" id="uxProgCancel" class="btn btn-sm" data-testid="button-ux-progress-cancel" style="background:#fee2e2;color:#991b1b;border:1px solid #fca5a5">✕ ${esc(cancelLabel)}</button>
      </div>
    </div>`;
  document.body.appendChild(ov);
  const $bar = ov.querySelector('#uxProgBar');
  const $pct = ov.querySelector('#uxProgPct');
  const $cnt = ov.querySelector('#uxProgCount');
  const $lbl = ov.querySelector('#uxProgLabel');
  const _closeOverlay = () => {
    if (ctrl._done) return;
    ctrl._done = true;
    try { ov.remove(); } catch (_) {}
  };
  ov.querySelector('#uxProgCancel').onclick = () => {
    ctrl._cancelled = true;
    // Chiudi immediatamente l'overlay alla pressione di Annulla: l'utente
    // non deve attendere il prossimo yield del loop cooperativo.
    _closeOverlay();
    if (typeof opts.onCancel === 'function') { try { opts.onCancel(); } catch (_) {} }
  };
  return {
    update(done, labelOrTotal, maybeLabel) {
      // Firma flessibile: update(done, label) oppure update(done, total, label).
      let label = null;
      if (typeof labelOrTotal === 'number' && labelOrTotal > 0) {
        total = Math.max(1, labelOrTotal);
        label = maybeLabel != null ? maybeLabel : null;
      } else if (labelOrTotal != null) {
        label = labelOrTotal;
      }
      const d = Math.max(0, Math.min(total, Number(done || 0)));
      const pct = Math.round((d / total) * 100);
      $bar.style.width = pct + '%';
      $pct.textContent = pct + '%';
      $cnt.textContent = d + ' / ' + total;
      if (label != null) {
        // Tronca a una sola riga via CSS (white-space:nowrap+ellipsis); il
        // testo completo resta visibile come tooltip al passaggio del mouse.
        const s = String(label);
        $lbl.textContent = s;
        $lbl.title = s;
      }
    },
    close() { _closeOverlay(); },
    isCancelled() { return ctrl._cancelled; },
  };
}
window._uxProgressOverlay = _uxProgressOverlay;

// Toast non bloccante usato al posto di alert() nei flussi finder PEC/Soggetto.
// Si auto-rimuove dopo ~3.5s; type: 'info' | 'warn' | 'error' | 'success'.
function _uxToast(msg, type) {
  try {
    const colors = {
      info:    { bg: '#1e3a8a', fg: '#fff' },
      success: { bg: '#065f46', fg: '#fff' },
      warn:    { bg: '#92400e', fg: '#fff' },
      error:   { bg: '#991b1b', fg: '#fff' },
    };
    const c = colors[type] || colors.info;
    const el = document.createElement('div');
    el.setAttribute('role', 'status');
    el.style.cssText = `position:fixed;top:16px;right:16px;z-index:100000;background:${c.bg};color:${c.fg};padding:10px 14px;border-radius:6px;box-shadow:0 6px 18px rgba(0,0,0,.25);font-size:13px;max-width:420px;line-height:1.4;opacity:0;transition:opacity .15s ease`;
    el.textContent = String(msg || '');
    document.body.appendChild(el);
    requestAnimationFrame(() => { el.style.opacity = '1'; });
    setTimeout(() => {
      el.style.opacity = '0';
      setTimeout(() => { try { el.remove(); } catch (_) {} }, 200);
    }, 3500);
  } catch (_) { /* ignora */ }
}
window._uxToast = _uxToast;

async function _pecFindSubjectCandidates(pecId, opts) {
  // Restituisce un array di candidati [{ subject, matchedField, token, snippet }]
  // per la singola PEC indicata, escludendo i soggetti già collegati.
  // opts = { onProgress(done,total,label?), isCancelled() } per integrazione
  // con _uxProgressOverlay (cancellazione cooperativa + barra di progresso).
  opts = opts || {};
  const onProgress = typeof opts.onProgress === 'function' ? opts.onProgress : null;
  const isCancelled = typeof opts.isCancelled === 'function' ? opts.isCancelled : () => false;
  const pec = await DB.getPecMessage(pecId);
  if (!pec) return { candidates: [], linked: [], cancelled: false };
  const allSubjects = await _pecAllSubjects();
  const alreadyLinked = new Set((pec.soggettiCollegati || []).map(Number));
  const linkedSubjects = allSubjects.filter(s => alreadyLinked.has(s.id));
  const candidatesPool = allSubjects.filter(s => !alreadyLinked.has(s.id));
  if (candidatesPool.length === 0) return { candidates: [], linked: linkedSubjects.map(s => ({ subject: s, level: null })), cancelled: false };

  const totalSteps = candidatesPool.length + linkedSubjects.length + 1; // +1 = lettura .eml
  let stepDone = 0;
  if (onProgress) onProgress(0, totalSteps, t('pecFinderProgressReadingEml') || 'Lettura messaggio .eml…');

  const files = await DB.getEntityFiles('pec', pecId);
  const pecMsgFile = files.find(f => f.fileRole === 'pec_msg');
  const meta = await _pecExtractEmlBodyAndAddresses(pecMsgFile);
  const msgAddresses = _pecBuildMessageAddresses(pec, meta.addresses);
  stepDone++;
  if (onProgress) onProgress(stepDone, totalSteps);

  // Riusa _pecMatchSubjectAgainstPec così la pipeline di matching è
  // la stessa nelle due direzioni (PEC→soggetto e soggetto→PEC).
  const candidates = [];
  for (const subj of candidatesPool) {
    if (isCancelled()) return { candidates: [], linked: [], cancelled: true };
    const m = _pecMatchSubjectAgainstPec(subj, pec, meta.body, msgAddresses);
    if (m) candidates.push({ subject: subj, ...m });
    stepDone++;
    if (onProgress && (stepDone % 5 === 0 || stepDone === totalSteps)) {
      // Tronca il nome soggetto per evitare label che dilatano il modale.
      const sName = _pecSubjectLabel(subj);
      const sShort = sName.length > 40 ? sName.slice(0, 40) + '…' : sName;
      onProgress(stepDone, totalSteps, (t('pecFinderProgressMatching') || 'Confronto soggetti…') + ' ' + sShort);
      // Cedi il thread al browser per ridipingere la barra ogni 5 soggetti.
      await new Promise(r => setTimeout(r, 0));
    }
  }
  // Ordina per score: address (10000+) viene prima di mention (≤lunghezza token).
  candidates.sort((a, b) => (b.score || 0) - (a.score || 0));
  // Per i soggetti già collegati calcola anche il livello, così l'UI può
  // distinguere "già collegato come mittente/destinatario" da "menzione".
  const linkedAnnotated = [];
  for (const subj of linkedSubjects) {
    if (isCancelled()) return { candidates: [], linked: [], cancelled: true };
    const m = _pecMatchSubjectAgainstPec(subj, pec, meta.body, msgAddresses);
    linkedAnnotated.push(m ? { subject: subj, ...m } : { subject: subj, level: null });
    stepDone++;
    if (onProgress && (stepDone % 5 === 0 || stepDone === totalSteps)) {
      onProgress(stepDone, totalSteps);
    }
  }
  if (onProgress) onProgress(totalSteps, totalSteps);
  return { candidates, linked: linkedAnnotated, cancelled: false };
}

// Restituisce un badge HTML che descrive il LIVELLO del match (indirizzo/menzione)
// + il ruolo (mittente/destinatario) o lo snippet/campo per le menzioni.
// Riusabile in entrambi i finder per garantire coerenza visiva.
function _pecLevelBadge(item) {
  if (!item) return '';
  if (item.level === 'address') {
    const roleLabel = item.role === 'sender'
      ? (t('pecFinderRoleSender') || 'mittente')
      : (t('pecFinderRoleRecipient') || 'destinatario');
    const fieldLabel = ({
      from: t('pecFinderFieldFrom') || 'From',
      to: t('pecFinderFieldTo') || 'To',
      cc: t('pecFinderFieldCc') || 'Cc',
    })[item.matchedField] || item.matchedField;
    const certain = t('pecFinderLevelAddress') || 'Indirizzo PEC corrispondente';
    return `<span style="display:inline-block;padding:2px 8px;border-radius:10px;background:#dcfce7;color:#166534;font-size:11px;font-weight:600;border:1px solid #86efac">🟢 ${esc(certain)} · ${esc(roleLabel)} (${esc(fieldLabel)})</span>`;
  }
  if (item.level === 'mention') {
    const mentionLbl = t('pecFinderLevelMention') || 'Menzione testuale (da confermare)';
    return `<span style="display:inline-block;padding:2px 8px;border-radius:10px;background:#fef3c7;color:#92400e;font-size:11px;font-weight:600;border:1px solid #fde68a">🟡 ${esc(mentionLbl)}</span>`;
  }
  return '';
}

function _pecMatchedFieldLabel(key) {
  const map = {
    mittente: t('pecFinderFieldFrom') || 'mittente',
    destinatari: t('pecFinderFieldTo') || 'destinatari',
    oggetto: t('pecFinderFieldSubject') || 'oggetto',
    corpoTesto: t('pecFinderFieldBody') || 'corpo del messaggio',
    emlBody: t('pecFinderFieldEml') || 'testo del file .eml originale',
  };
  return map[key] || key;
}

async function _pecOpenSubjectFinder(pecId) {
  // Apri overlay di progresso che blocca tutta l'UI sotto: qualunque
  // click su pulsanti / sidebar / tabella è ignorato finché la ricerca
  // non termina o l'utente preme Annulla.
  const overlay = _uxProgressOverlay({
    title: t('pecFinderProgressTitle') || 'Ricerca soggetti nella PEC…',
    total: 1, // verrà ricalcolato al primo onProgress
  });
  let result;
  try {
    result = await _pecFindSubjectCandidates(pecId, {
      onProgress: (done, total, label) => overlay.update(done, total, label),
      isCancelled: () => overlay.isCancelled(),
    });
  } catch (e) {
    overlay.close();
    console.error('pec find subjects', e);
    _uxToast((t('pecFinderError') || 'Errore ricerca soggetti') + ': ' + (e.message || e), 'error');
    return;
  }
  overlay.close();
  if (result && result.cancelled) {
    // Annullato dall'utente: nessun alert invasivo, l'overlay si è già chiuso.
    return;
  }
  if (!result || ((!result.candidates || result.candidates.length === 0) && (!result.linked || result.linked.length === 0))) {
    _uxToast(t('pecFinderNoMatch') || 'Nessun soggetto dell\'esponente trovato in questa PEC.', 'info');
    return;
  }
  const { candidates, linked } = result;
  if (!candidates || candidates.length === 0) {
    // Nessun nuovo candidato, ma ci sono già soggetti collegati: avvisalo
    // mostrando comunque la lista informativa.
    if (linked && linked.length > 0) {
      const names = linked.map(s => _pecSubjectLabel(s.subject || s)).join(', ');
      _uxToast((t('pecFinderAllAlreadyLinked') || 'Nessun nuovo soggetto trovato. Già collegati a questa PEC') + ': ' + names, 'info');
      return;
    }
    _uxToast(t('pecFinderNoMatch') || 'Nessun soggetto dell\'esponente trovato in questa PEC.', 'info');
    return;
  }

  // Separa i candidati nei due livelli: address = certo (preselezionato),
  // mention = solo indizio testuale (NON preselezionato di default).
  const certain = candidates.filter(c => c.level === 'address');
  const mentions = candidates.filter(c => c.level === 'mention');

  document.querySelectorAll('#pecSubjFinderOverlay').forEach(o => o.remove());
  const ov = document.createElement('div');
  ov.id = 'pecSubjFinderOverlay';
  ov.className = 'fact-analysis-overlay';
  ov.style.zIndex = '10001';
  const renderRow = (c, preselect) => {
    const addr = c.subject.pec || c.subject.email || '';
    const snippetHtml = c.level === 'address'
      ? `<div style="font-size:12px;color:#374151;margin-top:4px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:4px;padding:6px;font-family:ui-monospace,monospace;word-break:break-all">${esc(c.matchedAddress || c.snippet || '')}</div>`
      : `<div style="font-size:12px;color:#374151;margin-top:4px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:4px;padding:6px;white-space:pre-wrap;word-break:break-word">${_pecRenderSnippetSafe(c.snippet)}</div>`;
    const borderColor = c.level === 'address' ? '#86efac' : '#fde68a';
    return `
    <label style="display:flex;align-items:flex-start;gap:10px;padding:10px;border:1px solid ${borderColor};border-radius:6px;background:#fff;margin-bottom:6px;cursor:pointer" data-testid="row-pec-finder-candidate-${c.subject.id}">
      <input type="checkbox" id="pecFinderChk_${c.subject.id}" data-subj-id="${c.subject.id}"${preselect ? ' checked' : ''} style="margin-top:3px" data-testid="checkbox-pec-finder-${c.subject.id}">
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:600;color:#1e3a8a">👤 ${esc(_pecSubjectLabel(c.subject))}${addr ? ` <span style="font-weight:400;color:#6b7280">· ${esc(addr)}</span>` : ''}</div>
        <div style="margin-top:4px">${_pecLevelBadge(c)}</div>
        ${c.level === 'mention' ? `<div style="font-size:11px;color:#92400e;margin-top:3px">${esc(t('pecFinderFoundIn') || 'trovato in')}: ${esc(_pecMatchedFieldLabel(c.matchedField))}</div>` : ''}
        ${snippetHtml}
      </div>
    </label>`;
  };
  const certainBlock = certain.length > 0
    ? `<div style="margin-bottom:8px;font-size:12px;font-weight:700;color:#166534">🟢 ${esc(t('pecFinderSectionCertain') || 'Match certi per indirizzo PEC')} (${certain.length})</div>${certain.map(c => renderRow(c, true)).join('')}`
    : '';
  const mentionsBlock = mentions.length > 0
    ? `<div style="margin:14px 0 8px;font-size:12px;font-weight:700;color:#92400e">🟡 ${esc(t('pecFinderSectionMentions') || 'Solo menzioni testuali — verifica manualmente')} (${mentions.length})</div>${mentions.map(c => renderRow(c, false)).join('')}`
    : '';
  const rows = certainBlock + mentionsBlock;
  const linkedBlock = linked && linked.length > 0
    ? `<div style="margin-top:14px;padding:10px;background:#f3f4f6;border:1px solid #e5e7eb;border-radius:6px">
        <div style="font-size:11px;color:#6b7280;font-weight:600;margin-bottom:4px">${esc(t('pecFinderAlreadyLinked') || 'Già collegati a questa PEC')}:</div>
        <div style="font-size:12px;color:#374151">${linked.map(l => esc(_pecSubjectLabel(l.subject || l)) + (l.level === 'address' ? ' 🟢' : (l.level === 'mention' ? ' 🟡' : ''))).join(', ')}</div>
      </div>`
    : '';
  ov.innerHTML = `
    <div style="background:#fff;border-radius:8px;max-width:720px;width:92%;max-height:86vh;display:flex;flex-direction:column;box-shadow:0 10px 30px rgba(0,0,0,.25)">
      <div style="background:#1e3a8a;color:#fff;padding:12px 16px;border-radius:8px 8px 0 0;display:flex;justify-content:space-between;align-items:center">
        <h3 style="margin:0;font-size:16px">🔎 ${esc(t('pecFinderTitle') || 'Soggetti suggeriti')}</h3>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('pecSubjFinderOverlay').remove()" data-testid="button-pec-finder-close">✕</button>
      </div>
      <div style="padding:14px 16px;overflow-y:auto;flex:1">
        <div style="font-size:12px;color:#6b7280;margin-bottom:10px">${esc(t('pecFinderHint') || 'Spunta i soggetti che vuoi collegare a questa PEC. Puoi rilanciare questa ricerca in qualunque momento (es. dopo aver aggiunto nuovi soggetti all\'esponente).')}</div>
        ${rows}
        ${linkedBlock}
      </div>
      <div style="padding:12px 16px;border-top:1px solid #e5e7eb;display:flex;gap:8px;justify-content:flex-end">
        <button class="btn btn-sm" onclick="document.getElementById('pecSubjFinderOverlay').remove()" data-testid="button-pec-finder-cancel">${esc(t('cancel') || 'Annulla')}</button>
        <button class="btn btn-sm btn-primary" style="background:#1e3a8a;color:#fff" onclick="_pecConfirmSubjectFinder(${pecId})" data-testid="button-pec-finder-confirm">✅ ${esc(t('pecFinderConfirm') || 'Collega selezionati')}</button>
      </div>
    </div>
  `;
  document.body.appendChild(ov);
}

async function _pecConfirmSubjectFinder(pecId) {
  const ov = document.getElementById('pecSubjFinderOverlay');
  if (!ov) return;
  const ids = Array.from(ov.querySelectorAll('input[type="checkbox"][data-subj-id]:checked'))
    .map(el => parseInt(el.getAttribute('data-subj-id'), 10))
    .filter(n => !isNaN(n));
  if (ids.length === 0) {
    ov.remove();
    return;
  }
  const pec = await DB.getPecMessage(pecId);
  if (!pec) { ov.remove(); return; }
  const current = Array.isArray(pec.soggettiCollegati) ? pec.soggettiCollegati.map(Number) : [];
  const merged = Array.from(new Set([...current, ...ids]));
  await DB.updatePecMessage(pecId, { soggettiCollegati: merged });
  ov.remove();
  await _pecShowDetail(pecId);
  _uxToast((t('pecFinderLinked') || 'Soggetti collegati') + ': ' + ids.length, 'success');
}

window._pecOpenSubjectFinder = _pecOpenSubjectFinder;

// =====================================================================
// Trova PEC dal soggetto (duale di _pecOpenSubjectFinder).
// Cerca tra TUTTE le PEC archiviate quelle che menzionano il soggetto
// (mittente, destinatari, oggetto, corpo, .eml originale) e propone
// all'utente di collegarle al soggetto corrente. Riusa la stessa
// pipeline di matching del finder PEC→soggetto per coerenza simmetrica.
// =====================================================================
async function _subjectFindPecs(subjectId, opts) {
  // opts = { onProgress(done,total,label?), isCancelled() } per integrazione
  // con _uxProgressOverlay. La lettura di tutti i .eml dell'archivio è
  // l'operazione più lenta dell'app: il progresso viene aggiornato a ogni
  // PEC analizzata e il loop cede il thread al browser ogni messaggio.
  opts = opts || {};
  const onProgress = typeof opts.onProgress === 'function' ? opts.onProgress : null;
  const isCancelled = typeof opts.isCancelled === 'function' ? opts.isCancelled : () => false;
  const subj = await DB.getSubject(subjectId);
  if (!subj) return { candidates: [], linked: [], cancelled: false };
  let allPecs = [];
  try { allPecs = await DB.getPecMessages(); } catch (_) { allPecs = []; }
  const total = Math.max(1, allPecs.length);
  if (onProgress) onProgress(0, total, t('subjectFinderProgressLoading') || 'Lettura archivio PEC…');
  const candidates = [];
  const linked = [];
  let i = 0;
  for (const pec of allPecs) {
    if (isCancelled()) return { candidates: [], linked: [], cancelled: true };
    const linkedIds = Array.isArray(pec.soggettiCollegati) ? pec.soggettiCollegati.map(Number) : [];
    const isLinked = linkedIds.includes(Number(subjectId));
    let meta = { body: '', addresses: { from: [], to: [], cc: [] } };
    try {
      const files = await DB.getEntityFiles('pec', pec.id);
      const pecMsgFile = files.find(f => f.fileRole === 'pec_msg');
      meta = await _pecExtractEmlBodyAndAddresses(pecMsgFile);
    } catch (_) {}
    const msgAddresses = _pecBuildMessageAddresses(pec, meta.addresses);
    const m = _pecMatchSubjectAgainstPec(subj, pec, meta.body, msgAddresses);
    if (m) {
      if (isLinked) linked.push({ pec, ...m });
      else candidates.push({ pec, ...m });
    }
    i++;
    if (onProgress) {
      // Label volutamente corta: il modale è 520px max e il CSS tronca con
      // ellipsis, ma riduciamo comunque l'oggetto a 40 char per evitare che
      // un soggetto lunghissimo occupi tutto lo spazio anche nel tooltip.
      const ogg = pec.oggetto ? (pec.oggetto.length > 40 ? pec.oggetto.slice(0, 40) + '…' : pec.oggetto) : '';
      const lbl = (t('subjectFinderProgressAnalyzing') || 'Analisi PEC') + ' ' + i + ' / ' + total + (ogg ? ' — ' + ogg : '');
      onProgress(i, total, lbl);
    }
    // Cedi il thread al browser ogni 2 PEC analizzate, per ridipingere
    // la barra e processare un eventuale click su Annulla senza congelarsi.
    if (i % 2 === 0) await new Promise(r => setTimeout(r, 0));
  }
  candidates.sort((a, b) => (b.score || 0) - (a.score || 0));
  linked.sort((a, b) => (b.score || 0) - (a.score || 0));
  return { candidates, linked, cancelled: false };
}

function _subjectPecRowLabel(pec) {
  const subj = (pec.oggetto || '').trim() || (t('pecNoSubject') || '(senza oggetto)');
  const date = (pec.dataInvio || '').trim();
  const from = (pec.mittente || '').trim();
  return { subj, date, from };
}

async function _subjectOpenPecFinder(subjectId) {
  // Apri overlay di progresso che blocca tutta l'UI sotto durante la
  // lettura di tutti i .eml dell'archivio (operazione potenzialmente
  // lunga). Il pulsante Annulla interrompe il loop in modo cooperativo.
  const overlay = _uxProgressOverlay({
    title: t('subjectFinderProgressTitle') || 'Ricerca PEC che menzionano il soggetto…',
    total: 1,
  });
  let result;
  try {
    result = await _subjectFindPecs(subjectId, {
      onProgress: (done, total, label) => overlay.update(done, total, label),
      isCancelled: () => overlay.isCancelled(),
    });
  } catch (e) {
    overlay.close();
    console.error('subject find pecs', e);
    _uxToast((t('subjectFinderPecError') || 'Errore ricerca PEC') + ': ' + (e.message || e), 'error');
    return;
  }
  overlay.close();
  if (result && result.cancelled) {
    // Annullato dall'utente: nessun alert.
    return;
  }
  const { candidates, linked } = result;
  if ((!candidates || candidates.length === 0) && (!linked || linked.length === 0)) {
    _uxToast(t('subjectFinderPecNoMatch') || 'Nessuna PEC archiviata risulta menzionare questo soggetto.', 'info');
    return;
  }
  if (!candidates || candidates.length === 0) {
    if (linked && linked.length > 0) {
      _uxToast((t('subjectFinderPecAllAlreadyLinked') || 'Nessuna nuova PEC trovata. PEC già collegate a questo soggetto') + ': ' + linked.length, 'info');
      return;
    }
    _uxToast(t('subjectFinderPecNoMatch') || 'Nessuna PEC archiviata risulta menzionare questo soggetto.', 'info');
    return;
  }

  // Separa nei due livelli: address = certo (preselezionato),
  // mention = solo indizio testuale (NON preselezionato).
  const certain = candidates.filter(c => c.level === 'address');
  const mentions = candidates.filter(c => c.level === 'mention');

  document.querySelectorAll('#subjPecFinderOverlay').forEach(o => o.remove());
  const ov = document.createElement('div');
  ov.id = 'subjPecFinderOverlay';
  ov.className = 'fact-analysis-overlay';
  ov.style.zIndex = '10001';
  const renderRow = (c, preselect) => {
    const { subj, date, from } = _subjectPecRowLabel(c.pec);
    const snippetHtml = c.level === 'address'
      ? `<div style="font-size:12px;color:#374151;margin-top:4px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:4px;padding:6px;font-family:ui-monospace,monospace;word-break:break-all">${esc(c.matchedAddress || c.snippet || '')}</div>`
      : `<div style="font-size:12px;color:#374151;margin-top:4px;background:#f8fafc;border:1px solid #e5e7eb;border-radius:4px;padding:6px;white-space:pre-wrap;word-break:break-word">${_pecRenderSnippetSafe(c.snippet)}</div>`;
    const borderColor = c.level === 'address' ? '#86efac' : '#fde68a';
    return `
    <label style="display:flex;align-items:flex-start;gap:10px;padding:10px;border:1px solid ${borderColor};border-radius:6px;background:#fff;margin-bottom:6px;cursor:pointer" data-testid="row-subj-finder-pec-${c.pec.id}">
      <input type="checkbox" data-pec-id="${c.pec.id}"${preselect ? ' checked' : ''} style="margin-top:3px" data-testid="checkbox-subj-finder-pec-${c.pec.id}">
      <div style="flex:1;min-width:0">
        <div style="font-size:13px;font-weight:600;color:#1e3a8a">📧 ${esc(subj)}</div>
        <div style="font-size:11px;color:#374151;margin-top:2px">${esc(date || '—')}${from ? ' · ' + esc(from) : ''}</div>
        <div style="margin-top:4px">${_pecLevelBadge(c)}</div>
        ${c.level === 'mention' ? `<div style="font-size:11px;color:#92400e;margin-top:3px">${esc(t('subjectFinderPecFoundIn') || 'trovato in')}: ${esc(_pecMatchedFieldLabel(c.matchedField))}</div>` : ''}
        ${snippetHtml}
      </div>
    </label>`;
  };
  const certainBlock = certain.length > 0
    ? `<div style="margin-bottom:8px;font-size:12px;font-weight:700;color:#166534">🟢 ${esc(t('subjectFinderSectionCertain') || 'Match certi per indirizzo PEC')} (${certain.length})</div>${certain.map(c => renderRow(c, true)).join('')}`
    : '';
  const mentionsBlock = mentions.length > 0
    ? `<div style="margin:14px 0 8px;font-size:12px;font-weight:700;color:#92400e">🟡 ${esc(t('subjectFinderSectionMentions') || 'Solo menzioni testuali — verifica manualmente')} (${mentions.length})</div>${mentions.map(c => renderRow(c, false)).join('')}`
    : '';
  const rows = certainBlock + mentionsBlock;
  const linkedBlock = linked && linked.length > 0
    ? `<div style="margin-top:14px;padding:10px;background:#f3f4f6;border:1px solid #e5e7eb;border-radius:6px">
        <div style="font-size:11px;color:#6b7280;font-weight:600;margin-bottom:4px">${esc(t('subjectFinderPecAlreadyLinked') || 'Già collegate a questo soggetto')} (${linked.length}):</div>
        <div style="font-size:12px;color:#374151">${linked.map(l => {
          const { subj, date } = _subjectPecRowLabel(l.pec);
          return `📧 ${esc(subj)}${date ? ' (' + esc(date) + ')' : ''}`;
        }).join(' · ')}</div>
      </div>`
    : '';
  ov.innerHTML = `
    <div style="background:#fff;border-radius:8px;max-width:760px;width:92%;max-height:86vh;display:flex;flex-direction:column;box-shadow:0 10px 30px rgba(0,0,0,.25)">
      <div style="background:#1e3a8a;color:#fff;padding:12px 16px;border-radius:8px 8px 0 0;display:flex;justify-content:space-between;align-items:center">
        <h3 style="margin:0;font-size:16px">🔎 ${esc(t('subjectFinderPecTitle') || 'PEC suggerite per questo soggetto')}</h3>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('subjPecFinderOverlay').remove()" data-testid="button-subj-finder-pec-close">✕</button>
      </div>
      <div style="padding:14px 16px;overflow-y:auto;flex:1">
        <div style="font-size:12px;color:#6b7280;margin-bottom:10px">${esc(t('subjectFinderPecHint') || 'Spunta le PEC che vuoi collegare a questo soggetto. Puoi rilanciare questa ricerca in qualunque momento (es. dopo aver archiviato nuove PEC).')}</div>
        ${rows}
        ${linkedBlock}
      </div>
      <div style="padding:12px 16px;border-top:1px solid #e5e7eb;display:flex;gap:8px;justify-content:flex-end">
        <button class="btn btn-sm" onclick="document.getElementById('subjPecFinderOverlay').remove()" data-testid="button-subj-finder-pec-cancel">${esc(t('cancel') || 'Annulla')}</button>
        <button class="btn btn-sm btn-primary" style="background:#1e3a8a;color:#fff" onclick="_subjectConfirmPecFinder(${subjectId})" data-testid="button-subj-finder-pec-confirm">✅ ${esc(t('subjectFinderPecConfirm') || 'Collega selezionate')}</button>
      </div>
    </div>
  `;
  document.body.appendChild(ov);
}

async function _subjectConfirmPecFinder(subjectId) {
  const ov = document.getElementById('subjPecFinderOverlay');
  if (!ov) return;
  const ids = Array.from(ov.querySelectorAll('input[type="checkbox"][data-pec-id]:checked'))
    .map(el => parseInt(el.getAttribute('data-pec-id'), 10))
    .filter(n => !isNaN(n));
  if (ids.length === 0) { ov.remove(); return; }
  const sid = Number(subjectId);
  let updated = 0;
  for (const pecId of ids) {
    try {
      const pec = await DB.getPecMessage(pecId);
      if (!pec) continue;
      const current = Array.isArray(pec.soggettiCollegati) ? pec.soggettiCollegati.map(Number) : [];
      if (current.includes(sid)) continue;
      const merged = Array.from(new Set([...current, sid]));
      await DB.updatePecMessage(pecId, { soggettiCollegati: merged });
      updated++;
    } catch (e) { console.warn('link pec to subject failed', pecId, e); }
  }
  ov.remove();
  // Refresh del dettaglio soggetto: il blocco "PEC collegate" mostra una
  // lista filtrata da `pec.soggettiCollegati` ma non si aggiorna da sola
  // dopo il save dal finder. Lo ri-renderiamo se è presente nel DOM,
  // così le PEC appena collegate appaiono senza dover chiudere/riaprire.
  try {
    if (document.getElementById('subjectPecCollegate') && typeof _renderSubjectPecCollegate === 'function') {
      // Questa funzione viene invocata dal finder PEC nel form di modifica
      // soggetto: ri-renderizza con i pulsanti Scollega visibili.
      await _renderSubjectPecCollegate(sid, { mode: 'edit' });
    }
  } catch (e) { console.warn('refresh subject pec block failed', e); }
  _uxToast((t('subjectFinderPecLinked') || 'PEC collegate al soggetto') + ': ' + updated, 'success');
}

window._subjectOpenPecFinder = _subjectOpenPecFinder;
window._subjectConfirmPecFinder = _subjectConfirmPecFinder;
window._pecToggleDetailView = _pecToggleDetailView;
window._pecRenderOriginalMessageView = _pecRenderOriginalMessageView;

// Task #194: handler globali per il download/anteprima degli allegati estratti
// dal postacert.eml. Leggono dal cache _pecMsgAttCache popolato da
// _pecRenderOriginalMessageView.
window._pecMsgAttDownload = function (pecId, idx) {
  try {
    const cache = (window._pecMsgAttCache || {})[pecId] || [];
    const a = cache[idx];
    if (!a) return;
    const blob = new Blob([a.bytes], { type: a.contentType || 'application/octet-stream' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = a.filename || ('allegato_' + (idx + 1));
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setTimeout(() => URL.revokeObjectURL(url), 60000);
  } catch (e) { console.warn('attach download', e); }
};

window._pecMsgAttPreview = function (pecId, idx) {
  try {
    const cache = (window._pecMsgAttCache || {})[pecId] || [];
    const a = cache[idx];
    if (!a) return;
    const escH = s => (s == null ? '' : String(s).replace(/[<>&"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c])));
    const ct = (a.contentType || '').toLowerCase();
    const fn = (a.filename || '').toLowerCase();
    const blob = new Blob([a.bytes], { type: a.contentType || 'application/octet-stream' });
    const url = URL.createObjectURL(blob);

    let inner = '';
    if (ct.startsWith('image/') || /\.(png|jpe?g|gif|bmp|webp|svg)$/.test(fn)) {
      inner = `<img src="${url}" style="max-width:100%;max-height:100%;object-fit:contain;display:block;margin:auto" alt="${escH(a.filename)}" data-testid="img-pec-att-preview"/>`;
    } else if (ct === 'application/pdf' || fn.endsWith('.pdf')) {
      inner = `<iframe src="${url}" style="width:100%;height:100%;border:none;background:#fff" data-testid="iframe-pec-att-preview"></iframe>`;
    } else if (ct.startsWith('text/') || ct === 'application/json' || ct === 'application/xml' || /\.(txt|log|csv|json|xml|md)$/.test(fn)) {
      try {
        const txt = new TextDecoder('utf-8', { fatal: false }).decode(a.bytes);
        inner = `<pre style="white-space:pre-wrap;word-break:break-word;font-family:ui-monospace,monospace;font-size:13px;background:#fff;color:#111;padding:14px;margin:0;height:100%;overflow:auto;box-sizing:border-box" data-testid="text-pec-att-preview">${escH(txt)}</pre>`;
      } catch (_) {
        inner = `<div style="padding:20px;color:#dc2626">${escH(t('pecMsgViewPreviewError') || 'Impossibile decodificare il contenuto come testo')}</div>`;
      }
    } else if (ct === 'text/html' || /\.html?$/.test(fn)) {
      // sandboxed: no scripts, no top-navigation
      try {
        const html = new TextDecoder('utf-8', { fatal: false }).decode(a.bytes);
        const safe = (typeof _emlSanitizeHtml === 'function') ? _emlSanitizeHtml(html) : html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
        inner = `<iframe sandbox="" srcdoc="${escH('<style>body{font-family:sans-serif;font-size:14px;color:#111;margin:14px;line-height:1.5}img{max-width:100%}a{color:#1e40af}</style>' + safe)}" style="width:100%;height:100%;border:none;background:#fff" data-testid="iframe-pec-att-preview-html"></iframe>`;
      } catch (_) {
        inner = `<div style="padding:20px;color:#dc2626">${escH(t('pecMsgViewPreviewError') || 'Impossibile decodificare il contenuto come HTML')}</div>`;
      }
    } else {
      URL.revokeObjectURL(url);
      alert((t('pecMsgViewPreviewUnavailable') || 'Anteprima non disponibile per questo tipo di file. Usa il bottone Scarica.'));
      return;
    }

    // Modale standard dell'app, stessa struttura usata da openFilePreviewModal
    // (header gradient, overlay scuro, classi .modal-overlay/.modal-content).
    const overlay = document.createElement('div');
    overlay.id = 'pecMsgAttPreviewOverlay';
    overlay.className = 'modal-overlay';
    overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.6);z-index:10010;display:flex;align-items:center;justify-content:center';

    const modal = document.createElement('div');
    modal.className = 'modal-content';
    modal.style.cssText = 'width:92vw;max-width:1100px;height:90vh;overflow:hidden;padding:0;border-radius:12px;box-shadow:0 20px 60px rgba(0,0,0,0.35);display:flex;flex-direction:column';

    const sizeKb = (a.bytes.length / 1024).toFixed(1);
    modal.innerHTML = `
      <div class="amf-gradient-header" style="border-radius:12px 12px 0 0;flex-shrink:0;margin:0;padding:8px 14px">
        <h3 style="display:flex;align-items:center;gap:8px;min-width:0;overflow:hidden;font-size:13px">
          <span style="background:#dbeafe;color:#1e40af;border-radius:4px;padding:2px 7px;font-size:11px;font-weight:700;flex-shrink:0">📎</span>
          <span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px">${escH(a.filename)} <span style="font-weight:400;color:#cbd5e1;font-size:11px">(${sizeKb} KB · ${escH(a.contentType || '')})</span></span>
        </h3>
        <div class="header-actions" style="gap:6px">
          <button class="btn btn-sm" onclick="_pecMsgAttDownload(${pecId},${idx})" data-testid="button-pec-att-preview-download">${escH(t('download') || 'Scarica')}</button>
          <button class="btn btn-sm" id="btnPecAttPrevClose" data-testid="button-pec-att-preview-close">${escH(t('close') || 'Chiudi')}</button>
        </div>
      </div>
      <div style="flex:1;min-height:0;overflow:hidden;padding:8px;display:flex;flex-direction:column;background:#f3f4f6">
        <div style="flex:1;min-height:0;display:flex;flex-direction:column" class="fp-modal-body-wrap">${inner}</div>
      </div>
    `;

    const closeAndCleanup = () => {
      overlay.remove();
      setTimeout(() => { try { URL.revokeObjectURL(url); } catch (_) {} }, 500);
    };
    modal.querySelector('#btnPecAttPrevClose').onclick = closeAndCleanup;
    overlay.addEventListener('click', e => { if (e.target === overlay) closeAndCleanup(); });
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
  } catch (e) {
    console.warn('attach preview', e);
    alert((t('pecMsgViewPreviewError') || 'Errore anteprima allegato') + ': ' + (e.message || e));
  }
};
window._pecConfirmSubjectFinder = _pecConfirmSubjectFinder;

const _PEC_ACT_ROLES = ['pec_msg', 'pec_attach'];
const _PEC_PROOF_ROLES = ['pec_acc', 'pec_del'];

async function _pecClonePecFilesAsPointers(pecId, entityType, entityId, lang, hierarchy, roles) {
  const srcFiles = await DB.getEntityFiles('pec', pecId);
  for (const sf of srcFiles) {
    if (roles && !roles.includes(sf.fileRole)) continue;
    const ptr = {
      entityType,
      entityId,
      lang,
      actId: entityType === 'act' ? entityId : 0,
      caseId: hierarchy.caseId || null,
      proceedingId: hierarchy.proceedingId || null,
      dossierId: hierarchy.dossierId || null,
      fileName: sf.fileName,
      fileSize: sf.fileSize,
      fileType: sf.fileType,
      hash: sf.hash,
      storagePath: sf.storagePath,
      diskFileName: sf.diskFileName,
      blob: null,
      sourceFileId: sf.id,
      fileRole: sf.fileRole,
      createdAt: sf.createdAt || new Date().toISOString(),
    };
    await DB.createFile(ptr);
  }
}

async function _pecCreateFromMessage(pecId, factId, mode, lang) {
  const pec = await DB.getPecMessage(pecId);
  if (!pec) return;
  const fact = await DB.getFact(factId);
  const dossierId = fact ? fact.dossierId : null;
  const hierarchy = { dossierId };
  if (dossierId) {
    const dos = await DB.getDossier(dossierId);
    if (dos) {
      hierarchy.proceedingId = dos.proceedingId;
      const pr = await DB.getProceeding(dos.proceedingId);
      if (pr) hierarchy.caseId = pr.caseId;
    }
  }
  const titleBase = (pec.oggetto || 'PEC').slice(0, 120);
  const desc = lang === 'it'
    ? `Mittente: ${pec.mittente}\nDestinatario: ${(pec.destinatari || [pec.destinatario]).join('; ')}\nData invio: ${pec.dataInvio}\n${pec.dataAccettazione ? 'Accettazione: ' + pec.dataAccettazione + '\n' : ''}${pec.dataConsegna ? 'Consegna: ' + pec.dataConsegna + '\n' : ''}\n${pec.corpoTesto || pec.note || ''}`
    : `Sender: ${pec.mittente}\nRecipient: ${(pec.destinatari || [pec.destinatario]).join('; ')}\nSent: ${pec.dataInvio}\n${pec.dataAccettazione ? 'Accepted: ' + pec.dataAccettazione + '\n' : ''}${pec.dataConsegna ? 'Delivered: ' + pec.dataConsegna + '\n' : ''}\n${pec.corpoTesto || pec.note || ''}`;

  // Import PEC: factId mantenuto per coerenza di contesto (refresh UI,
  // file hierarchy), ma _skipFactRelation:true assicura che atti e prove
  // creati nascano ORFANI. L'utente collega esplicitamente tramite
  // drag-and-drop (handler app.js ~11711 atti, ~11720 prove).
  if (mode === 'act' || mode === 'both') {
    const actData = {
      factId, dossierId,
      _skipFactRelation: true,
      _isFromDossier: false,
      type: 'altro', subtype: null,
      authority: pec.mittente || '', authorityRole: 'PEC',
      titleIt: lang === 'it' ? `[PEC] ${titleBase}` : null,
      titleEn: lang === 'en' ? `[PEC] ${titleBase}` : null,
      descriptionIt: lang === 'it' ? desc : null,
      descriptionEn: lang === 'en' ? desc : null,
      dataAtto: pec.dataInvio ? pec.dataInvio.slice(0, 10) : null,
    };
    const newAct = await DB.createAct(actData);
    await _pecClonePecFilesAsPointers(pecId, 'act', newAct.id, lang, hierarchy, _PEC_ACT_ROLES);
  }
  if (mode === 'proof' || mode === 'both') {
    const proofData = {
      factId,
      _skipFactRelation: true,
      mediaType: 'document',
      titleIt: lang === 'it' ? `[PEC ricevute] ${titleBase}` : null,
      titleEn: lang === 'en' ? `[PEC receipts] ${titleBase}` : null,
      descriptionIt: lang === 'it' ? desc : null,
      descriptionEn: lang === 'en' ? desc : null,
      sourceLabel: pec.mittente || '',
      acquisitionDate: pec.dataConsegna || pec.dataAccettazione || pec.dataInvio,
    };
    const newProof = await DB.createProof(proofData);
    await _pecClonePecFilesAsPointers(pecId, 'proof', newProof.id, lang, hierarchy, _PEC_PROOF_ROLES);
  }
  document.getElementById('pecPickerOverlay').remove();
  if (typeof _updateActsColumn === 'function' && (mode === 'act' || mode === 'both')) await _updateActsColumn(factId);
  if (typeof _updateProofsColumn === 'function' && (mode === 'proof' || mode === 'both')) await _updateProofsColumn(factId);
  if (typeof _decoratePecBadges === 'function') setTimeout(_decoratePecBadges, 200);
}

// Trova la PEC sorgente di un'entità (atto/prova) — ritorna pecId o null
async function _pecFindSourceFor(entityType, entityId) {
  const myFiles = await DB.getEntityFiles(entityType, entityId);
  for (const f of myFiles) {
    if (f.sourceFileId == null) continue;
    const src = await DB.getFile ? await DB.getFile(f.sourceFileId) : null;
    if (src && src.entityType === 'pec') return src.entityId;
  }
  // fallback via Dexie diretto
  for (const f of myFiles) {
    if (f.sourceFileId == null) continue;
    const src = await db.files.get(f.sourceFileId);
    if (src && src.entityType === 'pec') return src.entityId;
  }
  return null;
}

async function _pecOpenFromBadge(entityType, entityId) {
  const pecId = await _pecFindSourceFor(entityType, entityId);
  if (pecId == null) return;
  await openArchivioPecModal();
  setTimeout(() => _pecShowDetail(pecId), 150);
}

// ---------- Badge "📧 Da archivio PEC" su card atti/prove ----------
async function _decoratePecBadges() {
  const cards = document.querySelectorAll('[data-testid^="card-act-"], [data-testid^="card-proof-"], [data-testid^="amf-act-"], [data-testid^="amf-proof-"]');
  for (const card of cards) {
    if (card.querySelector('.pec-source-badge')) continue;
    const tid = card.getAttribute('data-testid') || '';
    const m = tid.match(/-(\d+)$/);
    if (!m) continue;
    const id = parseInt(m[1], 10);
    const isAct = tid.includes('act');
    const entityType = isAct ? 'act' : 'proof';
    const has = await DB.getEntityHasPecSource(entityType, id);
    if (has) {
      const badge = document.createElement('span');
      badge.className = 'pec-source-badge';
      badge.style.cssText = 'display:inline-block;background:#2563eb;color:#fff;font-size:10px;font-weight:600;padding:2px 6px;border-radius:4px;margin-left:6px;cursor:pointer';
      badge.title = t('badgeFromPecTitle') || 'Apri PEC sorgente nell\'archivio';
      badge.textContent = '📧 ' + (t('badgeFromPec') || 'Da archivio PEC');
      badge.onclick = (e) => { e.stopPropagation(); _pecOpenFromBadge(entityType, id); };
      const target = card.querySelector('strong, .card-title, h4, b') || card.firstElementChild || card;
      target.appendChild(badge);
    }
  }
}

window.openArchivioPecModal = openArchivioPecModal;
window._pecShowForm = _pecShowForm;
window._pecSaveForm = _pecSaveForm;

// =================== Parsing file .eml ===================
function _emlDecodeMimeWord(s) {
  if (!s) return '';
  // join encoded words separated solo da whitespace (RFC 2047)
  s = s.replace(/\?=\s+=\?/g, '?==?');
  return s.replace(/=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g, (m, charset, enc, txt) => {
    try {
      let bytes;
      if (enc === 'B' || enc === 'b') {
        const bin = atob(txt.replace(/\s+/g, ''));
        bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      } else {
        txt = txt.replace(/_/g, ' ');
        const out = [];
        for (let i = 0; i < txt.length; i++) {
          if (txt[i] === '=' && i + 2 < txt.length) {
            const h = txt.substr(i + 1, 2);
            if (/^[0-9A-Fa-f]{2}$/.test(h)) { out.push(parseInt(h, 16)); i += 2; continue; }
          }
          out.push(txt.charCodeAt(i) & 0xff);
        }
        bytes = new Uint8Array(out);
      }
      return new TextDecoder((charset || 'utf-8').toLowerCase().replace(/^"|"$/g, '')).decode(bytes);
    } catch (e) { return m; }
  });
}

function _emlParseHeaders(headerText) {
  const lines = headerText.split(/\r?\n/);
  const headers = [];
  let cur = null;
  for (const ln of lines) {
    if (/^[ \t]/.test(ln) && cur) {
      cur.value += ' ' + ln.replace(/^\s+/, '');
    } else if (ln) {
      const idx = ln.indexOf(':');
      if (idx > 0) {
        cur = { name: ln.slice(0, idx).trim().toLowerCase(), value: ln.slice(idx + 1).trim() };
        headers.push(cur);
      }
    }
  }
  return headers;
}

function _emlGetHeader(headers, name) {
  const h = headers.find(x => x.name === name.toLowerCase());
  return h ? h.value : null;
}

function _emlParseHeaderParams(value) {
  if (!value) return { type: '', params: {} };
  const parts = value.split(';');
  const type = (parts.shift() || '').trim().toLowerCase();
  const params = {};
  for (const p of parts) {
    const eq = p.indexOf('=');
    if (eq > 0) {
      const k = p.slice(0, eq).trim().toLowerCase();
      let v = p.slice(eq + 1).trim();
      if (v.startsWith('"') && v.endsWith('"')) v = v.slice(1, -1);
      params[k] = v;
    }
  }
  return { type, params };
}

function _emlDecodeQP(s) {
  s = s.replace(/=\r?\n/g, '');
  const out = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '=' && i + 2 < s.length) {
      const h = s.substr(i + 1, 2);
      if (/^[0-9A-Fa-f]{2}$/.test(h)) { out.push(parseInt(h, 16)); i += 2; continue; }
    }
    out.push(s.charCodeAt(i) & 0xff);
  }
  return new Uint8Array(out);
}

function _emlDecodeBase64(s) {
  s = s.replace(/[^A-Za-z0-9+/=]/g, '');
  try {
    const bin = atob(s);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  } catch (e) { return new Uint8Array(0); }
}

function _emlDecodeBody(rawBody, encoding) {
  encoding = (encoding || '7bit').toLowerCase().trim();
  if (encoding === 'base64') return _emlDecodeBase64(rawBody);
  if (encoding === 'quoted-printable') return _emlDecodeQP(rawBody);
  const bytes = new Uint8Array(rawBody.length);
  for (let i = 0; i < rawBody.length; i++) bytes[i] = rawBody.charCodeAt(i) & 0xff;
  return bytes;
}

function _emlSplitParts(body, boundary) {
  const delim = '--' + boundary;
  const parts = [];
  let idx = body.indexOf(delim);
  if (idx < 0) return parts;
  while (true) {
    let s = idx + delim.length;
    if (body.substr(s, 2) === '--') break;
    if (body[s] === '\r') s++;
    if (body[s] === '\n') s++;
    const next = body.indexOf(delim, s);
    if (next < 0) break;
    let part = body.slice(s, next);
    if (part.endsWith('\r\n')) part = part.slice(0, -2);
    else if (part.endsWith('\n')) part = part.slice(0, -1);
    parts.push(part);
    idx = next;
  }
  return parts;
}

function _emlParsePart(raw) {
  let sep = raw.indexOf('\r\n\r\n');
  let sepLen = 4;
  if (sep < 0) { sep = raw.indexOf('\n\n'); sepLen = 2; }
  const headerText = sep < 0 ? raw : raw.slice(0, sep);
  const bodyText = sep < 0 ? '' : raw.slice(sep + sepLen);
  const headers = _emlParseHeaders(headerText);
  const ct = _emlParseHeaderParams(_emlGetHeader(headers, 'content-type') || 'text/plain');
  const cte = _emlGetHeader(headers, 'content-transfer-encoding');
  const cd = _emlParseHeaderParams(_emlGetHeader(headers, 'content-disposition') || '');
  const filenameRaw = cd.params.filename || ct.params.name || null;
  const filename = filenameRaw ? _emlDecodeMimeWord(filenameRaw) : null;
  const node = {
    headers, contentType: ct.type || 'text/plain', params: ct.params,
    encoding: cte, disposition: cd.type || null, filename,
    parts: null, bodyBytes: null,
  };
  if (node.contentType.startsWith('multipart/') && ct.params.boundary) {
    node.parts = _emlSplitParts(bodyText, ct.params.boundary).map(_emlParsePart);
  } else {
    node.bodyBytes = _emlDecodeBody(bodyText, cte);
  }
  return node;
}

function _emlBytesToText(bytes, charset) {
  try { return new TextDecoder((charset || 'utf-8').toLowerCase()).decode(bytes); }
  catch (e) { return new TextDecoder('utf-8').decode(bytes); }
}

function _emlExtract(node, out) {
  out = out || { textPlain: '', textHtml: '', attachments: [] };
  if (node.parts) {
    if (node.contentType === 'multipart/alternative') {
      const plain = node.parts.find(p => p.contentType === 'text/plain' && !p.filename);
      const html = node.parts.find(p => p.contentType === 'text/html' && !p.filename);
      if (plain) _emlExtract(plain, out);
      else if (html) _emlExtract(html, out);
      for (const p of node.parts) {
        if (p === plain || p === html) continue;
        _emlExtract(p, out);
      }
    } else {
      for (const p of node.parts) _emlExtract(p, out);
    }
    return out;
  }
  if (!node.bodyBytes) return out;
  const charset = node.params.charset;
  const isAttachment = node.filename || node.disposition === 'attachment';
  if (isAttachment) {
    out.attachments.push({
      filename: node.filename || ('allegato-' + (out.attachments.length + 1)),
      contentType: node.contentType || 'application/octet-stream',
      bytes: node.bodyBytes,
    });
  } else if (node.contentType === 'text/plain' && !out.textPlain) {
    out.textPlain = _emlBytesToText(node.bodyBytes, charset);
  } else if (node.contentType === 'text/html' && !out.textHtml) {
    out.textHtml = _emlBytesToText(node.bodyBytes, charset);
  } else if (node.contentType && !node.contentType.startsWith('text/')) {
    out.attachments.push({
      filename: 'parte-' + (out.attachments.length + 1),
      contentType: node.contentType,
      bytes: node.bodyBytes,
    });
  }
  return out;
}

function _emlParseDate(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return '';
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function _emlExtractAddresses(field) {
  if (!field) return [];
  return field.split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/)
    .map(p => {
      const m = p.match(/<([^>]+)>/);
      return (m ? m[1] : p).trim();
    })
    .filter(Boolean);
}

function _pecHtmlToText(html) {
  try {
    const tmp = document.createElement('div');
    tmp.innerHTML = html.replace(/<\s*(br|\/p|\/div|\/li|\/tr)[^>]*>/gi, '\n');
    return (tmp.textContent || tmp.innerText || '').replace(/\n{3,}/g, '\n\n').trim();
  } catch (e) { return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); }
}

// =====================================================================
// CFB (Compound File Binary) reader + minimal Outlook .msg parser.
// Implements just what's needed to extract sender/recipients/subject/date/
// body/attachments from a top-level .msg file (no embedded messages).
// =====================================================================
function _msgReadCFB(buf) {
  const dv = new DataView(buf);
  if (dv.getUint32(0, true) !== 0xE011CFD0 || dv.getUint32(4, true) !== 0xE11AB1A1) {
    throw new Error('Non e\' un file CFB/.msg valido');
  }
  const sectorSize = 1 << dv.getUint16(0x1E, true);
  const miniSectorSize = 1 << dv.getUint16(0x20, true);
  const firstDirSector = dv.getUint32(0x30, true);
  const miniCutoff = dv.getUint32(0x38, true);
  const firstMiniFatSector = dv.getUint32(0x3C, true);
  const firstDifatSector = dv.getUint32(0x44, true);
  const ENDOFCHAIN = 0xFFFFFFFE, FREESECT = 0xFFFFFFFF;
  const sectorOffset = sec => (sec + 1) * sectorSize;
  const difat = [];
  for (let i = 0; i < 109; i++) {
    const v = dv.getUint32(0x4C + i * 4, true);
    if (v === FREESECT) break;
    difat.push(v);
  }
  let nextDifatSec = firstDifatSector;
  const entriesPerDifatSec = (sectorSize / 4) - 1;
  while (nextDifatSec !== ENDOFCHAIN && nextDifatSec !== FREESECT) {
    const off = sectorOffset(nextDifatSec);
    for (let i = 0; i < entriesPerDifatSec; i++) {
      const v = dv.getUint32(off + i * 4, true);
      if (v === FREESECT) break;
      difat.push(v);
    }
    nextDifatSec = dv.getUint32(off + sectorSize - 4, true);
  }
  const fatEntriesPerSec = sectorSize / 4;
  const fat = new Uint32Array(difat.length * fatEntriesPerSec);
  for (let i = 0; i < difat.length; i++) {
    const off = sectorOffset(difat[i]);
    for (let j = 0; j < fatEntriesPerSec; j++) {
      fat[i * fatEntriesPerSec + j] = dv.getUint32(off + j * 4, true);
    }
  }
  function chainSectors(startSec) {
    const out = [];
    let sec = startSec;
    while (sec !== ENDOFCHAIN && sec !== FREESECT && sec < fat.length) {
      out.push(sec);
      sec = fat[sec];
      if (out.length > 200000) break;
    }
    return out;
  }
  function readChainAll(startSec) {
    const secs = chainSectors(startSec);
    const out = new Uint8Array(secs.length * sectorSize);
    for (let i = 0; i < secs.length; i++) {
      out.set(new Uint8Array(buf, sectorOffset(secs[i]), sectorSize), i * sectorSize);
    }
    return out;
  }
  const dirData = readChainAll(firstDirSector);
  const dirDV = new DataView(dirData.buffer, dirData.byteOffset, dirData.byteLength);
  const numEntries = (dirData.length / 128) | 0;
  const entries = [];
  for (let i = 0; i < numEntries; i++) {
    const off = i * 128;
    const nameLen = dirDV.getUint16(off + 0x40, true);
    let name = '';
    if (nameLen >= 2) {
      const chars = (nameLen / 2) - 1;
      const cs = [];
      for (let j = 0; j < chars; j++) cs.push(dirDV.getUint16(off + j * 2, true));
      name = String.fromCharCode(...cs);
    }
    entries.push({
      name,
      type: dirDV.getUint8(off + 0x42),
      left: dirDV.getUint32(off + 0x44, true),
      right: dirDV.getUint32(off + 0x48, true),
      child: dirDV.getUint32(off + 0x4C, true),
      startSector: dirDV.getUint32(off + 0x74, true),
      size: dirDV.getUint32(off + 0x78, true) + dirDV.getUint32(off + 0x7C, true) * 0x100000000,
    });
  }
  const root = entries[0];
  const miniStreamFull = readChainAll(root.startSector);
  const miniStream = miniStreamFull.subarray(0, root.size);
  const miniFatSecs = chainSectors(firstMiniFatSector);
  const miniFat = new Uint32Array(miniFatSecs.length * fatEntriesPerSec);
  for (let i = 0; i < miniFatSecs.length; i++) {
    const off = sectorOffset(miniFatSecs[i]);
    for (let j = 0; j < fatEntriesPerSec; j++) {
      miniFat[i * fatEntriesPerSec + j] = dv.getUint32(off + j * 4, true);
    }
  }
  function readStream(entry) {
    if (!entry.size) return new Uint8Array(0);
    if (entry.size < miniCutoff) {
      const out = new Uint8Array(entry.size);
      let sec = entry.startSector, pos = 0;
      while (sec !== ENDOFCHAIN && sec !== FREESECT && pos < entry.size && sec < miniFat.length) {
        const off = sec * miniSectorSize;
        const len = Math.min(miniSectorSize, entry.size - pos);
        out.set(miniStream.subarray(off, off + len), pos);
        pos += len;
        sec = miniFat[sec];
      }
      return out;
    }
    const data = readChainAll(entry.startSector);
    return data.subarray(0, entry.size);
  }
  function collectChildren(rootIdx) {
    const out = [];
    const stack = [rootIdx];
    const seen = new Set();
    while (stack.length) {
      const idx = stack.pop();
      if (idx === FREESECT || idx >= entries.length || seen.has(idx)) continue;
      seen.add(idx);
      const e = entries[idx];
      out.push({ idx, entry: e });
      if (e.left !== FREESECT) stack.push(e.left);
      if (e.right !== FREESECT) stack.push(e.right);
    }
    return out;
  }
  return { entries, root, readStream, collectChildren };
}

function _msgParseProperties(propsStream, headerSize, streams) {
  const dv = new DataView(propsStream.buffer, propsStream.byteOffset, propsStream.byteLength);
  const props = {};
  for (let off = headerSize; off + 16 <= propsStream.length; off += 16) {
    const type = dv.getUint16(off, true);
    const id = dv.getUint16(off + 2, true);
    const idHex = id.toString(16).padStart(4, '0').toUpperCase();
    const typeHex = type.toString(16).padStart(4, '0').toUpperCase();
    if (type === 0x0003) {
      props[idHex] = dv.getInt32(off + 8, true);
    } else if (type === 0x000B) {
      props[idHex] = !!dv.getUint16(off + 8, true);
    } else if (type === 0x0040) {
      const lo = dv.getUint32(off + 8, true);
      const hi = dv.getUint32(off + 12, true);
      const ft = hi * 0x100000000 + lo;
      const ms = ft / 10000 - 11644473600000;
      const d = new Date(ms);
      if (!isNaN(d.getTime())) props[idHex] = d;
    } else if (type === 0x001F || type === 0x001E || type === 0x0102) {
      const data = streams['__substg1.0_' + idHex + typeHex];
      if (!data) continue;
      if (type === 0x001F) {
        let s = '';
        for (let i = 0; i + 1 < data.length; i += 2) s += String.fromCharCode(data[i] | (data[i + 1] << 8));
        props[idHex] = s;
      } else if (type === 0x001E) {
        try { props[idHex] = new TextDecoder('windows-1252').decode(data); }
        catch (e) { props[idHex] = new TextDecoder('utf-8').decode(data); }
      } else {
        props[idHex] = data;
      }
    }
  }
  return props;
}

function _msgCollectStorageContents(cfb, storageEntry) {
  const children = cfb.collectChildren(storageEntry.child);
  const streams = {};
  for (const c of children) {
    if (c.entry.type === 2) streams[c.entry.name] = cfb.readStream(c.entry);
  }
  return streams;
}

function _msgParse(buf) {
  const cfb = _msgReadCFB(buf);
  const topChildren = cfb.collectChildren(cfb.root.child);
  const topStreams = {};
  const recipStorages = [];
  const attachStorages = [];
  for (const c of topChildren) {
    if (c.entry.type === 2) {
      topStreams[c.entry.name] = cfb.readStream(c.entry);
    } else if (c.entry.type === 1) {
      if (c.entry.name.startsWith('__recip_version1.0_')) recipStorages.push(c);
      else if (c.entry.name.startsWith('__attach_version1.0_')) attachStorages.push(c);
    }
  }
  const propsStream = topStreams['__properties_version1.0'];
  const props = propsStream ? _msgParseProperties(propsStream, 32, topStreams) : {};
  const recipients = recipStorages.map(s => {
    const streams = _msgCollectStorageContents(cfb, s.entry);
    return streams['__properties_version1.0']
      ? _msgParseProperties(streams['__properties_version1.0'], 8, streams) : {};
  });
  const attachments = attachStorages.map(s => {
    const streams = _msgCollectStorageContents(cfb, s.entry);
    return streams['__properties_version1.0']
      ? _msgParseProperties(streams['__properties_version1.0'], 8, streams) : {};
  });
  return { props, recipients, attachments };
}

function _msgFormatDate(d) {
  if (!d || !(d instanceof Date) || isNaN(d.getTime())) return '';
  const pad = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function _msgPickEmail(...vals) {
  for (const v of vals) {
    if (typeof v === 'string' && /@/.test(v) && !/^\/o=/i.test(v)) return v.trim();
  }
  for (const v of vals) {
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return '';
}

function _msgExtractFields(parsed) {
  const p = parsed.props;
  const subject = p['0037'] || p['0E1D'] || '';
  const body = p['1000'] || '';
  const html = (typeof p['1013'] === 'string')
    ? p['1013']
    : (p['1013'] instanceof Uint8Array ? new TextDecoder('utf-8').decode(p['1013']) : '');
  const from = _msgPickEmail(p['5D01'], p['0C1F'], p['5D02'], p['0065'], p['0C1A'], p['0042']);
  const toList = [], ccList = [];
  for (const r of parsed.recipients) {
    const email = _msgPickEmail(r['39FE'], r['3003'], r['3001']);
    if (!email) continue;
    const type = r['0C15'];
    if (type === 2) ccList.push(email);
    else if (type === 3) { /* Bcc - skip */ }
    else toList.push(email);
  }
  if (!toList.length && typeof p['0E04'] === 'string') {
    p['0E04'].split(/[;,]/).map(s => s.trim()).filter(Boolean).forEach(s => toList.push(s));
  }
  if (!ccList.length && typeof p['0E03'] === 'string') {
    p['0E03'].split(/[;,]/).map(s => s.trim()).filter(Boolean).forEach(s => ccList.push(s));
  }
  const dateVal = p['0039'] instanceof Date ? p['0039'] : (p['0E06'] instanceof Date ? p['0E06'] : null);
  const messageId = (typeof p['1035'] === 'string' ? p['1035'] : '').trim().replace(/^<|>$/g, '');
  const attachments = [];
  for (const a of parsed.attachments) {
    const filename = a['3707'] || a['3704'] || ('allegato-' + (attachments.length + 1));
    const ctype = a['370E'] || 'application/octet-stream';
    const data = a['3701'];
    if (data instanceof Uint8Array && data.length) {
      attachments.push({ filename, contentType: ctype, bytes: data });
    }
  }
  return { subject, body, html, from, toList, ccList, dateVal, messageId, attachments };
}

async function _pecOnMsgSelected(file) {
  const buf = await file.arrayBuffer();
  const parsed = _msgParse(buf);
  const ex = _msgExtractFields(parsed);
  const setVal = (id, val, force) => {
    const el = document.getElementById(id);
    if (el && val != null && (force || !el.value)) el.value = val;
  };
  setVal('pecF_mittente', ex.from, true);
  setVal('pecF_destinatario', ex.toList.join('; '), true);
  setVal('pecF_oggetto', ex.subject, true);
  setVal('pecF_messageId', ex.messageId, true);
  const dt = _msgFormatDate(ex.dateVal);
  if (dt) setVal('pecF_dataInvio', dt, true);
  const bodyText = ex.body && ex.body.trim()
    ? ex.body.trim()
    : (ex.html ? _pecHtmlToText(ex.html) : '');
  if (bodyText) setVal('pecF_corpo', bodyText, true);
  if (ex.ccList.length) {
    const noteEl = document.getElementById('pecF_note');
    if (noteEl && !noteEl.value) noteEl.value = 'Cc: ' + ex.ccList.join('; ');
  }
  window._pecExtractedAttachments = ex.attachments.map(a => ({
    filename: a.filename,
    contentType: a.contentType,
    blob: new Blob([a.bytes], { type: a.contentType || 'application/octet-stream' }),
  }));
  _pecRenderExtractedAttachmentsList();
  if (typeof _pecRenderEmlPreview === 'function') {
    try { _pecRenderEmlPreview(null); } catch (_) { /* ignore */ }
  }
}

async function _pecOnEmlSelected(input) {
  const f = input && input.files && input.files[0];
  if (!f) return;
  try {
    const buf = await f.arrayBuffer();
    const isCfb = buf.byteLength >= 8 && (() => {
      const dv = new DataView(buf, 0, 8);
      return dv.getUint32(0, true) === 0xE011CFD0 && dv.getUint32(4, true) === 0xE11AB1A1;
    })();
    const isMsgByName = /\.msg$/i.test(f.name || '');
    if (isCfb || isMsgByName) {
      try {
        await _pecOnMsgSelected(f);
        return;
      } catch (e) {
        console.error('MSG parse error', e);
        alert((typeof t === 'function' && t('msgParseError')) || ('Errore nella lettura del file .msg: ' + (e.message || e)));
        return;
      }
    }
    const raw = new TextDecoder('latin1').decode(buf);
    const root = _emlParsePart(raw);
    const get = n => _emlDecodeMimeWord(_emlGetHeader(root.headers, n) || '');
    const from = get('from');
    const to = get('to');
    const cc = get('cc');
    const subj = get('subject');
    const dateStr = _emlGetHeader(root.headers, 'date');
    const messageId = (_emlGetHeader(root.headers, 'message-id') || '').trim().replace(/^<|>$/g, '');
    const extracted = _emlExtract(root);
    const body = extracted.textPlain
      ? extracted.textPlain.trim()
      : (extracted.textHtml ? _pecHtmlToText(extracted.textHtml) : '');

    const fromAddrs = _emlExtractAddresses(from);
    const toAddrs = _emlExtractAddresses(to);
    const ccAddrs = _emlExtractAddresses(cc);

    const setVal = (id, val, force) => {
      const el = document.getElementById(id);
      if (el && val != null && (force || !el.value)) el.value = val;
    };
    setVal('pecF_mittente', fromAddrs[0] || from, true);
    setVal('pecF_destinatario', toAddrs.join('; '), true);
    setVal('pecF_oggetto', subj, true);
    setVal('pecF_messageId', messageId, true);
    const dt = _emlParseDate(dateStr);
    if (dt) setVal('pecF_dataInvio', dt, true);
    if (body) setVal('pecF_corpo', body, true);
    if (ccAddrs.length) {
      const noteEl = document.getElementById('pecF_note');
      if (noteEl && !noteEl.value) noteEl.value = 'Cc: ' + ccAddrs.join('; ');
    }

    window._pecExtractedAttachments = extracted.attachments.map(a => ({
      filename: a.filename,
      contentType: a.contentType,
      blob: new Blob([a.bytes], { type: a.contentType || 'application/octet-stream' }),
    }));
    _pecRenderExtractedAttachmentsList();

    let smimeRes = null;
    try { await _loadAgidTrustList(); } catch (_) {}
    try { smimeRes = _smimeVerifyPecReceipt(raw); } catch (_) { smimeRes = null; }
    _pecRenderEmlPreview({
      filename: f.name,
      sizeKb: (f.size / 1024).toFixed(1),
      from, to, cc, subject: subj, date: dateStr || '', messageId,
      returnPath: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'return-path') || ''),
      replyTo: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'reply-to') || ''),
      authResults: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'authentication-results') || ''),
      receivedSpf: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'received-spf') || ''),
      dkim: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'dkim-signature') || ''),
      bodyText: extracted.textPlain || '',
      bodyHtml: extracted.textHtml || '',
      smimeStatus: smimeRes ? smimeRes.status : null,
      smimeDetails: smimeRes ? smimeRes.details : '',
      smimeSigner: smimeRes ? smimeRes.signer : '',
      smimeAgidProvider: smimeRes ? (smimeRes.agidProvider || '') : '',
    });
  } catch (e) {
    console.error('EML parse error', e);
    alert((typeof t === 'function' && t('emlParseError')) || ('Errore nella lettura del file .eml: ' + (e.message || e)));
  }
}

function _emlSanitizeHtml(html) {
  if (!html) return '';
  try {
    const doc = new DOMParser().parseFromString(html, 'text/html');
    const walk = (node) => {
      const kids = Array.from(node.childNodes);
      for (const c of kids) {
        if (c.nodeType === 1) {
          const tag = c.tagName.toLowerCase();
          if (tag === 'script' || tag === 'style' || tag === 'iframe' || tag === 'object' || tag === 'embed' || tag === 'link' || tag === 'meta' || tag === 'form') {
            c.remove();
            continue;
          }
          for (const a of Array.from(c.attributes)) {
            const n = a.name.toLowerCase();
            const v = (a.value || '').trim().toLowerCase();
            if (n.startsWith('on') || ((n === 'href' || n === 'src' || n === 'action') && (v.startsWith('javascript:') || v.startsWith('data:text/html')))) {
              c.removeAttribute(a.name);
            }
          }
          walk(c);
        }
      }
    };
    walk(doc.body);
    return doc.body.innerHTML;
  } catch (_) {
    return '';
  }
}

function _pecBuildEmlPreviewHtml(d, opts) {
  opts = opts || {};
  const escH = s => (s == null ? '' : String(s).replace(/[<>&"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c])));
  const safeHtml = d.bodyHtml ? _emlSanitizeHtml(d.bodyHtml) : '';
  const bodyTab = safeHtml
    ? `<iframe sandbox="" srcdoc="${escH('<style>body{font-family:sans-serif;font-size:13px;color:#111;margin:8px}img{max-width:100%}</style>' + safeHtml)}" style="width:100%;height:240px;border:1px solid #e5e7eb;border-radius:4px;background:#fff" data-testid="iframe-eml-body-html"></iframe>`
    : `<pre style="white-space:pre-wrap;font-family:ui-monospace,monospace;font-size:12px;color:#111;background:#fff;border:1px solid #e5e7eb;border-radius:4px;padding:8px;max-height:240px;overflow:auto;margin:0" data-testid="text-eml-body-text">${escH(d.bodyText || '(corpo vuoto)')}</pre>`;
  const headerRow = (label, val, testid) => val ? `<tr><td style="padding:2px 6px 2px 0;color:#6b7280;white-space:nowrap;vertical-align:top">${escH(label)}</td><td style="padding:2px 0;color:#111;word-break:break-all" data-testid="${testid}">${escH(val)}</td></tr>` : '';
  const headersTable = `<table style="width:100%;font-size:11px;border-collapse:collapse"><tbody>
    ${headerRow('From:', d.from, 'text-eml-hdr-from')}
    ${headerRow('To:', d.to, 'text-eml-hdr-to')}
    ${headerRow('Cc:', d.cc, 'text-eml-hdr-cc')}
    ${headerRow('Subject:', d.subject, 'text-eml-hdr-subject')}
    ${headerRow('Date:', d.date, 'text-eml-hdr-date')}
    ${headerRow('Message-ID:', d.messageId, 'text-eml-hdr-msgid')}
    ${headerRow('Return-Path:', d.returnPath, 'text-eml-hdr-returnpath')}
    ${headerRow('Reply-To:', d.replyTo, 'text-eml-hdr-replyto')}
    ${headerRow('Received-SPF:', d.receivedSpf, 'text-eml-hdr-spf')}
    ${headerRow('Authentication-Results:', d.authResults, 'text-eml-hdr-auth')}
    ${headerRow('DKIM-Signature:', d.dkim ? d.dkim.slice(0, 200) + (d.dkim.length > 200 ? '…' : '') : '', 'text-eml-hdr-dkim')}
  </tbody></table>`;
  const lblPrev = (typeof t === 'function' && t('pecEmlPreview')) || 'Anteprima messaggio';
  const lblHdr = (typeof t === 'function' && t('pecEmlHeaders')) || 'Header tecnici';
  const lblBody = (typeof t === 'function' && t('pecEmlBody')) || 'Corpo';
  const fmt = safeHtml ? 'HTML' : 'TXT';
  const wrap = opts.wrapDetails !== false;
  const smimeBlock = d.smimeStatus
    ? `<div style="margin-top:6px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
        ${_pecSmimeBadge(d.smimeStatus, d.smimeAgidProvider)}
        ${d.smimeDetails ? `<span style="font-size:11px;color:#6b7280">${escH(d.smimeDetails)}</span>` : ''}
        ${d.smimeSigner ? `<span style="font-size:11px;color:#6b7280">· signer: ${escH(d.smimeSigner)}</span>` : ''}
      </div>` : '';
  const inner = `${smimeBlock}<div style="margin-top:6px">
      <div style="font-size:11px;color:#1e40af;font-weight:600;margin-bottom:4px">${escH(lblBody)}</div>
      ${bodyTab}
    </div>
    <details style="margin-top:8px">
      <summary style="cursor:pointer;font-size:11px;font-weight:600;color:#1e40af">🔧 ${escH(lblHdr)}</summary>
      <div style="margin-top:4px;background:#fafaf9;padding:6px;border-radius:4px">${headersTable}</div>
    </details>`;
  if (!wrap) return inner;
  const testid = opts.testid || 'container-eml-preview';
  const openAttr = opts.open === false ? '' : ' open';
  return `<details${openAttr} style="margin-top:8px;background:#fff;border:1px solid #bfdbfe;border-radius:6px;padding:6px 8px" data-testid="${escH(testid)}">
    <summary style="cursor:pointer;font-size:12px;font-weight:600;color:#1e40af">👁️ ${escH(lblPrev)} — ${escH(d.filename || '')} (${escH(d.sizeKb)} KB · ${fmt})</summary>
    ${inner}
  </details>`;
}

function _pecRenderEmlPreview(d) {
  const cont = document.getElementById('pecF_emlPreview');
  if (!cont) return;
  if (!d) { cont.innerHTML = ''; return; }
  cont.innerHTML = _pecBuildEmlPreviewHtml(d, { open: true });
}

async function _pecLoadFileBytes(fileRec) {
  if (!fileRec) return null;
  if (fileRec.blob) {
    const b = fileRec.blob;
    if (b instanceof Uint8Array) return b;
    if (b instanceof ArrayBuffer) return new Uint8Array(b);
    if (b instanceof Blob) return new Uint8Array(await b.arrayBuffer());
  }
  if (fileRec.storagePath) {
    try {
      let dir = (typeof FS_FILES_HANDLE !== 'undefined' && FS_FILES_HANDLE) ? FS_FILES_HANDLE
              : (typeof FS_DIR_HANDLE !== 'undefined' && FS_DIR_HANDLE) ? FS_DIR_HANDLE : null;
      if (!dir) return null;
      const parts = fileRec.storagePath.split('/').filter(Boolean);
      for (const part of parts) dir = await dir.getDirectoryHandle(part);
      const fh = await dir.getFileHandle(fileRec.diskFileName || fileRec.fileName);
      const file = await fh.getFile();
      return new Uint8Array(await file.arrayBuffer());
    } catch (e) {
      console.warn('_pecLoadFileBytes read error:', e);
      return null;
    }
  }
  return null;
}

async function _pecRenderArchivedEmlPreview(fileId, containerId) {
  const cont = document.getElementById(containerId);
  if (!cont) return;
  if (cont.dataset.loaded === '1') return;
  cont.innerHTML = `<div style="font-size:12px;color:#6b7280;padding:6px">${(typeof t === 'function' && t('loading')) || 'Caricamento…'}</div>`;
  try {
    const f = await DB.getFile(fileId);
    if (!f) {
      cont.innerHTML = `<div style="font-size:12px;color:#dc2626;padding:6px">${(typeof t === 'function' && t('previewNotAvailable')) || 'Anteprima non disponibile'}</div>`;
      return;
    }
    const bytes = await _pecLoadFileBytes(f);
    if (!bytes || !bytes.length) {
      cont.innerHTML = `<div style="font-size:12px;color:#dc2626;padding:6px">${(typeof t === 'function' && t('previewNotAvailable')) || 'Anteprima non disponibile'}</div>`;
      return;
    }
    const raw = new TextDecoder('latin1').decode(bytes);
    const root = _emlParsePart(raw);
    const get = n => _emlDecodeMimeWord(_emlGetHeader(root.headers, n) || '');
    const from = get('from');
    const to = get('to');
    const cc = get('cc');
    const subj = get('subject');
    const dateStr = _emlGetHeader(root.headers, 'date');
    const messageId = (_emlGetHeader(root.headers, 'message-id') || '').trim().replace(/^<|>$/g, '');
    const extracted = _emlExtract(root);
    const d = {
      filename: f.fileName,
      sizeKb: ((f.fileSize || bytes.length) / 1024).toFixed(1),
      from, to, cc, subject: subj, date: dateStr || '', messageId,
      returnPath: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'return-path') || ''),
      replyTo: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'reply-to') || ''),
      authResults: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'authentication-results') || ''),
      receivedSpf: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'received-spf') || ''),
      dkim: _emlDecodeMimeWord(_emlGetHeader(root.headers, 'dkim-signature') || ''),
      bodyText: extracted.textPlain || '',
      bodyHtml: extracted.textHtml || '',
    };
    cont.innerHTML = _pecBuildEmlPreviewHtml(d, { wrapDetails: false });
    cont.dataset.loaded = '1';
  } catch (e) {
    console.error('Archived EML preview error', e);
    cont.innerHTML = `<div style="font-size:12px;color:#dc2626;padding:6px">${(typeof t === 'function' && t('emlParseError')) || 'Errore nella lettura del file .eml'}: ${(e && e.message) || ''}</div>`;
  }
}

function _pecRenderExtractedAttachmentsList() {
  const cont = document.getElementById('pecF_extractedAtt');
  if (!cont) return;
  const list = window._pecExtractedAttachments || [];
  if (!list.length) {
    cont.innerHTML = '<div style="margin-top:6px;font-size:11px;color:#6b7280">Nessun allegato estratto.</div>';
    return;
  }
  cont.innerHTML = `<div style="margin-top:8px;font-size:12px;color:#374151" data-testid="container-eml-attachments"><b>📎 Allegati estratti dal file importato (${list.length}):</b><ul style="margin:4px 0 0 16px;padding:0">${list.map((a, i) => `<li data-testid="text-eml-attachment-${i}">${(a.filename || '').replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))} <span style="color:#6b7280">(${(a.blob.size / 1024).toFixed(1)} KB)</span></li>`).join('')}</ul><div style="font-size:11px;color:#6b7280;margin-top:4px">Verranno salvati come allegati della PEC al salvataggio.</div></div>`;
}

/* ============== MBOX BULK IMPORT (Task #180) ============== */

async function _mboxParseStream(file, onMessage, onProgress) {
  // Streaming parser memory-light: emette per ogni messaggio
  //   { startByte, endByte, headersText }
  // dove headersText contiene solo le header iniziali (fino al primo riga vuota,
  // limitato a 64KB) — abbastanza per classificazione e grouping. Il corpo NON
  // viene mai trattenuto in memoria; viene riletto on-demand via file.slice() in
  // fase di save (vedi _pecReadMessageBytes / _pecReadMessageRoot).
  const CHUNK = 4 * 1024 * 1024;
  const HEAD_MAX = 64 * 1024;
  const decoder = new TextDecoder('latin1');
  let offset = 0;
  let bufStartByte = -1; // sentinel '\n' è il "byte" virtuale a posizione -1
  let buffer = '\n';
  const total = file.size;
  let count = 0;
  const SAFE_TAIL = 4096;
  const sepRe = /\nFrom [^\n]*\n/g;
  const extractHeaders = (s) => {
    const blank = s.search(/\r?\n\r?\n/);
    const cut = blank >= 0 ? Math.min(blank, HEAD_MAX) : Math.min(s.length, HEAD_MAX);
    return s.slice(0, cut);
  };
  const flush = (final) => {
    const limit = final ? buffer.length : Math.max(0, buffer.length - SAFE_TAIL);
    sepRe.lastIndex = 0;
    const seps = [];
    let m;
    while ((m = sepRe.exec(buffer)) !== null) {
      if (m.index >= limit && !final) break;
      seps.push({ at: m.index, after: m.index + m[0].length });
    }
    for (let i = 0; i < seps.length - 1; i++) {
      const startBuf = seps[i].after, endBuf = seps[i + 1].at;
      if (endBuf > startBuf) {
        count++;
        onMessage({
          startByte: bufStartByte + startBuf,
          endByte: bufStartByte + endBuf,
          headersText: extractHeaders(buffer.slice(startBuf, Math.min(endBuf, startBuf + HEAD_MAX))),
        }, count);
      }
    }
    if (final && seps.length > 0) {
      const startBuf = seps[seps.length - 1].after, endBuf = buffer.length;
      if (endBuf > startBuf) {
        count++;
        onMessage({
          startByte: bufStartByte + startBuf,
          endByte: bufStartByte + endBuf,
          headersText: extractHeaders(buffer.slice(startBuf, Math.min(endBuf, startBuf + HEAD_MAX))),
        }, count);
      }
      buffer = '';
      bufStartByte = bufStartByte + endBuf;
    } else if (seps.length > 0) {
      const cutBuf = seps[seps.length - 1].at;
      bufStartByte = bufStartByte + cutBuf;
      buffer = buffer.slice(cutBuf);
    }
  };
  while (offset < total) {
    const slice = file.slice(offset, Math.min(offset + CHUNK, total));
    const buf = await slice.arrayBuffer();
    buffer += decoder.decode(buf, { stream: true });
    offset += buf.byteLength;
    if (onProgress) onProgress(offset, total, count);
    flush(false);
    await new Promise(r => setTimeout(r, 0));
  }
  flush(true);
  return count;
}

async function _pecReadMessageBytes(file, item) {
  // Rilegge i byte originali del messaggio dalla sorgente.
  // - mbox: il file passato è l'unico .mbox, slice via offset.
  // - cartella .eml: ogni item porta il proprio File (item.file), slice via offset
  //   (per i .eml interi sono 0..size).
  // - .zip: ogni item porta un File costruito sui bytes della entry .eml,
  //   anch'esso letto via slice 0..size.
  const src = (item && item.file) || file;
  const ab = await src.slice(item.startByte, item.endByte).arrayBuffer();
  return new Uint8Array(ab);
}

async function _pecReadMessageRoot(file, item) {
  const bytes = await _pecReadMessageBytes(file, item);
  const txt = new TextDecoder('latin1').decode(bytes);
  return _emlParsePart(txt);
}

// ───────────────────────────────────────────────────────────────────────────
// Verifica firma S/MIME del daticert.xml nelle ricevute PEC.
// Le ricevute PEC sono firmate dal gestore tramite multipart/signed +
// smime.p7s (PKCS#7 SignedData detached). La verifica conferma che il
// contenuto firmato (tipicamente il sotto-multipart con daticert.xml) non è
// stato manomesso e che la firma corrisponde alla chiave pubblica del
// certificato firmatario. La validazione di catena verso il TSL AgID NON è
// inclusa: il badge "valida" attesta solo l'integrità crittografica.
// ───────────────────────────────────────────────────────────────────────────
// ───────────────────────────────────────────────────────────────────────────
// Trust list AgID — caricamento offline da file statico bundlato.
// La trust list è in `data/agid_pec_trustlist.json` (JSON puro, separato dal
// codice). Viene letta UNA volta sola via fetch locale (nessuna chiamata di
// rete: il fetch su file statico bundlato è risolto dal server di sviluppo
// o dal browser file://). Conservata in window.AGID_PEC_TRUSTLIST.
// ───────────────────────────────────────────────────────────────────────────
// La trust list è caricata via <script src="data/agid_pec_trustlist.js">
// in index.html, che assegna window.AGID_PEC_TRUSTLIST = {...}. Funziona
// anche da file:// (i tag <script> locali sono ammessi, il fetch no per CORS).
// Questa funzione resta async per compatibilità con i chiamanti, ma non
// effettua più alcuna I/O: legge solo la variabile globale già pronta.
let _agidTrustListWarnedOnce = false;
async function _loadAgidTrustList() {
  if (window.AGID_PEC_TRUSTLIST && Array.isArray(window.AGID_PEC_TRUSTLIST.providers)) {
    return window.AGID_PEC_TRUSTLIST;
  }
  if (!_agidTrustListWarnedOnce) {
    _agidTrustListWarnedOnce = true;
    console.warn('AgID trust list non caricata: lo <script src="data/agid_pec_trustlist.js"> manca o è malformato. I badge "gestore accreditato AgID" resteranno disabilitati.');
  }
  return null;
}
// Log diagnostico una sola volta all'avvio.
if (typeof window !== 'undefined') {
  if (window.AGID_PEC_TRUSTLIST && Array.isArray(window.AGID_PEC_TRUSTLIST.providers)) {
    try { console.log('AgID trust list caricata (offline) — versione', window.AGID_PEC_TRUSTLIST.version, '— gestori:', window.AGID_PEC_TRUSTLIST.providers.length); } catch (_) {}
  }
}

/**
 * Lookup deterministico di un gestore PEC accreditato AgID.
 *
 * Match esclusivamente su DUE criteri (nessun fallback su subject/dominio):
 *   1) Fingerprint SHA-256 del DER di un cert della catena PKCS#7
 *      corrisponde a uno di `provider.caFingerprintsSha256` (hex lowercase).
 *   2) Common Name dell'Issuer del cert firmatario corrisponde
 *      esattamente (case-insensitive, trimmed) a uno di `provider.issuerCNs`.
 *
 * @param {string} signerIssuerCN  CN dell'Issuer del cert firmatario (può essere vuoto).
 * @param {string[]} chainFingerprintsSha256  Array di hex lowercase dei DER dei certs nella catena PKCS#7.
 * @returns {string|null}  Nome del gestore se riconosciuto, altrimenti null.
 */
function _agidLookupProvider(signerIssuerCN, chainFingerprintsSha256) {
  try {
    const tl = window.AGID_PEC_TRUSTLIST;
    if (!tl || !Array.isArray(tl.providers)) return null;
    const cn = String(signerIssuerCN || '').trim().toLowerCase();
    const fps = Array.isArray(chainFingerprintsSha256)
      ? chainFingerprintsSha256.map(s => String(s || '').toLowerCase()).filter(Boolean)
      : [];
    for (const p of tl.providers) {
      // Criterio 1 (preferito): fingerprint SHA-256 di una CA della catena
      if (fps.length && Array.isArray(p.caFingerprintsSha256)) {
        for (const fp of p.caFingerprintsSha256) {
          const k = String(fp || '').toLowerCase().replace(/[^0-9a-f]/g, '');
          if (k && fps.indexOf(k) !== -1) return p.name;
        }
      }
      // Criterio 2: Issuer CN del firmatario combacia ESATTAMENTE con un CN della trust list
      if (cn && Array.isArray(p.issuerCNs)) {
        for (const exact of p.issuerCNs) {
          const e = String(exact || '').trim().toLowerCase();
          if (e && e === cn) return p.name;
        }
      }
    }
    return null;
  } catch (_) { return null; }
}

function _smimeFindSignedParts(rawTextLatin1) {
  // Cerca la prima envelope multipart/signed nel messaggio (latin1-decoded,
  // 1 char = 1 byte). Restituisce { signedBytesText, p7sBase64, micalg } o null.
  const re = /Content-Type\s*:\s*multipart\/signed\s*;([\s\S]*?)\r?\n(?:[ \t][^\r\n]*\r?\n)*\r?\n/i;
  const m = rawTextLatin1.match(re);
  if (!m) return null;
  // Param block: include eventuali continuation lines (folded headers)
  const paramsRaw = m[1].replace(/\r?\n[ \t]+/g, ' ');
  const bm = paramsRaw.match(/boundary\s*=\s*"?([^";\r\n]+)"?/i);
  if (!bm) return null;
  const boundary = bm[1].trim();
  const aMatch = paramsRaw.match(/micalg\s*=\s*"?([^";\r\n]+)"?/i);
  const micalg = aMatch ? aMatch[1].trim().toLowerCase() : 'sha-256';
  const startBoundary = '--' + boundary;
  const headerEnd = m.index + m[0].length;
  const ix1 = rawTextLatin1.indexOf(startBoundary, headerEnd);
  if (ix1 < 0) return null;
  let signedStart = ix1 + startBoundary.length;
  if (rawTextLatin1[signedStart] === '\r') signedStart++;
  if (rawTextLatin1[signedStart] === '\n') signedStart++;
  // I bytes firmati DEVONO mantenere CRLF originali. Cerca il prossimo boundary.
  let signedEnd = rawTextLatin1.indexOf('\r\n' + startBoundary, signedStart);
  let eolLen = 2;
  if (signedEnd < 0) {
    signedEnd = rawTextLatin1.indexOf('\n' + startBoundary, signedStart);
    eolLen = 1;
  }
  if (signedEnd < 0) return null;
  const signed = rawTextLatin1.slice(signedStart, signedEnd);
  // p7s sub-part
  let p7sStart = signedEnd + eolLen + startBoundary.length;
  if (rawTextLatin1[p7sStart] === '\r') p7sStart++;
  if (rawTextLatin1[p7sStart] === '\n') p7sStart++;
  let p7sEnd = rawTextLatin1.indexOf('\r\n' + startBoundary, p7sStart);
  if (p7sEnd < 0) p7sEnd = rawTextLatin1.indexOf('\n' + startBoundary, p7sStart);
  if (p7sEnd < 0) p7sEnd = rawTextLatin1.length;
  const p7sBlock = rawTextLatin1.slice(p7sStart, p7sEnd);
  const sep = p7sBlock.search(/\r?\n\r?\n/);
  if (sep < 0) return null;
  const p7sBody = p7sBlock.slice(sep).replace(/^[\r\n]+/, '');
  const p7sBase64 = p7sBody.replace(/[^A-Za-z0-9+/=]/g, '');
  return { signed, p7sBase64, micalg };
}

function _smimeMdForOid(oid) {
  if (typeof forge === 'undefined') return null;
  if (oid === '2.16.840.1.101.3.4.2.1') return forge.md.sha256.create();
  if (oid === '1.3.14.3.2.26') return forge.md.sha1.create();
  if (oid === '2.16.840.1.101.3.4.2.2') return forge.md.sha384.create();
  if (oid === '2.16.840.1.101.3.4.2.3') return forge.md.sha512.create();
  return forge.md.sha256.create();
}

function _smimeVerifyPecReceipt(rawTextLatin1) {
  // Restituisce { ok, status, details, signer } dove:
  //   ok: true|false|null (null = non verificabile, mancano dati o errore)
  //   status: 'valid' | 'invalid' | 'missing' | 'unavailable' | 'error'
  if (typeof forge === 'undefined' || !forge.asn1 || !forge.pki) {
    return { ok: null, status: 'unavailable', details: 'libreria di verifica non caricata', signer: '' };
  }
  const parts = _smimeFindSignedParts(rawTextLatin1);
  if (!parts) return { ok: null, status: 'missing', details: 'nessuna parte multipart/signed con smime.p7s', signer: '' };
  try {
    const der = forge.util.decode64(parts.p7sBase64);
    const asn1 = forge.asn1.fromDer(der);
    // ContentInfo SEQUENCE: [0]=OID contentType, [1]=[0] EXPLICIT content
    if (!asn1 || !asn1.value || asn1.value.length < 2) throw new Error('ContentInfo malformato');
    const sd = asn1.value[1].value[0]; // SignedData SEQUENCE
    const sdv = sd.value;
    // sdv ordering: version, digestAlgorithms SET, encapContentInfo SEQUENCE,
    //               [0] IMPL certs OPT, [1] IMPL crls OPT, signerInfos SET
    const signerInfos = sdv[sdv.length - 1];
    if (!signerInfos || !signerInfos.value || !signerInfos.value.length) throw new Error('signerInfos vuoto');
    const signerInfo = signerInfos.value[0];
    const siv = signerInfo.value;
    let signedAttrsNode = null, signatureNode = null, digestAlgNode = null, sidNode = null;
    for (let i = 0; i < siv.length; i++) {
      const n = siv[i];
      if (n.tagClass === forge.asn1.Class.CONTEXT_SPECIFIC && n.type === 0) signedAttrsNode = n;
      else if (n.type === forge.asn1.Type.OCTETSTRING) { if (!signatureNode) signatureNode = n; }
      else if (n.type === forge.asn1.Type.SEQUENCE) {
        if (!sidNode) sidNode = n;            // primo SEQUENCE = issuerAndSerialNumber (sid)
        else if (!digestAlgNode) digestAlgNode = n; // secondo SEQUENCE = digestAlgorithm
        // i SEQUENCE successivi sono signatureAlgorithm: lasciamo tutti
      }
    }
    if (!signatureNode) throw new Error('firma assente nel SignerInfo');
    if (!digestAlgNode) throw new Error('digestAlgorithm assente');
    const digestOid = forge.asn1.derToOid(digestAlgNode.value[0].value);

    // Estrai certificati [0] IMPLICIT al livello SignedData
    const certs = [];
    for (const n of sdv) {
      if (n.tagClass === forge.asn1.Class.CONTEXT_SPECIFIC && n.type === 0) {
        for (const c of (n.value || [])) {
          try { certs.push(forge.pki.certificateFromAsn1(c)); } catch (_) { /* skip non-cert */ }
        }
      }
    }
    if (!certs.length) throw new Error('nessun certificato firmatario nel PKCS#7');
    // Tenta match issuer+serial
    let signerCert = certs[0];
    try {
      if (sidNode && sidNode.value && sidNode.value.length >= 2) {
        const serialBytes = sidNode.value[1].value;
        const serialHex = forge.util.bytesToHex(serialBytes).replace(/^0+/, '') || '0';
        const matched = certs.find(c => (c.serialNumber || '').replace(/^0+/, '').toLowerCase() === serialHex.toLowerCase());
        if (matched) signerCert = matched;
      }
    } catch (_) { /* fallback al primo cert */ }

    // Validità temporale del certificato (alla data odierna; in mancanza di
    // contestualizzazione robusta della data ricevuta, "now" è una stima
    // accettabile per segnalare cert scaduti).
    const now = new Date();
    const certValidNow = now >= signerCert.validity.notBefore && now <= signerCert.validity.notAfter;

    // Digest del contenuto firmato. Calcoliamo in più varianti di
    // canonicalizzazione dei terminatori di riga, perché molti file .eml
    // perdono i CRLF originali quando vengono salvati/scaricati da
    // client di posta o file system con normalizzazione automatica.
    // La firma S/MIME è calcolata sui bytes esatti come arrivati: se
    // anche solo i CRLF sono diventati LF, l'hash cambia. Proviamo
    // quindi (in ordine):
    //   1) bytes "as-is" (caso ideale, file binario integro)
    //   2) tutti i LF singoli normalizzati a CRLF (recupero da file
    //      passati per filesystem/client che li hanno collassati)
    //   3) tutti i CRLF normalizzati a LF (raro, ma alcune pipeline
    //      lo fanno in entrambi i sensi)
    // Se uno qualsiasi combacia, consideriamo la firma valida e marchiamo
    // `mdNormalized = true` per segnalarlo all'utente.
    const _signedAsIs = parts.signed;
    const _signedToCrlf = parts.signed.replace(/\r\n/g, '\n').replace(/\r/g, '\n').replace(/\n/g, '\r\n');
    const _signedToLf = parts.signed.replace(/\r\n/g, '\n');
    const _digestOf = (txt) => {
      const md = _smimeMdForOid(digestOid);
      md.update(txt);
      return md.digest().getBytes();
    };
    const _digAsIs = _digestOf(_signedAsIs);
    let contentDigest = _digAsIs;
    let signedCanonical = _signedAsIs;
    let mdNormalized = false;

    let mdMatches = true;
    let sigDigestSrc = parts.signed;
    if (signedAttrsNode) {
      let foundMdAttr = false;
      for (const attr of (signedAttrsNode.value || [])) {
        if (attr.value && attr.value.length >= 2) {
          let oid;
          try { oid = forge.asn1.derToOid(attr.value[0].value); } catch (_) { continue; }
          if (oid === '1.2.840.113549.1.9.4') {
            const setVal = attr.value[1].value[0];
            const expected = setVal.value;
            if (expected === _digAsIs) {
              mdMatches = true;
            } else if (_signedToCrlf !== _signedAsIs && expected === _digestOf(_signedToCrlf)) {
              mdMatches = true; mdNormalized = true; signedCanonical = _signedToCrlf; contentDigest = _digestOf(_signedToCrlf);
            } else if (_signedToLf !== _signedAsIs && expected === _digestOf(_signedToLf)) {
              mdMatches = true; mdNormalized = true; signedCanonical = _signedToLf; contentDigest = _digestOf(_signedToLf);
            } else {
              mdMatches = false;
            }
            foundMdAttr = true;
            break;
          }
        }
      }
      if (!foundMdAttr) mdMatches = false;
      // Quando signedAttrs è presente, la firma è calcolata sul DER della
      // SET OF Attribute (tag 0x31), NON sul tag IMPLICIT [0] (0xA0).
      const setNode = forge.asn1.create(
        forge.asn1.Class.UNIVERSAL, forge.asn1.Type.SET, true,
        signedAttrsNode.value
      );
      sigDigestSrc = forge.asn1.toDer(setNode).getBytes();
    }
    const sigMd = _smimeMdForOid(digestOid);
    sigMd.update(sigDigestSrc);
    const sigDigestBytes = sigMd.digest().getBytes();
    const signatureBytes = signatureNode.value;
    let sigOk = false;
    try { sigOk = signerCert.publicKey.verify(sigDigestBytes, signatureBytes); } catch (_) { sigOk = false; }

    const subj = (signerCert.subject.attributes || [])
      .map(a => `${a.shortName || a.name || a.type}=${a.value}`).join(', ');
    const issuerDn = (signerCert.issuer.attributes || [])
      .map(a => `${a.shortName || a.name || a.type}=${a.value}`).join(', ');
    // Estrai SOLO il Common Name dell'Issuer del firmatario (per il match deterministico
    // contro `issuerCNs` della trust list — nessun substring, solo equality CI).
    let signerIssuerCN = '';
    try {
      const cnAttr = (signerCert.issuer.attributes || []).find(a =>
        (a.shortName === 'CN') || (a.name === 'commonName') || (a.type === '2.5.4.3'));
      if (cnAttr) signerIssuerCN = String(cnAttr.value || '').trim();
    } catch (_) { signerIssuerCN = ''; }
    // Calcola fingerprint SHA-256 (hex lowercase) del DER di OGNI certificato presente
    // nella catena PKCS#7. Verifica AgID via fingerprint pinning sulle CA emettitrici.
    const chainFingerprints = [];
    try {
      for (const c of certs) {
        try {
          const der = forge.asn1.toDer(forge.pki.certificateToAsn1(c)).getBytes();
          const md = forge.md.sha256.create();
          md.update(der);
          chainFingerprints.push(md.digest().toHex().toLowerCase());
        } catch (_) { /* skip */ }
      }
    } catch (_) {}
    // Match offline contro la trust list AgID (file dati `data/agid_pec_trustlist.json`).
    // Lookup deterministico: SOLO fingerprint SHA-256 catena O Issuer CN ESATTO.
    // Nessun fallback su subject/dominio (verrebbe banalmente bypassato da un cert
    // self-signed con CN simile). Nessuna chiamata di rete.
    let agidProvider = null;
    try {
      agidProvider = _agidLookupProvider(signerIssuerCN, chainFingerprints) || null;
    } catch (_) { agidProvider = null; }

    if (sigOk && mdMatches) {
      const tail = certValidNow ? '' : ' (cert. fuori validità temporale)';
      const normTail = mdNormalized ? ' — accettata dopo normalizzazione CRLF (il file .eml ha probabilmente subito una conversione di terminatori di riga durante salvataggio/trasferimento)' : '';
      if (agidProvider) {
        return { ok: true, status: 'agid', details: `firma S/MIME valida — gestore accreditato AgID: ${agidProvider}${tail}${normTail}`, signer: subj, issuer: issuerDn, agidProvider };
      }
      return { ok: true, status: 'valid', details: `firma S/MIME crittograficamente valida${tail}${normTail}`, signer: subj, issuer: issuerDn, agidProvider: null };
    }
    const reasons = [];
    if (!sigOk) reasons.push('firma RSA non valida');
    if (!mdMatches) reasons.push('messageDigest non corrisponde al contenuto firmato (provate anche le varianti CRLF/LF — il messaggio potrebbe essere stato modificato dopo la firma)');
    return { ok: false, status: 'invalid', details: 'firma non verificata: ' + reasons.join('; '), signer: subj, issuer: issuerDn, agidProvider };
  } catch (e) {
    return { ok: null, status: 'error', details: 'errore parsing/verifica: ' + (e.message || e), signer: '', issuer: '', agidProvider: null };
  }
}

// Verifica le ricevute (acc + del) di un gruppo PEC e ritorna lo stato
// aggregato + un breve messaggio per le note.
async function _smimeVerifyGroup(g) {
  const targets = [];
  if (g.acc) targets.push({ kind: 'acc', item: g.acc });
  for (const d of g.dels) targets.push({ kind: 'del', item: d });
  if (!targets.length) return { status: 'absent', summary: '' };
  // Garantisci che la trust list AgID sia disponibile prima del primo lookup,
  // per evitare falsi negativi 'valid' alla prima verifica dopo l'avvio.
  try { await _loadAgidTrustList(); } catch (_) {}
  const results = [];
  for (const tg of targets) {
    try {
      const bytes = await _pecReadMessageBytes(null, tg.item);
      const txt = new TextDecoder('latin1').decode(bytes);
      const r = _smimeVerifyPecReceipt(txt);
      results.push({ kind: tg.kind, ...r });
    } catch (e) {
      results.push({ kind: tg.kind, ok: null, status: 'error', details: 'lettura ricevuta fallita', signer: '' });
    }
  }
  const oks = results.filter(r => r.ok === true).length;
  const bads = results.filter(r => r.ok === false).length;
  const agidProviders = results.map(r => r.agidProvider).filter(Boolean);
  const allAgid = results.length > 0 && agidProviders.length === results.length;
  let agg;
  if (results.length && oks === results.length) agg = allAgid ? 'agid' : 'valid';
  else if (bads > 0) agg = 'invalid';
  else agg = 'unverifiable';
  // Gestore aggregato: se tutti i risultati indicano lo stesso provider, lo restituiamo;
  // altrimenti il primo non vuoto (caso raro acc/del firmate da gestori diversi).
  const uniqProviders = Array.from(new Set(agidProviders));
  const aggProvider = uniqProviders.length === 1 ? uniqProviders[0] : (uniqProviders[0] || null);
  const lines = results.map(r => `${r.kind === 'acc' ? 'Accettazione' : 'Consegna'}: ${r.details}${r.signer ? ' [' + r.signer + ']' : ''}`);
  return { status: agg, summary: lines.join('\n'), details: results, agidProvider: aggProvider };
}

function _pecSmimeBadge(status, agidProvider, direction) {
  // Restituisce HTML del badge per uno stato S/MIME.
  // status: 'agid' | 'valid' | 'invalid' | 'unverifiable' | 'absent'
  // agidProvider: nome del gestore PEC riconosciuto (opzionale, usato per tooltip su 'agid')
  // direction: 'in' | 'out' — se 'in' e status='absent', mostra chip "PEC ricevuta"
  if (status === 'agid') {
    const baseTitle = t('pecSmimeAgidTitle') || 'Firma S/MIME valida e gestore PEC riconosciuto come accreditato AgID (trust list offline bundlata nell\'app).';
    const fullTitle = agidProvider ? `${baseTitle}\n\nGestore: ${agidProvider}` : baseTitle;
    const label = t('pecSmimeAgid') || 'gestore accreditato AgID';
    return `<span title="${esc(fullTitle)}" style="display:inline-block;background:#bbf7d0;color:#14532d;border:1px solid #22c55e;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700" data-testid="badge-pec-smime-agid">✓✓ ${esc(label)}</span>`;
  }
  if (status === 'valid')        return `<span title="${esc(t('pecSmimeValidTitle') || 'Firma S/MIME crittograficamente valida (integrità del daticert.xml verificata).')}" style="display:inline-block;background:#dcfce7;color:#166534;border:1px solid #86efac;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600" data-testid="badge-pec-smime-valid">✓ ${esc(t('pecSmimeValid') || 'firma valida')}</span>`;
  if (status === 'invalid')      return `<span title="${esc(t('pecSmimeInvalidTitle') || 'Firma S/MIME non valida: la ricevuta potrebbe essere stata manomessa.')}" style="display:inline-block;background:#fee2e2;color:#991b1b;border:1px solid #fca5a5;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600" data-testid="badge-pec-smime-invalid">✗ ${esc(t('pecSmimeInvalid') || 'firma non valida')}</span>`;
  if (status === 'unverifiable') return `<span title="${esc(t('pecSmimeUnverifiableTitle') || 'Firma S/MIME non verificabile in questo ambiente offline.')}" style="display:inline-block;background:#fef3c7;color:#92400e;border:1px solid #fcd34d;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600" data-testid="badge-pec-smime-unverifiable">⚠ ${esc(t('pecSmimeUnverifiable') || 'firma non verificabile')}</span>`;
  if (status === 'absent') {
    // Per le PEC ricevute (in entrata) non ci sono ricevute firmate del
    // mittente: l'utente è il destinatario, non riceve daticert/smime delle
    // proprie comunicazioni. Mostriamo invece un chip neutro "PEC ricevuta"
    // per non confondere l'utente con un falso allarme.
    if (direction === 'in') {
      return `<span title="${esc(t('pecInBadgeTitle') || 'PEC ricevuta in entrata: le ricevute di accettazione/consegna firmate S/MIME sono prerogativa del mittente, non del destinatario.')}" style="display:inline-block;background:#dbeafe;color:#1e40af;border:1px solid #93c5fd;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600" data-testid="badge-pec-in">📩 ${esc(t('pecInBadge') || 'PEC ricevuta')}</span>`;
    }
    return `<span title="${esc(t('pecSmimeAbsentTitle') || 'Nessuna ricevuta firmata presente per questa PEC.')}" style="display:inline-block;background:#e5e7eb;color:#374151;border:1px solid #d1d5db;padding:2px 8px;border-radius:10px;font-size:11px" data-testid="badge-pec-smime-absent">— ${esc(t('pecSmimeAbsent') || 'nessuna ricevuta firmata')}</span>`;
  }
  return '';
}

function _pecExtractPostacertEml(root) {
  let found = null;
  const walk = (n) => {
    if (found || !n) return;
    if (n.parts) { for (const p of n.parts) walk(p); return; }
    const fn = (n.filename || '').toLowerCase();
    const ct = (n.contentType || '').toLowerCase();
    if (fn === 'postacert.eml' || ct === 'message/rfc822') found = n;
  };
  walk(root);
  if (!found || !found.bodyBytes) return null;
  try {
    const txt = new TextDecoder('latin1').decode(found.bodyBytes);
    return _emlParsePart(txt);
  } catch (e) { return null; }
}

// Estrae daticert.xml dalle ricevute PEC italiane. È SEMPRE presente nelle
// ricevute conformi al protocollo (DM 02/11/2005) e contiene i metadati reali
// del messaggio originale: mittente, destinatari, oggetto, data — anche
// quando postacert.eml manca o non è ricostruibile (S/MIME particolari).
function _pecExtractDaticertXml(root) {
  let found = null;
  const walk = (n) => {
    if (found || !n) return;
    if (n.parts) { for (const p of n.parts) walk(p); return; }
    const fn = (n.filename || '').toLowerCase();
    const ct = (n.contentType || '').toLowerCase();
    if (fn === 'daticert.xml' || (ct === 'application/xml' && fn === 'daticert.xml')) found = n;
  };
  walk(root);
  if (!found || !found.bodyBytes) return null;
  try {
    // daticert.xml è sempre UTF-8 per spec
    return new TextDecoder('utf-8').decode(found.bodyBytes);
  } catch (e) { return null; }
}

// Parser semplice (regex-based, no DOMParser per coerenza ambiente offline)
// del daticert.xml. Tollera attributi e namespace. Restituisce:
//   { mittente, destinatari[], oggetto, dateIso, messageId, gestoreEmittente, tipo }
function _pecParseDaticert(xml) {
  if (!xml || typeof xml !== 'string') return null;
  const tag = (name) => {
    const re = new RegExp('<' + name + '\\b[^>]*>([\\s\\S]*?)</' + name + '>', 'i');
    const m = xml.match(re);
    return m ? m[1].trim() : '';
  };
  const tagAll = (name) => {
    const re = new RegExp('<' + name + '\\b[^>]*>([\\s\\S]*?)</' + name + '>', 'gi');
    const out = []; let m;
    while ((m = re.exec(xml)) !== null) out.push(m[1].trim());
    return out;
  };
  const decodeXml = (s) => String(s || '')
    // Entità numeriche: &#x201C; (hex) e &#8220; (dec) — usate dai gestori
    // PEC per virgolette curve, accenti, ecc. Decodificarle è essenziale
    // per il matching subject orfano e per la visualizzazione corretta.
    .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => { try { return String.fromCodePoint(parseInt(h, 16)); } catch (_) { return ''; } })
    .replace(/&#(\d+);/g, (_, d) => { try { return String.fromCodePoint(parseInt(d, 10)); } catch (_) { return ''; } })
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');

  const mittente = decodeXml(tag('mittente')).toLowerCase();
  const destinatari = tagAll('destinatari').map(decodeXml).map(s => s.toLowerCase()).filter(Boolean);
  // Schema AgID: <destinatari tipo="certificato|esterno">indirizzo</destinatari>.
  // Distinguere i due tipi è essenziale per etichettare correttamente le ricevute
  // di consegna (gli "esterni" sono mail ordinarie, non ricevono ricevute PEC).
  const tagAllWithAttr = (name, attrName, attrValue) => {
    const re = new RegExp('<' + name + '\\b([^>]*)>([\\s\\S]*?)</' + name + '>', 'gi');
    const out = []; let m;
    while ((m = re.exec(xml)) !== null) {
      const attrs = m[1] || '';
      const am = attrs.match(new RegExp('\\b' + attrName + '\\s*=\\s*"([^"]*)"', 'i'));
      const v = am ? am[1].toLowerCase() : '';
      if (v === attrValue) out.push(m[2].trim());
    }
    return out;
  };
  const destinatariCertificati = tagAllWithAttr('destinatari', 'tipo', 'certificato')
    .map(decodeXml).map(s => s.toLowerCase()).filter(Boolean);
  const destinatariEsterni = tagAllWithAttr('destinatari', 'tipo', 'esterno')
    .map(decodeXml).map(s => s.toLowerCase()).filter(Boolean);
  // <consegna>indirizzo</consegna> presente solo nei daticert di tipo
  // "avvenuta-consegna" — è il destinatario specifico di QUELLA ricevuta.
  // consegnaDest: preserviamo il valore VERBATIM dal daticert.xml.
  // Vincolo legale: il contenuto certificato non va alterato. Il matching
  // case-insensitive con destinatari[] viene fatto al momento del confronto
  // dai consumer (che applicano .toLowerCase() a entrambi i lati).
  const consegnaDest = decodeXml(tag('consegna'));
  const oggetto = decodeXml(tag('oggetto'));
  const messageId = decodeXml(tag('msgid')).replace(/^<|>$/g, '');
  const gestoreEmittente = decodeXml(tag('gestore-emittente'));
  // tipo è attributo di <postacert tipo="...">
  const tipoMatch = xml.match(/<postacert\b[^>]*\btipo\s*=\s*"([^"]+)"/i);
  const tipo = tipoMatch ? tipoMatch[1].toLowerCase() : '';
  // <data zona="+0200"><giorno>20/04/2026</giorno><ora>14:30:00</ora></data>
  const giorno = decodeXml(tag('giorno'));
  const ora = decodeXml(tag('ora'));
  const zonaMatch = xml.match(/<data\b[^>]*\bzona\s*=\s*"([^"]+)"/i);
  const zona = zonaMatch ? zonaMatch[1] : '';
  let dateIso = '';
  if (giorno && ora) {
    const dm = giorno.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (dm) {
      const dd = dm[1].padStart(2, '0'), MM = dm[2].padStart(2, '0'), yyyy = dm[3];
      const tz = zona && /^[+-]\d{2}:?\d{2}$/.test(zona)
        ? (zona.length === 5 ? zona.slice(0,3)+':'+zona.slice(3) : zona)
        : 'Z';
      dateIso = `${yyyy}-${MM}-${dd}T${ora}${tz}`;
    }
  }
  return { mittente, destinatari, destinatariCertificati, destinatariEsterni, consegnaDest, oggetto, dateIso, messageId, gestoreEmittente, tipo };
}

function _pecIsLikelyPecManagerSender(addr) {
  // Per AgID, le ricevute PEC hanno mittente nella forma "posta-certificata@<dominio-gestore>".
  // Restringiamo il fallback a questo pattern (più, per tolleranza, "pec-noreply@" / "noreply@pec.").
  if (!addr) return false;
  const a = String(addr).toLowerCase();
  if (/^posta-certificata@/.test(a)) return true;
  if (/^pec-?noreply@/.test(a)) return true;
  if (/@pec\./.test(a)) return true;
  return false;
}

function _pecClassifyMboxMessage(root) {
  const xr = (_emlGetHeader(root.headers, 'x-ricevuta') || '').toLowerCase().trim();
  const subject = _emlDecodeMimeWord(_emlGetHeader(root.headers, 'subject') || '');
  const refMsgId = (_emlGetHeader(root.headers, 'x-riferimento-message-id') || '').trim().replace(/^<|>$/g, '');
  const messageId = (_emlGetHeader(root.headers, 'message-id') || '').trim().replace(/^<|>$/g, '');
  const fromRaw = _emlDecodeMimeWord(_emlGetHeader(root.headers, 'from') || '');
  const fromAddr = (_emlExtractAddresses(fromRaw)[0] || fromRaw || '').toLowerCase();
  const toRaw = _emlDecodeMimeWord(_emlGetHeader(root.headers, 'to') || '');
  const ccRaw = _emlDecodeMimeWord(_emlGetHeader(root.headers, 'cc') || '');
  const dateStr = _emlGetHeader(root.headers, 'date') || '';
  const dt = new Date(dateStr); const ts = isNaN(dt.getTime()) ? 0 : dt.getTime();
  let role = 'msg', deliveryStatus = '';
  if (xr) {
    deliveryStatus = xr;
    role = (xr === 'accettazione') ? 'acc' : 'del';
  } else if (_pecIsLikelyPecManagerSender(fromAddr)) {
    // Fallback solo se il mittente è verosimilmente un gestore PEC: evita falsi positivi
    // su mailbox miste contenenti email "ACCETTAZIONE: ..." non-PEC.
    const su = subject.toUpperCase().replace(/^\s+/, '');
    if (su.startsWith('ACCETTAZIONE:'))      { role = 'acc'; deliveryStatus = 'accettazione'; }
    else if (su.startsWith('CONSEGNA:') || su.startsWith('AVVENUTA CONSEGNA:')) { role = 'del'; deliveryStatus = 'avvenuta-consegna'; }
    else if (su.startsWith('PRESA IN CARICO:')) { role = 'del'; deliveryStatus = 'presa-in-carico'; }
    else if (su.startsWith('ERRORE CONSEGNA:') || su.startsWith('AVVISO DI MANCATA CONSEGNA:') || su.startsWith('PREAVVISO DI ERRORE CONSEGNA:')) { role = 'del'; deliveryStatus = 'errore-consegna'; }
  }
  // Bug fix PEC ricevute: rilevamento busta di trasporto in entrata.
  // Una PEC ricevuta arriva dal proprio gestore (`posta-certificata@<gestore>`)
  // con `Subject: POSTA CERTIFICATA: <oggetto vero>` e contiene un postacert.eml
  // allegato col messaggio reale. Senza questo flag il record veniva salvato
  // (o spesso scartato) coi dati del provider invece che del vero mittente,
  // e la direzione restava 'unknown' → invisibile col filtro "Ricevuta".
  const xTrasporto = (_emlGetHeader(root.headers, 'x-trasporto') || '').toLowerCase().trim();
  const subjUp = subject.toUpperCase().replace(/^\s+/, '');
  const isTransport = (role === 'msg') && (
    xTrasporto === 'posta-certificata' ||
    (_pecIsLikelyPecManagerSender(fromAddr) && subjUp.startsWith('POSTA CERTIFICATA:'))
  );
  const normalizedSubject = subject.replace(/^(POSTA CERTIFICATA|ACCETTAZIONE|CONSEGNA|AVVENUTA CONSEGNA|ERRORE CONSEGNA|PRESA IN CARICO|AVVISO DI MANCATA CONSEGNA|PREAVVISO DI ERRORE CONSEGNA)\s*:\s*/i, '').trim();
  // postacert non più estratto qui (pesante): viene riletto on-demand in fase di
  // save dal file. Se serve in pass 1 (per fallback matching) lo recupera il chiamante.
  return { role, deliveryStatus, isTransport, messageId, refMessageId: refMsgId, subject, normalizedSubject, fromAddr, fromRaw, toRaw, ccRaw, ts, dateStr };
}

// ───────────────────────────────────────────────────────────────────────────
// Task #195: calcolo della direzione PEC (Inviata/Ricevuta) — deterministico,
// basato sui ruoli delle ricevute presenti nel gruppo + override opzionale
// con la PEC del profilo utente.
// Restituisce { direction, reason } con direction ∈ 'sent' | 'received' | 'unknown'
// e reason = chiave i18n (es. 'pecDirReasonAcc') per il tooltip.
// ───────────────────────────────────────────────────────────────────────────
function _pecComputeDirectionFromGroup(group, profilePecRaw) {
  const profilePec = (profilePecRaw || '').trim().toLowerCase();
  // Override con il profilo utente (se configurato e match certo)
  if (profilePec) {
    const fromOrig = ((group.from || '') + '').toLowerCase();
    if (fromOrig && fromOrig === profilePec) {
      return { direction: 'sent', reason: 'pecDirReasonProfileFrom' };
    }
    // To del postacert può non essere noto in fase di grouping; lo deriviamo dai
    // postacertTo / msg.toRaw quando disponibili.
    const toCandidates = [];
    if (group.msg && group.msg.toRaw) toCandidates.push(group.msg.toRaw);
    if (group.acc && group.acc.postacertTo) toCandidates.push(group.acc.postacertTo);
    for (const d of (group.dels || [])) if (d && d.postacertTo) toCandidates.push(d.postacertTo);
    for (const raw of toCandidates) {
      const addrs = (typeof _emlExtractAddresses === 'function') ? _emlExtractAddresses(raw) : [String(raw)];
      for (const a of addrs) if ((a || '').toLowerCase() === profilePec) {
        return { direction: 'received', reason: 'pecDirReasonProfileTo' };
      }
    }
  }
  // Regola euristica deterministica (decision table esatta)
  // 1. acc presente               → sent  (l'accettazione è emessa solo al mittente)
  // 2. del presente (no acc)      → sent  (la consegna ritorna al mittente)
  // 3. solo msg da gestore PEC    → received (busta di trasporto consegnata)
  // 4. altrimenti                 → unknown (es. .eml standalone non identificabile)
  const hasAcc = !!group.acc;
  const hasDel = Array.isArray(group.dels) && group.dels.length > 0;
  const hasMsg = !!group.msg;
  if (hasAcc) return { direction: 'sent', reason: 'pecDirReasonAcc' };
  if (hasDel) return { direction: 'sent', reason: 'pecDirReasonDel' };
  if (hasMsg) {
    const fromOrig = ((group.msg && group.msg.fromAddr) || group.from || '').toLowerCase();
    if (typeof _pecIsLikelyPecManagerSender === 'function' && _pecIsLikelyPecManagerSender(fromOrig)) {
      return { direction: 'received', reason: 'pecDirReasonTransport' };
    }
  }
  return { direction: 'unknown', reason: 'pecDirReasonNone' };
}

// Variante per record già salvati su DB (legacy o post-import). Usa direttamente
// pec.direction se presente; altrimenti deriva da dataAccettazione/dataConsegna
// e dal profilo utente.
function _pecComputeDirectionFromRecord(pec, profilePecRaw) {
  // Il profilo utente ha SEMPRE la precedenza sul valore persistito: se l'utente
  // aggiorna la propria PEC dopo l'import, la classificazione si aggiorna senza
  // dover reimportare i record.
  const profilePec = (profilePecRaw || '').trim().toLowerCase();
  const mit = (pec && pec.mittente || '').toLowerCase();
  const dests = Array.isArray(pec && pec.destinatari) ? pec.destinatari.map(d => (d || '').toLowerCase()) : [];
  if (profilePec) {
    if (mit && mit === profilePec) return { direction: 'sent', reason: 'pecDirReasonProfileFrom' };
    if (dests.includes(profilePec)) return { direction: 'received', reason: 'pecDirReasonProfileTo' };
  }
  if (pec && (pec.direction === 'sent' || pec.direction === 'received' || pec.direction === 'unknown')) {
    return { direction: pec.direction, reason: pec.directionReason || 'pecDirReasonNone' };
  }
  if (pec && pec.dataAccettazione) return { direction: 'sent', reason: 'pecDirReasonAcc' };
  if (pec && pec.dataConsegna) return { direction: 'sent', reason: 'pecDirReasonDel' };
  // Fallback: senza ricevute, se il mittente è un gestore PEC è una ricevuta.
  if (typeof _pecIsLikelyPecManagerSender === 'function' && _pecIsLikelyPecManagerSender(mit)) {
    return { direction: 'received', reason: 'pecDirReasonTransport' };
  }
  return { direction: 'unknown', reason: 'pecDirReasonNone' };
}

function _pecDirectionBadge(direction, reasonKey, opts) {
  const small = opts && opts.small;
  const idSuffix = (opts && (opts.recordId !== undefined && opts.recordId !== null)) ? ('-' + opts.recordId) : '';
  const pad = small ? '1px 6px' : '2px 8px';
  const fs = small ? '10px' : '11px';
  const cfg = {
    sent:     { bg:'#dbeafe', fg:'#1e3a8a', bd:'#93c5fd', icon:'📤', label: t('pecDirSent') || 'Inviata',   ttlKey:'pecDirSentTitle' },
    received: { bg:'#dcfce7', fg:'#14532d', bd:'#86efac', icon:'📥', label: t('pecDirReceived') || 'Ricevuta', ttlKey:'pecDirReceivedTitle' },
    unknown:  { bg:'#f3f4f6', fg:'#4b5563', bd:'#d1d5db', icon:'❓', label: t('pecDirUnknown') || 'Sconosciuta', ttlKey:'pecDirUnknownTitle' },
  };
  const c = cfg[direction] || cfg.unknown;
  const reasonTxt = reasonKey ? (t(reasonKey) || '') : '';
  const baseTitle = t(c.ttlKey) || c.label;
  const title = reasonTxt ? (baseTitle + ' — ' + reasonTxt) : baseTitle;
  const tid = 'badge-pec-direction-' + direction + idSuffix;
  return `<span title="${esc(title)}" data-testid="${tid}" style="display:inline-block;background:${c.bg};color:${c.fg};border:1px solid ${c.bd};padding:${pad};border-radius:10px;font-size:${fs};font-weight:600;line-height:1.2">${c.icon} ${esc(c.label)}</span>`;
}

let _pecDirectionFilter = '';
try { _pecDirectionFilter = localStorage.getItem('pec_direction_filter') || ''; } catch (_) {}
let _pecProfileAddrCache = null;
async function _pecGetProfilePec() {
  if (_pecProfileAddrCache !== null) return _pecProfileAddrCache;
  try {
    const p = (typeof DB.getUserProfile === 'function') ? (await DB.getUserProfile()) : null;
    _pecProfileAddrCache = (p && p.pec ? String(p.pec).trim().toLowerCase() : '') || '';
  } catch (_) { _pecProfileAddrCache = ''; }
  return _pecProfileAddrCache;
}
function _pecInvalidateProfileCache() { _pecProfileAddrCache = null; }
function _pecSetDirectionFilter(v) {
  _pecDirectionFilter = v || '';
  try { localStorage.setItem('pec_direction_filter', _pecDirectionFilter); } catch (_) {}
  // Aggiorna lo stato visivo dei pulsanti del gruppo filtro (selected/non selected)
  const opts = ['', 'sent', 'received'];
  for (const o of opts) {
    const tid = 'button-pec-dir-filter-' + (o || 'all');
    const btn = document.querySelector(`[data-testid="${tid}"]`);
    if (!btn) continue;
    const active = (_pecDirectionFilter || '') === o;
    btn.style.background = active ? '#2563eb' : '#fff';
    btn.style.color = active ? '#fff' : '#374151';
    btn.style.borderColor = active ? '#1e3a8a' : '#d1d5db';
  }
  _pecRenderList();
}
window._pecSetDirectionFilter = _pecSetDirectionFilter;

function _pecGroupMboxMessages(items) {
  const byKey = new Map();
  const groups = [];
  // Pass 1: original messages (anche senza Message-ID: usiamo una chiave sintetica
  // così il messaggio è comunque selezionabile per l'import, anche se non potrà
  // essere accoppiato da ricevute via X-Riferimento-Message-ID).
  let synthIdx = 0;
  for (const it of items) {
    if (it.role === 'msg') {
      // Dedupe deterministica: se lo stesso Message-ID compare più volte nel
      // mbox (es. mbox concatenati), tieni la prima occorrenza e ignora le altre.
      if (it.messageId && byKey.has(it.messageId)) continue;
      const key = it.messageId || ('nomid:' + (++synthIdx) + ':' + (it.fromAddr || '') + ':' + (it.ts || 0));
      // Bug fix PEC ricevute: per le buste di trasporto in entrata (isTransport),
      // i metadati "veri" (mittente, oggetto, data, message-id) sono nel
      // postacert.eml interno. _pecAnalyzeAndPreview li ha già estratti in
      // it.postacert*; usiamoli qui per il rendering del gruppo invece degli
      // header esterni (`posta-certificata@<gestore>`).
      const useTransport = !!it.isTransport;
      const gFrom = (useTransport && it.postacertFrom) ? it.postacertFrom : it.fromAddr;
      const gSubj = (useTransport && it.postacertSubject) ? it.postacertSubject : (it.normalizedSubject || it.subject);
      const gTs   = (useTransport && it.postacertTs) ? it.postacertTs : it.ts;
      const gDateStr = (useTransport && it.postacertDateStr) ? it.postacertDateStr : it.dateStr;
      const g = { keyMsgId: key, msg: it, acc: null, accs: [], dels: [], from: gFrom, ts: gTs, dateStr: gDateStr, subject: gSubj, source: 'msg', matchMode: '', noMessageId: !it.messageId };
      groups.push(g);
      if (it.messageId) byKey.set(it.messageId, g);
    }
  }
  // Pass 2: receipts
  for (const it of items) {
    if (it.role === 'msg') continue;
    let g = it.refMessageId ? byKey.get(it.refMessageId) : null;
    let matchMode = g ? 'ref' : '';
    if (!g) {
      // Fallback: match receipt → original message via (originalSender + normalizedSubject + ±5 min).
      // Il "From" della ricevuta è "posta-certificata@gestore", quindi confrontiamo con l'eventuale
      // "From" estratto dal postacert.eml interno (che è il vero mittente originale).
      const normSubj = (s) => (s || '')
        // Decodifica entità numeriche per resilienza: alcuni gestori
        // emettono &#x201C; nel daticert mentre l'header MIME ha la
        // virgoletta reale — senza decodifica il match fallisce.
        .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => { try { return String.fromCodePoint(parseInt(h, 16)); } catch (_) { return ''; } })
        .replace(/&#(\d+);/g, (_, d) => { try { return String.fromCodePoint(parseInt(d, 10)); } catch (_) { return ''; } })
        .toLowerCase().replace(/\s+/g, ' ').trim();
      const subj = normSubj(it.normalizedSubject);
      const origFrom = (it.postacertFrom || '').toLowerCase();
      // Fallback strict: senza mittente originale verificabile NON facciamo auto-match,
      // la ricevuta resta orfana e l'utente decide manualmente. Evita falsi positivi
      // su mailbox dense con stesso oggetto. Il subject è normalizzato in
      // case-insensitive con collapse degli spazi per non perdere coppie valide.
      if (origFrom && subj) {
        const cands = groups.filter(gg => gg.source === 'msg'
          && normSubj(gg.subject) === subj
          && (gg.from || '').toLowerCase() === origFrom);
        g = cands.find(gg => Math.abs(gg.ts - it.ts) <= 5 * 60 * 1000) || null;
        if (g) matchMode = 'fallback';
      }
    }
    if (!g) {
      const key = it.refMessageId || ('orphan:' + (it.messageId || groups.length));
      g = byKey.get(key);
      if (!g) {
        g = { keyMsgId: key, msg: null, acc: null, accs: [], dels: [], from: '', ts: it.ts, dateStr: it.dateStr, subject: it.normalizedSubject, source: 'receipt-only', matchMode: 'orphan', refMissing: !!it.refMessageId };
        groups.push(g); byKey.set(key, g);
      }
    } else if (!g.matchMode || g.matchMode === 'ref') {
      g.matchMode = matchMode || g.matchMode;
    }
    if (it.role === 'acc') {
      // Aruba/InfoCert possono emettere accettazioni multiple per la stessa
      // PEC (es. .1.1 e .1.2 quando ci sono destinatari misti PEC + posta
      // ordinaria, o quando il gestore segmenta la spedizione). Le teniamo
      // tutte in g.accs[]; g.acc resta la prima per compatibilità.
      g.accs.push(it);
      if (!g.acc) g.acc = it;
    } else {
      g.dels.push(it);
    }
    // Per gli orfani usiamo i campi del postacert (subject/from/date/message-id)
    // pre-calcolati in pass 1 (vedi _pecMboxBeginParse).
    if (g.source === 'receipt-only') {
      if (it.postacertSubject) g.subject = it.postacertSubject;
      if (it.postacertFrom) g.from = it.postacertFrom.toLowerCase();
      if (it.postacertTs) { g.ts = it.postacertTs; g.dateStr = it.postacertDateStr || g.dateStr; }
      if (it.postacertMessageId) g.keyMsgId = it.postacertMessageId;
    }
  }
  groups.sort((a, b) => (b.ts || 0) - (a.ts || 0));
  return groups;
}

async function _pecMboxImportFlow() {
  const inp = document.createElement('input');
  inp.type = 'file';
  inp.accept = '.mbox,application/mbox,text/plain';
  inp.style.display = 'none';
  document.body.appendChild(inp);
  inp.addEventListener('change', async () => {
    const f = inp.files && inp.files[0];
    document.body.removeChild(inp);
    if (!f) return;
    window._pecImportSourceKind = 'mbox';
    await _pecMboxBeginParse(f);
  });
  inp.click();
}

// ───────────────────────────────────────────────────────────────────────────
// Import bulk PEC da cartella di file .eml (folder picker o drag&drop).
// Riusa lo stesso flusso di classificazione/grouping/preview/import del .mbox.
// ───────────────────────────────────────────────────────────────────────────
async function _pecEmlFolderImportFlow() {
  const inp = document.createElement('input');
  inp.type = 'file';
  inp.multiple = true;
  // webkitdirectory abilita il folder picker su Chromium/WebKit; resta multiplo come fallback.
  inp.setAttribute('webkitdirectory', '');
  inp.setAttribute('directory', '');
  inp.style.display = 'none';
  document.body.appendChild(inp);
  inp.addEventListener('change', async () => {
    const all = inp.files ? Array.from(inp.files) : [];
    document.body.removeChild(inp);
    const emls = all.filter(f => /\.eml$/i.test(f.name));
    if (!emls.length) {
      alert(t('pecImportEmlNoneFound') || 'Nessun file .eml trovato nella cartella selezionata.');
      return;
    }
    window._pecImportSourceKind = 'eml';
    await _pecEmlFilesBeginParse(emls);
  });
  inp.click();
}

async function _pecEmlFilesBeginParse(files) {
  // Modal di parsing (stessa UX del .mbox, ma il "totale" è il numero di file .eml)
  const ov = document.createElement('div');
  ov.id = 'pecMboxOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:11000;display:flex;align-items:center;justify-content:center';
  ov.innerHTML = `
    <div style="background:#fff;width:min(1280px,96vw);height:min(880px,94vh);border-radius:10px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.4)" data-testid="modal-pec-eml-folder">
      <div style="display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid #e5e7eb;background:#2563eb;color:#fff">
        <span style="font-size:22px">📁</span>
        <h2 style="margin:0;font-size:18px;flex:1">${t('pecImportEmlTitle') || 'Import bulk PEC da cartella .eml'}</h2>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('pecMboxOverlay').remove()" data-testid="button-pec-mbox-close">✕</button>
      </div>
      <div id="pecMboxBody" style="flex:1;overflow:auto;padding:16px;font-size:13px">
        <div data-testid="text-pec-mbox-progress" style="color:#374151">${t('pecImportEmlReading') || 'Lettura dei file .eml in corso…'} <b>${files.length}</b> ${t('pecImportEmlFiles') || 'file'}</div>
        <div id="pecMboxProgressBar" style="margin-top:10px;background:#e5e7eb;border-radius:6px;height:10px;overflow:hidden"><div id="pecMboxProgressFill" style="height:100%;width:0%;background:#2563eb;transition:width .15s"></div></div>
        <div id="pecMboxProgressText" style="margin-top:6px;color:#6b7280;font-size:12px">0%</div>
      </div>
      <div id="pecMboxFooter" style="padding:10px 16px;border-top:1px solid #e5e7eb;background:#f9fafb;display:flex;justify-content:flex-end;gap:8px">
        <button class="btn btn-sm" onclick="document.getElementById('pecMboxOverlay').remove()" data-testid="button-pec-mbox-cancel">${t('pecImportMboxCancel') || 'Annulla'}</button>
      </div>
    </div>`;
  document.body.appendChild(ov);

  const HEAD_MAX = 64 * 1024;
  const decoder = new TextDecoder('latin1');
  const items = [];
  for (let i = 0; i < files.length; i++) {
    const f = files[i];
    try {
      // Leggi soltanto la testata del file per classificazione/grouping (Pass A).
      // Il body verrà riletto on-demand in fase di save.
      const head = await f.slice(0, Math.min(HEAD_MAX, f.size)).arrayBuffer();
      const headersText = decoder.decode(head);
      const headerRoot = _emlParsePart(headersText + '\r\n\r\n');
      const cls = _pecClassifyMboxMessage(headerRoot);
      items.push({ ...cls, file: f, startByte: 0, endByte: f.size });
    } catch (e) {
      console.warn('eml: skip malformed file', f.name, e);
    }
    const pct = Math.round(((i + 1) / files.length) * 100);
    const fill = document.getElementById('pecMboxProgressFill');
    const txt = document.getElementById('pecMboxProgressText');
    if (fill) fill.style.width = pct + '%';
    if (txt) txt.textContent = `${pct}% — ${i + 1}/${files.length} ${t('pecImportMboxParsedNShort') || 'messaggi letti'}`;
    if (i % 25 === 24) await new Promise(r => setTimeout(r, 0));
  }

  if (!items.length) {
    document.getElementById('pecMboxBody').innerHTML = `<div style="color:#dc2626" data-testid="text-pec-mbox-empty">${t('pecImportEmlNoneValid') || 'Nessun file .eml valido trovato.'}</div>`;
    return;
  }
  await _pecAnalyzeAndPreview(items);
}

// Raccoglie ricorsivamente tutti i .eml da una lista di DataTransferItem (drag&drop).
// Supporta sia file singoli sia cartelle (Chrome/Edge/Firefox via webkitGetAsEntry).
async function _pecCollectEmlsFromDataTransfer(items) {
  const out = [];
  const walkEntry = async (entry) => {
    if (!entry) return;
    if (entry.isFile) {
      if (!/\.eml$/i.test(entry.name)) return;
      await new Promise((resolve) => {
        entry.file((file) => { out.push(file); resolve(); }, () => resolve());
      });
    } else if (entry.isDirectory) {
      const reader = entry.createReader();
      const readBatch = () => new Promise((resolve) => {
        reader.readEntries(async (entries) => {
          if (!entries.length) return resolve(false);
          for (const e of entries) await walkEntry(e);
          resolve(true);
        }, () => resolve(false));
      });
      while (await readBatch()) { /* loop until empty */ }
    }
  };
  const tasks = [];
  for (const it of items) {
    if (it.kind !== 'file') continue;
    const entry = it.webkitGetAsEntry ? it.webkitGetAsEntry() : null;
    if (entry) {
      tasks.push(walkEntry(entry));
    } else {
      const f = it.getAsFile && it.getAsFile();
      if (f && /\.eml$/i.test(f.name)) out.push(f);
    }
  }
  await Promise.all(tasks);
  return out;
}

function _pecArchiveAttachDnD() {
  const ov = document.getElementById('archivioPecOverlay');
  if (!ov || ov._pecDndAttached) return;
  ov._pecDndAttached = true;
  let depth = 0;
  let hint = null;
  const showHint = () => {
    if (hint) return;
    hint = document.createElement('div');
    hint.id = 'pecArchiveDndHint';
    hint.style.cssText = 'position:absolute;inset:0;background:rgba(37,99,235,.10);border:3px dashed #2563eb;display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:600;color:#1e40af;pointer-events:none;z-index:5';
    hint.textContent = t('pecImportEmlDropHere') || 'Rilascia qui i file .eml o una cartella per importarli in blocco';
    const card = ov.querySelector('div');
    if (card) { card.style.position = 'relative'; card.appendChild(hint); }
  };
  const hideHint = () => { if (hint) { hint.remove(); hint = null; } depth = 0; };
  ov.addEventListener('dragenter', (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return;
    e.preventDefault(); depth++; showHint();
  });
  ov.addEventListener('dragover', (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return;
    e.preventDefault(); e.dataTransfer.dropEffect = 'copy';
  });
  ov.addEventListener('dragleave', (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes('Files')) return;
    depth = Math.max(0, depth - 1); if (depth === 0) hideHint();
  });
  ov.addEventListener('drop', async (e) => {
    if (!e.dataTransfer) return;
    if (!Array.from(e.dataTransfer.types || []).includes('Files')) return;
    e.preventDefault(); hideHint();
    let emls = [];
    try {
      if (e.dataTransfer.items && e.dataTransfer.items.length) {
        emls = await _pecCollectEmlsFromDataTransfer(e.dataTransfer.items);
      } else if (e.dataTransfer.files) {
        emls = Array.from(e.dataTransfer.files).filter(f => /\.eml$/i.test(f.name));
      }
    } catch (err) {
      console.error('drop walk failed', err);
    }
    if (!emls.length) {
      alert(t('pecImportEmlNoneFound') || 'Nessun file .eml trovato nella cartella selezionata.');
      return;
    }
    window._pecImportSourceKind = 'eml';
    await _pecEmlFilesBeginParse(emls);
  });
}

// ───────────────────────────────────────────────────────────────────────────
// Import bulk PEC da archivio .zip dei gestori (Aruba/Postacert/Legalmail).
// Riusa la stessa pipeline (_pecAnalyzeAndPreview) del flusso .mbox / cartella
// .eml: ogni entry .eml dello .zip viene avvolta in un File in memoria così
// gli helper _pecReadMessageBytes / _pecReadMessageRoot lavorano per slice.
// ───────────────────────────────────────────────────────────────────────────
async function _pecZipImportFlow() {
  if (typeof JSZip === 'undefined') {
    alert(t('pecImportZipNoJSZip') || 'Libreria JSZip non disponibile.');
    return;
  }
  const inp = document.createElement('input');
  inp.type = 'file';
  inp.accept = '.zip,application/zip,application/x-zip-compressed';
  inp.style.display = 'none';
  document.body.appendChild(inp);
  inp.addEventListener('change', async () => {
    const f = inp.files && inp.files[0];
    document.body.removeChild(inp);
    if (!f) return;
    window._pecImportSourceKind = 'zip';
    await _pecZipBeginParse(f);
  });
  inp.click();
}

async function _pecZipBeginParse(file) {
  // Modal di parsing dedicato (UX coerente con .mbox e cartella .eml)
  const ov = document.createElement('div');
  ov.id = 'pecMboxOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:11000;display:flex;align-items:center;justify-content:center';
  ov.innerHTML = `
    <div style="background:#fff;width:min(1280px,96vw);height:min(880px,94vh);border-radius:10px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.4)" data-testid="modal-pec-zip">
      <div style="display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid #e5e7eb;background:#2563eb;color:#fff">
        <span style="font-size:22px">🗜️</span>
        <h2 style="margin:0;font-size:18px;flex:1">${t('pecImportZipTitle') || 'Import bulk PEC da archivio .zip dei gestori (Aruba/Postacert/Legalmail)'}</h2>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('pecMboxOverlay').remove()" data-testid="button-pec-mbox-close">✕</button>
      </div>
      <div id="pecMboxBody" style="flex:1;overflow:auto;padding:16px;font-size:13px">
        <div data-testid="text-pec-mbox-progress" style="color:#374151">${t('pecImportZipParsing') || 'Estrazione .eml dall\u2019archivio in corso\u2026'} <b>${(file.size / (1024 * 1024)).toFixed(1)} MB</b></div>
        <div id="pecMboxProgressBar" style="margin-top:10px;background:#e5e7eb;border-radius:6px;height:10px;overflow:hidden"><div id="pecMboxProgressFill" style="height:100%;width:0%;background:#2563eb;transition:width .15s"></div></div>
        <div id="pecMboxProgressText" style="margin-top:6px;color:#6b7280;font-size:12px">0%</div>
      </div>
      <div id="pecMboxFooter" style="padding:10px 16px;border-top:1px solid #e5e7eb;background:#f9fafb;display:flex;justify-content:flex-end;gap:8px">
        <button class="btn btn-sm" onclick="document.getElementById('pecMboxOverlay').remove()" data-testid="button-pec-mbox-cancel">${t('pecImportMboxCancel') || 'Annulla'}</button>
      </div>
    </div>`;
  document.body.appendChild(ov);

  const HEAD_MAX = 64 * 1024;
  const decoder = new TextDecoder('latin1');
  const items = [];
  try {
    const buf = await file.arrayBuffer();
    const zip = await JSZip.loadAsync(buf);
    // Filtra entries .eml (case-insensitive), saltando directory e file di sistema.
    const entries = [];
    zip.forEach((relPath, entry) => {
      if (entry.dir) return;
      const name = (entry.name || relPath || '').toLowerCase();
      if (!name.endsWith('.eml')) return;
      const base = name.split('/').pop() || '';
      if (base.startsWith('._') || base === '.ds_store') return;
      entries.push(entry);
    });
    const total = entries.length;
    if (!total) {
      document.getElementById('pecMboxBody').innerHTML = `<div style="color:#dc2626" data-testid="text-pec-mbox-empty">${t('pecImportZipNoEml') || 'Nessun file .eml trovato nell\u2019archivio .zip.'}</div>`;
      return;
    }
    for (let i = 0; i < entries.length; i++) {
      const entry = entries[i];
      try {
        const bytes = await entry.async('uint8array');
        // Estrai solo le header (≤64KB) per classificazione + grouping.
        const headLen = Math.min(bytes.byteLength, HEAD_MAX);
        const headTxt = decoder.decode(bytes.subarray(0, headLen));
        const headerRoot = _emlParsePart(headTxt + '\r\n\r\n');
        const cls = _pecClassifyMboxMessage(headerRoot);
        // Wrappa i bytes in un File così _pecReadMessageBytes(item.file) funziona
        // senza modifiche: slice 0..size restituisce esattamente l'.eml originale.
        const baseName = (entry.name.split('/').pop() || 'message.eml');
        const f = new File([bytes], baseName, { type: 'message/rfc822' });
        items.push({ ...cls, file: f, startByte: 0, endByte: f.size, zipEntryName: entry.name });
      } catch (e) { console.warn('zip: skip malformed .eml', entry && entry.name, e); }
      if (i % 8 === 7 || i === entries.length - 1) {
        const pct = Math.round(((i + 1) / total) * 100);
        const fill = document.getElementById('pecMboxProgressFill');
        const txt = document.getElementById('pecMboxProgressText');
        if (fill) fill.style.width = pct + '%';
        if (txt) txt.textContent = `${pct}% — ${i + 1}/${total} ${t('pecImportZipParsedNShort') || '.eml letti'}`;
        await new Promise(r => setTimeout(r, 0));
      }
    }
  } catch (e) {
    console.error('zip parse failed', e);
    alert((t('pecImportZipError') || 'Errore lettura .zip: ') + (e.message || e));
    const ovv = document.getElementById('pecMboxOverlay'); if (ovv) ovv.remove();
    return;
  }

  if (!items.length) {
    document.getElementById('pecMboxBody').innerHTML = `<div style="color:#dc2626" data-testid="text-pec-mbox-empty">${t('pecImportZipNoEml') || 'Nessun file .eml trovato nell\u2019archivio .zip.'}</div>`;
    return;
  }

  await _pecAnalyzeAndPreview(items);
}

async function _pecMboxBeginParse(file) {
  // Show parsing modal
  const ov = document.createElement('div');
  ov.id = 'pecMboxOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:11000;display:flex;align-items:center;justify-content:center';
  ov.innerHTML = `
    <div style="background:#fff;width:min(1280px,96vw);height:min(880px,94vh);border-radius:10px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.4)" data-testid="modal-pec-mbox">
      <div style="display:flex;align-items:center;gap:12px;padding:14px 18px;border-bottom:1px solid #e5e7eb;background:#2563eb;color:#fff">
        <span style="font-size:22px">📥</span>
        <h2 style="margin:0;font-size:18px;flex:1">${t('pecImportMboxTitle') || 'Import bulk PEC da file .mbox'}</h2>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('pecMboxOverlay').remove()" data-testid="button-pec-mbox-close">✕</button>
      </div>
      <div id="pecMboxBody" style="flex:1;overflow:auto;padding:16px;font-size:13px">
        <div data-testid="text-pec-mbox-progress" style="color:#374151">${t('pecImportMboxParsing') || 'Lettura del file in corso…'} <b>${(file.size / (1024 * 1024)).toFixed(1)} MB</b></div>
        <div id="pecMboxProgressBar" style="margin-top:10px;background:#e5e7eb;border-radius:6px;height:10px;overflow:hidden"><div id="pecMboxProgressFill" style="height:100%;width:0%;background:#2563eb;transition:width .15s"></div></div>
        <div id="pecMboxProgressText" style="margin-top:6px;color:#6b7280;font-size:12px">0%</div>
      </div>
      <div id="pecMboxFooter" style="padding:10px 16px;border-top:1px solid #e5e7eb;background:#f9fafb;display:flex;justify-content:flex-end;gap:8px">
        <button class="btn btn-sm" onclick="document.getElementById('pecMboxOverlay').remove()" data-testid="button-pec-mbox-cancel">${t('pecImportMboxCancel') || 'Annulla'}</button>
      </div>
    </div>`;
  document.body.appendChild(ov);

  // Ogni item generato porterà già il proprio File in item.file (vedi sotto):
  // non serve uno stato globale tipo _pecMboxSourceFile.
  const items = [];
  try {
    await _mboxParseStream(file,
      (info) => {
        try {
          // Pass A: parse SOLO le header (≤64KB) per classificazione + grouping.
          // Niente body in memoria.
          const headerRoot = _emlParsePart(info.headersText + '\r\n\r\n');
          const cls = _pecClassifyMboxMessage(headerRoot);
          // file = mbox: tutti gli item condividono lo stesso File, gli offset
          // identificano il messaggio dentro il mbox.
          const item = { ...cls, file, startByte: info.startByte, endByte: info.endByte };
          items.push(item);
        } catch (e) { console.warn('mbox: skip malformed message', e); }
      },
      (off, total, n) => {
        const pct = Math.round((off / total) * 100);
        const fill = document.getElementById('pecMboxProgressFill');
        const txt = document.getElementById('pecMboxProgressText');
        if (fill) fill.style.width = pct + '%';
        if (txt) txt.textContent = `${pct}% — ${n} ${t('pecImportMboxParsedNShort') || 'messaggi letti'}`;
      });
  } catch (e) {
    console.error('mbox parse failed', e);
    alert((t('pecImportMboxError') || 'Errore lettura .mbox: ') + (e.message || e));
    const ovv = document.getElementById('pecMboxOverlay'); if (ovv) ovv.remove();
    return;
  }

  if (!items.length) {
    document.getElementById('pecMboxBody').innerHTML = `<div style="color:#dc2626" data-testid="text-pec-mbox-empty">${t('pecImportMboxNoMessages') || 'Nessun messaggio trovato nel file .mbox.'}</div>`;
    return;
  }

  await _pecAnalyzeAndPreview(items);
}

// Pipeline condivisa post-parse: Phase A2 (postacert details) + grouping + dedupe + render.
// Funziona sia per import .mbox sia per import cartella .eml: ogni item porta
// il proprio File in item.file (quando manca, fallback al primo item disponibile).
async function _pecAnalyzeAndPreview(items) {
  // Bug fix PEC ricevute: includiamo nell'estrazione "postacert" anche i
  // messaggi di trasporto in entrata (`role === 'msg' && isTransport`),
  // altrimenti il modal di anteprima e il save userebbero il mittente del
  // provider (`posta-certificata@...`) invece del vero mittente.
  const receipts = items.filter(it => it.role !== 'msg' || it.isTransport);
  for (let i = 0; i < receipts.length; i++) {
    const it = receipts[i];
    try {
      const root = await _pecReadMessageRoot(null, it);
      const pc = _pecExtractPostacertEml(root);
      if (pc) {
        const pfromRaw = _emlDecodeMimeWord(_emlGetHeader(pc.headers, 'from') || '');
        it.postacertFrom = (_emlExtractAddresses(pfromRaw)[0] || pfromRaw || '').toLowerCase();
        it.postacertSubject = _emlDecodeMimeWord(_emlGetHeader(pc.headers, 'subject') || '');
        const pd = _emlGetHeader(pc.headers, 'date') || '';
        const pdt = pd ? new Date(pd) : null;
        if (pdt && !isNaN(pdt.getTime())) { it.postacertTs = pdt.getTime(); it.postacertDateStr = pd; }
        it.postacertMessageId = (_emlGetHeader(pc.headers, 'message-id') || '').trim().replace(/^<|>$/g, '');
      }
      // Daticert.xml: fonte CANONICA del mittente reale (es. cds_pat_deposito@pec.ga-cert.it)
      // anche quando postacert.eml manca o non è ricostruibile. Sovrascrive solo i
      // campi non ancora valorizzati per non degradare quando postacert è già OK.
      try {
        const dcXml = _pecExtractDaticertXml(root);
        if (dcXml) {
          const dc = _pecParseDaticert(dcXml);
          if (dc) {
            it.daticert = dc;
            if (!it.postacertFrom    && dc.mittente)    it.postacertFrom = dc.mittente;
            if (!it.postacertSubject && dc.oggetto)     it.postacertSubject = dc.oggetto;
            if (!it.postacertMessageId && dc.messageId) it.postacertMessageId = dc.messageId;
            if (!it.postacertTs && dc.dateIso) {
              const dt = new Date(dc.dateIso);
              if (!isNaN(dt.getTime())) { it.postacertTs = dt.getTime(); it.postacertDateStr = dc.dateIso; }
            }
          }
        }
      } catch (_) { /* daticert opzionale */ }
      // Per le ricevute di consegna estraiamo il destinatario SPECIFICO di
      // questa singola ricevuta (utile per tooltip in anteprima import).
      if (it.role === 'del') {
        let dest = (it.daticert && it.daticert.consegnaDest) || '';
        if (!dest) {
          try {
            const ext = _emlExtract(root);
            const txt = (ext && ext.textPlain) || '';
            let m = txt.match(/indirizzato a\s+["']?([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})["']?[\s\S]{0,80}?è stato consegnato/i);
            if (!m) m = txt.match(/addressed to\s+["']?([A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,})["']?[\s\S]{0,80}?has been delivered/i);
            if (m) dest = m[1].toLowerCase();
          } catch (_) {}
        }
        it.deliveryRecipient = dest || '';
      }
    } catch (e) { /* skip */ }
    if (i % 25 === 24) await new Promise(r => setTimeout(r, 0));
  }

  const groups = _pecGroupMboxMessages(items);
  const existing = await DB.getPecMessages();
  const existingByMsgId = new Map();
  for (const p of existing) {
    const k = (p.messageId || '').trim();
    if (k) existingByMsgId.set(k, p.id);
  }
  for (const g of groups) {
    g.duplicate = !!g.keyMsgId && existingByMsgId.has(g.keyMsgId);
    g.existingPecId = g.duplicate ? existingByMsgId.get(g.keyMsgId) : null;
  }

  // Pre-verifica firma S/MIME su acc + del di ogni gruppo, così il badge è
  // visibile in anteprima e l'utente può decidere skip/overwrite consapevolmente.
  for (let gi = 0; gi < groups.length; gi++) {
    try {
      const sm = await _smimeVerifyGroup(groups[gi]);
      groups[gi].smimeStatus = sm.status;
      groups[gi].smimeAgidProvider = sm.agidProvider || '';
    } catch (_) { groups[gi].smimeStatus = 'error'; groups[gi].smimeAgidProvider = ''; }
    if (gi % 10 === 9) await new Promise(r => setTimeout(r, 0));
  }

  // Pre-calcolo direzione (Inviata/Ricevuta) per ogni gruppo, così il badge
  // è visibile già in anteprima accanto alla data.
  try {
    const profilePec = await _pecGetProfilePec();
    for (const g of groups) {
      try {
        const dir = _pecComputeDirectionFromGroup(g, profilePec);
        g.direction = dir.direction;
        g.directionReason = dir.reason;
      } catch (_) { g.direction = 'unknown'; g.directionReason = 'pecDirReasonNone'; }
    }
  } catch (_) { /* profile non disponibile, lasciamo unknown */ }

  window._pecMboxGroups = groups;
  _pecMboxRenderPreview(groups, items.length);
}

function _pecMboxFmtDate(ts, fallback) {
  if (ts) { try { return new Date(ts).toLocaleString(); } catch (_) {} }
  return fallback || '';
}

function _pecMboxRenderPreview(groups, totalParsed) {
  const body = document.getElementById('pecMboxBody');
  const footer = document.getElementById('pecMboxFooter');
  if (!body || !footer) return;
  const escAttr = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const newCount = groups.filter(g => !g.duplicate).length;
  const dupCount = groups.filter(g => g.duplicate).length;
  const orphanCount = groups.filter(g => g.source === 'receipt-only').length;

  const rows = groups.map((g, i) => {
    const status = g.duplicate ? `<span style="color:#b45309;font-weight:600" title="${escAttr(g.keyMsgId)}">${t('pecImportMboxStatusDup') || 'Duplicato'}</span>`
      : (g.source === 'receipt-only' ? `<span style="color:#dc2626" title="${escAttr(g.matchMode === 'orphan' && g.refMissing ? 'Riferisce a Message-ID non presente nel mbox' : '')}">${t('pecImportMboxStatusOrphan') || 'Solo ricevute'}</span>`
        : `<span style="color:#16a34a;font-weight:600">${t('pecImportMboxStatusNew') || 'Nuova'}</span>`);
    const matchBadge = g.source === 'msg' && g.matchMode === 'fallback' ? `<span style="margin-left:4px;background:#fef3c7;color:#92400e;padding:1px 6px;border-radius:4px;font-size:10px" title="${escAttr(t('pecImportMboxMatchByFallback') || 'fallback')}">~</span>` : '';
    const selectCell = g.duplicate
      ? `<select class="mbox-row-action" data-idx="${i}" data-testid="select-mbox-action-${i}" style="font-size:11px;padding:2px 4px">
           <option value="skip" selected>${escAttr(t('pecImportMboxActionSkip') || 'Salta')}</option>
           <option value="overwrite">${escAttr(t('pecImportMboxActionOverwrite') || 'Sovrascrivi')}</option>
         </select>`
      : `<input type="checkbox" class="mbox-row-chk" data-idx="${i}" checked data-testid="checkbox-mbox-group-${i}">`;
    return `
      <tr data-testid="row-mbox-group-${i}" style="border-bottom:1px solid #e5e7eb">
        <td style="padding:6px;text-align:center">${selectCell}</td>
        <td style="padding:6px;font-size:12px">${(() => {
          const d = g.direction || 'unknown';
          const dirIcon = d === 'sent' ? '📤' : (d === 'received' ? '📥' : '❓');
          const dirLbl = d === 'sent' ? (t('pecDirSent') || 'Inviata') : (d === 'received' ? (t('pecDirReceived') || 'Ricevuta') : (t('pecDirUnknown') || 'Direzione sconosciuta'));
          return `<span title="${escAttr(dirLbl)}" style="margin-right:4px">${dirIcon}</span>`;
        })()}${escAttr(_pecMboxFmtDate(g.ts, g.dateStr))}</td>
        <td style="padding:6px;font-size:12px">${escAttr(g.from || '—')}</td>
        <td style="padding:6px;font-size:12px;max-width:380px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${escAttr(g.subject || '')}">${escAttr(g.subject || '—')} ${matchBadge}</td>
        <td style="padding:6px;text-align:center">${g.msg ? '✅' : '—'}</td>
        <td style="padding:6px;text-align:center">${(g.accs && g.accs.length) ? (g.accs.length === 1 ? '✅' : '✅×' + g.accs.length) : (g.acc ? '✅' : '—')}</td>
        <td style="padding:6px;text-align:center" title="${escAttr(g.dels.length ? g.dels.map(d => `• ${d.deliveryRecipient || (t('unknownRecipient') || 'destinatario sconosciuto')}${d.deliveryStatus ? ' [' + d.deliveryStatus + ']' : ''}`).join('\n') : '')}">${g.dels.length || '—'}</td>
        <td style="padding:6px;text-align:center">${g.smimeStatus ? _pecSmimeBadge(g.smimeStatus, g.smimeAgidProvider, g.direction === 'received' ? 'in' : (g.direction === 'sent' ? 'out' : '')) : (g.direction === 'received' ? _pecSmimeBadge('absent', null, 'in') : '—')}</td>
        <td style="padding:6px;font-size:12px">${status}</td>
      </tr>`;
  }).join('');

  body.innerHTML = `
    <div style="margin-bottom:10px;display:flex;gap:14px;align-items:center;flex-wrap:wrap;color:#374151">
      <div data-testid="text-mbox-summary"><b>${groups.length}</b> ${t('pecImportMboxGroupsHeader') || 'gruppi PEC riconosciuti'} (da ${totalParsed} messaggi) — <span style="color:#16a34a">${newCount} ${t('pecImportMboxStatusNew') || 'nuove'}</span> · <span style="color:#b45309">${dupCount} ${t('pecImportMboxStatusDup') || 'duplicate'}</span> · <span style="color:#dc2626">${orphanCount} ${t('pecImportMboxStatusOrphan') || 'solo ricevute'}</span></div>
      <button class="btn btn-xs" onclick="document.querySelectorAll('.mbox-row-chk').forEach(c=>c.checked=true)" data-testid="button-mbox-select-all">${t('pecImportMboxSelectAll') || 'Seleziona tutti'}</button>
      <button class="btn btn-xs" onclick="document.querySelectorAll('.mbox-row-chk').forEach(c=>c.checked=false)" data-testid="button-mbox-deselect-all">${t('pecImportMboxDeselectAll') || 'Deseleziona tutti'}</button>
    </div>
    <div style="border:1px solid #e5e7eb;border-radius:6px;overflow:auto;max-height:calc(94vh - 270px)">
      <table style="width:100%;border-collapse:collapse;font-size:13px">
        <thead style="position:sticky;top:0;background:#f3f4f6;z-index:1">
          <tr>
            <th style="padding:6px;text-align:center;font-weight:600">${t('pecImportMboxColSelect') || 'Importa'}</th>
            <th style="padding:6px;text-align:left;font-weight:600">${t('pecImportMboxColDate') || 'Data'}</th>
            <th style="padding:6px;text-align:left;font-weight:600">${t('pecImportMboxColFrom') || 'Mittente'}</th>
            <th style="padding:6px;text-align:left;font-weight:600">${t('pecImportMboxColSubject') || 'Oggetto'}</th>
            <th style="padding:6px;text-align:center;font-weight:600" title="${t('pecImportMboxColMsgT') || 'Messaggio originale presente'}">${t('pecImportMboxColMsg') || 'Msg'}</th>
            <th style="padding:6px;text-align:center;font-weight:600" title="${t('pecImportMboxColAccT') || 'Ricevuta accettazione'}">${t('pecImportMboxColAcc') || 'Acc.'}</th>
            <th style="padding:6px;text-align:center;font-weight:600" title="${t('pecImportMboxColDelT') || 'Ricevute consegna'}">${t('pecImportMboxColDel') || 'Cons.'}</th>
            <th style="padding:6px;text-align:center;font-weight:600" title="${t('pecImportMboxColSmimeT') || 'Esito verifica firma S/MIME delle ricevute'}">${t('pecImportMboxColSmime') || 'Firma'}</th>
            <th style="padding:6px;text-align:left;font-weight:600">${t('pecImportMboxColStatus') || 'Stato'}</th>
          </tr>
        </thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <div style="margin-top:10px;padding:8px 10px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:6px;font-size:12px;color:#166534" data-testid="text-mbox-integrity-note">
      ${t('pecImportMboxIntegrityNote') || 'I file .eml verranno salvati invariati (bytes originali, hash SHA-256). Per ogni PEC viene registrata in nota la modalità di abbinamento automatico.'}
    </div>`;

  footer.innerHTML = `
    <button class="btn btn-sm" onclick="document.getElementById('pecMboxOverlay').remove()" data-testid="button-pec-mbox-cancel">${t('pecImportMboxCancel') || 'Annulla'}</button>
    <button class="btn btn-sm btn-primary" onclick="_pecMboxConfirmImport()" data-testid="button-pec-mbox-confirm">${t('pecImportMboxConfirm') || 'Importa selezionate'}</button>`;
}

async function _pecMboxConfirmImport() {
  const groups = window._pecMboxGroups || [];
  const checks = document.querySelectorAll('.mbox-row-chk');
  const selects = document.querySelectorAll('.mbox-row-action');
  // queue: { group, mode: 'create' | 'overwrite' }
  const queue = [];
  let skippedDup = 0;
  checks.forEach(c => { if (c.checked) queue.push({ group: groups[parseInt(c.dataset.idx, 10)], mode: 'create' }); });
  selects.forEach(s => {
    if (s.value === 'overwrite') {
      queue.push({ group: groups[parseInt(s.dataset.idx, 10)], mode: 'overwrite' });
    } else {
      skippedDup++;
    }
  });
  if (!queue.length) { alert(t('pecImportMboxNothingSelected') || 'Seleziona almeno un gruppo da importare.'); return; }
  const selected = queue;

  const body = document.getElementById('pecMboxBody');
  const footer = document.getElementById('pecMboxFooter');
  if (footer) footer.innerHTML = '';
  body.innerHTML = `
    <div data-testid="text-pec-mbox-importing" style="color:#374151">${t('pecImportMboxImporting') || 'Importazione in corso…'}</div>
    <div style="margin-top:10px;background:#e5e7eb;border-radius:6px;height:10px;overflow:hidden"><div id="mboxImpFill" style="height:100%;width:0%;background:#2563eb;transition:width .15s"></div></div>
    <div id="mboxImpText" style="margin-top:6px;color:#6b7280;font-size:12px">0 / ${selected.length}</div>
    <ul id="mboxImpLog" style="margin-top:10px;padding-left:18px;font-size:12px;color:#374151;max-height:calc(94vh - 280px);overflow:auto"></ul>`;

  let ok = 0, over = 0, err = 0, orphansImported = 0;
  // Conta tutti gli orfani non selezionati per l'import (rimangono non collegati a un originale)
  const selectedIdx = new Set(selected.map(s => groups.indexOf(s.group)));
  let orphansUnlinked = 0;
  for (let k = 0; k < groups.length; k++) {
    if (groups[k].source === 'receipt-only' && !selectedIdx.has(k)) orphansUnlinked++;
  }
  for (let i = 0; i < selected.length; i++) {
    const { group: g, mode } = selected[i];
    try {
      if (mode === 'overwrite' && g.existingPecId) {
        // Safer overwrite: prima crea il nuovo record, poi rimuovi quello vecchio.
        // Se la creazione fallisce, il record originale resta intatto.
        await _pecMboxSaveGroup(g);
        try { await DB.deletePecMessage(g.existingPecId); }
        catch (delErr) {
          console.warn('overwrite: vecchio record non rimosso', delErr);
          const li = document.createElement('li');
          li.style.color = '#b45309';
          li.textContent = `⚠ ${g.subject || g.keyMsgId}: ${t('pecImportMboxOverwriteDelFailed') || 'nuovo record creato ma il duplicato precedente non è stato rimosso (resta in archivio).'}`;
          document.getElementById('mboxImpLog').appendChild(li);
        }
        over++;
      } else {
        await _pecMboxSaveGroup(g);
        ok++;
      }
      if (g.source === 'receipt-only') orphansImported++;
    } catch (e) {
      console.error('mbox import group failed', e);
      err++;
      const li = document.createElement('li');
      li.style.color = '#dc2626';
      li.textContent = `❌ ${g.subject || g.keyMsgId}: ${e.message || e}`;
      document.getElementById('mboxImpLog').appendChild(li);
    }
    const fill = document.getElementById('mboxImpFill');
    const txt = document.getElementById('mboxImpText');
    if (fill) fill.style.width = Math.round(((i + 1) / selected.length) * 100) + '%';
    if (txt) txt.textContent = `${i + 1} / ${selected.length}`;
    await new Promise(r => setTimeout(r, 0));
  }
  const summary = document.createElement('div');
  summary.style.cssText = 'margin-top:12px;padding:10px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:6px;color:#166534;font-weight:600';
  summary.dataset.testid = 'text-mbox-import-result';
  summary.textContent = (t('pecImportMboxResultDone') || 'Import completato: {0} create, {1} sovrascritte, {2} duplicate saltate, {3} gruppi orfani non importati, {4} con errori.')
    .replace('{0}', ok).replace('{1}', over).replace('{2}', skippedDup).replace('{3}', orphansUnlinked).replace('{4}', err);
  if (orphansImported > 0) {
    const note = document.createElement('div');
    note.style.cssText = 'margin-top:6px;color:#92400e;font-size:12px';
    note.textContent = (t('pecImportMboxResultOrphansImported') || 'Nota: {0} gruppi importati contengono solo ricevute (messaggio originale assente nel mbox).')
      .replace('{0}', orphansImported);
    body.appendChild(note);
  }
  body.appendChild(summary);
  if (footer) footer.innerHTML = `<button class="btn btn-sm btn-primary" onclick="(function(){var o=document.getElementById('pecMboxOverlay');if(o)o.remove();_pecRenderList&&_pecRenderList();})()" data-testid="button-pec-mbox-done">${t('close') || 'Chiudi'}</button>`;
}

async function _pecMboxSaveGroup(g) {
  // Pass B (lazy): rileggi dalla sorgente solo i messaggi del gruppo selezionato.
  // Ogni item porta il proprio File in item.file (per .mbox è sempre lo stesso,
  // per cartella .eml è il singolo .eml, per .zip è un File costruito sui bytes
  // della entry .eml estratta dall'archivio).
  const msgRoot = g.msg ? await _pecReadMessageRoot(null, g.msg) : null;
  const accRoot = g.acc ? await _pecReadMessageRoot(null, g.acc) : null;
  const delRoots = [];
  for (const d of g.dels) delRoots.push(await _pecReadMessageRoot(null, d));
  // Determine canonical headers source: original message > postacert.eml inside acc/del
  // > headers ESTERNE della ricevuta stessa (ultima risorsa: il "From" sarà
  // posta-certificata@gestore, ma le date e il subject sono comunque utili).
  let headSource = msgRoot;
  let headSourceKind = msgRoot ? 'msg' : '';
  // Bug fix PEC ricevute: se il msg è una busta di trasporto in entrata
  // (`isTransport` settato in classify), il "vero" messaggio è dentro il
  // postacert.eml allegato. Senza questo unwrap salveremmo il record con
  // From=`posta-certificata@<gestore>` invece del mittente reale.
  if (msgRoot && g.msg && g.msg.isTransport) {
    const pcInner = _pecExtractPostacertEml(msgRoot);
    if (pcInner) { headSource = pcInner; headSourceKind = 'transport-postacert'; }
  }
  const recRoot = accRoot || delRoots[0] || null;
  if (!headSource && recRoot) {
    const pc = _pecExtractPostacertEml(recRoot);
    if (pc) { headSource = pc; headSourceKind = 'postacert'; }
    else    { headSource = recRoot; headSourceKind = 'receipt-outer'; }
  }
  // Daticert.xml: fonte autoritativa del mittente/destinatari/oggetto/data REALI
  // del messaggio originale. Lo leggiamo SEMPRE (se presente) e lo usiamo per
  // sovrascrivere il "From" del provider quando headSource = receipt-outer
  // (es. cds_pat_deposito@pec.ga-cert.it invece di posta-certificata@gestore).
  let dcParsed = null;
  if (recRoot) {
    try {
      const dcXml = _pecExtractDaticertXml(recRoot);
      if (dcXml) dcParsed = _pecParseDaticert(dcXml);
    } catch (_) { /* daticert opzionale */ }
  }
  const hget = (n) => headSource ? _emlDecodeMimeWord(_emlGetHeader(headSource.headers, n) || '') : '';
  const fromRawHdr = hget('from');
  // Se headSource è la busta esterna della ricevuta, il "From" è del provider:
  // preferisci il mittente reale dal daticert.xml.
  const fromRaw = (headSourceKind === 'receipt-outer' && dcParsed && dcParsed.mittente)
    ? dcParsed.mittente
    : fromRawHdr;
  const toRawHdr = hget('to');
  const toRaw = (headSourceKind === 'receipt-outer' && dcParsed && dcParsed.destinatari.length)
    ? dcParsed.destinatari.join(', ')
    : toRawHdr;
  const ccRaw = hget('cc');
  // Subject: preferisci daticert (ha l'oggetto originale, non "POSTA CERTIFICATA: ...")
  // Fallback per transport-postacert: se il subject del postacert.eml è vuoto
  // (PEC senza oggetto, lecito secondo specifica), prova g.subject che può
  // contenere il subject della busta esterna ("POSTA CERTIFICATA: ...").
  const subjPostacert = hget('subject') || '';
  const subj = (dcParsed && dcParsed.oggetto)
    ? dcParsed.oggetto
    : (subjPostacert || g.subject || '');
  // Data: in receipt-outer, l'header Date è quella della ricevuta del provider,
  // NON quella del messaggio originale. Daticert.xml ha la data ufficiale.
  const dateStr = (headSourceKind === 'receipt-outer' && dcParsed && dcParsed.dateIso)
    ? dcParsed.dateIso
    : ((headSource ? _emlGetHeader(headSource.headers, 'date') : null) || g.dateStr || '');
  const messageId = (
    (dcParsed && dcParsed.messageId)
    || (headSourceKind !== 'receipt-outer' && headSource ? (_emlGetHeader(headSource.headers, 'message-id') || '') : '')
  ).trim().replace(/^<|>$/g, '') || g.keyMsgId || '';
  const fromAddrs = _emlExtractAddresses(fromRaw);
  const toAddrs = _emlExtractAddresses(toRaw);
  const ccAddrs = _emlExtractAddresses(ccRaw);
  const dataInvio = _emlParseDate(dateStr);
  // Body text from headSource (original or postacert)
  let corpoTesto = '';
  if (headSource) {
    const ext = _emlExtract(headSource);
    corpoTesto = ext.textPlain ? ext.textPlain.trim() : (ext.textHtml ? _pecHtmlToText(ext.textHtml) : '');
  }
  const dataAcc = g.acc ? _emlParseDate(g.acc.dateStr) : '';
  const dataDel = (g.dels.find(d => d.deliveryStatus === 'avvenuta-consegna') || g.dels[0])
    ? _emlParseDate((g.dels.find(d => d.deliveryStatus === 'avvenuta-consegna') || g.dels[0]).dateStr) : '';

  // Match note
  let matchTxt;
  if (g.source === 'receipt-only') {
    matchTxt = t('pecImportMboxMatchOrphan') || 'solo ricevute (originale assente nel mbox)';
  } else if (g.matchMode === 'ref') {
    matchTxt = t('pecImportMboxMatchByRef') || 'X-Riferimento-Message-ID';
  } else if (g.matchMode === 'fallback') {
    matchTxt = t('pecImportMboxMatchByFallback') || 'fallback (mittente + oggetto + finestra temporale)';
  } else {
    // Originale presente nel mbox ma nessuna ricevuta da accoppiare
    matchTxt = t('pecImportMboxMatchMsgOnly') || 'messaggio originale (nessuna ricevuta da accoppiare nel mbox)';
  }
  const isZipSource = window._pecImportSourceKind === 'zip'
    || !!((g.msg && g.msg.zipEntryName) || (g.acc && g.acc.zipEntryName) || (g.dels && g.dels.some(d => d && d.zipEntryName)));
  const srcLabel = isZipSource
    ? (t('pecImportSourceZip') || 'archivio .zip')
    : window._pecImportSourceKind === 'eml'
      ? (t('pecImportSourceEmlFolder') || 'cartella .eml')
      : (t('pecImportSourceMbox') || '.mbox');
  const noteAuto = (t('pecImportMboxNoteAutoSrc') || 'Import automatico da {1} — abbinamento via {0}')
    .replace('{0}', matchTxt).replace('{1}', srcLabel);
  let note = noteAuto;
  if (ccAddrs.length) note += '\nCc: ' + ccAddrs.join('; ');
  if (g.dels.length) {
    const statuses = g.dels.map(d => d.deliveryStatus).filter(Boolean);
    if (statuses.length) note += '\n' + (t('pecImportMboxDelStatuses') || 'Stati ricevute consegna') + ': ' + statuses.join(', ');
  }

  // Fallback robusti: i campi del gruppo (g.from/g.dateStr/g.ts/g.subject)
  // sono già stati popolati durante _pecAnalyzeAndPreview (sia dal postacert.eml
  // per gli orfani sia dalle headers proprie per i messaggi originali).
  // Senza questi fallback, mailbox con ricevute non in formato canonico
  // (postacert.eml mancante o nascosto in S/MIME) facevano fallire 100% degli import.
  const fallbackDateIso = (g.ts && !isNaN(g.ts)) ? new Date(g.ts).toISOString() : '';
  const data = {
    mittente: fromAddrs[0] || fromRaw || g.from || '',
    destinatario: toAddrs[0] || '',
    destinatari: toAddrs,
    dataInvio: dataInvio || fallbackDateIso || '',
    dataAccettazione: dataAcc || null,
    dataConsegna: dataDel || null,
    messageId,
    oggetto: (() => {
      const cleaned = (subj || g.subject || '').replace(/^POSTA CERTIFICATA\s*:\s*/i, '').trim();
      // Una PEC senza oggetto è lecita secondo specifica AgID. Non bloccare
      // l'import: salva placeholder leggibile invece di stringa vuota.
      return cleaned || (t('pecNoSubject') || '(senza oggetto)');
    })(),
    note,
    corpoTesto,
    lingua: 'it',
    soggettiCollegati: [],
  };
  // L'oggetto NON è obbligatorio: una PEC senza oggetto è lecita (AgID),
  // viene salvata col placeholder "(senza oggetto)". Solo mittente e data
  // sono dati minimi indispensabili per identificare la PEC.
  if (!data.mittente || !data.dataInvio) {
    const missing = [];
    if (!data.mittente)  missing.push('mittente');
    if (!data.dataInvio) missing.push('data');
    const base = t('pecImportMboxInvalidGroup') || 'gruppo PEC senza dati minimi (mittente/data)';
    throw new Error(`${base} [mancanti: ${missing.join(', ')}; sorgente headers: ${headSourceKind || 'nessuna'}]`);
  }
  data.year = _pecYearFromDate(data.dataInvio);
  // Task #195: calcola e persiste la direzione (Inviata/Ricevuta) sul record
  try {
    const profilePec = await _pecGetProfilePec();
    const dir = _pecComputeDirectionFromGroup(g, profilePec);
    data.direction = dir.direction;
    data.directionReason = dir.reason;
  } catch (_) { data.direction = 'unknown'; data.directionReason = 'pecDirReasonNone'; }

  const pecId = await DB.createPecMessage(data);
  const lang = data.lingua;

  // Save raw EML files: rileggi i byte ORIGINALI dal file mbox via offset.
  const saveBytes = async (item, role, suggestedName) => {
    if (!item) return;
    const bytes = await _pecReadMessageBytes(null, item);
    const f = new File([bytes], suggestedName, { type: 'message/rfc822' });
    await storeFileForEntity(f, 'pec', pecId, lang, {}, role);
  };
  if (g.msg) await saveBytes(g.msg, 'pec_msg', 'messaggio.eml');
  // Numerazione progressiva delle accettazioni multiple (Aruba .1.1/.1.2,
  // ecc.). Backward-compat: se accs è vuoto ma g.acc presente, salviamo
  // quella singola.
  const accsToSave = (g.accs && g.accs.length) ? g.accs : (g.acc ? [g.acc] : []);
  const existingAccs = (await DB.getEntityFiles('pec', pecId))
    .filter(f => f.fileRole === 'pec_acc').length;
  for (let ai = 0; ai < accsToSave.length; ai++) {
    const a = accsToSave[ai];
    const seq = existingAccs + ai + 1;
    const bytes = await _pecReadMessageBytes(null, a);
    const f = new File([bytes], `accettazione-${String(seq).padStart(2, '0')}.eml`, { type: 'message/rfc822' });
    await storeFileForEntity(f, 'pec', pecId, lang, {}, 'pec_acc', { accIdx: seq });
  }
  // Numerazione progressiva univoca per le ricevute di consegna: partiamo dal
  // conteggio di eventuali pec_del già esistenti (caso di re-import sulla stessa
  // PEC) e usiamo zero-pad a 2 cifre → consegna-01.eml, consegna-02.eml, ...
  // Evita collisioni di nome che causerebbero sovrascritture sul filesystem.
  const existingDels = (await DB.getEntityFiles('pec', pecId))
    .filter(f => f.fileRole === 'pec_del').length;
  for (let di = 0; di < g.dels.length; di++) {
    const d = g.dels[di];
    const seq = existingDels + di + 1;
    const bytes = await _pecReadMessageBytes(null, d);
    const f = new File([bytes], `consegna-${String(seq).padStart(2, '0')}.eml`, { type: 'message/rfc822' });
    await storeFileForEntity(f, 'pec', pecId, lang, {}, 'pec_del', { delIdx: seq });
  }

  // Extract attachments from headSource (original or postacert) and persist
  let attIdx = 0;
  if (headSource) {
    const ext = _emlExtract(headSource);
    for (const a of ext.attachments || []) {
      attIdx++;
      const b = new Blob([a.bytes], { type: a.contentType || 'application/octet-stream' });
      const file = new File([b], a.filename || ('allegato-' + attIdx), { type: a.contentType || 'application/octet-stream' });
      await storeFileForEntity(file, 'pec', pecId, lang, {}, 'pec_attach', { attachIdx: attIdx });
    }
  }
  // Verifica firma S/MIME delle ricevute (acc + del) e salva esito sulla PEC.
  try {
    const sm = await _smimeVerifyGroup(g);
    const pecRec = await DB.getPecMessage(pecId);
    if (pecRec) {
      pecRec.smimeStatus = sm.status;
      pecRec.smimeAgidProvider = sm.agidProvider || '';
      const lbl = {
        agid: '✓✓ firma valida — gestore accreditato AgID',
        valid: '✓ firma valida',
        invalid: '✗ firma non valida',
        unverifiable: '⚠ firma non verificabile',
        absent: '— nessuna ricevuta firmata'
      }[sm.status] || sm.status;
      const provLine = sm.agidProvider ? `\nGestore PEC riconosciuto: ${sm.agidProvider}` : '';
      const append = `\n\n[S/MIME] ${lbl}${provLine}${sm.summary ? '\n' + sm.summary : ''}`;
      pecRec.note = (pecRec.note || '') + append;
      await DB.updatePecMessage(pecId, pecRec);
    }
  } catch (e) { /* non bloccare l'import per errori di verifica */ }
  return pecId;
}

/* ===== Task #194: Svuotamento totale archivio PEC con conferma a codice ===== */
function _pecWipeGenCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let s = '';
  for (let i = 0; i < 4; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return 'WIPE-' + s + '-PEC';
}
function _pecWipeFmtBytes(b) {
  if (!b || b <= 0) return '0 B';
  const u = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0; let n = b;
  while (n >= 1024 && i < u.length - 1) { n /= 1024; i++; }
  return n.toFixed(n >= 100 || i === 0 ? 0 : (n >= 10 ? 1 : 2)) + ' ' + u[i];
}
async function _pecWipeShowConfirm() {
  // Chiudi eventuale modale precedente
  const prev = document.getElementById('pecWipeOverlay');
  if (prev) prev.remove();
  // Calcola riepilogo
  const allPec = await DB.getPecMessages();
  let pecFiles = [];
  try { pecFiles = await db.files.where('entityType').equals('pec').toArray(); } catch (_) {}
  const fileCount = pecFiles.length;
  let bytes = 0;
  for (const f of pecFiles) if (typeof f.size === 'number' && f.size > 0) bytes += f.size;
  const pecCount = allPec.length;
  if (pecCount === 0 && fileCount === 0) {
    alert(t('pecWipeNoData') || 'Archivio PEC già vuoto.');
    return;
  }
  const code = _pecWipeGenCode();
  window._pecWipeCode = code;
  const ov = document.createElement('div');
  ov.id = 'pecWipeOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:10005;display:flex;align-items:center;justify-content:center';
  ov.innerHTML = `
    <div style="background:#fff;width:min(560px,94vw);border-radius:10px;overflow:hidden;box-shadow:0 12px 40px rgba(0,0,0,.5);border:2px solid #7f1d1d">
      <div style="display:flex;align-items:center;gap:10px;padding:14px 18px;background:#7f1d1d;color:#fff">
        <span style="font-size:24px">⚠️</span>
        <h2 style="margin:0;font-size:17px;flex:1">${esc(t('pecWipeTitle') || 'Svuotamento archivio PEC')}</h2>
        <button class="btn btn-xs" style="background:transparent;color:#fff;border:1px solid #fff" onclick="document.getElementById('pecWipeOverlay').remove()" data-testid="button-pec-wipe-cancel-x">✕</button>
      </div>
      <div style="padding:18px;font-size:14px;color:#1f2937">
        <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:6px;padding:10px;margin-bottom:14px;color:#7f1d1d">
          <strong>${esc(t('pecWipeWarning') || "Stai per eliminare definitivamente tutti i messaggi PEC e i loro file fisici. L'operazione non è reversibile.")}</strong>
        </div>
        <div style="margin-bottom:14px">
          <div style="font-weight:600;margin-bottom:6px">${esc(t('pecWipeSummary') || 'Saranno rimossi:')}</div>
          <ul style="margin:0;padding-left:22px;line-height:1.7">
            <li><strong data-testid="text-wipe-pec-count">${pecCount}</strong> ${esc(t('pecWipeMessages') || 'messaggi PEC')}</li>
            <li><strong data-testid="text-wipe-file-count">${fileCount}</strong> ${esc(t('pecWipeFiles') || 'file allegati')}</li>
            <li>${esc(t('pecWipeSize') || 'spazio liberato')}: <strong data-testid="text-wipe-bytes">${_pecWipeFmtBytes(bytes)}</strong></li>
          </ul>
        </div>
        <div style="margin-bottom:8px;font-weight:600">${esc(t('pecWipeCodeLabel') || 'Per confermare, ricopia esattamente il codice:')}</div>
        <div style="display:flex;gap:8px;align-items:center;margin-bottom:10px">
          <code id="pecWipeCodeBox" data-testid="text-wipe-code" style="font-family:'Courier New',monospace;font-size:18px;font-weight:700;background:#1f2937;color:#fbbf24;padding:8px 14px;border-radius:6px;letter-spacing:2px;flex:1;text-align:center">${code}</code>
          <button class="btn btn-xs" onclick="navigator.clipboard.writeText('${code}').then(()=>{this.textContent='✓'});" data-testid="button-wipe-copy-code">${esc(t('pecWipeCodeCopy') || 'Copia')}</button>
        </div>
        <input type="text" id="pecWipeCodeInput" placeholder="${esc(t('pecWipeInputPlaceholder') || 'Digita o incolla il codice…')}"
               style="width:100%;padding:10px;border:2px solid #d1d5db;border-radius:6px;font-family:'Courier New',monospace;font-size:16px;letter-spacing:2px;text-align:center;text-transform:uppercase"
               oninput="_pecWipeCheckCode(this.value)" autocomplete="off" autocapitalize="characters" data-testid="input-wipe-code">
        <div id="pecWipeCodeMsg" style="min-height:18px;margin-top:6px;font-size:12px;color:#7f1d1d"></div>
        <div id="pecWipeProgress" style="display:none;margin-top:10px">
          <div style="font-size:12px;color:#374151;margin-bottom:4px" id="pecWipeProgressLabel">${esc(t('pecWipeProgress') || 'Cancellazione file fisici…')}</div>
          <div style="background:#e5e7eb;border-radius:4px;height:10px;overflow:hidden">
            <div id="pecWipeProgressBar" style="background:#7f1d1d;height:100%;width:0%;transition:width .15s"></div>
          </div>
        </div>
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;padding:12px 18px;background:#f9fafb;border-top:1px solid #e5e7eb">
        <button class="btn" onclick="document.getElementById('pecWipeOverlay').remove()" data-testid="button-wipe-cancel">${esc(t('pecWipeCancelBtn') || 'Annulla')}</button>
        <button id="pecWipeConfirmBtn" class="btn" disabled
                style="background:#9ca3af;color:#fff;cursor:not-allowed"
                onclick="_pecWipeExecute()" data-testid="button-wipe-confirm">${esc(t('pecWipeConfirmBtn') || 'Svuota definitivamente')}</button>
      </div>
    </div>`;
  document.body.appendChild(ov);
  setTimeout(() => { const i = document.getElementById('pecWipeCodeInput'); if (i) i.focus(); }, 50);
}
function _pecWipeCheckCode(val) {
  const code = window._pecWipeCode || '';
  const btn = document.getElementById('pecWipeConfirmBtn');
  const msg = document.getElementById('pecWipeCodeMsg');
  const v = (val || '').trim().toUpperCase();
  if (!btn) return;
  if (v === code) {
    btn.disabled = false;
    btn.style.background = '#7f1d1d';
    btn.style.cursor = 'pointer';
    if (msg) msg.textContent = '';
  } else {
    btn.disabled = true;
    btn.style.background = '#9ca3af';
    btn.style.cursor = 'not-allowed';
    if (msg) msg.textContent = v && v.length >= code.length ? (t('pecWipeMismatch') || 'Il codice non combacia.') : '';
  }
}
async function _pecWipeExecute() {
  const btn = document.getElementById('pecWipeConfirmBtn');
  if (!btn || btn.disabled) return;
  btn.disabled = true;
  btn.style.background = '#9ca3af';
  btn.style.cursor = 'wait';
  const cancelBtn = document.querySelector('[data-testid="button-wipe-cancel"]');
  if (cancelBtn) cancelBtn.disabled = true;
  const xBtn = document.querySelector('[data-testid="button-pec-wipe-cancel-x"]');
  if (xBtn) { xBtn.disabled = true; xBtn.style.opacity = '.4'; xBtn.style.cursor = 'not-allowed'; xBtn.onclick = null; }
  const input = document.getElementById('pecWipeCodeInput');
  if (input) input.disabled = true;
  const prog = document.getElementById('pecWipeProgress');
  const bar = document.getElementById('pecWipeProgressBar');
  const lbl = document.getElementById('pecWipeProgressLabel');
  if (prog) prog.style.display = 'block';
  let result = { pecCount: 0, fileCount: 0, bytesFreed: 0 };
  try {
    result = await DB.wipeAllPecMessages((i, total) => {
      if (bar) bar.style.width = (total ? Math.round((i / total) * 100) : 0) + '%';
      if (lbl) lbl.textContent = `${t('pecWipeProgress') || 'Cancellazione file fisici…'} (${i}/${total})`;
    });
  } catch (e) {
    console.error('wipeAllPecMessages failed:', e);
    alert((t('pecWipeError') || 'Errore durante lo svuotamento') + ': ' + (e && e.message ? e.message : e));
    const ov = document.getElementById('pecWipeOverlay');
    if (ov) ov.remove();
    return;
  }
  // Cleanup memoria
  try { window._pecMsgAttCache = {}; } catch (_) {}
  try { _pecSelectedId = null; } catch (_) {}
  try { _pecDetailView = 'message'; } catch (_) {}
  // Tracciabilità minima (localStorage, capped a 20 voci)
  try {
    const log = JSON.parse(localStorage.getItem('pec_wipe_log') || '[]');
    log.push({ at: new Date().toISOString(), pec: result.pecCount, files: result.fileCount, bytes: result.bytesFreed });
    while (log.length > 20) log.shift();
    localStorage.setItem('pec_wipe_log', JSON.stringify(log));
  } catch (_) {}
  console.log('[PEC WIPE]', new Date().toISOString(), result);
  // Chiudi modale e rinfresca lista
  const ov = document.getElementById('pecWipeOverlay');
  if (ov) ov.remove();
  try { await _pecRenderList(); } catch (_) {}
  const pane = document.getElementById('pecDetailPane');
  if (pane) pane.innerHTML = `<div style="color:#6b7280;text-align:center;margin-top:80px;font-size:14px">${esc(t('pecSelectHint') || 'Seleziona una PEC dalla lista o creane una nuova')}</div>`;
  // Notifica
  const doneMsg = (t('pecWipeDone') || '✓ Archivio PEC svuotato') +
    ` — ${result.pecCount} ${t('pecWipeMessages') || 'messaggi PEC'}, ${result.fileCount} ${t('pecWipeFiles') || 'file allegati'} (${_pecWipeFmtBytes(result.bytesFreed)})`;
  if (typeof showToast === 'function') showToast(doneMsg, 'success');
  else alert(doneMsg);
}

