// Backfill linkKind on entitySubjects for existing proceeding-level links (one-shot).
async function _backfillProceedingLinkKind() {
  try {
    const flagKey = 'uxg_backfill_linkkind_v1';
    if (localStorage.getItem(flagKey) === '1') return;
    if (typeof db === 'undefined' || !db.entitySubjects) return;
    const all = await db.entitySubjects.where('entityType').equals('proceeding').toArray();
    let updated = 0;
    for (const link of all) {
      if (link.linkKind) continue;
      const kind = _deriveLinkKindFromProcRole(link.qualificaProcessuale || '');
      await db.entitySubjects.update(link.id, { linkKind: kind });
      updated++;
    }
    localStorage.setItem(flagKey, '1');
    if (updated) console.log('[linkKind] backfilled', updated, 'proceeding links');
  } catch (e) { console.warn('[linkKind] backfill skipped', e); }
}
// Migrazione completa one-shot: shadow-sync di tutti i procedimenti penali esistenti
// (popola entitySubjects con linkKind=vigilanza/inquirente/giudicante/parteOffesa/indagatoImputato
// fased usando vigilanceSubjects e phases nidificati come sorgente).
async function _migrateAllProceedingsShadow() {
  try {
    const flagKey = 'uxg_shadow_migration_v1';
    if (localStorage.getItem(flagKey) === '1') return;
    if (typeof DB === 'undefined' || !DB.getAllProceedings) return;
    const procs = await DB.getAllProceedings();
    let migrated = 0;
    for (const p of procs) {
      if (!p || p.type !== 'penale') continue;
      await syncProceedingShadowLinks(p.id, p);
      migrated++;
    }
    localStorage.setItem(flagKey, '1');
    if (migrated) console.log('[shadow] migrated', migrated, 'proceedings');
  } catch (e) { console.warn('[shadow] migration skipped', e); }
}
// Backfill one-shot: per ogni prova con factId nullo/assente, se esiste una
// sola factProofRelations associata, copia quel factId sul record prova.
// Recupera dati legacy creati prima della persistenza di proof.factId.
async function _backfillProofFactId() {
  try {
    // Idempotente: gira ad ogni avvio. Necessario perche' i dati possono
    // essere importati DOPO il primo DOMContentLoaded (apertura cartella,
    // import JSON, restore da ZIP). Rimuove anche eventuali flag legacy.
    try { localStorage.removeItem('uxg_backfill_proof_factid_v1'); } catch (_) {}
    if (typeof db === 'undefined' || !db.proofs || !db.factProofRelations) return;
    const proofs = await db.proofs.toArray();
    const rels = await db.factProofRelations.toArray();
    const byProof = {};
    rels.forEach(r => {
      if (!byProof[r.proofId]) byProof[r.proofId] = new Set();
      byProof[r.proofId].add(r.factId);
    });
    let updated = 0;
    for (const p of proofs) {
      if (p.factId) continue;
      const set = byProof[p.id];
      if (!set || set.size !== 1) continue;
      const fid = [...set][0];
      await db.proofs.update(p.id, { factId: fid });
      updated++;
    }
    if (updated) console.log('[proof.factId] backfilled', updated, 'proofs');
  } catch (e) { console.warn('[proof.factId] backfill skipped', e); }
}
window._backfillProofFactId = _backfillProofFactId;
document.addEventListener('DOMContentLoaded', () => {
  setTimeout(async () => {
    await _backfillProceedingLinkKind();
    await _migrateAllProceedingsShadow();
    await _backfillProofFactId();
  }, 1500);
});

